/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2015_SEED = {"dse/writing/part-b/2015/Q2":[{"front":"revitalising PE lessons","meaning":"振興體育課","examples":[{"en":"The proposal is about revitalising PE lessons.","zh":"這份建議書是關於振興體育課。"},{"en":"Revitalising PE lessons means making physical education classes active, fresh, and meaningful again.","zh":"revitalising PE lessons 的意思是令體育課重新變得活躍、新鮮和有意義。"},{"en":"A school can revitalise PE lessons by adding new activities that suit different students.","zh":"學校可以透過加入適合不同學生的新活動來振興體育課。"},{"en":"Revitalising PE lessons matters because boring classes may make students dislike exercise.","zh":"振興體育課很重要，因為沉悶課堂可能令學生不喜歡運動。"},{"en":"This phrase suggests improving something that has become tired or ineffective.","zh":"這個短語暗示改善某些已變得沉悶或低效的東西。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"give students a reason to move","meaning":"給學生一個活動身體的理由","examples":[{"en":"The school should give students a reason to move.","zh":"學校應給學生一個活動身體的理由。"},{"en":"To give students a reason to move means to make exercise feel meaningful, enjoyable, or worth doing.","zh":"give students a reason to move 的意思是令運動感覺有意義、有樂趣或值得做。"},{"en":"A fun team challenge can give students a reason to move during PE lessons.","zh":"有趣的團隊挑戰可以在體育課中給學生一個活動身體的理由。"},{"en":"Students are more willing to exercise when the activity feels useful rather than forced.","zh":"當活動感覺有用而不是被迫時，學生會更願意運動。"},{"en":"This phrase shows that motivation matters as much as physical movement.","zh":"這個短語顯示動機與身體活動同樣重要。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"chairperson of the Class Association","meaning":"班會主席","examples":[{"en":"Chris Wong writes as chairperson of the Class Association.","zh":"Chris Wong 以班會主席身份寫信。"},{"en":"The chairperson of the Class Association is the student leader who represents the class group.","zh":"chairperson of the Class Association 是代表班會的學生領袖。"},{"en":"The chairperson may collect classmates’ opinions before writing to the school.","zh":"班會主席可以在寫信給學校前收集同學意見。"},{"en":"A chairperson should speak responsibly because he or she represents more than one person.","zh":"班會主席應負責任地發言，因為他或她代表的不只是一個人。"},{"en":"This phrase explains the writer’s role and authority in the proposal.","zh":"這個短語解釋作者在建議書中的身份和代表性。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"raise a concern","meaning":"提出關注","examples":[{"en":"He is writing to raise a concern mentioned by his classmates.","zh":"他寫信是為了提出同學提及的關注。"},{"en":"To raise a concern means to bring a worry or problem to someone’s attention.","zh":"raise a concern 的意思是把一個憂慮或問題帶到某人注意之中。"},{"en":"Students may raise a concern about PE lessons if many classmates feel left out.","zh":"如果許多同學感到被忽略，學生可以提出對體育課的關注。"},{"en":"Raising a concern politely can help teachers understand a problem before it becomes worse.","zh":"禮貌地提出關注可以幫助老師在問題惡化前理解情況。"},{"en":"This phrase is useful in formal writing when introducing an issue respectfully.","zh":"這個短語在正式寫作中很有用，可用來尊重地引入問題。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"raised repeatedly by","meaning":"被反覆提出","examples":[{"en":"The concern has been raised repeatedly by his classmates.","zh":"這個關注已被他的同學反覆提出。"},{"en":"Raised repeatedly by means mentioned again and again by a person or group.","zh":"raised repeatedly by 的意思是被某人或某群體一次又一次提及。"},{"en":"The problem of boring PE lessons was raised repeatedly by students during class meetings.","zh":"沉悶體育課的問題在班會中被學生反覆提出。"},{"en":"If a concern is raised repeatedly, it probably deserves serious attention.","zh":"如果某個關注被反覆提出，它很可能值得認真注意。"},{"en":"This phrase shows that the issue is not one person’s sudden complaint.","zh":"這個短語顯示該議題不是一個人的突然投訴。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"feel disappointed with","meaning":"對……感到失望","examples":[{"en":"Many students feel disappointed with their present PE lessons.","zh":"許多學生對現時的體育課感到失望。"},{"en":"To feel disappointed with something means to feel unhappy because it is worse than expected.","zh":"feel disappointed with something 的意思是因某事比預期差而感到不開心。"},{"en":"Students may feel disappointed with PE if they wait more than they exercise.","zh":"如果學生等待的時間比運動時間更多，他們可能對體育課感到失望。"},{"en":"Disappointment grows when lessons promise health but feel like repeated tests.","zh":"當課堂本應促進健康，卻感覺像重複測驗時，失望會增加。"},{"en":"This phrase describes an emotional reaction to an unsatisfactory experience.","zh":"這個短語描述對不理想經驗的情緒反應。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"present physical education lessons","meaning":"現時的體育課","examples":[{"en":"Students are unhappy with their present physical education lessons.","zh":"學生對現時的體育課不滿。"},{"en":"Present physical education lessons means the PE classes students are currently having.","zh":"present physical education lessons 的意思是學生目前正在上的體育課。"},{"en":"Present physical education lessons may feel narrow if they repeat the same ball games every week.","zh":"如果每星期都重複同樣球類活動，現時的體育課可能感覺狹窄。"},{"en":"Reviewing present PE lessons helps a school see what should be improved.","zh":"檢討現時的體育課可以幫助學校看見需要改善之處。"},{"en":"This phrase focuses on the current situation, not past or future classes.","zh":"這個短語聚焦目前情況，而不是過去或未來的課堂。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"this is not because...rather...","meaning":"這不是因為……而是……","examples":[{"en":"This is not because students dislike exercise; rather, the lessons have become discouraging.","zh":"這不是因為學生不喜歡運動，而是因為課堂變得令人洩氣。"},{"en":"This is not because A; rather, B means B is the real reason, not A.","zh":"this is not because A; rather, B 的意思是真正原因是 B，而不是 A。"},{"en":"This is not because students are lazy; rather, the activities do not suit different abilities.","zh":"這不是因為學生懶惰，而是因為活動不適合不同能力。"},{"en":"This structure helps correct a misunderstanding before giving a better explanation.","zh":"這個結構幫助在提出更好解釋前先修正誤解。"},{"en":"It is useful when a problem is often blamed on the wrong cause.","zh":"當問題常被歸咎於錯誤原因時，這個結構很有用。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"discover the joy of movement","meaning":"發現活動身體的樂趣","examples":[{"en":"PE should help students discover the joy of movement.","zh":"體育課應幫助學生發現活動身體的樂趣。"},{"en":"To discover the joy of movement means to realise that moving the body can feel enjoyable and rewarding.","zh":"discover the joy of movement 的意思是明白活動身體可以令人感到愉快和有滿足感。"},{"en":"A student may discover the joy of movement through dance, skipping, frisbee, or fitness games.","zh":"學生可以透過跳舞、跳繩、飛盤或體能遊戲發現活動身體的樂趣。"},{"en":"When students enjoy movement, they are more likely to exercise outside school.","zh":"當學生享受活動身體，他們更可能在校外運動。"},{"en":"This phrase shows that PE should build positive feelings, not just skills.","zh":"這個短語顯示體育課應建立正面感受，而不只是技能。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"develop healthy habits","meaning":"培養健康習慣","examples":[{"en":"PE lessons should help students develop healthy habits.","zh":"體育課應幫助學生培養健康習慣。"},{"en":"To develop healthy habits means to build regular behaviours that support physical and mental health.","zh":"develop healthy habits 的意思是建立支持身心健康的規律行為。"},{"en":"Students develop healthy habits when they learn to warm up, exercise safely, and stretch properly.","zh":"當學生學會熱身、安全運動和正確伸展時，就是培養健康習慣。"},{"en":"Healthy habits are easier to keep when exercise feels enjoyable and achievable.","zh":"當運動感覺有趣而做得到時，健康習慣較容易維持。"},{"en":"This phrase describes a long-term goal of PE lessons.","zh":"這個短語描述體育課的長遠目標。"}],"source":"2015 Q2.pdf","sourcePage":1},{"front":"predictable, narrow and discouraging","meaning":"可預測、狹窄而令人氣餒","examples":[{"en":"Some students feel that PE has become predictable, narrow and discouraging.","zh":"有些學生覺得體育課已變得可預測、狹窄而令人氣餒。"},{"en":"Predictable, narrow and discouraging means the lessons are easy to guess, limited in variety, and reduce motivation.","zh":"predictable, narrow and discouraging 的意思是課堂容易猜到、種類有限，並削弱動力。"},{"en":"PE becomes predictable, narrow and discouraging when students play the same sport every week.","zh":"當學生每星期都玩同一種運動，體育課就會變得可預測、狹窄而令人氣餒。"},{"en":"Such lessons may benefit confident players but leave others feeling unsuccessful.","zh":"這類課堂可能令有信心的球員受益，卻令其他人感到失敗。"},{"en":"This phrase explains why students may dislike PE even if they do not dislike exercise.","zh":"這個短語解釋為何學生可能不喜歡體育課，即使他們不是不喜歡運動。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"with this in mind","meaning":"有見及此","examples":[{"en":"With this in mind, he hopes the school will refresh the PE curriculum.","zh":"有見及此，他希望學校會更新體育課程。"},{"en":"With this in mind means considering the point just mentioned before making a suggestion.","zh":"with this in mind 的意思是在考慮剛才提到的觀點後提出建議。"},{"en":"Students feel left out; with this in mind, the school should offer more varied activities.","zh":"學生感到被忽略；有見及此，學校應提供更多元活動。"},{"en":"This phrase connects a problem to the recommendation that follows.","zh":"這個短語把問題與接下來的建議連繫起來。"},{"en":"It helps show that the proposal is based on students’ real concerns.","zh":"它幫助顯示建議是基於學生的真實關注。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"refresh the PE curriculum","meaning":"更新體育課程","examples":[{"en":"The school should consider refreshing the PE curriculum.","zh":"學校應考慮更新體育課程。"},{"en":"To refresh the PE curriculum means to update the content, activities, and aims of PE lessons.","zh":"refresh the PE curriculum 的意思是更新體育課的內容、活動和目標。"},{"en":"A school can refresh the PE curriculum by adding circuit training and ultimate frisbee.","zh":"學校可以透過加入循環訓練和極限飛盤來更新體育課程。"},{"en":"Refreshing the curriculum may help students who feel bored or excluded.","zh":"更新課程可能幫助感到沉悶或被排除的學生。"},{"en":"This phrase suggests improvement without completely rejecting the existing programme.","zh":"這個短語暗示改善，而不是完全否定現有課程。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"more inclusive, varied and meaningful","meaning":"更共融、更多元、更有意義","examples":[{"en":"PE lessons should become more inclusive, varied and meaningful.","zh":"體育課應變得更共融、更多元和更有意義。"},{"en":"More inclusive, varied and meaningful means more students can join, more activities are offered, and the lessons feel useful.","zh":"more inclusive, varied and meaningful 的意思是更多學生能參與、活動更多樣，課堂也感覺有用。"},{"en":"A PE programme becomes more inclusive when less athletic students can succeed safely.","zh":"當運動能力較弱的學生也能安全成功，體育課程就變得更共融。"},{"en":"Varied and meaningful lessons help students see exercise as part of life, not only school assessment.","zh":"多元而有意義的課堂幫助學生把運動看成生活的一部分，而不只是學校評核。"},{"en":"This phrase describes the kind of PE that motivates different learners.","zh":"這個短語描述能激勵不同學習者的體育課。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"in particular","meaning":"尤其是","examples":[{"en":"In particular, he suggests two new activities.","zh":"尤其是，他建議兩項新活動。"},{"en":"In particular means especially or more specifically.","zh":"in particular 的意思是特別是或更具體地說。"},{"en":"The school should improve PE; in particular, it should add activities for mixed-ability groups.","zh":"學校應改善體育課；尤其是，應加入適合能力混合小組的活動。"},{"en":"Writers use this phrase when moving from a general idea to a specific example.","zh":"作者由一般想法轉向具體例子時會使用這個短語。"},{"en":"It helps readers focus on the most important details.","zh":"它幫助讀者集中於最重要的細節。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"existing lessons","meaning":"現有課堂","examples":[{"en":"Students are unhappy with the existing lessons.","zh":"學生對現有課堂不滿。"},{"en":"Existing lessons are the lessons currently being offered or used.","zh":"existing lessons 是目前正在提供或使用的課堂。"},{"en":"Existing PE lessons may rely too much on familiar ball games.","zh":"現有體育課堂可能過度依賴熟悉的球類活動。"},{"en":"Reviewing existing lessons helps teachers see what should stay and what should change.","zh":"檢討現有課堂幫助老師看見甚麼應保留、甚麼應改變。"},{"en":"This phrase refers to the current programme before improvements are made.","zh":"這個短語指改善前的目前課程。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"suggest two activities","meaning":"建議兩項活動","examples":[{"en":"He would like to suggest two activities for PE lessons.","zh":"他想為體育課建議兩項活動。"},{"en":"To suggest two activities means to propose two possible things students could do.","zh":"suggest two activities 的意思是提出兩項學生可以進行的活動。"},{"en":"A class representative may suggest two activities after collecting classmates’ opinions.","zh":"班代表可以在收集同學意見後建議兩項活動。"},{"en":"Suggesting activities is useful when criticism should be followed by solutions.","zh":"當批評之後應提出解決方法時，建議活動很有用。"},{"en":"This phrase introduces practical recommendations.","zh":"這個短語引入實際建議。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"be warmly welcomed","meaning":"受到熱烈歡迎","examples":[{"en":"The two activities would be warmly welcomed by students.","zh":"這兩項活動會受到學生熱烈歡迎。"},{"en":"Be warmly welcomed means be received with pleasure, interest, and support.","zh":"be warmly welcomed 的意思是被愉快、有興趣和支持地接受。"},{"en":"A new PE activity may be warmly welcomed if it gives everyone a chance to move.","zh":"如果新的體育活動給每個人活動身體的機會，它可能受到熱烈歡迎。"},{"en":"Students warmly welcome changes when they feel their concerns have been heard.","zh":"當學生覺得自己的關注被聽見時，他們會熱烈歡迎改變。"},{"en":"This phrase predicts a positive response from the audience.","zh":"這個短語預測對象會有正面反應。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"to begin with","meaning":"首先","examples":[{"en":"To begin with, many classmates find current PE lessons uninteresting.","zh":"首先，許多同學覺得現時的體育課沉悶。"},{"en":"To begin with means first of all or as the first point.","zh":"to begin with 的意思是首先或作為第一點。"},{"en":"To begin with, the school should understand why students feel discouraged.","zh":"首先，學校應理解為何學生感到氣餒。"},{"en":"Writers use this phrase to start the first reason in an argument.","zh":"作者使用這個短語來開始論點中的第一個原因。"},{"en":"It helps organise a proposal clearly.","zh":"它幫助清楚組織建議書。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"current PE lessons","meaning":"現時的體育課","examples":[{"en":"Many classmates find current PE lessons uninteresting.","zh":"許多同學覺得現時的體育課沉悶。"},{"en":"Current PE lessons are the physical education classes students are having now.","zh":"current PE lessons 是學生現在上的體育課。"},{"en":"Current PE lessons may feel repetitive if the format seldom changes.","zh":"如果形式很少改變，現時的體育課可能感覺重複。"},{"en":"If current PE lessons discourage weaker students, the school should review them.","zh":"如果現時的體育課令能力較弱的學生氣餒，學校應檢討。"},{"en":"This phrase focuses on what is happening in PE at present.","zh":"這個短語聚焦目前體育課正在發生的情況。"}],"source":"2015 Q2.pdf","sourcePage":2},{"front":"the format seldom changes","meaning":"形式很少改變","examples":[{"en":"Students are bored because the format seldom changes.","zh":"學生感到沉悶，因為形式很少改變。"},{"en":"The format seldom changes means the lesson structure stays almost the same most of the time.","zh":"the format seldom changes 的意思是課堂結構大多數時候幾乎一樣。"},{"en":"If every PE lesson starts with drills and ends with the same game, the format seldom changes.","zh":"如果每節體育課都由操練開始，並以同一個遊戲結束，形式就是很少改變。"},{"en":"A format that seldom changes may make even useful activities feel dull.","zh":"很少改變的形式可能令有用活動也變得沉悶。"},{"en":"This phrase explains boredom through repetition.","zh":"這個短語透過重複來解釋沉悶。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"more often than not","meaning":"多數情況下","examples":[{"en":"More often than not, students repeat the same kinds of activities.","zh":"多數情況下，學生重複同類活動。"},{"en":"More often than not means usually or in most cases.","zh":"more often than not 的意思是通常或多數情況下。"},{"en":"More often than not, PE lessons focus on the same sports each term.","zh":"多數情況下，體育課每學期都集中於同樣運動。"},{"en":"This phrase describes a common pattern without saying it happens every single time.","zh":"這個短語描述常見模式，但不是說每一次都如此。"},{"en":"It is useful when making a careful general statement.","zh":"當作出謹慎的一般說法時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"warm-up drills","meaning":"熱身操練","examples":[{"en":"Lessons often move from warm-up drills to a familiar ball game.","zh":"課堂常由熱身操練進入熟悉的球類活動。"},{"en":"Warm-up drills are short exercises used to prepare the body before harder activity.","zh":"warm-up drills 是在較劇烈活動前準備身體的短練習。"},{"en":"Warm-up drills may include jogging, stretching, jumping, or simple movement patterns.","zh":"熱身操練可以包括慢跑、伸展、跳躍或簡單動作模式。"},{"en":"Good warm-up drills can prevent injury, but repeating the same ones every lesson may feel boring.","zh":"良好的熱身操練可以防止受傷，但每堂重複同樣內容可能會沉悶。"},{"en":"This phrase describes preparation at the start of PE.","zh":"這個短語描述體育課開始時的準備。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"familiar ball game","meaning":"熟悉的球類活動","examples":[{"en":"Students often play a familiar ball game such as basketball or volleyball.","zh":"學生常玩熟悉的球類活動，例如籃球或排球。"},{"en":"A familiar ball game is a sport with a ball that students already know well.","zh":"familiar ball game 是學生已很熟悉的球類運動。"},{"en":"Basketball, football, volleyball, and handball can all be familiar ball games in school.","zh":"籃球、足球、排球和手球都可以是學校裏熟悉的球類活動。"},{"en":"Familiar ball games are easy to organise, but they may not suit every student.","zh":"熟悉的球類活動容易安排，但未必適合每位學生。"},{"en":"This phrase suggests comfort for some students and repetition for others.","zh":"這個短語暗示對某些學生來說是熟悉，對另一些學生來說是重複。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"repeat similar skills","meaning":"重複相似技巧","examples":[{"en":"Students repeat similar skills under time pressure.","zh":"學生在時間壓力下重複相似技巧。"},{"en":"To repeat similar skills means to practise nearly the same movements again and again.","zh":"repeat similar skills 的意思是一次又一次練習幾乎相同的動作。"},{"en":"Students may repeat similar skills such as passing, serving, or shooting every lesson.","zh":"學生可能每堂都重複相似技巧，例如傳球、發球或投籃。"},{"en":"Repeating similar skills can build ability, but it may reduce interest if there is no variety.","zh":"重複相似技巧可以建立能力，但如果沒有變化，可能會減少興趣。"},{"en":"This phrase explains why practice can become dull.","zh":"這個短語解釋為何練習可以變得沉悶。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"under time pressure","meaning":"在時間壓力下","examples":[{"en":"Students often practise skills under time pressure.","zh":"學生常在時間壓力下練習技巧。"},{"en":"Under time pressure means needing to complete something within a limited time.","zh":"under time pressure 的意思是需要在有限時間內完成某事。"},{"en":"A student may feel nervous when asked to shoot, pass, or run under time pressure.","zh":"當學生被要求在時間壓力下投籃、傳球或跑步時，可能會緊張。"},{"en":"Time pressure can make weaker students afraid of mistakes in front of others.","zh":"時間壓力可以令能力較弱的學生害怕在別人面前犯錯。"},{"en":"This phrase shows how the lesson environment can affect confidence.","zh":"這個短語顯示課堂環境如何影響信心。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, the arrangement seems practical.","zh":"乍看之下，這個安排似乎實際可行。"},{"en":"At first glance means when something is first seen or considered, before deeper thought.","zh":"at first glance 的意思是在初次看見或考慮某事時，還未深入思考。"},{"en":"At first glance, using the same ball games seems easy because the equipment is ready.","zh":"乍看之下，使用同樣球類活動似乎容易，因為器材已準備好。"},{"en":"A plan may look sensible at first glance but exclude many students on closer inspection.","zh":"一個計劃乍看之下可能合理，但仔細看來會排除許多學生。"},{"en":"This phrase prepares readers for a more careful judgement.","zh":"這個短語為讀者準備更仔細的判斷。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"practical arrangement","meaning":"實際可行的安排","examples":[{"en":"The arrangement seems practical because the equipment is available.","zh":"這個安排似乎實際可行，因為器材可供使用。"},{"en":"A practical arrangement is a plan that is easy to carry out with available time, space, or resources.","zh":"practical arrangement 是可以用現有時間、空間或資源容易執行的計劃。"},{"en":"Using the school hall for circuit training may be a practical arrangement on rainy days.","zh":"在雨天使用學校禮堂進行循環訓練，可能是實際可行的安排。"},{"en":"A practical arrangement is helpful, but it should still meet students’ needs.","zh":"實際可行的安排有幫助，但仍應滿足學生需要。"},{"en":"This phrase describes convenience, not necessarily quality.","zh":"這個短語描述方便性，不一定描述質素。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"the rules are known","meaning":"規則已為人熟悉","examples":[{"en":"The rules are known, so teachers can manage the class easily.","zh":"規則已為人熟悉，所以老師可以容易管理班級。"},{"en":"The rules are known means most students and teachers already understand how the game works.","zh":"the rules are known 的意思是大多數學生和老師已明白遊戲如何進行。"},{"en":"Basketball is easy to start because the rules are known by many students.","zh":"籃球容易開始，因為許多學生都熟悉規則。"},{"en":"When the rules are known, less time is needed for explanation.","zh":"當規則已為人熟悉，就較少時間需要用來解釋。"},{"en":"This phrase explains why familiar activities are convenient.","zh":"這個短語解釋為何熟悉活動很方便。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"equipment is available","meaning":"器材可供使用","examples":[{"en":"The equipment is available for familiar ball games.","zh":"熟悉球類活動的器材可供使用。"},{"en":"Equipment is available means the necessary tools or materials can already be used.","zh":"equipment is available 的意思是所需工具或材料已經可以使用。"},{"en":"If cones, discs, and skipping ropes are available, teachers can run different PE stations.","zh":"如果雪糕筒、飛盤和跳繩可供使用，老師可以設立不同體育訓練站。"},{"en":"Available equipment makes planning easier, but lessons still need variety.","zh":"可用器材令計劃較容易，但課堂仍需要變化。"},{"en":"This phrase explains one practical reason for choosing an activity.","zh":"這個短語解釋選擇某項活動的一個實際原因。"}],"source":"2015 Q2.pdf","sourcePage":3},{"front":"manage the class easily","meaning":"容易管理班級","examples":[{"en":"Teachers can manage the class easily with familiar sports.","zh":"老師可以用熟悉的運動容易管理班級。"},{"en":"To manage the class easily means to keep students organised, safe, and under control without difficulty.","zh":"manage the class easily 的意思是毫不困難地讓學生有秩序、安全並受控。"},{"en":"Teachers may manage the class easily when students already know where to stand and what to do.","zh":"當學生已知道站在哪裏和做甚麼時，老師可能較容易管理班級。"},{"en":"Easy management is useful, but it should not be the only reason for choosing activities.","zh":"容易管理很有用，但不應是選擇活動的唯一原因。"},{"en":"This phrase focuses on the teacher’s practical classroom needs.","zh":"這個短語聚焦老師在課堂上的實際需要。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, the lesson mainly benefits confident players.","zh":"仔細看來，課堂主要令有信心的球員受益。"},{"en":"On closer inspection means after looking at the details more carefully.","zh":"on closer inspection 的意思是在更仔細查看細節後。"},{"en":"On closer inspection, a fun ball game may leave quiet students waiting at the side.","zh":"仔細看來，有趣的球類活動可能令安靜學生在旁邊等候。"},{"en":"This phrase shows that the first impression may not reveal the full problem.","zh":"這個短語顯示第一印象未必揭示完整問題。"},{"en":"It is useful when a plan seems good but has hidden weaknesses.","zh":"當一個計劃看似好但有隱藏弱點時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"benefit mainly","meaning":"主要令……受益","examples":[{"en":"The lesson benefits mainly students who are already confident in those sports.","zh":"這課堂主要令已經對那些運動有信心的學生受益。"},{"en":"Benefit mainly means help one group more than others.","zh":"benefit mainly 的意思是比其他群體更多地幫助某一群人。"},{"en":"Competitive games may benefit mainly students who already play on school teams.","zh":"競爭性比賽可能主要令已是校隊成員的學生受益。"},{"en":"If PE benefits mainly strong players, weaker students may feel excluded.","zh":"如果體育課主要令強項學生受益，能力較弱的學生可能感到被排除。"},{"en":"This phrase helps identify unequal effects within one activity.","zh":"這個短語幫助指出同一活動中的不平等影響。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"confident in those sports","meaning":"對那些運動有信心","examples":[{"en":"Some students are already confident in those sports.","zh":"有些學生已經對那些運動有信心。"},{"en":"Confident in those sports means feeling sure and comfortable when playing those activities.","zh":"confident in those sports 的意思是在進行那些活動時感到有把握和自在。"},{"en":"A student who joins the basketball team may be confident in that sport during PE.","zh":"加入籃球隊的學生在體育課中可能對籃球有信心。"},{"en":"Students confident in those sports may dominate games without realising others feel left out.","zh":"對那些運動有信心的學生可能主導比賽，卻沒有意識到其他人感到被忽略。"},{"en":"This phrase describes existing ability and self-belief.","zh":"這個短語描述已有能力和自信。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"dominate the games","meaning":"主導比賽","examples":[{"en":"Stronger players often dominate the games.","zh":"較強的球員常主導比賽。"},{"en":"To dominate the games means to control most of the play and take most of the chances.","zh":"dominate the games 的意思是控制大部分比賽過程，並取得大部分機會。"},{"en":"In a basketball lesson, stronger players may dominate the game by keeping the ball for themselves.","zh":"在籃球課中，較強的球員可能透過自己控球來主導比賽。"},{"en":"When a few students dominate the games, others may move less and lose interest.","zh":"當少數學生主導比賽，其他人可能活動較少並失去興趣。"},{"en":"This phrase shows how ability differences can affect participation.","zh":"這個短語展示能力差異如何影響參與。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"less athletic students","meaning":"運動能力較弱的學生","examples":[{"en":"Less athletic students may feel left out during PE lessons.","zh":"運動能力較弱的學生可能在體育課中感到被忽略。"},{"en":"Less athletic students are students who are less strong, fast, skilful, or confident in sports.","zh":"less athletic students 是在運動方面較不強壯、快速、熟練或有信心的學生。"},{"en":"Less athletic students may enjoy PE more when activities have different difficulty levels.","zh":"當活動有不同難度級別時，運動能力較弱的學生可能更享受體育課。"},{"en":"If lessons only reward speed and power, less athletic students may feel discouraged.","zh":"如果課堂只獎勵速度和力量，運動能力較弱的學生可能感到氣餒。"},{"en":"This phrase helps teachers consider students with different physical abilities.","zh":"這個短語幫助老師考慮不同體能的學生。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"be left standing at the side","meaning":"被晾在一旁站着","examples":[{"en":"Some students are left standing at the side.","zh":"有些學生被晾在一旁站着。"},{"en":"To be left standing at the side means to be present but not really included in the activity.","zh":"be left standing at the side 的意思是在場卻沒有真正被包括在活動中。"},{"en":"In a fast ball game, weaker students may be left standing at the side while others play.","zh":"在快速球類比賽中，能力較弱的學生可能被晾在一旁站着，看着其他人玩。"},{"en":"Students left standing at the side may feel embarrassed and invisible.","zh":"被晾在一旁站着的學生可能感到尷尬和被忽視。"},{"en":"This phrase shows exclusion within a lesson that is supposed to involve everyone.","zh":"這個短語展示本應讓每個人參與的課堂中出現排除。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"afraid of making mistakes","meaning":"害怕犯錯","examples":[{"en":"Students may be afraid of making mistakes in front of others.","zh":"學生可能害怕在其他人面前犯錯。"},{"en":"Afraid of making mistakes means worried about doing something wrong and being judged.","zh":"afraid of making mistakes 的意思是擔心做錯事並被別人評判。"},{"en":"A student may be afraid of making mistakes when asked to serve a volleyball before the whole class.","zh":"當學生要在全班面前發排球時，可能害怕犯錯。"},{"en":"Fear of mistakes can stop students from trying new skills.","zh":"害怕犯錯會阻止學生嘗試新技巧。"},{"en":"This phrase explains why some students avoid participation.","zh":"這個短語解釋為何有些學生逃避參與。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"in front of others","meaning":"在其他人面前","examples":[{"en":"Some students dislike performing skills in front of others.","zh":"有些學生不喜歡在其他人面前表演技巧。"},{"en":"In front of others means while other people are watching.","zh":"in front of others 的意思是在其他人觀看時。"},{"en":"A shy student may feel nervous when running, throwing, or jumping in front of others.","zh":"害羞學生在其他人面前跑步、投擲或跳躍時可能會緊張。"},{"en":"Performing in front of others can create pressure, especially when mistakes are obvious.","zh":"在其他人面前表現可能造成壓力，尤其當錯誤很明顯時。"},{"en":"This phrase shows the social side of classroom anxiety.","zh":"這個短語展示課堂焦慮的社交一面。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"spend more time...than...","meaning":"花更多時間……而不是……","examples":[{"en":"Some students spend more time waiting than actually moving.","zh":"有些學生花更多時間等待，而不是真正活動身體。"},{"en":"Spend more time A than B means one activity takes more time than another.","zh":"spend more time A than B 的意思是一項活動花的時間比另一項更多。"},{"en":"In some PE lessons, students spend more time standing in line than practising skills.","zh":"在某些體育課中，學生花更多時間排隊，而不是練習技巧。"},{"en":"If students spend more time waiting than moving, the lesson fails its physical purpose.","zh":"如果學生花更多時間等待而不是活動，課堂就未能達到其體育目的。"},{"en":"This structure helps compare what happens with what should happen.","zh":"這個結構幫助比較實際情況與應有情況。"}],"source":"2015 Q2.pdf","sourcePage":4},{"front":"waiting for their turn","meaning":"等候輪到自己","examples":[{"en":"Some students spend too much time waiting for their turn.","zh":"有些學生花太多時間等候輪到自己。"},{"en":"Waiting for their turn means standing by until it is their chance to take part.","zh":"waiting for their turn 的意思是在旁等待，直到輪到自己參與。"},{"en":"In a shooting drill, students may wait for their turn while only one person practises.","zh":"在投籃操練中，學生可能在只有一人練習時等候輪到自己。"},{"en":"Long waiting time reduces movement and makes PE feel slow.","zh":"長時間等待會減少活動量，並令體育課感覺緩慢。"},{"en":"This phrase describes a common problem in poorly organised activities.","zh":"這個短語描述組織不佳活動中的常見問題。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"actually moving","meaning":"真正活動身體","examples":[{"en":"PE lessons should let students spend more time actually moving.","zh":"體育課應讓學生花更多時間真正活動身體。"},{"en":"Actually moving means physically using the body, not just standing, watching, or waiting.","zh":"actually moving 的意思是真正使用身體，而不是只站着、觀看或等待。"},{"en":"Circuit training helps more students stay actually moving at the same time.","zh":"循環訓練幫助更多學生同時真正活動身體。"},{"en":"If students are actually moving, PE is more likely to improve fitness and mood.","zh":"如果學生真正活動身體，體育課較可能改善體能和心情。"},{"en":"This phrase focuses on real physical participation.","zh":"這個短語聚焦真實身體參與。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"performing the same drills","meaning":"做同樣的操練","examples":[{"en":"Performing the same drills can make PE feel like a test.","zh":"做同樣的操練可以令體育課感覺像測驗。"},{"en":"Performing the same drills means repeating identical practice exercises again and again.","zh":"performing the same drills 的意思是一次又一次重複相同練習。"},{"en":"Students may dislike performing the same drills if every mistake is visible.","zh":"如果每個錯誤都很明顯，學生可能不喜歡做同樣的操練。"},{"en":"Repeated drills can help skills, but without variety they may feel mechanical.","zh":"重複操練可以幫助技能，但沒有變化時可能感覺機械化。"},{"en":"This phrase explains how practice can become pressure.","zh":"這個短語解釋練習如何變成壓力。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"feel more like a test than a break","meaning":"感覺更像測驗而不是休息","examples":[{"en":"PE may feel more like a test than a break from academic pressure.","zh":"體育課可能感覺更像測驗，而不是從學業壓力中休息。"},{"en":"Feel more like a test than a break means the activity creates pressure instead of relief.","zh":"feel more like a test than a break 的意思是活動帶來壓力，而不是放鬆。"},{"en":"PE feels more like a test than a break when students fear being judged for every mistake.","zh":"當學生害怕每個錯誤都被評判時，體育課就感覺更像測驗而不是休息。"},{"en":"A lesson meant for health becomes discouraging if students feel examined all the time.","zh":"如果學生一直感到被考核，本應促進健康的課堂就會變得令人洩氣。"},{"en":"This phrase contrasts the intended purpose with the actual experience.","zh":"這個短語對比原本目的與實際經驗。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"academic pressure","meaning":"學業壓力","examples":[{"en":"Students need a break from academic pressure.","zh":"學生需要從學業壓力中休息。"},{"en":"Academic pressure is stress caused by study, homework, tests, grades, and future expectations.","zh":"academic pressure 是由學習、功課、測驗、成績和未來期望造成的壓力。"},{"en":"PE can reduce academic pressure when it gives students a healthy way to relax.","zh":"當體育課給學生健康放鬆方式時，它可以減少學業壓力。"},{"en":"If PE becomes another test, it adds to academic pressure instead of easing it.","zh":"如果體育課變成另一種測驗，它就會增加而不是減輕學業壓力。"},{"en":"This phrase describes a common burden in student life.","zh":"這個短語描述學生生活中的常見負擔。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"it is therefore easy to see why","meaning":"因此很容易理解為何","examples":[{"en":"It is therefore easy to see why students gradually lose motivation.","zh":"因此很容易理解為何學生逐漸失去動力。"},{"en":"It is therefore easy to see why means the reason becomes clear after considering the previous points.","zh":"it is therefore easy to see why 的意思是在考慮前面觀點後，原因變得清楚。"},{"en":"If students wait, feel judged, and repeat the same drills, it is easy to see why they dislike PE.","zh":"如果學生等待、感到被評判，又重複同樣操練，就很容易理解為何他們不喜歡體育課。"},{"en":"This phrase helps connect evidence to a conclusion.","zh":"這個短語幫助把證據連接到結論。"},{"en":"It is useful when the writer wants the reader to accept a logical result.","zh":"當作者希望讀者接受合乎邏輯的結果時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"gradually lose motivation","meaning":"逐漸失去動力","examples":[{"en":"Students gradually lose motivation when lessons offer little choice.","zh":"當課堂提供很少選擇時，學生會逐漸失去動力。"},{"en":"To gradually lose motivation means to become less willing to try over time.","zh":"gradually lose motivation 的意思是隨時間變得較不願意嘗試。"},{"en":"A student may gradually lose motivation if PE always makes him feel unsuccessful.","zh":"如果體育課總令學生感到失敗，他可能逐漸失去動力。"},{"en":"Motivation can fade when improvement is invisible and embarrassment is common.","zh":"當進步看不見而尷尬很常見時，動力會慢慢消失。"},{"en":"This phrase shows a slow emotional decline.","zh":"這個短語展示緩慢的情緒下降。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"little room for personal improvement","meaning":"很少個人進步空間","examples":[{"en":"The activity offers little room for personal improvement.","zh":"這項活動提供很少個人進步空間。"},{"en":"Little room for personal improvement means there are few chances for a student to get better at their own pace.","zh":"little room for personal improvement 的意思是學生很少有機會按自己的步伐變得更好。"},{"en":"A game dominated by strong players gives weaker students little room for personal improvement.","zh":"被強項球員主導的比賽，給能力較弱的學生很少個人進步空間。"},{"en":"PE becomes more encouraging when students can measure their own progress.","zh":"當學生能量度自己的進步時，體育課會更令人鼓舞。"},{"en":"This phrase criticises activities that do not help individuals grow.","zh":"這個短語批評不能幫助個人成長的活動。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"enjoyment naturally disappears","meaning":"樂趣自然消失","examples":[{"en":"Enjoyment naturally disappears when students feel unsuccessful.","zh":"當學生感到不成功時，樂趣自然消失。"},{"en":"Enjoyment naturally disappears means pleasure fades in an expected way because the experience is negative.","zh":"enjoyment naturally disappears 的意思是因經驗負面，樂趣以可預期方式消退。"},{"en":"If a student is always chosen last, enjoyment naturally disappears.","zh":"如果學生總是最後被選中，樂趣自然消失。"},{"en":"Students enjoy PE less when every lesson reminds them of failure.","zh":"當每節課都提醒學生自己失敗，他們會較不享受體育課。"},{"en":"This phrase explains why emotion changes when confidence is damaged.","zh":"這個短語解釋當信心受損時，情緒如何改變。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"respectfully suggest","meaning":"恭敬地建議","examples":[{"en":"One activity he respectfully suggests is circuit training.","zh":"他恭敬地建議的一項活動是循環訓練。"},{"en":"To respectfully suggest means to propose an idea politely, especially to someone with authority.","zh":"respectfully suggest 的意思是禮貌地提出想法，尤其是向有權力的人提出。"},{"en":"Students may respectfully suggest a new activity to the PE panel.","zh":"學生可以向體育科組恭敬地建議一項新活動。"},{"en":"This phrase helps the writer sound cooperative rather than demanding.","zh":"這個短語幫助作者聽起來合作，而不是命令。"},{"en":"It is useful in formal proposals and letters.","zh":"它在正式建議書和信件中很有用。"}],"source":"2015 Q2.pdf","sourcePage":5},{"front":"station-based fitness circuit training","meaning":"分站式體能循環訓練","examples":[{"en":"Station-based fitness circuit training would make PE more active.","zh":"分站式體能循環訓練會令體育課更活躍。"},{"en":"Station-based fitness circuit training is a lesson format where students move between exercise stations.","zh":"station-based fitness circuit training 是學生在不同運動訓練站之間輪換的課堂形式。"},{"en":"One station may involve skipping, another may involve balance, and another may involve stretching.","zh":"一個訓練站可以做跳繩，另一個做平衡訓練，另一個做伸展。"},{"en":"This activity keeps more students moving because groups rotate at the same time.","zh":"這項活動讓更多學生保持活動，因為小組同時輪換。"},{"en":"This phrase describes an organised way to train different fitness skills.","zh":"這個短語描述有組織地訓練不同體能技能的方法。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"in a typical lesson","meaning":"在一節典型課堂中","examples":[{"en":"In a typical lesson, the hall could be divided into several stations.","zh":"在一節典型課堂中，禮堂可以被分成幾個訓練站。"},{"en":"In a typical lesson means in a normal or usual class of this kind.","zh":"in a typical lesson 的意思是在這類正常或常見課堂中。"},{"en":"In a typical PE lesson, students may begin with warm-up exercises before the main activity.","zh":"在一節典型體育課中，學生可能先做熱身運動，再進入主要活動。"},{"en":"This phrase helps readers imagine how the proposal would work in practice.","zh":"這個短語幫助讀者想像建議在實際課堂中如何運作。"},{"en":"It is useful when explaining the ordinary structure of a lesson.","zh":"當解釋課堂的一般結構時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"be divided into several stations","meaning":"被分成幾個訓練站","examples":[{"en":"The playground could be divided into several stations.","zh":"操場可以被分成幾個訓練站。"},{"en":"To be divided into several stations means to be separated into different activity areas.","zh":"be divided into several stations 的意思是被分成不同活動區域。"},{"en":"A hall can be divided into stations for skipping, stretching, balance, and strength exercises.","zh":"禮堂可以被分成跳繩、伸展、平衡和力量練習訓練站。"},{"en":"Dividing the space into stations helps many groups work at the same time.","zh":"把空間分成訓練站，可以幫助多個小組同時活動。"},{"en":"This phrase describes a practical layout for active lessons.","zh":"這個短語描述活躍課堂的實際場地安排。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"skipping","meaning":"跳繩","examples":[{"en":"One station could focus on skipping.","zh":"其中一個訓練站可以集中於跳繩。"},{"en":"Skipping is an exercise in which a person jumps over a rope repeatedly.","zh":"skipping 是一種人反覆跳過繩子的運動。"},{"en":"Skipping can improve fitness, rhythm, coordination, and stamina.","zh":"跳繩可以改善體能、節奏感、協調和耐力。"},{"en":"Students can measure progress by counting how many skips they complete in one minute.","zh":"學生可以透過記錄一分鐘內完成多少次跳繩來量度進步。"},{"en":"This activity is simple, inexpensive, and suitable for different ability levels.","zh":"這項活動簡單、成本低，並適合不同能力水平。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"agility ladders","meaning":"敏捷梯","examples":[{"en":"Students could practise footwork with agility ladders.","zh":"學生可以用敏捷梯練習步法。"},{"en":"Agility ladders are flat ladder-like training tools used for quick footwork exercises.","zh":"agility ladders 是平放在地上、像梯子的訓練工具，用於快速步法練習。"},{"en":"Students step in and out of agility ladders to practise speed, balance, and coordination.","zh":"學生踏進踏出敏捷梯，以練習速度、平衡和協調。"},{"en":"Agility ladder drills can be adjusted for beginners and stronger students.","zh":"敏捷梯操練可以為初學者和能力較強的學生調整。"},{"en":"This phrase describes equipment that trains movement control.","zh":"這個短語描述訓練動作控制的器材。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"resistance-band exercises","meaning":"阻力帶練習","examples":[{"en":"Resistance-band exercises can help students build strength safely.","zh":"阻力帶練習可以幫助學生安全地建立力量。"},{"en":"Resistance-band exercises are strength exercises using stretchy bands that create resistance.","zh":"resistance-band exercises 是使用有彈性的阻力帶來產生阻力的力量練習。"},{"en":"Students can use resistance bands to train arms, shoulders, legs, or core muscles.","zh":"學生可以使用阻力帶訓練手臂、肩膀、雙腿或核心肌肉。"},{"en":"These exercises are safer for beginners because the resistance can be controlled.","zh":"這些練習對初學者較安全，因為阻力可以控制。"},{"en":"This phrase describes a simple way to build strength without heavy equipment.","zh":"這個短語描述不需重型器材也能建立力量的簡單方法。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"balance tasks","meaning":"平衡訓練","examples":[{"en":"Balance tasks can improve control and coordination.","zh":"平衡訓練可以改善控制和協調。"},{"en":"Balance tasks are exercises that train people to stay steady while moving or holding a position.","zh":"balance tasks 是訓練人們在移動或保持姿勢時維持穩定的練習。"},{"en":"Standing on one leg or walking along a line can be a balance task.","zh":"單腳站立或沿着一條線行走都可以是平衡訓練。"},{"en":"Balance tasks help students control their bodies and reduce the risk of falling.","zh":"平衡訓練幫助學生控制身體，並減少跌倒風險。"},{"en":"This phrase describes exercises that build stability, not speed alone.","zh":"這個短語描述建立穩定性的練習，而不只是速度。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"stretching","meaning":"伸展運動","examples":[{"en":"Stretching could be included as one station.","zh":"伸展運動可以包括成為其中一個訓練站。"},{"en":"Stretching means slowly lengthening muscles to improve flexibility and prepare or relax the body.","zh":"stretching 的意思是慢慢拉長肌肉，以改善柔軟度並準備或放鬆身體。"},{"en":"Students may stretch their legs, shoulders, and back after fitness exercises.","zh":"學生可以在體能練習後伸展雙腿、肩膀和背部。"},{"en":"Stretching can reduce tightness and help prevent injury when done properly.","zh":"正確進行伸展運動可以減少繃緊並幫助防止受傷。"},{"en":"This activity reminds students that PE includes recovery as well as effort.","zh":"這項活動提醒學生，體育課包括恢復，也包括努力。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"work in small groups","meaning":"以小組形式活動","examples":[{"en":"Students would work in small groups during the circuit.","zh":"學生會在循環訓練中以小組形式活動。"},{"en":"To work in small groups means to complete activities with a few classmates rather than the whole class at once.","zh":"work in small groups 的意思是與幾位同學一起完成活動，而不是全班同時做同一件事。"},{"en":"Students working in small groups can encourage one another and share equipment more easily.","zh":"以小組形式活動的學生可以互相鼓勵，也較容易共用器材。"},{"en":"Small groups reduce waiting time because more students can participate together.","zh":"小組可以減少等候時間，因為更多學生能一起參與。"},{"en":"This phrase describes a cooperative class arrangement.","zh":"這個短語描述合作式課堂安排。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"rotate every few minutes","meaning":"每隔幾分鐘輪換","examples":[{"en":"Students would rotate every few minutes.","zh":"學生會每隔幾分鐘輪換。"},{"en":"To rotate every few minutes means to move from one station or activity to another after a short time.","zh":"rotate every few minutes 的意思是短時間後由一個訓練站或活動轉到另一個。"},{"en":"A group may rotate from skipping to stretching after three minutes.","zh":"小組可以在三分鐘後由跳繩輪換到伸展。"},{"en":"Regular rotation keeps the lesson lively and gives students different kinds of movement.","zh":"定時輪換令課堂保持活躍，並給學生不同種類的動作。"},{"en":"This phrase describes organised change during an activity.","zh":"這個短語描述活動中的有組織轉換。"}],"source":"2015 Q2.pdf","sourcePage":6},{"front":"offer three levels","meaning":"提供三個難度級別","examples":[{"en":"Each station could offer three levels.","zh":"每個訓練站可以提供三個難度級別。"},{"en":"To offer three levels means to provide three degrees of difficulty for students to choose from.","zh":"offer three levels 的意思是提供三種難度讓學生選擇。"},{"en":"A skipping station may offer easy, standard, and challenge levels.","zh":"跳繩站可以提供容易、標準和挑戰級別。"},{"en":"Offering levels helps both beginners and stronger students participate meaningfully.","zh":"提供級別幫助初學者和能力較強的學生都有意義地參與。"},{"en":"This phrase shows how an activity can become more inclusive.","zh":"這個短語展示活動如何變得更共融。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"beginner, standard and challenge","meaning":"初階、標準和挑戰","examples":[{"en":"The three levels could be beginner, standard and challenge.","zh":"三個級別可以是初階、標準和挑戰。"},{"en":"Beginner, standard and challenge describe three levels from easier to harder.","zh":"beginner, standard and challenge 描述由較容易到較困難的三個級別。"},{"en":"A beginner level helps students who are new or less confident.","zh":"初階級別幫助新手或較沒有信心的學生。"},{"en":"A challenge level gives stronger students a way to push themselves further.","zh":"挑戰級別給能力較強的學生一個進一步挑戰自己的方法。"},{"en":"This phrase shows how one activity can fit different abilities.","zh":"這個短語展示同一活動如何適合不同能力。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"participate safely","meaning":"安全地參與","examples":[{"en":"Less fit students can still participate safely.","zh":"體能較弱的學生仍可以安全地參與。"},{"en":"To participate safely means to join an activity without unreasonable risk of injury or embarrassment.","zh":"participate safely 的意思是在沒有不合理受傷或尷尬風險下參與活動。"},{"en":"Students participate safely when exercises match their fitness level.","zh":"當練習配合學生體能水平時，他們就能安全地參與。"},{"en":"Safe participation helps weaker students try instead of standing aside.","zh":"安全參與幫助能力較弱的學生嘗試，而不是站在一旁。"},{"en":"This phrase shows that inclusion must consider safety and confidence.","zh":"這個短語顯示共融必須考慮安全和信心。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"push oneself further","meaning":"進一步挑戰自己","examples":[{"en":"More athletic students can push themselves further.","zh":"運動能力較強的學生可以進一步挑戰自己。"},{"en":"To push oneself further means to challenge oneself to do a little more or improve beyond the usual level.","zh":"push oneself further 的意思是挑戰自己多做一點，或超越平常水平。"},{"en":"A strong student may push herself further by choosing the challenge level in each station.","zh":"能力強的學生可以在每個訓練站選擇挑戰級別，進一步挑戰自己。"},{"en":"Pushing oneself further is healthy when it is done safely and voluntarily.","zh":"在安全和自願的情況下進一步挑戰自己是健康的。"},{"en":"This phrase shows personal challenge rather than comparison with others.","zh":"這個短語展示個人挑戰，而不是與別人比較。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"change the focus from...to...","meaning":"把焦點由……轉為……","examples":[{"en":"The activity changes the focus from comparison to personal progress.","zh":"這項活動把焦點由比較轉為個人進步。"},{"en":"Change the focus from A to B means shift attention away from one thing and toward another.","zh":"change the focus from A to B 的意思是把注意力從一件事轉向另一件事。"},{"en":"PE improves when it changes the focus from winning to improving one’s own result.","zh":"當體育課把焦點由勝利轉為改善自己的成績時，它會變得更好。"},{"en":"This structure helps explain how a new activity changes students’ mindset.","zh":"這個結構幫助解釋新活動如何改變學生心態。"},{"en":"It is useful when describing a better educational purpose.","zh":"當描述更好的教育目的時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"personal progress","meaning":"個人進步","examples":[{"en":"Circuit training encourages personal progress.","zh":"循環訓練鼓勵個人進步。"},{"en":"Personal progress means improvement measured against one’s own previous performance.","zh":"personal progress 是以自己過去表現來衡量的改善。"},{"en":"A student makes personal progress when he skips ten more times than last week.","zh":"如果學生比上星期多跳十次繩，他就是取得個人進步。"},{"en":"Personal progress can motivate students who do not usually win games.","zh":"個人進步可以激勵平時不常勝出比賽的學生。"},{"en":"This phrase shifts attention from beating others to improving oneself.","zh":"這個短語把注意力由打敗別人轉向改善自己。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"instead of asking","meaning":"而不是問","examples":[{"en":"Instead of asking who is best, students can focus on improvement.","zh":"而不是問誰最好，學生可以專注於進步。"},{"en":"Instead of asking means choosing not to focus on one question and focusing on another idea instead.","zh":"instead of asking 的意思是不聚焦某個問題，而改為聚焦另一個想法。"},{"en":"Instead of asking who ran fastest, students can ask whether they improved their own time.","zh":"學生可以不問誰跑得最快，而問自己是否改善了時間。"},{"en":"This phrase helps replace competition with personal reflection.","zh":"這個短語幫助以個人反思取代競爭。"},{"en":"It is useful when suggesting a healthier way to judge success.","zh":"當建議更健康的成功標準時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"improve my own result","meaning":"改善自己的成績","examples":[{"en":"A student can try to improve his own result from last week.","zh":"學生可以嘗試改善自己上星期的成績。"},{"en":"To improve my own result means to do better than my previous performance.","zh":"improve my own result 的意思是比自己過去的表現做得更好。"},{"en":"A student may improve his own result by completing more skips in one minute.","zh":"學生可以透過一分鐘內完成更多次跳繩來改善自己的成績。"},{"en":"Focusing on one’s own result makes PE less embarrassing and more encouraging.","zh":"專注於自己的成績，令體育課較不尷尬，也更令人鼓舞。"},{"en":"This phrase supports personal progress rather than class ranking.","zh":"這個短語支持個人進步，而不是班級排名。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"stay active at the same time","meaning":"同時保持活動","examples":[{"en":"The activity allows everyone to stay active at the same time.","zh":"這項活動讓每個人同時保持活動。"},{"en":"To stay active at the same time means all students keep moving during the same period.","zh":"stay active at the same time 的意思是所有學生在同一段時間內保持活動身體。"},{"en":"Circuit stations help students stay active at the same time instead of waiting in one long line.","zh":"循環訓練站幫助學生同時保持活動，而不是排成一條長隊等候。"},{"en":"When everyone stays active, PE becomes more effective for fitness.","zh":"當每個人都保持活動，體育課對體能更有效。"},{"en":"This phrase highlights participation and efficient use of lesson time.","zh":"這個短語突顯參與和有效運用課堂時間。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"thereby reducing","meaning":"從而減少","examples":[{"en":"The circuit keeps students active, thereby reducing long queues.","zh":"循環訓練讓學生保持活動，從而減少長長的人龍。"},{"en":"Thereby reducing means causing something to become less as a result.","zh":"thereby reducing 的意思是因此令某事物減少。"},{"en":"More stations allow more students to move at once, thereby reducing waiting time.","zh":"更多訓練站讓更多學生同時活動，從而減少等候時間。"},{"en":"This phrase connects a solution directly to its benefit.","zh":"這個短語把解決方法直接連接到其好處。"},{"en":"It is useful in proposals when explaining why a measure works.","zh":"在建議書中解釋措施為何有效時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":7},{"front":"long queues","meaning":"長長的人龍","examples":[{"en":"Circuit training can reduce long queues in PE lessons.","zh":"循環訓練可以減少體育課中的長長人龍。"},{"en":"Long queues are lines of people waiting for a long time.","zh":"long queues 是很多人排隊等候很久的隊伍。"},{"en":"Long queues form when only one student can practise at a time.","zh":"當每次只有一名學生能練習時，長長的人龍就會形成。"},{"en":"Long queues make PE less active because students spend too much time waiting.","zh":"長長的人龍令體育課較不活躍，因為學生花太多時間等待。"},{"en":"This phrase describes an organisation problem that reduces movement.","zh":"這個短語描述會減少活動量的組織問題。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"embarrassment","meaning":"尷尬","examples":[{"en":"The activity can reduce embarrassment for less confident students.","zh":"這項活動可以減少較沒信心學生的尷尬。"},{"en":"Embarrassment is the uncomfortable feeling of being ashamed or exposed in front of others.","zh":"embarrassment 是在別人面前感到羞愧或被暴露的不舒服感覺。"},{"en":"A student may feel embarrassment after missing a ball while classmates watch.","zh":"學生在同學觀看下打失球後，可能感到尷尬。"},{"en":"PE activities reduce embarrassment when students can practise at their own level.","zh":"當學生能按自己的程度練習時，體育活動可以減少尷尬。"},{"en":"This word describes an emotion that can stop participation.","zh":"這個詞描述一種會阻止參與的情緒。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"competitive ball games","meaning":"競爭性球類活動","examples":[{"en":"Some students dislike competitive ball games.","zh":"有些學生不喜歡競爭性球類活動。"},{"en":"Competitive ball games are sports with a ball where teams or players try to beat one another.","zh":"competitive ball games 是球員或隊伍試圖打敗對方的球類運動。"},{"en":"Basketball and volleyball can become competitive ball games when winning is the main focus.","zh":"當勝利成為主要焦點時，籃球和排球可以變成競爭性球類活動。"},{"en":"Competitive ball games may motivate strong players but frighten less confident students.","zh":"競爭性球類活動可能激勵強項學生，但令較沒信心的學生害怕。"},{"en":"This phrase helps explain why PE needs more than traditional sports.","zh":"這個短語幫助解釋為何體育課需要不只是傳統運動。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"record how many skips","meaning":"記錄能跳多少次繩","examples":[{"en":"A student may enjoy recording how many skips he can complete.","zh":"學生可能喜歡記錄自己能跳多少次繩。"},{"en":"To record how many skips means to count and write down the number of successful rope jumps.","zh":"record how many skips 的意思是計算並寫下成功跳繩的次數。"},{"en":"A student can record how many skips he completes each week to see progress.","zh":"學生可以每星期記錄自己跳多少次繩，以看見進步。"},{"en":"Recording results makes improvement visible and personal.","zh":"記錄成績令進步變得可見和個人化。"},{"en":"This phrase shows a simple way to measure fitness progress.","zh":"這個短語展示量度體能進步的簡單方法。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"complete in one minute","meaning":"在一分鐘內完成","examples":[{"en":"He can record how many skips he can complete in one minute.","zh":"他可以記錄自己在一分鐘內能完成多少次跳繩。"},{"en":"Complete in one minute means finish or perform as much as possible within sixty seconds.","zh":"complete in one minute 的意思是在六十秒內完成或做到盡可能多。"},{"en":"A student may count how many squats he can complete in one minute.","zh":"學生可以計算自己在一分鐘內能完成多少次深蹲。"},{"en":"Measuring what students complete in one minute makes progress clear and fair.","zh":"量度學生在一分鐘內完成多少，能令進步清晰而公平。"},{"en":"This phrase sets a simple time limit for personal improvement.","zh":"這個短語為個人進步設定簡單時間限制。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"small, visible improvements","meaning":"細小而看得見的進步","examples":[{"en":"Small, visible improvements can make PE rewarding.","zh":"細小而看得見的進步可以令體育課有滿足感。"},{"en":"Small, visible improvements are minor changes that students can clearly notice.","zh":"small, visible improvements 是學生能清楚注意到的小改變。"},{"en":"Completing five more skips than last week is a small, visible improvement.","zh":"比上星期多完成五次跳繩，就是細小而看得見的進步。"},{"en":"These improvements encourage students because progress feels real and achievable.","zh":"這些進步鼓勵學生，因為進展感覺真實而做得到。"},{"en":"This phrase shows why personal records can motivate learners.","zh":"這個短語展示為何個人紀錄能激勵學習者。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"achievable and rewarding","meaning":"做得到而有滿足感","examples":[{"en":"The activity would make PE feel achievable and rewarding.","zh":"這項活動會令體育課感覺做得到而有滿足感。"},{"en":"Achievable and rewarding means possible to do and satisfying after effort.","zh":"achievable and rewarding 的意思是可以做到，並在努力後令人滿足。"},{"en":"A beginner-level station can make PE feel achievable for less confident students.","zh":"初階訓練站可以令較沒信心的學生覺得體育課做得到。"},{"en":"Visible progress makes exercise rewarding because students can see their effort paying off.","zh":"看得見的進步令運動有滿足感，因為學生能看見努力有成果。"},{"en":"This phrase describes an activity that builds confidence and enjoyment.","zh":"這個短語描述建立信心和樂趣的活動。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"worth introducing","meaning":"值得引入","examples":[{"en":"A second activity worth introducing is ultimate frisbee.","zh":"第二項值得引入的活動是極限飛盤。"},{"en":"Worth introducing means useful or valuable enough to be added.","zh":"worth introducing 的意思是有用或有價值到值得加入。"},{"en":"Circuit training is worth introducing if it helps more students stay active.","zh":"如果循環訓練幫助更多學生保持活動，它就值得引入。"},{"en":"An activity is worth introducing when it solves a real problem in current lessons.","zh":"當一項活動能解決現時課堂的真實問題，它就值得引入。"},{"en":"This phrase helps recommend a new idea politely.","zh":"這個短語幫助禮貌地推薦新想法。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"ultimate frisbee","meaning":"極限飛盤","examples":[{"en":"Ultimate frisbee is suitable for mixed-ability groups.","zh":"極限飛盤適合能力混合的小組。"},{"en":"Ultimate frisbee is a team sport in which players pass a flying disc and score by catching it in an end zone.","zh":"ultimate frisbee 是一項團隊運動，球員傳接飛盤，並在得分區接住飛盤得分。"},{"en":"Ultimate frisbee needs running, passing, communication, and fair play.","zh":"極限飛盤需要跑動、傳接、溝通和公平競賽。"},{"en":"Because it involves less heavy contact, ultimate frisbee can feel safer than some ball games.","zh":"因為它較少激烈身體碰撞，極限飛盤可以比某些球類活動感覺更安全。"},{"en":"This sport can include different types of students, not only the strongest players.","zh":"這項運動可以包含不同類型學生，而不只是最強的球員。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"unlike traditional team sports","meaning":"不像傳統團隊運動","examples":[{"en":"Unlike traditional team sports, ultimate frisbee is easy to learn.","zh":"不像傳統團隊運動，極限飛盤容易學習。"},{"en":"Unlike traditional team sports means different from common sports such as football, basketball, or volleyball.","zh":"unlike traditional team sports 的意思是與足球、籃球或排球等常見運動不同。"},{"en":"Unlike traditional team sports, ultimate frisbee may give quieter students more ways to contribute.","zh":"不像傳統團隊運動，極限飛盤可能給較安靜的學生更多貢獻方式。"},{"en":"This phrase introduces a contrast between a new activity and familiar sports.","zh":"這個短語引入新活動與熟悉運動之間的對比。"},{"en":"It helps explain why the proposed activity may solve existing problems.","zh":"它幫助解釋為何建議活動可能解決現有問題。"}],"source":"2015 Q2.pdf","sourcePage":8},{"front":"easy to learn","meaning":"容易學習","examples":[{"en":"Ultimate frisbee is easy to learn.","zh":"極限飛盤容易學習。"},{"en":"Easy to learn means simple enough for beginners to understand and start quickly.","zh":"easy to learn 的意思是簡單到初學者能快速理解和開始。"},{"en":"An activity is easy to learn when students can join after a short explanation.","zh":"當學生聽過簡短解釋後就能參與，活動就是容易學習。"},{"en":"Easy-to-learn sports reduce fear because students do not need years of experience.","zh":"容易學習的運動減少恐懼，因為學生不需要多年經驗。"},{"en":"This phrase explains why an activity may suit a whole class.","zh":"這個短語解釋為何某活動可能適合全班。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"inexpensive to organise","meaning":"籌辦成本低","examples":[{"en":"The game is inexpensive to organise.","zh":"這項遊戲籌辦成本低。"},{"en":"Inexpensive to organise means not requiring much money, equipment, or special facilities.","zh":"inexpensive to organise 的意思是不需要很多金錢、器材或特殊設施。"},{"en":"Ultimate frisbee is inexpensive to organise because it needs only discs, cones, and open space.","zh":"極限飛盤籌辦成本低，因為只需要飛盤、雪糕筒和空地。"},{"en":"Low cost makes an activity easier for schools to try regularly.","zh":"成本低令學校較容易定期試行活動。"},{"en":"This phrase highlights the practical advantage of a proposal.","zh":"這個短語突顯建議的實際優點。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"suitable for mixed-ability groups","meaning":"適合能力混合的小組","examples":[{"en":"Ultimate frisbee is suitable for mixed-ability groups.","zh":"極限飛盤適合能力混合的小組。"},{"en":"Suitable for mixed-ability groups means useful for students with different skill and fitness levels.","zh":"suitable for mixed-ability groups 的意思是適合技能和體能不同的學生。"},{"en":"A sport is suitable for mixed-ability groups when beginners and strong players can both contribute.","zh":"當初學者和能力強的學生都能貢獻時，該運動就適合能力混合的小組。"},{"en":"Ultimate frisbee suits mixed abilities because students can help through running, passing, planning, or communication.","zh":"極限飛盤適合混合能力，因為學生可以透過跑動、傳球、計劃或溝通提供幫助。"},{"en":"This phrase shows that the activity is inclusive.","zh":"這個短語顯示活動具共融性。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"a few discs, cones and an open space","meaning":"幾個飛盤、雪糕筒和一片空地","examples":[{"en":"A class only needs a few discs, cones and an open space.","zh":"一班學生只需要幾個飛盤、雪糕筒和一片空地。"},{"en":"A few discs, cones and an open space are simple materials needed to set up ultimate frisbee.","zh":"a few discs, cones and an open space 是設置極限飛盤所需的簡單材料。"},{"en":"Discs are used for passing, cones mark the playing area, and open space allows movement.","zh":"飛盤用來傳接，雪糕筒標示場地，空地讓學生跑動。"},{"en":"Because the equipment is simple, the activity is practical for schools.","zh":"因為器材簡單，這項活動對學校來說實際可行。"},{"en":"This phrase shows that the sport does not need expensive facilities.","zh":"這個短語顯示這項運動不需要昂貴設施。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"running into space","meaning":"跑到空位","examples":[{"en":"The game involves passing and running into space.","zh":"這項遊戲涉及傳球和跑到空位。"},{"en":"Running into space means moving into an open area where a teammate can pass to you.","zh":"running into space 的意思是跑到可以讓隊友傳球給你的空曠位置。"},{"en":"In ultimate frisbee, a player runs into space to receive the disc safely.","zh":"在極限飛盤中，球員跑到空位以安全接住飛盤。"},{"en":"Running into space teaches students teamwork and awareness of the whole field.","zh":"跑到空位教導學生團隊合作和對整個場地的觀察。"},{"en":"This phrase describes movement that is purposeful, not random.","zh":"這個短語描述有目的而不是隨機的移動。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"heavy physical contact","meaning":"激烈身體碰撞","examples":[{"en":"The game involves defending without heavy physical contact.","zh":"這項遊戲涉及防守，但沒有激烈身體碰撞。"},{"en":"Heavy physical contact means strong body contact such as pushing, crashing, or tackling.","zh":"heavy physical contact 是推撞、碰撞或攔截等強烈身體接觸。"},{"en":"Some students fear sports with heavy physical contact because they worry about injury.","zh":"有些學生害怕有激烈身體碰撞的運動，因為他們擔心受傷。"},{"en":"Reducing heavy physical contact can make PE safer and less intimidating.","zh":"減少激烈身體碰撞可以令體育課更安全、沒那麼令人卻步。"},{"en":"This phrase explains why ultimate frisbee may suit more students.","zh":"這個短語解釋為何極限飛盤可能適合更多學生。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"safer and less intimidating","meaning":"更安全、沒那麼令人卻步","examples":[{"en":"Ultimate frisbee is safer and less intimidating than many ball games.","zh":"極限飛盤比許多球類活動更安全、沒那麼令人卻步。"},{"en":"Safer and less intimidating means less likely to cause injury or fear.","zh":"safer and less intimidating 的意思是較不容易造成受傷或恐懼。"},{"en":"A sport with clear rules and little contact can feel safer and less intimidating.","zh":"有清晰規則和少身體碰撞的運動，可以感覺更安全、沒那麼令人卻步。"},{"en":"Students may participate more willingly when an activity feels safer and less frightening.","zh":"當活動感覺更安全和較不嚇人時，學生可能更願意參與。"},{"en":"This phrase describes an environment that encourages hesitant students.","zh":"這個短語描述能鼓勵猶豫學生的環境。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"highly competitive ball games","meaning":"高度競爭性的球類活動","examples":[{"en":"Some students feel nervous during highly competitive ball games.","zh":"有些學生在高度競爭性的球類活動中感到緊張。"},{"en":"Highly competitive ball games are sports where winning, speed, and strong performance become very important.","zh":"highly competitive ball games 是勝利、速度和強表現變得十分重要的球類運動。"},{"en":"Students may feel anxious in highly competitive ball games if stronger players dominate.","zh":"如果較強球員主導比賽，學生在高度競爭性的球類活動中可能感到焦慮。"},{"en":"These games can be exciting for some students but stressful for others.","zh":"這些遊戲對某些學生來說刺激，但對其他學生來說有壓力。"},{"en":"This phrase explains why schools should include less intimidating alternatives.","zh":"這個短語解釋為何學校應加入較不令人卻步的替代活動。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"different types of learners","meaning":"不同類型的學習者","examples":[{"en":"The activity gives different types of learners a meaningful role.","zh":"這項活動給不同類型的學習者一個有意義的角色。"},{"en":"Different types of learners are students who learn, move, think, or contribute in different ways.","zh":"different types of learners 是以不同方式學習、活動、思考或貢獻的學生。"},{"en":"Some learners are fast runners, some are careful planners, and some are strong communicators.","zh":"有些學習者跑得快，有些擅長細心計劃，有些擅長溝通。"},{"en":"PE becomes more inclusive when different types of learners can all succeed.","zh":"當不同類型的學習者都能成功時，體育課會更共融。"},{"en":"This phrase reminds teachers that ability is not one single thing.","zh":"這個短語提醒老師，能力不是單一一種東西。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"meaningful role","meaning":"有意義的角色","examples":[{"en":"Every student can have a meaningful role in the game.","zh":"每位學生都可以在遊戲中有一個有意義的角色。"},{"en":"A meaningful role is a useful part that makes a person feel included and valuable.","zh":"meaningful role 是有用的角色，令人感到被包括和有價值。"},{"en":"A quieter student may have a meaningful role by calling for passes and helping teammates position themselves.","zh":"較安靜的學生可以透過叫隊友傳球和幫助隊友走位，擁有有意義的角色。"},{"en":"When students have meaningful roles, they are more likely to join actively.","zh":"當學生有有意義的角色時，他們更可能積極參與。"},{"en":"This phrase shows that participation should include real contribution.","zh":"這個短語顯示參與應包括真正貢獻。"}],"source":"2015 Q2.pdf","sourcePage":9},{"front":"fast runners","meaning":"跑得快的學生","examples":[{"en":"Fast runners can create space in ultimate frisbee.","zh":"跑得快的學生可以在極限飛盤中拉開空位。"},{"en":"Fast runners are students who can move quickly across the playing area.","zh":"fast runners 是能快速穿過場地的學生。"},{"en":"In ultimate frisbee, fast runners can draw defenders away from teammates.","zh":"在極限飛盤中，跑得快的學生可以把防守者引離隊友。"},{"en":"Fast runners help the team, but the game should not depend only on speed.","zh":"跑得快的學生能幫助團隊，但比賽不應只依靠速度。"},{"en":"This phrase describes one type of strength in PE.","zh":"這個短語描述體育課中的一種長處。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"create space","meaning":"拉開空位","examples":[{"en":"Fast runners can create space for their teammates.","zh":"跑得快的學生可以為隊友拉開空位。"},{"en":"To create space means to move in a way that opens room for others to pass, run, or play.","zh":"create space 的意思是透過移動打開空間，讓別人傳球、跑動或比賽。"},{"en":"A player creates space by running away from defenders and pulling them aside.","zh":"球員可以透過跑離防守者並把他們引開來拉開空位。"},{"en":"Creating space helps teammates because they have more room to receive the disc.","zh":"拉開空位能幫助隊友，因為他們有更多空間接住飛盤。"},{"en":"This phrase describes teamwork through movement.","zh":"這個短語描述透過移動進行團隊合作。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"careful thinkers","meaning":"思考細心的學生","examples":[{"en":"Careful thinkers can plan passes.","zh":"思考細心的學生可以計劃傳球。"},{"en":"Careful thinkers are students who observe, analyse, and make decisions thoughtfully.","zh":"careful thinkers 是會觀察、分析並深思熟慮作決定的學生。"},{"en":"A careful thinker may notice which teammate is free before passing the disc.","zh":"思考細心的學生可能在傳飛盤前注意哪位隊友無人防守。"},{"en":"Team sports benefit from careful thinkers because not every contribution is about speed.","zh":"團隊運動受益於思考細心的學生，因為不是每種貢獻都關於速度。"},{"en":"This phrase recognises mental skills in physical education.","zh":"這個短語承認體育教育中的思考技能。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"plan passes","meaning":"計劃傳球","examples":[{"en":"Careful thinkers can plan passes during the game.","zh":"思考細心的學生可以在比賽中計劃傳球。"},{"en":"To plan passes means to decide where, when, and to whom the ball or disc should be passed.","zh":"plan passes 的意思是決定何處、何時以及傳給誰。"},{"en":"A player may plan a pass by watching defenders and choosing the safest teammate.","zh":"球員可以透過觀察防守者並選擇最安全的隊友來計劃傳球。"},{"en":"Planning passes improves teamwork because players think before acting.","zh":"計劃傳球可以改善團隊合作，因為球員在行動前會思考。"},{"en":"This phrase describes strategy in a team sport.","zh":"這個短語描述團隊運動中的策略。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"less aggressive students","meaning":"較不進取的學生","examples":[{"en":"Less aggressive students can still contribute through communication.","zh":"較不進取的學生仍可以透過溝通作出貢獻。"},{"en":"Less aggressive students are students who are not forceful, rough, or highly competitive in games.","zh":"less aggressive students 是在比賽中較不強勢、粗暴或高度競爭的學生。"},{"en":"A less aggressive student may prefer passing, positioning, or encouraging teammates.","zh":"較不進取的學生可能較喜歡傳球、走位或鼓勵隊友。"},{"en":"PE should give less aggressive students ways to contribute without physical intimidation.","zh":"體育課應給較不進取的學生在沒有身體壓迫下作出貢獻的方法。"},{"en":"This phrase helps include quieter or gentler learners.","zh":"這個短語幫助包括較安靜或較溫和的學習者。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"contribute through communication and positioning","meaning":"透過溝通和走位作出貢獻","examples":[{"en":"Students can contribute through communication and positioning.","zh":"學生可以透過溝通和走位作出貢獻。"},{"en":"To contribute through communication and positioning means to help the team by speaking clearly and standing or moving wisely.","zh":"contribute through communication and positioning 的意思是透過清楚說話，以及明智地站位或移動來幫助團隊。"},{"en":"A student may call out open space or move into a better position to receive a pass.","zh":"學生可以喊出空位，或移動到更好的位置接球。"},{"en":"Communication and positioning allow students to help even if they are not the fastest runners.","zh":"溝通和走位讓學生即使不是跑得最快，也能幫助團隊。"},{"en":"This phrase shows that teamwork has many forms.","zh":"這個短語顯示團隊合作有很多形式。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, ultimate frisbee encourages fair play.","zh":"更好的是，極限飛盤鼓勵公平競賽。"},{"en":"Better still means even better or more importantly in addition to the previous point.","zh":"better still 的意思是更好的是，或在前一點之外更重要的是。"},{"en":"The activity is easy to learn; better still, it teaches teamwork.","zh":"這項活動容易學習；更好的是，它教導團隊合作。"},{"en":"Writers use this phrase to add a stronger advantage.","zh":"作者使用這個短語來加入更強的優點。"},{"en":"It helps build a persuasive recommendation.","zh":"它幫助建立有說服力的建議。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"encourage fair play","meaning":"鼓勵公平競賽","examples":[{"en":"Ultimate frisbee encourages fair play.","zh":"極限飛盤鼓勵公平競賽。"},{"en":"To encourage fair play means to promote honesty, respect, and fairness during a game.","zh":"encourage fair play 的意思是在比賽中推動誠實、尊重和公平。"},{"en":"A sport encourages fair play when players admit mistakes and respect decisions.","zh":"當球員承認錯誤並尊重決定時，該運動就是鼓勵公平競賽。"},{"en":"Fair play helps students compete without becoming cruel or dishonest.","zh":"公平競賽幫助學生競爭時不變得殘酷或不誠實。"},{"en":"This phrase shows that PE can teach values as well as fitness.","zh":"這個短語顯示體育課可以教導價值觀，也可以訓練體能。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"be expected to","meaning":"被期望","examples":[{"en":"Players are expected to respect rules.","zh":"球員被期望尊重規則。"},{"en":"Be expected to means people are supposed to do something because it is required or considered right.","zh":"be expected to 的意思是人們應該做某事，因為它被要求或被視為正確。"},{"en":"Students are expected to listen to safety instructions before using equipment.","zh":"學生在使用器材前被期望聆聽安全指示。"},{"en":"When players are expected to follow fair rules, the game becomes safer and more respectful.","zh":"當球員被期望遵守公平規則，比賽會更安全和更有尊重。"},{"en":"This phrase describes a standard of behaviour.","zh":"這個短語描述行為標準。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"respect rules","meaning":"尊重規則","examples":[{"en":"Players are expected to respect rules.","zh":"球員被期望尊重規則。"},{"en":"To respect rules means to follow rules honestly because they protect fairness and safety.","zh":"respect rules 的意思是誠實遵守規則，因為規則保護公平和安全。"},{"en":"Students respect rules when they admit a foul instead of pretending nothing happened.","zh":"當學生承認犯規，而不是假裝甚麼都沒有發生時，就是尊重規則。"},{"en":"Respecting rules makes games fairer for both strong and weaker players.","zh":"尊重規則令比賽對強項和較弱的球員都更公平。"},{"en":"This phrase connects discipline with fairness.","zh":"這個短語把紀律與公平連繫起來。"}],"source":"2015 Q2.pdf","sourcePage":10},{"front":"resolve minor disputes calmly","meaning":"冷靜解決小爭議","examples":[{"en":"Players learn to resolve minor disputes calmly.","zh":"球員學會冷靜解決小爭議。"},{"en":"To resolve minor disputes calmly means to settle small disagreements without shouting or anger.","zh":"resolve minor disputes calmly 的意思是不靠叫喊或憤怒來處理小分歧。"},{"en":"Players may resolve a minor dispute by discussing whether a pass was caught inside the line.","zh":"球員可以透過討論傳球是否在界內接住，來冷靜解決小爭議。"},{"en":"Calmly resolving disputes teaches students communication and self-control.","zh":"冷靜解決爭議教導學生溝通和自制。"},{"en":"This phrase shows how sport can train social skills.","zh":"這個短語顯示運動如何訓練社交技巧。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"in this sense","meaning":"從這個意義上說","examples":[{"en":"In this sense, PE would also teach sportsmanship.","zh":"從這個意義上說，體育課也會教導運動精神。"},{"en":"In this sense means in this particular way or from this point of view.","zh":"in this sense 的意思是以這種特定方式或從這個角度而言。"},{"en":"If PE teaches students to respect rules, in this sense it teaches character as well as fitness.","zh":"如果體育課教學生尊重規則，從這個意義上說，它既教體能，也教品格。"},{"en":"This phrase links an example to a wider meaning.","zh":"這個短語把例子連接到更廣泛意義。"},{"en":"It is useful when explaining why a point matters.","zh":"當解釋某點為何重要時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"not merely train our bodies","meaning":"不只是鍛鍊身體","examples":[{"en":"PE would not merely train students’ bodies.","zh":"體育課不只是鍛鍊學生的身體。"},{"en":"Not merely train our bodies means not only improve physical strength, speed, or fitness.","zh":"not merely train our bodies 的意思是不只改善身體力量、速度或體能。"},{"en":"PE should not merely train bodies; it should also teach cooperation and responsibility.","zh":"體育課不應只是鍛鍊身體；它也應教導合作和責任感。"},{"en":"This phrase helps expand the purpose of physical education.","zh":"這個短語幫助擴展體育教育的目的。"},{"en":"It shows that sport can develop character as well as muscles.","zh":"它顯示運動可以培養品格，也可以鍛鍊肌肉。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"teach cooperation, responsibility and sportsmanship","meaning":"教導合作、責任感和運動精神","examples":[{"en":"PE can teach cooperation, responsibility and sportsmanship.","zh":"體育課可以教導合作、責任感和運動精神。"},{"en":"To teach cooperation, responsibility and sportsmanship means to help students learn teamwork, duty, fairness, and respect.","zh":"teach cooperation, responsibility and sportsmanship 的意思是幫助學生學習團隊合作、責任、公平和尊重。"},{"en":"A team sport teaches cooperation when students communicate instead of playing alone.","zh":"當學生溝通而不是各自玩，團隊運動就是教導合作。"},{"en":"PE teaches responsibility when students follow rules and care for equipment.","zh":"當學生遵守規則並愛護器材，體育課就是教導責任感。"},{"en":"This phrase shows that PE can build social values.","zh":"這個短語顯示體育課可以建立社交價值觀。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"to conclude","meaning":"總括而言","examples":[{"en":"To conclude, the school should review its PE lessons.","zh":"總括而言，學校應檢討其體育課。"},{"en":"To conclude means finally or to bring the argument to an end.","zh":"to conclude 的意思是最後或把論點作結。"},{"en":"To conclude, PE lessons should be more active, inclusive, and enjoyable.","zh":"總括而言，體育課應更活躍、更共融和更有趣。"},{"en":"Writers use this phrase before giving a final summary or recommendation.","zh":"作者在給出最終總結或建議前會使用這個短語。"},{"en":"It helps readers recognise the ending of a formal proposal.","zh":"它幫助讀者辨認正式建議書的結尾。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"sincerely hope","meaning":"衷心希望","examples":[{"en":"He sincerely hopes the school will review the PE lessons.","zh":"他衷心希望學校會檢討體育課。"},{"en":"To sincerely hope means to truly and honestly wish for something to happen.","zh":"sincerely hope 的意思是真誠地希望某事發生。"},{"en":"Students sincerely hope their suggestions will be considered by the school.","zh":"學生衷心希望學校會考慮他們的建議。"},{"en":"This phrase makes a request sound respectful and heartfelt.","zh":"這個短語令請求聽起來尊重而真摯。"},{"en":"It is useful in formal letters when asking for positive action.","zh":"在正式信件中請求正面行動時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"review our PE lessons","meaning":"檢討我們的體育課","examples":[{"en":"The Class Association hopes the school will review its PE lessons.","zh":"班會希望學校會檢討我們的體育課。"},{"en":"To review our PE lessons means to examine the current PE programme carefully to see what can improve.","zh":"review our PE lessons 的意思是仔細檢視現時體育課程，看看有甚麼可以改善。"},{"en":"Teachers may review PE lessons by collecting student feedback and observing participation.","zh":"老師可以透過收集學生意見和觀察參與情況來檢討體育課。"},{"en":"Reviewing lessons can show whether activities are inclusive, varied, and effective.","zh":"檢討課堂可以顯示活動是否共融、多元和有效。"},{"en":"This phrase asks for thoughtful evaluation before change.","zh":"這個短語要求在改變前進行有思考的評估。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"existing programme","meaning":"現有課程","examples":[{"en":"The existing programme still has value.","zh":"現有課程仍有價值。"},{"en":"The existing programme means the current set of lessons, activities, or arrangements.","zh":"existing programme 是目前的一套課堂、活動或安排。"},{"en":"A proposal may respect the existing programme while suggesting improvements.","zh":"建議書可以尊重現有課程，同時提出改善。"},{"en":"The existing PE programme may teach basic sports skills but still need more variety.","zh":"現有體育課程可能教授基本運動技巧，但仍需要更多變化。"},{"en":"This phrase helps avoid sounding completely critical.","zh":"這個短語幫助避免聽起來完全批評。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"considerable room for improvement","meaning":"有相當大的改善空間","examples":[{"en":"There is considerable room for improvement in PE lessons.","zh":"體育課有相當大的改善空間。"},{"en":"Considerable room for improvement means there are many meaningful ways something can become better.","zh":"considerable room for improvement 的意思是某事有很多有意義的改善方法。"},{"en":"If many students feel excluded, there is considerable room for improvement in the activity design.","zh":"如果許多學生感到被排除，活動設計就有相當大的改善空間。"},{"en":"This phrase is polite because it criticises a problem without sounding rude.","zh":"這個短語很有禮貌，因為它指出問題而不顯得粗魯。"},{"en":"It is useful when recognising value while still calling for change.","zh":"當承認價值但仍呼籲改變時，它很有用。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"pilot fitness circuit training","meaning":"試行體能循環訓練","examples":[{"en":"The school could pilot fitness circuit training once or twice a month.","zh":"學校可以每月一至兩次試行體能循環訓練。"},{"en":"To pilot fitness circuit training means to try it on a small scale before making it regular.","zh":"pilot fitness circuit training 的意思是在小規模下試行體能循環訓練，然後才把它變成常規。"},{"en":"A school may pilot the activity with one class before using it across all forms.","zh":"學校可以先在一班試行這項活動，再推展至所有級別。"},{"en":"Piloting a new activity allows teachers to collect feedback and adjust problems.","zh":"試行新活動讓老師收集意見並調整問題。"},{"en":"This phrase describes a careful way to test a proposal.","zh":"這個短語描述測試建議的謹慎方法。"}],"source":"2015 Q2.pdf","sourcePage":11},{"front":"once or twice a month","meaning":"每月一至兩次","examples":[{"en":"The new activities could be tried once or twice a month.","zh":"新活動可以每月一至兩次試行。"},{"en":"Once or twice a month means one or two times each month.","zh":"once or twice a month 的意思是每個月一次或兩次。"},{"en":"A school may introduce ultimate frisbee once or twice a month to test student interest.","zh":"學校可以每月一至兩次引入極限飛盤，以測試學生興趣。"},{"en":"Trying activities once or twice a month makes change manageable for teachers.","zh":"每月一至兩次試行活動，令改變對老師而言較易管理。"},{"en":"This phrase gives a realistic frequency for a pilot scheme.","zh":"這個短語為試行計劃提供實際頻率。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"be willing to help","meaning":"願意協助","examples":[{"en":"The Class Association would be willing to help collect feedback.","zh":"班會願意協助收集意見。"},{"en":"Be willing to help means be ready and happy to offer support.","zh":"be willing to help 的意思是準備好並樂意提供支援。"},{"en":"Students may be willing to help set up cones or record classmates’ opinions.","zh":"學生可能願意協助擺放雪糕筒或記錄同學意見。"},{"en":"Offering help shows that the proposal is cooperative, not just demanding.","zh":"主動提出協助顯示建議是合作的，而不只是要求。"},{"en":"This phrase makes a request sound responsible and constructive.","zh":"這個短語令請求聽起來負責任而具建設性。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"collect student feedback","meaning":"收集學生意見","examples":[{"en":"The Class Association could collect student feedback afterwards.","zh":"班會可以之後收集學生意見。"},{"en":"To collect student feedback means to gather students’ opinions after an activity or change.","zh":"collect student feedback 的意思是在活動或改變後收集學生看法。"},{"en":"Students can collect feedback through short forms, class discussions, or online surveys.","zh":"學生可以透過簡短表格、班級討論或網上問卷收集意見。"},{"en":"Feedback helps teachers know whether new PE activities are enjoyable and effective.","zh":"意見回饋幫助老師知道新體育活動是否有趣和有效。"},{"en":"This phrase describes a way to improve decisions with real student voices.","zh":"這個短語描述用真實學生聲音改善決策的方法。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"make PE lessons more enjoyable","meaning":"令體育課更有趣","examples":[{"en":"These changes would make PE lessons more enjoyable.","zh":"這些改變會令體育課更有趣。"},{"en":"To make PE lessons more enjoyable means to make PE feel more pleasant, interesting, and satisfying.","zh":"make PE lessons more enjoyable 的意思是令體育課感覺更愉快、有趣和有滿足感。"},{"en":"More varied activities can make PE lessons more enjoyable for students who dislike ball games.","zh":"更多元的活動可以令不喜歡球類活動的學生覺得體育課更有趣。"},{"en":"Enjoyable lessons are more likely to encourage lifelong exercise.","zh":"有趣的課堂更可能鼓勵終身運動。"},{"en":"This phrase explains the positive result of the proposed changes.","zh":"這個短語解釋建議改變帶來的正面結果。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"more inclusive and more effective","meaning":"更共融、更有效","examples":[{"en":"The changes would make PE more inclusive and more effective.","zh":"這些改變會令體育課更共融、更有效。"},{"en":"More inclusive and more effective means more students can participate and the lessons achieve better results.","zh":"more inclusive and more effective 的意思是更多學生能參與，課堂也取得更好效果。"},{"en":"PE becomes more inclusive when activities suit beginners, confident players, and quieter students.","zh":"當活動適合初學者、有信心的球員和較安靜的學生時，體育課就更共融。"},{"en":"PE becomes more effective when students spend more time moving and improving.","zh":"當學生花更多時間活動和進步時，體育課就更有效。"},{"en":"This phrase combines fairness with practical success.","zh":"這個短語結合公平和實際成效。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"promote lifelong exercise","meaning":"推廣終身運動","examples":[{"en":"Better PE lessons can promote lifelong exercise.","zh":"更好的體育課可以推廣終身運動。"},{"en":"To promote lifelong exercise means to encourage people to keep being active throughout their lives.","zh":"promote lifelong exercise 的意思是鼓勵人們一生都保持活動。"},{"en":"PE promotes lifelong exercise when students discover activities they enjoy beyond school.","zh":"當學生發現在校外也享受的活動時，體育課就是推廣終身運動。"},{"en":"If students associate exercise with embarrassment, lifelong exercise becomes less likely.","zh":"如果學生把運動與尷尬聯繫起來，終身運動就較不可能發生。"},{"en":"This phrase describes the long-term purpose of physical education.","zh":"這個短語描述體育教育的長遠目的。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"I would be grateful if","meaning":"如你能……我將不勝感激","examples":[{"en":"I would be grateful if you could consider our views.","zh":"如你能考慮我們的意見，我將不勝感激。"},{"en":"I would be grateful if is a polite formal phrase used to make a request.","zh":"I would be grateful if 是用來提出請求的禮貌正式短語。"},{"en":"I would be grateful if the school could review the PE curriculum.","zh":"如學校能檢討體育課程，我們將不勝感激。"},{"en":"This phrase sounds respectful because it asks rather than demands.","zh":"這個短語聽起來尊重，因為它是請求而不是命令。"},{"en":"It is useful in formal letters to teachers, principals, or organisations.","zh":"它適用於寫給老師、校長或機構的正式信件。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"consider our views","meaning":"考慮我們的意見","examples":[{"en":"The writer asks Ms Chan to consider the students’ views.","zh":"作者請陳老師考慮學生的意見。"},{"en":"To consider our views means to think carefully about our opinions before making a decision.","zh":"consider our views 的意思是在作決定前仔細思考我們的看法。"},{"en":"A principal considers students’ views when she reads their feedback before changing rules.","zh":"校長在改變規則前閱讀學生意見，就是考慮學生的意見。"},{"en":"Asking someone to consider our views is polite because it does not demand immediate agreement.","zh":"請別人考慮我們的意見是禮貌的，因為它沒有要求立即同意。"},{"en":"This phrase shows respect for both the decision-maker and the students.","zh":"這個短語同時尊重決策者和學生。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"Yours sincerely is used to close this formal letter.","zh":"Yours sincerely 用來結束這封正式信件。"},{"en":"Yours sincerely is a polite closing used when writing a formal letter to someone whose name is known.","zh":"Yours sincerely 是在寫給已知姓名收信人的正式信件中使用的禮貌結尾語。"},{"en":"A student may end a letter to Ms Chan with “Yours sincerely”.","zh":"學生寫信給陳老師時，可以用 Yours sincerely 作結。"},{"en":"This closing makes the letter sound respectful and complete.","zh":"這個結尾令信件聽起來尊重而完整。"},{"en":"It is suitable for formal letters, not casual messages to friends.","zh":"它適合正式信件，不適合給朋友的隨意訊息。"}],"source":"2015 Q2.pdf","sourcePage":12},{"front":"Chairperson, Class Association","meaning":"班會主席","examples":[{"en":"Chris Wong signs as Chairperson of the Class Association.","zh":"Chris Wong 以班會主席身份署名。"},{"en":"Chairperson, Class Association is a title showing that the writer represents the student class body.","zh":"Chairperson, Class Association 是顯示作者代表班級學生組織的職銜。"},{"en":"A student may sign with this title after writing a proposal on behalf of classmates.","zh":"學生代表同學寫建議書後，可以用這個職銜署名。"},{"en":"The title gives the letter more authority because it shows a representative role.","zh":"這個職銜令信件更有代表性，因為它顯示作者有代表角色。"},{"en":"This phrase belongs in the signature line of a formal school letter.","zh":"這個短語屬於正式校園信件的署名位置。"}],"source":"2015 Q2.pdf","sourcePage":12}],"dse/writing/part-b/2015/Q3":[{"front":"the first line","meaning":"第一行；第一句","examples":[{"en":"Mrs Lam and Jason will start with the first line.","zh":"Lam 太太和 Jason 會從第一句開始。"},{"en":"The first line is the opening sentence or first spoken line of a text, song, or script.","zh":"the first line 指文章、歌曲或劇本的開頭一句或第一行。"},{"en":"A student may feel nervous before reading the first line of a speech.","zh":"學生在朗讀演講的第一句前可能會緊張。"},{"en":"If the first line is strong, it can catch the audience’s attention quickly.","zh":"如果第一句有力，它可以很快吸引觀眾注意。"},{"en":"In the story, starting with the first line suggests a new beginning for Mrs Lam.","zh":"在故事中，從第一句開始暗示 Lam 太太的新開始。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"every afternoon","meaning":"每天下午","examples":[{"en":"Every afternoon, Mrs Lam sat beside the window.","zh":"每天下午，Lam 太太都坐在窗邊。"},{"en":"Every afternoon means each day during the afternoon period.","zh":"every afternoon 指每一天的下午時段。"},{"en":"Every afternoon, students gather in the library to finish homework.","zh":"每天下午，學生都聚在圖書館完成功課。"},{"en":"Doing something every afternoon can show routine, habit, or loneliness.","zh":"每天下午做同一件事，可以顯示日常習慣或孤單。"},{"en":"In the story, the phrase shows Mrs Lam’s quiet daily pattern.","zh":"在故事中，這個短語顯示 Lam 太太安靜的日常模式。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"while the city hurried past","meaning":"當城市匆匆流過時","examples":[{"en":"Mrs Lam sat quietly while the city hurried past.","zh":"當城市匆匆流過時，Lam 太太安靜地坐着。"},{"en":"While the city hurried past means while the busy life outside continued quickly.","zh":"while the city hurried past 指外面忙碌的生活快速繼續。"},{"en":"An old man watched buses and shoppers move past while the city hurried past.","zh":"當城市匆匆流過時，老人看着巴士和購物的人經過。"},{"en":"This phrase contrasts one quiet person with a fast-moving world.","zh":"這個短語把一個安靜的人與快速移動的世界形成對比。"},{"en":"In the story, it shows Mrs Lam feeling still while life around her keeps moving.","zh":"在故事中，它顯示 Lam 太太靜止不動，而身邊生活仍在前進。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"sat beside the window","meaning":"坐在窗邊","examples":[{"en":"Mrs Lam sat beside the window of the elderly centre.","zh":"Lam 太太坐在長者中心的窗邊。"},{"en":"Sat beside the window means sat next to the window.","zh":"sat beside the window 指坐在窗戶旁邊。"},{"en":"A student sat beside the window to get more light while reading.","zh":"學生坐在窗邊閱讀，以得到更多光線。"},{"en":"Someone who sits beside the window can watch the world outside without joining it.","zh":"坐在窗邊的人可以看着外面的世界，而不一定參與其中。"},{"en":"In the story, this position makes Mrs Lam seem quiet and observant.","zh":"在故事中，這個位置令 Lam 太太顯得安靜而善於觀察。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"Sham Shui Po Elderly Centre","meaning":"深水埗長者中心","examples":[{"en":"Mrs Lam sat inside the Sham Shui Po Elderly Centre.","zh":"Lam 太太坐在深水埗長者中心裏。"},{"en":"Sham Shui Po Elderly Centre is a centre where older people in Sham Shui Po can meet, rest, and join activities.","zh":"Sham Shui Po Elderly Centre 是讓深水埗長者見面、休息和參加活動的中心。"},{"en":"The Sham Shui Po Elderly Centre may offer classes, meals, health talks, and social events.","zh":"深水埗長者中心可能提供課程、膳食、健康講座和社交活動。"},{"en":"An elderly centre can help older people feel less isolated.","zh":"長者中心可以幫助長者減少孤立感。"},{"en":"In the story, the centre becomes the place where Mrs Lam’s old dream returns.","zh":"在故事中，中心成為 Lam 太太舊夢重現的地方。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"stitched costumes","meaning":"縫製戲服","examples":[{"en":"Mrs Lam stitched costumes for other people’s dreams.","zh":"Lam 太太為別人的夢想縫製戲服。"},{"en":"Stitched costumes means sewed performance clothes carefully by hand or machine.","zh":"stitched costumes 指用手或機器仔細縫製表演服裝。"},{"en":"A seamstress stitched costumes for the school musical before opening night.","zh":"女裁縫在首演前為學校音樂劇縫製戲服。"},{"en":"Stitching costumes takes patience because every button, sleeve, and seam matters.","zh":"縫製戲服需要耐性，因為每粒鈕扣、衣袖和縫線都重要。"},{"en":"In the story, Mrs Lam makes costumes for performers while hiding her own dream.","zh":"在故事中，Lam 太太為表演者做戲服，卻隱藏自己的夢想。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"other people’s dreams","meaning":"別人的夢想","examples":[{"en":"She stitched costumes for other people’s dreams.","zh":"她為別人的夢想縫製戲服。"},{"en":"Other people’s dreams means the hopes, ambitions, or performances belonging to others.","zh":"other people’s dreams 指屬於其他人的希望、抱負或表演。"},{"en":"A teacher may help with other people’s dreams by training students for competitions.","zh":"老師訓練學生參賽，就是在幫助別人的夢想。"},{"en":"Working for other people’s dreams can feel meaningful, but also painful if your own dream is buried.","zh":"為別人的夢想工作可以有意義，但如果自己的夢被埋藏，也會令人痛苦。"},{"en":"This phrase shows Mrs Lam supporting others while neglecting herself.","zh":"這個短語顯示 Lam 太太支持別人，卻忽略自己。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"at seventy-six","meaning":"七十六歲時","examples":[{"en":"At seventy-six, Mrs Lam still had steady hands.","zh":"七十六歲時，Lam 太太仍有穩定的雙手。"},{"en":"At seventy-six means when she was seventy-six years old.","zh":"at seventy-six 指她七十六歲的時候。"},{"en":"At seventy-six, my grandfather still walked to the market every morning.","zh":"七十六歲時，我的祖父仍每天早上走路去街市。"},{"en":"This phrase often shows what someone can still do at an old age.","zh":"這個短語常顯示某人在年老時仍能做到甚麼。"},{"en":"In the story, it reminds readers that Mrs Lam is old but still skilled.","zh":"在故事中，它提醒讀者 Lam 太太年紀已大，但仍有技巧。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"steady hands","meaning":"穩定的雙手","examples":[{"en":"She had the steady hands of a seamstress.","zh":"她有女裁縫般穩定的雙手。"},{"en":"Steady hands are hands that move carefully and do not shake.","zh":"steady hands 指動作仔細、不會顫抖的雙手。"},{"en":"A nurse needs steady hands when giving an injection.","zh":"護士打針時需要穩定的雙手。"},{"en":"Steady hands help a seamstress sew tiny stitches neatly.","zh":"穩定的雙手幫助縫紉師整齊地縫出細小針腳。"},{"en":"In the story, Mrs Lam’s steady hands show years of skill and patience.","zh":"在故事中，Lam 太太穩定的雙手顯示多年技巧和耐性。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"seamstress","meaning":"女裁縫；縫紉師","examples":[{"en":"Mrs Lam had worked like a skilled seamstress for many years.","zh":"Lam 太太多年來像熟練女裁縫一樣工作。"},{"en":"A seamstress is a woman who sews clothes professionally or skillfully.","zh":"seamstress 指專業或熟練地縫製衣服的女性。"},{"en":"A seamstress can repair torn sleeves, shorten trousers, and make costumes.","zh":"女裁縫可以修補破袖、改短褲子和製作戲服。"},{"en":"A good seamstress needs patience, careful eyes, and steady hands.","zh":"好的縫紉師需要耐性、仔細眼睛和穩定的雙手。"},{"en":"In the story, Mrs Lam’s work as a seamstress connects her to the stage, but not yet to singing.","zh":"在故事中，Lam 太太作為縫紉師的工作把她與舞台連在一起，但還未連到歌唱。"}],"source":"2015 Q3.pdf","sourcePage":1},{"front":"quiet eyes","meaning":"沉靜的眼神","examples":[{"en":"She had the quiet eyes of someone who had spent a lifetime being useful.","zh":"她有一雙沉靜的眼神，像是一生都在做個有用的人。"},{"en":"Quiet eyes are eyes that seem calm, gentle, and full of unspoken experience.","zh":"quiet eyes 指看起來平靜、溫和，並充滿未說出口經歷的眼神。"},{"en":"The old teacher had quiet eyes that noticed every nervous student.","zh":"那位老教師有沉靜的眼神，能注意到每個緊張的學生。"},{"en":"Quiet eyes may suggest a person has seen much but does not complain.","zh":"沉靜的眼神可能暗示一個人經歷很多，卻不抱怨。"},{"en":"In the story, Mrs Lam’s quiet eyes hint at a life of service and hidden sadness.","zh":"在故事中，Lam 太太的沉靜眼神暗示她一生服務別人，也藏着傷感。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"spent a lifetime being useful","meaning":"一生都在做個有用的人","examples":[{"en":"Mrs Lam had spent a lifetime being useful.","zh":"Lam 太太一生都在做個有用的人。"},{"en":"Spent a lifetime being useful means used one’s whole life helping others and doing practical work.","zh":"spent a lifetime being useful 指用一生幫助別人和做實際工作。"},{"en":"A mother may spend a lifetime being useful to her family without asking for thanks.","zh":"母親可能一生都在對家庭有用，卻不要求感謝。"},{"en":"Being useful can be honourable, but it may also hide personal dreams.","zh":"做個有用的人可以很可敬，但也可能隱藏個人夢想。"},{"en":"This phrase shows that Mrs Lam has always served others before herself.","zh":"這個短語顯示 Lam 太太一直先服務別人，再想到自己。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"hidden in her biscuit tin","meaning":"藏在她的餅乾罐裏","examples":[{"en":"A faded photograph was hidden in her biscuit tin.","zh":"一張褪色照片藏在她的餅乾罐裏。"},{"en":"Hidden in her biscuit tin means kept secretly inside a small metal box originally used for biscuits.","zh":"hidden in her biscuit tin 指秘密收在原本裝餅乾的小金屬罐裏。"},{"en":"My grandmother kept old letters hidden in her biscuit tin.","zh":"我的祖母把舊信藏在她的餅乾罐裏。"},{"en":"Something hidden in a biscuit tin may be ordinary to others but precious to its owner.","zh":"藏在餅乾罐裏的東西，對別人可能普通，對物主卻很珍貴。"},{"en":"In the story, the photograph hidden there protects Mrs Lam’s forgotten dream.","zh":"在故事中，藏在那裏的照片保護着 Lam 太太被遺忘的夢。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"biscuit tin","meaning":"餅乾罐","examples":[{"en":"The photograph was hidden in a biscuit tin.","zh":"那張照片藏在餅乾罐裏。"},{"en":"A biscuit tin is a metal container once used to hold biscuits.","zh":"biscuit tin 指原本用來裝餅乾的金屬罐。"},{"en":"Many families keep buttons, needles, or old photos in a biscuit tin.","zh":"許多家庭會把鈕扣、針線或舊照片放在餅乾罐裏。"},{"en":"A biscuit tin can become a small box for memories after the biscuits are gone.","zh":"餅乾吃完後，餅乾罐可以變成收藏回憶的小盒子。"},{"en":"In the story, the biscuit tin holds Mrs Lam’s private past.","zh":"在故事中，餅乾罐保存了 Lam 太太私人的過去。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"faded photograph","meaning":"褪色照片","examples":[{"en":"Mrs Lam kept a faded photograph in her biscuit tin.","zh":"Lam 太太在餅乾罐裏保存了一張褪色照片。"},{"en":"A faded photograph is an old photo whose colours have become pale over time.","zh":"faded photograph 指顏色隨時間變淡的舊照片。"},{"en":"A faded photograph of a school trip may still bring back strong memories.","zh":"一張學校旅行的褪色照片仍可能喚起強烈回憶。"},{"en":"Faded photographs can show how long a memory has been kept.","zh":"褪色照片可以顯示一段回憶被保存了多久。"},{"en":"In the story, the faded photograph connects Mrs Lam to her younger self.","zh":"在故事中，褪色照片把 Lam 太太與年輕時的自己連在一起。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"embroidered sleeves","meaning":"繡花衣袖","examples":[{"en":"The girl in the photograph wore embroidered sleeves.","zh":"照片中的女孩穿着繡花衣袖。"},{"en":"Embroidered sleeves are sleeves decorated with stitched patterns or designs.","zh":"embroidered sleeves 指用針線圖案裝飾的衣袖。"},{"en":"A Cantonese opera costume may have embroidered sleeves with flowers and birds.","zh":"粵劇戲服可能有繡着花鳥的繡花衣袖。"},{"en":"Embroidered sleeves can make a performer look elegant and traditional.","zh":"繡花衣袖可以令表演者看起來優雅而傳統。"},{"en":"In the story, the sleeves suggest Mrs Lam once belonged close to the world of opera.","zh":"在故事中，衣袖暗示 Lam 太太曾經接近粵劇世界。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"Cantonese opera studio","meaning":"粵劇戲棚；粵劇訓練室","examples":[{"en":"The girl stood outside a Cantonese opera studio.","zh":"那個女孩站在粵劇訓練室外。"},{"en":"A Cantonese opera studio is a place where people learn, rehearse, or perform Cantonese opera.","zh":"Cantonese opera studio 是人們學習、排練或表演粵劇的地方。"},{"en":"Students may practise singing, movement, and gestures in a Cantonese opera studio.","zh":"學生可能在粵劇訓練室練習唱腔、身段和手勢。"},{"en":"A Cantonese opera studio connects music, costume, acting, and tradition.","zh":"粵劇訓練室連繫音樂、戲服、演技和傳統。"},{"en":"In the story, it represents the dream Mrs Lam once had.","zh":"在故事中，它代表 Lam 太太曾經擁有的夢想。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"had once wanted to","meaning":"曾經想要","examples":[{"en":"That girl had once wanted to sing.","zh":"那個女孩曾經想要唱歌。"},{"en":"Had once wanted to means wanted something in the past, though the wish may have been lost or delayed.","zh":"had once wanted to 指過去曾經想做某事，即使願望後來失去或延遲。"},{"en":"My father had once wanted to be a painter before he became a clerk.","zh":"我父親成為文員前，曾經想要當畫家。"},{"en":"Mrs Lam had once wanted to sing, but family duties changed her life.","zh":"Lam 太太曾經想要唱歌，但家庭責任改變了她的人生。"},{"en":"This phrase carries regret because it points to an old dream.","zh":"這個短語帶有遺憾，因為它指向一個舊夢。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"Por Por","meaning":"婆婆","examples":[{"en":"Jason called Mrs Lam “Por Por.”","zh":"Jason 稱 Lam 太太為「婆婆」。"},{"en":"Por Por is a Cantonese term meaning grandmother or an elderly woman addressed warmly.","zh":"Por Por 是粵語稱呼，意思是祖母或親切稱呼年長女性。"},{"en":"A child may call her grandmother “Por Por” in a Cantonese-speaking family.","zh":"在粵語家庭中，孩子可能稱祖母為「婆婆」。"},{"en":"Calling Mrs Lam “Por Por” makes Jason sound friendly and respectful.","zh":"稱 Lam 太太為「婆婆」令 Jason 聽起來親切又尊重。"},{"en":"In the story, this name helps build a gentle bond between them.","zh":"在故事中，這個稱呼幫助建立他們之間溫柔的連繫。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"opera star","meaning":"粵劇明星","examples":[{"en":"Jason asked if Mrs Lam had really wanted to be an opera star.","zh":"Jason 問 Lam 太太是否真的曾想成為粵劇明星。"},{"en":"An opera star is a famous performer who sings and acts in opera.","zh":"opera star 指在戲曲或歌劇中唱歌和演戲的著名表演者。"},{"en":"A Cantonese opera star needs a strong voice, stage presence, and years of training.","zh":"粵劇明星需要有力聲音、舞台魅力和多年訓練。"},{"en":"Wanting to be an opera star shows Mrs Lam once had a public artistic dream.","zh":"想成為粵劇明星顯示 Lam 太太曾有公開的藝術夢想。"},{"en":"This phrase contrasts her hidden wish with her quiet present life.","zh":"這個短語把她隱藏的願望與現在安靜的生活形成對比。"}],"source":"2015 Q3.pdf","sourcePage":2},{"front":"Form Four student","meaning":"中四學生","examples":[{"en":"Jason was a Form Four student from the drama club.","zh":"Jason 是戲劇學會的一名中四學生。"},{"en":"A Form Four student is a student in the fourth year of secondary school in Hong Kong.","zh":"Form Four student 指香港中學四年級的學生。"},{"en":"A Form Four student may be preparing for senior secondary subjects and activities.","zh":"中四學生可能正在準備高中科目和活動。"},{"en":"Jason being a Form Four student shows he is young but old enough to notice Mrs Lam’s talent.","zh":"Jason 是中四學生，顯示他年輕，但已足以留意 Lam 太太的才華。"},{"en":"This phrase places Jason clearly in a school setting.","zh":"這個短語清楚把 Jason 放在校園背景中。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"school drama club","meaning":"學校戲劇學會","examples":[{"en":"Jason came from the school drama club.","zh":"Jason 來自學校戲劇學會。"},{"en":"A school drama club is a student group that practises acting and prepares performances.","zh":"school drama club 是練習演戲和準備表演的學生團體。"},{"en":"Members of a school drama club may rehearse after lessons for a play.","zh":"學校戲劇學會成員可能放學後為話劇排練。"},{"en":"A drama club needs scripts, props, costumes, and teamwork.","zh":"戲劇學會需要劇本、道具、戲服和團隊合作。"},{"en":"In the story, the drama club brings students into the elderly centre.","zh":"在故事中，戲劇學會把學生帶進長者中心。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"looking for buttons","meaning":"尋找鈕扣時","examples":[{"en":"Jason found the photo while looking for buttons.","zh":"Jason 在尋找鈕扣時發現了照片。"},{"en":"Looking for buttons means searching for small fasteners used on clothes.","zh":"looking for buttons 指尋找用在衣服上的小扣子。"},{"en":"The costume team was looking for buttons to repair an old jacket.","zh":"戲服組在尋找鈕扣，以修補一件舊外套。"},{"en":"Looking for buttons seems ordinary, but it leads Jason to Mrs Lam’s secret photo.","zh":"尋找鈕扣看似普通，卻令 Jason 發現 Lam 太太秘密的照片。"},{"en":"This phrase shows how a small task can uncover a hidden story.","zh":"這個短語顯示小任務如何揭開隱藏故事。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"snatched it back","meaning":"一把搶回來","examples":[{"en":"Mrs Lam snatched the photograph back.","zh":"Lam 太太一把搶回那張照片。"},{"en":"Snatched it back means took something back quickly and forcefully.","zh":"snatched it back 指快速而用力地把某物拿回來。"},{"en":"The child snatched his diary back when his sister opened it.","zh":"妹妹打開日記時，孩子一把搶回來。"},{"en":"Mrs Lam snatches the photo back because it protects a painful private memory.","zh":"Lam 太太一把搶回照片，因為它保存着痛苦的私人回憶。"},{"en":"This phrase shows sudden fear, shame, or protectiveness.","zh":"這個短語顯示突然的恐懼、羞愧或保護心。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"another life","meaning":"另一段人生","examples":[{"en":"Mrs Lam said the photograph belonged to another life.","zh":"Lam 太太說那張照片屬於另一段人生。"},{"en":"Another life means a past period that feels almost separate from who someone is now.","zh":"another life 指一段過去時期，感覺幾乎與現在的自己分開。"},{"en":"My teacher said her days as a singer belonged to another life.","zh":"我的老師說她當歌手的日子屬於另一段人生。"},{"en":"Mrs Lam calls her old dream another life because it feels far away and unreachable.","zh":"Lam 太太把舊夢稱為另一段人生，因為它感覺遙遠而不可及。"},{"en":"This phrase shows distance between past hopes and present reality.","zh":"這個短語顯示過去希望與現在現實之間的距離。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"unfinished","meaning":"未完成的","examples":[{"en":"Jason thought that old dream was unfinished.","zh":"Jason 覺得那個舊夢仍是未完成的。"},{"en":"Unfinished means not completed or not brought to an end.","zh":"unfinished 指尚未完成或尚未結束。"},{"en":"An unfinished painting may still wait in the corner of a room.","zh":"一幅未完成的畫可能仍放在房間角落等待。"},{"en":"An old dream can feel unfinished if the person never had a real chance to try.","zh":"如果一個人從未真正有機會嘗試，舊夢可能感覺未完成。"},{"en":"In the story, Jason sees Mrs Lam’s singing dream as still alive.","zh":"在故事中，Jason 覺得 Lam 太太的歌唱夢仍然活着。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"in her experience","meaning":"以她的經驗來說","examples":[{"en":"In her experience, dreams belonged to luckier people.","zh":"以她的經驗來說，夢想屬於較幸運的人。"},{"en":"In her experience means based on what she has lived through and learned.","zh":"in her experience 指根據她親身經歷和學到的事。"},{"en":"In my experience, good friendships need patience and honesty.","zh":"以我的經驗來說，好的友誼需要耐性和誠實。"},{"en":"In Mrs Lam’s experience, duties came before dreams.","zh":"以 Lam 太太的經驗來說，責任先於夢想。"},{"en":"This phrase shows a personal belief shaped by life.","zh":"這個短語顯示由人生塑造的個人信念。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"belonged to luckier people","meaning":"屬於較幸運的人","examples":[{"en":"Dreams, in her experience, belonged to luckier people.","zh":"以她的經驗來說，夢想屬於較幸運的人。"},{"en":"Belonged to luckier people means seemed available only to people with better chances or fewer burdens.","zh":"belonged to luckier people 指某事似乎只屬於機會較好或負擔較少的人。"},{"en":"University once seemed to belong to luckier people for students who had to work early.","zh":"對早早要工作的學生來說，大學曾像是屬於較幸運的人。"},{"en":"Mrs Lam believes dreams belonged to luckier people because family duties blocked her path.","zh":"Lam 太太相信夢想屬於較幸運的人，因為家庭責任阻擋了她的路。"},{"en":"This phrase shows resignation and quiet sadness.","zh":"這個短語顯示認命和安靜的悲傷。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"fallen ill","meaning":"病倒","examples":[{"en":"Her father had fallen ill.","zh":"她的父親病倒了。"},{"en":"Fallen ill means become sick.","zh":"fallen ill 指生病或病倒。"},{"en":"The teacher fell ill before the school trip and had to rest at home.","zh":"老師在學校旅行前病倒，只能在家休息。"},{"en":"When a parent falls ill, children may need to take on more responsibility.","zh":"當父母病倒，孩子可能需要承擔更多責任。"},{"en":"In the story, her father’s illness begins the chain of duties that delays her dream.","zh":"在故事中，父親病倒開始了一連串令她夢想延遲的責任。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"school fees","meaning":"學費","examples":[{"en":"Her brothers needed school fees.","zh":"她的弟弟們需要學費。"},{"en":"School fees are money paid for education or school expenses.","zh":"school fees 指為教育或學校開支支付的金錢。"},{"en":"Some families save for months to pay school fees.","zh":"有些家庭儲蓄數月來支付學費。"},{"en":"If brothers need school fees, an older sister may work instead of studying.","zh":"如果弟弟們需要學費，姐姐可能要工作而不是讀書。"},{"en":"In Mrs Lam’s life, school fees represent family duty over personal dreams.","zh":"在 Lam 太太的人生中，學費代表家庭責任壓過個人夢想。"}],"source":"2015 Q3.pdf","sourcePage":3},{"front":"later came","meaning":"後來接踵而來的是","examples":[{"en":"Later came marriage, children and bills.","zh":"後來接踵而來的是婚姻、子女和帳單。"},{"en":"Later came means these things arrived or happened afterwards.","zh":"later came 指這些事情在之後到來或發生。"},{"en":"First came schoolwork; later came exams, interviews and decisions.","zh":"起初是功課；後來接踵而來的是考試、面試和決定。"},{"en":"Later came new duties that made Mrs Lam’s dream feel even further away.","zh":"後來接踵而來的新責任，令 Lam 太太的夢想感覺更遙遠。"},{"en":"This phrase can make life events feel like a procession.","zh":"這個短語可以令人感到人生事件一件接一件而來。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"marriage, children and bills","meaning":"婚姻、子女和帳單","examples":[{"en":"Marriage, children and bills came later in her life.","zh":"婚姻、子女和帳單後來出現在她的人生裏。"},{"en":"Marriage, children and bills means family life, parenting duties and financial responsibilities.","zh":"marriage, children and bills 指家庭生活、養育責任和財務負擔。"},{"en":"Many adults balance marriage, children and bills with work every day.","zh":"許多成年人每天在工作中平衡婚姻、子女和帳單。"},{"en":"For Mrs Lam, marriage, children and bills left little room for singing.","zh":"對 Lam 太太來說，婚姻、子女和帳單令歌唱夢幾乎沒有空間。"},{"en":"This phrase shows ordinary responsibilities that can quietly replace dreams.","zh":"這個短語顯示平凡責任如何安靜地取代夢想。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time she was free, her knees hurt.","zh":"到她終於自由的時候，她的膝蓋已經疼痛。"},{"en":"By the time means when a later moment arrived, something had already changed.","zh":"by the time 指到某個較後時刻時，某事已經改變。"},{"en":"By the time the rain stopped, the streets were already flooded.","zh":"到雨停的時候，街道已經水浸。"},{"en":"By the time Mrs Lam had time for herself, her body had grown older.","zh":"到 Lam 太太有時間留給自己時，她的身體已經老了。"},{"en":"This phrase shows the sadness of a chance arriving late.","zh":"這個短語顯示機會來得太遲的傷感。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"her knees hurt","meaning":"她的膝蓋疼痛","examples":[{"en":"By the time Mrs Lam was free, her knees hurt.","zh":"到 Lam 太太終於自由時，她的膝蓋已經疼痛。"},{"en":"Her knees hurt means she felt pain in her knee joints.","zh":"her knees hurt 指她的膝關節感到疼痛。"},{"en":"After climbing many stairs, my grandmother said her knees hurt.","zh":"爬了很多樓梯後，我的祖母說她的膝蓋疼痛。"},{"en":"Knee pain can make dancing, walking, or standing for long periods difficult.","zh":"膝蓋疼痛會令跳舞、走路或久站變得困難。"},{"en":"In the story, her knees hurting shows how time has changed her body.","zh":"在故事中，她的膝蓋疼痛顯示時間如何改變她的身體。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"her voice shook","meaning":"她的聲音顫抖","examples":[{"en":"Her voice shook when she was finally free to dream again.","zh":"當她終於可以再次做夢時，她的聲音顫抖。"},{"en":"Her voice shook means her voice trembled because of age, fear, emotion or weakness.","zh":"her voice shook 指她的聲音因年紀、恐懼、情緒或虛弱而顫動。"},{"en":"The student’s voice shook when she spoke in front of the hall.","zh":"學生在禮堂前發言時聲音顫抖。"},{"en":"Mrs Lam’s voice shakes because the dream still matters to her.","zh":"Lam 太太的聲音顫抖，因為那個夢對她仍然重要。"},{"en":"This phrase shows emotion that the body cannot hide.","zh":"這個短語顯示身體無法隱藏的情感。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"too loud for old wishes","meaning":"對昔日願望來說太嘈雜","examples":[{"en":"The world seemed too loud for old wishes.","zh":"這個世界對昔日願望來說似乎太嘈雜。"},{"en":"Too loud for old wishes means life felt too busy, noisy, or harsh for quiet dreams from the past.","zh":"too loud for old wishes 指生活太忙、太吵或太 harsh，容不下過去安靜的夢。"},{"en":"A retired man may feel the modern city is too loud for old wishes.","zh":"退休老人可能覺得現代城市對昔日願望來說太嘈雜。"},{"en":"Mrs Lam thinks her dream cannot survive in a world that has moved on without her.","zh":"Lam 太太覺得世界已經不等她，她的夢無法存活。"},{"en":"This phrase shows how age and change can make dreams feel fragile.","zh":"這個短語顯示年齡和變化如何令夢想變得脆弱。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"still","meaning":"儘管如此","examples":[{"en":"Still, the students rehearsed at the centre every Wednesday.","zh":"儘管如此，學生們每逢星期三仍在中心排練。"},{"en":"Still means despite what was just said, something continued or remained true.","zh":"still 指儘管剛才提到那些情況，某事仍然繼續或仍然真實。"},{"en":"The work was tiring; still, the team returned the next day.","zh":"工作很疲累；儘管如此，隊伍第二天仍回來。"},{"en":"Mrs Lam thought dreams were too late; still, the students kept rehearsing nearby.","zh":"Lam 太太以為夢想太遲；儘管如此，學生們仍在附近排練。"},{"en":"This word introduces hope after difficulty.","zh":"這個詞在困難後引入希望。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"rehearsed at the centre","meaning":"在中心排練","examples":[{"en":"The students rehearsed at the elderly centre every Wednesday.","zh":"學生們每逢星期三在長者中心排練。"},{"en":"Rehearsed at the centre means practised a performance in that centre.","zh":"rehearsed at the centre 指在該中心練習表演。"},{"en":"The drama club rehearsed at the community centre because the school hall was full.","zh":"因為學校禮堂已滿，戲劇學會在社區中心排練。"},{"en":"Rehearsing at the centre brings young students into contact with older residents.","zh":"在中心排練讓年輕學生接觸長者居民。"},{"en":"In the story, the rehearsals slowly pull Mrs Lam toward the stage.","zh":"在故事中，排練慢慢把 Lam 太太拉向舞台。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"the elderly","meaning":"長者","examples":[{"en":"The play was about the elderly realising their dreams.","zh":"那齣劇是關於長者實現夢想。"},{"en":"The elderly means older people, especially as a group in society.","zh":"the elderly 指年長人士，特別是作為社會群體。"},{"en":"Community centres often organise activities for the elderly.","zh":"社區中心常為長者舉辦活動。"},{"en":"The elderly may still have dreams, talents and stories that younger people do not see.","zh":"長者可能仍有年輕人看不見的夢想、才華和故事。"},{"en":"In the play, the elderly are not treated as finished people, but as people with hopes.","zh":"在劇中，長者不是被視為人生已完結的人，而是仍有希望的人。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"realising their dreams","meaning":"實現夢想","examples":[{"en":"The students’ play was about the elderly realising their dreams.","zh":"學生的劇本是關於長者實現夢想。"},{"en":"Realising their dreams means making their hopes become real.","zh":"realising their dreams 指令他們的希望成為現實。"},{"en":"A woman may realise her dream by opening a small bakery after retirement.","zh":"一位女士可能在退休後開小麵包店，實現夢想。"},{"en":"Realising dreams can require courage, help and a second chance.","zh":"實現夢想可能需要勇氣、幫助和第二次機會。"},{"en":"In the story, this idea slowly becomes true for Mrs Lam herself.","zh":"在故事中，這個想法慢慢在 Lam 太太身上成真。"}],"source":"2015 Q3.pdf","sourcePage":4},{"front":"though none of them knew","meaning":"雖然他們沒有一個知道","examples":[{"en":"None of the students knew how an old woman carried disappointment.","zh":"他們沒有一個知道一位老婦人如何承受失望。"},{"en":"Though none of them knew means although no one in the group understood the hidden truth.","zh":"though none of them knew 指雖然那群人沒有一個理解隱藏的真相。"},{"en":"The class wrote about poverty, though none of them knew how hunger felt.","zh":"全班寫關於貧窮，雖然他們沒有一個知道飢餓的感覺。"},{"en":"The students act out elderly dreams, though none of them know Mrs Lam’s private loss.","zh":"學生演長者夢想，雖然他們沒有一個知道 Lam 太太私人的失落。"},{"en":"This phrase shows a gap between performance and real experience.","zh":"這個短語顯示表演與真實經驗之間的距離。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"carry disappointment","meaning":"承受失望","examples":[{"en":"An old woman might carry disappointment without showing it.","zh":"一位老婦人可能沒有表露出來地承受失望。"},{"en":"Carry disappointment means live with sadness or regret quietly for a long time.","zh":"carry disappointment 指長時間安靜地帶着悲傷或遺憾生活。"},{"en":"A father may carry disappointment when he gives up study to support his family.","zh":"父親為供養家庭而放棄學業時，可能承受失望。"},{"en":"Mrs Lam carries disappointment because her singing dream was delayed for decades.","zh":"Lam 太太承受失望，因為她的歌唱夢被延遲了數十年。"},{"en":"This phrase makes disappointment feel like a heavy object held inside.","zh":"這個短語令失望感覺像藏在心裏的重物。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"without showing it","meaning":"沒有表露出來","examples":[{"en":"Mrs Lam carried disappointment without showing it.","zh":"Lam 太太承受失望，卻沒有表露出來。"},{"en":"Without showing it means not letting other people see the feeling or problem.","zh":"without showing it 指不讓別人看見那種感受或問題。"},{"en":"A student may feel worried before an exam without showing it.","zh":"學生考試前可能很擔心，卻沒有表露出來。"},{"en":"Mrs Lam hides disappointment behind quiet work and useful hands.","zh":"Lam 太太把失望藏在安靜工作和有用的雙手後面。"},{"en":"This phrase shows hidden emotion beneath ordinary behaviour.","zh":"這個短語顯示普通行為下隱藏的情感。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"helped with props","meaning":"幫忙處理道具","examples":[{"en":"Mrs Lam helped with props for the play.","zh":"Lam 太太幫忙處理那齣劇的道具。"},{"en":"Helped with props means assisted in preparing objects used on stage.","zh":"helped with props 指協助準備舞台上使用的物件。"},{"en":"The art teacher helped with props by painting a cardboard door.","zh":"美術老師幫忙處理道具，為紙板門上色。"},{"en":"Helping with props lets Mrs Lam support the play without performing at first.","zh":"幫忙處理道具讓 Lam 太太起初不用表演也能支持那齣劇。"},{"en":"This phrase shows her staying close to the stage from the side.","zh":"這個短語顯示她從旁邊接近舞台。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"props","meaning":"道具","examples":[{"en":"The students needed props for their performance.","zh":"學生們的表演需要道具。"},{"en":"Props are objects used by actors or performers on stage.","zh":"props 指演員或表演者在舞台上使用的物件。"},{"en":"A cup, letter, fan, or chair can be a prop in a play.","zh":"杯、信、扇或椅子都可以是戲劇道具。"},{"en":"Good props help the audience believe the world of the story.","zh":"好的道具幫助觀眾相信故事世界。"},{"en":"In the story, props give Mrs Lam a practical way to join the students’ work.","zh":"在故事中，道具給 Lam 太太一個實際方法參與學生的工作。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"corrected a line","meaning":"修改一句台詞","examples":[{"en":"Mrs Lam corrected a line in the students’ play.","zh":"Lam 太太修改了學生劇本中的一句台詞。"},{"en":"Corrected a line means changed a sentence in a script to make it better or more accurate.","zh":"corrected a line 指修改劇本中的一句話，使它更好或更準確。"},{"en":"The teacher corrected a line because the character would not speak that way.","zh":"老師修改了一句台詞，因為角色不會那樣說話。"},{"en":"Mrs Lam corrects a line because she understands the feeling better than the students.","zh":"Lam 太太修改台詞，因為她比學生更理解那種感受。"},{"en":"This phrase shows her quiet authority and experience.","zh":"這個短語顯示她安靜的權威和經驗。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"pride and regret","meaning":"驕傲與遺憾","examples":[{"en":"Mrs Lam taught Jason how pride and regret could live in the same smile.","zh":"Lam 太太教 Jason 明白驕傲與遺憾如何同時存在於同一個笑容中。"},{"en":"Pride and regret mean feeling pleased about something while also feeling sadness about what was lost.","zh":"pride and regret 指既為某事感到欣慰，又為失去的東西感到傷感。"},{"en":"A parent may feel pride and regret when a child leaves home for university.","zh":"孩子離家讀大學時，父母可能同時感到驕傲與遺憾。"},{"en":"Mrs Lam understands pride and regret because her useful life also cost her dream.","zh":"Lam 太太理解驕傲與遺憾，因為她有用的一生也犧牲了夢想。"},{"en":"This phrase shows that emotions can be mixed and complicated.","zh":"這個短語顯示情感可以混合而複雜。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"live in the same smile","meaning":"同時存在於同一個笑容中","examples":[{"en":"Pride and regret could live in the same smile.","zh":"驕傲與遺憾可以同時存在於同一個笑容中。"},{"en":"Live in the same smile means two different feelings can appear together in one expression.","zh":"live in the same smile 指兩種不同感受可以在同一個表情中一起出現。"},{"en":"Joy and sadness can live in the same smile at a graduation ceremony.","zh":"在畢業禮上，喜悅與傷感可以同時存在於同一個笑容中。"},{"en":"Mrs Lam’s smile can hold both satisfaction and old pain.","zh":"Lam 太太的笑容可以同時承載滿足和舊痛。"},{"en":"This phrase helps describe complicated human emotion simply.","zh":"這個短語用簡單方式描述複雜的人類情感。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"little by little","meaning":"一點一點地","examples":[{"en":"Little by little, the play began to take shape.","zh":"一點一點地，那齣劇開始成形。"},{"en":"Little by little means gradually, in small steps over time.","zh":"little by little 指隨時間逐步地、一小步一小步地。"},{"en":"Little by little, the shy student became more confident on stage.","zh":"一點一點地，那個害羞學生在舞台上變得更有信心。"},{"en":"A play takes shape little by little through rehearsals, corrections, and teamwork.","zh":"一齣劇透過排練、修改和團隊合作一點一點地成形。"},{"en":"This phrase shows slow but real progress.","zh":"這個短語顯示緩慢但真實的進步。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"take shape","meaning":"成形","examples":[{"en":"The play began to take shape.","zh":"那齣劇開始成形。"},{"en":"Take shape means start to become clear, organised, or complete.","zh":"take shape 指開始變得清楚、有組織或完整。"},{"en":"After several meetings, the class project began to take shape.","zh":"經過幾次會議後，班級項目開始成形。"},{"en":"A performance takes shape when actors know their lines and movements.","zh":"當演員熟悉台詞和動作，表演就開始成形。"},{"en":"In the story, the play taking shape also helps Mrs Lam’s dream take shape.","zh":"在故事中，劇本成形也幫助 Lam 太太的夢想成形。"}],"source":"2015 Q3.pdf","sourcePage":5},{"front":"rainy evening","meaning":"下雨的晚上","examples":[{"en":"One rainy evening, Mrs Lam sang while sewing.","zh":"一個下雨的晚上，Lam 太太一邊縫紉一邊唱歌。"},{"en":"A rainy evening is an evening when rain is falling.","zh":"rainy evening 指正在下雨的晚上。"},{"en":"On a rainy evening, the streets were quiet and the windows shone.","zh":"在一個下雨的晚上，街道很安靜，窗戶閃着光。"},{"en":"A rainy evening can create a soft, private mood for memory.","zh":"下雨的晚上可以營造柔和、私密的回憶氣氛。"},{"en":"In the story, the rainy evening becomes the moment when Mrs Lam’s hidden voice appears.","zh":"在故事中，那個下雨的晚上成為 Lam 太太隱藏聲音出現的時刻。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"phoenix robe","meaning":"鳳袍","examples":[{"en":"Mrs Lam was sewing a phoenix robe.","zh":"Lam 太太正在縫製一件鳳袍。"},{"en":"A phoenix robe is a dramatic costume decorated with a phoenix image, often linked to Chinese opera or ceremony.","zh":"phoenix robe 指飾有鳳凰圖案的戲服，常與中國戲曲或儀式有關。"},{"en":"A performer may wear a phoenix robe to show dignity, beauty, or royal status.","zh":"表演者可能穿鳳袍來顯示尊貴、美麗或皇室身份。"},{"en":"Sewing a phoenix robe requires careful work because the design is detailed.","zh":"縫製鳳袍需要細心，因為圖案很精細。"},{"en":"In the story, the phoenix robe suggests rebirth and Mrs Lam’s return to the stage.","zh":"在故事中，鳳袍暗示重生和 Lam 太太重返舞台。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"forgot herself","meaning":"忘我","examples":[{"en":"Mrs Lam forgot herself and sang a few lines.","zh":"Lam 太太忘我地唱了幾句。"},{"en":"Forgot herself means acted naturally without thinking about fear, rules, or self-control.","zh":"forgot herself 指不再想着恐懼、規矩或自我控制，而自然地行動。"},{"en":"The shy boy forgot himself and laughed loudly during the game.","zh":"那個害羞男孩在遊戲中忘我地大笑。"},{"en":"Mrs Lam forgets herself because the old song rises before she can stop it.","zh":"Lam 太太忘我，是因為舊歌在她能阻止前已湧上來。"},{"en":"This phrase shows a hidden part of someone appearing unexpectedly.","zh":"這個短語顯示一個人隱藏的一面突然出現。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"sang a few lines from","meaning":"唱了幾句……","examples":[{"en":"She sang a few lines from The Floral Princess.","zh":"她唱了幾句《帝女花》。"},{"en":"Sang a few lines from means performed a short part of a song, poem, or script.","zh":"sang a few lines from 指唱出歌曲、詩或劇本中的一小部分。"},{"en":"My grandmother sang a few lines from an old folk song.","zh":"我的祖母唱了幾句舊民歌。"},{"en":"Mrs Lam sings only a few lines, but they reveal years of memory.","zh":"Lam 太太只唱了幾句，卻揭示多年的回憶。"},{"en":"This phrase shows how a small piece of music can open a whole past.","zh":"這個短語顯示一小段音樂如何打開整個過去。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"The Floral Princess","meaning":"《帝女花》","examples":[{"en":"Mrs Lam sang a few lines from The Floral Princess.","zh":"Lam 太太唱了幾句《帝女花》。"},{"en":"The Floral Princess is the English title of the Cantonese opera Princess Changping.","zh":"The Floral Princess 是粵劇《帝女花》的英文名稱。"},{"en":"Many Cantonese opera lovers recognise songs from The Floral Princess.","zh":"許多粵劇愛好者都認得《帝女花》中的唱段。"},{"en":"Singing from The Floral Princess connects Mrs Lam to Cantonese opera tradition.","zh":"唱《帝女花》把 Lam 太太與粵劇傳統連在一起。"},{"en":"In the story, this title shows that her old dream is specific and deeply rooted.","zh":"在故事中，這個劇名顯示她的舊夢很具體，而且根深蒂固。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"fell silent","meaning":"安靜下來","examples":[{"en":"The room fell silent when Mrs Lam sang.","zh":"Lam 太太唱歌時，房間安靜下來。"},{"en":"Fell silent means became quiet suddenly.","zh":"fell silent 指突然變得安靜。"},{"en":"The classroom fell silent when the student began her speech.","zh":"學生開始演講時，課室安靜下來。"},{"en":"The room falls silent because Mrs Lam’s voice surprises everyone.","zh":"房間安靜下來，因為 Lam 太太的聲音令所有人驚訝。"},{"en":"This phrase shows that her singing has power.","zh":"這個短語顯示她的歌聲有力量。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"is our ending","meaning":"是我們的結尾","examples":[{"en":"Jason said Mrs Lam’s voice was their ending.","zh":"Jason 說 Lam 太太的聲音是他們的結尾。"},{"en":"Is our ending means it is the final part that completes the performance.","zh":"is our ending 指它是完成表演的最後部分。"},{"en":"The choir’s last song is our ending because it brings everyone together.","zh":"合唱團最後一首歌是我們的結尾，因為它把所有人連在一起。"},{"en":"Jason believes Mrs Lam’s voice can give the play emotional completion.","zh":"Jason 相信 Lam 太太的聲音可以給那齣劇情感上的完成。"},{"en":"This phrase shows that her hidden talent becomes central to the students’ work.","zh":"這個短語顯示她隱藏的才華成為學生作品的核心。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"I only sew","meaning":"我只負責縫製","examples":[{"en":"Mrs Lam insisted that she only sewed.","zh":"Lam 太太堅持說自己只負責縫製。"},{"en":"I only sew means I just make or repair clothes, not perform or take centre stage.","zh":"I only sew 指我只是製作或修補衣服，不是表演或站到台中央。"},{"en":"A costume maker may say, “I only sew,” because she sees herself as backstage help.","zh":"戲服師可能說「我只負責縫製」，因為她把自己視為幕後幫手。"},{"en":"Mrs Lam says she only sews to avoid admitting that she can sing.","zh":"Lam 太太說自己只負責縫製，是為了避免承認自己會唱。"},{"en":"This phrase shows how she limits herself.","zh":"這個短語顯示她如何限制自己。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"don’t just","meaning":"不只是","examples":[{"en":"Jason told Mrs Lam that she did not just sew.","zh":"Jason 告訴 Lam 太太，她不只是縫製。"},{"en":"Don’t just means do more than the simple action being mentioned.","zh":"don’t just 指做的不只是剛提到的簡單動作。"},{"en":"A good teacher does not just mark homework; she helps students understand mistakes.","zh":"好老師不只是批改功課；她幫助學生理解錯誤。"},{"en":"Mrs Lam does not just sew because she also understands stories, feelings, and songs.","zh":"Lam 太太不只是縫製，因為她也理解故事、情感和歌曲。"},{"en":"This phrase helps someone see their own value more fully.","zh":"這個短語幫助人更完整地看見自己的價值。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"for once in her life","meaning":"生平第一次","examples":[{"en":"For once in her life, Mrs Lam had no answer.","zh":"生平第一次，Lam 太太無言以對。"},{"en":"For once in her life means on this rare occasion, unlike most of her life.","zh":"for once in her life 指在這個罕見時刻，與她大半生不同。"},{"en":"For once in her life, the strict teacher laughed until she cried.","zh":"生平第一次，那位嚴肅老師笑到流淚。"},{"en":"Mrs Lam usually knows how to answer, but this time Jason’s words reach her.","zh":"Lam 太太通常知道如何回答，但這次 Jason 的話打動了她。"},{"en":"This phrase marks an unusual emotional moment.","zh":"這個短語標示一個不尋常的情感時刻。"}],"source":"2015 Q3.pdf","sourcePage":6},{"front":"had no answer","meaning":"無言以對","examples":[{"en":"Mrs Lam had no answer after Jason replied.","zh":"Jason 回答後，Lam 太太無言以對。"},{"en":"Had no answer means could not think of anything to say in response.","zh":"had no answer 指想不到任何話回應。"},{"en":"The student had no answer when the teacher asked why the homework was copied.","zh":"老師問學生為何抄功課時，學生無言以對。"},{"en":"Mrs Lam has no answer because Jason has named the truth she avoids.","zh":"Lam 太太無言以對，因為 Jason 說中了她一直避開的真相。"},{"en":"This phrase shows silence caused by being deeply affected.","zh":"這個短語顯示因被深深觸動而沉默。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"practice was hard","meaning":"練習很艱難","examples":[{"en":"Practice was hard for Mrs Lam.","zh":"對 Lam 太太來說，練習很艱難。"},{"en":"Practice was hard means rehearsing or training was difficult.","zh":"practice was hard 指排練或訓練很困難。"},{"en":"Practice was hard for the new actor because she had never stood on stage before.","zh":"對新演員來說，練習很艱難，因為她從未站過舞台。"},{"en":"Practice is hard for Mrs Lam because her body, memory, and confidence are tested.","zh":"對 Lam 太太來說，練習很艱難，因為她的身體、記憶和信心都被考驗。"},{"en":"This phrase shows that returning to a dream is not easy.","zh":"這個短語顯示重返夢想並不容易。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"missed cues","meaning":"錯過提示","examples":[{"en":"Mrs Lam missed cues during practice.","zh":"Lam 太太在練習中錯過提示。"},{"en":"Missed cues means failed to notice signals that show when to speak, sing, or move.","zh":"missed cues 指沒有留意到該說話、唱歌或移動的提示。"},{"en":"An actor missed cues when she entered before the music started.","zh":"演員在音樂開始前進場，就是錯過提示。"},{"en":"Missing cues can happen when a performer is nervous or unfamiliar with the script.","zh":"當表演者緊張或不熟悉劇本時，可能會錯過提示。"},{"en":"In the story, this shows Mrs Lam struggling to perform again.","zh":"在故事中，這顯示 Lam 太太重新表演時的掙扎。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"lost breath","meaning":"喘不過氣；氣息不足","examples":[{"en":"Mrs Lam lost breath while practising.","zh":"Lam 太太練習時氣息不足。"},{"en":"Lost breath means became unable to breathe steadily enough to continue.","zh":"lost breath 指無法穩定呼吸到足以繼續。"},{"en":"The runner lost breath after climbing the steep hill.","zh":"跑手爬上陡斜山路後喘不過氣。"},{"en":"A singer may lose breath if a phrase is long or nerves are strong.","zh":"如果一句唱詞很長或太緊張，歌手可能氣息不足。"},{"en":"This phrase shows the physical challenge of singing at her age.","zh":"這個短語顯示她這個年紀唱歌的身體挑戰。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"walked off","meaning":"離場；走開","examples":[{"en":"Mrs Lam once walked off because two boys were giggling.","zh":"Lam 太太有一次因為兩個男孩在笑而離場。"},{"en":"Walked off means left a place suddenly, often because of anger or hurt.","zh":"walked off 指突然離開某地，常因憤怒或受傷。"},{"en":"The actor walked off when people laughed during his speech.","zh":"演講時有人笑，那名演員便走開了。"},{"en":"Mrs Lam walks off because she feels judged and ashamed.","zh":"Lam 太太離場，因為她覺得被評價和羞辱。"},{"en":"This phrase shows a moment when fear nearly defeats her.","zh":"這個短語顯示恐懼幾乎打敗她的一刻。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"were giggling","meaning":"在咯咯地笑","examples":[{"en":"Two boys were giggling during practice.","zh":"兩個男孩在練習期間咯咯地笑。"},{"en":"Were giggling means were laughing quietly in a silly or nervous way.","zh":"were giggling 指以傻氣或緊張的方式小聲笑。"},{"en":"The children were giggling at the back of the classroom.","zh":"孩子們在課室後排咯咯地笑。"},{"en":"Giggling during someone’s practice can make the performer feel embarrassed.","zh":"在別人練習時咯咯地笑，可能令表演者尷尬。"},{"en":"In the story, the boys’ laughter touches Mrs Lam’s deepest insecurity.","zh":"在故事中，男孩的笑聲觸碰到 Lam 太太最深的不安。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"laughing at my age","meaning":"嘲笑我的年紀","examples":[{"en":"Mrs Lam thought the boys were laughing at her age.","zh":"Lam 太太以為那些男孩在嘲笑她的年紀。"},{"en":"Laughing at my age means mocking me because I am old.","zh":"laughing at my age 指因我年老而取笑我。"},{"en":"An elderly learner may fear that young people are laughing at her age when she makes mistakes.","zh":"年長學習者出錯時，可能害怕年輕人在嘲笑自己的年紀。"},{"en":"Mrs Lam worries they are laughing at her age because she already doubts herself.","zh":"Lam 太太擔心他們嘲笑她的年紀，因為她本已懷疑自己。"},{"en":"This phrase shows how shame can make laughter feel personal.","zh":"這個短語顯示羞愧如何令笑聲變得針對自己。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"even if they were","meaning":"即使他們真的是","examples":[{"en":"Even if they were laughing, Jason told her to stand her ground.","zh":"Jason 告訴她，即使他們真的是在笑，她也要堅持立場。"},{"en":"Even if they were means although that possibility may be true.","zh":"even if they were 指即使那種可能性是真的。"},{"en":"Even if they were rude, you can still answer calmly.","zh":"即使他們真的是無禮，你仍可以冷靜回答。"},{"en":"Jason means that even if the boys were laughing, Mrs Lam should not surrender her dream.","zh":"Jason 的意思是，即使男孩真的在笑，Lam 太太也不應放棄夢想。"},{"en":"This phrase helps someone face a fear without denying it.","zh":"這個短語幫助人面對恐懼，而不是否認它。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"stand your ground","meaning":"堅持立場；不要退縮","examples":[{"en":"Jason told Mrs Lam to stand her ground.","zh":"Jason 叫 Lam 太太堅持立場。"},{"en":"Stand your ground means stay firm and not give up when challenged.","zh":"stand your ground 指面對挑戰時保持堅定，不退縮。"},{"en":"A student should stand her ground if she knows her answer is correct.","zh":"如果學生知道自己的答案正確，就應堅持立場。"},{"en":"Mrs Lam needs to stand her ground because her dream deserves space.","zh":"Lam 太太需要堅持立場，因為她的夢想值得有位置。"},{"en":"This phrase encourages courage under pressure.","zh":"這個短語鼓勵人在壓力下保持勇氣。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"wanted to quit","meaning":"想放棄","examples":[{"en":"Mrs Lam wanted to quit.","zh":"Lam 太太想放棄。"},{"en":"Wanted to quit means wanted to stop doing something before finishing it.","zh":"wanted to quit 指想在完成前停止做某事。"},{"en":"The new swimmer wanted to quit after the first difficult lesson.","zh":"新游泳學生在第一堂困難課後想放棄。"},{"en":"Mrs Lam wants to quit because embarrassment feels stronger than hope.","zh":"Lam 太太想放棄，因為尷尬感比希望更強。"},{"en":"This phrase shows the point where a person nearly gives up.","zh":"這個短語顯示一個人幾乎要放棄的時刻。"}],"source":"2015 Q3.pdf","sourcePage":7},{"front":"at one point","meaning":"有一刻","examples":[{"en":"At one point, Mrs Lam folded the robe into a plastic bag.","zh":"有一刻，Lam 太太把鳳袍摺進膠袋裏。"},{"en":"At one point means at a particular moment during a longer situation.","zh":"at one point 指在較長情況中的某一特定時刻。"},{"en":"At one point during rehearsal, everyone forgot the next line.","zh":"排練中有一刻，所有人都忘了下一句台詞。"},{"en":"At one point, Mrs Lam is so discouraged that she prepares to leave.","zh":"有一刻，Lam 太太灰心到準備離開。"},{"en":"This phrase helps mark an important moment in the process.","zh":"這個短語幫助標示過程中的重要時刻。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"folded something into","meaning":"把……摺進","examples":[{"en":"She folded the phoenix robe into a plastic bag.","zh":"她把鳳袍摺進膠袋裏。"},{"en":"Folded something into means bent and placed something inside another container.","zh":"folded something into 指把某物摺好並放進另一個容器裏。"},{"en":"The student folded her uniform into a sports bag after practice.","zh":"學生練習後把校服摺進運動袋裏。"},{"en":"Folding the robe into a bag makes Mrs Lam’s withdrawal feel practical and final.","zh":"把鳳袍摺進袋裏，令 Lam 太太的退出感覺實際而決絕。"},{"en":"This phrase shows a physical action that carries emotional meaning.","zh":"這個短語顯示一個帶有情感意義的身體動作。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"plastic bag","meaning":"膠袋","examples":[{"en":"Mrs Lam folded the phoenix robe into a plastic bag.","zh":"Lam 太太把鳳袍摺進膠袋裏。"},{"en":"A plastic bag is a light bag made of plastic, often used for carrying things.","zh":"plastic bag 指由塑膠製成、常用來攜帶物品的輕便袋。"},{"en":"A student carried her wet shoes in a plastic bag after PE class.","zh":"體育課後，學生用膠袋裝濕鞋。"},{"en":"Putting a beautiful robe into a plastic bag can make the dream seem small and ordinary.","zh":"把美麗的鳳袍放進膠袋，可以令夢想顯得細小而普通。"},{"en":"In the story, the plastic bag contrasts with the dignity of the phoenix robe.","zh":"在故事中，膠袋與鳳袍的尊貴形成對比。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"enough was enough","meaning":"夠了；到此為止","examples":[{"en":"Mrs Lam told herself enough was enough.","zh":"Lam 太太告訴自己：夠了，到此為止。"},{"en":"Enough was enough means a person decides they can no longer accept a situation.","zh":"enough was enough 指一個人決定再也不能接受某種情況。"},{"en":"After three unfair comments, the student decided enough was enough.","zh":"聽到三次不公平評論後，學生決定夠了。"},{"en":"Mrs Lam tells herself enough is enough because practice feels too painful.","zh":"Lam 太太告訴自己到此為止，因為練習感覺太痛苦。"},{"en":"This phrase shows a firm decision to stop or resist something.","zh":"這個短語顯示停止或反抗某事的堅定決定。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"dreamed of","meaning":"夢見","examples":[{"en":"That night, she dreamed of the girl in the photograph.","zh":"那晚，她夢見照片中的女孩。"},{"en":"Dreamed of means saw or imagined someone or something while sleeping.","zh":"dreamed of 指在睡夢中看見或想像某人或某物。"},{"en":"The child dreamed of flying over the harbour.","zh":"孩子夢見自己飛越海港。"},{"en":"Mrs Lam dreams of the girl because her younger self is still waiting.","zh":"Lam 太太夢見那個女孩，因為她年輕時的自己仍在等待。"},{"en":"This phrase connects sleep with memory and desire.","zh":"這個短語把睡眠與回憶和渴望連在一起。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"accuse her","meaning":"指責她","examples":[{"en":"The girl in the photograph did not accuse her.","zh":"照片中的女孩沒有指責她。"},{"en":"Accuse her means blame her or say she did something wrong.","zh":"accuse her 指責備她或說她做錯了事。"},{"en":"The teacher did not accuse the student until she had proof.","zh":"老師在有證據前沒有指責那名學生。"},{"en":"Mrs Lam fears her younger self may accuse her of giving up.","zh":"Lam 太太害怕年輕時的自己會指責她放棄。"},{"en":"In the dream, the girl waits instead of blaming her.","zh":"在夢中，那個女孩沒有責怪她，而是在等待。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"under a paper moon","meaning":"在紙月亮下","examples":[{"en":"The girl simply stood under a paper moon and waited.","zh":"那個女孩只是站在紙月亮下等待。"},{"en":"Under a paper moon means beneath a stage-like moon made from paper or something artificial.","zh":"under a paper moon 指在用紙或人造材料製成、像舞台道具的月亮之下。"},{"en":"In the school play, the princess stood under a paper moon.","zh":"在學校話劇中，公主站在紙月亮下。"},{"en":"A paper moon can suggest theatre, memory, and a dream that is fragile but visible.","zh":"紙月亮可以暗示戲劇、回憶，以及脆弱但可見的夢。"},{"en":"In the story, the girl under the paper moon seems to wait on an imagined stage.","zh":"在故事中，站在紙月亮下的女孩像是在想像中的舞台上等待。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"not until then did","meaning":"直到那時才","examples":[{"en":"Not until then did Mrs Lam understand the meaning of the dream.","zh":"直到那時，Lam 太太才明白那個夢的意思。"},{"en":"Not until then did means only at that moment did something finally happen or become clear.","zh":"not until then did 指只有到那一刻某事才終於發生或變清楚。"},{"en":"Not until the teacher explained the ending did I understand the story.","zh":"直到老師解釋結局，我才明白故事。"},{"en":"Not until the dream does Mrs Lam understand what she truly wants.","zh":"直到那個夢出現，Lam 太太才明白自己真正想要甚麼。"},{"en":"This structure emphasises a delayed realisation.","zh":"這個結構強調遲來的領悟。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"applause","meaning":"掌聲","examples":[{"en":"The dream was not applause.","zh":"那個夢不是掌聲。"},{"en":"Applause means clapping to show approval, praise, or enjoyment.","zh":"applause 指拍手以表示認同、讚賞或喜愛。"},{"en":"The audience gave loud applause after the final song.","zh":"最後一首歌後，觀眾給予熱烈掌聲。"},{"en":"Mrs Lam realises the dream is not applause, because praise is not the deepest need.","zh":"Lam 太太明白那個夢不是掌聲，因為讚賞不是最深的需要。"},{"en":"This word helps separate public approval from personal fulfilment.","zh":"這個詞幫助分開公眾認可和個人圓滿。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"youth restored","meaning":"青春復還","examples":[{"en":"The dream was not youth restored.","zh":"那個夢不是青春復還。"},{"en":"Youth restored means becoming young again or getting back one’s youth.","zh":"youth restored 指重新變得年輕或取回青春。"},{"en":"No medicine can truly give a person youth restored.","zh":"沒有藥物能真正讓人青春復還。"},{"en":"Mrs Lam does not need youth restored; she needs permission to be seen now.","zh":"Lam 太太不需要青春復還；她需要現在被看見的許可。"},{"en":"This phrase shows that the story is not about reversing age.","zh":"這個短語顯示故事不是關於逆轉年齡。"}],"source":"2015 Q3.pdf","sourcePage":8},{"front":"permission to","meaning":"去……的許可","examples":[{"en":"The dream was permission to take up space.","zh":"那個夢是去佔有自己位置的許可。"},{"en":"Permission to do something means the right or freedom to do it.","zh":"permission to do something 指做某事的權利或自由。"},{"en":"A shy student may need permission to speak without fear of being judged.","zh":"害羞學生可能需要不怕被評價地說話的許可。"},{"en":"Mrs Lam needs permission to sing as she is, not as she once was.","zh":"Lam 太太需要以現在的自己歌唱的許可，而不是以昔日的自己。"},{"en":"This phrase shows an inner approval she has long denied herself.","zh":"這個短語顯示她長久不給自己的內在允許。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"take up space","meaning":"佔有自己的位置","examples":[{"en":"Mrs Lam needed permission to take up space.","zh":"Lam 太太需要佔有自己位置的許可。"},{"en":"Take up space means allow yourself to be present, visible, and important.","zh":"take up space 指容許自己存在、被看見和變得重要。"},{"en":"A quiet student takes up space when she speaks clearly in a meeting.","zh":"安靜學生在會議中清楚發言時，就是佔有自己的位置。"},{"en":"Older people also deserve to take up space in public life and art.","zh":"長者也值得在公共生活和藝術中佔有自己的位置。"},{"en":"In the story, Mrs Lam learns she does not have to remain small.","zh":"在故事中，Lam 太太學會自己不必一直縮小。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"become visible","meaning":"變得被看見","examples":[{"en":"She needed permission to become visible.","zh":"她需要變得被看見的許可。"},{"en":"Become visible means be seen, noticed, or recognised by others.","zh":"become visible 指被別人看見、注意或承認。"},{"en":"A volunteer may become visible when the school finally thanks her publicly.","zh":"當學校終於公開感謝義工時，她可能變得被看見。"},{"en":"Mrs Lam has spent years behind costumes, but now she wants to be visible herself.","zh":"Lam 太太多年來藏在戲服背後，但現在她想自己被看見。"},{"en":"This phrase shows a move from hidden service to public presence.","zh":"這個短語顯示從隱藏服務走向公開存在。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"finish a song","meaning":"唱完一首歌","examples":[{"en":"Mrs Lam wanted to finish a song she had carried for years.","zh":"Lam 太太想唱完一首她多年來一直背負的歌。"},{"en":"Finish a song means sing or perform it to the end.","zh":"finish a song 指把一首歌唱到或表演到結尾。"},{"en":"The young singer was nervous but managed to finish the song.","zh":"年輕歌手很緊張，但成功唱完一首歌。"},{"en":"For Mrs Lam, finishing a song means completing an old dream.","zh":"對 Lam 太太來說，唱完一首歌就是完成一個舊夢。"},{"en":"This phrase turns a performance into an act of personal healing.","zh":"這個短語把表演變成個人療癒的行動。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"had been carrying for sixty years","meaning":"已經背負了六十年","examples":[{"en":"She had been carrying the song for sixty years.","zh":"她已經背負那首歌六十年。"},{"en":"Had been carrying for sixty years means had kept it inside her for six decades.","zh":"had been carrying for sixty years 指把它藏在心裏長達六十年。"},{"en":"My grandfather had been carrying a war memory for sixty years before he spoke of it.","zh":"我的祖父把戰爭記憶背負了六十年，才終於說出來。"},{"en":"Mrs Lam has carried the song so long that it has become part of her life.","zh":"Lam 太太背負那首歌太久，以致它已成為她人生的一部分。"},{"en":"This phrase shows the weight and endurance of a hidden dream.","zh":"這個短語顯示隱藏夢想的重量和持久。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"on the night of the performance","meaning":"演出當晚","examples":[{"en":"On the night of the performance, the hall was packed.","zh":"演出當晚，禮堂坐滿了人。"},{"en":"On the night of the performance means during the evening when the show took place.","zh":"on the night of the performance 指表演舉行的那個晚上。"},{"en":"On the night of the performance, students arrived early to put on costumes.","zh":"演出當晚，學生很早到達換戲服。"},{"en":"This phrase signals the important moment after weeks of practice.","zh":"這個短語標示數星期練習後的重要時刻。"},{"en":"In the story, it marks the night Mrs Lam must face the audience.","zh":"在故事中，它標示 Lam 太太必須面對觀眾的晚上。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"the hall was packed","meaning":"禮堂坐滿了人","examples":[{"en":"The hall was packed on the night of the performance.","zh":"演出當晚，禮堂坐滿了人。"},{"en":"The hall was packed means the hall was full of people.","zh":"the hall was packed 指禮堂裏坐滿了人。"},{"en":"The hall was packed for the school concert because families came to watch.","zh":"學校音樂會時，因為家人都來觀看，禮堂坐滿了人。"},{"en":"A packed hall can make a performer feel proud and frightened at the same time.","zh":"坐滿人的禮堂可以令表演者同時感到自豪和害怕。"},{"en":"In the story, the full hall increases Mrs Lam’s fear and importance.","zh":"在故事中，滿座禮堂增加了 Lam 太太的恐懼和重要性。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"behind the curtain","meaning":"在布幕後","examples":[{"en":"Mrs Lam waited behind the curtain.","zh":"Lam 太太在布幕後等待。"},{"en":"Behind the curtain means in the hidden area just off the stage before appearing.","zh":"behind the curtain 指在舞台旁未被觀眾看見的隱藏位置。"},{"en":"The actors whispered behind the curtain before the play began.","zh":"話劇開始前，演員們在布幕後低聲說話。"},{"en":"Waiting behind the curtain can feel tense because the audience is close but unseen.","zh":"在布幕後等待可以很緊張，因為觀眾很近但看不見。"},{"en":"In the story, this place stands between Mrs Lam’s old hidden life and public voice.","zh":"在故事中，這個地方位於 Lam 太太舊日隱藏生活和公開聲音之間。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"heart beating louder than the drums","meaning":"心跳聲比鼓聲更響","examples":[{"en":"She could hear her heart beating louder than the drums.","zh":"她聽見自己的心跳聲比鼓聲更響。"},{"en":"Heart beating louder than the drums means she felt so nervous that her heartbeat seemed louder than the music.","zh":"heart beating louder than the drums 指她緊張得覺得心跳聲比音樂還大。"},{"en":"Before the competition, the dancer felt her heart beating louder than the drums.","zh":"比賽前，舞者覺得自己的心跳聲比鼓聲更響。"},{"en":"This phrase makes fear physical and easy to imagine.","zh":"這個短語令恐懼變得具體而容易想像。"},{"en":"In the story, it shows how much courage Mrs Lam needs before singing.","zh":"在故事中，它顯示 Lam 太太唱歌前需要多大勇氣。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"drums","meaning":"鼓","examples":[{"en":"The drums sounded as the performance began.","zh":"表演開始時，鼓聲響起。"},{"en":"Drums are musical instruments played by striking a stretched surface.","zh":"drums 是敲擊繃緊表面而發聲的樂器。"},{"en":"Drums can create rhythm, excitement, and tension in a performance.","zh":"鼓可以在表演中製造節奏、興奮和緊張感。"},{"en":"In Cantonese opera, drums can guide movement and dramatic timing.","zh":"在粵劇中，鼓可以引導動作和戲劇節奏。"},{"en":"In the story, the drums make Mrs Lam’s nervous heartbeat feel even stronger.","zh":"在故事中，鼓聲令 Lam 太太緊張的心跳更加明顯。"}],"source":"2015 Q3.pdf","sourcePage":9},{"front":"act normal","meaning":"表現正常","examples":[{"en":"Her grandson had once told her to act normal in public.","zh":"她的孫兒曾叫她在公眾場合表現正常。"},{"en":"Act normal means behave in a way that does not attract attention or seem unusual.","zh":"act normal 指行為不要引人注意或顯得奇怪。"},{"en":"The nervous student tried to act normal when the teacher called her name.","zh":"老師叫到她名字時，緊張的學生嘗試表現正常。"},{"en":"Being told to act normal can make someone feel ashamed of their true self.","zh":"被叫做「表現正常」可以令人對真實的自己感到羞愧。"},{"en":"In the story, this phrase shows how Mrs Lam has been pushed to stay invisible.","zh":"在故事中，這個短語顯示 Lam 太太如何被推向隱形。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"in public","meaning":"在公眾場合","examples":[{"en":"Her grandson once told her to act normal in public.","zh":"她的孫兒曾叫她在公眾場合表現正常。"},{"en":"In public means in places where other people can see or hear you.","zh":"in public 指在別人能看見或聽見你的地方。"},{"en":"Students are expected to speak politely in public.","zh":"學生在公眾場合應有禮貌地說話。"},{"en":"Mrs Lam has learned to limit herself in public so others will not judge her.","zh":"Lam 太太學會在公眾場合限制自己，以免被人評價。"},{"en":"This phrase contrasts private dreams with public behaviour.","zh":"這個短語把私人夢想與公開行為形成對比。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"third row","meaning":"第三排","examples":[{"en":"Her grandson sat in the third row.","zh":"她的孫兒坐在第三排。"},{"en":"The third row means the row of seats after the first and second rows.","zh":"third row 指第一排和第二排之後的一排座位。"},{"en":"We sat in the third row, close enough to see the actors’ faces.","zh":"我們坐在第三排，近得可以看見演員的臉。"},{"en":"A family member in the third row can feel both near and emotionally distant.","zh":"坐在第三排的家人可以身體上很近，情感上卻很遠。"},{"en":"In the story, the grandson is physically present but first emotionally absent.","zh":"在故事中，孫兒身體上在場，但起初情感上缺席。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"eyes fixed on","meaning":"眼睛盯着","examples":[{"en":"Her grandson sat with his eyes fixed on his phone.","zh":"她的孫兒坐着，眼睛盯着電話。"},{"en":"Eyes fixed on something means looking at it steadily and not looking away.","zh":"eyes fixed on something 指穩定地看着某物，沒有移開目光。"},{"en":"The child sat with her eyes fixed on the cartoon.","zh":"孩子坐着，眼睛盯着卡通片。"},{"en":"Eyes fixed on a phone can show distraction or lack of interest.","zh":"眼睛盯着電話可以顯示分心或缺乏興趣。"},{"en":"In the story, the grandson’s eyes fixed on his phone show he is not yet seeing Mrs Lam.","zh":"在故事中，孫兒盯着電話，顯示他還未真正看見 Lam 太太。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"at first","meaning":"起初","examples":[{"en":"At first, Mrs Lam’s voice was thin.","zh":"起初，Lam 太太的聲音很單薄。"},{"en":"At first means at the beginning, before a change happens.","zh":"at first 指在開始時，在變化發生之前。"},{"en":"At first, the new student was quiet, but later she joined the discussion.","zh":"起初，新學生很安靜，但後來加入討論。"},{"en":"At first, Mrs Lam sounds weak because fear is still controlling her.","zh":"起初，Lam 太太聽起來較弱，因為恐懼仍控制着她。"},{"en":"This phrase prepares readers for improvement later.","zh":"這個短語為之後的改善作準備。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"voice was thin","meaning":"聲音單薄","examples":[{"en":"At first, her voice was thin.","zh":"起初，她的聲音單薄。"},{"en":"Voice was thin means the voice sounded weak, light, or lacking fullness.","zh":"voice was thin 指聲音聽起來弱、輕或不夠飽滿。"},{"en":"After being sick, the singer’s voice was thin during the first song.","zh":"生病後，歌手第一首歌時聲音單薄。"},{"en":"Mrs Lam’s voice is thin because she is nervous and out of practice.","zh":"Lam 太太的聲音單薄，因為她緊張而且久未練習。"},{"en":"This phrase makes the audience hear her uncertainty.","zh":"這個短語令觀眾聽見她的不確定。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"notes wavered","meaning":"音符顫動；走音不穩","examples":[{"en":"A few notes wavered as she began singing.","zh":"她開始唱歌時，有幾個音符顫動。"},{"en":"Notes wavered means some musical notes shook or became unsteady.","zh":"notes wavered 指一些音符顫抖或變得不穩。"},{"en":"The student’s notes wavered when she sang in front of the class.","zh":"學生在全班面前唱歌時，音符顫動。"},{"en":"Notes may waver when a singer is nervous or short of breath.","zh":"當歌手緊張或氣息不足時，音符可能不穩。"},{"en":"In the story, the wavering notes show Mrs Lam’s fear at the beginning.","zh":"在故事中，顫動的音符顯示 Lam 太太起初的恐懼。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"nearly looked down","meaning":"差點低頭","examples":[{"en":"Mrs Lam nearly looked down.","zh":"Lam 太太差點低頭。"},{"en":"Nearly looked down means almost lowered her eyes, often from fear or shame.","zh":"nearly looked down 指幾乎垂下眼睛，常因恐懼或羞愧。"},{"en":"The speaker nearly looked down when she forgot a word.","zh":"演講者忘記一個字時差點低頭。"},{"en":"Mrs Lam nearly looks down because she almost returns to hiding.","zh":"Lam 太太差點低頭，因為她幾乎又回到隱藏自己。"},{"en":"This phrase shows a moment when confidence almost breaks.","zh":"這個短語顯示信心幾乎破裂的一刻。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"instead","meaning":"反而","examples":[{"en":"Instead, she lifted her sleeve and drew a breath.","zh":"反而，她抬起衣袖，吸了一口氣。"},{"en":"Instead means in place of the expected action.","zh":"instead 指不是做預期中的事，而是做另一件事。"},{"en":"She wanted to run away; instead, she stayed and answered the question.","zh":"她想逃走；反而，她留下來回答問題。"},{"en":"Mrs Lam almost looks down; instead, she chooses to continue.","zh":"Lam 太太幾乎低頭；反而，她選擇繼續。"},{"en":"This word marks a turning point from fear to courage.","zh":"這個詞標示從恐懼走向勇氣的轉折點。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"lifted her sleeve","meaning":"抬起衣袖","examples":[{"en":"Mrs Lam lifted her sleeve before singing.","zh":"Lam 太太唱歌前抬起衣袖。"},{"en":"Lifted her sleeve means raised the sleeve of her costume or clothing.","zh":"lifted her sleeve 指抬起戲服或衣服的袖子。"},{"en":"The dancer lifted her sleeve to begin the traditional movement.","zh":"舞者抬起衣袖，開始傳統動作。"},{"en":"In Cantonese opera, lifting a sleeve can be graceful and meaningful.","zh":"在粵劇中，抬起衣袖可以優雅而有意思。"},{"en":"In the story, this action helps Mrs Lam enter the role and claim the stage.","zh":"在故事中，這個動作幫助 Lam 太太進入角色並佔有舞台。"}],"source":"2015 Q3.pdf","sourcePage":10},{"front":"drew a breath","meaning":"吸了一口氣","examples":[{"en":"She drew a breath from somewhere deeper than fear.","zh":"她從比恐懼更深處吸了一口氣。"},{"en":"Drew a breath means took air into the lungs before speaking, singing, or acting.","zh":"drew a breath 指在說話、唱歌或行動前把空氣吸進肺裏。"},{"en":"The singer drew a breath before the difficult high note.","zh":"歌手在困難高音前吸了一口氣。"},{"en":"Drawing a breath can help a nervous person steady the body.","zh":"吸一口氣可以幫助緊張的人穩住身體。"},{"en":"In the story, Mrs Lam’s breath becomes an act of courage.","zh":"在故事中，Lam 太太的呼吸成為勇氣的行動。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"deeper than fear","meaning":"比恐懼更深處","examples":[{"en":"She drew a breath from somewhere deeper than fear.","zh":"她從比恐懼更深處吸了一口氣。"},{"en":"Deeper than fear means coming from a stronger inner place than fear.","zh":"deeper than fear 指來自比恐懼更強的內心深處。"},{"en":"The student answered from somewhere deeper than fear because the truth mattered.","zh":"學生從比恐懼更深處回答，因為真相很重要。"},{"en":"Mrs Lam finds something deeper than fear: memory, dignity, and desire.","zh":"Lam 太太找到比恐懼更深的東西：記憶、尊嚴和渴望。"},{"en":"This phrase shows that courage can come from a very old, hidden strength.","zh":"這個短語顯示勇氣可以來自很久以前隱藏的力量。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"not as…, but as…","meaning":"不是以……而是以……","examples":[{"en":"She sang not as a young woman, but as an old woman who had survived life.","zh":"她唱歌時不是以年輕女子的身分，而是以一位熬過人生的老婦人身分。"},{"en":"Not as A, but as B means not in one identity or way, but in another more accurate one.","zh":"not as A, but as B 指不是以某種身份或方式，而是以另一種更準確的身份或方式。"},{"en":"He spoke not as a winner, but as someone who had learned from failure.","zh":"他發言時不是以勝利者身分，而是以從失敗中學習的人身分。"},{"en":"Mrs Lam does not sing as her younger self; she sings as the woman life has made her.","zh":"Lam 太太不是以年輕時的自己歌唱，而是以被人生塑造出來的女人歌唱。"},{"en":"This structure replaces a shallow image with a deeper truth.","zh":"這個結構用更深層真相取代表面形象。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"pretending life had been easy","meaning":"假裝人生一直容易","examples":[{"en":"She was not pretending life had been easy.","zh":"她不是在假裝人生一直容易。"},{"en":"Pretending life had been easy means acting as if one’s life had no pain, difficulty, or sacrifice.","zh":"pretending life had been easy 指裝作自己的人生沒有痛苦、困難或犧牲。"},{"en":"The old man smiled without pretending life had been easy.","zh":"那位老人微笑着，卻沒有假裝人生一直容易。"},{"en":"Mrs Lam sings honestly because she does not hide the hardship in her voice.","zh":"Lam 太太誠實地歌唱，因為她沒有把艱難從聲音中藏起來。"},{"en":"This phrase shows that strength can include suffering.","zh":"這個短語顯示力量可以包含痛苦。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"had survived it","meaning":"熬過了它","examples":[{"en":"She sang as an old woman who had survived life.","zh":"她以一位熬過人生的老婦人身分歌唱。"},{"en":"Had survived it means had lived through something difficult and continued.","zh":"had survived it 指經歷困難後仍繼續活下來。"},{"en":"After years of illness, she had survived it and returned to work.","zh":"經過多年疾病後，她熬過了它，並重返工作。"},{"en":"Mrs Lam has survived family duties, lost chances, and silence.","zh":"Lam 太太熬過了家庭責任、錯失的機會和沉默。"},{"en":"This phrase gives age dignity instead of treating it as weakness.","zh":"這個短語賦予年老尊嚴，而不是把它視為弱點。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"shifting in their seats","meaning":"在座位上坐立不安","examples":[{"en":"People stopped shifting in their seats.","zh":"人們停止在座位上坐立不安。"},{"en":"Shifting in their seats means moving around slightly while sitting, often from boredom or discomfort.","zh":"shifting in their seats 指坐着時微微移動，常因沉悶或不舒服。"},{"en":"Students were shifting in their seats before the long speech ended.","zh":"長演講結束前，學生們在座位上坐立不安。"},{"en":"When Mrs Lam sings, people stop shifting because they are fully listening.","zh":"Lam 太太唱歌時，人們停止坐立不安，因為他們完全在聽。"},{"en":"This phrase shows the audience becoming still and attentive.","zh":"這個短語顯示觀眾變得安靜而專注。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"sat taller","meaning":"坐得更挺直","examples":[{"en":"The elderly residents sat taller when Mrs Lam sang.","zh":"Lam 太太唱歌時，長者居民坐得更挺直。"},{"en":"Sat taller means sat more upright, often because of pride, hope, or attention.","zh":"sat taller 指坐得更直，常因驕傲、希望或注意。"},{"en":"The students sat taller when their team was praised.","zh":"當自己的隊伍被稱讚時，學生們坐得更挺直。"},{"en":"The elderly residents sit taller because Mrs Lam’s voice gives them dignity too.","zh":"長者居民坐得更挺直，因為 Lam 太太的聲音也給了他們尊嚴。"},{"en":"This phrase shows emotional change through body posture.","zh":"這個短語透過身體姿勢顯示情感變化。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"lowered his phone","meaning":"放下電話","examples":[{"en":"Mrs Lam’s grandson slowly lowered his phone.","zh":"Lam 太太的孫兒慢慢放下電話。"},{"en":"Lowered his phone means moved the phone down and stopped focusing on it.","zh":"lowered his phone 指把電話移低，並停止專注於它。"},{"en":"The teenager lowered his phone when the singer began the final song.","zh":"歌手開始最後一首歌時，年輕人放下電話。"},{"en":"Lowering his phone shows the grandson finally paying attention to Mrs Lam.","zh":"放下電話顯示孫兒終於注意 Lam 太太。"},{"en":"In the story, this small action shows respect beginning to grow.","zh":"在故事中，這個小動作顯示尊重開始生長。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"by the final note","meaning":"到最後一個音符時","examples":[{"en":"By the final note, her voice had grown steady.","zh":"到最後一個音符時，她的聲音已變得穩定。"},{"en":"By the final note means by the time the last musical sound was reached.","zh":"by the final note 指到達最後一個樂音的時候。"},{"en":"By the final note, the nervous singer had found her confidence.","zh":"到最後一個音符時，緊張的歌手已找回自信。"},{"en":"This phrase shows change from the beginning to the end of a performance.","zh":"這個短語顯示表演從開始到結束的變化。"},{"en":"In the story, Mrs Lam becomes stronger as the song continues.","zh":"在故事中，Lam 太太隨着歌曲繼續而變得更有力量。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"grown so steady that","meaning":"變得如此穩定以致","examples":[{"en":"Her voice had grown so steady that even the rain seemed to pause.","zh":"她的聲音變得如此穩定，以致連外面的雨也似乎停了下來。"},{"en":"Grown so steady that means become so stable that it causes or seems to cause a result.","zh":"grown so steady that 指變得如此穩定，以致造成或似乎造成某種結果。"},{"en":"The speaker’s voice grew so steady that the room became quiet.","zh":"演講者的聲音變得如此穩定，以致房間安靜下來。"},{"en":"Mrs Lam’s voice grows so steady that nature itself seems to listen.","zh":"Lam 太太的聲音變得如此穩定，以致連自然也似乎在聆聽。"},{"en":"This phrase exaggerates stability to show emotional power.","zh":"這個短語用誇張方式顯示穩定帶來的情感力量。"}],"source":"2015 Q3.pdf","sourcePage":11},{"front":"seemed to pause","meaning":"似乎停了下來","examples":[{"en":"Even the rain outside seemed to pause.","zh":"連外面的雨也似乎停了下來。"},{"en":"Seemed to pause means appeared to stop briefly, even if it may not really have stopped.","zh":"seemed to pause 指看似短暫停止，即使未必真的停止。"},{"en":"The whole class seemed to pause when the winner was announced.","zh":"得獎者公布時，全班似乎停了下來。"},{"en":"Rain seeming to pause suggests the song has created a powerful silence.","zh":"雨似乎停下來，暗示歌曲創造了強大的寂靜。"},{"en":"This phrase gives the moment a magical feeling.","zh":"這個短語令那一刻帶有神奇感。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"for a second","meaning":"有一秒","examples":[{"en":"For a second, there was silence.","zh":"有一秒，四周一片寂靜。"},{"en":"For a second means for a very short moment.","zh":"for a second 指在非常短的一刻。"},{"en":"For a second, everyone forgot to clap after the powerful speech.","zh":"有一秒，大家在有力演講後忘記拍掌。"},{"en":"A second of silence can show that people are deeply moved.","zh":"一秒的沉默可以顯示人們被深深打動。"},{"en":"In the story, the silence before applause makes Mrs Lam’s song feel important.","zh":"在故事中，掌聲前的寂靜令 Lam 太太的歌顯得重要。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"the hall rose","meaning":"全場站起來","examples":[{"en":"Then the hall rose for Mrs Lam.","zh":"然後，全場為 Lam 太太站起來。"},{"en":"The hall rose means the people in the hall stood up together to show respect.","zh":"the hall rose 指禮堂裏的人一起站起來表示尊重。"},{"en":"The hall rose when the old teacher received the lifetime award.","zh":"老教師獲得終身成就獎時，全場站起來。"},{"en":"A hall rising for someone shows public honour and strong emotion.","zh":"全場為某人站起來，顯示公開敬意和強烈情感。"},{"en":"In the story, the audience finally recognises Mrs Lam’s courage.","zh":"在故事中，觀眾終於承認 Lam 太太的勇氣。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"bowed","meaning":"鞠躬","examples":[{"en":"Mrs Lam bowed after the performance.","zh":"Lam 太太在表演後鞠躬。"},{"en":"Bowed means bent the upper body to thank or respect the audience.","zh":"bowed 指彎下上身向觀眾表示感謝或尊重。"},{"en":"The actors bowed after the final scene.","zh":"演員們在最後一幕後鞠躬。"},{"en":"A bow can show gratitude, humility, and completion.","zh":"鞠躬可以表示感謝、謙卑和完成。"},{"en":"In the story, Mrs Lam’s bow carries the weight of her whole life.","zh":"在故事中，Lam 太太的一鞠躬承載着她整個人生的重量。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"in that bow","meaning":"在那一鞠躬之中","examples":[{"en":"In that bow were all the years she had lost.","zh":"在那一鞠躬之中，是她失去的所有歲月。"},{"en":"In that bow means contained within that single gesture.","zh":"in that bow 指包含在那一個動作之中。"},{"en":"In that bow were months of practice, fear and courage.","zh":"在那一鞠躬之中，是數月的練習、恐懼和勇氣。"},{"en":"Mrs Lam’s bow holds more than thanks; it holds memory and regret.","zh":"Lam 太太的鞠躬不只包含感謝，也包含記憶和遺憾。"},{"en":"This phrase gives a small movement deep emotional meaning.","zh":"這個短語給一個小動作深厚情感意義。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"the years she had lost","meaning":"她失去的歲月","examples":[{"en":"Her bow held all the years she had lost.","zh":"她的鞠躬承載了她失去的所有歲月。"},{"en":"The years she had lost means the time and chances that passed without her dream being realised.","zh":"the years she had lost 指夢想未能實現時流逝的時間和機會。"},{"en":"The artist thought of the years she had lost before returning to painting.","zh":"那位藝術家重拾繪畫前，想起自己失去的歲月。"},{"en":"Mrs Lam lost years to duty, work and silence.","zh":"Lam 太太把歲月失給了責任、工作和沉默。"},{"en":"This phrase expresses regret for time that cannot be recovered.","zh":"這個短語表達對無法追回的時間的遺憾。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"the years she still had","meaning":"她仍然擁有的歲月","examples":[{"en":"Her bow also held all the years she still had.","zh":"她的鞠躬也承載了她仍然擁有的歲月。"},{"en":"The years she still had means the remaining time and possibilities in her life.","zh":"the years she still had 指她生命中剩下的時間和可能性。"},{"en":"After retirement, he began thinking about the years he still had.","zh":"退休後，他開始思考自己仍然擁有的歲月。"},{"en":"Mrs Lam realises she still has time to sing, teach and be seen.","zh":"Lam 太太明白自己仍有時間唱歌、教人和被看見。"},{"en":"This phrase turns the ending toward hope instead of loss.","zh":"這個短語把結尾轉向希望，而不是失去。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"not young again","meaning":"並非再次年輕","examples":[{"en":"Mrs Lam was not young again.","zh":"Lam 太太並非再次年輕。"},{"en":"Not young again means she did not return to her youth or become physically young.","zh":"not young again 指她沒有回到青春，也沒有身體上重新年輕。"},{"en":"After winning the race, the grandfather was proud but not young again.","zh":"祖父贏得比賽後很自豪，但並非再次年輕。"},{"en":"Mrs Lam’s victory does not erase age, pain or time.","zh":"Lam 太太的勝利沒有抹去年齡、痛楚或時間。"},{"en":"This phrase keeps the story honest about ageing.","zh":"這個短語讓故事誠實面對衰老。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"something better","meaning":"更好的東西；更珍貴的狀態","examples":[{"en":"She was something better: herself, fully and fearlessly.","zh":"她成為了更珍貴的狀態：完整而無懼的自己。"},{"en":"Something better means a more valuable or meaningful state than what was expected.","zh":"something better 指比預期更有價值或更有意義的狀態。"},{"en":"She did not become famous; she became something better, confident in her own voice.","zh":"她沒有成名；她成為了更好的自己，對自己的聲音有信心。"},{"en":"Mrs Lam is not young again, but she becomes something better by becoming fully herself.","zh":"Lam 太太並非再次年輕，但她透過完整成為自己而成為更珍貴的狀態。"},{"en":"This phrase shows that self-acceptance can be better than lost youth.","zh":"這個短語顯示自我接納可以比失去的青春更好。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"fully and fearlessly","meaning":"完整而無懼地","examples":[{"en":"Mrs Lam became herself, fully and fearlessly.","zh":"Lam 太太完整而無懼地成為自己。"},{"en":"Fully and fearlessly means completely and without fear.","zh":"fully and fearlessly 指完全地、沒有恐懼地。"},{"en":"The student spoke fully and fearlessly when she finally trusted her own ideas.","zh":"當學生終於相信自己的想法時，她完整而無懼地發言。"},{"en":"Mrs Lam sings fully and fearlessly when she stops apologising for her age.","zh":"當 Lam 太太不再為自己的年紀道歉時，她完整而無懼地歌唱。"},{"en":"This phrase shows complete self-acceptance and courage.","zh":"這個短語顯示完全的自我接納和勇氣。"}],"source":"2015 Q3.pdf","sourcePage":12},{"front":"after the performance","meaning":"演出後","examples":[{"en":"After the performance, her grandson ran to her.","zh":"演出後，她的孫兒跑向她。"},{"en":"After the performance means when the show had ended.","zh":"after the performance 指表演結束之後。"},{"en":"After the performance, the actors took photos with their families.","zh":"演出後，演員們與家人拍照。"},{"en":"The grandson runs to Mrs Lam after the performance because he finally sees her differently.","zh":"孫兒在演出後跑向 Lam 太太，因為他終於以不同方式看見她。"},{"en":"This phrase moves the story from public applause to family emotion.","zh":"這個短語把故事從公開掌聲轉向家庭情感。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"wet eyes","meaning":"眼泛淚光","examples":[{"en":"Her grandson ran to her with wet eyes.","zh":"她的孫兒眼泛淚光地跑向她。"},{"en":"Wet eyes are eyes filled with tears or close to crying.","zh":"wet eyes 指眼中含淚或快要哭出來。"},{"en":"The teacher had wet eyes when her students thanked her.","zh":"學生感謝老師時，老師眼泛淚光。"},{"en":"Wet eyes show that the grandson is moved by Mrs Lam’s performance.","zh":"眼泛淚光顯示孫兒被 Lam 太太的表演打動。"},{"en":"This phrase reveals emotion without directly saying he cried.","zh":"這個短語不直接說他哭了，卻揭示情感。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"beneath the stage lights","meaning":"在舞台燈光下","examples":[{"en":"Mrs Lam looked at the phoenix robe beneath the stage lights.","zh":"Lam 太太在舞台燈光下看着那件鳳袍。"},{"en":"Beneath the stage lights means under the lights used to illuminate a performance area.","zh":"beneath the stage lights 指在照亮表演區的燈光之下。"},{"en":"The dancers’ costumes shone beneath the stage lights.","zh":"舞者的服裝在舞台燈光下閃亮。"},{"en":"A robe beneath the stage lights belongs to performance, not storage.","zh":"舞台燈光下的袍服屬於表演，而不是收藏。"},{"en":"In the story, the lights make Mrs Lam’s costume and dream visible.","zh":"在故事中，燈光令 Lam 太太的戲服和夢想變得可見。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"slowly but surely","meaning":"慢慢但確定地","examples":[{"en":"Slowly but surely, a smile crossed her face.","zh":"慢慢但確定地，一個笑容在她臉上浮現。"},{"en":"Slowly but surely means gradually but with certainty.","zh":"slowly but surely 指逐漸地，但很確定。"},{"en":"Slowly but surely, the shy student began to speak in class.","zh":"慢慢但確定地，那個害羞學生開始在課堂上發言。"},{"en":"Mrs Lam’s smile appears slowly but surely because confidence is settling inside her.","zh":"Lam 太太的笑容慢慢但確定地出現，因為自信正在她心裏安定下來。"},{"en":"This phrase shows gentle, certain change.","zh":"這個短語顯示溫柔而確定的變化。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"a smile crossed her face","meaning":"笑容在她臉上浮現","examples":[{"en":"A smile crossed Mrs Lam’s face.","zh":"笑容在 Lam 太太臉上浮現。"},{"en":"A smile crossed her face means a smile slowly appeared on her face.","zh":"a smile crossed her face 指笑容慢慢在她臉上出現。"},{"en":"A smile crossed the child’s face when she saw her mother.","zh":"孩子看見母親時，笑容在她臉上浮現。"},{"en":"Mrs Lam’s smile crosses her face after she understands what she has achieved.","zh":"Lam 太太明白自己完成了甚麼後，笑容在她臉上浮現。"},{"en":"This phrase describes emotion appearing gently and visibly.","zh":"這個短語描述情感溫柔而可見地出現。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"come next Wednesday","meaning":"下星期三來","examples":[{"en":"Mrs Lam told her grandson to come next Wednesday.","zh":"Lam 太太叫她的孫兒下星期三來。"},{"en":"Come next Wednesday means arrive or attend on the following Wednesday.","zh":"come next Wednesday 指在下一個星期三到來或出席。"},{"en":"The coach told the team to come next Wednesday for extra practice.","zh":"教練叫隊伍下星期三來加練。"},{"en":"Mrs Lam invites her grandson to come next Wednesday because she wants to pass on the song.","zh":"Lam 太太邀請孫兒下星期三來，因為她想把歌曲傳下去。"},{"en":"This phrase points to continuation after the performance.","zh":"這個短語指向演出後的延續。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"start with","meaning":"從……開始","examples":[{"en":"They would start with the first line.","zh":"他們會從第一句開始。"},{"en":"Start with means begin by using or doing something first.","zh":"start with 指先用某物或先做某事來開始。"},{"en":"When learning a song, students often start with the first line.","zh":"學歌時，學生常從第一句開始。"},{"en":"Mrs Lam and her grandson start with the first line because every dream needs a beginning.","zh":"Lam 太太和孫兒從第一句開始，因為每個夢都需要起點。"},{"en":"This phrase shows a simple first step toward learning.","zh":"這個短語顯示學習的一個簡單第一步。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"by the following month","meaning":"到了下個月","examples":[{"en":"By the following month, the elderly centre had a new poster.","zh":"到了下個月，長者中心已有一張新海報。"},{"en":"By the following month means when the next month arrived, something had already happened.","zh":"by the following month 指到下一個月時，某事已經發生。"},{"en":"By the following month, the club had gained ten new members.","zh":"到了下個月，那個學會已有十名新成員。"},{"en":"The new poster shows that Mrs Lam’s performance has created change quickly.","zh":"新海報顯示 Lam 太太的表演很快帶來改變。"},{"en":"This phrase helps show the result of an earlier event.","zh":"這個短語幫助顯示早前事件的結果。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"on its door","meaning":"在門上","examples":[{"en":"The elderly centre had a new poster on its door.","zh":"長者中心門上有一張新海報。"},{"en":"On its door means attached to or displayed on the door of a place.","zh":"on its door 指貼在或展示在某個地方的門上。"},{"en":"The classroom had an exam notice on its door.","zh":"課室門上貼着考試通知。"},{"en":"A poster on the door is easy for visitors to see.","zh":"門上的海報很容易讓訪客看見。"},{"en":"In the story, the poster on the door publicly welcomes new dreams.","zh":"在故事中，門上的海報公開歡迎新的夢想。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"Cantonese Opera Workshop","meaning":"粵劇工作坊","examples":[{"en":"The new poster announced a Cantonese Opera Workshop.","zh":"新海報宣布開辦粵劇工作坊。"},{"en":"A Cantonese Opera Workshop is a class or activity where people learn Cantonese opera skills.","zh":"Cantonese Opera Workshop 指讓人學習粵劇技巧的課程或活動。"},{"en":"A Cantonese Opera Workshop may teach singing, gestures, costumes, and stage movement.","zh":"粵劇工作坊可能教授唱腔、手勢、戲服和舞台動作。"},{"en":"Opening a Cantonese Opera Workshop gives older people a place to try performance.","zh":"開辦粵劇工作坊給長者一個嘗試表演的地方。"},{"en":"In the story, the workshop turns Mrs Lam’s private dream into a shared opportunity.","zh":"在故事中，工作坊把 Lam 太太的私人夢想變成共享機會。"}],"source":"2015 Q3.pdf","sourcePage":13},{"front":"no audition","meaning":"毋須試音","examples":[{"en":"The workshop required no audition.","zh":"那個工作坊毋須試音。"},{"en":"No audition means people do not need to perform a test before joining.","zh":"no audition 指參加前不需要先表演測試。"},{"en":"A choir with no audition welcomes beginners as well as experienced singers.","zh":"毋須試音的合唱團歡迎初學者和有經驗的歌手。"},{"en":"No audition makes the workshop less frightening for elderly residents.","zh":"毋須試音令工作坊對長者居民來說沒那麼可怕。"},{"en":"This phrase shows that the door is open to people who lack confidence.","zh":"這個短語顯示門向缺乏信心的人打開。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"no age limit","meaning":"不設年齡限制","examples":[{"en":"The workshop had no age limit.","zh":"那個工作坊不設年齡限制。"},{"en":"No age limit means people of any age can join.","zh":"no age limit 指任何年齡的人都可以參加。"},{"en":"A drawing class with no age limit may include children, parents, and grandparents.","zh":"不設年齡限制的繪畫班可能包括孩子、父母和祖父母。"},{"en":"No age limit tells older people that it is not too late to begin.","zh":"不設年齡限制告訴長者，現在開始並不太遲。"},{"en":"In the story, this phrase directly answers Mrs Lam’s fear of being too old.","zh":"在故事中，這個短語直接回應 Lam 太太害怕自己太老的恐懼。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"dreams welcome","meaning":"歡迎帶着夢想前來","examples":[{"en":"The poster said, “Dreams welcome.”","zh":"海報寫着：「歡迎帶着夢想前來。」"},{"en":"Dreams welcome means people’s hopes and ambitions are invited and accepted.","zh":"dreams welcome 指人們的希望和抱負都被邀請和接納。"},{"en":"A community art class with “dreams welcome” tells beginners they can try.","zh":"寫着「歡迎帶着夢想前來」的社區藝術班告訴初學者可以嘗試。"},{"en":"This phrase makes the workshop feel warm instead of competitive.","zh":"這個短語令工作坊感覺溫暖，而不是競爭性強。"},{"en":"In the story, it shows the centre becoming a place for unfinished dreams.","zh":"在故事中，它顯示中心成為未完成夢想的地方。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"for years","meaning":"多年來","examples":[{"en":"For years, Mrs Lam believed her chance had passed her by.","zh":"多年來，Lam 太太相信自己的機會已經錯過。"},{"en":"For years means during many years.","zh":"for years 指在許多年之中。"},{"en":"For years, the old piano sat unused in the corner.","zh":"多年來，那部舊鋼琴一直閒置在角落。"},{"en":"Mrs Lam has believed for years that singing no longer belongs to her.","zh":"多年來，Lam 太太相信唱歌已不再屬於她。"},{"en":"This phrase shows how long a belief or sadness has lasted.","zh":"這個短語顯示一種信念或傷感持續了多久。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"her chance had passed her by","meaning":"她的機會已經錯過","examples":[{"en":"Mrs Lam believed her chance had passed her by.","zh":"Lam 太太相信她的機會已經錯過。"},{"en":"Her chance had passed her by means she thought the opportunity had already gone and would not return.","zh":"her chance had passed her by 指她以為機會已經離開，不會回來。"},{"en":"He believed his chance had passed him by when the scholarship deadline ended.","zh":"獎學金截止後，他以為自己的機會已經錯過。"},{"en":"Mrs Lam thinks her chance has passed because she is old and her body hurts.","zh":"Lam 太太覺得機會已經錯過，因為她年紀大了，身體也疼痛。"},{"en":"This phrase shows regret over a missed opportunity.","zh":"這個短語顯示對錯失機會的遺憾。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"no one saw what was coming","meaning":"沒有人預料到接下來的事","examples":[{"en":"No one saw what was coming: Mrs Lam stepped into her own dream.","zh":"沒有人預料到接下來的事：Lam 太太走進自己的夢想。"},{"en":"No one saw what was coming means nobody expected the surprising event that happened next.","zh":"no one saw what was coming 指沒有人預料到接下來發生的驚人事件。"},{"en":"No one saw what was coming when the quiet student won the speech contest.","zh":"那個安靜學生贏得演講比賽時，沒有人預料到接下來的事。"},{"en":"People did not expect Mrs Lam to become the centre of the story.","zh":"人們沒有預料到 Lam 太太會成為故事中心。"},{"en":"This phrase prepares readers for a surprising change.","zh":"這個短語讓讀者準備迎接驚人轉變。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"spent her life sewing costumes","meaning":"一生都在縫製戲服","examples":[{"en":"Mrs Lam had spent her life sewing costumes.","zh":"Lam 太太一生都在縫製戲服。"},{"en":"Spent her life sewing costumes means used many years making clothes for performances.","zh":"spent her life sewing costumes 指用多年時間為表演製作服裝。"},{"en":"A theatre worker may spend her life sewing costumes without ever standing on stage.","zh":"劇場工作者可能一生都在縫製戲服，卻從未站上舞台。"},{"en":"Mrs Lam’s life of sewing costumes kept her close to art but behind the scenes.","zh":"Lam 太太縫製戲服的一生令她接近藝術，但一直在幕後。"},{"en":"This phrase shows both dedication and sacrifice.","zh":"這個短語同時顯示奉獻和犧牲。"}],"source":"2015 Q3.pdf","sourcePage":14},{"front":"stepped into one of her own","meaning":"走進屬於自己的夢想；穿上自己的人生戲服","examples":[{"en":"The woman who sewed costumes stepped into one of her own.","zh":"那個縫製戲服的女人，走進了屬於自己的那一件。"},{"en":"Stepped into one of her own means entered a dream, role, or costume that finally belonged to herself.","zh":"stepped into one of her own 指走進終於屬於自己的夢想、角色或戲服。"},{"en":"After years of helping others perform, the teacher stepped into one of her own by singing onstage.","zh":"多年幫別人表演後，那位老師透過上台唱歌走進了屬於自己的夢想。"},{"en":"Mrs Lam steps into one of her own when she stops sewing only for others and performs herself.","zh":"當 Lam 太太不再只為別人縫製，而是親自表演時，她走進了屬於自己的夢。"},{"en":"This phrase beautifully completes the story by turning her work into her own life.","zh":"這個短語美麗地完成故事，把她的工作變成她自己的人生。"}],"source":"2015 Q3.pdf","sourcePage":14}],"dse/writing/part-b/2015/Q4":[{"front":"when classrooms cross borders","meaning":"當課室跨越國界","examples":[{"en":"The article discusses what happens when classrooms cross borders.","zh":"這篇文章討論當課室跨越國界時會發生甚麼。"},{"en":"When classrooms cross borders means when education moves beyond one country and students learn overseas.","zh":"When classrooms cross borders 指教育走出一個國家，學生到海外學習。"},{"en":"A classroom crosses borders when a Hong Kong student studies in Britain, Canada or Australia.","zh":"當香港學生到英國、加拿大或澳洲讀書，課室就跨越了國界。"},{"en":"When classrooms cross borders, students meet new teaching styles, languages and cultures.","zh":"當課室跨越國界，學生會遇到新的教學模式、語言和文化。"},{"en":"This phrase connects education with international movement.","zh":"這個短語把教育和國際流動連接起來。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"Hong Kong International Airport","meaning":"香港國際機場","examples":[{"en":"At Hong Kong International Airport, it is common to see young students leaving for school overseas.","zh":"在香港國際機場，常見年輕學生離港到海外升學。"},{"en":"Hong Kong International Airport is the airport many Hong Kong families use when travelling abroad.","zh":"香港國際機場是許多香港家庭出國時使用的機場。"},{"en":"A child leaving for overseas school may say goodbye to family at Hong Kong International Airport.","zh":"離港到海外讀書的孩子可能在香港國際機場與家人道別。"},{"en":"The airport becomes emotional when it is the place where a student’s new life begins.","zh":"當機場成為學生新生活開始的地方，它就變得充滿情感。"},{"en":"This phrase gives the article a real and local setting.","zh":"這個短語為文章提供真實而本地的場景。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"it is no longer unusual to","meaning":"……已不再罕見","examples":[{"en":"It is no longer unusual to see a young student pulling a large suitcase.","zh":"看見年輕學生拉着大行李箱已不再罕見。"},{"en":"It is no longer unusual to means something has become common or normal.","zh":"It is no longer unusual to 指某事已變得常見或正常。"},{"en":"It is no longer unusual to see teenagers preparing for overseas schools.","zh":"看見青少年準備到海外升學已不再罕見。"},{"en":"When many families make the same choice, the choice no longer feels rare.","zh":"當很多家庭作出同一選擇，這個選擇就不再少見。"},{"en":"This phrase shows that a social trend has become more visible.","zh":"這個短語顯示某個社會趨勢變得更明顯。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"a twelve-year-old student","meaning":"十二歲學生","examples":[{"en":"A twelve-year-old student may leave Hong Kong for overseas schooling.","zh":"十二歲學生可能會離開香港到海外升學。"},{"en":"A twelve-year-old student is a child who is twelve years old and still very young.","zh":"A twelve-year-old student 指一名十二歲、仍然很年幼的學生。"},{"en":"A twelve-year-old student may need help adapting to a new school and home.","zh":"十二歲學生可能需要幫助去適應新學校和新住處。"},{"en":"Sending a twelve-year-old student abroad can bring both opportunities and worries.","zh":"送十二歲學生到海外可以帶來機會，也帶來憂慮。"},{"en":"This phrase highlights how young some overseas students are.","zh":"這個短語突出有些海外升學學生年紀很小。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"pull a suitcase","meaning":"拉着行李箱","examples":[{"en":"A twelve-year-old student was pulling a suitcase larger than himself.","zh":"一名十二歲學生拉着一個比自己還大的行李箱。"},{"en":"Pull a suitcase means move luggage along by holding its handle and dragging it on wheels.","zh":"Pull a suitcase 指握着行李箱手柄，靠輪子把它拉動。"},{"en":"A child pulling a suitcase at the airport may look brave but nervous.","zh":"在機場拉着行李箱的孩子可能看起來勇敢但緊張。"},{"en":"Pulling a suitcase can symbolise leaving home for a new stage of life.","zh":"拉着行李箱可以象徵離家進入人生新階段。"},{"en":"This phrase gives a simple physical image of departure.","zh":"這個短語給出離別的簡單身體畫面。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"larger than himself","meaning":"比他自己還大","examples":[{"en":"The student was pulling a suitcase larger than himself.","zh":"那名學生拉着一個比他自己還大的行李箱。"},{"en":"Larger than himself means bigger than the student’s own body or size.","zh":"Larger than himself 指比學生自己的身體或體型還大。"},{"en":"A suitcase larger than himself makes the child look especially small.","zh":"一個比他自己還大的行李箱，令孩子看起來特別細小。"},{"en":"This image shows the heavy responsibility placed on a young student.","zh":"這個畫面顯示年幼學生承受的沉重責任。"},{"en":"The phrase helps readers feel the emotional weight of leaving home.","zh":"這個短語幫助讀者感受離家的情感重量。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"smile bravely","meaning":"勇敢地微笑","examples":[{"en":"The student smiled bravely while his parents tried not to cry.","zh":"那名學生勇敢地微笑，而他的父母努力不哭出來。"},{"en":"Smile bravely means smile even though one feels afraid, sad or nervous.","zh":"Smile bravely 指即使害怕、傷心或緊張，仍然微笑。"},{"en":"A child may smile bravely before boarding a plane alone.","zh":"孩子獨自登機前，可能會勇敢地微笑。"},{"en":"Smiling bravely can hide fear and comfort the people saying goodbye.","zh":"勇敢地微笑可以掩飾恐懼，也安慰正在道別的人。"},{"en":"This phrase shows courage mixed with sadness.","zh":"這個短語顯示勇氣中帶着悲傷。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"try not to cry","meaning":"努力不哭出來","examples":[{"en":"His parents tried not to cry at the airport.","zh":"他的父母在機場努力不哭出來。"},{"en":"Try not to cry means make an effort to hold back tears.","zh":"Try not to cry 指努力忍住眼淚。"},{"en":"Parents may try not to cry because they do not want their child to worry.","zh":"父母可能努力不哭出來，因為不想孩子擔心。"},{"en":"Saying goodbye at the airport can be painful even when the decision is hopeful.","zh":"即使這個決定充滿希望，在機場道別仍可能很痛。"},{"en":"This phrase shows controlled emotion.","zh":"這個短語顯示被控制住的情感。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"this quiet scene reflects","meaning":"這個安靜場面反映","examples":[{"en":"This quiet scene reflects a growing educational trend.","zh":"這個安靜場面反映了一個日益增長的教育趨勢。"},{"en":"This quiet scene reflects means this small moment shows a larger meaning or social pattern.","zh":"This quiet scene reflects 指這個小時刻顯示更大的意義或社會模式。"},{"en":"A child saying goodbye at the airport can reflect changes in family education choices.","zh":"孩子在機場道別，可以反映家庭教育選擇的轉變。"},{"en":"Quiet scenes are powerful because they show big issues through ordinary moments.","zh":"安靜場面之所以有力，是因為它們透過普通時刻呈現大議題。"},{"en":"This phrase links one image to a wider trend.","zh":"這個短語把一個畫面連接到更廣泛的趨勢。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"a growing educational trend","meaning":"日益增長的教育趨勢","examples":[{"en":"Overseas schooling has become a growing educational trend.","zh":"海外升學已成為一個日益增長的教育趨勢。"},{"en":"A growing educational trend is an education-related pattern that more people are following.","zh":"A growing educational trend 指越來越多人跟隨的教育相關模式。"},{"en":"More families choosing boarding schools abroad can be a growing educational trend.","zh":"越來越多家庭選擇海外寄宿學校，可以是一個日益增長的教育趨勢。"},{"en":"A growing educational trend may change how local schools plan their programmes.","zh":"日益增長的教育趨勢可能改變本地學校規劃課程的方式。"},{"en":"This phrase describes a change becoming more common over time.","zh":"這個短語描述一種隨時間變得更常見的變化。"}],"source":"2015 Q4.pdf","sourcePage":1},{"front":"against the background of","meaning":"在……背景下","examples":[{"en":"Against the background of intense academic competition, parents are considering overseas schooling.","zh":"在激烈學業競爭的背景下，父母正考慮海外升學。"},{"en":"Against the background of means because a wider situation exists around the issue.","zh":"Against the background of 指因為某個較大的情況存在於事件周圍。"},{"en":"Against the background of rising study pressure, some families look for other school systems.","zh":"在學習壓力上升的背景下，有些家庭尋找其他教育制度。"},{"en":"This phrase explains the setting that makes a decision understandable.","zh":"這個短語解釋令某個決定變得可以理解的背景。"},{"en":"It is useful in formal essays when linking causes to context.","zh":"在正式文章中把原因與背景連接起來時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"intense academic competition","meaning":"激烈的學業競爭","examples":[{"en":"Hong Kong students face intense academic competition.","zh":"香港學生面對激烈的學業競爭。"},{"en":"Intense academic competition means strong pressure to perform better than others in study.","zh":"Intense academic competition 指在學習上要比別人表現更好的強大壓力。"},{"en":"Students may feel intense academic competition when every test affects ranking.","zh":"當每次測驗都影響排名，學生可能感到激烈的學業競爭。"},{"en":"Intense academic competition can push students to work hard but also make them exhausted.","zh":"激烈的學業競爭可以推動學生努力，但也可能令他們疲憊。"},{"en":"This phrase describes pressure inside an education system.","zh":"這個短語描述教育制度內的壓力。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"considering overseas schooling","meaning":"考慮海外升學","examples":[{"en":"Many Hong Kong parents are considering overseas schooling.","zh":"許多香港父母正考慮海外升學。"},{"en":"Considering overseas schooling means seriously thinking about sending a child to study in another country.","zh":"Considering overseas schooling 指認真思考是否送孩子到另一個國家讀書。"},{"en":"Parents may consider overseas schooling when they worry about stress or limited subject choices.","zh":"當父母擔心壓力或科目選擇有限時，可能會考慮海外升學。"},{"en":"This decision requires money, planning and emotional preparation.","zh":"這個決定需要金錢、計劃和情感準備。"},{"en":"This phrase shows that families are weighing an important choice.","zh":"這個短語顯示家庭正在衡量一個重要選擇。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"gain broader opportunities","meaning":"獲得更廣闊的機會","examples":[{"en":"Parents hope their children can gain broader opportunities.","zh":"父母希望孩子能獲得更廣闊的機會。"},{"en":"Gain broader opportunities means get more chances for study, growth or future work.","zh":"Gain broader opportunities 指得到更多學習、成長或未來工作的機會。"},{"en":"Overseas schooling may help students gain broader opportunities through new subjects and networks.","zh":"海外升學可能透過新科目和人際網絡，幫助學生獲得更廣闊的機會。"},{"en":"Broader opportunities can include language learning, university choices and cultural experience.","zh":"更廣闊的機會可以包括語言學習、大學選擇和文化經驗。"},{"en":"This phrase explains one reason parents consider studying abroad.","zh":"這個短語解釋父母考慮海外升學的其中一個原因。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"develop independence","meaning":"培養獨立能力","examples":[{"en":"Overseas schooling may help children develop independence.","zh":"海外升學可能幫助孩子培養獨立能力。"},{"en":"Develop independence means learn to make decisions and care for oneself without constant help.","zh":"Develop independence 指學會自己作決定和照顧自己，而不是一直依賴幫助。"},{"en":"A student develops independence when she manages homework, meals and money herself.","zh":"當學生自己管理功課、膳食和金錢時，她就在培養獨立能力。"},{"en":"Living abroad can develop independence because parents are not nearby every day.","zh":"海外生活可以培養獨立能力，因為父母不是每天在身邊。"},{"en":"This phrase connects overseas study with personal growth.","zh":"這個短語把海外升學和個人成長連接起來。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"escape a system","meaning":"逃離一個制度","examples":[{"en":"Some parents hope their children can escape a system they regard as too narrow.","zh":"有些父母希望孩子能逃離一個他們視為過於狹窄的制度。"},{"en":"Escape a system means get away from a structure or set of rules that feels limiting.","zh":"Escape a system 指離開一個令人感到受限制的結構或規則。"},{"en":"A family may want to escape a system that focuses only on exam marks.","zh":"家庭可能想逃離一個只集中於考試分數的制度。"},{"en":"Students may feel freer when they leave a system that does not fit their interests.","zh":"當學生離開不配合自己興趣的制度時，可能會感到更自由。"},{"en":"This phrase suggests pressure and the wish for alternatives.","zh":"這個短語暗示壓力和尋找其他選擇的願望。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"regard as too narrow","meaning":"視為過於狹窄","examples":[{"en":"Some parents regard the local system as too narrow.","zh":"有些父母視本地制度為過於狹窄。"},{"en":"Regard as too narrow means see something as limited, restrictive or lacking variety.","zh":"Regard as too narrow 指認為某事有限、受限制或缺乏多樣性。"},{"en":"Parents may regard a curriculum as too narrow if it ignores art, sport and creativity.","zh":"如果課程忽視藝術、運動和創意，父母可能視它為過於狹窄。"},{"en":"A system can feel too narrow when it rewards only one kind of success.","zh":"當一個制度只獎賞一種成功，它就可能顯得過於狹窄。"},{"en":"This phrase shows a judgement about educational limits.","zh":"這個短語顯示對教育限制的判斷。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"this article examines","meaning":"本文探討","examples":[{"en":"This article examines two major reasons behind this phenomenon.","zh":"本文探討這個現象背後的兩個主要原因。"},{"en":"This article examines means the article studies, explains or discusses something carefully.","zh":"This article examines 指文章仔細研究、解釋或討論某事。"},{"en":"This article examines why more families choose overseas schooling.","zh":"本文探討為何越來越多家庭選擇海外升學。"},{"en":"Writers use this phrase to tell readers the focus of an essay.","zh":"作者用這個短語告訴讀者文章焦點。"},{"en":"This phrase is common in formal introductions.","zh":"這個短語常見於正式引言。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"major reasons behind","meaning":"……背後的主要原因","examples":[{"en":"The article examines the major reasons behind this phenomenon.","zh":"文章探討這個現象背後的主要原因。"},{"en":"Major reasons behind means the main causes that explain why something happens.","zh":"Major reasons behind 指解釋某事發生的主要成因。"},{"en":"Study pressure is one major reason behind the rise in overseas schooling.","zh":"學習壓力是海外升學增加背後的一個主要原因。"},{"en":"Understanding the reasons behind a trend helps people respond wisely.","zh":"理解趨勢背後的原因，能幫助人作出明智回應。"},{"en":"This phrase is useful when analysing causes.","zh":"分析原因時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"this phenomenon","meaning":"這個現象","examples":[{"en":"This phenomenon has affected both local schools and children.","zh":"這個現象影響了本地學校和孩子。"},{"en":"This phenomenon means this noticeable situation or trend.","zh":"This phenomenon 指這個值得注意的情況或趨勢。"},{"en":"The growing number of children studying abroad is the phenomenon being discussed.","zh":"越來越多孩子到海外讀書，就是正在討論的現象。"},{"en":"A phenomenon becomes important when it affects families, schools and society.","zh":"當一個現象影響家庭、學校和社會，它就變得重要。"},{"en":"This phrase helps avoid repeating the full description of a trend.","zh":"這個短語幫助避免重複完整描述某個趨勢。"}],"source":"2015 Q4.pdf","sourcePage":2},{"front":"considers its impact on","meaning":"考慮其對……的影響","examples":[{"en":"The article considers its impact on local schools and children.","zh":"文章考慮其對本地學校和孩子的影響。"},{"en":"Considers its impact on means thinks about how something affects people or places.","zh":"Considers its impact on 指思考某事如何影響人或地方。"},{"en":"A report may consider the impact of homework on students’ sleep.","zh":"報告可能考慮功課對學生睡眠的影響。"},{"en":"Considering impact helps readers see both benefits and problems.","zh":"考慮影響能幫助讀者看見好處和問題。"},{"en":"This phrase is useful in balanced analysis.","zh":"這個短語適合用於平衡分析。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"local schools","meaning":"本地學校","examples":[{"en":"The trend has a real impact on local schools.","zh":"這個趨勢對本地學校有實際影響。"},{"en":"Local schools are schools in the students’ own city or community.","zh":"Local schools 指學生自己城市或社區內的學校。"},{"en":"Local schools may lose students when families choose overseas education.","zh":"當家庭選擇海外教育，本地學校可能失去學生。"},{"en":"Strong local schools can reduce the pressure to look abroad.","zh":"強大的本地學校可以減少家庭向海外尋找選擇的壓力。"},{"en":"This phrase contrasts home education with foreign schooling.","zh":"這個短語把本地教育和海外教育作對比。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"the children who leave","meaning":"離開的孩子","examples":[{"en":"The article also considers the impact on the children who leave.","zh":"文章也考慮這個趨勢對離開的孩子的影響。"},{"en":"The children who leave are students who move away from home to study elsewhere.","zh":"The children who leave 指離開家到其他地方讀書的學生。"},{"en":"The children who leave may gain independence but also feel homesick.","zh":"離開的孩子可能得到獨立能力，但也可能思鄉。"},{"en":"Their experience matters because they carry the emotional cost of the decision.","zh":"他們的經歷很重要，因為他們承受這個決定的情感代價。"},{"en":"This phrase focuses attention on students, not only parents or schools.","zh":"這個短語把注意力放在學生身上，而不只是父母或學校。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"examination-oriented culture","meaning":"考試導向文化","examples":[{"en":"The first reason is the pressure of Hong Kong’s examination-oriented culture.","zh":"第一個原因是香港考試導向文化帶來的壓力。"},{"en":"Examination-oriented culture means a learning culture that focuses heavily on tests and marks.","zh":"Examination-oriented culture 指高度集中於考試和分數的學習文化。"},{"en":"Students in an examination-oriented culture may study mainly to score well.","zh":"在考試導向文化中，學生可能主要為了取得高分而學習。"},{"en":"Such a culture can build discipline but may reduce curiosity and joy.","zh":"這種文化可以建立紀律，但也可能減少好奇心和樂趣。"},{"en":"This phrase explains one source of pressure in education.","zh":"這個短語解釋教育壓力的一個來源。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"from…to…","meaning":"由……到……","examples":[{"en":"From primary-school dictations to public examinations, students face constant assessment.","zh":"由小學默書到公開考試，學生面對持續不斷的評核。"},{"en":"From…to… shows the full range between two points or examples.","zh":"From…to… 用來顯示兩個點或例子之間的整個範圍。"},{"en":"From homework to final exams, students may feel pressure at every stage.","zh":"由功課到期末考試，學生在每個階段都可能感到壓力。"},{"en":"This structure helps show that assessment happens throughout school life.","zh":"這個結構幫助顯示評核貫穿整個校園生活。"},{"en":"It is useful when describing a wide pattern.","zh":"描述廣泛模式時，這個結構很有用。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"primary-school dictations","meaning":"小學默書","examples":[{"en":"From primary-school dictations to public examinations, students are trained to perform.","zh":"由小學默書到公開考試，學生都被訓練去表現。"},{"en":"Primary-school dictations are spelling or writing tests given to young pupils.","zh":"Primary-school dictations 指給小學生做的串字或書寫測驗。"},{"en":"Primary-school dictations may make children feel pressure from an early age.","zh":"小學默書可能令孩子從小就感到壓力。"},{"en":"When even small tests matter too much, school can feel stressful.","zh":"當連小測也變得太重要，學校就可能令人緊張。"},{"en":"This phrase shows that assessment begins early.","zh":"這個短語顯示評核很早就開始。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"public examinations","meaning":"公開考試","examples":[{"en":"Hong Kong students prepare for public examinations.","zh":"香港學生為公開考試作準備。"},{"en":"Public examinations are major official exams taken by many students in the same education system.","zh":"Public examinations 指同一教育制度中許多學生參加的重要官方考試。"},{"en":"Public examinations can affect university choices and future pathways.","zh":"公開考試可以影響大學選擇和未來路徑。"},{"en":"Students may feel strong pressure when one public examination carries great weight.","zh":"當一次公開考試佔很大比重，學生可能感到強大壓力。"},{"en":"This phrase is central to discussions of school competition.","zh":"這個短語是討論學業競爭的核心。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"be trained to","meaning":"被訓練去……","examples":[{"en":"Students are trained to perform under relentless assessment.","zh":"學生被訓練去在持續不斷的評核下表現。"},{"en":"Be trained to means be taught or prepared to do something in a certain way.","zh":"Be trained to 指被教導或準備以某種方式做某事。"},{"en":"Students are trained to answer exam questions quickly and accurately.","zh":"學生被訓練去快速而準確地回答考試題目。"},{"en":"Training can be useful, but too much exam training may reduce creativity.","zh":"訓練可以有用，但太多考試訓練可能減少創意。"},{"en":"This phrase shows how a system shapes behaviour.","zh":"這個短語顯示制度如何塑造行為。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"perform under","meaning":"在……下表現","examples":[{"en":"Students are trained to perform under relentless assessment.","zh":"學生被訓練去在持續不斷的評核下表現。"},{"en":"Perform under means do well while facing a certain pressure or condition.","zh":"Perform under 指在某種壓力或條件下有好表現。"},{"en":"Athletes must perform under pressure during important competitions.","zh":"運動員必須在重要比賽壓力下表現。"},{"en":"Students may struggle to perform under constant tests and expectations.","zh":"學生可能難以在持續測驗和期望下表現。"},{"en":"This phrase connects achievement with the conditions surrounding it.","zh":"這個短語把成就和周圍條件連接起來。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"relentless assessment","meaning":"持續不斷的評核","examples":[{"en":"Students face relentless assessment from a young age.","zh":"學生從小就面對持續不斷的評核。"},{"en":"Relentless assessment means testing or judging that continues without much rest.","zh":"Relentless assessment 指幾乎沒有休息地持續測試或評價。"},{"en":"Weekly quizzes, dictations and exams can feel like relentless assessment.","zh":"每週小測、默書和考試可能令人覺得是持續不斷的評核。"},{"en":"Relentless assessment may make students tired even when they achieve good marks.","zh":"持續不斷的評核即使讓學生取得好分數，也可能令他們疲累。"},{"en":"This phrase describes pressure that does not easily stop.","zh":"這個短語描述不容易停止的壓力。"}],"source":"2015 Q4.pdf","sourcePage":3},{"front":"not that…","meaning":"這並不是說……","examples":[{"en":"Not that discipline is unimportant; rather, the problem is excessive focus on marks.","zh":"這並不是說紀律不重要；而是問題在於過度集中於分數。"},{"en":"Not that… means the writer is not denying one point, but wants to make a different point clear.","zh":"Not that… 指作者不是否定某一點，而是想清楚說明另一點。"},{"en":"Not that exams are useless; rather, they should not control all learning.","zh":"這並不是說考試沒有用；而是它們不應控制所有學習。"},{"en":"This phrase helps avoid misunderstanding in an argument.","zh":"這個短語有助避免論證中的誤解。"},{"en":"It is useful when giving a balanced view.","zh":"表達平衡觀點時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"discipline","meaning":"紀律","examples":[{"en":"Discipline is important, but curiosity should not be pushed aside.","zh":"紀律很重要，但好奇心不應被推到一旁。"},{"en":"Discipline means self-control and the ability to follow rules or keep working.","zh":"Discipline 指自我控制，以及遵守規則或持續努力的能力。"},{"en":"Students need discipline to revise regularly and meet deadlines.","zh":"學生需要紀律去定期溫習和按時完成任務。"},{"en":"Discipline becomes unhealthy if it leaves no room for curiosity or rest.","zh":"如果紀律完全不留空間給好奇心或休息，它就會變得不健康。"},{"en":"This word is important when discussing study habits.","zh":"討論學習習慣時，這個詞很重要。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"become so focused on","meaning":"變得過於集中於……","examples":[{"en":"Education can become so focused on marks that curiosity is pushed aside.","zh":"教育可能變得過於集中於分數，以致好奇心被推到一旁。"},{"en":"Become so focused on means pay so much attention to one thing that other things are ignored.","zh":"Become so focused on 指過分注意某一件事，以致忽略其他事情。"},{"en":"A school may become so focused on exam results that students stop enjoying learning.","zh":"學校可能變得過於集中於考試成績，以致學生不再享受學習。"},{"en":"Too much focus on marks can narrow what education means.","zh":"過分集中於分數會收窄教育的意義。"},{"en":"This phrase explains imbalance.","zh":"這個短語解釋不平衡狀態。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"marks","meaning":"分數","examples":[{"en":"Education should not focus only on marks.","zh":"教育不應只集中於分數。"},{"en":"Marks are scores or grades students receive for schoolwork or exams.","zh":"Marks 指學生在功課或考試中得到的分數或等級。"},{"en":"Good marks can open opportunities, but they do not show every ability.","zh":"好分數可以帶來機會，但不能顯示所有能力。"},{"en":"If students care only about marks, they may avoid creative risks.","zh":"如果學生只在意分數，他們可能會避免創意上的嘗試。"},{"en":"This word is central to exam-related pressure.","zh":"這個詞是考試壓力討論的核心。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"curiosity is pushed to the margins","meaning":"好奇心被推到邊緣","examples":[{"en":"Curiosity is pushed to the margins when education focuses only on marks.","zh":"當教育只集中於分數，好奇心就被推到邊緣。"},{"en":"Curiosity is pushed to the margins means the desire to ask questions becomes less important.","zh":"Curiosity is pushed to the margins 指提問和探索的慾望變得不重要。"},{"en":"When students memorise answers all day, curiosity may be pushed to the margins.","zh":"當學生整天背答案，好奇心可能被推到邊緣。"},{"en":"Education loses depth if curiosity is treated as a distraction.","zh":"如果好奇心被視為分心，教育就會失去深度。"},{"en":"This phrase shows how a valuable quality can be neglected.","zh":"這個短語顯示有價值的特質如何被忽略。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"fear that","meaning":"擔心","examples":[{"en":"Many parents fear that their children are becoming exhausted learners.","zh":"許多父母擔心孩子正變成疲憊的學習者。"},{"en":"Fear that means worry that something bad may be true or may happen.","zh":"Fear that 指擔心某件壞事可能是真的或可能發生。"},{"en":"Parents may fear that too many tests are damaging their child’s interest in learning.","zh":"父母可能擔心太多測驗正在損害孩子的學習興趣。"},{"en":"Fear can push families to search for different school systems.","zh":"擔心可以推動家庭尋找不同教育制度。"},{"en":"This phrase introduces concern and anxiety.","zh":"這個短語引出關注和焦慮。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"excellent test-takers","meaning":"出色的應試者","examples":[{"en":"Parents fear that their children are becoming excellent test-takers but exhausted learners.","zh":"父母擔心孩子正變成出色的應試者，卻是疲憊的學習者。"},{"en":"Excellent test-takers are students who are very good at exams and test techniques.","zh":"Excellent test-takers 指非常擅長考試和應試技巧的學生。"},{"en":"A student can be an excellent test-taker but still dislike learning.","zh":"學生可以是出色的應試者，但仍然不喜歡學習。"},{"en":"Schools may produce excellent test-takers if they train students only for marks.","zh":"如果學校只為分數訓練學生，就可能培養出出色的應試者。"},{"en":"This phrase questions whether exam success equals real education.","zh":"這個短語質疑考試成功是否等於真正教育。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"exhausted learners","meaning":"疲憊的學習者","examples":[{"en":"Students may become excellent test-takers but exhausted learners.","zh":"學生可能成為出色的應試者，卻也是疲憊的學習者。"},{"en":"Exhausted learners are students who are mentally or physically tired from too much study pressure.","zh":"Exhausted learners 指因過多學習壓力而身心疲累的學生。"},{"en":"Exhausted learners may get good marks but lose curiosity and joy.","zh":"疲憊的學習者可能取得好分數，但失去好奇心和樂趣。"},{"en":"Too many tests and tutorial classes can create exhausted learners.","zh":"太多測驗和補習班可以製造疲憊的學習者。"},{"en":"This phrase shows the hidden cost of academic pressure.","zh":"這個短語顯示學業壓力的隱藏代價。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"coursework","meaning":"課程習作","examples":[{"en":"Some overseas systems include coursework, projects, and a wider choice of subjects.","zh":"一些海外制度包括課程習作、專題和更廣泛的科目選擇。"},{"en":"Coursework means school assignments completed during a course, not only final exams.","zh":"Coursework 指在課程期間完成的學校作業，而不只是期末考試。"},{"en":"Coursework may include essays, research tasks, presentations or practical work.","zh":"課程習作可以包括文章、研究任務、匯報或實作。"},{"en":"Coursework can reduce pressure because students are assessed in different ways.","zh":"課程習作可以減少壓力，因為學生以不同方式被評核。"},{"en":"This word is useful when comparing education systems.","zh":"比較教育制度時，這個詞很有用。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"a wider choice of subjects","meaning":"更廣泛的科目選擇","examples":[{"en":"Overseas systems may offer a wider choice of subjects.","zh":"海外制度可能提供更廣泛的科目選擇。"},{"en":"A wider choice of subjects means more different courses for students to select.","zh":"A wider choice of subjects 指學生可以選擇更多不同課程。"},{"en":"Students may choose drama, design technology or environmental science.","zh":"學生可能選擇戲劇、設計與科技或環境科學。"},{"en":"A wider choice of subjects helps students develop interests beyond exam basics.","zh":"更廣泛的科目選擇幫助學生發展考試基本科目以外的興趣。"},{"en":"This phrase explains why some families find overseas schools attractive.","zh":"這個短語解釋為何有些家庭覺得海外學校吸引。"}],"source":"2015 Q4.pdf","sourcePage":4},{"front":"appear to offer","meaning":"似乎提供","examples":[{"en":"Overseas systems appear to offer a healthier balance.","zh":"海外制度似乎提供更健康的平衡。"},{"en":"Appear to offer means seem to provide something, based on what people see or believe.","zh":"Appear to offer 指根據人們看見或相信的情況，似乎提供某物。"},{"en":"Smaller classes appear to offer more personal attention.","zh":"小班教學似乎提供更多個人關注。"},{"en":"Overseas schools appear to offer more room for projects and discussion.","zh":"海外學校似乎提供更多專題和討論空間。"},{"en":"This phrase is careful because it describes an impression, not absolute proof.","zh":"這個短語較謹慎，因為它描述印象，而不是絕對證明。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"a healthier balance between","meaning":"……之間更健康的平衡","examples":[{"en":"Overseas systems may offer a healthier balance between achievement and personal growth.","zh":"海外制度可能在成就和個人成長之間提供更健康的平衡。"},{"en":"A healthier balance between two things means both are valued without one damaging the other.","zh":"A healthier balance between two things 指兩者都受到重視，而其中一方不會傷害另一方。"},{"en":"A school should keep a healthier balance between exam results and student well-being.","zh":"學校應在考試成績和學生身心健康之間保持更健康的平衡。"},{"en":"When achievement and personal growth are balanced, students can succeed without losing themselves.","zh":"當成就和個人成長取得平衡，學生可以成功而不失去自我。"},{"en":"This phrase is useful in education arguments.","zh":"這個短語適合用於教育論證。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"achievement","meaning":"成就","examples":[{"en":"Education should balance achievement and personal growth.","zh":"教育應平衡成就和個人成長。"},{"en":"Achievement means success gained through effort, skill or study.","zh":"Achievement 指透過努力、技能或學習取得的成功。"},{"en":"High marks can be one kind of achievement, but not the only one.","zh":"高分可以是一種成就，但不是唯一成就。"},{"en":"Achievement becomes more meaningful when students also grow as people.","zh":"當學生也在人格上成長，成就就更有意義。"},{"en":"This word is useful when discussing goals in education.","zh":"討論教育目標時，這個詞很有用。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"personal growth","meaning":"個人成長","examples":[{"en":"Overseas schooling may support personal growth.","zh":"海外升學可能支持個人成長。"},{"en":"Personal growth means becoming more mature, confident, independent or self-aware.","zh":"Personal growth 指變得更成熟、更自信、更獨立或更了解自己。"},{"en":"Managing daily life abroad can support a student’s personal growth.","zh":"在海外管理日常生活可以支持學生的個人成長。"},{"en":"Personal growth matters because education is not only about marks.","zh":"個人成長很重要，因為教育不只是分數。"},{"en":"This phrase connects learning with character development.","zh":"這個短語把學習和人格發展連接起來。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take a student who loves drama, environmental science, or design technology, for example.","zh":"以一名喜歡戲劇、環境科學或設計與科技的學生為例。"},{"en":"Take…for example means use a specific case to explain a general idea.","zh":"Take…for example 指用一個具體個案解釋一般想法。"},{"en":"Take a shy student who loves video editing, for example.","zh":"以一名喜歡剪片的害羞學生為例。"},{"en":"Writers use this phrase to make an abstract point easier to understand.","zh":"作者用這個短語令抽象重點更容易理解。"},{"en":"This phrase introduces a concrete illustration.","zh":"這個短語引出具體例子。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"environmental science","meaning":"環境科學","examples":[{"en":"A student may love environmental science.","zh":"學生可能喜歡環境科學。"},{"en":"Environmental science is the study of nature, pollution, climate and how humans affect the planet.","zh":"Environmental science 指研究自然、污染、氣候和人類如何影響地球的學科。"},{"en":"A student who loves environmental science may enjoy fieldwork and research projects.","zh":"喜歡環境科學的學生可能享受實地考察和研究專題。"},{"en":"This subject helps young people understand problems such as waste and climate change.","zh":"這個科目幫助年輕人理解浪費和氣候變化等問題。"},{"en":"This phrase names an academic interest beyond traditional exam subjects.","zh":"這個短語指出傳統考試科目以外的學術興趣。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"design technology","meaning":"設計與科技","examples":[{"en":"A student may love design technology.","zh":"學生可能喜歡設計與科技。"},{"en":"Design technology is a subject where students design, make and test useful products or solutions.","zh":"Design technology 指學生設計、製作和測試有用產品或方案的科目。"},{"en":"Students may use design technology to create models, apps or simple machines.","zh":"學生可能用設計與科技創作模型、應用程式或簡單機械。"},{"en":"This subject suits learners who enjoy solving problems with practical creativity.","zh":"這個科目適合喜歡用實用創意解決問題的學習者。"},{"en":"This phrase shows that education can include making, not only memorising.","zh":"這個短語顯示教育可以包括製作，而不只是背誦。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"be squeezed in","meaning":"被勉強塞進時間表","examples":[{"en":"These interests may be squeezed in after tutorial classes.","zh":"這些興趣可能被勉強塞進補習班之後的時間表。"},{"en":"Be squeezed in means be fitted into a busy schedule with very little space or time.","zh":"Be squeezed in 指在非常忙碌的時間表中勉強安排進去。"},{"en":"A student may squeeze music practice in after homework and revision.","zh":"學生可能在功課和溫習後勉強塞進音樂練習。"},{"en":"When interests are squeezed in, they may feel less important than exams.","zh":"當興趣被勉強塞進時間表，它們可能顯得不如考試重要。"},{"en":"This phrase shows how busy schedules limit personal development.","zh":"這個短語顯示繁忙時間表如何限制個人發展。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"tutorial classes","meaning":"補習班","examples":[{"en":"Students may have to fit their interests in after tutorial classes.","zh":"學生可能要在補習班之後才安排自己的興趣。"},{"en":"Tutorial classes are extra lessons outside normal school, often used for exam preparation.","zh":"Tutorial classes 指正常上課以外的額外課堂，常用於準備考試。"},{"en":"Many students attend tutorial classes after school or at weekends.","zh":"許多學生在放學後或週末上補習班。"},{"en":"Too many tutorial classes can leave little time for rest or hobbies.","zh":"太多補習班可能令學生很少有時間休息或培養興趣。"},{"en":"This phrase is common in discussions of academic pressure.","zh":"這個短語常見於學業壓力討論。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"In some overseas schools, by contrast, these interests can become proper pathways.","zh":"相比之下，在一些海外學校，這些興趣可以成為正式路徑。"},{"en":"By contrast means compared with the previous situation, this is different.","zh":"By contrast 指與前面的情況相比，這裏有所不同。"},{"en":"Local schools may focus on exams; by contrast, some overseas schools include more projects.","zh":"本地學校可能集中於考試；相比之下，一些海外學校包括更多專題。"},{"en":"Writers use this phrase to show a clear difference.","zh":"作者用這個短語顯示清楚差異。"},{"en":"This phrase helps compare education systems.","zh":"這個短語幫助比較教育制度。"}],"source":"2015 Q4.pdf","sourcePage":5},{"front":"proper academic pathways","meaning":"正式的學術路徑","examples":[{"en":"Drama or design technology can become proper academic pathways.","zh":"戲劇或設計與科技可以成為正式的學術路徑。"},{"en":"Proper academic pathways are recognised routes of study that can lead to further learning or careers.","zh":"Proper academic pathways 指被認可、可通往進一步學習或職業的學習路線。"},{"en":"A student who loves drama may follow a proper academic pathway in theatre studies.","zh":"喜歡戲劇的學生可能走上戲劇研究的正式學術路徑。"},{"en":"When interests become academic pathways, students feel their talents are respected.","zh":"當興趣成為學術路徑，學生會感到自己的才能被尊重。"},{"en":"This phrase shows how schools can value different abilities.","zh":"這個短語顯示學校如何重視不同能力。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"it is therefore easy to see why","meaning":"因此不難理解為甚麼","examples":[{"en":"It is therefore easy to see why parents regard foreign schooling as attractive.","zh":"因此不難理解為甚麼父母視海外教育為吸引。"},{"en":"It is therefore easy to see why means the reason has become understandable after the explanation.","zh":"It is therefore easy to see why 指經過解釋後，原因變得可以理解。"},{"en":"If local pressure is high, it is easy to see why families look abroad.","zh":"如果本地壓力很大，就不難理解為甚麼家庭向海外尋找選擇。"},{"en":"Writers use this phrase after giving evidence or reasons.","zh":"作者在提出證據或原因後會使用這個短語。"},{"en":"This phrase helps connect explanation with conclusion.","zh":"這個短語幫助把解釋和結論連接起來。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"foreign schooling","meaning":"海外教育","examples":[{"en":"Parents may regard foreign schooling as a way to protect enthusiasm.","zh":"父母可能視海外教育為保護學習熱情的方法。"},{"en":"Foreign schooling means education in another country.","zh":"Foreign schooling 指在另一個國家接受教育。"},{"en":"Foreign schooling may expose students to new subjects, cultures and teaching methods.","zh":"海外教育可能讓學生接觸新科目、文化和教學方法。"},{"en":"Some families choose foreign schooling because they want broader opportunities.","zh":"有些家庭選擇海外教育，因為他們想要更廣闊的機會。"},{"en":"This phrase is another way to describe overseas education.","zh":"這個短語是描述海外升學的另一種說法。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"a way to protect","meaning":"保護……的方法","examples":[{"en":"Parents see foreign schooling as a way to protect both results and enthusiasm.","zh":"父母視海外教育為保護成績和熱情的方法。"},{"en":"A way to protect something means a method for keeping something safe or healthy.","zh":"A way to protect something 指使某物保持安全或健康的方法。"},{"en":"Rest days are a way to protect students from burnout.","zh":"休息日是保護學生免於過度疲勞的方法。"},{"en":"Parents may look for a way to protect curiosity while keeping academic progress.","zh":"父母可能尋找一種既保持學業進步又保護好奇心的方法。"},{"en":"This phrase explains the purpose behind a choice.","zh":"這個短語解釋選擇背後的目的。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"results and enthusiasm","meaning":"成績和熱情","examples":[{"en":"Parents hope to protect both results and enthusiasm.","zh":"父母希望同時保護成績和熱情。"},{"en":"Results and enthusiasm mean academic performance and interest in learning.","zh":"Results and enthusiasm 指學業表現和學習興趣。"},{"en":"A good school helps students achieve results without losing enthusiasm.","zh":"好學校幫助學生取得成績，同時不失去熱情。"},{"en":"If students focus only on results, their enthusiasm may fade.","zh":"如果學生只集中於成績，他們的熱情可能會消退。"},{"en":"This phrase shows the balance parents want.","zh":"這個短語顯示父母想要的平衡。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"the desire for","meaning":"對……的渴望","examples":[{"en":"Another reason is the desire for global exposure.","zh":"另一個原因是對國際視野的渴望。"},{"en":"The desire for something means a strong wish to have or experience it.","zh":"The desire for something 指強烈希望擁有或經歷某事。"},{"en":"The desire for independence may lead students to study abroad.","zh":"對獨立的渴望可能令學生想出國讀書。"},{"en":"Parents’ desire for broader opportunities can shape education choices.","zh":"父母對更廣闊機會的渴望可以影響教育選擇。"},{"en":"This phrase introduces a motivation.","zh":"這個短語引出一種動機。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"global exposure","meaning":"國際視野；國際接觸","examples":[{"en":"Many parents want their children to gain global exposure.","zh":"許多父母希望孩子獲得國際視野。"},{"en":"Global exposure means contact with different countries, cultures, languages and ways of thinking.","zh":"Global exposure 指接觸不同國家、文化、語言和思考方式。"},{"en":"Students gain global exposure when they study with classmates from many backgrounds.","zh":"當學生與來自不同背景的同學一起學習，他們就獲得國際接觸。"},{"en":"Global exposure can make young people more open-minded and adaptable.","zh":"國際視野可以令年輕人更思想開明和適應力更強。"},{"en":"This phrase explains one attraction of overseas schooling.","zh":"這個短語解釋海外升學的一個吸引之處。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"outward-looking","meaning":"具國際視野的","examples":[{"en":"Families are becoming more outward-looking.","zh":"家庭正變得更具國際視野。"},{"en":"Outward-looking means interested in the wider world beyond one’s own place.","zh":"Outward-looking 指關心自己所在地以外更廣闊的世界。"},{"en":"Outward-looking families may compare different education systems before deciding.","zh":"具國際視野的家庭可能在決定前比較不同教育制度。"},{"en":"An outward-looking student wants to understand other cultures and viewpoints.","zh":"具國際視野的學生想了解其他文化和觀點。"},{"en":"This word describes an international mindset.","zh":"這個詞描述一種國際化心態。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"master English","meaning":"掌握英語","examples":[{"en":"Parents want their children to master English.","zh":"父母希望孩子掌握英語。"},{"en":"Master English means become very good at using English in speaking, reading and writing.","zh":"Master English 指在說、讀和寫方面非常熟練地使用英語。"},{"en":"Students may master English faster when they use it every day at school.","zh":"當學生每天在學校使用英語，他們可能更快掌握英語。"},{"en":"Mastering English can help students enter foreign universities more smoothly.","zh":"掌握英語可以幫助學生更順利入讀外國大學。"},{"en":"This phrase shows a practical goal of overseas education.","zh":"這個短語顯示海外教育的一個實際目標。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"understand different cultures","meaning":"了解不同文化","examples":[{"en":"Parents want their children to understand different cultures.","zh":"父母希望孩子了解不同文化。"},{"en":"Understand different cultures means learn how people from other places live, think and behave.","zh":"Understand different cultures 指學習其他地方的人如何生活、思考和行動。"},{"en":"Students understand different cultures when they share classes and meals with international friends.","zh":"當學生與國際朋友一起上課和用餐，他們會了解不同文化。"},{"en":"Understanding cultures can reduce quick judgement and misunderstanding.","zh":"了解文化可以減少倉促判斷和誤解。"},{"en":"This phrase connects education with social learning.","zh":"這個短語把教育和社交學習連接起來。"}],"source":"2015 Q4.pdf","sourcePage":6},{"front":"prepare for university life abroad","meaning":"為海外大學生活作準備","examples":[{"en":"Overseas schooling can prepare students for university life abroad.","zh":"海外升學可以為學生的海外大學生活作準備。"},{"en":"Prepare for university life abroad means help students get ready to study and live at a foreign university.","zh":"Prepare for university life abroad 指幫助學生準備在外國大學學習和生活。"},{"en":"Boarding school may prepare students for university life abroad by teaching independence.","zh":"寄宿學校可以透過培養獨立能力，為海外大學生活作準備。"},{"en":"Students who know the teaching style may feel less shocked at university.","zh":"熟悉教學模式的學生上大學時可能較少感到震驚。"},{"en":"This phrase explains a long-term benefit of overseas schooling.","zh":"這個短語解釋海外升學的長遠好處。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"not just about","meaning":"不只是關於","examples":[{"en":"Education is not just about passing examinations.","zh":"教育不只是關於通過考試。"},{"en":"Not just about means something has more meaning than one simple purpose.","zh":"Not just about 指某事不只有一個簡單目的，而有更多意義。"},{"en":"School is not just about marks; it is also about learning how to live with others.","zh":"學校不只是關於分數，也關於學會與人相處。"},{"en":"This phrase moves from a narrow view to a broader view.","zh":"這個短語把狹窄看法推向更廣闊看法。"},{"en":"It is useful when explaining deeper educational values.","zh":"解釋更深層教育價值時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"passing examinations","meaning":"通過考試","examples":[{"en":"Education is not just about passing examinations.","zh":"教育不只是關於通過考試。"},{"en":"Passing examinations means getting good enough results to succeed in exams.","zh":"Passing examinations 指取得足夠好的成績以考試合格或成功。"},{"en":"Passing examinations is important, but it cannot replace curiosity and life skills.","zh":"通過考試很重要，但不能取代好奇心和生活技能。"},{"en":"Students may pass examinations without learning how to think independently.","zh":"學生可能通過考試，卻沒有學會獨立思考。"},{"en":"This phrase represents a narrow goal if used alone.","zh":"如果單獨使用，這個短語代表一個狹窄目標。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"learn how to think","meaning":"學會思考","examples":[{"en":"Education should teach children how to think, speak, and live with others.","zh":"教育應教孩子如何思考、說話和與人共同生活。"},{"en":"Learn how to think means develop the ability to question, reason and make judgement.","zh":"Learn how to think 指培養提問、推理和判斷的能力。"},{"en":"Students learn how to think when teachers ask them to explain their answers.","zh":"當老師要求學生解釋答案，學生就在學會思考。"},{"en":"Overseas classes may help students think through debate and discussion.","zh":"海外課堂可能透過辯論和討論幫助學生思考。"},{"en":"This phrase focuses on understanding, not memorisation alone.","zh":"這個短語集中於理解，而不只是背誦。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"live among people","meaning":"與人共同生活","examples":[{"en":"Students learn to live among people whose assumptions are different from their own.","zh":"學生學會與想法和自己不同的人共同生活。"},{"en":"Live among people means share daily life with others in the same community or place.","zh":"Live among people 指在同一社區或地方與他人一起過日常生活。"},{"en":"A student abroad may live among people with different languages and habits.","zh":"海外學生可能與語言和習慣不同的人共同生活。"},{"en":"Living among different people teaches patience, respect and communication.","zh":"與不同的人共同生活會教人耐性、尊重和溝通。"},{"en":"This phrase connects education with social experience.","zh":"這個短語把教育和社交經驗連接起來。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"assumptions are different from","meaning":"想法與……不同","examples":[{"en":"Students meet people whose assumptions are different from their own.","zh":"學生遇到想法與自己不同的人。"},{"en":"Assumptions are different from means people have different beliefs about what is normal or true.","zh":"Assumptions are different from 指人們對甚麼是正常或真實有不同信念。"},{"en":"A Hong Kong student may meet classmates whose assumptions about success are different from theirs.","zh":"香港學生可能遇到對成功的想法與自己不同的同學。"},{"en":"Different assumptions can create misunderstanding but also deeper learning.","zh":"不同想法可能造成誤解，但也帶來更深入學習。"},{"en":"This phrase helps explain cultural difference.","zh":"這個短語幫助解釋文化差異。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"a teenager studying in","meaning":"在……讀書的青少年","examples":[{"en":"A teenager studying in Canada, Britain, or Australia may become more independent.","zh":"在加拿大、英國或澳洲讀書的青少年可能變得更獨立。"},{"en":"A teenager studying in a place is a young person attending school there.","zh":"A teenager studying in a place 指在某地上學的年輕人。"},{"en":"A teenager studying in Australia may learn to manage homework and daily chores alone.","zh":"在澳洲讀書的青少年可能學會自己管理功課和日常家務。"},{"en":"Studying in another country can change a teenager’s habits and confidence.","zh":"到另一個國家讀書可以改變青少年的習慣和信心。"},{"en":"This phrase introduces a concrete student example.","zh":"這個短語引出具體學生例子。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"debate in class","meaning":"在課堂上辯論","examples":[{"en":"A student abroad may have to debate in class.","zh":"海外學生可能需要在課堂上辯論。"},{"en":"Debate in class means discuss and defend ideas with classmates during lessons.","zh":"Debate in class 指在課堂中與同學討論並捍衛想法。"},{"en":"Students debate in class when they compare different views on a social issue.","zh":"當學生比較對社會議題的不同看法時，就是在課堂上辯論。"},{"en":"Debating in class helps students speak clearly and think critically.","zh":"在課堂上辯論幫助學生清楚表達和批判思考。"},{"en":"This phrase describes active classroom participation.","zh":"這個短語描述主動課堂參與。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"cook simple meals","meaning":"煮簡單飯菜","examples":[{"en":"A student abroad may need to cook simple meals.","zh":"海外學生可能需要煮簡單飯菜。"},{"en":"Cook simple meals means prepare basic food for oneself.","zh":"Cook simple meals 指為自己準備基本食物。"},{"en":"A student may cook simple meals such as noodles, eggs or rice.","zh":"學生可能煮麵、雞蛋或飯等簡單飯菜。"},{"en":"Cooking simple meals teaches independence because students cannot rely on parents every day.","zh":"煮簡單飯菜能培養獨立，因為學生不能每天依賴父母。"},{"en":"This phrase shows a practical life skill.","zh":"這個短語顯示一項實用生活技能。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"manage pocket money","meaning":"管理零用錢","examples":[{"en":"A student abroad may learn to manage pocket money.","zh":"海外學生可能學會管理零用錢。"},{"en":"Manage pocket money means plan how to spend and save a small personal budget.","zh":"Manage pocket money 指計劃如何花費和儲起少量個人預算。"},{"en":"Students manage pocket money by deciding how much to spend on food and transport.","zh":"學生透過決定食物和交通花費來管理零用錢。"},{"en":"Poor money management can make life abroad stressful.","zh":"金錢管理不好會令海外生活充滿壓力。"},{"en":"This phrase connects independence with daily responsibility.","zh":"這個短語把獨立和日常責任連接起來。"}],"source":"2015 Q4.pdf","sourcePage":7},{"front":"solve problems","meaning":"解決問題","examples":[{"en":"A student abroad may have to solve problems without parents’ help.","zh":"海外學生可能需要在沒有父母幫助下解決問題。"},{"en":"Solve problems means find answers or practical ways to deal with difficulties.","zh":"Solve problems 指找出答案或實際方法去處理困難。"},{"en":"A student may solve problems such as missing a bus or misunderstanding homework.","zh":"學生可能要解決錯過巴士或誤解功課等問題。"},{"en":"Solving problems alone can build confidence over time.","zh":"獨自解決問題可以隨時間建立信心。"},{"en":"This phrase shows an important life skill.","zh":"這個短語顯示重要生活技能。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"without immediately asking","meaning":"不立即請求……","examples":[{"en":"Students may solve problems without immediately asking parents for help.","zh":"學生可能不立即向父母求助，而是自己解決問題。"},{"en":"Without immediately asking means not requesting help at once before trying to think.","zh":"Without immediately asking 指在嘗試思考前，不立刻請求幫助。"},{"en":"A student may check a map without immediately asking an adult for directions.","zh":"學生可能先查看地圖，而不是立即向成年人問路。"},{"en":"Waiting before asking for help can develop independence, but help is still available when needed.","zh":"不立刻求助可以培養獨立，但需要時仍然可以尋求幫助。"},{"en":"This phrase shows a step toward self-reliance.","zh":"這個短語顯示走向自立的一步。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"make students more confident and adaptable","meaning":"令學生更自信和適應力更強","examples":[{"en":"These experiences can make students more confident and adaptable.","zh":"這些經歷可以令學生更自信和適應力更強。"},{"en":"Make students more confident and adaptable means help them believe in themselves and adjust to new situations.","zh":"Make students more confident and adaptable 指幫助學生相信自己並適應新情況。"},{"en":"Living abroad can make students more confident because they handle daily problems themselves.","zh":"海外生活可以令學生更自信，因為他們自己處理日常問題。"},{"en":"Meeting different cultures can make students more adaptable.","zh":"接觸不同文化可以令學生適應力更強。"},{"en":"This phrase explains a positive effect of overseas study.","zh":"這個短語解釋海外升學的正面影響。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"adaptable","meaning":"適應力強","examples":[{"en":"Overseas experiences can make students more adaptable.","zh":"海外經歷可以令學生適應力更強。"},{"en":"Adaptable means able to adjust to new situations, places or people.","zh":"Adaptable 指能適應新情況、新地方或新人的。"},{"en":"An adaptable student can study with different classmates and teaching styles.","zh":"適應力強的學生能配合不同同學和教學模式學習。"},{"en":"Students become adaptable when they learn to stay calm during change.","zh":"當學生學會在轉變中保持冷靜，他們就變得適應力強。"},{"en":"This word is useful when discussing global education.","zh":"討論國際教育時，這個詞很有用。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, overseas schooling may help students enter foreign universities more smoothly.","zh":"此外，海外升學可能幫助學生更順利入讀外國大學。"},{"en":"Moreover means in addition, and introduces another important point.","zh":"Moreover 指此外，用來引出另一個重要重點。"},{"en":"Overseas schooling builds independence; moreover, it can prepare students for university abroad.","zh":"海外升學建立獨立能力；此外，它可以為海外大學作準備。"},{"en":"Writers use moreover to add support to an argument.","zh":"作者用 moreover 為論點加入支持。"},{"en":"This word helps organise formal essays.","zh":"這個詞幫助組織正式文章。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"enter foreign universities","meaning":"入讀外國大學","examples":[{"en":"Overseas schooling may help students enter foreign universities.","zh":"海外升學可能幫助學生入讀外國大學。"},{"en":"Enter foreign universities means gain admission to universities in other countries.","zh":"Enter foreign universities 指獲得其他國家大學錄取。"},{"en":"Students may enter foreign universities more easily if they understand the application system.","zh":"如果學生了解申請制度，可能更容易入讀外國大學。"},{"en":"Overseas schooling can make the transition to foreign universities less difficult.","zh":"海外升學可以令過渡到外國大學較不困難。"},{"en":"This phrase describes a common long-term education goal.","zh":"這個短語描述常見的長遠教育目標。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"more smoothly","meaning":"更順利地","examples":[{"en":"Students may enter foreign universities more smoothly after overseas schooling.","zh":"海外升學後，學生可能更順利地入讀外國大學。"},{"en":"More smoothly means with fewer difficulties, delays or shocks.","zh":"More smoothly 指困難、延誤或衝擊較少。"},{"en":"A student may adapt more smoothly if she already knows the teaching style.","zh":"如果學生已熟悉教學模式，她可能更順利地適應。"},{"en":"Preparation helps major changes happen more smoothly.","zh":"準備能幫助重大轉變更順利地發生。"},{"en":"This phrase shows an easier transition.","zh":"這個短語顯示較容易的過渡。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"be used to","meaning":"習慣","examples":[{"en":"They are already used to the teaching style and campus culture.","zh":"他們已經習慣當地的教學模式和校園文化。"},{"en":"Be used to means be familiar with something and no longer find it strange.","zh":"Be used to 指熟悉某事，並不再覺得陌生。"},{"en":"Students may be used to speaking in class after studying overseas.","zh":"海外讀書後，學生可能習慣在課堂上發言。"},{"en":"Being used to a new system can reduce fear and confusion.","zh":"習慣新制度可以減少恐懼和困惑。"},{"en":"This phrase describes adjustment through experience.","zh":"這個短語描述透過經驗而適應。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"teaching style","meaning":"教學模式","examples":[{"en":"Students may become used to the teaching style overseas.","zh":"學生可能會習慣海外的教學模式。"},{"en":"Teaching style means the way teachers organise lessons and help students learn.","zh":"Teaching style 指老師組織課堂和幫助學生學習的方式。"},{"en":"A teaching style may include discussion, projects, lectures or group work.","zh":"教學模式可以包括討論、專題、講課或小組活動。"},{"en":"Students need time to adjust when the teaching style is different from home.","zh":"當教學模式與家鄉不同，學生需要時間適應。"},{"en":"This phrase is useful when comparing schools.","zh":"比較學校時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"campus culture","meaning":"校園文化","examples":[{"en":"Students may become used to campus culture before university.","zh":"學生可能在大學前已習慣校園文化。"},{"en":"Campus culture means the habits, values and social life of a school or university.","zh":"Campus culture 指學校或大學的習慣、價值觀和社交生活。"},{"en":"Campus culture includes clubs, classroom behaviour and how students talk to teachers.","zh":"校園文化包括學會、課堂行為和學生如何與老師交談。"},{"en":"Understanding campus culture helps students feel less like outsiders.","zh":"理解校園文化幫助學生較少覺得自己像外人。"},{"en":"This phrase connects study with daily school life.","zh":"這個短語把學習和日常校園生活連接起來。"}],"source":"2015 Q4.pdf","sourcePage":8},{"front":"for such families","meaning":"對這類家庭而言","examples":[{"en":"For such families, sending a child abroad is an investment in mobility.","zh":"對這類家庭而言，送孩子到海外是對流動力的投資。"},{"en":"For such families means for families with the attitudes or needs just described.","zh":"For such families 指對剛才描述的那類有相似想法或需要的家庭而言。"},{"en":"For such families, overseas schooling is about future choices, not only school ranking.","zh":"對這類家庭而言，海外升學關乎未來選擇，而不只是學校排名。"},{"en":"This phrase narrows the discussion to a particular group.","zh":"這個短語把討論收窄到某一類群體。"},{"en":"It helps connect general analysis with a specific type of family.","zh":"它幫助把一般分析連接到特定家庭類型。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"sending a child abroad","meaning":"送孩子到海外","examples":[{"en":"Sending a child abroad is not simply an escape from Hong Kong.","zh":"送孩子到海外不只是逃離香港。"},{"en":"Sending a child abroad means arranging for a child to live and study in another country.","zh":"Sending a child abroad 指安排孩子到另一個國家生活和讀書。"},{"en":"Sending a child abroad requires trust, money and emotional readiness.","zh":"送孩子到海外需要信任、金錢和情感準備。"},{"en":"Families may send a child abroad to seek wider learning experiences.","zh":"家庭可能送孩子到海外，以尋求更廣闊的學習經歷。"},{"en":"This phrase describes a major family decision.","zh":"這個短語描述重大的家庭決定。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"not so much…as…","meaning":"與其說是……不如說是……","examples":[{"en":"Sending a child abroad is not so much an escape from Hong Kong as an investment in mobility.","zh":"送孩子到海外與其說是逃離香港，不如說是對流動力的投資。"},{"en":"Not so much…as… means one description is less accurate than another.","zh":"Not so much…as… 指一個描述不如另一個描述準確。"},{"en":"Overseas schooling is not so much a holiday as a serious life change.","zh":"海外升學與其說是假期，不如說是嚴肅的人生轉變。"},{"en":"This structure helps correct a simple interpretation with a deeper one.","zh":"這個結構幫助用更深解釋修正簡單理解。"},{"en":"It is useful in formal analysis.","zh":"它適合用於正式分析。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"an escape from Hong Kong","meaning":"逃離香港","examples":[{"en":"Some families do not see overseas schooling as an escape from Hong Kong.","zh":"有些家庭不把海外升學視為逃離香港。"},{"en":"An escape from Hong Kong means leaving Hong Kong to get away from pressure or limits.","zh":"An escape from Hong Kong 指離開香港以避開壓力或限制。"},{"en":"Some parents may see overseas schooling as opportunity rather than escape.","zh":"有些父母可能把海外升學視為機會，而不是逃離。"},{"en":"The phrase can sound negative if it suggests running away from local problems.","zh":"如果這個短語暗示逃避本地問題，它可能帶有負面意味。"},{"en":"This phrase helps discuss different motives for studying abroad.","zh":"這個短語幫助討論海外升學的不同動機。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"an investment in mobility","meaning":"對流動力的投資","examples":[{"en":"For many families, overseas schooling is an investment in mobility.","zh":"對許多家庭而言，海外升學是對流動力的投資。"},{"en":"An investment in mobility means spending resources now to create more future choices across places.","zh":"An investment in mobility 指現在投入資源，以創造未來跨地域選擇。"},{"en":"Learning English and adapting to foreign schools can be an investment in mobility.","zh":"學習英語和適應外國學校可以是對流動力的投資。"},{"en":"Families may hope their children can study, work or live in more than one country.","zh":"家庭可能希望孩子將來能在不止一個國家學習、工作或生活。"},{"en":"This phrase connects education with future flexibility.","zh":"這個短語把教育和未來彈性連接起來。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"this trend has a real impact on","meaning":"這個趨勢對……有實際影響","examples":[{"en":"This trend has a real impact on local schools.","zh":"這個趨勢對本地學校有實際影響。"},{"en":"This trend has a real impact on means it produces noticeable effects, not just discussion.","zh":"This trend has a real impact on 指它產生可見影響，而不只是引起討論。"},{"en":"Student outflow has a real impact on schools when class sizes shrink.","zh":"當班級人數減少，學生外流就對學校有實際影響。"},{"en":"A trend becomes serious when it changes resources, programmes and communities.","zh":"當趨勢改變資源、課程和社群，它就變得嚴重。"},{"en":"This phrase stresses practical consequences.","zh":"這個短語強調實際後果。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"enrolment numbers","meaning":"入學人數","examples":[{"en":"Schools may lose enrolment numbers when more students leave.","zh":"當更多學生離開，學校可能失去入學人數。"},{"en":"Enrolment numbers are the number of students registered in a school or course.","zh":"Enrolment numbers 指在學校或課程中註冊的學生數目。"},{"en":"Falling enrolment numbers can affect funding and subject choices.","zh":"入學人數下降可能影響資金和科目選擇。"},{"en":"Schools watch enrolment numbers because they show whether families are staying.","zh":"學校留意入學人數，因為它顯示家庭是否留下。"},{"en":"This phrase is important in education planning.","zh":"這個短語在教育規劃中很重要。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"diversity of talent","meaning":"人才多樣性","examples":[{"en":"Schools may lose diversity of talent as students leave.","zh":"隨着學生離開，學校可能失去人才多樣性。"},{"en":"Diversity of talent means having students with many different abilities and strengths.","zh":"Diversity of talent 指擁有具備不同能力和強項的學生。"},{"en":"A school has diversity of talent when it has strong musicians, athletes, debaters and artists.","zh":"當學校有優秀音樂人、運動員、辯論員和藝術家，就有人才多樣性。"},{"en":"Losing talented students can make school life less rich.","zh":"失去有才華的學生可能令校園生活不再那麼豐富。"},{"en":"This phrase shows that student value is not only about numbers.","zh":"這個短語顯示學生價值不只是數量。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"Schools may lose not only enrolment numbers but also diversity of talent.","zh":"學校可能不但失去入學人數，而且失去人才多樣性。"},{"en":"Not only…but also… adds a second important point to the first.","zh":"Not only…but also… 在第一點之外加入第二個重要重點。"},{"en":"Overseas study affects not only families but also local schools.","zh":"海外升學不但影響家庭，而且影響本地學校。"},{"en":"This structure helps show that a problem has more than one effect.","zh":"這個結構幫助顯示問題有多於一個影響。"},{"en":"It is useful for building stronger arguments.","zh":"它適合用來建立更有力的論點。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"might have led","meaning":"原本可能帶領","examples":[{"en":"A student who might have led the debate team may suddenly leave.","zh":"一名原本可能帶領辯論隊的學生可能突然離開。"},{"en":"Might have led means could possibly have guided or been in charge of something, but did not.","zh":"Might have led 指原本可能引導或負責某事，但最後沒有發生。"},{"en":"A talented student might have led the orchestra if she had stayed.","zh":"如果一位有才華的學生留下，她原本可能帶領管弦樂團。"},{"en":"When students leave, schools lose contributions they might have made.","zh":"當學生離開，學校失去他們原本可能作出的貢獻。"},{"en":"This phrase shows a lost possibility.","zh":"這個短語顯示失去的可能性。"}],"source":"2015 Q4.pdf","sourcePage":9},{"front":"debate team","meaning":"辯論隊","examples":[{"en":"A talented student might have led the debate team.","zh":"一位有才華的學生原本可能帶領辯論隊。"},{"en":"A debate team is a group of students who practise arguing ideas in a formal way.","zh":"Debate team 指練習以正式方式辯論想法的一組學生。"},{"en":"A strong debate team helps students think quickly and speak clearly.","zh":"強大的辯論隊幫助學生快速思考和清楚表達。"},{"en":"If a skilled speaker leaves, the debate team may lose confidence and leadership.","zh":"如果熟練講者離開，辯論隊可能失去信心和領導力。"},{"en":"This phrase represents one area of school talent.","zh":"這個短語代表學校才能的一個範疇。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"strengthen the orchestra","meaning":"加強管弦樂團實力","examples":[{"en":"A student might have strengthened the orchestra.","zh":"一名學生原本可能加強管弦樂團實力。"},{"en":"Strengthen the orchestra means make the school music group better or more complete.","zh":"Strengthen the orchestra 指令學校音樂團隊變得更好或更完整。"},{"en":"A skilled violinist can strengthen the orchestra during concerts.","zh":"熟練小提琴手可以在音樂會中加強管弦樂團實力。"},{"en":"When musical students leave, the orchestra may have fewer strong players.","zh":"當有音樂才能的學生離開，管弦樂團可能少了強力成員。"},{"en":"This phrase shows how one student can improve a whole group.","zh":"這個短語顯示一名學生如何改善整個團隊。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"raise the standard of","meaning":"提高……的水平","examples":[{"en":"A student might have raised the standard of classroom discussion.","zh":"一名學生原本可能提高課堂討論的水平。"},{"en":"Raise the standard of means improve the quality of something.","zh":"Raise the standard of 指改善某事的質素。"},{"en":"Thoughtful questions can raise the standard of a class discussion.","zh":"有思考深度的問題可以提高課堂討論的水平。"},{"en":"Talented students raise the standard of learning when they challenge classmates to think deeper.","zh":"有才華的學生提出挑戰時，可以提高整體學習水平。"},{"en":"This phrase connects individual contribution with group improvement.","zh":"這個短語把個人貢獻和群體進步連接起來。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"classroom discussion","meaning":"課堂討論","examples":[{"en":"Some students help raise the standard of classroom discussion.","zh":"有些學生幫助提高課堂討論的水平。"},{"en":"Classroom discussion means students and teachers exchange ideas during a lesson.","zh":"Classroom discussion 指學生和老師在課堂中交流想法。"},{"en":"Classroom discussion improves when students ask clear questions and listen carefully.","zh":"當學生提出清楚問題並細心聆聽，課堂討論就會改善。"},{"en":"Good discussion helps students learn how to think, not only remember.","zh":"好的討論幫助學生學會思考，而不只是記憶。"},{"en":"This phrase describes active learning in class.","zh":"這個短語描述課堂中的主動學習。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"disappear from the community","meaning":"從社群中消失","examples":[{"en":"A talented student may suddenly disappear from the community.","zh":"有才華的學生可能突然從社群中消失。"},{"en":"Disappear from the community means leave a group so that others no longer see or benefit from one’s presence.","zh":"Disappear from the community 指離開某個群體，使其他人不再看見或受惠於他的存在。"},{"en":"When a student moves abroad, she may disappear from school clubs and teams.","zh":"當學生移居海外，她可能從學會和校隊中消失。"},{"en":"The community loses energy when active members leave suddenly.","zh":"當活躍成員突然離開，社群會失去活力。"},{"en":"This phrase shows the social effect of student outflow.","zh":"這個短語顯示學生外流的社會影響。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"if the outflow becomes significant","meaning":"如果外流變得明顯","examples":[{"en":"If the outflow becomes significant, schools may face tighter resources.","zh":"如果外流變得明顯，學校可能面對更緊絀的資源。"},{"en":"If the outflow becomes significant means if the number of people leaving becomes large enough to matter.","zh":"If the outflow becomes significant 指如果離開的人數大到足以造成影響。"},{"en":"If many senior students leave, subject choices may become limited.","zh":"如果很多高中學生離開，科目選擇可能變得有限。"},{"en":"This phrase introduces a possible consequence of a growing trend.","zh":"這個短語引出一個增長趨勢可能帶來的後果。"},{"en":"It is useful for discussing risk.","zh":"它適合用來討論風險。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"outflow","meaning":"外流","examples":[{"en":"The outflow of students may affect local schools.","zh":"學生外流可能影響本地學校。"},{"en":"Outflow means the movement of people or resources away from a place or system.","zh":"Outflow 指人或資源離開某地方或制度。"},{"en":"Student outflow happens when many children leave local schools for overseas schools.","zh":"當許多孩子離開本地學校到海外讀書，就出現學生外流。"},{"en":"A large outflow can reduce class sizes and school income.","zh":"大量外流可以減少班級人數和學校收入。"},{"en":"This word is useful when discussing movement away from a community.","zh":"討論離開社群的流動時，這個詞很有用。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"smaller senior forms","meaning":"較小規模的高中級別","examples":[{"en":"Some schools may face smaller senior forms.","zh":"有些學校可能面對較小規模的高中級別。"},{"en":"Smaller senior forms means fewer students in the higher year levels of secondary school.","zh":"Smaller senior forms 指中學較高年級的學生人數較少。"},{"en":"Smaller senior forms may make it harder to offer many elective subjects.","zh":"較小規模的高中級別可能令學校較難提供多種選修科。"},{"en":"If many older students leave, the school community may feel less active.","zh":"如果很多高年級學生離開，學校社群可能較不活躍。"},{"en":"This phrase describes a practical effect on school structure.","zh":"這個短語描述對學校結構的實際影響。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"fewer subject combinations","meaning":"較少科目組合","examples":[{"en":"Some schools may offer fewer subject combinations.","zh":"有些學校可能提供較少科目組合。"},{"en":"Fewer subject combinations means students have fewer possible groups of subjects to choose from.","zh":"Fewer subject combinations 指學生可選擇的科目配搭較少。"},{"en":"A school with fewer students may not offer every subject combination.","zh":"學生人數較少的學校可能無法提供所有科目組合。"},{"en":"Fewer subject combinations can limit students whose interests are unusual.","zh":"較少科目組合可能限制興趣較特別的學生。"},{"en":"This phrase shows how student numbers affect curriculum choice.","zh":"這個短語顯示學生人數如何影響課程選擇。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"tighter resources","meaning":"更緊絀的資源","examples":[{"en":"Schools may face tighter resources if many students leave.","zh":"如果很多學生離開，學校可能面對更緊絀的資源。"},{"en":"Tighter resources means less money, staff, time or space available than before.","zh":"Tighter resources 指可用的金錢、人手、時間或空間比以前少。"},{"en":"A school with tighter resources may reduce clubs or subject options.","zh":"資源更緊絀的學校可能減少學會或科目選擇。"},{"en":"Tighter resources can make it harder to support every student well.","zh":"更緊絀的資源會令學校較難好好支援每個學生。"},{"en":"This phrase describes pressure on an organisation.","zh":"這個短語描述機構面對的壓力。"}],"source":"2015 Q4.pdf","sourcePage":10},{"front":"nevertheless","meaning":"儘管如此","examples":[{"en":"Nevertheless, the trend also serves as a warning.","zh":"儘管如此，這個趨勢也作為一個警號。"},{"en":"Nevertheless means despite what has just been said.","zh":"Nevertheless 指儘管剛才說了某事，情況仍然如此。"},{"en":"Overseas study may bring benefits; nevertheless, local schools should notice the warning signs.","zh":"海外升學可能帶來好處；儘管如此，本地學校應留意警號。"},{"en":"Writers use nevertheless to introduce a contrasting point.","zh":"作者用 nevertheless 引出對比重點。"},{"en":"This word helps create balanced analysis.","zh":"這個詞幫助作出平衡分析。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"serve as a warning","meaning":"作為警號","examples":[{"en":"The trend serves as a warning to local schools.","zh":"這個趨勢對本地學校作為一個警號。"},{"en":"Serve as a warning means act as a sign that something needs attention or change.","zh":"Serve as a warning 指成為提醒人注意或改變的訊號。"},{"en":"Falling student numbers can serve as a warning that families are dissatisfied.","zh":"學生人數下降可以作為家庭不滿的警號。"},{"en":"A warning is useful if schools respond before the problem becomes worse.","zh":"如果學校在問題惡化前回應，警號就是有用的。"},{"en":"This phrase connects a trend with the need for action.","zh":"這個短語把趨勢和行動需要連接起來。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"be reminded that","meaning":"被提醒","examples":[{"en":"Local schools are being reminded that reputation alone is no longer enough.","zh":"本地學校正被提醒，單靠聲譽已不再足夠。"},{"en":"Be reminded that means be made to remember or notice an important fact.","zh":"Be reminded that 指被促使記起或注意某個重要事實。"},{"en":"Schools are reminded that students need support, not only exam training.","zh":"學校被提醒，學生需要支援，而不只是考試訓練。"},{"en":"A trend can remind institutions to review old assumptions.","zh":"一個趨勢可以提醒機構重新檢視舊有假設。"},{"en":"This phrase introduces a lesson from events.","zh":"這個短語引出從事件中得到的教訓。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"reputation alone","meaning":"單靠聲譽","examples":[{"en":"Reputation alone is no longer enough for local schools.","zh":"對本地學校而言，單靠聲譽已不再足夠。"},{"en":"Reputation alone means only a good name or past prestige, without other improvements.","zh":"Reputation alone 指只有好名聲或過去威望，而沒有其他改善。"},{"en":"A famous school cannot rely on reputation alone if students feel unsupported.","zh":"如果學生感到缺乏支援，名校不能單靠聲譽。"},{"en":"Families now look at mental health support, curriculum flexibility and global exposure.","zh":"家庭現在會看精神健康支援、課程彈性和國際接觸。"},{"en":"This phrase warns against depending only on past success.","zh":"這個短語提醒人不要只依賴過去成功。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"no longer enough","meaning":"不再足夠","examples":[{"en":"Reputation alone is no longer enough.","zh":"單靠聲譽已不再足夠。"},{"en":"No longer enough means not sufficient now, although it may have worked before.","zh":"No longer enough 指現在已不足夠，雖然以前可能有用。"},{"en":"Good exam results are no longer enough if students lose motivation.","zh":"如果學生失去動力，好考試成績已不再足夠。"},{"en":"Schools need more than reputation to keep families’ trust.","zh":"學校需要聲譽以外的東西，才能保持家庭信任。"},{"en":"This phrase marks a change in expectations.","zh":"這個短語標示期望的轉變。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"stronger counselling","meaning":"更有力的輔導","examples":[{"en":"Schools may need to provide stronger counselling.","zh":"學校可能需要提供更有力的輔導。"},{"en":"Stronger counselling means better and more effective emotional or academic guidance for students.","zh":"Stronger counselling 指更好、更有效的情緒或學業指導。"},{"en":"Stronger counselling can help students handle stress before it becomes serious.","zh":"更有力的輔導可以幫助學生在壓力變嚴重前處理它。"},{"en":"Schools need counsellors who understand exam pressure, family worries and future choices.","zh":"學校需要理解考試壓力、家庭憂慮和未來選擇的輔導人員。"},{"en":"This phrase highlights student support beyond lessons.","zh":"這個短語突出課堂以外的學生支援。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"flexible curricula","meaning":"更靈活的課程","examples":[{"en":"Schools may need more flexible curricula.","zh":"學校可能需要更靈活的課程。"},{"en":"Flexible curricula are courses that allow different choices, pathways or learning styles.","zh":"Flexible curricula 指容許不同選擇、路徑或學習方式的課程。"},{"en":"A flexible curriculum may include projects, arts, technology and practical subjects.","zh":"靈活課程可以包括專題、藝術、科技和實用科目。"},{"en":"Flexibility helps students whose talents do not fit a narrow exam path.","zh":"靈活性幫助才能不適合狹窄考試路徑的學生。"},{"en":"This phrase suggests reform in what schools teach.","zh":"這個短語暗示學校教學內容的改革。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"mental-health support","meaning":"精神健康支援","examples":[{"en":"Schools may need better mental-health support.","zh":"學校可能需要更好的精神健康支援。"},{"en":"Mental-health support means help for students’ emotional well-being and psychological stress.","zh":"Mental-health support 指對學生情緒健康和心理壓力的幫助。"},{"en":"Counsellors, quiet rooms and stress workshops can be forms of mental-health support.","zh":"輔導員、安靜空間和壓力工作坊都可以是精神健康支援。"},{"en":"Better mental-health support can prevent students from becoming exhausted learners.","zh":"更好的精神健康支援可以防止學生成為疲憊的學習者。"},{"en":"This phrase is important when discussing student well-being.","zh":"討論學生身心健康時，這個短語很重要。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"learning experiences","meaning":"學習經歷","examples":[{"en":"Schools should provide learning experiences that connect students with the wider world.","zh":"學校應提供把學生連繫到更廣闊世界的學習經歷。"},{"en":"Learning experiences are activities or situations through which students gain knowledge and skills.","zh":"Learning experiences 指學生透過活動或情況獲得知識和技能的經驗。"},{"en":"Exchange projects, field trips and international discussions are learning experiences.","zh":"交流專題、實地考察和國際討論都是學習經歷。"},{"en":"Good learning experiences make education feel real and useful.","zh":"好的學習經歷令教育感覺真實而有用。"},{"en":"This phrase is broader than ordinary classroom lessons.","zh":"這個短語比普通課堂更廣泛。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"connect students with","meaning":"把學生連繫到……","examples":[{"en":"Learning experiences should connect Hong Kong students with the wider world.","zh":"學習經歷應把香港學生連繫到更廣闊的世界。"},{"en":"Connect students with means help students come into contact with people, ideas or places.","zh":"Connect students with 指幫助學生接觸人物、想法或地方。"},{"en":"Online exchange lessons can connect students with classmates overseas.","zh":"網上交流課可以把學生連繫到海外同學。"},{"en":"Schools connect students with the wider world when they invite global speakers or run exchange projects.","zh":"學校邀請國際講者或舉辦交流專題時，就是把學生連繫到更廣闊世界。"},{"en":"This phrase shows the purpose of international learning.","zh":"這個短語顯示國際學習的目的。"}],"source":"2015 Q4.pdf","sourcePage":11},{"front":"the wider world","meaning":"更廣闊的世界","examples":[{"en":"Students need learning experiences connected with the wider world.","zh":"學生需要與更廣闊世界連接的學習經歷。"},{"en":"The wider world means places, people and ideas beyond one’s own local environment.","zh":"The wider world 指自己本地環境以外的地方、人物和想法。"},{"en":"Students meet the wider world through travel, online exchanges and international classmates.","zh":"學生透過旅行、網上交流和國際同學接觸更廣闊世界。"},{"en":"Contact with the wider world can broaden students’ understanding of success.","zh":"接觸更廣闊世界可以擴闊學生對成功的理解。"},{"en":"This phrase contrasts local experience with global awareness.","zh":"這個短語把本地經驗和全球意識作對比。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"in that sense","meaning":"從這個意義上說","examples":[{"en":"In that sense, the departure of some students could push local education to improve.","zh":"從這個意義上說，一些學生的離開可能推動本地教育改善。"},{"en":"In that sense means from that particular point of view.","zh":"In that sense 指從那個特定角度來看。"},{"en":"In that sense, student outflow can be a warning rather than only a loss.","zh":"從這個意義上說，學生外流可以是一個警號，而不只是損失。"},{"en":"Writers use this phrase to explain a careful interpretation.","zh":"作者用這個短語解釋謹慎的理解。"},{"en":"It helps show that an issue can be understood in more than one way.","zh":"它幫助顯示一個議題可以有多於一種理解方式。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"the departure of","meaning":"……的離開","examples":[{"en":"The departure of some students could push local education to improve.","zh":"一些學生的離開可能推動本地教育改善。"},{"en":"The departure of someone means their leaving from a place, group or system.","zh":"The departure of someone 指某人離開一個地方、群體或制度。"},{"en":"The departure of talented students can affect clubs and classroom discussion.","zh":"有才華學生的離開可以影響學會和課堂討論。"},{"en":"A departure may be painful but can also force institutions to change.","zh":"離開可能令人難受，但也可以迫使機構改變。"},{"en":"This phrase is formal and suitable for essays.","zh":"這個短語較正式，適合文章寫作。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"push local education to improve","meaning":"推動本地教育改善","examples":[{"en":"The trend could push local education to improve.","zh":"這個趨勢可能推動本地教育改善。"},{"en":"Push local education to improve means pressure schools and the system to become better.","zh":"Push local education to improve 指給學校和制度壓力，促使它們變得更好。"},{"en":"Student outflow may push local education to offer more support and flexible subjects.","zh":"學生外流可能推動本地教育提供更多支援和靈活科目。"},{"en":"Competition can push institutions to review old habits.","zh":"競爭可以推動機構檢視舊習慣。"},{"en":"This phrase shows how a problem can become motivation for reform.","zh":"這個短語顯示問題如何變成改革動力。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"those who remain","meaning":"留下來的人","examples":[{"en":"Local education may improve for those who remain.","zh":"本地教育可能為留下來的人而改善。"},{"en":"Those who remain means the people who stay after others have left.","zh":"Those who remain 指其他人離開後仍然留下的人。"},{"en":"Students who remain in local schools may benefit if the system improves.","zh":"如果制度改善，留在本地學校的學生可能受惠。"},{"en":"A school should care for those who remain, not only worry about those who leave.","zh":"學校應照顧留下來的人，而不只是擔心離開的人。"},{"en":"This phrase focuses on the students still inside the system.","zh":"這個短語集中於仍在制度內的學生。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"the impact is mixed","meaning":"影響有好有壞","examples":[{"en":"For the children who leave, the impact is mixed.","zh":"對離開的孩子而言，影響有好有壞。"},{"en":"The impact is mixed means the effects include both benefits and problems.","zh":"The impact is mixed 指影響同時包括好處和問題。"},{"en":"Overseas study can bring confidence, but the impact is mixed if loneliness is serious.","zh":"海外升學可以帶來信心，但如果孤獨感嚴重，影響就是有好有壞。"},{"en":"A mixed impact requires balanced judgement, not simple praise or criticism.","zh":"有好有壞的影響需要平衡判斷，而不是簡單讚成或批評。"},{"en":"This phrase is useful when discussing complex issues.","zh":"討論複雜議題時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"on the positive side","meaning":"從正面來看","examples":[{"en":"On the positive side, overseas study can be life-changing.","zh":"從正面來看，海外升學可以改變人生。"},{"en":"On the positive side means looking at the good part of a situation.","zh":"On the positive side 指從情況的好處來看。"},{"en":"On the positive side, students abroad may become more independent.","zh":"從正面來看，海外學生可能變得更獨立。"},{"en":"Writers use this phrase before explaining benefits.","zh":"作者在解釋好處前會使用這個短語。"},{"en":"This phrase helps organise a balanced discussion.","zh":"這個短語幫助組織平衡討論。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"overseas study","meaning":"海外升學","examples":[{"en":"Overseas study can be life-changing.","zh":"海外升學可以改變人生。"},{"en":"Overseas study means studying in a country different from one’s home.","zh":"Overseas study 指在自己家鄉以外的國家讀書。"},{"en":"Overseas study may expose students to new languages, cultures and learning styles.","zh":"海外升學可能讓學生接觸新語言、文化和學習模式。"},{"en":"It can be exciting but also emotionally difficult.","zh":"它可以令人興奮，但在情感上也可能困難。"},{"en":"This phrase describes education outside the home country.","zh":"這個短語描述在本國以外接受教育。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"life-changing","meaning":"改變人生的","examples":[{"en":"Overseas study can be life-changing for some students.","zh":"對一些學生來說，海外升學可以是改變人生的。"},{"en":"Life-changing means powerful enough to change a person’s future, character or view of life.","zh":"Life-changing 指有足夠力量改變一個人的未來、性格或人生觀。"},{"en":"Living abroad can be life-changing when students learn independence and confidence.","zh":"當學生學會獨立和自信，海外生活可以改變人生。"},{"en":"A life-changing experience may be difficult while it is happening.","zh":"改變人生的經歷在發生時可能很困難。"},{"en":"This word shows strong personal impact.","zh":"這個詞顯示強烈的個人影響。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"fluent in English","meaning":"英語更流利","examples":[{"en":"Students may become more fluent in English.","zh":"學生的英語可能變得更流利。"},{"en":"Fluent in English means able to speak, write or understand English smoothly and naturally.","zh":"Fluent in English 指能順暢而自然地說、寫或理解英語。"},{"en":"A student may become fluent in English after using it daily at school.","zh":"學生每天在學校使用英語後，可能變得英語更流利。"},{"en":"Fluency helps students join class discussions and make friends abroad.","zh":"流利英語幫助學生參與課堂討論和在海外交朋友。"},{"en":"This phrase describes language ability.","zh":"這個短語描述語言能力。"}],"source":"2015 Q4.pdf","sourcePage":12},{"front":"open-minded","meaning":"思想開明","examples":[{"en":"Students may become more open-minded after overseas study.","zh":"海外升學後，學生可能變得更思想開明。"},{"en":"Open-minded means willing to consider different ideas, cultures or ways of life.","zh":"Open-minded 指願意考慮不同想法、文化或生活方式。"},{"en":"An open-minded student listens before judging unfamiliar customs.","zh":"思想開明的學生會先聆聽，再判斷陌生習俗。"},{"en":"Studying with international classmates can make students more open-minded.","zh":"與國際同學一起學習可以令學生更思想開明。"},{"en":"This word describes a flexible and respectful attitude.","zh":"這個詞描述靈活而尊重他人的態度。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"return with","meaning":"帶着……回來","examples":[{"en":"Students may return with a broader view of success.","zh":"學生可能帶着對成功更廣闊的看法回來。"},{"en":"Return with means come back bringing a new quality, idea or experience.","zh":"Return with 指回來時帶着新的特質、想法或經驗。"},{"en":"A student may return with stronger English and greater independence.","zh":"學生可能帶着更強英語能力和更大獨立性回來。"},{"en":"Returning with new ideas can benefit the student’s family and community.","zh":"帶着新想法回來可以令學生的家庭和社群受惠。"},{"en":"This phrase connects coming home with personal change.","zh":"這個短語把回家和個人改變連接起來。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"a broader view of success","meaning":"對成功更廣闊的看法","examples":[{"en":"Students may return with a broader view of success.","zh":"學生可能帶着對成功更廣闊的看法回來。"},{"en":"A broader view of success means seeing success as more than marks, ranking or money.","zh":"A broader view of success 指把成功看成不只是分數、排名或金錢。"},{"en":"Students may learn that creativity, kindness and independence are also forms of success.","zh":"學生可能學會創意、善良和獨立也是成功形式。"},{"en":"A broader view of success can reduce pressure from narrow expectations.","zh":"對成功更廣闊的看法可以減少狹窄期望帶來的壓力。"},{"en":"This phrase expands the meaning of achievement.","zh":"這個短語擴闊成就的意義。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"stand on their own feet","meaning":"自立","examples":[{"en":"Students may develop a stronger ability to stand on their own feet.","zh":"學生可能培養更強的自立能力。"},{"en":"Stand on their own feet means live and make decisions independently.","zh":"Stand on their own feet 指獨立生活和作決定。"},{"en":"A student stands on her own feet when she manages study, money and daily problems.","zh":"當學生自己管理學習、金錢和日常問題時，她就是自立。"},{"en":"Overseas life can teach children to stand on their own feet earlier.","zh":"海外生活可以較早教孩子自立。"},{"en":"This phrase describes practical independence.","zh":"這個短語描述實際的獨立能力。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"the price of independence","meaning":"獨立的代價","examples":[{"en":"The price of independence can be loneliness.","zh":"獨立的代價可能是孤獨。"},{"en":"The price of independence means the difficulty or sacrifice that comes with becoming independent.","zh":"The price of independence 指變得獨立所帶來的困難或犧牲。"},{"en":"A student may gain freedom abroad, but the price of independence may be homesickness.","zh":"學生在海外可能得到自由，但獨立的代價可能是思鄉。"},{"en":"Independence is valuable, yet it can bring emotional costs.","zh":"獨立很有價值，但也可能帶來情感成本。"},{"en":"This phrase shows that benefits can have hidden costs.","zh":"這個短語顯示好處也可能有隱藏代價。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"mature enough to","meaning":"成熟到足以……","examples":[{"en":"A child may seem mature enough to board a plane.","zh":"孩子可能看似成熟到足以登機。"},{"en":"Mature enough to means developed enough in judgement or behaviour to do something.","zh":"Mature enough to 指在判斷或行為上發展到足以做某事。"},{"en":"A teenager may be mature enough to manage homework but not homesickness.","zh":"青少年可能成熟到足以管理功課，但未必能處理思鄉。"},{"en":"Looking mature enough does not always mean being emotionally ready.","zh":"看似足夠成熟不一定代表情感上準備好了。"},{"en":"This phrase connects age, ability and responsibility.","zh":"這個短語把年齡、能力和責任連接起來。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"board a plane","meaning":"登機","examples":[{"en":"A child may be mature enough to board a plane but still feel lonely.","zh":"孩子可能成熟到足以登機，但仍然感到孤獨。"},{"en":"Board a plane means get onto an aircraft before it leaves.","zh":"Board a plane 指在飛機起飛前上機。"},{"en":"Boarding a plane alone can feel exciting and frightening for a young student.","zh":"獨自登機對年幼學生來說可以既興奮又可怕。"},{"en":"A child may board a plane confidently but cry after arriving overseas.","zh":"孩子可能自信地登機，但抵達海外後哭泣。"},{"en":"This phrase marks the physical start of studying abroad.","zh":"這個短語標示海外升學實際開始的一刻。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"too young to handle","meaning":"太年幼而無法處理","examples":[{"en":"A child may still be too young to handle homesickness.","zh":"孩子可能仍然太年幼而無法處理思鄉。"},{"en":"Too young to handle means not old or mature enough to deal with something well.","zh":"Too young to handle 指年紀或成熟度不足以好好處理某事。"},{"en":"A twelve-year-old may be too young to handle long periods away from family.","zh":"十二歲孩子可能太年幼而無法處理長時間離家。"},{"en":"Some emotional problems require support, even for capable students.","zh":"有些情感問題需要支援，即使學生能力強也一樣。"},{"en":"This phrase warns that ability and age must be considered carefully.","zh":"這個短語提醒人要仔細考慮能力和年齡。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"homesickness","meaning":"思鄉","examples":[{"en":"Some children may struggle with homesickness.","zh":"有些孩子可能會受思鄉困擾。"},{"en":"Homesickness is sadness or longing for home while living away from it.","zh":"Homesickness 指離家生活時對家的悲傷或思念。"},{"en":"A student may feel homesickness when she misses family dinners and familiar voices.","zh":"當學生想念家庭晚飯和熟悉聲音時，可能會思鄉。"},{"en":"Homesickness can affect sleep, mood and school performance.","zh":"思鄉可以影響睡眠、情緒和學校表現。"},{"en":"This word is important when discussing overseas study.","zh":"討論海外升學時，這個詞很重要。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"cultural misunderstanding","meaning":"文化誤解","examples":[{"en":"Overseas students may face cultural misunderstanding.","zh":"海外學生可能面對文化誤解。"},{"en":"Cultural misunderstanding means confusion or conflict caused by different customs, values or communication styles.","zh":"Cultural misunderstanding 指由不同習俗、價值觀或溝通方式造成的困惑或衝突。"},{"en":"A student may face cultural misunderstanding when classmates misread her quietness as rudeness.","zh":"當同學把她的安靜誤解為無禮，學生可能面對文化誤解。"},{"en":"Cultural misunderstanding can make students feel isolated if no one explains the difference.","zh":"如果沒有人解釋差異，文化誤解可能令學生感到孤立。"},{"en":"This phrase shows a possible difficulty of living abroad.","zh":"這個短語顯示海外生活可能遇到的困難。"}],"source":"2015 Q4.pdf","sourcePage":13},{"front":"justifying the family’s sacrifice","meaning":"證明家人的犧牲值得","examples":[{"en":"Some students feel pressure to justify the family’s sacrifice.","zh":"有些學生感到壓力，要證明家人的犧牲值得。"},{"en":"Justifying the family’s sacrifice means proving that the money, effort and separation were worth it.","zh":"Justifying the family’s sacrifice 指證明金錢、努力和分離是值得的。"},{"en":"A student may feel she must get excellent results to justify the family’s sacrifice.","zh":"學生可能覺得自己必須取得優異成績，才能證明家人的犧牲值得。"},{"en":"This pressure can make overseas study emotionally heavy.","zh":"這種壓力可以令海外升學在情感上變得沉重。"},{"en":"This phrase connects family love with student burden.","zh":"這個短語把家人的愛和學生負擔連接起來。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"family’s sacrifice","meaning":"家人的犧牲","examples":[{"en":"The pressure of the family’s sacrifice can be heavy.","zh":"家人的犧牲所帶來的壓力可以很沉重。"},{"en":"Family’s sacrifice means what family members give up, such as money, time or closeness, for someone’s future.","zh":"Family’s sacrifice 指家人為某人的未來放棄的東西，例如金錢、時間或親近相處。"},{"en":"Parents may work harder to pay for overseas schooling.","zh":"父母可能更努力工作，以支付海外學費。"},{"en":"A child may feel the family’s sacrifice every time school fees are mentioned.","zh":"每次提到學費，孩子都可能感受到家人的犧牲。"},{"en":"This phrase shows the emotional cost behind education choices.","zh":"這個短語顯示教育選擇背後的情感代價。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"caught between two worlds","meaning":"夾在兩個世界之間","examples":[{"en":"Some students may feel caught between two worlds.","zh":"有些學生可能覺得自己夾在兩個世界之間。"},{"en":"Caught between two worlds means feeling unable to belong fully to either of two cultures or places.","zh":"Caught between two worlds 指感到無法完全屬於兩種文化或地方其中任何一方。"},{"en":"An overseas student may feel caught between home culture and the new school culture.","zh":"海外學生可能覺得自己夾在家鄉文化和新學校文化之間。"},{"en":"This feeling can grow when old friends and new classmates do not understand each other.","zh":"當舊朋友和新同學彼此不理解，這種感覺可能加深。"},{"en":"This phrase describes identity tension.","zh":"這個短語描述身份上的拉扯。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"not fully local","meaning":"未能完全融入當地","examples":[{"en":"Some students may feel not fully local in their new school.","zh":"有些學生在新學校可能感到未能完全融入當地。"},{"en":"Not fully local means not completely accepted as belonging to the new place.","zh":"Not fully local 指未被完全接受為屬於新地方的一員。"},{"en":"A student may speak the language well but still feel not fully local.","zh":"學生可能語言說得好，但仍感到未能完全融入當地。"},{"en":"Feeling not fully local can make friendship-building harder.","zh":"感到未能完全融入當地，可能令建立友誼更困難。"},{"en":"This phrase shows the difficulty of belonging abroad.","zh":"這個短語顯示在海外尋找歸屬感的困難。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"gradually distant from","meaning":"與……逐漸疏遠","examples":[{"en":"Some students become gradually distant from friends back home.","zh":"有些學生與家鄉朋友逐漸疏遠。"},{"en":"Gradually distant from means slowly less close to someone over time.","zh":"Gradually distant from 指隨時間慢慢與某人不再親近。"},{"en":"A student abroad may become gradually distant from classmates who stayed in Hong Kong.","zh":"海外學生可能與留在香港的同學逐漸疏遠。"},{"en":"Time zones, busy schedules and different experiences can create distance.","zh":"時區、繁忙時間表和不同經歷可以造成距離。"},{"en":"This phrase describes a slow change in relationships.","zh":"這個短語描述關係中的緩慢變化。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"friends back home","meaning":"家鄉的朋友","examples":[{"en":"Students may miss friends back home.","zh":"學生可能想念家鄉的朋友。"},{"en":"Friends back home are friends who remain in one’s original home city or country.","zh":"Friends back home 指仍留在原本家鄉城市或國家的朋友。"},{"en":"A student abroad may text friends back home after a lonely school day.","zh":"海外學生在孤單的上學日後，可能傳訊息給家鄉朋友。"},{"en":"Friends back home can provide comfort but may not fully understand the new life abroad.","zh":"家鄉的朋友可以提供安慰，但未必完全理解海外新生活。"},{"en":"This phrase connects overseas study with old relationships.","zh":"這個短語把海外升學和舊關係連接起來。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Social media can connect overseas students with friends.","zh":"社交媒體可以把海外學生和朋友連繫起來。"},{"en":"Social media means online platforms where people share messages, photos, videos and updates.","zh":"Social media 指人們分享訊息、照片、影片和近況的網上平台。"},{"en":"Overseas students use social media to keep in touch with family and classmates.","zh":"海外學生使用社交媒體與家人和同學保持聯絡。"},{"en":"Social media helps reduce distance, but it cannot replace being physically together.","zh":"社交媒體有助減少距離，但不能取代真正在一起。"},{"en":"This phrase describes a digital tool for connection.","zh":"這個短語描述一種連結人的數碼工具。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"replace a family dinner","meaning":"取代一頓家庭晚飯","examples":[{"en":"Social media cannot replace a family dinner.","zh":"社交媒體不能取代一頓家庭晚飯。"},{"en":"Replace a family dinner means take the place of eating and talking with family in person.","zh":"Replace a family dinner 指取代與家人親身吃飯和聊天的時刻。"},{"en":"A video call helps, but it cannot fully replace a warm meal at home.","zh":"視像通話有幫助，但不能完全取代家中溫暖的一餐。"},{"en":"Family dinners give comfort through food, conversation and physical presence.","zh":"家庭晚飯透過食物、對話和真實陪伴帶來安慰。"},{"en":"This phrase shows the limits of digital connection.","zh":"這個短語顯示數碼連結的限制。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"the comfort of","meaning":"……帶來的安慰","examples":[{"en":"Social media cannot replace the comfort of Cantonese conversation.","zh":"社交媒體不能取代廣東話對話帶來的安慰。"},{"en":"The comfort of something means the warm, safe or familiar feeling it gives.","zh":"The comfort of something 指某事帶來的溫暖、安全或熟悉感。"},{"en":"The comfort of a familiar voice can help a homesick student after school.","zh":"熟悉聲音帶來的安慰可以幫助放學後思鄉的學生。"},{"en":"Students abroad may miss the comfort of family jokes and local expressions.","zh":"海外學生可能想念家庭笑話和本地用語帶來的安慰。"},{"en":"This phrase shows emotional support from familiar things.","zh":"這個短語顯示熟悉事物帶來的情感支援。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"Cantonese conversation","meaning":"廣東話對話","examples":[{"en":"Cantonese conversation can comfort a homesick student.","zh":"廣東話對話可以安慰思鄉的學生。"},{"en":"Cantonese conversation means speaking naturally in Cantonese with others.","zh":"Cantonese conversation 指與別人自然地用廣東話交談。"},{"en":"After using English all day, a student may feel relaxed during Cantonese conversation.","zh":"整天使用英語後，學生可能在廣東話對話中感到放鬆。"},{"en":"Familiar language can carry humour, memory and belonging.","zh":"熟悉語言可以承載幽默、記憶和歸屬感。"},{"en":"This phrase connects language with emotional home.","zh":"這個短語把語言和情感上的家連接起來。"}],"source":"2015 Q4.pdf","sourcePage":14},{"front":"after a difficult day","meaning":"在艱難的一天之後","examples":[{"en":"Cantonese conversation may comfort a student after a difficult day.","zh":"在艱難的一天之後，廣東話對話可能安慰學生。"},{"en":"After a difficult day means following a day full of stress, problems or sadness.","zh":"After a difficult day 指在充滿壓力、問題或悲傷的一天之後。"},{"en":"After a difficult day at school, a call home can feel especially important.","zh":"在學校經歷艱難一天之後，給家裏打一通電話可能特別重要。"},{"en":"Students abroad may need comfort after a difficult day of misunderstanding or loneliness.","zh":"海外學生在經歷誤解或孤獨的艱難一天後，可能需要安慰。"},{"en":"This phrase gives emotional timing to an experience.","zh":"這個短語為經歷加入情感上的時間點。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, overseas schooling reflects parental hope and anxiety.","zh":"總括而言，海外升學反映父母的希望與焦慮。"},{"en":"All things considered means after thinking about all important points.","zh":"All things considered 指考慮所有重要因素之後。"},{"en":"All things considered, overseas study can bring growth but also emotional risk.","zh":"總括而言，海外升學可以帶來成長，但也有情感風險。"},{"en":"Writers use this phrase before giving a balanced conclusion.","zh":"作者在提出平衡結論前會使用這個短語。"},{"en":"This phrase helps close an argument thoughtfully.","zh":"這個短語幫助有思考地結束論證。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"the growing number of","meaning":"越來越多的……","examples":[{"en":"The growing number of Hong Kong children studying overseas reflects parental hope and anxiety.","zh":"越來越多香港孩子到海外讀書，反映父母的希望與焦慮。"},{"en":"The growing number of means more and more of a particular group or thing.","zh":"The growing number of 指某一群體或事物越來越多。"},{"en":"The growing number of students leaving local schools has attracted public attention.","zh":"越來越多學生離開本地學校，已引起公眾關注。"},{"en":"A growing number can signal a wider social change.","zh":"越來越多的數量可以顯示更廣泛的社會轉變。"},{"en":"This phrase is useful when describing trends.","zh":"描述趨勢時，這個短語很有用。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"studying overseas","meaning":"到海外讀書","examples":[{"en":"More Hong Kong children are studying overseas.","zh":"越來越多香港孩子到海外讀書。"},{"en":"Studying overseas means receiving education in another country.","zh":"Studying overseas 指在另一個國家接受教育。"},{"en":"Students studying overseas may live in dormitories, host families or boarding schools.","zh":"到海外讀書的學生可能住在宿舍、寄宿家庭或寄宿學校。"},{"en":"Studying overseas can build independence but may also create homesickness.","zh":"到海外讀書可以建立獨立能力，但也可能造成思鄉。"},{"en":"This phrase describes the central trend of the article.","zh":"這個短語描述文章的核心趨勢。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"reflect parental hope and anxiety","meaning":"反映父母的希望與焦慮","examples":[{"en":"The trend reflects parental hope and anxiety.","zh":"這個趨勢反映父母的希望與焦慮。"},{"en":"Reflect parental hope and anxiety means show both parents’ dreams and worries.","zh":"Reflect parental hope and anxiety 指顯示父母的夢想和憂慮。"},{"en":"Parents hope for better opportunities but feel anxious about distance and pressure.","zh":"父母希望孩子有更好機會，但也因距離和壓力而焦慮。"},{"en":"Overseas schooling reflects hope when families imagine growth, and anxiety when they fear harm.","zh":"當家庭想像成長時，海外升學反映希望；當他們害怕傷害時，則反映焦慮。"},{"en":"This phrase captures the emotional mixture behind the decision.","zh":"這個短語概括這個決定背後的複雜情感。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"learn from the trend","meaning":"從趨勢中學習","examples":[{"en":"Local schools should learn from the trend.","zh":"本地學校應從這個趨勢中學習。"},{"en":"Learn from the trend means study what the trend reveals and improve because of it.","zh":"Learn from the trend 指研究趨勢揭示的問題，並因此改善。"},{"en":"Schools can learn from the trend by strengthening counselling and curriculum choice.","zh":"學校可以透過加強輔導和課程選擇，從趨勢中學習。"},{"en":"A trend becomes useful when institutions treat it as feedback.","zh":"當機構把趨勢視為回饋，趨勢就變得有用。"},{"en":"This phrase turns a challenge into a chance to improve.","zh":"這個短語把挑戰變成改善機會。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"a magic door to success","meaning":"通往成功的魔法門","examples":[{"en":"Overseas education is not a magic door to success.","zh":"海外教育不是通往成功的魔法門。"},{"en":"A magic door to success means an easy and guaranteed path to achievement.","zh":"A magic door to success 指容易而保證成功的道路。"},{"en":"Studying abroad is not a magic door to success if a child is not emotionally ready.","zh":"如果孩子在情感上未準備好，海外升學就不是通往成功的魔法門。"},{"en":"Hard work, support and adjustment still matter after leaving Hong Kong.","zh":"離開香港後，努力、支援和適應仍然重要。"},{"en":"This phrase warns against unrealistic expectations.","zh":"這個短語提醒人不要有不切實際的期望。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"only when","meaning":"只有當……才","examples":[{"en":"Only when children are prepared emotionally can overseas study bring genuine growth.","zh":"只有當孩子在情感上準備好，海外升學才可以帶來真正成長。"},{"en":"Only when means something can happen only if a necessary condition is met.","zh":"Only when 指只有在必要條件達成時，某事才會發生。"},{"en":"Only when students feel supported can they make good use of overseas opportunities.","zh":"只有當學生感到受支持，他們才可以好好運用海外機會。"},{"en":"This phrase makes emotional preparation sound essential, not optional.","zh":"這個短語令情感準備聽起來是必要的，而不是可有可無。"},{"en":"It is useful for expressing a strict condition.","zh":"它適合用來表達嚴格條件。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"prepared emotionally","meaning":"情感上準備好","examples":[{"en":"Children should be prepared emotionally before studying overseas.","zh":"孩子到海外讀書前，應在情感上準備好。"},{"en":"Prepared emotionally means ready to handle feelings such as loneliness, fear and homesickness.","zh":"Prepared emotionally 指準備好處理孤獨、恐懼和思鄉等感受。"},{"en":"A child is emotionally prepared when she knows who to ask for help abroad.","zh":"當孩子知道在海外可以向誰求助，她就在情感上較準備好。"},{"en":"Emotional preparation is as important as academic preparation for young students.","zh":"對年幼學生來說，情感準備和學業準備同樣重要。"},{"en":"This phrase focuses on mental readiness.","zh":"這個短語集中於心理準備。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"not just academically","meaning":"不只是學業上","examples":[{"en":"Children need to be prepared emotionally, not just academically.","zh":"孩子需要在情感上準備好，而不只是學業上。"},{"en":"Not just academically means not only in school subjects, exams or grades.","zh":"Not just academically 指不只是學科、考試或成績方面。"},{"en":"A student may be academically strong but still unready for loneliness abroad.","zh":"學生可能學業很強，但仍未準備好面對海外孤獨感。"},{"en":"Preparing only academically ignores the emotional side of overseas study.","zh":"只在學業上準備，會忽略海外升學的情感面。"},{"en":"This phrase broadens the meaning of readiness.","zh":"這個短語擴闊準備的意義。"}],"source":"2015 Q4.pdf","sourcePage":15},{"front":"a foreign classroom","meaning":"外國課室","examples":[{"en":"A foreign classroom can become a place of genuine growth.","zh":"外國課室可以成為真正成長的地方。"},{"en":"A foreign classroom is a learning environment in another country.","zh":"A foreign classroom 指另一個國家的學習環境。"},{"en":"A foreign classroom may include new teaching styles, classmates and cultural expectations.","zh":"外國課室可能包括新的教學模式、同學和文化期望。"},{"en":"Students need support to turn a foreign classroom into a place of growth.","zh":"學生需要支援，才能把外國課室變成成長的地方。"},{"en":"This phrase symbolises the overseas learning experience.","zh":"這個短語象徵海外學習經歷。"}],"source":"2015 Q4.pdf","sourcePage":16},{"front":"genuine growth","meaning":"真正成長","examples":[{"en":"Overseas education can become a place of genuine growth.","zh":"海外教育可以成為真正成長的地方。"},{"en":"Genuine growth means real personal development, not just better grades or appearance.","zh":"Genuine growth 指真實的個人成長，而不只是成績或外表變好。"},{"en":"Genuine growth happens when students become more independent, thoughtful and resilient.","zh":"當學生變得更獨立、更懂思考和更有韌性，真正成長就會發生。"},{"en":"Overseas study brings genuine growth only when children are supported emotionally and academically.","zh":"只有當孩子在情感和學業上都得到支援，海外升學才會帶來真正成長。"},{"en":"This phrase describes the deeper goal of education.","zh":"這個短語描述教育更深層的目標。"}],"source":"2015 Q4.pdf","sourcePage":16}],"dse/writing/part-b/2015/Q5":[{"front":"for all, not for some","meaning":"為所有人而設，而非只屬於部分人","examples":[{"en":"The harbour should be for all, not a commodity for some.","zh":"海港應為所有人而設，而不是只屬於部分人的商品。"},{"en":"For all, not for some means something should serve everyone, not only a privileged group.","zh":"為所有人而設，而非只屬於部分人，是指某物應服務所有人，而不是只服務特權群體。"},{"en":"A public library should be for all, not for some, because every student needs access to books.","zh":"公共圖書館應為所有人而設，而非只屬於部分人，因為每個學生都需要接觸書本。"},{"en":"When public land is used only by the wealthy, it is no longer for all.","zh":"當公共土地只供富有人士使用時，它就不再是為所有人而設。"},{"en":"This phrase stresses fairness, shared ownership, and public access.","zh":"這個短語強調公平、共同擁有和公眾使用。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"a commodity","meaning":"商品；可買賣的東西","examples":[{"en":"The harbour should not be treated as a commodity.","zh":"海港不應被視為商品。"},{"en":"A commodity is something bought, sold, or used mainly for profit.","zh":"商品是指主要為了盈利而被購買、出售或使用的東西。"},{"en":"Housing becomes a commodity when people see homes only as investments, not places to live.","zh":"當人們只把房屋視為投資，而不是居住地方時，房屋就變成商品。"},{"en":"Treating public space as a commodity can reduce access for ordinary citizens.","zh":"把公共空間視為商品，可能會減少普通市民的使用機會。"},{"en":"This word warns that something valuable to society should not be judged only by money.","zh":"這個詞提醒我們，對社會有價值的東西不應只用金錢衡量。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"Dear Editor","meaning":"尊敬的編輯","examples":[{"en":"The letter begins with Dear Editor.","zh":"這封信以「尊敬的編輯」開始。"},{"en":"Dear Editor is a formal greeting used at the start of a letter to a newspaper or magazine.","zh":"「尊敬的編輯」是寫給報章或雜誌時在信件開首使用的正式稱呼。"},{"en":"A student may write Dear Editor before sharing an opinion about public space.","zh":"學生在分享對公共空間的意見前，可能會寫「尊敬的編輯」。"},{"en":"This greeting shows that the writer is addressing the person who handles readers’ letters.","zh":"這個稱呼表示作者正在向處理讀者來信的人發言。"},{"en":"It is more suitable for a formal letter than a casual greeting like Hi.","zh":"它比「你好」這類隨意問候更適合正式信件。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"express my strong support for","meaning":"表達我對……的強烈支持","examples":[{"en":"I am writing to express my strong support for public harbourfront space.","zh":"我寫信是為了表達我對公共海濱空間的強烈支持。"},{"en":"To express my strong support for something means to clearly say that I firmly agree with it.","zh":"表達我對某事的強烈支持，是指清楚說明自己堅定同意它。"},{"en":"Residents may express strong support for a new park because children need safe play areas.","zh":"居民可能強烈支持興建新公園，因為孩子需要安全的遊樂地方。"},{"en":"This phrase is useful when a writer wants to show a clear position at the beginning.","zh":"當作者想在開首表明清晰立場時，這個短語很有用。"},{"en":"Strong support sounds more serious when it is followed by reasons and evidence.","zh":"強烈支持若配合理由和證據，會聽起來更有說服力。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"undeveloped harbourfront areas","meaning":"尚未發展的海濱地區","examples":[{"en":"Hong Kong’s undeveloped harbourfront areas should remain open to the public.","zh":"香港尚未發展的海濱地區應繼續向公眾開放。"},{"en":"Undeveloped harbourfront areas are waterfront sites that have not yet been built over.","zh":"尚未發展的海濱地區是指尚未被建築物覆蓋的海旁土地。"},{"en":"Undeveloped harbourfront areas can become parks, promenades, lawns, or public sitting-out spaces.","zh":"尚未發展的海濱地區可以成為公園、海濱長廊、草地或公共休憩空間。"},{"en":"If these areas are sold too quickly, future citizens may lose rare public land.","zh":"如果這些地區太快被出售，未來市民可能失去珍貴公共土地。"},{"en":"This phrase points to land whose future use still needs careful decision.","zh":"這個短語指向一種仍需小心決定未來用途的土地。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"open spaces","meaning":"開放空間","examples":[{"en":"The harbourfront should be left as open spaces for public use.","zh":"海濱應保留作公眾使用的開放空間。"},{"en":"Open spaces are areas without dense buildings where people can walk, rest, play, or gather.","zh":"開放空間是沒有密集建築、可供人們散步、休息、玩耍或聚集的地方。"},{"en":"A crowded district needs open spaces so residents can breathe and relax.","zh":"擠迫地區需要開放空間，讓居民可以呼吸和放鬆。"},{"en":"Open spaces improve city life because they give people room outside small homes.","zh":"開放空間改善城市生活，因為它給住在細小家居的人戶外空間。"},{"en":"This phrase usually refers to parks, lawns, squares, and promenades.","zh":"這個短語通常指公園、草地、廣場和海濱長廊。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"public use","meaning":"公眾使用","examples":[{"en":"The remaining harbourfront should be protected for public use.","zh":"餘下的海濱地區應受到保護，供公眾使用。"},{"en":"Public use means ordinary people can use a place or facility, not only private owners.","zh":"公眾使用是指普通人可以使用某個地方或設施，而不只是私人業主可以使用。"},{"en":"A playground built for public use should be open to children from different families.","zh":"為公眾使用而建的遊樂場，應向不同家庭的孩子開放。"},{"en":"Protecting land for public use keeps important spaces from becoming exclusive.","zh":"保護土地作公眾使用，可以防止重要空間變成少數人專享。"},{"en":"This phrase focuses on access, fairness, and shared benefit.","zh":"這個短語著重使用權、公平和共同利益。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"Victoria Harbour","meaning":"維多利亞港","examples":[{"en":"Victoria Harbour is central to Hong Kong’s identity.","zh":"維多利亞港對香港身份十分重要。"},{"en":"Victoria Harbour is the famous harbour between Hong Kong Island and Kowloon.","zh":"維多利亞港是位於香港島與九龍之間的著名海港。"},{"en":"Many visitors recognise Hong Kong through the view of Victoria Harbour and its skyline.","zh":"許多遊客透過維多利亞港和其天際線的景觀認識香港。"},{"en":"Victoria Harbour matters because it connects history, transport, trade, and public memory.","zh":"維多利亞港很重要，因為它連接歷史、交通、貿易和公共記憶。"},{"en":"This name often represents Hong Kong’s image as a harbour city.","zh":"這個名稱常代表香港作為海港城市的形象。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"more than a strip of valuable land","meaning":"不只是一片有價值的土地","examples":[{"en":"Victoria Harbour is more than a strip of valuable land.","zh":"維多利亞港不只是一片有價值的土地。"},{"en":"More than a strip of valuable land means it has cultural and public meaning beyond its price.","zh":"不只是一片有價值的土地，是指它除了價格以外，還有文化和公共意義。"},{"en":"A school playground is more than a strip of land because children build memories there.","zh":"學校操場不只是一片土地，因為孩子會在那裡建立回憶。"},{"en":"Seeing the harbour as more than land helps planners protect its social value.","zh":"把海港看成不只是土地，有助規劃者保護它的社會價值。"},{"en":"This phrase rejects a purely commercial view of place.","zh":"這個短語否定只從商業角度看地方的想法。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"a strip of valuable land","meaning":"一幅有價值的土地","examples":[{"en":"Developers may see the harbourfront as a strip of valuable land.","zh":"發展商可能把海濱視為一幅有價值的土地。"},{"en":"A strip of valuable land is a narrow piece of land that can bring high financial value.","zh":"一幅有價值的土地是指能帶來高財政價值的一片土地。"},{"en":"A site beside a railway station may be seen as a strip of valuable land by property companies.","zh":"鐵路站旁邊的地盤可能被地產公司視為一幅有價值的土地。"},{"en":"Calling the harbourfront a strip of valuable land can make people forget its public meaning.","zh":"把海濱稱為一幅有價值的土地，可能令人忘記它的公共意義。"},{"en":"This phrase is often used when land is viewed through money and development.","zh":"當土地被金錢和發展角度看待時，這個短語常會出現。"}],"source":"2015 Q5.pdf","sourcePage":1},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, Victoria Harbour is the city’s breathing space.","zh":"事實上，維多利亞港是這座城市的透氣空間。"},{"en":"In fact introduces the real or stronger truth behind a point.","zh":"事實上用來引出一個觀點背後真正或更有力的事實。"},{"en":"Some think parks waste land; in fact, they protect public health.","zh":"有些人認為公園浪費土地；事實上，公園保護公共健康。"},{"en":"Writers use in fact to correct a narrow or mistaken view.","zh":"作者使用「事實上」來修正狹窄或錯誤的看法。"},{"en":"This phrase makes the next statement sound more certain and important.","zh":"這個短語令下一句聽起來更確定和重要。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"breathing space","meaning":"透氣空間","examples":[{"en":"The harbour is the city’s breathing space.","zh":"海港是這座城市的透氣空間。"},{"en":"Breathing space means room to relax, move, and feel less crowded.","zh":"透氣空間是指讓人放鬆、走動和感到沒那麼擠迫的空間。"},{"en":"A small park gives breathing space to residents living in high-rise buildings.","zh":"小公園為住在高樓大廈的居民提供透氣空間。"},{"en":"Cities need breathing space because people cannot live well among concrete alone.","zh":"城市需要透氣空間，因為人不能只在石屎之中好好生活。"},{"en":"This phrase uses the image of breathing to show the need for open public land.","zh":"這個短語用呼吸的意象，顯示開放公共土地的需要。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"shared memory","meaning":"共同記憶","examples":[{"en":"Victoria Harbour is part of the city’s shared memory.","zh":"維多利亞港是這座城市共同記憶的一部分。"},{"en":"Shared memory means memories, stories, and experiences that many people in a community recognise together.","zh":"共同記憶是指社區中許多人一起認得的回憶、故事和經歷。"},{"en":"A public square can become shared memory when generations gather there for festivals.","zh":"當幾代人在公共廣場聚集慶祝節日時，那裡可以成為共同記憶。"},{"en":"Protecting places with shared memory helps a city keep its identity.","zh":"保護有共同記憶的地方，有助城市保存身份。"},{"en":"This phrase shows that a place can carry emotional and historical meaning.","zh":"這個短語顯示一個地方可以承載情感和歷史意義。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"public face","meaning":"公眾形象；城市門面","examples":[{"en":"The harbour is also Hong Kong’s public face.","zh":"海港也是香港的城市門面。"},{"en":"Public face means the image a city, person, or organisation shows to the outside world.","zh":"公眾形象或城市門面，是指城市、個人或機構向外界展示的形象。"},{"en":"A clean waterfront can become the public face of a city for tourists and residents.","zh":"潔淨的海濱可以成為城市面向遊客和居民的門面。"},{"en":"If the harbourfront is blocked by private towers, the city’s public face may feel less welcoming.","zh":"如果海濱被私人高樓阻擋，城市門面可能感覺沒那麼歡迎人。"},{"en":"This phrase connects physical appearance with reputation.","zh":"這個短語把外觀與聲譽連接起來。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"land shortage","meaning":"土地短缺","examples":[{"en":"Land shortage has increased pressure on the harbourfront.","zh":"土地短缺增加了海濱所承受的壓力。"},{"en":"Land shortage means there is not enough land for housing, business, transport, or public needs.","zh":"土地短缺是指沒有足夠土地應付房屋、商業、交通或公共需要。"},{"en":"In a crowded city, land shortage can make every empty site seem valuable.","zh":"在擠迫城市中，土地短缺會令每一幅空地都看似有價值。"},{"en":"Land shortage may push governments to consider difficult planning choices.","zh":"土地短缺可能迫使政府考慮困難的規劃選擇。"},{"en":"This phrase explains why development pressure becomes strong.","zh":"這個短語解釋為何發展壓力會變強。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"commercial pressure","meaning":"商業壓力","examples":[{"en":"Commercial pressure may threaten open harbourfront areas.","zh":"商業壓力可能威脅開放的海濱地區。"},{"en":"Commercial pressure means the force to use something for business, profit, or private development.","zh":"商業壓力是指把某物用於商業、盈利或私人發展的推力。"},{"en":"A quiet street may face commercial pressure when chain stores want to replace small shops.","zh":"當連鎖店想取代小店時，一條安靜街道可能面對商業壓力。"},{"en":"Commercial pressure can reduce public space if profit becomes the only priority.","zh":"如果盈利成為唯一優先事項，商業壓力可能減少公共空間。"},{"en":"This phrase shows how money can influence planning decisions.","zh":"這個短語顯示金錢如何影響規劃決定。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"worsening","meaning":"惡化","examples":[{"en":"Land shortage and commercial pressure are worsening.","zh":"土地短缺和商業壓力正在惡化。"},{"en":"Worsening means becoming more serious, difficult, or harmful.","zh":"惡化是指變得更嚴重、更困難或更有害。"},{"en":"Traffic congestion is worsening when journeys take longer every month.","zh":"如果車程每個月都變長，交通擠塞就是正在惡化。"},{"en":"If pressure on public land is worsening, planning decisions become more urgent.","zh":"如果公共土地壓力正在惡化，規劃決定就變得更迫切。"},{"en":"This word shows that a problem is not staying the same but getting worse.","zh":"這個詞顯示問題不是維持不變，而是變得更差。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"be tempted to","meaning":"可能會忍不住想","examples":[{"en":"Developers may be tempted to convert these sites into private developments.","zh":"發展商可能會忍不住想把這些地點改建成私人發展項目。"},{"en":"To be tempted to do something means to feel strongly drawn to do it, even if it may not be wise.","zh":"可能會忍不住想做某事，是指很想做，即使那樣做未必明智。"},{"en":"A student may be tempted to skip revision when friends invite them out.","zh":"當朋友邀請外出時，學生可能會忍不住想跳過溫習。"},{"en":"Developers may be tempted by profit when waterfront land has high value.","zh":"當海濱土地價值高時，發展商可能會被盈利吸引。"},{"en":"This phrase suggests desire that needs careful control.","zh":"這個短語表示一種需要小心控制的欲望。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"convert these sites into","meaning":"把這些地點改建成","examples":[{"en":"Developers may convert these sites into flats, offices and shopping malls.","zh":"發展商可能把這些地點改建成住宅單位、辦公室和商場。"},{"en":"To convert these sites into something means to change the land for a new use.","zh":"把這些地點改建成某物，是指把土地改作新的用途。"},{"en":"An old factory site can be converted into housing, a park, or a cultural centre.","zh":"舊工廠地點可以被改建成房屋、公園或文化中心。"},{"en":"Converting public waterfront sites into private buildings may permanently change access.","zh":"把公共海濱地點改建成私人建築，可能永久改變使用權。"},{"en":"This phrase focuses on changing the function of a place.","zh":"這個短語著重改變一個地方的功能。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"flats, offices and shopping malls","meaning":"住宅單位、辦公室和商場","examples":[{"en":"The sites could be converted into flats, offices and shopping malls.","zh":"這些地點可能被改建成住宅單位、辦公室和商場。"},{"en":"Flats, offices and shopping malls are private or commercial buildings used for living, work, and shopping.","zh":"住宅單位、辦公室和商場是用作居住、工作和購物的私人或商業建築。"},{"en":"These developments may bring revenue, but they do not always create open public space.","zh":"這些發展項目可能帶來收入，但不一定創造開放公共空間。"},{"en":"If every waterfront site becomes flats, offices and shopping malls, ordinary people may lose access.","zh":"如果每個海濱地點都變成住宅單位、辦公室和商場，普通人可能失去使用權。"},{"en":"This phrase represents a development model focused on property and commerce.","zh":"這個短語代表以物業和商業為中心的發展模式。"}],"source":"2015 Q5.pdf","sourcePage":2},{"front":"so as to increase","meaning":"以增加","examples":[{"en":"Developers may build on the harbourfront so as to increase supply and revenue.","zh":"發展商可能在海濱興建項目，以增加供應和收入。"},{"en":"So as to increase means in order to make something larger or greater.","zh":"以增加是指為了令某物變得更多或更大。"},{"en":"A school may open more classes so as to increase the number of available places.","zh":"學校可能開設更多班級，以增加可用學額。"},{"en":"Businesses may change a site so as to increase profit, but public value must also be considered.","zh":"企業可能改變一個地點以增加利潤，但公共價值也必須被考慮。"},{"en":"This phrase clearly explains the purpose behind an action.","zh":"這個短語清楚解釋行動背後的目的。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"supply and revenue","meaning":"供應和收入","examples":[{"en":"Private development may increase supply and revenue.","zh":"私人發展項目可能增加供應和收入。"},{"en":"Supply and revenue mean the amount of available goods or space and the money earned from them.","zh":"供應和收入是指可用貨品或空間的數量，以及由此賺取的金錢。"},{"en":"Building more flats may increase housing supply and government revenue.","zh":"興建更多單位可能增加房屋供應和政府收入。"},{"en":"Supply and revenue matter, but they should not erase public access.","zh":"供應和收入很重要，但不應抹走公眾使用權。"},{"en":"This phrase is often used when discussing economic benefits of development.","zh":"這個短語常用於討論發展帶來的經濟利益。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, building over the harbourfront would be a serious mistake.","zh":"就我而言，在海濱上興建建築會是一個嚴重錯誤。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"就我而言，是指以我的意見或角度來說。"},{"en":"As far as I am concerned, public parks are essential in a crowded city.","zh":"就我而言，公共公園在擠迫城市中是必要的。"},{"en":"This phrase lets the writer state a clear personal judgement.","zh":"這個短語讓作者清楚表達個人判斷。"},{"en":"It is useful in letters when expressing a firm position politely.","zh":"在信件中禮貌地表達堅定立場時，這個短語很有用。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"a serious mistake","meaning":"嚴重錯誤","examples":[{"en":"Turning the harbourfront into private developments would be a serious mistake.","zh":"把海濱變成私人發展項目會是一個嚴重錯誤。"},{"en":"A serious mistake is an error that may cause important or long-lasting harm.","zh":"嚴重錯誤是可能造成重要或長遠傷害的錯誤。"},{"en":"Selling a public playground without replacing it would be a serious mistake.","zh":"出售公共遊樂場而不作替代安排會是嚴重錯誤。"},{"en":"Some planning mistakes are serious because they cannot easily be undone.","zh":"有些規劃錯誤很嚴重，因為它們不容易被撤回。"},{"en":"This phrase shows that the writer believes the decision would be deeply harmful.","zh":"這個短語顯示作者認為該決定會造成重大傷害。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"the remaining harbourfront","meaning":"餘下的海濱地區","examples":[{"en":"The remaining harbourfront should be protected.","zh":"餘下的海濱地區應受到保護。"},{"en":"The remaining harbourfront means the waterfront areas that are still not privately developed or fully built over.","zh":"餘下的海濱地區是指仍未被私人發展或完全建滿的海旁地區。"},{"en":"The remaining harbourfront is precious because much urban land has already been used.","zh":"餘下的海濱地區很珍貴，因為許多城市土地已被使用。"},{"en":"If the remaining harbourfront is lost, future generations may have fewer public spaces.","zh":"如果餘下的海濱地區失去，下一代可能會有更少公共空間。"},{"en":"This phrase stresses that what is left should be handled carefully.","zh":"這個短語強調剩下的東西應被小心處理。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"should be protected","meaning":"應該受到保護","examples":[{"en":"The remaining harbourfront should be protected for public use.","zh":"餘下的海濱地區應受到保護，供公眾使用。"},{"en":"Should be protected means action should be taken to keep something safe from harm or loss.","zh":"應該受到保護，是指應採取行動，使某物免受傷害或失去。"},{"en":"Historic buildings should be protected because they carry community memory.","zh":"歷史建築應受到保護，因為它們承載社區記憶。"},{"en":"Public land should be protected when private development would remove shared access.","zh":"當私人發展會移除共同使用權時，公共土地應受到保護。"},{"en":"This phrase shows a clear recommendation, not just a preference.","zh":"這個短語顯示清晰建議，而不只是偏好。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"promotes social fairness","meaning":"促進社會公平","examples":[{"en":"An open harbourfront promotes social fairness.","zh":"開放的海濱促進社會公平。"},{"en":"Promotes social fairness means helps different people enjoy more equal opportunities or benefits.","zh":"促進社會公平，是指幫助不同人享有更平等的機會或利益。"},{"en":"Free public sports facilities promote social fairness because low-income families can use them too.","zh":"免費公共運動設施促進社會公平，因為低收入家庭也可以使用。"},{"en":"Open waterfronts promote fairness by serving rich and poor citizens alike.","zh":"開放海濱透過同時服務富有和貧窮市民來促進公平。"},{"en":"This phrase links planning decisions with justice in daily life.","zh":"這個短語把規劃決定與日常生活中的公義連接起來。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"improves urban well-being","meaning":"改善城市福祉","examples":[{"en":"Open harbourfront space improves urban well-being.","zh":"開放海濱空間改善城市福祉。"},{"en":"Improves urban well-being means makes city life healthier, calmer, and more pleasant.","zh":"改善城市福祉，是指令城市生活更健康、更平靜和更愉快。"},{"en":"Parks improve urban well-being by giving residents places to walk, rest, and meet friends.","zh":"公園透過提供散步、休息和見朋友的地方來改善城市福祉。"},{"en":"Good public space can improve well-being by reducing stress in crowded districts.","zh":"良好公共空間可以透過減少擠迫地區的壓力來改善福祉。"},{"en":"This phrase focuses on people’s quality of life in cities.","zh":"這個短語著重城市中人們的生活質素。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"strengthens long-term appeal","meaning":"增強長遠吸引力","examples":[{"en":"Protecting the harbourfront strengthens Hong Kong’s long-term appeal.","zh":"保護海濱能增強香港的長遠吸引力。"},{"en":"Strengthens long-term appeal means makes a place more attractive over many years.","zh":"增強長遠吸引力，是指令一個地方在多年之後仍更吸引人。"},{"en":"A city strengthens its long-term appeal when it protects parks, heritage, and clean waterfronts.","zh":"城市保護公園、歷史遺產和潔淨海濱時，就是增強長遠吸引力。"},{"en":"Short-term profit may fade, but public beauty can strengthen long-term appeal.","zh":"短期利潤可能消退，但公共美景可以增強長遠吸引力。"},{"en":"This phrase connects present planning with future attractiveness.","zh":"這個短語把現在的規劃與未來吸引力連接起來。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"first and foremost","meaning":"首先；最重要的是","examples":[{"en":"First and foremost, an open harbourfront belongs equally to everyone.","zh":"首先，開放海濱平等地屬於所有人。"},{"en":"First and foremost introduces the most important point before other reasons.","zh":"首先或最重要的是，用來在其他理由前引出最重要的一點。"},{"en":"First and foremost, a school should be a safe place for students.","zh":"最重要的是，學校應是學生安全的地方。"},{"en":"Writers use this phrase when they want readers to focus on the central argument.","zh":"作者想讓讀者集中於核心論點時，會使用這個短語。"},{"en":"It makes the first reason sound especially important.","zh":"它令第一個理由聽起來特別重要。"}],"source":"2015 Q5.pdf","sourcePage":3},{"front":"public assets","meaning":"公共資產","examples":[{"en":"An open harbourfront is one of the few public assets in Hong Kong.","zh":"開放海濱是香港少數公共資產之一。"},{"en":"Public assets are places, facilities, or resources owned or shared for public benefit.","zh":"公共資產是為公眾利益而擁有或共享的地方、設施或資源。"},{"en":"Libraries, parks, roads, and public squares can be public assets.","zh":"圖書館、公園、道路和公共廣場都可以是公共資產。"},{"en":"Public assets should be managed for long-term community value, not only quick profit.","zh":"公共資產應為長遠社區價值而管理，而不只是為快速盈利。"},{"en":"This phrase presents open space as something citizens collectively benefit from.","zh":"這個短語把開放空間呈現為市民共同受惠的東西。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"belongs equally to everyone","meaning":"平等地屬於所有人","examples":[{"en":"The harbourfront belongs equally to everyone.","zh":"海濱平等地屬於所有人。"},{"en":"Belongs equally to everyone means all people have the same right to enjoy or use it.","zh":"平等地屬於所有人，是指所有人都有相同權利享用或使用它。"},{"en":"A public beach belongs equally to everyone when no group can block others from entering.","zh":"當沒有任何群體可以阻止別人進入時，公共沙灘就是平等地屬於所有人。"},{"en":"If a space belongs equally to everyone, its design should consider children, elderly people, and wheelchair users.","zh":"如果一個空間平等地屬於所有人，其設計應考慮兒童、長者和輪椅使用者。"},{"en":"This phrase strongly supports fairness in public planning.","zh":"這個短語有力支持公共規劃中的公平。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"luxury flats","meaning":"豪宅單位","examples":[{"en":"Luxury flats may look impressive, but they are not accessible to everyone.","zh":"豪宅單位可能看起來氣派，但並非人人可使用。"},{"en":"Luxury flats are expensive homes designed for wealthy buyers or tenants.","zh":"豪宅單位是為富有買家或租客而設的昂貴住宅。"},{"en":"A tower of luxury flats may raise property value but reduce ordinary public access.","zh":"一座豪宅大廈可能提高物業價值，但減少普通公眾使用權。"},{"en":"Luxury flats can create a private view where public space could have served many people.","zh":"豪宅單位可能創造私人景觀，而原本公共空間可服務很多人。"},{"en":"This phrase often represents development that benefits a limited group.","zh":"這個短語常代表只惠及有限群體的發展。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"grade-A offices","meaning":"甲級寫字樓","examples":[{"en":"Grade-A offices are accessible mainly to those who can afford them.","zh":"甲級寫字樓主要供負擔得起的人使用。"},{"en":"Grade-A offices are high-quality office spaces in prime business locations.","zh":"甲級寫字樓是位於主要商業地段的高質素辦公空間。"},{"en":"Large companies may rent grade-A offices for their staff and clients.","zh":"大公司可能租用甲級寫字樓給員工和客戶使用。"},{"en":"Grade-A offices can bring business activity, but they do not replace public open space.","zh":"甲級寫字樓可以帶來商業活動，但不能取代公共開放空間。"},{"en":"This phrase suggests commercial development aimed at wealthy firms.","zh":"這個短語表示面向富有企業的商業發展。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"look impressive","meaning":"看起來氣派","examples":[{"en":"Luxury flats and grade-A offices may look impressive.","zh":"豪宅單位和甲級寫字樓可能看起來氣派。"},{"en":"To look impressive means to appear grand, attractive, or important.","zh":"看起來氣派是指外表顯得宏偉、吸引或重要。"},{"en":"A tall glass building may look impressive from a distance.","zh":"一座玻璃高樓從遠處看可能很氣派。"},{"en":"Something that looks impressive may still fail to serve ordinary people.","zh":"看起來氣派的東西仍可能無法服務普通人。"},{"en":"This phrase reminds readers that appearance is not the same as public value.","zh":"這個短語提醒讀者，外觀不等於公共價值。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"accessible mainly to","meaning":"主要供……使用","examples":[{"en":"These developments are accessible mainly to people who can afford them.","zh":"這些發展項目主要供負擔得起的人使用。"},{"en":"Accessible mainly to means used mostly by a particular group, not by everyone.","zh":"主要供某些人使用，是指多數由特定群體使用，而不是人人可用。"},{"en":"Private clubs are accessible mainly to members who can pay the fees.","zh":"私人會所主要供能支付會費的會員使用。"},{"en":"If harbourfront land becomes accessible mainly to wealthy residents, social fairness suffers.","zh":"如果海濱土地變成主要供富裕居民使用，社會公平就會受損。"},{"en":"This phrase points out limits on who can use a place or service.","zh":"這個短語指出誰可以使用某地方或服務的限制。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"those who can afford them","meaning":"負擔得起的人","examples":[{"en":"Luxury developments are mainly for those who can afford them.","zh":"豪華發展項目主要供負擔得起的人使用。"},{"en":"Those who can afford them means people with enough money to pay for those things.","zh":"負擔得起的人，是指有足夠金錢支付那些東西的人。"},{"en":"Private gyms may serve only those who can afford expensive membership fees.","zh":"私人健身中心可能只服務負擔得起昂貴會費的人。"},{"en":"Public spaces should not be limited to those who can afford them.","zh":"公共空間不應只限負擔得起的人使用。"},{"en":"This phrase highlights the difference between wealth-based access and public access.","zh":"這個短語突出基於財富的使用權與公共使用權之間的差別。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, a promenade can be used by everyone.","zh":"相比之下，海濱長廊可供所有人使用。"},{"en":"By contrast introduces a clear difference from the previous point.","zh":"相比之下，用來引出與前一點明顯不同的情況。"},{"en":"Private towers serve a few people; by contrast, public parks serve whole districts.","zh":"私人高樓服務少數人；相比之下，公共公園服務整個地區。"},{"en":"Writers use by contrast to make two ideas easier to compare.","zh":"作者使用「相比之下」令兩個想法更容易比較。"},{"en":"This phrase helps show why public space differs from private development.","zh":"這個短語幫助顯示公共空間與私人發展的不同。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"a promenade","meaning":"海濱長廊","examples":[{"en":"A promenade can be used by people from different districts.","zh":"海濱長廊可供來自不同地區的人使用。"},{"en":"A promenade is a public walkway, often beside the sea, where people can stroll and enjoy the view.","zh":"海濱長廊是公共行人道，通常位於海邊，讓人散步和欣賞景色。"},{"en":"Families may visit a promenade after dinner to walk and talk.","zh":"家庭可能晚飯後到海濱長廊散步聊天。"},{"en":"A good promenade should be wide, safe, shaded, and open to all.","zh":"良好的海濱長廊應寬闊、安全、有遮蔭，並向所有人開放。"},{"en":"This word describes public space that connects leisure with movement.","zh":"這個詞描述把休閒與步行連接起來的公共空間。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"a lawn","meaning":"草地","examples":[{"en":"A lawn beside the harbour can serve families and elderly residents.","zh":"海港旁邊的草地可以服務家庭和年長居民。"},{"en":"A lawn is an open area covered with grass where people can sit, play, or rest.","zh":"草地是覆蓋青草的開放地方，人們可以坐下、玩耍或休息。"},{"en":"Children may run on a lawn while parents sit nearby.","zh":"孩子可能在草地上奔跑，而父母坐在旁邊。"},{"en":"A public lawn gives city residents soft open ground instead of only concrete.","zh":"公共草地給城市居民柔軟的開放地面，而不只是石屎。"},{"en":"This word suggests simple outdoor space for everyday enjoyment.","zh":"這個詞表示可供日常享受的簡單戶外空間。"}],"source":"2015 Q5.pdf","sourcePage":4},{"front":"sitting-out area","meaning":"休憩處","examples":[{"en":"A sitting-out area gives ordinary people a place to rest.","zh":"休憩處給普通人一個休息的地方。"},{"en":"A sitting-out area is a small public space with seats where people can pause and relax.","zh":"休憩處是有座椅的小型公共空間，讓人停下來放鬆。"},{"en":"Elderly residents may use a sitting-out area after buying food at the market.","zh":"年長居民在街市買食物後，可能會使用休憩處。"},{"en":"Sitting-out areas matter in crowded districts because many homes are small.","zh":"休憩處在擠迫地區很重要，因為許多家居空間細小。"},{"en":"This phrase describes modest but important public comfort.","zh":"這個短語描述簡單但重要的公共舒適空間。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"without paying a cent","meaning":"不用付一分錢","examples":[{"en":"People can enjoy the harbourfront without paying a cent.","zh":"人們不用付一分錢也可以享受海濱。"},{"en":"Without paying a cent means without spending any money at all.","zh":"不用付一分錢，是指完全不用花任何金錢。"},{"en":"Children can play in a public park without paying a cent.","zh":"孩子可以不用付一分錢在公共公園玩耍。"},{"en":"Free access matters because not every family can afford paid leisure activities.","zh":"免費使用很重要，因為不是每個家庭都負擔得起收費休閒活動。"},{"en":"This phrase highlights the fairness of public space.","zh":"這個短語突出公共空間的公平性。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"this distinction matters","meaning":"這個分別很重要","examples":[{"en":"This distinction matters in a crowded city.","zh":"在擠迫城市中，這個分別很重要。"},{"en":"This distinction matters means this difference is important and affects real life.","zh":"這個分別很重要，是指這種差異重要並會影響現實生活。"},{"en":"The distinction between public and private space matters when many families live in small flats.","zh":"當許多家庭住在細小單位時，公共與私人空間之間的分別很重要。"},{"en":"A small difference in access can matter greatly to people with fewer resources.","zh":"使用權上的小差別，對資源較少的人可能十分重要。"},{"en":"This phrase tells readers not to ignore an important contrast.","zh":"這個短語告訴讀者不要忽視重要對比。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"private space","meaning":"私人空間","examples":[{"en":"Private space is limited in Hong Kong.","zh":"香港的私人空間有限。"},{"en":"Private space means space controlled by individuals, families, or private owners.","zh":"私人空間是由個人、家庭或私人業主管理的空間。"},{"en":"A small flat may give a family very little private space for rest or study.","zh":"細小單位可能給家庭很少休息或學習的私人空間。"},{"en":"When private space is limited, public parks become more important.","zh":"當私人空間有限時，公共公園就變得更重要。"},{"en":"This phrase helps explain why open public areas matter in dense cities.","zh":"這個短語幫助解釋為何開放公共地方在密集城市中重要。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"daily life is crowded","meaning":"日常生活擠迫","examples":[{"en":"Daily life is crowded in Hong Kong.","zh":"香港的日常生活擠迫。"},{"en":"Daily life is crowded means people’s normal routines take place in busy, tight, or limited spaces.","zh":"日常生活擠迫，是指人們的平常生活在繁忙、狹窄或有限空間中進行。"},{"en":"Daily life is crowded when trains, homes, streets, and shops are all packed.","zh":"當火車、家居、街道和商店都擠滿人時，日常生活就是擠迫的。"},{"en":"Crowded daily life can make people value quiet open areas more.","zh":"擠迫的日常生活會令人更重視安靜開放的地方。"},{"en":"This phrase describes pressure felt not once, but every day.","zh":"這個短語描述不是一次性，而是每天都感受到的壓力。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"a form of everyday dignity","meaning":"一種日常尊嚴","examples":[{"en":"Public space is a form of everyday dignity.","zh":"公共空間是一種日常尊嚴。"},{"en":"A form of everyday dignity means something that helps ordinary people live with comfort, respect, and freedom.","zh":"一種日常尊嚴，是指幫助普通人以舒適、尊重和自由生活的東西。"},{"en":"A clean public toilet can be a form of everyday dignity for workers and elderly people.","zh":"乾淨的公共洗手間可以是工人和長者的一種日常尊嚴。"},{"en":"Open harbourfront space gives dignity because people can rest without needing to buy anything.","zh":"開放海濱空間帶來尊嚴，因為人們不用購物也能休息。"},{"en":"This phrase turns public space from a luxury into a basic human need.","zh":"這個短語把公共空間由奢侈品變成基本人的需要。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"instead of a decorative extra","meaning":"而不是額外裝飾","examples":[{"en":"Public space is a form of dignity instead of a decorative extra.","zh":"公共空間是一種尊嚴，而不是額外裝飾。"},{"en":"Instead of a decorative extra means not merely something added to look nice.","zh":"而不是額外裝飾，是指不只是為了好看而加上的東西。"},{"en":"A shaded walkway is necessary for elderly residents, instead of a decorative extra.","zh":"對年長居民來說，有遮蔭的行人道是必要的，而不是額外裝飾。"},{"en":"Public space should be planned as daily support, not as decoration after buildings are finished.","zh":"公共空間應被規劃為日常支援，而不是建築完成後才加入的裝飾。"},{"en":"This phrase contrasts real social need with surface appearance.","zh":"這個短語對比真正社會需要與表面外觀。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"picnic","meaning":"野餐","examples":[{"en":"Families can picnic by the harbour.","zh":"家庭可以在海港旁野餐。"},{"en":"To picnic means to eat a simple meal outdoors, often in a park or open space.","zh":"野餐是指在戶外吃簡單餐點，通常在公園或開放空間。"},{"en":"A family may picnic on a lawn because it is cheaper than eating in a restaurant.","zh":"一個家庭可能在草地上野餐，因為這比在餐廳吃飯便宜。"},{"en":"Public lawns make picnics possible for people who do not have private gardens.","zh":"公共草地讓沒有私人花園的人也可以野餐。"},{"en":"This word shows how open space supports simple family leisure.","zh":"這個詞顯示開放空間如何支援簡單家庭休閒。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"domestic helpers","meaning":"家庭傭工","examples":[{"en":"Domestic helpers can rest on Sundays at open public spaces.","zh":"家庭傭工可以在星期日在開放公共空間休息。"},{"en":"Domestic helpers are workers who help families with household tasks, childcare, or elderly care.","zh":"家庭傭工是協助家庭處理家務、照顧孩子或照顧長者的工人。"},{"en":"Many domestic helpers need public spaces on rest days because they may not have private rooms for leisure.","zh":"許多家庭傭工在休息日需要公共空間，因為她們未必有私人休閒房間。"},{"en":"Open harbourfront areas can give domestic helpers a dignified place to gather and relax.","zh":"開放海濱地區可以給家庭傭工一個有尊嚴的聚集和放鬆地方。"},{"en":"This phrase reminds planners to consider workers who are often overlooked.","zh":"這個短語提醒規劃者考慮常被忽視的工人。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"practise photography","meaning":"練習攝影","examples":[{"en":"Teenagers can practise photography along the harbourfront.","zh":"青少年可以沿着海濱練習攝影。"},{"en":"To practise photography means to take photos regularly in order to improve skill.","zh":"練習攝影是指定期拍照，以提升技巧。"},{"en":"A student may practise photography by taking pictures of light, water, people, and buildings.","zh":"學生可能透過拍攝光線、水面、人物和建築來練習攝影。"},{"en":"Public places help young people practise creative skills without paying for a studio.","zh":"公共地方幫助年輕人不用支付影樓費用也能練習創意技巧。"},{"en":"This phrase shows how open space can support learning and creativity.","zh":"這個短語顯示開放空間如何支援學習和創意。"}],"source":"2015 Q5.pdf","sourcePage":5},{"front":"elderly residents","meaning":"年長居民","examples":[{"en":"Elderly residents can exercise while looking across the water.","zh":"年長居民可以一邊望向水面，一邊做運動。"},{"en":"Elderly residents are older people who live in a particular district or city.","zh":"年長居民是居住在某地區或城市的較年長人士。"},{"en":"Elderly residents may need safe, flat, and nearby places for walking.","zh":"年長居民可能需要安全、平坦和就近的地方散步。"},{"en":"Harbourfront promenades can help elderly residents stay active and socially connected.","zh":"海濱長廊可以幫助年長居民保持活躍和社交連繫。"},{"en":"This phrase reminds planners to consider age-friendly public design.","zh":"這個短語提醒規劃者考慮長者友善的公共設計。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"looking across the water","meaning":"望向水面","examples":[{"en":"Elderly residents can exercise while looking across the water.","zh":"年長居民可以一邊望向水面，一邊做運動。"},{"en":"Looking across the water means gazing over a harbour, river, or sea toward the other side.","zh":"望向水面是指望過海港、河流或海面，看向另一邊。"},{"en":"A person sitting on a bench may feel calmer while looking across the water.","zh":"坐在長椅上的人望向水面時，可能會感到更平靜。"},{"en":"Views across water can make exercise and walking more pleasant.","zh":"望向水面的景觀可以令運動和散步更愉快。"},{"en":"This phrase connects physical activity with visual relief.","zh":"這個短語把身體活動與視覺放鬆連接起來。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"only when","meaning":"只有當……時","examples":[{"en":"Only when waterfront land remains open can ordinary citizens enjoy the harbour fully.","zh":"只有當海濱土地保持開放時，普通市民才能充分享受海港。"},{"en":"Only when introduces the necessary condition for something to happen.","zh":"只有當……時，用來引出某事發生所需的必要條件。"},{"en":"Only when a park is truly public can all families use it freely.","zh":"只有當公園真正公共時，所有家庭才能自由使用。"},{"en":"This structure strongly shows that one result depends on one condition.","zh":"這個句式強烈顯示一個結果取決於一個條件。"},{"en":"It helps writers emphasise what must happen first.","zh":"它幫助作者強調甚麼必須先發生。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"waterfront land","meaning":"海濱土地","examples":[{"en":"Waterfront land should remain open to ordinary citizens.","zh":"海濱土地應繼續向普通市民開放。"},{"en":"Waterfront land is land beside a harbour, river, lake, or sea.","zh":"海濱土地是位於海港、河流、湖泊或海邊的土地。"},{"en":"Waterfront land is often valuable because it has views, air, and public attraction.","zh":"海濱土地通常很有價值，因為它有景觀、空氣和公共吸引力。"},{"en":"If waterfront land is blocked by private buildings, citizens lose direct contact with the water.","zh":"如果海濱土地被私人建築阻擋，市民會失去與水面的直接接觸。"},{"en":"This phrase is important in city planning because such land is limited and symbolic.","zh":"這個短語在城市規劃中重要，因為這類土地有限且具象徵意義。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"ordinary citizens","meaning":"普通市民","examples":[{"en":"Ordinary citizens should be able to enjoy the harbour.","zh":"普通市民應能享受海港。"},{"en":"Ordinary citizens are regular members of the public, not officials, developers, or wealthy elites.","zh":"普通市民是一般公眾成員，而不是官員、發展商或富裕精英。"},{"en":"Ordinary citizens need parks, clinics, libraries, and transport they can actually use.","zh":"普通市民需要自己真正能使用的公園、診所、圖書館和交通。"},{"en":"Public planning should ask how ordinary citizens live day by day.","zh":"公共規劃應詢問普通市民每天如何生活。"},{"en":"This phrase brings attention back to everyday people.","zh":"這個短語把注意力帶回日常生活中的人。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"walled off by privilege","meaning":"被特權圍起來","examples":[{"en":"The harbour should not be walled off by privilege.","zh":"海港不應被特權圍起來。"},{"en":"Walled off by privilege means blocked from ordinary people because only richer or more powerful groups can enter.","zh":"被特權圍起來，是指因只有較富有或較有權力的群體能進入，而把普通人阻隔在外。"},{"en":"A beach is walled off by privilege if only luxury residents can reach it.","zh":"如果只有豪宅居民能到達沙灘，那片沙灘就是被特權圍起來。"},{"en":"When public views are walled off by privilege, a city becomes less fair.","zh":"當公共景觀被特權圍起來時，城市會變得較不公平。"},{"en":"This phrase uses a wall image to criticise social exclusion.","zh":"這個短語用牆的意象批評社會排斥。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"turn such sites into","meaning":"把這些地方變成","examples":[{"en":"Turning such sites into private developments would reduce public access.","zh":"把這些地方變成私人發展項目會減少公眾使用權。"},{"en":"To turn such sites into something means to change those places into a different form or use.","zh":"把這些地方變成某物，是指把那些地方改變成另一種形式或用途。"},{"en":"Turning an old pier into a public museum can preserve memory and access.","zh":"把舊碼頭變成公共博物館，可以保存記憶和使用權。"},{"en":"Turning harbourfront sites into private towers may remove space for walking and sitting.","zh":"把海濱地點變成私人高樓，可能移除散步和坐下的空間。"},{"en":"This phrase focuses on the consequences of changing land use.","zh":"這個短語著重改變土地用途所帶來的後果。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"private developments","meaning":"私人發展項目","examples":[{"en":"Private developments would limit access to the harbourfront.","zh":"私人發展項目會限制使用海濱的機會。"},{"en":"Private developments are buildings or projects owned and operated mainly for private use or profit.","zh":"私人發展項目是主要為私人使用或盈利而擁有和營運的建築或項目。"},{"en":"Luxury housing estates and commercial towers are examples of private developments.","zh":"豪宅屋苑和商業高樓都是私人發展項目的例子。"},{"en":"Private developments may bring money, but they can also reduce shared public space.","zh":"私人發展項目可能帶來金錢，但也可能減少共享公共空間。"},{"en":"This phrase contrasts private benefit with public access.","zh":"這個短語對比私人利益與公眾使用權。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"replace a common good with","meaning":"以……取代公共利益","examples":[{"en":"Building private flats would replace a common good with a gated view.","zh":"興建私人住宅會以被圍起來的景觀取代公共利益。"},{"en":"To replace a common good with something means to remove a shared benefit and put a more limited benefit in its place.","zh":"以某物取代公共利益，是指移除共享好處，並放入一種較有限的好處。"},{"en":"Closing a public playground to build a private car park replaces a common good with private convenience.","zh":"關閉公共遊樂場來建私人停車場，就是以私人方便取代公共利益。"},{"en":"Replacing shared space with exclusive views can damage social fairness.","zh":"以專屬景觀取代共享空間，可能損害社會公平。"},{"en":"This phrase criticises development that narrows who benefits.","zh":"這個短語批評縮窄受惠者的發展方式。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"a common good","meaning":"公共利益；共有資源","examples":[{"en":"The harbourfront is a common good.","zh":"海濱是公共利益。"},{"en":"A common good is something that benefits the community as a whole.","zh":"公共利益或共有資源，是指使整個社區受惠的東西。"},{"en":"Clean air, public parks, and safe streets are common goods.","zh":"清潔空氣、公共公園和安全街道都是公共利益。"},{"en":"A common good should not be controlled only by people who can pay the most.","zh":"公共利益不應只由出價最高的人控制。"},{"en":"This phrase presents public space as a shared social resource.","zh":"這個短語把公共空間呈現為共享的社會資源。"}],"source":"2015 Q5.pdf","sourcePage":6},{"front":"a gated view","meaning":"被圍起來的景觀","examples":[{"en":"Private developments would turn the harbour into a gated view.","zh":"私人發展項目會把海港變成被圍起來的景觀。"},{"en":"A gated view is a beautiful view that only a restricted group can enjoy.","zh":"被圍起來的景觀，是指只有受限制群體才能欣賞的美麗景觀。"},{"en":"If only residents behind gates can see the sea, the waterfront becomes a gated view.","zh":"如果只有閘門後的居民可以看到海，海濱就變成被圍起來的景觀。"},{"en":"A gated view removes the emotional and visual benefit from ordinary citizens.","zh":"被圍起來的景觀會把情感和視覺上的好處從普通市民手中拿走。"},{"en":"This phrase criticises private control over what should be publicly shared.","zh":"這個短語批評私人控制本應公共共享的東西。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"run counter to","meaning":"違背","examples":[{"en":"Private development runs counter to the spirit of a harbour city.","zh":"私人發展違背海港城市的精神。"},{"en":"To run counter to something means to go against it or conflict with it.","zh":"違背某事，是指與它相反或衝突。"},{"en":"Blocking a public waterfront runs counter to the idea of an open city.","zh":"阻擋公共海濱違背開放城市的理念。"},{"en":"A policy runs counter to fairness when it benefits only a small wealthy group.","zh":"當政策只惠及少數富有群體時，它就違背公平。"},{"en":"This phrase is useful for showing that an action contradicts a principle.","zh":"這個短語適合顯示某行動與原則矛盾。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"the spirit of a harbour city","meaning":"海港城市的精神","examples":[{"en":"Open access reflects the spirit of a harbour city.","zh":"開放使用權反映海港城市的精神。"},{"en":"The spirit of a harbour city means openness, movement, exchange, and connection with the water.","zh":"海港城市的精神是指開放、流動、交流和與水面的連繫。"},{"en":"A harbour city loses part of its spirit when citizens cannot walk beside the sea.","zh":"當市民不能在海邊散步時，海港城市就失去部分精神。"},{"en":"Public piers, promenades, and waterfront events can express the spirit of a harbour city.","zh":"公共碼頭、海濱長廊和海濱活動可以表達海港城市的精神。"},{"en":"This phrase links city identity with access to the harbour.","zh":"這個短語把城市身份與使用海港的權利連接起來。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, open harbourfront areas make Hong Kong more liveable.","zh":"此外，開放海濱地區令香港更宜居。"},{"en":"Moreover adds another important point to strengthen an argument.","zh":"此外用來加入另一個重要觀點，以加強論點。"},{"en":"Parks improve health; moreover, they help neighbours meet one another.","zh":"公園改善健康；此外，它們幫助鄰里彼此見面。"},{"en":"Writers use moreover when the next reason supports the same opinion.","zh":"當下一個理由支持同一意見時，作者會使用「此外」。"},{"en":"This word helps an argument sound organised and logical.","zh":"這個詞幫助論證聽起來有組織和合邏輯。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"healthier, calmer and more liveable","meaning":"更健康、更平靜、更宜居","examples":[{"en":"Open harbourfront areas make Hong Kong healthier, calmer and more liveable.","zh":"開放海濱地區令香港更健康、更平靜、更宜居。"},{"en":"Healthier, calmer and more liveable means better for the body, mind, and daily life.","zh":"更健康、更平靜、更宜居，是指對身體、心靈和日常生活更好。"},{"en":"A district becomes healthier, calmer and more liveable when people can walk safely near greenery.","zh":"當人們可以在綠化環境附近安全步行時，地區會變得更健康、更平靜和更宜居。"},{"en":"Public open space helps reduce stress and encourages exercise.","zh":"公共開放空間有助減少壓力並鼓勵運動。"},{"en":"This phrase describes city improvement from a human point of view.","zh":"這個短語從人的角度描述城市改善。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"densely built","meaning":"建築密集","examples":[{"en":"The more densely a city is built, the more urgently it needs breathing room.","zh":"城市建築越密集，就越迫切需要透氣空間。"},{"en":"Densely built means filled with many buildings close together.","zh":"建築密集是指很多建築物靠得很近。"},{"en":"A densely built district may have narrow streets, tall blocks, and little open space.","zh":"建築密集的地區可能有狹窄街道、高樓和很少開放空間。"},{"en":"Densely built cities need parks because residents have fewer places to relax.","zh":"建築密集的城市需要公園，因為居民較少地方放鬆。"},{"en":"This phrase explains why open land becomes more valuable in crowded places.","zh":"這個短語解釋為何開放土地在擠迫地方更有價值。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"urgently needs","meaning":"迫切需要","examples":[{"en":"A densely built city urgently needs breathing room.","zh":"建築密集的城市迫切需要透氣空間。"},{"en":"Urgently needs means needs something very quickly or seriously because the problem is pressing.","zh":"迫切需要是指因問題緊急而非常需要某物。"},{"en":"A hospital urgently needs more staff when patients are waiting too long.","zh":"當病人等候太久時，醫院迫切需要更多人手。"},{"en":"A crowded district urgently needs open space when residents have nowhere to rest.","zh":"當居民沒有地方休息時，擠迫地區迫切需要開放空間。"},{"en":"This phrase shows that the need is not minor or optional.","zh":"這個短語顯示需要並非微小或可有可無。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"breathing room","meaning":"透氣空間","examples":[{"en":"Hong Kong needs breathing room beside the harbour.","zh":"香港需要海港旁的透氣空間。"},{"en":"Breathing room means enough space to move, rest, and feel less pressured.","zh":"透氣空間是指足夠讓人走動、休息和減少壓力的空間。"},{"en":"Students need breathing room between exams so they can recover mentally.","zh":"學生在考試之間需要透氣空間，好讓心理恢復。"},{"en":"A city needs breathing room when buildings and crowds make life feel tight.","zh":"當建築和人群令生活感到擠迫時，城市需要透氣空間。"},{"en":"This phrase can describe both physical space and emotional relief.","zh":"這個短語既可描述實際空間，也可描述情緒紓緩。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"encourage walking","meaning":"鼓勵步行","examples":[{"en":"Parks and promenades encourage walking.","zh":"公園和海濱長廊鼓勵步行。"},{"en":"To encourage walking means to make people more likely to walk because the place is safe and pleasant.","zh":"鼓勵步行是指因地方安全舒適而令人更願意走路。"},{"en":"Shaded paths and benches encourage walking among elderly residents.","zh":"有遮蔭的小路和長椅鼓勵年長居民步行。"},{"en":"Walking becomes easier when streets are clean, open, and connected.","zh":"當街道乾淨、開放又連接良好時，步行會變得更容易。"},{"en":"This phrase links design with healthier daily habits.","zh":"這個短語把設計與更健康的日常習慣連接起來。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"jogging","meaning":"緩步跑","examples":[{"en":"Promenades encourage jogging and cycling.","zh":"海濱長廊鼓勵緩步跑和踩單車。"},{"en":"Jogging is running slowly and steadily for exercise.","zh":"緩步跑是為了運動而慢慢、穩定地跑步。"},{"en":"Many office workers go jogging after work to reduce stress.","zh":"許多辦公室員工下班後緩步跑，以減少壓力。"},{"en":"A wide harbourfront path makes jogging safer than running beside traffic.","zh":"寬闊的海濱小路比在交通旁跑步更安全。"},{"en":"This word shows how open public space supports physical health.","zh":"這個詞顯示開放公共空間如何支援身體健康。"}],"source":"2015 Q5.pdf","sourcePage":7},{"front":"cycling","meaning":"踩單車","examples":[{"en":"Open harbourfront areas encourage cycling.","zh":"開放海濱地區鼓勵踩單車。"},{"en":"Cycling means riding a bicycle for transport, exercise, or leisure.","zh":"踩單車是指為交通、運動或休閒而騎自行車。"},{"en":"Families may enjoy cycling along a safe waterfront path on weekends.","zh":"家庭可能在週末沿安全的海濱小路踩單車。"},{"en":"Cycling is easier when routes are separated from heavy traffic.","zh":"當路線與繁忙交通分開時，踩單車會更容易。"},{"en":"This word shows how public design can support active lifestyles.","zh":"這個詞顯示公共設計如何支援活躍生活方式。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"quiet conversation","meaning":"安靜交談","examples":[{"en":"Public open spaces encourage quiet conversation.","zh":"公共開放空間鼓勵安靜交談。"},{"en":"Quiet conversation means calm, gentle talking without noise or pressure.","zh":"安靜交談是指沒有噪音或壓力的平靜溫和對話。"},{"en":"Friends may have a quiet conversation on a bench beside the harbour.","zh":"朋友可能在海港旁的長椅上安靜交談。"},{"en":"Quiet conversations help people relax and maintain relationships.","zh":"安靜交談幫助人們放鬆和維持關係。"},{"en":"This phrase shows that public space supports emotional and social life, not only exercise.","zh":"這個短語顯示公共空間不只支援運動，也支援情感和社交生活。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"thereby improving","meaning":"從而改善","examples":[{"en":"Open spaces encourage exercise, thereby improving health.","zh":"開放空間鼓勵運動，從而改善健康。"},{"en":"Thereby improving means improving something as a result of the action just mentioned.","zh":"從而改善，是指因剛提到的行動而改善某事。"},{"en":"Planting trees gives shade, thereby improving comfort on hot days.","zh":"種樹提供樹蔭，從而改善炎熱日子的舒適度。"},{"en":"Safe walkways encourage walking, thereby improving residents’ daily activity.","zh":"安全行人道鼓勵步行，從而改善居民的日常活動量。"},{"en":"This phrase links an action directly to its positive result.","zh":"這個短語把行動直接連接到正面結果。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"physical and mental health","meaning":"身心健康","examples":[{"en":"Parks improve both physical and mental health.","zh":"公園改善身心健康。"},{"en":"Physical and mental health means the condition of the body and the mind.","zh":"身心健康是指身體和心理的狀況。"},{"en":"Walking improves physical health, while quiet views can support mental health.","zh":"步行改善身體健康，而安靜景觀可以支援心理健康。"},{"en":"Public open space protects health because it encourages movement and reduces stress.","zh":"公共開放空間透過鼓勵活動和減少壓力來保護健康。"},{"en":"This phrase reminds us that city planning affects more than buildings.","zh":"這個短語提醒我們，城市規劃影響的不只是建築物。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"existing promenades","meaning":"現有海濱長廊","examples":[{"en":"The existing promenades in Tsim Sha Tsui and Kwun Tong are useful public spaces.","zh":"尖沙咀和觀塘的現有海濱長廊是有用的公共空間。"},{"en":"Existing promenades are waterfront walkways that already exist and are being used.","zh":"現有海濱長廊是已經存在並正在被使用的海旁行人道。"},{"en":"Existing promenades show how people enjoy the harbour when access is open.","zh":"現有海濱長廊顯示當使用權開放時，人們如何享受海港。"},{"en":"Studying existing promenades can help planners design better future waterfronts.","zh":"研究現有海濱長廊可以幫助規劃者設計更好的未來海濱。"},{"en":"This phrase uses current examples to support an argument.","zh":"這個短語用現有例子支持論點。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"Tsim Sha Tsui","meaning":"尖沙咀","examples":[{"en":"The Tsim Sha Tsui promenade attracts many visitors.","zh":"尖沙咀海濱長廊吸引許多遊客。"},{"en":"Tsim Sha Tsui is a busy district in Kowloon known for harbour views, shops, and cultural facilities.","zh":"尖沙咀是九龍一個繁忙地區，以海港景觀、商店和文化設施聞名。"},{"en":"Visitors often go to Tsim Sha Tsui to look across Victoria Harbour.","zh":"遊客常到尖沙咀眺望維多利亞港。"},{"en":"Public space in Tsim Sha Tsui is valuable because the district is crowded and popular.","zh":"尖沙咀的公共空間很有價值，因為該區擠迫又受歡迎。"},{"en":"This place name helps give the argument a real local example.","zh":"這個地名幫助論點加入真實本地例子。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"Kwun Tong","meaning":"觀塘","examples":[{"en":"The Kwun Tong promenade gives residents space to relax.","zh":"觀塘海濱長廊給居民放鬆的空間。"},{"en":"Kwun Tong is a district in Kowloon with residential, industrial, and commercial areas.","zh":"觀塘是九龍一個有住宅、工業和商業區的地區。"},{"en":"Residents may visit the Kwun Tong promenade to walk, rest, or enjoy the harbour view.","zh":"居民可能到觀塘海濱長廊散步、休息或欣賞海港景色。"},{"en":"Public waterfront space matters in Kwun Tong because the district has many busy roads and buildings.","zh":"觀塘的公共海濱空間很重要，因為該區有許多繁忙道路和建築。"},{"en":"This place name shows that harbourfront space benefits local communities, not only tourists.","zh":"這個地名顯示海濱空間不只惠及遊客，也惠及本地社區。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"not merely exercising","meaning":"不只是在做運動","examples":[{"en":"Visitors are not merely exercising when they walk along the harbour.","zh":"遊人沿着海港散步時，不只是在做運動。"},{"en":"Not merely exercising means they are doing more than physical movement.","zh":"不只是在做運動，是指他們做的不只是身體活動。"},{"en":"A person walking by the harbour may also be relaxing, thinking, and escaping stress.","zh":"一個人在海港旁散步時，可能也在放鬆、思考和逃離壓力。"},{"en":"This phrase helps readers see the emotional value of open space.","zh":"這個短語幫助讀者看見開放空間的情感價值。"},{"en":"It shows that public space supports both body and mind.","zh":"它顯示公共空間同時支援身體和心靈。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"escaping from","meaning":"逃離","examples":[{"en":"They are escaping from traffic noise and workplace pressure.","zh":"他們正在逃離交通噪音和工作壓力。"},{"en":"Escaping from something means getting away from an unpleasant situation, sound, or pressure.","zh":"逃離某事是指離開令人不快的情況、聲音或壓力。"},{"en":"After school, students may visit a park to escape from homework stress for a while.","zh":"放學後，學生可能到公園暫時逃離功課壓力。"},{"en":"Open waterfronts help city residents escape from noise and crowds.","zh":"開放海濱幫助城市居民逃離噪音和人群。"},{"en":"This phrase shows public space as relief from daily pressure.","zh":"這個短語把公共空間呈現為日常壓力中的紓緩。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"even briefly","meaning":"即使只是短暫地","examples":[{"en":"Visitors can escape, even briefly, from city pressure.","zh":"遊人可以逃離城市壓力，即使只是短暫地。"},{"en":"Even briefly means even for a short time.","zh":"即使只是短暫地，是指即使時間很短。"},{"en":"Sitting under a tree even briefly can help a tired worker feel calmer.","zh":"即使只是短暫地坐在樹下，也可以令疲倦工人感到較平靜。"},{"en":"A short break still matters when daily life is crowded and stressful.","zh":"當日常生活擠迫又有壓力時，短暫休息仍然重要。"},{"en":"This phrase shows that small moments of relief can have value.","zh":"這個短語顯示小小的紓緩時刻也有價值。"}],"source":"2015 Q5.pdf","sourcePage":8},{"front":"traffic noise","meaning":"交通噪音","examples":[{"en":"Open spaces offer relief from traffic noise.","zh":"開放空間提供從交通噪音中得到的紓緩。"},{"en":"Traffic noise is the sound made by cars, buses, lorries, and other vehicles.","zh":"交通噪音是汽車、巴士、貨車和其他車輛製造的聲音。"},{"en":"People living beside busy roads may hear traffic noise from early morning to late night.","zh":"住在繁忙道路旁的人可能由清晨到深夜都聽到交通噪音。"},{"en":"Parks and waterfront paths can give residents a break from traffic noise.","zh":"公園和海濱小路可以讓居民暫時遠離交通噪音。"},{"en":"This phrase shows one everyday pressure of city life.","zh":"這個短語顯示城市生活中的一種日常壓力。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"concrete walls","meaning":"石屎牆","examples":[{"en":"Promenades offer a break from concrete walls.","zh":"海濱長廊讓人暫時遠離石屎牆。"},{"en":"Concrete walls are hard grey walls made from building material, often linked with dense urban spaces.","zh":"石屎牆是由建築材料製成的堅硬灰色牆壁，常與密集城市空間有關。"},{"en":"A city full of concrete walls can feel heavy and closed in.","zh":"充滿石屎牆的城市可能感覺沉重和封閉。"},{"en":"Green open spaces soften the feeling created by concrete walls.","zh":"綠化開放空間可以柔化石屎牆造成的感覺。"},{"en":"This phrase represents the hard physical environment of a crowded city.","zh":"這個短語代表擠迫城市中的堅硬實體環境。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"workplace pressure","meaning":"工作壓力","examples":[{"en":"Many people visit promenades to escape workplace pressure.","zh":"許多人到海濱長廊，是為了逃離工作壓力。"},{"en":"Workplace pressure means stress caused by duties, deadlines, colleagues, or job expectations.","zh":"工作壓力是由職責、限期、同事或工作期望造成的壓力。"},{"en":"Office workers may walk by the harbour after work to reduce workplace pressure.","zh":"辦公室員工下班後可能在海港旁散步，以減少工作壓力。"},{"en":"Public spaces help people recover from workplace pressure without spending money.","zh":"公共空間幫助人們不用花錢也能從工作壓力中恢復。"},{"en":"This phrase connects urban design with mental health.","zh":"這個短語把城市設計與心理健康連接起來。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"green and open spaces","meaning":"綠化及開放空間","examples":[{"en":"Green and open spaces help soften urban heat.","zh":"綠化及開放空間有助紓緩城市熱力。"},{"en":"Green and open spaces are areas with plants, grass, trees, and room for air and movement.","zh":"綠化及開放空間是有植物、草地、樹木，以及空氣和活動空間的地方。"},{"en":"Parks, lawns, and tree-lined promenades are green and open spaces.","zh":"公園、草地和樹木成行的海濱長廊都是綠化及開放空間。"},{"en":"Such spaces improve comfort by providing shade, airflow, and visual relief.","zh":"這些空間透過提供樹蔭、空氣流通和視覺放鬆來改善舒適度。"},{"en":"This phrase combines environmental value with public enjoyment.","zh":"這個短語結合環境價值與公眾享受。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"wind corridors","meaning":"通風廊","examples":[{"en":"Open harbourfront areas can allow wind corridors.","zh":"開放海濱地區可以形成通風廊。"},{"en":"Wind corridors are open paths that let air move through a city.","zh":"通風廊是讓空氣穿過城市的開放路徑。"},{"en":"Tall buildings too close together can block wind corridors.","zh":"太密集的高樓可以阻擋通風廊。"},{"en":"Keeping wind corridors near the harbour can make nearby streets cooler and more comfortable.","zh":"在海港附近保留通風廊，可以令附近街道更涼爽和舒適。"},{"en":"This phrase shows how open space affects the city’s climate and airflow.","zh":"這個短語顯示開放空間如何影響城市氣候和空氣流通。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"shade and vegetation","meaning":"樹蔭和植被","examples":[{"en":"Shade and vegetation can make the city more comfortable.","zh":"樹蔭和植被可以令城市更舒適。"},{"en":"Shade and vegetation mean protection from direct sunlight and plants such as trees, grass, and shrubs.","zh":"樹蔭和植被是指遮擋直射陽光的地方，以及樹木、草地和灌木等植物。"},{"en":"Shade and vegetation help walkers stay cooler on hot afternoons.","zh":"樹蔭和植被幫助行人在炎熱下午保持較涼爽。"},{"en":"A promenade without shade and vegetation may feel too hot to use.","zh":"沒有樹蔭和植被的海濱長廊可能太熱而難以使用。"},{"en":"This phrase points to simple design features that improve daily comfort.","zh":"這個短語指出改善日常舒適度的簡單設計元素。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"soften the urban heat","meaning":"紓緩城市熱力","examples":[{"en":"Green spaces can soften the urban heat.","zh":"綠化空間可以紓緩城市熱力。"},{"en":"To soften the urban heat means to reduce the harsh heat felt in a built-up city.","zh":"紓緩城市熱力，是指減少建築密集城市中感受到的強烈熱力。"},{"en":"Trees soften urban heat by shading pavements and cooling the air.","zh":"樹木透過遮蔭行人路和冷卻空氣來紓緩城市熱力。"},{"en":"Open harbourfront spaces can soften heat better than another wall of towers.","zh":"開放海濱空間比另一排高樓更能紓緩熱力。"},{"en":"This phrase connects environmental design with human comfort.","zh":"這個短語把環境設計與人的舒適連接起來。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"high-rise blocks","meaning":"高樓大廈","examples":[{"en":"High-rise blocks can intensify urban heat.","zh":"高樓大廈可以加劇城市熱力。"},{"en":"High-rise blocks are tall residential or commercial buildings with many floors.","zh":"高樓大廈是有很多樓層的高住宅或商業建築。"},{"en":"A district full of high-rise blocks may feel crowded and shaded in some places but hot in others.","zh":"充滿高樓大廈的地區，某些地方可能感到擠迫和陰暗，另一些地方則炎熱。"},{"en":"High-rise blocks can reduce airflow when they are built too close together.","zh":"當高樓大廈建得太密時，可能減少空氣流通。"},{"en":"This phrase often describes dense vertical city development.","zh":"這個短語常描述密集的垂直城市發展。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"intensify","meaning":"加劇","examples":[{"en":"High-rise blocks can intensify the urban heat.","zh":"高樓大廈可以加劇城市熱力。"},{"en":"To intensify means to make something stronger, worse, or more serious.","zh":"加劇是指令某事變得更強、更差或更嚴重。"},{"en":"Heavy traffic can intensify air pollution near schools.","zh":"繁忙交通可能加劇學校附近的空氣污染。"},{"en":"Lack of trees may intensify heat on wide concrete roads.","zh":"缺乏樹木可能加劇寬闊石屎路上的熱力。"},{"en":"This word shows that an action can make an existing problem worse.","zh":"這個詞顯示一個行動可以令已有問題惡化。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"be filled with towers","meaning":"被高樓填滿","examples":[{"en":"If the harbourfront is filled with towers, the city will feel more closed in.","zh":"如果海濱被高樓填滿，城市會感覺更封閉。"},{"en":"To be filled with towers means to have many tall buildings occupying the area.","zh":"被高樓填滿，是指一個地區被許多高層建築佔據。"},{"en":"A waterfront filled with towers may block views, wind, and public movement.","zh":"被高樓填滿的海濱可能阻擋景觀、風和公眾活動。"},{"en":"Filling the harbourfront with towers can make the sea feel distant from citizens.","zh":"以高樓填滿海濱，可能令市民感覺海變得遙遠。"},{"en":"This phrase warns against overcrowding a precious edge of the city.","zh":"這個短語警告人不要過度擠滿城市珍貴邊緣。"}],"source":"2015 Q5.pdf","sourcePage":9},{"front":"floor area","meaning":"樓面面積","examples":[{"en":"More towers may create more floor area.","zh":"更多高樓可能創造更多樓面面積。"},{"en":"Floor area means the total usable space inside buildings.","zh":"樓面面積是指建築物內可使用空間的總量。"},{"en":"Developers often calculate floor area to estimate how many flats or offices can be built.","zh":"發展商常計算樓面面積，以估計可興建多少單位或辦公室。"},{"en":"More floor area can bring profit, but it may also reduce open public space.","zh":"更多樓面面積可以帶來利潤，但也可能減少開放公共空間。"},{"en":"This phrase is useful when discussing the financial side of development.","zh":"這個短語適合討論發展的財務層面。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"less airflow","meaning":"較少空氣流通","examples":[{"en":"More towers may mean less airflow.","zh":"更多高樓可能意味較少空氣流通。"},{"en":"Less airflow means less movement of air through a place.","zh":"較少空氣流通，是指空氣穿過一個地方的流動較少。"},{"en":"A narrow street surrounded by tall buildings may have less airflow.","zh":"被高樓包圍的狹窄街道可能有較少空氣流通。"},{"en":"Less airflow can make hot weather feel heavier and less comfortable.","zh":"較少空氣流通會令炎熱天氣感覺更沉重和不舒服。"},{"en":"This phrase explains one environmental cost of dense construction.","zh":"這個短語解釋密集建築的一種環境代價。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"skyline","meaning":"天際線","examples":[{"en":"The skyline may feel increasingly closed in.","zh":"天際線可能感覺越來越封閉。"},{"en":"A skyline is the outline of buildings and land seen against the sky.","zh":"天際線是建築物和土地在天空背景下形成的輪廓。"},{"en":"Hong Kong’s skyline is famous because towers stand beside the harbour.","zh":"香港天際線很著名，因為高樓矗立在海港旁。"},{"en":"If too many towers block the waterfront, the skyline may feel less open.","zh":"如果太多高樓阻擋海濱，天際線可能感覺沒那麼開放。"},{"en":"This word connects city appearance with public feeling.","zh":"這個詞把城市外觀與公眾感受連接起來。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"increasingly closed in","meaning":"越來越封閉","examples":[{"en":"The harbourfront skyline may feel increasingly closed in.","zh":"海濱天際線可能感覺越來越封閉。"},{"en":"Increasingly closed in means becoming more surrounded, blocked, or lacking in openness.","zh":"越來越封閉，是指變得更被包圍、阻擋或缺乏開放感。"},{"en":"A street feels increasingly closed in when more tall buildings rise on both sides.","zh":"當街道兩旁興建越來越多高樓時，街道會感覺越來越封閉。"},{"en":"A closed-in waterfront can make people feel separated from the sea.","zh":"封閉的海濱可能令人感到與海分隔。"},{"en":"This phrase describes a gradual loss of openness.","zh":"這個短語描述開放感逐漸失去。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"rarely does a city get a chance to","meaning":"一個城市很少有機會……","examples":[{"en":"Rarely does a city get a chance to reserve land beside the sea.","zh":"一個城市很少有機會保留海邊土地。"},{"en":"Rarely does a city get a chance to means it is uncommon for a city to have such an opportunity.","zh":"一個城市很少有機會……，是指城市不常有這樣的機會。"},{"en":"Rarely does a school get a chance to redesign its playground from the beginning.","zh":"一所學校很少有機會從頭重新設計操場。"},{"en":"This structure makes the opportunity sound precious and unusual.","zh":"這個句式令機會聽起來珍貴而罕有。"},{"en":"It reminds readers that a planning chance may not return.","zh":"它提醒讀者，規劃機會可能不會再來。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"reserve land","meaning":"保留土地","examples":[{"en":"Hong Kong should reserve land beside the sea for public use.","zh":"香港應保留海邊土地作公眾使用。"},{"en":"To reserve land means to keep land for a particular future purpose.","zh":"保留土地是指為特定未來目的保存土地。"},{"en":"A town may reserve land for a school before more families move in.","zh":"城鎮可能在更多家庭搬入前保留土地興建學校。"},{"en":"Reserving harbourfront land protects future public needs from short-term pressure.","zh":"保留海濱土地可以保護未來公共需要，免受短期壓力影響。"},{"en":"This phrase shows planning ahead rather than using every site immediately.","zh":"這個短語顯示預先規劃，而不是立即使用每個地點。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"beside the sea","meaning":"在海邊","examples":[{"en":"Harbourfront land beside the sea is precious.","zh":"在海邊的海濱土地十分珍貴。"},{"en":"Beside the sea means next to or close to the sea.","zh":"在海邊是指在海旁或接近海的地方。"},{"en":"People enjoy walking beside the sea because the air and view feel open.","zh":"人們喜歡在海邊散步，因為空氣和景觀感覺開闊。"},{"en":"Land beside the sea often has strong public, scenic, and emotional value.","zh":"海邊土地通常有強烈的公共、景觀和情感價值。"},{"en":"This phrase gives a clear physical location and a sense of openness.","zh":"這個短語給出清晰位置和開放感。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"lost to permanent construction","meaning":"因永久建築而失去","examples":[{"en":"Once harbourfront land is lost to permanent construction, it is hard to regain.","zh":"海濱土地一旦因永久建築而失去，就很難取回。"},{"en":"Lost to permanent construction means taken over by buildings that are difficult to remove.","zh":"因永久建築而失去，是指被難以移除的建築物佔用。"},{"en":"A public field is lost to permanent construction when towers are built on it.","zh":"當高樓建在公共球場上時，該球場就因永久建築而失去。"},{"en":"Once land is lost this way, future planners have fewer choices.","zh":"土地一旦以這種方式失去，未來規劃者就有更少選擇。"},{"en":"This phrase warns that some development decisions are difficult to reverse.","zh":"這個短語警告我們，有些發展決定很難逆轉。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"permanent construction","meaning":"永久建築","examples":[{"en":"Permanent construction would make open harbourfront space hard to recover.","zh":"永久建築會令開放海濱空間難以恢復。"},{"en":"Permanent construction refers to buildings or structures intended to remain for a long time.","zh":"永久建築是指打算長期存在的建築物或結構。"},{"en":"A temporary market can be removed, but permanent construction is much harder to undo.","zh":"臨時市集可以移除，但永久建築更難撤回。"},{"en":"Permanent construction on waterfront land can block access for generations.","zh":"海濱土地上的永久建築可能阻擋幾代人的使用權。"},{"en":"This phrase highlights the long-term effect of development.","zh":"這個短語突出發展的長遠影響。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"almost impossible to regain","meaning":"幾乎不可能取回","examples":[{"en":"Once the land is lost, it will be almost impossible to regain.","zh":"土地一旦失去，就幾乎不可能取回。"},{"en":"Almost impossible to regain means extremely difficult to get back.","zh":"幾乎不可能取回，是指極難重新得到。"},{"en":"A public view blocked by private towers may be almost impossible to regain.","zh":"被私人高樓阻擋的公共景觀可能幾乎不可能取回。"},{"en":"Land decisions must be careful because lost public space is rarely easy to recover.","zh":"土地決定必須小心，因為失去的公共空間很少容易恢復。"},{"en":"This phrase warns readers about irreversible loss.","zh":"這個短語警告讀者不可逆轉的損失。"}],"source":"2015 Q5.pdf","sourcePage":10},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, Hong Kong needs more housing and economic activity.","zh":"誠然，香港需要更多房屋和經濟活動。"},{"en":"Granted is used to admit that an opposing point has some truth.","zh":"誠然用來承認相反觀點有一定道理。"},{"en":"Granted, a city needs development, but it also needs parks.","zh":"誠然，城市需要發展，但也需要公園。"},{"en":"Writers use granted to sound fair before explaining why they still disagree.","zh":"作者使用「誠然」令自己在解釋不同意前聽起來公平。"},{"en":"This word helps balance an argument.","zh":"這個詞幫助平衡論證。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"economic activity","meaning":"經濟活動","examples":[{"en":"Hong Kong needs housing and economic activity.","zh":"香港需要房屋和經濟活動。"},{"en":"Economic activity means actions that produce, sell, buy, or exchange goods and services.","zh":"經濟活動是指生產、出售、購買或交換貨品和服務的行動。"},{"en":"Shops, offices, markets, and tourism all create economic activity.","zh":"商店、辦公室、市場和旅遊都創造經濟活動。"},{"en":"Economic activity is important, but it should not destroy public space.","zh":"經濟活動很重要，但不應摧毀公共空間。"},{"en":"This phrase refers to the business and financial life of a city.","zh":"這個短語指城市的商業和財務生活。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"it does not follow that","meaning":"這並不代表","examples":[{"en":"It does not follow that the harbourfront should be sacrificed.","zh":"這並不代表海濱應該被犧牲。"},{"en":"It does not follow that means one fact does not automatically prove the next claim.","zh":"這並不代表，是指一個事實不會自動證明下一個主張。"},{"en":"A city needs housing, but it does not follow that every park should be built over.","zh":"城市需要房屋，但這並不代表每個公園都應被建築覆蓋。"},{"en":"This phrase helps writers reject weak logic.","zh":"這個短語幫助作者否定薄弱邏輯。"},{"en":"It shows that a problem may have other solutions.","zh":"它顯示一個問題可能有其他解決方法。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"be sacrificed for","meaning":"為……而犧牲","examples":[{"en":"The harbourfront should not be sacrificed for housing or commerce.","zh":"海濱不應為房屋或商業而犧牲。"},{"en":"To be sacrificed for something means to be given up in order to achieve another aim.","zh":"為某事而犧牲，是指為達成另一目的而放棄某物。"},{"en":"A school playground should not be sacrificed for extra parking spaces.","zh":"學校操場不應為額外停車位而犧牲。"},{"en":"Public space is sacrificed when profit is valued more than community life.","zh":"當利潤比社區生活更受重視時，公共空間就被犧牲。"},{"en":"This phrase suggests a painful loss made for another purpose.","zh":"這個短語表示為另一目的而作出的痛苦損失。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"for these purposes","meaning":"為了這些目的","examples":[{"en":"The harbourfront should not be sacrificed for these purposes.","zh":"海濱不應為了這些目的而被犧牲。"},{"en":"For these purposes means for the aims just mentioned.","zh":"為了這些目的，是指為了剛才提到的目標。"},{"en":"More offices may be needed, but a public park should not be removed for these purposes.","zh":"也許需要更多辦公室，但不應為了這些目的移除公共公園。"},{"en":"This phrase avoids repeating a list of aims such as housing and commerce.","zh":"這個短語避免重複房屋和商業等一串目標。"},{"en":"It helps connect a warning to the previous sentence.","zh":"它幫助把警告與前一句連接起來。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"be pursued through","meaning":"應透過……來推動","examples":[{"en":"Housing should be pursued through brownfield redevelopment and urban renewal.","zh":"房屋應透過棕地重建和市區重建來推動。"},{"en":"To be pursued through something means to be achieved by using that method or route.","zh":"應透過某方法來推動，是指使用該方法或路線來達成目標。"},{"en":"Better public transport can be pursued through improved bus routes and railway links.","zh":"更好的公共交通可以透過改善巴士路線和鐵路連接來推動。"},{"en":"Housing goals can be pursued through several methods, not only harbourfront development.","zh":"房屋目標可以透過多種方法推動，而不只是發展海濱。"},{"en":"This phrase points to an alternative way to solve a problem.","zh":"這個短語指出解決問題的替代方法。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"brownfield redevelopment","meaning":"棕地重建","examples":[{"en":"Housing can be pursued through brownfield redevelopment.","zh":"房屋可以透過棕地重建來推動。"},{"en":"Brownfield redevelopment means reusing previously developed or disturbed land for new purposes.","zh":"棕地重建是指把曾經發展或受擾動的土地重新用於新用途。"},{"en":"Old industrial sites may become homes through brownfield redevelopment.","zh":"舊工業用地可以透過棕地重建變成住宅。"},{"en":"Brownfield redevelopment can reduce pressure to build on valuable public waterfront land.","zh":"棕地重建可以減少在珍貴公共海濱土地上興建建築的壓力。"},{"en":"This phrase describes a planning method that reuses land more efficiently.","zh":"這個短語描述更有效重用土地的規劃方法。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"urban renewal","meaning":"市區重建","examples":[{"en":"Urban renewal can help provide housing.","zh":"市區重建可以幫助提供房屋。"},{"en":"Urban renewal means improving or rebuilding older parts of a city.","zh":"市區重建是指改善或重建城市中較舊的部分。"},{"en":"Old buildings may be repaired or replaced through urban renewal.","zh":"舊樓可以透過市區重建被維修或重建。"},{"en":"Urban renewal can provide new homes while improving streets, facilities, and safety.","zh":"市區重建可以提供新住宅，同時改善街道、設施和安全。"},{"en":"This phrase shows another route to development without consuming open harbourfront land.","zh":"這個短語顯示另一條發展道路，而不用佔用開放海濱土地。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"better use of idle sites","meaning":"更善用閒置土地","examples":[{"en":"Housing can come from better use of idle sites.","zh":"房屋可以來自更善用閒置土地。"},{"en":"Better use of idle sites means using unused or underused land more effectively.","zh":"更善用閒置土地，是指更有效地使用未被使用或使用不足的土地。"},{"en":"An empty government site could become temporary housing or community facilities.","zh":"空置政府土地可以變成臨時房屋或社區設施。"},{"en":"Better use of idle sites reduces waste in a city with land shortage.","zh":"在土地短缺的城市中，更善用閒置土地可以減少浪費。"},{"en":"This phrase suggests solving problems by using existing resources more wisely.","zh":"這個短語表示透過更明智使用現有資源來解決問題。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"idle sites","meaning":"閒置土地","examples":[{"en":"Idle sites should be used more effectively.","zh":"閒置土地應被更有效使用。"},{"en":"Idle sites are pieces of land that are unused, underused, or left empty.","zh":"閒置土地是未被使用、使用不足或被空置的土地。"},{"en":"A vacant lot near a station may be an idle site if no one uses it for years.","zh":"車站附近一幅空地如果多年沒有人使用，可能就是閒置土地。"},{"en":"Using idle sites well can reduce pressure on parks and waterfronts.","zh":"好好使用閒置土地，可以減少公園和海濱所承受的壓力。"},{"en":"This phrase points to land that already exists but is not serving the public fully.","zh":"這個短語指出已存在但未充分服務公眾的土地。"}],"source":"2015 Q5.pdf","sourcePage":11},{"front":"well-planned new development areas","meaning":"規劃完善的新發展區","examples":[{"en":"Housing can be provided through well-planned new development areas.","zh":"房屋可以透過規劃完善的新發展區提供。"},{"en":"Well-planned new development areas are newly built districts designed carefully with homes, transport, jobs, and services.","zh":"規劃完善的新發展區是仔細設計、包含住宅、交通、工作和服務的新建地區。"},{"en":"A new development area should include schools, clinics, parks, and transport links.","zh":"新發展區應包括學校、診所、公園和交通連接。"},{"en":"If development areas are well planned, housing growth does not need to destroy every open waterfront.","zh":"如果新發展區規劃完善，房屋增長不必摧毀每一處開放海濱。"},{"en":"This phrase stresses planning quality, not just building quantity.","zh":"這個短語強調規劃質素，而不只是建築數量。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"consuming","meaning":"消耗；佔用","examples":[{"en":"Housing should not be pursued by consuming the harbourfront.","zh":"房屋不應透過佔用海濱來推動。"},{"en":"Consuming means using up or taking over something until less of it remains.","zh":"消耗或佔用是指使用或佔去某物，使剩下的變少。"},{"en":"A city consumes green land when it builds over every field and hill slope.","zh":"城市在每塊田地和山坡上興建建築時，就是消耗綠地。"},{"en":"Consuming the harbourfront for private buildings would leave fewer shared spaces.","zh":"以私人建築佔用海濱，會留下更少共享空間。"},{"en":"This word suggests a loss caused by heavy use or development.","zh":"這個詞表示大量使用或發展造成的損失。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"symbolically valuable edge of the city","meaning":"城市最具象徵價值的邊緣","examples":[{"en":"The harbourfront is the most symbolically valuable edge of the city.","zh":"海濱是城市最具象徵價值的邊緣。"},{"en":"A symbolically valuable edge of the city is a boundary area that carries strong meaning for the city’s identity.","zh":"城市最具象徵價值的邊緣，是指承載城市身份強烈意義的邊界地帶。"},{"en":"A waterfront can be symbolically valuable because it shows how a city meets nature, trade, and history.","zh":"海濱可以具象徵價值，因為它顯示城市如何與自然、貿易和歷史相遇。"},{"en":"Building carelessly on such an edge can damage more than the physical view.","zh":"在這樣的邊緣上粗心建設，損害的不只是實際景觀。"},{"en":"This phrase shows that the harbourfront has meaning beyond land price.","zh":"這個短語顯示海濱的意義超越土地價格。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"commercial use","meaning":"商業用途","examples":[{"en":"Commercial use can also benefit from open public space.","zh":"商業用途也可以受惠於開放公共空間。"},{"en":"Commercial use means using land, buildings, or facilities for business purposes.","zh":"商業用途是指把土地、建築物或設施用於商業目的。"},{"en":"Cafés, shops, and markets are examples of commercial use.","zh":"咖啡店、商店和市集都是商業用途的例子。"},{"en":"Commercial use can work well near public space if it does not dominate access.","zh":"如果不主導使用權，商業用途可以在公共空間附近良好運作。"},{"en":"This phrase shows that business and public benefit can sometimes support each other.","zh":"這個短語顯示商業和公共利益有時可以互相支持。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"benefit from","meaning":"受惠於","examples":[{"en":"Commercial districts can benefit from open public space.","zh":"商業區可以受惠於開放公共空間。"},{"en":"To benefit from something means to gain help, value, or advantage from it.","zh":"受惠於某物，是指從它得到幫助、價值或好處。"},{"en":"Small restaurants benefit from nearby parks because more visitors pass by.","zh":"小餐廳受惠於附近公園，因為更多遊人會經過。"},{"en":"Residents benefit from open space through better health and daily comfort.","zh":"居民透過更好的健康和日常舒適受惠於開放空間。"},{"en":"This phrase shows a positive result gained from a condition or resource.","zh":"這個短語顯示由某條件或資源得到的正面結果。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"local visitors","meaning":"本地遊客；本地訪客","examples":[{"en":"A beautiful waterfront attracts local visitors.","zh":"美麗的海濱吸引本地訪客。"},{"en":"Local visitors are people from the same city or nearby districts who visit a place.","zh":"本地訪客是來自同一城市或附近地區，到訪某地的人。"},{"en":"Local visitors may come to the harbourfront after work or on weekends.","zh":"本地訪客可能在下班後或週末來到海濱。"},{"en":"A waterfront should serve local visitors, not only tourists.","zh":"海濱應服務本地訪客，而不只是遊客。"},{"en":"This phrase reminds planners that public places belong to residents as well as guests.","zh":"這個短語提醒規劃者，公共地方既屬於居民，也屬於客人。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"tourists","meaning":"遊客","examples":[{"en":"A beautiful waterfront attracts tourists.","zh":"美麗的海濱吸引遊客。"},{"en":"Tourists are people who travel to a place for leisure, sightseeing, or culture.","zh":"遊客是為休閒、觀光或文化而到某地旅行的人。"},{"en":"Tourists may visit the harbour to take photos and learn about the city.","zh":"遊客可能到海港拍照和認識這座城市。"},{"en":"Public waterfronts can attract tourists while still serving local residents.","zh":"公共海濱可以吸引遊客，同時仍服務本地居民。"},{"en":"This word connects city planning with travel and reputation.","zh":"這個詞把城市規劃與旅遊和聲譽連接起來。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"cultural events","meaning":"文化活動","examples":[{"en":"Open waterfront space can host cultural events.","zh":"開放海濱空間可以舉辦文化活動。"},{"en":"Cultural events are activities that share art, music, traditions, stories, or community identity.","zh":"文化活動是分享藝術、音樂、傳統、故事或社區身份的活動。"},{"en":"A harbourfront may host cultural events such as concerts, exhibitions, and festivals.","zh":"海濱可以舉辦音樂會、展覽和節日等文化活動。"},{"en":"Cultural events in public places allow more people to join without expensive tickets.","zh":"在公共地方舉辦文化活動，讓更多人不用昂貴門票也能參與。"},{"en":"This phrase shows how open space can support city life beyond business.","zh":"這個短語顯示開放空間如何支援商業以外的城市生活。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"weekend markets","meaning":"週末市集","examples":[{"en":"A beautiful waterfront can attract weekend markets.","zh":"美麗的海濱可以吸引週末市集。"},{"en":"Weekend markets are temporary markets held on Saturdays, Sundays, or holidays.","zh":"週末市集是在星期六、星期日或假期舉行的臨時市場。"},{"en":"Weekend markets may sell crafts, food, books, and local products.","zh":"週末市集可能售賣手工藝品、食物、書本和本地產品。"},{"en":"A harbourfront weekend market can bring people together without closing public access.","zh":"海濱週末市集可以凝聚人群，同時不關閉公眾使用權。"},{"en":"This phrase shows how public space can support small businesses and community life.","zh":"這個短語顯示公共空間如何支援小企業和社區生活。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"outdoor performances","meaning":"戶外表演","examples":[{"en":"Open spaces can support outdoor performances.","zh":"開放空間可以支援戶外表演。"},{"en":"Outdoor performances are music, dance, drama, or other shows held outside.","zh":"戶外表演是在戶外舉行的音樂、舞蹈、戲劇或其他演出。"},{"en":"A waterfront lawn can host outdoor performances during a community festival.","zh":"海濱草地可以在社區節日期間舉辦戶外表演。"},{"en":"Outdoor performances make culture more visible and accessible to ordinary people.","zh":"戶外表演令文化更可見，也更容易讓普通人接觸。"},{"en":"This phrase shows that public space can become a stage for the city.","zh":"這個短語顯示公共空間可以成為城市的舞台。"}],"source":"2015 Q5.pdf","sourcePage":12},{"front":"surrounding districts","meaning":"周邊地區","examples":[{"en":"Small businesses in surrounding districts can benefit from visitors.","zh":"周邊地區的小企業可以受惠於訪客。"},{"en":"Surrounding districts are nearby neighbourhoods or areas around a place.","zh":"周邊地區是某地方附近的社區或區域。"},{"en":"Shops in surrounding districts may gain customers when people visit a popular promenade.","zh":"當人們到受歡迎的海濱長廊時，周邊地區的商店可能得到顧客。"},{"en":"Improving a waterfront can help not only the site itself but also surrounding districts.","zh":"改善海濱不只幫助該地點本身，也可以幫助周邊地區。"},{"en":"This phrase shows that benefits can spread beyond one location.","zh":"這個短語顯示好處可以擴散到一個地點以外。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, leaving the harbourfront open is not anti-development.","zh":"換言之，保留海濱開放並不是反發展。"},{"en":"In other words introduces the same idea in a clearer or simpler way.","zh":"換言之，是用更清楚或更簡單方式表達同一想法。"},{"en":"Parks attract people and business; in other words, open space can support development.","zh":"公園吸引人流和商業；換言之，開放空間可以支持發展。"},{"en":"Writers use this phrase when they want to restate a point for clarity.","zh":"作者想為清晰起見重述觀點時，會使用這個短語。"},{"en":"It helps readers understand the main message more easily.","zh":"它幫助讀者更容易理解主要信息。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"anti-development","meaning":"反發展","examples":[{"en":"Protecting open space is not anti-development.","zh":"保護開放空間並不是反發展。"},{"en":"Anti-development means against building, economic growth, or change.","zh":"反發展是指反對建設、經濟增長或改變。"},{"en":"A person is not anti-development simply because they want better planning.","zh":"一個人只是想要更好規劃，並不等於反發展。"},{"en":"Protecting parks can be pro-development if it improves quality of life.","zh":"如果保護公園能改善生活質素，它也可以是支持發展。"},{"en":"This word is often used in debates about growth and conservation.","zh":"這個詞常用於關於增長和保育的辯論。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"quite the contrary","meaning":"正好相反","examples":[{"en":"Quite the contrary, it is a wiser kind of development.","zh":"正好相反，這是一種更明智的發展方式。"},{"en":"Quite the contrary means the opposite is true.","zh":"正好相反，是指事實剛好相反。"},{"en":"Public space does not weaken a city; quite the contrary, it can make the city more attractive.","zh":"公共空間不會削弱城市；正好相反，它可以令城市更吸引。"},{"en":"Writers use this phrase to strongly correct a mistaken idea.","zh":"作者使用這個短語有力地修正錯誤想法。"},{"en":"It helps turn an objection into support for the writer’s argument.","zh":"它幫助把反對意見轉化為支持作者論點。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"a wiser kind of development","meaning":"更明智的發展方式","examples":[{"en":"Leaving the harbourfront open is a wiser kind of development.","zh":"保留海濱開放是一種更明智的發展方式。"},{"en":"A wiser kind of development means growth that considers long-term public value, not only short-term profit.","zh":"更明智的發展方式，是指考慮長遠公共價值，而不只是短期利潤的增長。"},{"en":"Building parks beside homes can be a wiser kind of development than filling every site with towers.","zh":"在住宅旁興建公園，可能比把每個地點都建滿高樓更明智。"},{"en":"Wise development balances housing, business, health, and public access.","zh":"明智發展會平衡房屋、商業、健康和公眾使用權。"},{"en":"This phrase redefines development as quality, not just construction.","zh":"這個短語把發展重新定義為質素，而不只是建築。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"cities such as","meaning":"例如……的城市","examples":[{"en":"Cities such as Sydney and Singapore protect attractive waterfront spaces.","zh":"例如悉尼和新加坡等城市會保護吸引人的海濱空間。"},{"en":"Cities such as introduces examples of cities that show the writer’s point.","zh":"例如……的城市，用來引出能說明作者觀點的城市例子。"},{"en":"Cities such as Vancouver and Copenhagen are often discussed for public waterfront design.","zh":"例如溫哥華和哥本哈根等城市，常因公共海濱設計而被討論。"},{"en":"This phrase gives examples without claiming they are the only examples.","zh":"這個短語提供例子，但不表示它們是唯一例子。"},{"en":"It helps make an argument more concrete and comparative.","zh":"它幫助論點變得更具體和可比較。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"admired","meaning":"受人欣賞","examples":[{"en":"Sydney and Singapore are admired for their waterfronts.","zh":"悉尼和新加坡因其海濱而受人欣賞。"},{"en":"Admired means respected, liked, or looked up to by others.","zh":"受人欣賞是指被他人尊重、喜愛或看重。"},{"en":"A city may be admired for clean streets, good transport, and beautiful parks.","zh":"城市可能因乾淨街道、良好交通和美麗公園而受人欣賞。"},{"en":"Waterfronts are admired when they are open, attractive, and easy to use.","zh":"當海濱開放、吸引和易用時，就會受人欣賞。"},{"en":"This word shows positive reputation earned through good qualities.","zh":"這個詞顯示由良好特質帶來的正面聲譽。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"every inch of waterfront","meaning":"每一吋海濱","examples":[{"en":"A city should not sell every inch of waterfront to the highest bidder.","zh":"一個城市不應把每一吋海濱都賣給出價最高者。"},{"en":"Every inch of waterfront means all waterfront land, even the smallest parts.","zh":"每一吋海濱是指所有海濱土地，即使是最小的部分。"},{"en":"If every inch of waterfront becomes private, citizens lose contact with the water.","zh":"如果每一吋海濱都變成私人地方，市民會失去與水面的接觸。"},{"en":"This phrase stresses the danger of using up all public waterfront land.","zh":"這個短語強調用盡所有公共海濱土地的危險。"},{"en":"It reminds planners to keep some places open for everyone.","zh":"它提醒規劃者保留一些地方向所有人開放。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"be sold to the highest bidder","meaning":"賣給出價最高者","examples":[{"en":"Waterfront land should not simply be sold to the highest bidder.","zh":"海濱土地不應單純賣給出價最高者。"},{"en":"To be sold to the highest bidder means to be given to whoever offers the most money.","zh":"賣給出價最高者，是指交給願意支付最多金錢的人。"},{"en":"Public land should not always be sold to the highest bidder if community needs are ignored.","zh":"如果社區需要被忽視，公共土地不應總是賣給出價最高者。"},{"en":"Selling land this way may maximise revenue but reduce social value.","zh":"這樣賣地可能最大化收入，但減少社會價值。"},{"en":"This phrase criticises decisions based only on price.","zh":"這個短語批評只根據價格作決定。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"gather, walk, celebrate and remember","meaning":"聚集、散步、慶祝和回憶","examples":[{"en":"People should be able to gather, walk, celebrate and remember beside the water.","zh":"人們應能在水邊聚集、散步、慶祝和回憶。"},{"en":"Gather, walk, celebrate and remember describes the many public activities a shared place can support.","zh":"聚集、散步、慶祝和回憶，描述一個共享地方能支援的多種公共活動。"},{"en":"Families gather, friends walk, communities celebrate, and older residents remember past events at public waterfronts.","zh":"在公共海濱，家庭聚集、朋友散步、社區慶祝，年長居民回憶往事。"},{"en":"A good harbourfront is valuable because it holds both daily life and special occasions.","zh":"良好的海濱很有價值，因為它承載日常生活和特別場合。"},{"en":"This phrase presents public space as social, active, festive, and historical.","zh":"這個短語把公共空間呈現為社交、活躍、節慶和歷史性的地方。"}],"source":"2015 Q5.pdf","sourcePage":13},{"front":"beside the water","meaning":"在水邊","examples":[{"en":"Great harbour cities allow people to gather beside the water.","zh":"偉大的海港城市讓人們在水邊聚集。"},{"en":"Beside the water means next to a harbour, river, lake, or sea.","zh":"在水邊是指在海港、河流、湖泊或海旁。"},{"en":"People often feel calmer when they sit beside the water and watch the view.","zh":"當人們坐在水邊看景色時，常會感到更平靜。"},{"en":"Public paths beside the water help citizens feel connected to their city’s landscape.","zh":"水邊的公共小路幫助市民感到與城市景觀連繫。"},{"en":"This phrase gives a strong sense of place and openness.","zh":"這個短語給人強烈的地方感和開放感。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"all in all","meaning":"總括而言","examples":[{"en":"All in all, quality of life matters more than building height.","zh":"總括而言，生活質素比建築物高度更重要。"},{"en":"All in all introduces a final overall judgement after several points.","zh":"總括而言，是在提出幾點後引出整體最終判斷。"},{"en":"All in all, a city should be judged by how well ordinary people can live there.","zh":"總括而言，城市應以普通人能否好好生活來評價。"},{"en":"Writers use this phrase to signal that the argument is reaching a conclusion.","zh":"作者使用這個短語表示論證正走向結論。"},{"en":"It helps summarise the main message clearly.","zh":"它幫助清楚總結主要信息。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"world-class","meaning":"世界級","examples":[{"en":"A world-class city offers a high quality of life.","zh":"世界級城市提供高生活質素。"},{"en":"World-class means among the best in the world.","zh":"世界級是指屬於世界上最好的級別。"},{"en":"A world-class transport system is reliable, clean, and easy for different people to use.","zh":"世界級交通系統可靠、潔淨，並方便不同人使用。"},{"en":"A city is not world-class simply because it has many tall buildings.","zh":"城市不會只因有很多高樓就成為世界級。"},{"en":"This word describes excellence judged by international standards.","zh":"這個詞描述以國際標準判斷的卓越。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"quality of life","meaning":"生活質素","examples":[{"en":"What makes a city world-class is the quality of life it offers.","zh":"令城市成為世界級的是它提供的生活質素。"},{"en":"Quality of life means how comfortable, healthy, safe, and meaningful daily living is.","zh":"生活質素是指日常生活有多舒適、健康、安全和有意義。"},{"en":"Parks, clean air, good transport, and public safety all improve quality of life.","zh":"公園、清潔空氣、良好交通和公共安全都改善生活質素。"},{"en":"A city with high incomes but no public space may still have poor quality of life.","zh":"一個收入高但沒有公共空間的城市，生活質素仍可能很差。"},{"en":"This phrase focuses on how people actually experience a place.","zh":"這個短語著重人們實際如何經歷一個地方。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"at street level","meaning":"在街道層面","examples":[{"en":"A city’s quality of life should be felt at street level.","zh":"城市的生活質素應在街道層面被感受到。"},{"en":"At street level means in the everyday places where ordinary people walk, wait, shop, and meet.","zh":"在街道層面，是指在普通人走路、等候、購物和見面的日常地方。"},{"en":"A city looks successful from above, but at street level pedestrians may feel unsafe.","zh":"城市從高處看可能很成功，但在街道層面，行人可能感到不安全。"},{"en":"Public benches, shade, and clean pavements improve life at street level.","zh":"公共長椅、樹蔭和乾淨行人路改善街道層面的生活。"},{"en":"This phrase brings planning down to daily human experience.","zh":"這個短語把規劃帶回人的日常經驗。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"not simply","meaning":"不只是","examples":[{"en":"A city is not judged simply by the height of its buildings.","zh":"評價一座城市不只是看建築物的高度。"},{"en":"Not simply means not only or not just in that one way.","zh":"不只是是指不僅僅以那一種方式。"},{"en":"A school is not judged simply by exam results, but also by how students grow.","zh":"評價學校不只是看考試成績，也要看學生成長。"},{"en":"A city should not be judged simply by profit if public well-being is ignored.","zh":"如果公共福祉被忽視，城市不應只按利潤評價。"},{"en":"This phrase helps widen the way people evaluate something.","zh":"這個短語幫助拓闊人們評價事物的方式。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"the height of its buildings","meaning":"建築物的高度","examples":[{"en":"The height of buildings alone does not make a city world-class.","zh":"單靠建築物的高度並不能令城市成為世界級。"},{"en":"The height of its buildings means how tall the city’s buildings are.","zh":"建築物的高度是指城市中建築物有多高。"},{"en":"Tall buildings may create a dramatic skyline, but height alone does not guarantee comfort.","zh":"高樓可能創造壯觀天際線，但高度本身不保證舒適。"},{"en":"A city with lower buildings can still have excellent parks, transport, and public life.","zh":"建築物較低的城市仍可以有優秀公園、交通和公共生活。"},{"en":"This phrase contrasts visible construction with deeper quality of life.","zh":"這個短語對比可見建設與更深層的生活質素。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"for these reasons","meaning":"基於這些原因","examples":[{"en":"For these reasons, the undeveloped harbourfront should remain open.","zh":"基於這些原因，尚未發展的海濱應保持開放。"},{"en":"For these reasons means because of the points just explained.","zh":"基於這些原因，是指因為剛才解釋的幾點。"},{"en":"For these reasons, the school should keep the playground open after class.","zh":"基於這些原因，學校應在放學後保持操場開放。"},{"en":"Writers use this phrase to connect evidence with a conclusion.","zh":"作者使用這個短語把證據與結論連接起來。"},{"en":"It helps the final recommendation feel supported rather than sudden.","zh":"它幫助最後建議感覺有支持，而不是突然出現。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"should be left as","meaning":"應該保留作","examples":[{"en":"The harbourfront should be left as open space.","zh":"海濱應該保留作開放空間。"},{"en":"Should be left as means should remain in a particular form or use.","zh":"應該保留作，是指應保持某種形式或用途。"},{"en":"A small garden should be left as a quiet resting place for residents.","zh":"小花園應該保留作居民安靜休息的地方。"},{"en":"Leaving land as open space can be a deliberate planning choice, not neglect.","zh":"把土地保留作開放空間可以是有意識的規劃選擇，而不是忽略。"},{"en":"This phrase argues for preservation rather than conversion.","zh":"這個短語主張保留，而不是改建。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"the Government","meaning":"政府","examples":[{"en":"The Government should protect the remaining harbourfront.","zh":"政府應保護餘下的海濱地區。"},{"en":"The Government means the public authority responsible for making laws, policies, and planning decisions.","zh":"政府是負責制定法律、政策和規劃決定的公共機關。"},{"en":"The Government can decide whether land is used for public parks or private development.","zh":"政府可以決定土地是用作公共公園還是私人發展。"},{"en":"Citizens often ask the Government to protect resources that individuals cannot protect alone.","zh":"市民常要求政府保護個人無法獨自保護的資源。"},{"en":"This phrase identifies who has public responsibility.","zh":"這個短語指出誰承擔公共責任。"}],"source":"2015 Q5.pdf","sourcePage":14},{"front":"urban planners","meaning":"城市規劃師","examples":[{"en":"Urban planners should design harbourfront areas for public use.","zh":"城市規劃師應把海濱地區設計作公眾使用。"},{"en":"Urban planners are professionals who plan how land, buildings, transport, and public spaces should be arranged.","zh":"城市規劃師是規劃土地、建築、交通和公共空間如何安排的專業人士。"},{"en":"Urban planners decide where parks, roads, homes, and community facilities should go.","zh":"城市規劃師決定公園、道路、住宅和社區設施應放在哪裡。"},{"en":"Good urban planners consider how ordinary people move through the city every day.","zh":"好的城市規劃師會考慮普通人每天如何在城市中移動。"},{"en":"This phrase points to experts who shape city life.","zh":"這個短語指塑造城市生活的專家。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"district councils","meaning":"區議會","examples":[{"en":"District councils should help design accessible harbourfront spaces.","zh":"區議會應協助設計容易使用的海濱空間。"},{"en":"District councils are local public bodies that discuss community needs and district matters.","zh":"區議會是討論社區需要和地區事務的地方公共組織。"},{"en":"District councils may collect residents’ views on parks, transport, and public facilities.","zh":"區議會可能收集居民對公園、交通和公共設施的意見。"},{"en":"Involving district councils can make harbourfront planning more connected to local needs.","zh":"讓區議會參與，可以令海濱規劃更連繫本地需要。"},{"en":"This phrase refers to local-level participation in public decisions.","zh":"這個短語指公共決策中的地區層面參與。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"shaded walkways","meaning":"有遮蔭的行人道","examples":[{"en":"Harbourfront areas should include shaded walkways.","zh":"海濱地區應包括有遮蔭的行人道。"},{"en":"Shaded walkways are paths protected from strong sunlight by trees, roofs, or covers.","zh":"有遮蔭的行人道是受樹木、屋頂或上蓋保護，免受強烈陽光照射的小路。"},{"en":"Shaded walkways help elderly residents and children walk comfortably in hot weather.","zh":"有遮蔭的行人道幫助長者和兒童在炎熱天氣中舒適步行。"},{"en":"Without shade, a beautiful promenade may be difficult to use at noon.","zh":"如果沒有遮蔭，美麗的海濱長廊在中午可能難以使用。"},{"en":"This phrase shows how small design choices affect real public access.","zh":"這個短語顯示小設計選擇如何影響真正公共使用。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"barrier-free access","meaning":"無障礙通道","examples":[{"en":"The design should include barrier-free access.","zh":"設計應包括無障礙通道。"},{"en":"Barrier-free access means people with disabilities, elderly people, and families with prams can enter and move around easily.","zh":"無障礙通道是指殘疾人士、長者和推嬰兒車的家庭可以容易進入和活動。"},{"en":"Ramps, lifts, wide paths, and clear signs can provide barrier-free access.","zh":"斜道、升降機、寬闊小路和清晰指示可以提供無障礙通道。"},{"en":"A public space is not truly public if barrier-free access is missing.","zh":"如果缺少無障礙通道，公共空間就不是真正公共。"},{"en":"This phrase connects design with equality and dignity.","zh":"這個短語把設計與平等和尊嚴連接起來。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"lawns","meaning":"草地","examples":[{"en":"Harbourfront areas should include lawns.","zh":"海濱地區應包括草地。"},{"en":"Lawns are open grassy areas where people can sit, play, rest, or picnic.","zh":"草地是開放的青草地，人們可以坐下、玩耍、休息或野餐。"},{"en":"Lawns give children room to move and families space to gather.","zh":"草地給孩子活動空間，也給家庭聚集地方。"},{"en":"In a concrete city, lawns provide softness, colour, and breathing room.","zh":"在石屎城市中，草地提供柔和感、色彩和透氣空間。"},{"en":"This word shows a simple feature that makes public space more welcoming.","zh":"這個詞顯示一個令公共空間更受歡迎的簡單元素。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"cultural facilities","meaning":"文化設施","examples":[{"en":"The harbourfront should include cultural facilities.","zh":"海濱應包括文化設施。"},{"en":"Cultural facilities are places or structures that support art, heritage, performances, exhibitions, or learning.","zh":"文化設施是支援藝術、文化遺產、表演、展覽或學習的地方或結構。"},{"en":"Small stages, galleries, exhibition boards, and community rooms can be cultural facilities.","zh":"小舞台、畫廊、展板和社區活動室都可以是文化設施。"},{"en":"Cultural facilities make the harbourfront more than a walkway by giving people reasons to gather.","zh":"文化設施透過給人聚集理由，令海濱不只是行人道。"},{"en":"This phrase connects public space with creativity and identity.","zh":"這個短語把公共空間與創意和身份連接起來。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"family-friendly seating","meaning":"適合家庭使用的座椅","examples":[{"en":"Public spaces should provide family-friendly seating.","zh":"公共空間應提供適合家庭使用的座椅。"},{"en":"Family-friendly seating means seats that are safe, comfortable, and suitable for children, parents, and older relatives.","zh":"適合家庭使用的座椅，是指安全、舒適，並適合兒童、父母和年長親人的座椅。"},{"en":"Benches near shade and toilets can be family-friendly seating.","zh":"位於樹蔭和洗手間附近的長椅可以是適合家庭使用的座椅。"},{"en":"Families stay longer in public places when seating supports different ages.","zh":"當座椅支援不同年齡的人時，家庭會在公共地方停留更久。"},{"en":"This phrase shows that good design considers real users, not only appearance.","zh":"這個短語顯示良好設計考慮真實使用者，而不只是外觀。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"ensuring that","meaning":"確保","examples":[{"en":"Planners should design the area while ensuring that no operator dominates it.","zh":"規劃者應設計該區，同時確保沒有營運者主導它。"},{"en":"Ensuring that means making sure a certain condition is achieved or protected.","zh":"確保是指保證某個條件能達成或受到保護。"},{"en":"A school event should be planned while ensuring that all students can join safely.","zh":"學校活動應在確保所有學生能安全參與的情況下規劃。"},{"en":"Ensuring fair access prevents public space from becoming private in practice.","zh":"確保公平使用能防止公共空間在實際上變成私人地方。"},{"en":"This phrase shows careful control over the result of an action.","zh":"這個短語顯示對行動結果的細心控制。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"commercial operator","meaning":"商業營運者","examples":[{"en":"No single commercial operator should dominate the harbourfront.","zh":"不應有單一商業營運者主導海濱。"},{"en":"A commercial operator is a business or company that runs services, shops, or facilities for profit.","zh":"商業營運者是為盈利而經營服務、商店或設施的企業或公司。"},{"en":"A café company, event organiser, or shopping mall manager can be a commercial operator.","zh":"咖啡店公司、活動主辦者或商場管理者都可以是商業營運者。"},{"en":"Commercial operators may improve services, but they should not control public space.","zh":"商業營運者可以改善服務，但不應控制公共空間。"},{"en":"This phrase helps identify who might gain too much power over a shared place.","zh":"這個短語幫助指出誰可能在共享地方取得過多權力。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"dominate","meaning":"主導","examples":[{"en":"No single commercial operator should dominate public space.","zh":"不應有單一商業營運者主導公共空間。"},{"en":"To dominate means to control or strongly influence something more than others do.","zh":"主導是指比其他人更強地控制或影響某事。"},{"en":"A shopping mall dominates an area if every path forces people through its shops.","zh":"如果每條路都迫使人經過商店，商場就是主導該區。"},{"en":"When one company dominates public space, ordinary users may feel less free.","zh":"當一間公司主導公共空間時，普通使用者可能感到較不自由。"},{"en":"This word warns against unequal control.","zh":"這個詞警告人注意不平等控制。"}],"source":"2015 Q5.pdf","sourcePage":15},{"front":"central to Hong Kong’s identity","meaning":"對香港身份十分重要","examples":[{"en":"Victoria Harbour has always been central to Hong Kong’s identity.","zh":"維多利亞港一直對香港身份十分重要。"},{"en":"Central to Hong Kong’s identity means very important to how Hong Kong understands and presents itself.","zh":"對香港身份十分重要，是指對香港如何理解和展示自己非常重要。"},{"en":"The harbour is central to Hong Kong’s identity because it appears in history, trade, tourism, and public memory.","zh":"海港對香港身份重要，因為它出現在歷史、貿易、旅遊和公共記憶中。"},{"en":"A place central to identity should be protected with more care than ordinary land.","zh":"對身份重要的地方應比普通土地更小心保護。"},{"en":"This phrase connects geography with culture and belonging.","zh":"這個短語把地理與文化和歸屬感連接起來。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"let us not treat it as","meaning":"讓我們不要把它視為","examples":[{"en":"Let us not treat the harbour as merely another piece of land.","zh":"讓我們不要把海港視為只不過是另一幅土地。"},{"en":"Let us not treat it as means we should avoid seeing or handling it in that mistaken way.","zh":"讓我們不要把它視為某物，是指我們應避免用那種錯誤方式看待或處理它。"},{"en":"Let us not treat a public park as empty land waiting for profit.","zh":"讓我們不要把公共公園視為等待盈利的空地。"},{"en":"This phrase sounds formal and persuasive because it calls on the whole community.","zh":"這個短語聽起來正式而有說服力，因為它呼籲整個社群。"},{"en":"It warns readers to change their attitude before making a decision.","zh":"它提醒讀者在作決定前先改變態度。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"merely another piece of land","meaning":"只不過是另一幅土地","examples":[{"en":"The harbour should not be treated as merely another piece of land.","zh":"海港不應被視為只不過是另一幅土地。"},{"en":"Merely another piece of land means only ordinary land with no special public, cultural, or emotional value.","zh":"只不過是另一幅土地，是指只是普通土地，沒有特別公共、文化或情感價值。"},{"en":"A historic square should not be treated as merely another piece of land for sale.","zh":"歷史廣場不應被視為只不過是另一幅可出售土地。"},{"en":"Calling the harbour merely land ignores its role in the city’s identity.","zh":"把海港只稱為土地，會忽視它在城市身份中的作用。"},{"en":"This phrase criticises a narrow view of place.","zh":"這個短語批評對地方的狹窄看法。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"be sold, leased or fenced off","meaning":"被出售、出租或圍封","examples":[{"en":"The harbour should not be sold, leased or fenced off.","zh":"海港不應被出售、出租或圍封。"},{"en":"To be sold, leased or fenced off means to be transferred, rented out, or physically blocked from public use.","zh":"被出售、出租或圍封，是指被轉讓、租出或用實體阻隔方式阻止公眾使用。"},{"en":"A public garden loses its openness if it is sold, leased, or fenced off for private events.","zh":"如果公共花園被出售、出租或圍封作私人活動，它就失去開放性。"},{"en":"These actions can gradually turn shared land into restricted space.","zh":"這些行動可以逐漸把共享土地變成受限制空間。"},{"en":"This phrase lists ways public access can be lost.","zh":"這個短語列出公共使用權可能失去的方式。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"fenced off","meaning":"被圍封","examples":[{"en":"The harbourfront should not be fenced off from the public.","zh":"海濱不應被圍封，使公眾無法進入。"},{"en":"Fenced off means blocked by fences or barriers so people cannot enter freely.","zh":"被圍封是指被圍欄或障礙物阻擋，使人不能自由進入。"},{"en":"A playground is fenced off when gates are locked and residents cannot use it.","zh":"當遊樂場閘門上鎖、居民不能使用時，它就是被圍封。"},{"en":"Fencing off public waterfront land can make citizens feel excluded from their own city.","zh":"圍封公共海濱土地，可能令市民感到被自己的城市排除在外。"},{"en":"This phrase gives a physical image of lost access.","zh":"這個短語給出使用權失去的實體意象。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"remain what it ought to be","meaning":"保持它應有的樣子","examples":[{"en":"The harbour should remain what it ought to be.","zh":"海港應保持它應有的樣子。"},{"en":"Remain what it ought to be means continue to serve its proper and rightful purpose.","zh":"保持它應有的樣子，是指繼續服務其正當和應有目的。"},{"en":"A school library should remain what it ought to be: a place for reading and learning.","zh":"學校圖書館應保持它應有的樣子：一個閱讀和學習的地方。"},{"en":"The harbour remains what it ought to be when it is open, shared, and alive.","zh":"當海港開放、共享而有生命力時，它就保持了應有的樣子。"},{"en":"This phrase appeals to duty, identity, and proper use.","zh":"這個短語訴諸責任、身份和正確用途。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"where the whole city can breathe","meaning":"讓整個城市都能呼吸的地方","examples":[{"en":"The harbour should be a place where the whole city can breathe.","zh":"海港應是一個讓整個城市都能呼吸的地方。"},{"en":"Where the whole city can breathe means a shared place that gives everyone relief from crowding and pressure.","zh":"讓整個城市都能呼吸的地方，是指給所有人從擠迫和壓力中得到紓緩的共享地方。"},{"en":"A large public park can be a place where the whole neighbourhood can breathe.","zh":"大型公共公園可以是一個讓整個社區都能呼吸的地方。"},{"en":"The harbour lets the city breathe when people can walk, rest, and look across open water.","zh":"當人們可以散步、休息和望向開闊水面時，海港就讓城市呼吸。"},{"en":"This phrase ends with an image of public space as life-giving.","zh":"這個短語以公共空間帶來生命力的意象作結。"}],"source":"2015 Q5.pdf","sourcePage":16},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"The letter ends with Yours faithfully.","zh":"這封信以「謹啟」結尾。"},{"en":"Yours faithfully is a formal closing used at the end of a letter when the writer does not know the recipient personally.","zh":"「謹啟」是正式信件結尾使用的禮貌結語，通常用於作者不熟悉收信人的情況。"},{"en":"A student may end a letter to a newspaper editor with Yours faithfully.","zh":"學生可能以「謹啟」結束寫給報章編輯的信。"},{"en":"This closing shows respect and completes the formal letter structure.","zh":"這個結語表示尊重，並完成正式信件結構。"},{"en":"It is more suitable for public or official letters than casual messages.","zh":"它比隨意訊息更適合公開或正式信件。"}],"source":"2015 Q5.pdf","sourcePage":16}],"dse/writing/part-b/2015/Q6":[{"front":"Dear Ms Lee","meaning":"李女士鈞鑒","examples":[{"en":"A formal email to Ms Lee can begin with “Dear Ms Lee”.","zh":"寫給李女士的正式電郵可以以 “Dear Ms Lee” 開始。"},{"en":"“Dear Ms Lee” is a polite opening used when writing to a named woman in a formal email.","zh":"“Dear Ms Lee” 是寫給一位已知姓名女士時使用的禮貌正式開首語。"},{"en":"A student may write “Dear Ms Lee” before asking a teacher for help.","zh":"學生在請老師幫忙前，可能會寫 “Dear Ms Lee”。"},{"en":"In business writing, this greeting shows respect and keeps the tone professional.","zh":"在商業寫作中，這個稱呼顯示尊重，並保持語氣專業。"},{"en":"It is more formal than simply writing “Hi Ms Lee”.","zh":"它比單純寫 “Hi Ms Lee” 更正式。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"recent complaint concerning","meaning":"關於……的近期投訴","examples":[{"en":"This email summarises a recent complaint concerning a 5G plan upgrade.","zh":"這封電郵概述一宗關於 5G 計劃升級的近期投訴。"},{"en":"A recent complaint concerning something is a complaint made not long ago about that issue.","zh":"關於某事的近期投訴，是指不久前就該問題提出的投訴。"},{"en":"A shop may receive a recent complaint concerning a wrong delivery.","zh":"商店可能收到一宗關於送錯貨的近期投訴。"},{"en":"This phrase helps the writer identify the subject of the complaint clearly.","zh":"這個片語幫助作者清楚指出投訴主題。"},{"en":"It is useful in formal emails because it sounds precise and professional.","zh":"它在正式電郵中有用，因為語氣精確而專業。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"5G plan upgrade","meaning":"5G計劃升級","examples":[{"en":"The complaint concerns a 5G plan upgrade.","zh":"這宗投訴關於 5G 計劃升級。"},{"en":"A 5G plan upgrade means changing from an older mobile service plan to a 5G plan.","zh":"5G 計劃升級意思是由較舊的流動服務計劃轉為 5G 計劃。"},{"en":"A customer may expect faster data after a 5G plan upgrade.","zh":"顧客在 5G 計劃升級後可能期望有更快數據速度。"},{"en":"If the upgrade creates extra charges, the customer may complain.","zh":"如果升級帶來額外收費，顧客可能會投訴。"},{"en":"This phrase is common when discussing mobile phone service changes.","zh":"這個片語常用於討論手機服務變更。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"recommended follow-up","meaning":"建議跟進行動","examples":[{"en":"The email explains the recommended follow-up after the complaint.","zh":"這封電郵解釋投訴後的建議跟進行動。"},{"en":"Recommended follow-up means the suggested actions to take after a problem has been reported.","zh":"recommended follow-up 指問題被報告後建議採取的行動。"},{"en":"After a customer complaint, recommended follow-up may include a call and refund review.","zh":"顧客投訴後，建議跟進行動可能包括致電和檢視退款。"},{"en":"Good follow-up helps stop a small problem from becoming larger.","zh":"良好跟進有助防止小問題變大。"},{"en":"This phrase shows that the email is practical, not only descriptive.","zh":"這個片語顯示電郵是實際的，而不只是描述問題。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"I am writing to summarise","meaning":"我寫信是為了概述","examples":[{"en":"I am writing to summarise a recent complaint from Ms Chan.","zh":"我寫信是為了概述陳女士的一宗近期投訴。"},{"en":"“I am writing to summarise” is a formal way to state the purpose of an email.","zh":"“I am writing to summarise” 是正式說明電郵目的的說法。"},{"en":"A staff member may write this before reporting a customer service issue.","zh":"職員在匯報客戶服務問題前可能會這樣寫。"},{"en":"This phrase tells the reader that the email will give the main points.","zh":"這個片語告訴讀者電郵會交代主要重點。"},{"en":"It helps the email begin clearly and professionally.","zh":"它幫助電郵清楚而專業地開始。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"received from","meaning":"收到來自……","examples":[{"en":"The complaint was received from Ms Katherine Chan.","zh":"這宗投訴收到來自 Katherine Chan 女士。"},{"en":"Received from means obtained or sent by a particular person or source.","zh":"received from 意思是由某人或某來源收到。"},{"en":"The office received an email from a customer about poor service.","zh":"辦公室收到來自顧客的一封關於差劣服務的電郵。"},{"en":"Saying who the complaint was received from helps identify the case.","zh":"說明投訴來自誰，有助識別個案。"},{"en":"This phrase is useful when recording formal information.","zh":"這個片語適合用於記錄正式資料。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"a long-standing customer","meaning":"長期客戶","examples":[{"en":"Ms Chan is a long-standing customer of Hong Kong Mobile.","zh":"陳女士是 Hong Kong Mobile 的長期客戶。"},{"en":"A long-standing customer is someone who has used a company’s service for a long time.","zh":"長期客戶是長時間使用某公司服務的人。"},{"en":"A bank may treat a long-standing customer carefully because the relationship is valuable.","zh":"銀行可能會謹慎對待長期客戶，因為這段關係有價值。"},{"en":"Losing a long-standing customer can damage repeat business and reputation.","zh":"失去長期客戶可能損害回頭生意和聲譽。"},{"en":"This phrase shows why the complaint deserves careful handling.","zh":"這個片語顯示投訴值得仔細處理。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"suggest three possible actions","meaning":"建議三項可行行動","examples":[{"en":"I would like to suggest three possible actions for your consideration.","zh":"我想建議三項可行行動，供你考慮。"},{"en":"To suggest three possible actions means to offer three practical steps that may solve the problem.","zh":"suggest three possible actions 意思是提出三個可能解決問題的實際步驟。"},{"en":"A manager may suggest three possible actions after reviewing a complaint.","zh":"經理檢視投訴後，可能會建議三項可行行動。"},{"en":"Giving several options helps the decision-maker choose the best response.","zh":"提供幾個選項有助決策者選擇最佳回應。"},{"en":"This phrase makes the email solution-focused.","zh":"這個片語令電郵著重解決方案。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"for your consideration","meaning":"供你考慮","examples":[{"en":"These actions are suggested for your consideration.","zh":"這些行動是供你考慮的建議。"},{"en":"For your consideration means for you to think about before making a decision.","zh":"for your consideration 意思是讓你在作決定前思考。"},{"en":"A junior staff member may offer a proposal for a manager’s consideration.","zh":"初級職員可能提出建議，供經理考慮。"},{"en":"This phrase is polite because it does not force the reader to agree.","zh":"這個片語有禮貌，因為它沒有迫使讀者同意。"},{"en":"It is often used when giving suggestions to someone senior.","zh":"它常用於向較高級的人提出建議。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"by way of background","meaning":"作為背景資料","examples":[{"en":"By way of background, Ms Chan upgraded her mobile plan in July.","zh":"作為背景資料，陳女士在七月升級了手機計劃。"},{"en":"By way of background means the writer is giving useful context before the main details.","zh":"by way of background 意思是作者在交代主要細節前提供有用背景。"},{"en":"By way of background, the customer had used the same plan for five years.","zh":"作為背景資料，該顧客已使用同一計劃五年。"},{"en":"This phrase helps readers understand what happened before the complaint.","zh":"這個片語幫助讀者理解投訴前發生了甚麼。"},{"en":"It is useful when a case needs explanation before recommendations.","zh":"當個案在提出建議前需要解釋時，它很有用。"}],"source":"2015 Q6.pdf","sourcePage":1},{"front":"upgrade from…to…","meaning":"由……升級至……","examples":[{"en":"Ms Chan upgraded from her existing 4G plan to a 5G plan.","zh":"陳女士由現有 4G 計劃升級至 5G 計劃。"},{"en":"Upgrade from one plan to another means change to a newer or higher-level service.","zh":"upgrade from one plan to another 意思是轉用較新或較高級的服務。"},{"en":"A customer may upgrade from a basic plan to an unlimited plan.","zh":"顧客可能由基本計劃升級至無限計劃。"},{"en":"Problems can arise if the new plan does not perform better than the old one.","zh":"如果新計劃沒有比舊計劃表現更好，便可能出現問題。"},{"en":"This structure clearly shows the starting point and the new choice.","zh":"這個結構清楚顯示起點和新選擇。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"existing 4G plan","meaning":"現有4G計劃","examples":[{"en":"Ms Chan upgraded from her existing 4G plan.","zh":"陳女士由她的現有 4G 計劃升級。"},{"en":"An existing 4G plan is the mobile service plan a customer already has before any change.","zh":"現有 4G 計劃是顧客在作出任何變更前已經使用的流動服務計劃。"},{"en":"A customer may compare a new 5G plan with her existing 4G plan before upgrading.","zh":"顧客在升級前可能會把新的 5G 計劃與現有 4G 計劃比較。"},{"en":"If the new plan is worse, the customer may want to return to the existing plan.","zh":"如果新計劃更差，顧客可能想回復原有計劃。"},{"en":"This phrase helps show what service the customer had before.","zh":"這個片語幫助顯示顧客之前使用甚麼服務。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"5G Unlimited Plus plan","meaning":"5G無限Plus計劃","examples":[{"en":"She upgraded to the “5G Unlimited Plus” plan.","zh":"她升級至「5G 無限 Plus」計劃。"},{"en":"The “5G Unlimited Plus” plan is the name of the mobile service Ms Chan chose.","zh":"「5G 無限 Plus」計劃是陳女士選擇的流動服務名稱。"},{"en":"A plan name helps staff identify the exact service in the system.","zh":"計劃名稱幫助職員在系統中識別確切服務。"},{"en":"Customers may expect strong coverage and high data speed from a plan with this name.","zh":"顧客可能會從這個名稱期望有強網絡覆蓋和高速數據。"},{"en":"Naming the plan clearly prevents confusion during the complaint investigation.","zh":"清楚說出計劃名稱可避免投訴調查期間出現混亂。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"Causeway Bay branch","meaning":"銅鑼灣分店","examples":[{"en":"Ms Chan upgraded her plan at the Causeway Bay branch.","zh":"陳女士在銅鑼灣分店升級她的計劃。"},{"en":"The Causeway Bay branch is the shop location where the service change was made.","zh":"銅鑼灣分店是作出服務更改的店舖地點。"},{"en":"A customer may return to the same branch if she has questions about the contract.","zh":"如果顧客對合約有疑問，可能會回到同一分店查詢。"},{"en":"Naming the branch helps the company check which staff handled the sale.","zh":"說明分店有助公司查核哪位職員處理了銷售。"},{"en":"This detail is important when reviewing sales procedures.","zh":"這個細節在檢討銷售程序時很重要。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"sales representative","meaning":"銷售代表","examples":[{"en":"A sales representative explained the new plan to Ms Chan.","zh":"一名銷售代表向陳女士解釋新計劃。"},{"en":"A sales representative is a staff member who explains products and helps customers buy services.","zh":"銷售代表是解釋產品並協助顧客購買服務的職員。"},{"en":"A good sales representative should explain fees, limits, and contract terms clearly.","zh":"好的銷售代表應清楚解釋收費、限制和合約條款。"},{"en":"If the explanation is unclear, customers may later feel misled.","zh":"如果解釋不清，顧客之後可能覺得被誤導。"},{"en":"This role is important because the customer often relies on the salesperson’s words.","zh":"這個角色很重要，因為顧客往往依賴銷售員的說法。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"assure someone that","meaning":"向某人保證","examples":[{"en":"The sales representative assured her that the new plan would provide better service.","zh":"銷售代表向她保證新計劃會提供更好服務。"},{"en":"To assure someone that something is true means to tell them confidently so they feel safe.","zh":"assure someone that 意思是有信心地告訴某人某事是真的，令對方安心。"},{"en":"A doctor may assure a patient that the test is simple and safe.","zh":"醫生可能向病人保證檢查簡單而安全。"},{"en":"If staff assure customers incorrectly, trust can be damaged.","zh":"如果職員錯誤地向顧客保證，信任可能受損。"},{"en":"This phrase often creates responsibility because the customer relies on the assurance.","zh":"這個片語常帶有責任，因為顧客會依賴該保證。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"provide stronger coverage","meaning":"提供更強網絡覆蓋","examples":[{"en":"The new plan was expected to provide stronger coverage.","zh":"新計劃原本預期會提供更強網絡覆蓋。"},{"en":"To provide stronger coverage means to give a better mobile signal in more places.","zh":"provide stronger coverage 意思是在更多地方提供更好的手機訊號。"},{"en":"Customers expect stronger coverage when they pay for an upgraded plan.","zh":"顧客支付升級計劃費用時，會期望有更強網絡覆蓋。"},{"en":"If coverage remains weak at home, the upgrade may feel pointless.","zh":"如果家中網絡覆蓋仍然薄弱，升級可能感覺沒有意義。"},{"en":"This phrase is central to complaints about mobile network quality.","zh":"這個片語是流動網絡質素投訴的核心。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"faster data speed","meaning":"更快數據速度","examples":[{"en":"Ms Chan expected faster data speed after the upgrade.","zh":"陳女士期望升級後有更快數據速度。"},{"en":"Faster data speed means mobile internet works more quickly when loading pages, videos, or calls.","zh":"更快數據速度意思是流動網絡在載入網頁、影片或通話時更快。"},{"en":"Faster data speed helps users join video meetings without freezing.","zh":"更快數據速度幫助用戶參與視像會議而不會畫面停頓。"},{"en":"If data becomes slower after an upgrade, the customer may feel cheated.","zh":"如果升級後數據反而變慢，顧客可能覺得被欺騙。"},{"en":"This phrase describes one of the main promised benefits of a 5G plan.","zh":"這個片語描述 5G 計劃承諾的主要好處之一。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"unexpected additional charges","meaning":"意料之外的額外收費","examples":[{"en":"She was told there would be no unexpected additional charges.","zh":"她被告知不會有意料之外的額外收費。"},{"en":"Unexpected additional charges are extra fees the customer did not know about beforehand.","zh":"unexpected additional charges 指顧客事前不知道的額外費用。"},{"en":"A bill with hidden fees may create unexpected additional charges.","zh":"有隱藏收費的帳單可能產生意料之外的額外收費。"},{"en":"Such charges can damage trust if they were not explained before signing.","zh":"如果簽約前沒有解釋，這些收費可能損害信任。"},{"en":"Clear disclosure helps prevent disputes over extra costs.","zh":"清楚披露有助防止額外費用爭議。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"lead someone to consider","meaning":"令某人考慮","examples":[{"en":"The complaint has led the department to consider several actions.","zh":"這宗投訴令部門考慮幾項行動。"},{"en":"To lead someone to consider something means to cause them to think seriously about it.","zh":"lead someone to consider 意思是令某人認真思考某事。"},{"en":"A rise in complaints may lead a company to consider changing its procedures.","zh":"投訴增加可能令公司考慮改變程序。"},{"en":"This complaint led staff to consider compensation and technical checks.","zh":"這宗投訴令職員考慮賠償和技術檢查。"},{"en":"The phrase shows that a problem has produced a possible response.","zh":"這個片語顯示問題引出了可能回應。"}],"source":"2015 Q6.pdf","sourcePage":2},{"front":"immediate compensation","meaning":"即時賠償","examples":[{"en":"The department is considering immediate compensation.","zh":"部門正在考慮即時賠償。"},{"en":"Immediate compensation means quick payment, credit, or benefit offered soon after a problem.","zh":"immediate compensation 指問題發生後很快提供的付款、回贈或利益。"},{"en":"A company may offer immediate compensation after charging a customer wrongly.","zh":"公司向顧客錯誤收費後，可能提供即時賠償。"},{"en":"Immediate compensation can calm anger while the investigation continues.","zh":"即時賠償可以在調查繼續期間平息憤怒。"},{"en":"This phrase shows a practical response to inconvenience.","zh":"這個片語顯示對不便作出的實際回應。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"a technical review","meaning":"技術檢視","examples":[{"en":"The company should carry out a technical review.","zh":"公司應進行技術檢視。"},{"en":"A technical review is a careful check of systems, equipment, or network performance.","zh":"技術檢視是對系統、設備或網絡表現作仔細檢查。"},{"en":"A mobile company may conduct a technical review when customers report weak signals.","zh":"當顧客報告訊號弱時，流動網絡公司可能進行技術檢視。"},{"en":"A review can show whether the problem is temporary maintenance or poor coverage.","zh":"檢視可以顯示問題是臨時維修還是網絡覆蓋差。"},{"en":"This phrase suggests using facts before deciding responsibility.","zh":"這個片語表示在判斷責任前先使用事實。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"clearer sales procedures","meaning":"更清晰的銷售程序","examples":[{"en":"The complaint shows the need for clearer sales procedures.","zh":"這宗投訴顯示需要更清晰的銷售程序。"},{"en":"Clearer sales procedures are better steps that help staff explain terms and charges accurately.","zh":"clearer sales procedures 指幫助職員準確解釋條款和收費的更好步驟。"},{"en":"A checklist can create clearer sales procedures before customers sign contracts.","zh":"顧客簽署合約前使用清單，可以建立更清晰的銷售程序。"},{"en":"Without clear procedures, different staff may give different explanations.","zh":"沒有清晰程序，不同職員可能給出不同解釋。"},{"en":"This phrase points to a wider improvement beyond one complaint.","zh":"這個片語指出個別投訴以外的更廣泛改善。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"in order to","meaning":"為了","examples":[{"en":"The company should act quickly in order to restore customer confidence.","zh":"公司應迅速行動，為了恢復顧客信心。"},{"en":"In order to means for the purpose of doing or achieving something.","zh":"in order to 意思是為了做某事或達成某目標。"},{"en":"Staff should call the customer in order to explain the next steps.","zh":"職員應致電顧客，為了解釋下一步。"},{"en":"The company may waive charges in order to reduce frustration.","zh":"公司可能豁免收費，為了減少不滿。"},{"en":"This phrase clearly links an action with its purpose.","zh":"這個片語清楚連接行動和目的。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"restore the customer’s confidence","meaning":"恢復顧客信心","examples":[{"en":"The company needs to restore the customer’s confidence.","zh":"公司需要恢復顧客信心。"},{"en":"To restore the customer’s confidence means to help the customer trust the company again.","zh":"restore the customer’s confidence 意思是幫助顧客重新信任公司。"},{"en":"A clear apology and quick solution can restore customer confidence.","zh":"清楚道歉和快速解決方案可以恢復顧客信心。"},{"en":"If a complaint is ignored, confidence may fall further.","zh":"如果投訴被忽視，信心可能進一步下降。"},{"en":"Restoring confidence takes action, not only polite words.","zh":"恢復信心需要行動，而不只是禮貌說話。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"prevent the matter from escalating","meaning":"防止事件升級","examples":[{"en":"Prompt action can prevent the matter from escalating.","zh":"迅速行動可以防止事件升級。"},{"en":"To prevent the matter from escalating means to stop the problem from becoming more serious.","zh":"prevent the matter from escalating 意思是阻止問題變得更嚴重。"},{"en":"A quick call may prevent a complaint from escalating to social media.","zh":"一通快速電話可能防止投訴升級至社交媒體。"},{"en":"If nobody replies, the matter may escalate into a public dispute.","zh":"如果沒有人回覆，事件可能升級成公開爭議。"},{"en":"This phrase shows why early action is important.","zh":"這個片語顯示及早行動的重要性。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"protect the company’s reputation","meaning":"保護公司聲譽","examples":[{"en":"The company should protect its reputation by handling the case properly.","zh":"公司應透過妥善處理個案來保護其聲譽。"},{"en":"To protect the company’s reputation means to prevent damage to public trust in the company.","zh":"protect the company’s reputation 意思是防止公眾對公司的信任受損。"},{"en":"Good complaint handling can protect reputation even after a service mistake.","zh":"即使出現服務錯誤，良好投訴處理也可以保護聲譽。"},{"en":"Poor responses may make customers warn others online.","zh":"差劣回應可能令顧客在網上提醒他人。"},{"en":"This phrase connects customer service with the company’s public image.","zh":"這個片語把客戶服務與公司的公眾形象連接起來。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"in my view","meaning":"我認為","examples":[{"en":"In my view, the case should be handled carefully.","zh":"我認為，這個個案應謹慎處理。"},{"en":"In my view means in my opinion, and it is used before giving a judgement.","zh":"in my view 意思是「我認為」，用於提出判斷前。"},{"en":"In my view, the company should contact the customer personally.","zh":"我認為，公司應親自聯絡顧客。"},{"en":"This phrase sounds polite because it presents a view rather than an order.","zh":"這個片語聽起來有禮，因為它提出看法，而不是命令。"},{"en":"It is useful when making a professional recommendation.","zh":"它適合用於提出專業建議。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"be handled as","meaning":"被視作……處理","examples":[{"en":"The complaint should be handled as both a service failure and a warning sign.","zh":"這宗投訴應被視作服務失誤和警號來處理。"},{"en":"Be handled as means be treated or dealt with in a particular way.","zh":"be handled as 意思是以某種方式看待或處理。"},{"en":"A billing error should be handled as a customer service issue, not only an accounting problem.","zh":"帳單錯誤應被視作客戶服務問題處理，而不只是會計問題。"},{"en":"Handling the complaint as a warning sign helps the company improve procedures.","zh":"把投訴視作警號處理，有助公司改善程序。"},{"en":"This phrase shows how the case should be understood.","zh":"這個片語顯示個案應如何被理解。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"an individual service failure","meaning":"個別服務失誤","examples":[{"en":"The case may be an individual service failure.","zh":"這個個案可能是一宗個別服務失誤。"},{"en":"An individual service failure is one particular case where service did not meet the expected standard.","zh":"個別服務失誤是指某一個案中的服務未達預期標準。"},{"en":"A missed call-back can be an individual service failure.","zh":"一次未有回覆電話可以是個別服務失誤。"},{"en":"Even one service failure can harm trust if the customer feels ignored.","zh":"即使只有一次服務失誤，如果顧客覺得被忽視，也會損害信任。"},{"en":"This phrase focuses on the specific problem faced by one customer.","zh":"這個片語聚焦於一位顧客面對的具體問題。"}],"source":"2015 Q6.pdf","sourcePage":3},{"front":"a warning sign about","meaning":"關於……的警號","examples":[{"en":"The complaint is a warning sign about communication with customers.","zh":"這宗投訴是關於與顧客溝通的警號。"},{"en":"A warning sign about something is an early signal that a wider problem may exist.","zh":"a warning sign about something 指可能存在更廣泛問題的早期訊號。"},{"en":"Repeated billing complaints may be a warning sign about unclear sales explanations.","zh":"重複的帳單投訴可能是關於銷售解釋不清的警號。"},{"en":"A warning sign should lead to review before the problem grows.","zh":"警號應引起檢討，以免問題擴大。"},{"en":"This phrase shows that one case may reveal a larger weakness.","zh":"這個片語顯示一宗個案可能揭示更大弱點。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"communication with customers","meaning":"與顧客溝通","examples":[{"en":"The company should improve its communication with customers.","zh":"公司應改善與顧客溝通。"},{"en":"Communication with customers means how a company explains information and responds to customers.","zh":"communication with customers 指公司如何解釋資訊和回應顧客。"},{"en":"Clear communication with customers includes explaining fees before they sign.","zh":"清晰與顧客溝通包括在他們簽約前解釋收費。"},{"en":"Poor communication may lead to confusion, anger, and complaints.","zh":"溝通差可能導致混亂、憤怒和投訴。"},{"en":"This phrase is central to improving customer service.","zh":"這個片語是改善客戶服務的核心。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"according to","meaning":"根據","examples":[{"en":"According to Ms Chan, three problems occurred after the upgrade.","zh":"根據陳女士所說，升級後發生了三個問題。"},{"en":"According to means based on what a person or source says.","zh":"according to 意思是根據某人或某來源所說。"},{"en":"According to the bill, two extra charges were added.","zh":"根據帳單，有兩項額外收費被加入。"},{"en":"This phrase helps show where the information comes from.","zh":"這個片語幫助顯示資訊來源。"},{"en":"It is useful in reports because it separates facts from reported claims.","zh":"它在報告中有用，因為能把事實與陳述區分開。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"problems occurred","meaning":"問題發生","examples":[{"en":"Three problems occurred after the plan upgrade.","zh":"計劃升級後發生了三個問題。"},{"en":"Problems occurred means issues happened or appeared.","zh":"problems occurred 意思是問題出現或發生。"},{"en":"Billing problems occurred soon after the customer changed plans.","zh":"顧客轉換計劃後不久，帳單問題發生了。"},{"en":"If problems occur after an upgrade, the company should investigate quickly.","zh":"如果升級後發生問題，公司應迅速調查。"},{"en":"This phrase is neutral and suitable for formal reporting.","zh":"這個片語語氣中性，適合正式匯報。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"after the upgrade","meaning":"升級後","examples":[{"en":"The problems occurred after the upgrade.","zh":"問題在升級後發生。"},{"en":"After the upgrade means once the service plan had been changed to the new one.","zh":"after the upgrade 意思是在服務計劃改為新計劃之後。"},{"en":"The customer expected better service after the upgrade.","zh":"顧客在升級後期望有更好服務。"},{"en":"If performance worsens after the upgrade, the customer may question the sale.","zh":"如果升級後表現變差，顧客可能質疑銷售過程。"},{"en":"This phrase helps show the timing of the complaint.","zh":"這個片語幫助顯示投訴發生的時間。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"network performance","meaning":"網絡表現","examples":[{"en":"The network performance was far from satisfactory.","zh":"網絡表現遠未令人滿意。"},{"en":"Network performance means how well the mobile network works, including signal and speed.","zh":"network performance 指流動網絡運作得如何，包括訊號和速度。"},{"en":"Poor network performance may cause dropped calls and slow data.","zh":"網絡表現差可能導致通話中斷和數據變慢。"},{"en":"Customers expect better network performance after paying for a 5G plan.","zh":"顧客支付 5G 計劃費用後，會期望更好的網絡表現。"},{"en":"This phrase helps describe the service problem technically.","zh":"這個片語有助以技術方式描述服務問題。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"far from satisfactory","meaning":"遠未令人滿意","examples":[{"en":"The service was far from satisfactory after the upgrade.","zh":"升級後的服務遠未令人滿意。"},{"en":"Far from satisfactory means not good enough and clearly below expectations.","zh":"far from satisfactory 意思是不夠好，明顯低於期望。"},{"en":"A hotline response is far from satisfactory if nobody follows up.","zh":"如果沒有人跟進，熱線回應便遠未令人滿意。"},{"en":"If a premium plan performs poorly, customers may say it is far from satisfactory.","zh":"如果高級計劃表現差，顧客可能說它遠未令人滿意。"},{"en":"This phrase is formal but clearly critical.","zh":"這個片語正式，但批評清楚。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"report that","meaning":"報稱","examples":[{"en":"Ms Chan reported that her calls were repeatedly cut off.","zh":"陳女士報稱她的通話多次中斷。"},{"en":"To report that means to state or tell someone that something happened.","zh":"report that 意思是陳述或告知某事發生。"},{"en":"A customer may report that her bill contains unknown charges.","zh":"顧客可能報稱帳單包含不明收費。"},{"en":"This phrase is useful when recording what a complainant says.","zh":"這個片語適合用於記錄投訴人所說的內容。"},{"en":"It does not automatically prove the claim, but it records it clearly.","zh":"它不會自動證明說法屬實，但能清楚記錄。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"calls were repeatedly cut off","meaning":"通話多次中斷","examples":[{"en":"Ms Chan said her calls were repeatedly cut off.","zh":"陳女士表示她的通話多次中斷。"},{"en":"Calls were repeatedly cut off means phone conversations ended suddenly many times.","zh":"calls were repeatedly cut off 意思是電話對話多次突然終止。"},{"en":"Calls may be cut off when the signal is weak inside a building.","zh":"當建築物內訊號弱時，通話可能中斷。"},{"en":"Repeated dropped calls can make business communication impossible.","zh":"通話多次中斷可能令商務溝通無法進行。"},{"en":"This phrase describes a serious service quality problem.","zh":"這個片語描述嚴重服務質素問題。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"in her flat","meaning":"在她的單位內","examples":[{"en":"Calls were repeatedly cut off in her flat in Taikoo Shing.","zh":"她在太古城的單位內通話多次中斷。"},{"en":"In her flat means inside the apartment where she lives.","zh":"in her flat 意思是在她居住的住宅單位內。"},{"en":"A customer expects mobile service to work in her flat, especially if she works from home.","zh":"顧客期望流動服務在她的單位內可用，尤其如果她在家工作。"},{"en":"Weak signal in her flat may affect calls, meetings, and daily communication.","zh":"在她的單位內訊號弱，可能影響通話、會議和日常溝通。"},{"en":"This detail helps the company decide where to test coverage.","zh":"這個細節幫助公司決定在哪裡測試網絡覆蓋。"}],"source":"2015 Q6.pdf","sourcePage":4},{"front":"mobile data","meaning":"流動數據","examples":[{"en":"Mobile data often slowed down after the upgrade.","zh":"升級後，流動數據經常變慢。"},{"en":"Mobile data is internet access provided through a mobile phone network.","zh":"mobile data 是透過流動電話網絡提供的互聯網連接。"},{"en":"People use mobile data for emails, maps, video calls, and websites.","zh":"人們使用流動數據收發電郵、查地圖、視像通話和瀏覽網站。"},{"en":"Slow mobile data can make a 5G plan feel worse than expected.","zh":"流動數據緩慢會令 5G 計劃感覺比預期差。"},{"en":"This phrase identifies the internet part of the service, not voice calls.","zh":"這個片語指出服務中的上網部分，而不是語音通話。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"slow down","meaning":"變慢","examples":[{"en":"Mobile data often slowed down in Taikoo Shing.","zh":"流動數據在太古城經常變慢。"},{"en":"To slow down means to become less fast or less efficient.","zh":"slow down 意思是速度或效率下降。"},{"en":"Internet speed may slow down when many users are online at the same time.","zh":"當許多用戶同時上網時，網速可能變慢。"},{"en":"If data slows down during work, video meetings may fail.","zh":"如果數據在工作期間變慢，視像會議可能失敗。"},{"en":"This phrase describes a change from normal speed to poor performance.","zh":"這個片語描述由正常速度變成差劣表現。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"to the point where","meaning":"到……的程度","examples":[{"en":"The data slowed down to the point where video meetings became impossible.","zh":"數據變慢到視像會議無法進行的程度。"},{"en":"To the point where means reaching a level so serious that a result happens.","zh":"to the point where 意思是達到嚴重至造成某結果的程度。"},{"en":"The rain was heavy to the point where buses stopped running.","zh":"雨大到巴士停止行駛的程度。"},{"en":"Slow data became serious to the point where Ms Chan could not work properly.","zh":"數據緩慢嚴重到陳女士無法正常工作的程度。"},{"en":"This phrase shows the real effect of a problem.","zh":"這個片語顯示問題的實際影響。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"video meetings","meaning":"視像會議","examples":[{"en":"Slow mobile data made video meetings impossible.","zh":"緩慢的流動數據令視像會議無法進行。"},{"en":"Video meetings are online meetings where people use cameras and microphones to communicate.","zh":"視像會議是人們使用鏡頭和咪高峰溝通的網上會議。"},{"en":"Workers need stable data for video meetings with clients or colleagues.","zh":"員工需要穩定數據，才能與客戶或同事進行視像會議。"},{"en":"If video meetings keep freezing, work may be delayed.","zh":"如果視像會議不斷停頓，工作可能延誤。"},{"en":"This phrase shows why the network problem affected Ms Chan’s daily life.","zh":"這個片語顯示網絡問題為何影響陳女士的日常生活。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"first bill","meaning":"第一張帳單","examples":[{"en":"Her first bill included two unexpected charges.","zh":"她的第一張帳單包括兩項意料之外的收費。"},{"en":"The first bill is the first payment statement a customer receives after starting or changing a plan.","zh":"first bill 是顧客開始或更改計劃後收到的第一份付款月結單。"},{"en":"Customers often check the first bill carefully after an upgrade.","zh":"顧客在升級後通常會仔細檢查第一張帳單。"},{"en":"If the first bill contains unexplained charges, trust may be damaged immediately.","zh":"如果第一張帳單包含未解釋收費，信任可能立即受損。"},{"en":"This phrase shows that the billing problem appeared very early.","zh":"這個片語顯示帳單問題很早便出現。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"SIM replacement fee","meaning":"SIM卡更換費","examples":[{"en":"Her bill included a HK$120 SIM replacement fee.","zh":"她的帳單包括一項港幣 120 元的 SIM 卡更換費。"},{"en":"A SIM replacement fee is a charge for changing or issuing a new SIM card.","zh":"SIM replacement fee 是更換或發出新 SIM 卡的收費。"},{"en":"Customers should be told about a SIM replacement fee before they agree to upgrade.","zh":"顧客同意升級前，應被告知 SIM 卡更換費。"},{"en":"If the fee was not explained, the customer may dispute the charge.","zh":"如果該費用沒有被解釋，顧客可能會爭議收費。"},{"en":"This phrase names one specific billing item in the complaint.","zh":"這個片語指出投訴中的一項具體帳單項目。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"administrative adjustment","meaning":"行政調整費","examples":[{"en":"The bill also included a HK$280 administrative adjustment.","zh":"帳單亦包括一項港幣 280 元的行政調整費。"},{"en":"An administrative adjustment is a billing change made for office or account-processing reasons.","zh":"administrative adjustment 是因辦公室或帳戶處理原因而作出的帳單調整。"},{"en":"Customers may not understand an administrative adjustment unless it is clearly explained.","zh":"除非清楚解釋，否則顧客未必明白行政調整費。"},{"en":"A vague adjustment fee can create suspicion and complaints.","zh":"含糊的調整費可能引起懷疑和投訴。"},{"en":"This phrase should be supported by a clear reason on the bill.","zh":"這個片語應在帳單上配合清晰原因。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"neither of which","meaning":"兩者均不","examples":[{"en":"The bill included two charges, neither of which was clearly explained.","zh":"帳單包括兩項收費，兩者均未被清楚解釋。"},{"en":"Neither of which means not one of the two things mentioned.","zh":"neither of which 意思是剛提到的兩件事中沒有任何一件。"},{"en":"The customer received two messages, neither of which answered her question.","zh":"顧客收到兩則訊息，兩者均沒有回答她的問題。"},{"en":"This phrase is useful when criticising two items together.","zh":"這個片語適合用於同時批評兩個項目。"},{"en":"It shows that both charges lacked clear explanation.","zh":"它顯示兩項收費都缺乏清晰解釋。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"clearly explained","meaning":"清楚解釋","examples":[{"en":"The charges were not clearly explained when she signed the contract.","zh":"她簽署合約時，這些收費沒有被清楚解釋。"},{"en":"Clearly explained means described in a way that is easy to understand.","zh":"clearly explained 意思是以容易理解的方式描述。"},{"en":"Fees should be clearly explained before customers agree to a plan.","zh":"顧客同意計劃前，費用應被清楚解釋。"},{"en":"If charges are not clearly explained, customers may feel misled.","zh":"如果收費沒有清楚解釋，顧客可能覺得被誤導。"},{"en":"This phrase focuses on the quality of communication.","zh":"這個片語著重溝通質素。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"sign the contract","meaning":"簽署合約","examples":[{"en":"The fees were not explained before she signed the contract.","zh":"她簽署合約前，這些費用沒有被解釋。"},{"en":"To sign the contract means to agree formally to written terms by signing one’s name.","zh":"sign the contract 意思是簽名正式同意書面條款。"},{"en":"Customers should understand key fees before they sign the contract.","zh":"顧客在簽署合約前應理解主要收費。"},{"en":"Once a contract is signed, disputes become harder to resolve if terms were unclear.","zh":"合約一經簽署，如果條款不清，爭議會更難解決。"},{"en":"This phrase marks the formal moment of agreement.","zh":"這個片語標誌正式同意的一刻。"}],"source":"2015 Q6.pdf","sourcePage":5},{"front":"contact our hotline","meaning":"聯絡我們的熱線","examples":[{"en":"Ms Chan contacted our hotline three times in July.","zh":"陳女士在七月三次聯絡我們的熱線。"},{"en":"To contact our hotline means to call or reach the company’s customer service phone line.","zh":"contact our hotline 意思是致電或聯絡公司的客戶服務電話線。"},{"en":"Customers contact a hotline when they need help with service or billing problems.","zh":"顧客遇到服務或帳單問題時會聯絡熱線。"},{"en":"Repeated hotline contact shows the customer has tried to solve the issue.","zh":"多次聯絡熱線顯示顧客曾嘗試解決問題。"},{"en":"This phrase is useful when describing complaint history.","zh":"這個片語適合用來描述投訴歷史。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"be given different explanations","meaning":"獲得不同解釋","examples":[{"en":"She was given different explanations each time.","zh":"她每次都獲得不同解釋。"},{"en":"Be given different explanations means receive different answers about the same issue.","zh":"be given different explanations 意思是就同一問題收到不同答案。"},{"en":"A customer may feel confused if every staff member gives a different explanation.","zh":"如果每位職員都給出不同解釋，顧客可能感到混亂。"},{"en":"Different explanations suggest that staff may not have clear procedures.","zh":"不同解釋表示職員可能沒有清晰程序。"},{"en":"This phrase points to inconsistency in customer service.","zh":"這個片語指出客戶服務中的不一致。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"each time","meaning":"每次","examples":[{"en":"She was given a different explanation each time.","zh":"她每次都獲得不同解釋。"},{"en":"Each time means on every occasion when something happened.","zh":"each time 意思是每一次某事發生時。"},{"en":"Each time Ms Chan called, she expected a clear answer.","zh":"陳女士每次致電，都期望得到清晰答案。"},{"en":"If the answer changes each time, the customer may lose confidence.","zh":"如果答案每次都不同，顧客可能失去信心。"},{"en":"This phrase shows repetition and pattern.","zh":"這個片語顯示重複和模式。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"restart her phone","meaning":"重新啟動手機","examples":[{"en":"One colleague told her to restart her phone.","zh":"一位同事叫她重新啟動手機。"},{"en":"To restart her phone means to turn the phone off and on again.","zh":"restart her phone 意思是把手機關掉再開啟。"},{"en":"Hotline staff may ask customers to restart their phones to fix simple connection problems.","zh":"熱線職員可能要求顧客重新啟動手機，以解決簡單連接問題。"},{"en":"Restarting a phone may help sometimes, but it does not solve all network issues.","zh":"重新啟動手機有時有幫助，但不能解決所有網絡問題。"},{"en":"This phrase shows one basic troubleshooting suggestion.","zh":"這個片語顯示一項基本故障排除建議。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"be under maintenance","meaning":"正在維修","examples":[{"en":"Another colleague said the district was under maintenance.","zh":"另一位同事說該區正在維修。"},{"en":"Be under maintenance means repairs or technical work are being carried out.","zh":"be under maintenance 意思是正在進行維修或技術工程。"},{"en":"A mobile network may be under maintenance when engineers upgrade equipment.","zh":"當工程師升級設備時，流動網絡可能正在維修。"},{"en":"Customers should be told clearly if their area is under maintenance.","zh":"如果顧客所在地區正在維修，應清楚告知他們。"},{"en":"This phrase explains a possible reason for temporary poor service.","zh":"這個片語解釋暫時服務欠佳的可能原因。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"promise a call-back","meaning":"承諾回覆電話","examples":[{"en":"A third colleague promised a call-back.","zh":"第三位同事承諾回覆電話。"},{"en":"To promise a call-back means to say that someone will telephone the customer later.","zh":"promise a call-back 意思是說稍後會致電顧客。"},{"en":"Staff may promise a call-back after checking technical information.","zh":"職員在查核技術資料後，可能承諾回覆電話。"},{"en":"If a promised call-back is not made, the customer may feel ignored.","zh":"如果承諾的回覆電話沒有作出，顧客可能覺得被忽視。"},{"en":"This phrase creates a duty to follow up.","zh":"這個片語產生跟進責任。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"to date","meaning":"至今","examples":[{"en":"To date, the promised call-back has not been made.","zh":"至今，承諾的回覆電話尚未作出。"},{"en":"To date means up to now.","zh":"to date 意思是到目前為止。"},{"en":"To date, the customer has not received a written explanation.","zh":"至今，顧客仍未收到書面解釋。"},{"en":"This phrase is useful when showing that a problem remains unresolved.","zh":"這個片語適合用來顯示問題仍未解決。"},{"en":"It adds seriousness because time has already passed.","zh":"它增加嚴重性，因為時間已經過去。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"has not been made","meaning":"尚未作出","examples":[{"en":"The promised call-back has not been made.","zh":"承諾的回覆電話尚未作出。"},{"en":"Has not been made means the promised action has still not happened.","zh":"has not been made 意思是承諾的行動仍未發生。"},{"en":"If a refund decision has not been made, the customer may need an update.","zh":"如果退款決定尚未作出，顧客可能需要最新消息。"},{"en":"A call-back that has not been made can become another service failure.","zh":"尚未作出的回覆電話可能變成另一個服務失誤。"},{"en":"This phrase records an incomplete promise.","zh":"這個片語記錄一項未完成的承諾。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"understandably","meaning":"可以理解的是","examples":[{"en":"Understandably, Ms Chan feels disappointed.","zh":"可以理解的是，陳女士感到失望。"},{"en":"Understandably means it is easy to understand why someone feels that way.","zh":"understandably 意思是很容易理解某人為何有那種感受。"},{"en":"Understandably, a customer feels angry after three unanswered calls.","zh":"可以理解的是，顧客在三次電話未獲回覆後會生氣。"},{"en":"This word shows sympathy without blaming anyone too quickly.","zh":"這個字顯示同理心，而不是太快責怪任何人。"},{"en":"It helps the email sound fair and human.","zh":"它令電郵聽起來公平而有人情味。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"be sold a promise rather than a service","meaning":"買到的是承諾而不是服務","examples":[{"en":"Ms Chan feels that she has been sold a promise rather than a service.","zh":"陳女士覺得自己買到的是承諾，而不是服務。"},{"en":"To be sold a promise rather than a service means the customer received claims but not real performance.","zh":"be sold a promise rather than a service 意思是顧客得到的是說法，而不是真正表現。"},{"en":"A customer may feel this way when advertised benefits do not appear.","zh":"當宣傳的好處沒有出現時，顧客可能有這種感覺。"},{"en":"The phrase shows a serious gap between sales language and actual service.","zh":"這個片語顯示銷售說法與實際服務之間有嚴重落差。"},{"en":"It explains why the customer feels disappointed and misled.","zh":"它解釋為何顧客感到失望和被誤導。"}],"source":"2015 Q6.pdf","sourcePage":6},{"front":"ask either to…or to…","meaning":"要求要麼……要麼……","examples":[{"en":"She is asking either to return to her previous plan or to receive compensation.","zh":"她要求要麼回復原本的計劃，要麼獲得賠償。"},{"en":"Ask either to…or to… means request one of two possible actions.","zh":"ask either to…or to… 意思是要求兩個可能行動中的其中一個。"},{"en":"A customer may ask either to exchange the product or to get a refund.","zh":"顧客可能要求要麼換貨，要麼退款。"},{"en":"This structure makes the customer’s preferred solutions clear.","zh":"這個句式令顧客偏好的解決方案清楚。"},{"en":"It helps the company understand what outcomes may satisfy the complaint.","zh":"它幫助公司理解哪些結果可能令投訴得到處理。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"return to her previous plan","meaning":"回復原本的計劃","examples":[{"en":"Ms Chan wants to return to her previous plan.","zh":"陳女士想回復原本的計劃。"},{"en":"To return to her previous plan means to change back to the mobile plan she had before.","zh":"return to her previous plan 意思是轉回她之前使用的手機計劃。"},{"en":"A customer may want to return to a previous plan if the new one performs badly.","zh":"如果新計劃表現差，顧客可能想回復原本的計劃。"},{"en":"Allowing this may be fair if the upgrade was not properly explained.","zh":"如果升級沒有被妥善解釋，容許這樣做可能是公平的。"},{"en":"This phrase shows one practical remedy requested by the customer.","zh":"這個片語顯示顧客要求的一項實際補救方法。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"without penalty","meaning":"無需罰款","examples":[{"en":"She wants to return to her previous plan without penalty.","zh":"她希望無需罰款地回復原本的計劃。"},{"en":"Without penalty means without having to pay a fine or extra charge.","zh":"without penalty 意思是不需要支付罰款或額外費用。"},{"en":"A customer may ask to cancel a contract without penalty if the service fails.","zh":"如果服務失效，顧客可能要求無需罰款地取消合約。"},{"en":"Returning without penalty may be fair when the company caused the problem.","zh":"當問題由公司造成時，無需罰款地回復原狀可能是公平的。"},{"en":"This phrase focuses on removing financial punishment.","zh":"這個片語著重移除金錢懲罰。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"written apology","meaning":"書面道歉","examples":[{"en":"She is asking for a written apology and compensation.","zh":"她要求書面道歉和賠償。"},{"en":"A written apology is an apology given in writing, such as by email or letter.","zh":"written apology 是以文字形式作出的道歉，例如電郵或信件。"},{"en":"A company may send a written apology after failing to return a call.","zh":"公司未能回覆電話後，可能發出書面道歉。"},{"en":"Written apologies create a record and can feel more serious than spoken apologies.","zh":"書面道歉會留下紀錄，並可能比口頭道歉感覺更正式。"},{"en":"This phrase shows the customer wants formal recognition of the problem.","zh":"這個片語顯示顧客希望問題獲得正式承認。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"receive compensation","meaning":"獲得賠償","examples":[{"en":"Ms Chan wants to receive compensation for the poor service.","zh":"陳女士希望因服務欠佳而獲得賠償。"},{"en":"To receive compensation means to get money, credit, or another benefit because of loss or inconvenience.","zh":"receive compensation 意思是因損失或不便而得到金錢、回贈或其他補償。"},{"en":"Customers may receive compensation when they pay for a service that does not work.","zh":"當顧客付費的服務不能正常運作時，可能會獲得賠償。"},{"en":"Compensation can help repair trust, but it should match the seriousness of the problem.","zh":"賠償可以幫助修補信任，但應與問題嚴重程度相稱。"},{"en":"This phrase describes a common remedy in complaint handling.","zh":"這個片語描述投訴處理中的常見補救方法。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"the first action I recommend","meaning":"我建議的第一項行動","examples":[{"en":"The first action I recommend is to appoint one case officer.","zh":"我建議的第一項行動是指派一名個案主任。"},{"en":"The first action I recommend introduces the writer’s first suggested step.","zh":"the first action I recommend 用來引出作者建議的第一個步驟。"},{"en":"The first action I recommend after a complaint is to contact the customer directly.","zh":"投訴後，我建議的第一項行動是直接聯絡顧客。"},{"en":"This phrase helps organise recommendations in a clear order.","zh":"這個片語幫助按清晰次序組織建議。"},{"en":"It signals that more suggested actions will follow.","zh":"它表示之後還會有更多建議行動。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"appoint one case officer","meaning":"指派一名個案主任","examples":[{"en":"The company should appoint one case officer to handle the complaint.","zh":"公司應指派一名個案主任處理投訴。"},{"en":"To appoint one case officer means to choose one staff member to be responsible for the case.","zh":"appoint one case officer 意思是選定一位職員負責該個案。"},{"en":"One case officer can prevent the customer from repeating details many times.","zh":"一名個案主任可以避免顧客多次重複細節。"},{"en":"Appointing one officer gives the customer a clear contact person.","zh":"指派一名主任讓顧客有清晰聯絡人。"},{"en":"This phrase suggests a more organised complaint process.","zh":"這個片語建議更有組織的投訴程序。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"contact someone personally","meaning":"親自聯絡某人","examples":[{"en":"The case officer should contact Ms Chan personally.","zh":"個案主任應親自聯絡陳女士。"},{"en":"To contact someone personally means to speak to that person directly, not through a general message.","zh":"contact someone personally 意思是直接與該人聯絡，而不是只發一般訊息。"},{"en":"A manager may contact a disappointed customer personally to show concern.","zh":"經理可能親自聯絡失望的顧客，以表示關注。"},{"en":"Personal contact can make the customer feel the case is being taken seriously.","zh":"親自聯絡可以令顧客感到個案被認真處理。"},{"en":"This phrase suggests a more human and respectful response.","zh":"這個片語表示更有人情味和尊重的回應。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"resolve the billing dispute","meaning":"解決帳單爭議","examples":[{"en":"The company should resolve the billing dispute quickly.","zh":"公司應迅速解決帳單爭議。"},{"en":"To resolve the billing dispute means to settle disagreement about the charges on a bill.","zh":"resolve the billing dispute 意思是處理關於帳單收費的分歧。"},{"en":"Staff can resolve a billing dispute by checking contract terms and explaining fees.","zh":"職員可透過查核合約條款和解釋費用來解決帳單爭議。"},{"en":"If the dispute is not resolved, the customer may refuse to pay.","zh":"如果爭議沒有解決，顧客可能拒絕付款。"},{"en":"This phrase focuses on solving the money-related part of the complaint.","zh":"這個片語著重解決投訴中與金錢相關的部分。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"no later than this Friday","meaning":"不遲於本星期五","examples":[{"en":"The billing dispute should be resolved no later than this Friday.","zh":"帳單爭議應不遲於本星期五解決。"},{"en":"No later than this Friday means by Friday at the latest.","zh":"no later than this Friday 意思是最遲在本星期五或之前。"},{"en":"A manager may ask staff to reply no later than this Friday to avoid delay.","zh":"經理可能要求職員不遲於本星期五回覆，以避免延誤。"},{"en":"Setting a deadline helps make follow-up accountable.","zh":"設定期限有助令跟進具問責性。"},{"en":"This phrase gives a clear time limit for action.","zh":"這個片語為行動提供清晰時限。"}],"source":"2015 Q6.pdf","sourcePage":7},{"front":"instead of asking her to","meaning":"而不是要求她","examples":[{"en":"Instead of asking her to repeat the details, one officer should handle the case.","zh":"而不是要求她重複細節，應由一名主任處理個案。"},{"en":"Instead of asking her to means choosing not to require her to do something.","zh":"instead of asking her to 意思是選擇不要求她做某事。"},{"en":"Instead of asking her to call again, staff should return the promised call.","zh":"與其要求她再次致電，職員應回覆承諾的電話。"},{"en":"This phrase contrasts an unhelpful action with a better solution.","zh":"這個片語把沒有幫助的行動與更好方案作對比。"},{"en":"It shows consideration for the customer’s time and frustration.","zh":"它顯示對顧客時間和不滿的體諒。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"repeat the same details","meaning":"重複相同細節","examples":[{"en":"Ms Chan should not have to repeat the same details to different staff members.","zh":"陳女士不應需要向不同職員重複相同細節。"},{"en":"To repeat the same details means to explain the same facts again and again.","zh":"repeat the same details 意思是一再解釋同一批事實。"},{"en":"Customers become frustrated when they repeat the same details after every transfer.","zh":"顧客每次被轉接後都要重複相同細節，會感到挫敗。"},{"en":"A good complaint system records details so customers do not have to repeat them.","zh":"好的投訴系統會記錄細節，讓顧客不用重複。"},{"en":"This phrase shows why one case officer is useful.","zh":"這個片語顯示為何一名個案主任有用。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"staff members","meaning":"職員","examples":[{"en":"Different staff members gave Ms Chan different explanations.","zh":"不同職員給了陳女士不同解釋。"},{"en":"Staff members are employees who work for an organisation.","zh":"staff members 是在機構工作的員工。"},{"en":"Staff members should follow the same procedures when handling complaints.","zh":"職員處理投訴時應遵循相同程序。"},{"en":"If staff members give inconsistent answers, customers may lose trust.","zh":"如果職員給出不一致答案，顧客可能失去信任。"},{"en":"This phrase refers to the people involved in delivering service.","zh":"這個片語指參與提供服務的人員。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"acknowledge the inconvenience","meaning":"承認造成不便","examples":[{"en":"The company should acknowledge the inconvenience caused to Ms Chan.","zh":"公司應承認對陳女士造成的不便。"},{"en":"To acknowledge the inconvenience means to recognise that the customer has been troubled.","zh":"acknowledge the inconvenience 意思是承認顧客受到困擾。"},{"en":"A company may acknowledge inconvenience before explaining the solution.","zh":"公司可能先承認造成不便，再解釋解決方案。"},{"en":"Customers often want their frustration to be recognised, not dismissed.","zh":"顧客通常希望自己的挫折被承認，而不是被忽視。"},{"en":"This phrase helps make an apology feel sincere.","zh":"這個片語幫助道歉聽起來真誠。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"waive the disputed charges","meaning":"豁免有爭議的收費","examples":[{"en":"The company should waive the two disputed charges.","zh":"公司應豁免兩項有爭議的收費。"},{"en":"To waive the disputed charges means to cancel the fees that the customer is challenging.","zh":"waive the disputed charges 意思是取消顧客正在爭議的費用。"},{"en":"A company may waive a fee if it was not explained clearly.","zh":"如果費用沒有清楚解釋，公司可能豁免該收費。"},{"en":"Waiving disputed charges can reduce anger while facts are checked.","zh":"在查核事實期間豁免有爭議收費，可以減少憤怒。"},{"en":"This phrase describes a practical billing remedy.","zh":"這個片語描述一項實際帳單補救方法。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"while the case is being investigated","meaning":"在個案調查期間","examples":[{"en":"The charges should be waived while the case is being investigated.","zh":"在個案調查期間，這些收費應被豁免。"},{"en":"While the case is being investigated means during the period when staff are checking the facts.","zh":"while the case is being investigated 意思是在職員查核事實的期間。"},{"en":"A customer should receive updates while the case is being investigated.","zh":"在個案調查期間，顧客應收到最新消息。"},{"en":"Temporary relief can be offered while the investigation continues.","zh":"調查繼續期間，可以提供臨時紓緩安排。"},{"en":"This phrase shows that final responsibility has not yet been decided.","zh":"這個片語顯示最終責任尚未決定。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"offer a goodwill credit","meaning":"提供善意回贈","examples":[{"en":"The company could offer a goodwill credit of one month’s service fee.","zh":"公司可以提供相等於一個月服務費的善意回贈。"},{"en":"A goodwill credit is a credit offered to show care, even before full fault is admitted.","zh":"goodwill credit 是在未承認全部責任前，為表示關心而提供的回贈。"},{"en":"A company may offer a goodwill credit to keep a disappointed customer.","zh":"公司可能提供善意回贈，以挽留失望顧客。"},{"en":"Goodwill credit can reduce frustration without ending the investigation.","zh":"善意回贈可以減少不滿，而不會終止調查。"},{"en":"This phrase shows a gesture of customer care.","zh":"這個片語顯示一種照顧顧客的姿態。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"one month’s service fee","meaning":"一個月服務費","examples":[{"en":"A goodwill credit of one month’s service fee may be offered.","zh":"可以提供相等於一個月服務費的善意回贈。"},{"en":"One month’s service fee means the amount the customer normally pays for one month of service.","zh":"one month’s service fee 指顧客通常為一個月服務支付的金額。"},{"en":"If the plan costs HK$300 per month, one month’s service fee is HK$300.","zh":"如果計劃每月港幣 300 元，一個月服務費就是港幣 300 元。"},{"en":"Offering one month’s fee can be a simple way to compensate inconvenience.","zh":"提供一個月服務費可以是補償不便的簡單方法。"},{"en":"This phrase gives a clear amount for the proposed credit.","zh":"這個片語為建議回贈提供清晰金額。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"amount to","meaning":"等同於","examples":[{"en":"This would not amount to admitting full liability.","zh":"這不會等同於承認全部責任。"},{"en":"Amount to means be equal to or have the same effect as something.","zh":"amount to 意思是等於或具有與某事相同的效果。"},{"en":"Giving a small credit does not always amount to admitting legal responsibility.","zh":"提供小額回贈不一定等同於承認法律責任。"},{"en":"A polite apology may amount to goodwill, not full liability.","zh":"禮貌道歉可能等同於善意，而不是全部責任。"},{"en":"This phrase helps clarify what an action does and does not mean.","zh":"這個片語幫助澄清某行動代表和不代表甚麼。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"admit full liability","meaning":"承認全部責任","examples":[{"en":"The company should not admit full liability before the investigation is complete.","zh":"公司不應在調查完成前承認全部責任。"},{"en":"To admit full liability means to accept complete responsibility for the problem.","zh":"admit full liability 意思是接受問題的全部責任。"},{"en":"A company may offer temporary help without admitting full liability.","zh":"公司可以提供臨時幫助，而不承認全部責任。"},{"en":"Full liability should be decided after checking records and technical facts.","zh":"是否承認全部責任應在查核紀錄和技術事實後決定。"},{"en":"This phrase is important when balancing customer care with legal caution.","zh":"這個片語在平衡客戶關懷和法律謹慎時很重要。"}],"source":"2015 Q6.pdf","sourcePage":8},{"front":"before the investigation is complete","meaning":"在調查完成之前","examples":[{"en":"Full liability should not be admitted before the investigation is complete.","zh":"在調查完成之前，不應承認全部責任。"},{"en":"Before the investigation is complete means before all facts have been checked.","zh":"before the investigation is complete 意思是在所有事實被查核之前。"},{"en":"Staff should avoid final conclusions before the investigation is complete.","zh":"在調查完成之前，職員應避免作出最終結論。"},{"en":"This phrase explains why some decisions must wait for evidence.","zh":"這個片語解釋為何某些決定必須等待證據。"},{"en":"It helps the company act fairly and carefully.","zh":"它幫助公司公平而謹慎地行事。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"take someone’s experience seriously","meaning":"認真看待某人的經歷","examples":[{"en":"A goodwill credit would show that we take her experience seriously.","zh":"善意回贈會顯示我們認真看待她的經歷。"},{"en":"To take someone’s experience seriously means to treat what happened to them as important and real.","zh":"take someone’s experience seriously 意思是把某人經歷的事情視為重要和真實。"},{"en":"Customers feel respected when companies take their complaints seriously.","zh":"當公司認真看待投訴時，顧客會感到被尊重。"},{"en":"Ignoring repeated calls would suggest the company does not take the experience seriously.","zh":"忽視多次來電會顯示公司沒有認真看待該經歷。"},{"en":"This phrase shows empathy and responsibility.","zh":"這個片語顯示同理心和責任感。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"leave the complaint hanging","meaning":"讓投訴懸而未決","examples":[{"en":"We should not leave the complaint hanging.","zh":"我們不應讓投訴懸而未決。"},{"en":"To leave the complaint hanging means to leave it unresolved without clear action or answer.","zh":"leave the complaint hanging 意思是不作清晰行動或答覆，讓投訴未解決。"},{"en":"A complaint is left hanging when nobody replies after promising a call-back.","zh":"承諾回覆電話後沒有人回覆，投訴便被懸而未決。"},{"en":"Leaving a complaint hanging can make the customer more angry.","zh":"讓投訴懸而未決可能令顧客更加憤怒。"},{"en":"This phrase stresses the need for timely follow-up.","zh":"這個片語強調及時跟進的需要。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"run the risk of","meaning":"冒着……的風險","examples":[{"en":"If we delay, we run the risk of public criticism.","zh":"如果我們拖延，便冒着受到公開批評的風險。"},{"en":"To run the risk of something means to face the possibility of a bad result.","zh":"run the risk of 意思是面對某種壞結果可能出現的風險。"},{"en":"A company runs the risk of losing customers if it ignores complaints.","zh":"如果公司忽視投訴，便冒着失去顧客的風險。"},{"en":"Delayed replies run the risk of pushing customers to social media.","zh":"延遲回覆會冒着把顧客推向社交媒體的風險。"},{"en":"This phrase warns about a possible consequence.","zh":"這個片語提醒可能後果。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"turn one disappointed customer into","meaning":"把一名失望顧客變成","examples":[{"en":"Poor handling may turn one disappointed customer into a public critic.","zh":"處理不善可能把一名失望顧客變成公開批評者。"},{"en":"To turn one disappointed customer into something means to make one unhappy person become a bigger problem.","zh":"turn one disappointed customer into something 意思是令一位不滿的人變成更大問題。"},{"en":"Ignoring a complaint can turn one customer into an online critic.","zh":"忽視投訴可能把一位顧客變成網上批評者。"},{"en":"Careful handling can stop disappointment from becoming public anger.","zh":"謹慎處理可以防止失望變成公開憤怒。"},{"en":"This phrase shows how poor service can worsen a situation.","zh":"這個片語顯示差劣服務如何令情況惡化。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"public criticism on social media","meaning":"社交媒體上的公開批評","examples":[{"en":"The complaint could become public criticism on social media.","zh":"這宗投訴可能變成社交媒體上的公開批評。"},{"en":"Public criticism on social media means negative comments shared openly on platforms such as Facebook or Instagram.","zh":"public criticism on social media 指在 Facebook 或 Instagram 等平台公開分享的負面評論。"},{"en":"Customers may post public criticism when they feel ignored by a company.","zh":"當顧客覺得被公司忽視時，可能會發表公開批評。"},{"en":"Online criticism can spread quickly and damage reputation.","zh":"網上批評可以快速傳播並損害聲譽。"},{"en":"This phrase shows why companies should respond before issues become public.","zh":"這個片語顯示公司為何應在問題公開前回應。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"network operations team","meaning":"網絡營運團隊","examples":[{"en":"The network operations team should conduct a coverage and speed test.","zh":"網絡營運團隊應進行網絡覆蓋及速度測試。"},{"en":"The network operations team is the technical team responsible for checking and managing the network.","zh":"network operations team 是負責檢查和管理網絡的技術團隊。"},{"en":"This team can test whether signal strength is weak near a customer’s home.","zh":"這個團隊可以測試顧客住所附近訊號是否薄弱。"},{"en":"Customer service staff need technical findings from the network operations team.","zh":"客戶服務職員需要網絡營運團隊提供技術結果。"},{"en":"This phrase identifies who should handle the technical side of the case.","zh":"這個片語指出誰應處理個案中的技術部分。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"conduct a coverage and speed test","meaning":"進行網絡覆蓋及速度測試","examples":[{"en":"The team should conduct a coverage and speed test near Ms Chan’s home.","zh":"團隊應在陳女士住所附近進行網絡覆蓋及速度測試。"},{"en":"To conduct a coverage and speed test means to check signal strength and internet speed in a specific area.","zh":"conduct a coverage and speed test 意思是在特定地區檢查訊號強度和網速。"},{"en":"Engineers may conduct this test after customers report dropped calls.","zh":"顧客報稱通話中斷後，工程師可能進行這項測試。"},{"en":"The test can show whether the complaint is supported by technical facts.","zh":"測試可以顯示投訴是否有技術事實支持。"},{"en":"This phrase describes a practical investigation step.","zh":"這個片語描述一項實際調查步驟。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"near her home and office","meaning":"在她的住所和辦公室附近","examples":[{"en":"The test should be conducted near her home and office.","zh":"測試應在她的住所和辦公室附近進行。"},{"en":"Near her home and office means close to the places where she lives and works.","zh":"near her home and office 意思是在她居住和工作的地方附近。"},{"en":"Testing near both places helps show whether the problem is local or wider.","zh":"在兩個地點附近測試，有助顯示問題是局部還是較廣泛。"},{"en":"If service fails near her office, work communication may be affected.","zh":"如果她辦公室附近服務失效，工作溝通可能受影響。"},{"en":"This phrase identifies where the technical review should take place.","zh":"這個片語指出技術檢視應在哪裡進行。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"be caused by","meaning":"由……引起","examples":[{"en":"The problem may be caused by temporary maintenance.","zh":"問題可能由臨時維修引起。"},{"en":"Be caused by means happen because of a particular reason.","zh":"be caused by 意思是因某個特定原因而發生。"},{"en":"Slow data may be caused by network congestion or equipment problems.","zh":"數據緩慢可能由網絡擠塞或設備問題引起。"},{"en":"Finding what caused the issue helps the company give a fair answer.","zh":"找出問題原因有助公司給出公平答覆。"},{"en":"This phrase connects a problem with its possible cause.","zh":"這個片語把問題與可能原因連接起來。"}],"source":"2015 Q6.pdf","sourcePage":9},{"front":"temporary maintenance","meaning":"臨時維修","examples":[{"en":"The company should explain whether there is temporary maintenance.","zh":"公司應解釋是否有臨時維修。"},{"en":"Temporary maintenance is short-term repair or technical work on a system.","zh":"temporary maintenance 是對系統進行的短期維修或技術工程。"},{"en":"Mobile service may slow down during temporary maintenance.","zh":"流動服務在臨時維修期間可能變慢。"},{"en":"Customers should be told how long temporary maintenance will last.","zh":"顧客應被告知臨時維修會持續多久。"},{"en":"This phrase gives one possible explanation for weak service.","zh":"這個片語提供服務薄弱的一個可能解釋。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"tell her clearly when","meaning":"清楚告知她何時","examples":[{"en":"We should tell her clearly when the work will be completed.","zh":"我們應清楚告知她工程將於何時完成。"},{"en":"To tell her clearly when means to give her a specific time or date in an understandable way.","zh":"tell her clearly when 意思是以容易理解的方式告訴她具體時間或日期。"},{"en":"Staff should tell customers clearly when maintenance will end.","zh":"職員應清楚告知顧客維修何時結束。"},{"en":"Clear timing helps customers plan work and calls.","zh":"清晰時間有助顧客安排工作和通話。"},{"en":"This phrase shows the need for specific communication, not vague reassurance.","zh":"這個片語顯示需要具體溝通，而不是含糊安慰。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"the work will be completed","meaning":"工程將會完成","examples":[{"en":"She should be told when the maintenance work will be completed.","zh":"應告知她維修工程將於何時完成。"},{"en":"The work will be completed means the repair or maintenance will be finished.","zh":"the work will be completed 意思是維修或工程將會結束。"},{"en":"Customers need to know when the work will be completed so they can plan ahead.","zh":"顧客需要知道工程將於何時完成，以便提前安排。"},{"en":"If no completion time is given, customers may feel uncertain.","zh":"如果沒有提供完成時間，顧客可能感到不確定。"},{"en":"This phrase refers to the expected end of technical work.","zh":"這個片語指技術工程的預計結束時間。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"genuinely weak","meaning":"真正薄弱","examples":[{"en":"If the coverage is genuinely weak, she should be allowed to downgrade.","zh":"如果網絡覆蓋真正薄弱，她應獲准降級。"},{"en":"Genuinely weak means truly poor, not only a temporary or imagined problem.","zh":"genuinely weak 意思是真的差，而不只是暫時或想像中的問題。"},{"en":"A signal is genuinely weak if tests show low coverage in the area.","zh":"如果測試顯示該區網絡覆蓋低，訊號就是真正薄弱。"},{"en":"If service is genuinely weak at home, the customer deserves a practical remedy.","zh":"如果住所服務真正薄弱，顧客應得到實際補救方法。"},{"en":"This phrase shows that decisions should be based on evidence.","zh":"這個片語顯示決定應根據證據。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"be allowed to downgrade","meaning":"獲准降級","examples":[{"en":"Ms Chan should be allowed to downgrade if the coverage is weak.","zh":"如果網絡覆蓋薄弱，陳女士應獲准降級。"},{"en":"Be allowed to downgrade means be permitted to move to a lower or cheaper service plan.","zh":"be allowed to downgrade 意思是獲准轉到較低級或較便宜的服務計劃。"},{"en":"A customer may be allowed to downgrade if the premium plan fails to deliver promised benefits.","zh":"如果高級計劃未能提供承諾好處，顧客可能獲准降級。"},{"en":"Downgrading without penalty can be fair when the company cannot provide strong service.","zh":"當公司不能提供強服務時，無罰款降級可能是公平的。"},{"en":"This phrase describes a possible remedy for poor coverage.","zh":"這個片語描述網絡覆蓋差時的一項可能補救方法。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"early termination charge","meaning":"提前終止合約費","examples":[{"en":"She should not have to pay an early termination charge.","zh":"她不應需要支付提前終止合約費。"},{"en":"An early termination charge is a fee for ending a contract before the agreed period finishes.","zh":"early termination charge 是在合約期完結前終止合約所需支付的費用。"},{"en":"Customers may object to an early termination charge if the service has failed.","zh":"如果服務失效，顧客可能反對提前終止合約費。"},{"en":"Waiving this charge can be fair when the company cannot provide promised coverage.","zh":"當公司不能提供承諾的網絡覆蓋時，豁免此費用可能是公平的。"},{"en":"This phrase refers to a possible penalty in a service contract.","zh":"這個片語指服務合約中的一項可能罰款。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"temporary data pass","meaning":"臨時數據套票","examples":[{"en":"The company may provide a temporary data pass.","zh":"公司可以提供臨時數據套票。"},{"en":"A temporary data pass is a short-term data service given for a limited period.","zh":"temporary data pass 是在有限期間提供的短期數據服務。"},{"en":"A customer may receive a temporary data pass while the network problem is checked.","zh":"顧客在網絡問題被檢查期間，可能收到臨時數據套票。"},{"en":"This pass can help the customer continue working during the investigation.","zh":"這個套票可以幫助顧客在調查期間繼續工作。"},{"en":"This phrase describes a temporary support measure.","zh":"這個片語描述一項臨時支援措施。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"portable Wi-Fi device","meaning":"便攜式Wi-Fi裝置","examples":[{"en":"A portable Wi-Fi device could help her continue working.","zh":"便攜式 Wi-Fi 裝置可以幫助她繼續工作。"},{"en":"A portable Wi-Fi device is a small device that provides wireless internet and can be carried around.","zh":"portable Wi-Fi device 是可隨身攜帶並提供無線上網的小型裝置。"},{"en":"A company may lend a portable Wi-Fi device during a service outage.","zh":"公司可能在服務中斷期間借出便攜式 Wi-Fi 裝置。"},{"en":"This device can reduce inconvenience if mobile data is unreliable.","zh":"如果流動數據不穩定，這個裝置可以減少不便。"},{"en":"This phrase names a practical tool for temporary internet support.","zh":"這個片語指出一項提供臨時網絡支援的實用工具。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"continue working","meaning":"繼續工作","examples":[{"en":"Ms Chan needs to continue working while the issue is examined.","zh":"在問題檢查期間，陳女士需要繼續工作。"},{"en":"To continue working means to keep doing one’s job despite a problem.","zh":"continue working 意思是在問題存在時仍繼續做自己的工作。"},{"en":"Stable internet helps people continue working during video meetings.","zh":"穩定網絡幫助人們在視像會議期間繼續工作。"},{"en":"A temporary device may help a customer continue working from home.","zh":"臨時裝置可能幫助顧客在家繼續工作。"},{"en":"This phrase shows why quick support matters in daily life.","zh":"這個片語顯示快速支援為何對日常生活重要。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"while the issue is being examined","meaning":"在問題檢查期間","examples":[{"en":"A temporary device could be offered while the issue is being examined.","zh":"在問題檢查期間，可以提供臨時裝置。"},{"en":"While the issue is being examined means during the time staff are checking the problem.","zh":"while the issue is being examined 意思是在職員查核問題期間。"},{"en":"Customers may need temporary help while the issue is being examined.","zh":"在問題檢查期間，顧客可能需要臨時幫助。"},{"en":"This phrase shows that support can be offered before the final answer is ready.","zh":"這個片語顯示在最終答案準備好前也可以提供支援。"},{"en":"It helps balance investigation with immediate customer care.","zh":"它幫助平衡調查和即時客戶關懷。"}],"source":"2015 Q6.pdf","sourcePage":10},{"front":"only by checking…can…","meaning":"只有透過檢查……才可以……","examples":[{"en":"Only by checking the technical facts can we give a fair answer.","zh":"只有透過檢查技術事實，我們才可以給出公平答覆。"},{"en":"This structure means a result is possible only if a certain action is done first.","zh":"這個句式意思是只有先完成某行動，某結果才可能出現。"},{"en":"Only by checking the bill can staff know whether the charges were correct.","zh":"只有透過檢查帳單，職員才知道收費是否正確。"},{"en":"Only by listening to the customer can the company understand the full problem.","zh":"只有透過聆聽顧客，公司才可以理解完整問題。"},{"en":"This phrase strongly emphasises the necessary step.","zh":"這個片語強調必要步驟。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"technical facts","meaning":"技術事實","examples":[{"en":"The company needs to check the technical facts.","zh":"公司需要檢查技術事實。"},{"en":"Technical facts are objective information about systems, equipment, coverage, and performance.","zh":"technical facts 是關於系統、設備、網絡覆蓋和表現的客觀資料。"},{"en":"Speed test results and maintenance records are technical facts.","zh":"速度測試結果和維修紀錄都是技術事實。"},{"en":"Checking technical facts prevents the company from guessing.","zh":"檢查技術事實可防止公司靠猜測回應。"},{"en":"This phrase supports an evidence-based response.","zh":"這個片語支持以證據為本的回應。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"accurate, fair and defensible","meaning":"準確、公平且站得住腳","examples":[{"en":"The answer should be accurate, fair and defensible.","zh":"答覆應準確、公平且站得住腳。"},{"en":"Accurate, fair and defensible means correct, just, and able to be supported with reasons.","zh":"accurate, fair and defensible 意思是正確、公正，並能以理由支持。"},{"en":"A complaint decision is defensible when records and test results support it.","zh":"當紀錄和測試結果支持投訴決定時，該決定便站得住腳。"},{"en":"Customers are more likely to accept an answer that is accurate and fair.","zh":"顧客較可能接受準確且公平的答覆。"},{"en":"This phrase describes the quality of a good formal response.","zh":"這個片語描述良好正式回應的質素。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"review the sales and follow-up procedure","meaning":"檢討銷售及跟進程序","examples":[{"en":"The company should review the sales and follow-up procedure.","zh":"公司應檢討銷售及跟進程序。"},{"en":"To review the sales and follow-up procedure means to examine how staff sell plans and handle later enquiries.","zh":"review the sales and follow-up procedure 意思是檢查職員如何銷售計劃和處理後續查詢。"},{"en":"A company may review procedures after repeated complaints about unclear fees.","zh":"當多次出現關於收費不清的投訴時，公司可能檢討程序。"},{"en":"Reviewing procedures can prevent the same mistake from happening again.","zh":"檢討程序可以防止同一錯誤再次發生。"},{"en":"This phrase points to long-term improvement, not only compensation.","zh":"這個片語指出長遠改善，而不只是賠償。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"branch staff","meaning":"分店職員","examples":[{"en":"Branch staff should use a short disclosure checklist.","zh":"分店職員應使用一份簡短披露清單。"},{"en":"Branch staff are employees who work at a company’s physical shop or branch.","zh":"branch staff 是在公司實體店或分店工作的員工。"},{"en":"Branch staff often explain plans and contracts to customers face to face.","zh":"分店職員通常面對面向顧客解釋計劃和合約。"},{"en":"Clear training helps branch staff avoid giving incomplete information.","zh":"清晰培訓幫助分店職員避免提供不完整資訊。"},{"en":"This phrase identifies the staff involved at the sales stage.","zh":"這個片語指出銷售階段涉及的職員。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"disclosure checklist","meaning":"披露清單","examples":[{"en":"Staff should use a disclosure checklist before signing a contract.","zh":"職員應在簽署合約前使用披露清單。"},{"en":"A disclosure checklist is a list of key points staff must explain to customers.","zh":"disclosure checklist 是職員必須向顧客解釋的重點清單。"},{"en":"The checklist may include fees, coverage limits, and contract length.","zh":"清單可能包括收費、網絡覆蓋限制和合約期。"},{"en":"Using a checklist helps ensure important terms are not missed.","zh":"使用清單有助確保重要條款不被遺漏。"},{"en":"This phrase describes a tool for clearer sales communication.","zh":"這個片語描述一項令銷售溝通更清晰的工具。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"cover coverage limitations","meaning":"涵蓋網絡覆蓋限制","examples":[{"en":"The checklist should cover coverage limitations.","zh":"清單應涵蓋網絡覆蓋限制。"},{"en":"To cover coverage limitations means to include and explain areas where network service may be weaker.","zh":"cover coverage limitations 意思是包括並解釋網絡服務可能較弱的地方。"},{"en":"Sales staff should cover coverage limitations before promising better service.","zh":"銷售職員在承諾更好服務前，應涵蓋網絡覆蓋限制。"},{"en":"If limitations are covered clearly, customers can make informed choices.","zh":"如果限制被清楚涵蓋，顧客便能作出知情選擇。"},{"en":"This phrase shows what information should be included in disclosure.","zh":"這個片語顯示披露內容應包括甚麼資訊。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"coverage limitations","meaning":"網絡覆蓋限制","examples":[{"en":"Customers should be told about coverage limitations.","zh":"顧客應被告知網絡覆蓋限制。"},{"en":"Coverage limitations are areas or situations where network signal may not be strong.","zh":"coverage limitations 是指網絡訊號可能不強的地區或情況。"},{"en":"Indoor flats, basements, or crowded districts may have coverage limitations.","zh":"室內單位、地庫或人多地區可能有網絡覆蓋限制。"},{"en":"If customers know the limitations, they can judge whether the plan suits them.","zh":"如果顧客知道限制，便能判斷計劃是否適合自己。"},{"en":"This phrase is important because “5G” does not guarantee perfect service everywhere.","zh":"這個片語很重要，因為「5G」不代表每個地方都有完美服務。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"one-off fees","meaning":"一次性費用","examples":[{"en":"The checklist should explain any one-off fees.","zh":"清單應解釋任何一次性費用。"},{"en":"One-off fees are charges paid once, not every month.","zh":"one-off fees 是只需支付一次、不是每月支付的費用。"},{"en":"A SIM replacement fee may be a one-off fee.","zh":"SIM 卡更換費可能是一次性費用。"},{"en":"Customers should know one-off fees before agreeing to a contract.","zh":"顧客同意合約前應知道一次性費用。"},{"en":"Clear explanation of one-off fees helps prevent billing disputes.","zh":"清楚解釋一次性費用有助防止帳單爭議。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"cooling-off arrangements","meaning":"冷靜期安排","examples":[{"en":"The checklist should include cooling-off arrangements.","zh":"清單應包括冷靜期安排。"},{"en":"Cooling-off arrangements are rules that allow customers to cancel or change a contract within a short period.","zh":"cooling-off arrangements 是容許顧客在短時間內取消或更改合約的規則。"},{"en":"Customers should know whether a plan has a cooling-off period before signing.","zh":"顧客簽署前應知道計劃是否有冷靜期。"},{"en":"Clear cooling-off arrangements can reduce disputes after a rushed sale.","zh":"清晰冷靜期安排可以減少匆忙銷售後的爭議。"},{"en":"This phrase concerns customer protection after agreement.","zh":"這個片語關乎同意合約後的顧客保障。"}],"source":"2015 Q6.pdf","sourcePage":11},{"front":"sign a new contract","meaning":"簽署新合約","examples":[{"en":"Customers should understand the terms before they sign a new contract.","zh":"顧客在簽署新合約前應理解條款。"},{"en":"To sign a new contract means to formally agree to a new set of written terms.","zh":"sign a new contract 意思是正式同意一套新的書面條款。"},{"en":"Customers should ask questions before signing a new contract for a mobile plan.","zh":"顧客在簽署手機計劃新合約前應提出問題。"},{"en":"If important fees are hidden, the customer may dispute the new contract later.","zh":"如果重要收費被隱藏，顧客之後可能爭議新合約。"},{"en":"This phrase marks the point where clear explanation is especially important.","zh":"這個片語標誌清楚解釋尤其重要的時刻。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"confirmation email","meaning":"確認電郵","examples":[{"en":"A confirmation email should be sent automatically.","zh":"確認電郵應自動發送。"},{"en":"A confirmation email is a message that records and confirms what has been agreed.","zh":"confirmation email 是記錄並確認已同意內容的訊息。"},{"en":"After a plan upgrade, a confirmation email can list the price and key terms.","zh":"計劃升級後，確認電郵可以列出價錢和主要條款。"},{"en":"Confirmation emails help customers check whether details are correct.","zh":"確認電郵幫助顧客檢查資料是否正確。"},{"en":"This phrase describes a useful written record after a sale.","zh":"這個片語描述銷售後有用的書面紀錄。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"be sent automatically","meaning":"自動發送","examples":[{"en":"A confirmation email should be sent automatically after the sale.","zh":"銷售後，確認電郵應自動發送。"},{"en":"Be sent automatically means be delivered by the system without staff needing to send it manually.","zh":"be sent automatically 意思是由系統發出，而不需職員手動發送。"},{"en":"A receipt can be sent automatically after online payment.","zh":"網上付款後，收據可以自動發送。"},{"en":"Automatic emails reduce the chance that staff forget to follow up.","zh":"自動電郵減少職員忘記跟進的機會。"},{"en":"This phrase shows how technology can improve consistency.","zh":"這個片語顯示科技如何改善一致性。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"set out the key terms","meaning":"列明主要條款","examples":[{"en":"The confirmation email should set out the key terms.","zh":"確認電郵應列明主要條款。"},{"en":"To set out the key terms means to state the most important contract details clearly.","zh":"set out the key terms 意思是清楚列出最重要的合約細節。"},{"en":"The email should set out the monthly fee, contract period, and extra charges.","zh":"電郵應列明月費、合約期和額外收費。"},{"en":"If key terms are set out clearly, customers can check them later.","zh":"如果主要條款被清楚列明，顧客之後可以查閱。"},{"en":"This phrase is useful in formal writing about contracts.","zh":"這個片語適合用於關於合約的正式寫作。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"key terms","meaning":"主要條款","examples":[{"en":"Customers should receive the key terms in writing.","zh":"顧客應以書面形式收到主要條款。"},{"en":"Key terms are the most important conditions in an agreement.","zh":"key terms 是協議中最重要的條件。"},{"en":"Key terms may include price, service limits, fees, and cancellation rules.","zh":"主要條款可能包括價錢、服務限制、收費和取消規則。"},{"en":"Customers need key terms in writing so they do not rely only on memory.","zh":"顧客需要書面主要條款，才不會只依賴記憶。"},{"en":"This phrase focuses on the information customers must understand.","zh":"這個片語著重顧客必須理解的資訊。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"in plain English and Chinese","meaning":"以淺白中英文","examples":[{"en":"The key terms should be written in plain English and Chinese.","zh":"主要條款應以淺白中英文書寫。"},{"en":"In plain English and Chinese means in simple, clear language in both languages.","zh":"in plain English and Chinese 意思是以簡單清楚的中英文表達。"},{"en":"Contracts should use plain language so ordinary customers can understand them.","zh":"合約應使用淺白語言，讓普通顧客理解。"},{"en":"Plain bilingual terms reduce misunderstanding and complaints.","zh":"淺白雙語條款可減少誤解和投訴。"},{"en":"This phrase stresses clarity and accessibility.","zh":"這個片語強調清晰和易理解。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, hotline staff should record all call-back promises.","zh":"此外，熱線職員應記錄所有回覆電話承諾。"},{"en":"Moreover means in addition, and introduces another related point.","zh":"moreover 意思是「此外」，用來引出另一個相關重點。"},{"en":"The company should waive the charges; moreover, it should review the sales process.","zh":"公司應豁免收費；此外，也應檢討銷售程序。"},{"en":"This word helps add another recommendation smoothly.","zh":"這個字幫助順暢加入另一項建議。"},{"en":"It is useful in formal writing when building a series of points.","zh":"在正式寫作中建立一系列重點時，它很有用。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"hotline staff","meaning":"熱線職員","examples":[{"en":"Hotline staff should record all promises of call-backs.","zh":"熱線職員應記錄所有回覆電話承諾。"},{"en":"Hotline staff are customer service employees who answer phone enquiries.","zh":"hotline staff 是接聽電話查詢的客戶服務員工。"},{"en":"Hotline staff often handle complaints, billing questions, and technical problems.","zh":"熱線職員通常處理投訴、帳單問題和技術問題。"},{"en":"Clear records help hotline staff give consistent answers.","zh":"清晰紀錄幫助熱線職員給出一致答案。"},{"en":"This phrase identifies the team responsible for phone-based follow-up.","zh":"這個片語指出負責電話跟進的團隊。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"record all promises of call-backs","meaning":"記錄所有回覆電話承諾","examples":[{"en":"Staff should record all promises of call-backs in the system.","zh":"職員應在系統中記錄所有回覆電話承諾。"},{"en":"To record all promises of call-backs means to enter every promised return call into a system.","zh":"record all promises of call-backs 意思是把每個承諾回覆的電話輸入系統。"},{"en":"Recording promises helps supervisors check whether staff follow up.","zh":"記錄承諾有助主管檢查職員是否跟進。"},{"en":"If promises are not recorded, customers may be forgotten.","zh":"如果承諾沒有記錄，顧客可能被忘記。"},{"en":"This phrase describes a practical way to prevent missed follow-up.","zh":"這個片語描述一項防止漏掉跟進的實際方法。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"complaint system","meaning":"投訴系統","examples":[{"en":"The promises should be recorded in the complaint system.","zh":"這些承諾應記錄在投訴系統中。"},{"en":"A complaint system is a database or process for tracking customer complaints.","zh":"complaint system 是追蹤顧客投訴的資料庫或程序。"},{"en":"A good complaint system records dates, staff names, promises, and outcomes.","zh":"好的投訴系統會記錄日期、職員姓名、承諾和結果。"},{"en":"If the system is updated properly, customers do not need to repeat everything.","zh":"如果系統妥善更新，顧客便不用重複所有內容。"},{"en":"This phrase describes the tool used to manage complaint cases.","zh":"這個片語描述管理投訴個案的工具。"}],"source":"2015 Q6.pdf","sourcePage":12},{"front":"overdue cases","meaning":"逾期個案","examples":[{"en":"Overdue cases should be flagged to supervisors.","zh":"逾期個案應被標示給主管跟進。"},{"en":"Overdue cases are cases that have not been handled by the expected time.","zh":"overdue cases 是未在預期時間內處理的個案。"},{"en":"A promised call-back becomes overdue if nobody calls after the deadline.","zh":"如果限期過後仍沒有人致電，承諾的回覆電話便變成逾期個案。"},{"en":"Overdue cases need attention because delay can increase frustration.","zh":"逾期個案需要關注，因為延誤會增加不滿。"},{"en":"This phrase helps companies monitor unfinished work.","zh":"這個片語幫助公司監察未完成工作。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"be flagged to supervisors","meaning":"被標示給主管跟進","examples":[{"en":"Overdue cases should be flagged to supervisors.","zh":"逾期個案應被標示給主管跟進。"},{"en":"Be flagged to supervisors means be marked so managers can notice and follow up.","zh":"be flagged to supervisors 意思是被標記出來，讓主管注意和跟進。"},{"en":"A complaint may be flagged to a supervisor if it remains unresolved for several days.","zh":"如果投訴多日未解決，可能被標示給主管跟進。"},{"en":"Flagging cases helps prevent important problems from being missed.","zh":"標示個案有助防止重要問題被遺漏。"},{"en":"This phrase describes an escalation step inside a company.","zh":"這個片語描述公司內部的升級步驟。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"that way","meaning":"這樣一來","examples":[{"en":"That way, customers will no longer be passed from one colleague to another.","zh":"這樣一來，顧客將不再被不同同事推來推去。"},{"en":"That way means by doing this, or as a result of this method.","zh":"that way 意思是透過這樣做，或作為這種方法的結果。"},{"en":"Record all call-back promises; that way, supervisors can check delays.","zh":"記錄所有回覆電話承諾；這樣一來，主管可以檢查延誤。"},{"en":"Assign one case officer; that way, the customer has one contact point.","zh":"指派一名個案主任；這樣一來，顧客便有一個聯絡點。"},{"en":"This phrase connects a recommendation with its expected benefit.","zh":"這個片語把建議與預期好處連接起來。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"be passed from one colleague to another","meaning":"被不同同事推來推去","examples":[{"en":"Customers should not be passed from one colleague to another.","zh":"顧客不應被不同同事推來推去。"},{"en":"Be passed from one colleague to another means be transferred repeatedly without anyone taking responsibility.","zh":"be passed from one colleague to another 意思是被反覆轉交，卻沒有人負責。"},{"en":"A customer feels frustrated when every staff member sends her to someone else.","zh":"當每位職員都把顧客轉給別人，顧客會感到挫敗。"},{"en":"This problem can be solved by appointing one case officer.","zh":"指派一名個案主任可以解決這個問題。"},{"en":"This phrase criticises poor coordination inside customer service.","zh":"這個片語批評客戶服務內部協調不善。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"without a clear answer","meaning":"沒有清晰答覆","examples":[{"en":"Customers should not be passed around without a clear answer.","zh":"顧客不應在沒有清晰答覆的情況下被推來推去。"},{"en":"Without a clear answer means without receiving a definite and understandable response.","zh":"without a clear answer 意思是沒有收到明確而容易理解的回應。"},{"en":"A customer may call three times and still leave without a clear answer.","zh":"顧客可能致電三次，仍然沒有清晰答覆。"},{"en":"Not giving a clear answer makes the company look disorganised.","zh":"沒有清晰答覆會令公司看起來缺乏組織。"},{"en":"This phrase shows what customers should not experience.","zh":"這個片語顯示顧客不應經歷甚麼。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"in conclusion","meaning":"總括而言","examples":[{"en":"In conclusion, Ms Chan’s complaint should be handled promptly.","zh":"總括而言，陳女士的投訴應迅速處理。"},{"en":"In conclusion is used to introduce the final summary or judgement.","zh":"in conclusion 用來引出最後總結或判斷。"},{"en":"In conclusion, the company should contact the customer and review its procedures.","zh":"總括而言，公司應聯絡顧客並檢討程序。"},{"en":"This phrase helps readers know the email is reaching its final point.","zh":"這個片語幫助讀者知道電郵正進入最後重點。"},{"en":"It is common in formal reports and recommendation emails.","zh":"它常見於正式報告和建議電郵。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"be dealt with promptly","meaning":"迅速處理","examples":[{"en":"The complaint should be dealt with promptly.","zh":"這宗投訴應迅速處理。"},{"en":"Be dealt with promptly means be handled quickly and without unnecessary delay.","zh":"be dealt with promptly 意思是快速處理，不作不必要延誤。"},{"en":"A billing complaint should be dealt with promptly before trust is lost.","zh":"帳單投訴應在失去信任前迅速處理。"},{"en":"Prompt handling shows customers that the company respects their time.","zh":"迅速處理顯示公司尊重顧客時間。"},{"en":"This phrase stresses speed and responsibility.","zh":"這個片語強調速度和責任感。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"politely and transparently","meaning":"有禮且透明地","examples":[{"en":"The complaint should be handled politely and transparently.","zh":"這宗投訴應有禮且透明地處理。"},{"en":"Politely and transparently means with respect and clear openness about the process.","zh":"politely and transparently 意思是以尊重和清楚公開的方式處理。"},{"en":"Staff should explain delays politely and transparently to reduce frustration.","zh":"職員應有禮且透明地解釋延誤，以減少不滿。"},{"en":"A transparent response tells the customer what is being checked and why.","zh":"透明回應會告訴顧客正在檢查甚麼和原因。"},{"en":"This phrase describes the tone and method of good complaint handling.","zh":"這個片語描述良好投訴處理的語氣和方法。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"immediate objective","meaning":"即時目標","examples":[{"en":"The immediate objective is to settle her case.","zh":"即時目標是解決她的個案。"},{"en":"The immediate objective is the first and most urgent goal.","zh":"immediate objective 是第一個且最迫切的目標。"},{"en":"In a complaint, the immediate objective may be to contact the customer and stop further inconvenience.","zh":"在投訴中，即時目標可能是聯絡顧客並停止進一步不便。"},{"en":"Immediate objectives help staff know what must happen first.","zh":"即時目標幫助職員知道甚麼必須先完成。"},{"en":"This phrase separates short-term action from wider improvement.","zh":"這個片語把短期行動與更廣泛改善分開。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"settle her case","meaning":"解決她的個案","examples":[{"en":"The company should settle her case as soon as possible.","zh":"公司應盡快解決她的個案。"},{"en":"To settle her case means to resolve the complaint and reach a clear outcome.","zh":"settle her case 意思是解決投訴並達成清晰結果。"},{"en":"Settling her case may involve waiving charges and giving a written reply.","zh":"解決她的個案可能包括豁免收費和提供書面回覆。"},{"en":"If the case is not settled, the customer may continue complaining.","zh":"如果個案沒有解決，顧客可能繼續投訴。"},{"en":"This phrase focuses on bringing the individual complaint to a proper close.","zh":"這個片語著重妥善結束個別投訴。"}],"source":"2015 Q6.pdf","sourcePage":13},{"front":"wider objective","meaning":"更廣泛的目標","examples":[{"en":"The wider objective is to prevent similar complaints.","zh":"更廣泛的目標是防止類似投訴。"},{"en":"The wider objective is the broader goal beyond solving one case.","zh":"wider objective 是解決單一個案以外的更大目標。"},{"en":"After handling Ms Chan’s case, the wider objective is to improve sales procedures.","zh":"處理陳女士的個案後，更廣泛的目標是改善銷售程序。"},{"en":"A wider objective helps a company learn from a complaint.","zh":"更廣泛的目標幫助公司從投訴中學習。"},{"en":"This phrase shows that one complaint can lead to system improvement.","zh":"這個片語顯示一宗投訴可以帶來制度改善。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"make sure that","meaning":"確保","examples":[{"en":"The company should make sure that similar complaints do not arise again.","zh":"公司應確保類似投訴不會再次出現。"},{"en":"Make sure that means take action to ensure something happens or does not happen.","zh":"make sure that 意思是採取行動確保某事發生或不發生。"},{"en":"Staff should make sure that customers understand all fees before signing.","zh":"職員應確保顧客簽署前理解所有收費。"},{"en":"The company must make sure that call-back promises are recorded.","zh":"公司必須確保回覆電話承諾被記錄。"},{"en":"This phrase expresses responsibility for prevention.","zh":"這個片語表達預防責任。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"similar complaints","meaning":"類似投訴","examples":[{"en":"The company should prevent similar complaints from happening again.","zh":"公司應防止類似投訴再次發生。"},{"en":"Similar complaints are complaints about the same kind of problem.","zh":"similar complaints 是關於同類問題的投訴。"},{"en":"Other customers may make similar complaints if sales staff keep giving unclear explanations.","zh":"如果銷售職員繼續解釋不清，其他顧客可能提出類似投訴。"},{"en":"Preventing similar complaints requires better procedures, not only one apology.","zh":"防止類似投訴需要更好程序，而不只是一次道歉。"},{"en":"This phrase points to repeated risks inside the company.","zh":"這個片語指出公司內部的重複風險。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"arise again","meaning":"再次出現","examples":[{"en":"Similar complaints should not arise again.","zh":"類似投訴不應再次出現。"},{"en":"Arise again means happen or appear again after a previous case.","zh":"arise again 意思是在之前個案後再次發生或出現。"},{"en":"If procedures do not change, the same billing issue may arise again.","zh":"如果程序不改，同一帳單問題可能再次出現。"},{"en":"Training staff can help prevent confusion from arising again.","zh":"培訓職員可以幫助防止混亂再次出現。"},{"en":"This phrase stresses prevention after a problem has already happened.","zh":"這個片語強調問題已發生後的預防。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"I would be grateful if you could advise","meaning":"如你能指示……，我將不勝感激","examples":[{"en":"I would be grateful if you could advise whether I should draft a reply.","zh":"如你能指示我是否應草擬回覆，我將不勝感激。"},{"en":"This phrase is a polite formal request asking someone to give guidance.","zh":"這個片語是有禮的正式請求，用來請某人提供指引。"},{"en":"A junior staff member may write this when asking a manager for instructions.","zh":"初級職員向經理請示時，可能會這樣寫。"},{"en":"It sounds respectful because it leaves the decision to the recipient.","zh":"它聽起來尊重，因為把決定留給收件人。"},{"en":"This phrase is useful at the end of a professional email.","zh":"這個片語適合用於專業電郵結尾。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"draft a reply","meaning":"草擬回覆","examples":[{"en":"Chris asks whether he should draft a reply to Ms Chan.","zh":"Chris 詢問是否應草擬給陳女士的回覆。"},{"en":"To draft a reply means to prepare a first version of a response.","zh":"draft a reply 意思是準備回應的初稿。"},{"en":"An intern may draft a reply before a manager checks it.","zh":"實習生可能先草擬回覆，再由經理檢查。"},{"en":"Drafting a reply helps the company respond more quickly once the approach is approved.","zh":"草擬回覆有助在處理方向獲批准後更快回應。"},{"en":"This phrase describes a practical writing task after a complaint.","zh":"這個片語描述投訴後的實際寫作任務。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"based on the above recommendations","meaning":"根據上述建議","examples":[{"en":"The reply could be drafted based on the above recommendations.","zh":"回覆可以根據上述建議草擬。"},{"en":"Based on the above recommendations means using the suggestions already mentioned as the foundation.","zh":"based on the above recommendations 意思是以上文已提到的建議作為基礎。"},{"en":"A manager may approve a letter based on the above recommendations.","zh":"經理可能批准一封根據上述建議撰寫的信件。"},{"en":"This phrase helps connect the final action with the earlier analysis.","zh":"這個片語幫助把最後行動與前文分析連接起來。"},{"en":"It shows that the reply should follow the proposed plan.","zh":"它顯示回覆應跟隨建議方案。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"A formal email to a named recipient can end with “Yours sincerely”.","zh":"寫給已知姓名收件人的正式電郵可以以 “Yours sincerely” 結尾。"},{"en":"“Yours sincerely” is a polite formal closing used when the recipient’s name is known.","zh":"“Yours sincerely” 是知道收件人姓名時使用的禮貌正式結尾。"},{"en":"A staff member may end an email to Ms Lee with “Yours sincerely”.","zh":"職員可能以 “Yours sincerely” 結束寫給李女士的電郵。"},{"en":"This closing keeps the tone respectful and professional.","zh":"這個結尾保持語氣尊重和專業。"},{"en":"It is more suitable for formal business emails than “Cheers”.","zh":"它比 “Cheers” 更適合正式商業電郵。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"Summer Intern","meaning":"暑期實習生","examples":[{"en":"Chris Wong is a summer intern in the Customer Services Department.","zh":"Chris Wong 是客戶服務部的暑期實習生。"},{"en":"A summer intern is a temporary student worker who gains experience during the summer.","zh":"summer intern 是在暑假期間獲取工作經驗的臨時學生員工。"},{"en":"A summer intern may help write reports, answer enquiries, or prepare summaries.","zh":"暑期實習生可能協助撰寫報告、回答查詢或準備摘要。"},{"en":"Interns usually work under supervision because they are still learning.","zh":"實習生通常在監督下工作，因為他們仍在學習。"},{"en":"This title explains Chris’s role in the company.","zh":"這個職銜解釋 Chris 在公司中的角色。"}],"source":"2015 Q6.pdf","sourcePage":14},{"front":"Customer Services Department","meaning":"客戶服務部","examples":[{"en":"Chris works in the Customer Services Department.","zh":"Chris 在客戶服務部工作。"},{"en":"The Customer Services Department is the part of a company that helps customers with questions, complaints, and service problems.","zh":"客戶服務部是公司中協助顧客處理查詢、投訴和服務問題的部門。"},{"en":"This department may handle hotline calls, billing disputes, and apology letters.","zh":"這個部門可能處理熱線電話、帳單爭議和道歉信。"},{"en":"A strong Customer Services Department can protect customer trust.","zh":"強大的客戶服務部可以保護顧客信任。"},{"en":"This phrase identifies the team responsible for handling Ms Chan’s complaint.","zh":"這個片語指出負責處理陳女士投訴的團隊。"}],"source":"2015 Q6.pdf","sourcePage":14}],"dse/writing/part-b/2015/Q7":[{"front":"report on","meaning":"關於……的報告","examples":[{"en":"This is a report on the decline in cinema attendance in Hong Kong.","zh":"這是一份關於香港戲院入場人次下降的報告。"},{"en":"A report on something is a formal piece of writing that presents information, findings and suggestions about that topic.","zh":"關於某事的報告是正式整理該主題資料、發現和建議的文章。"},{"en":"Students wrote a report on recycling habits in their school.","zh":"學生寫了一份關於學校回收習慣的報告。"},{"en":"A report on cinema attendance should explain both the problem and possible solutions.","zh":"關於戲院入場人次的報告應同時解釋問題和可能的解決方法。"},{"en":"Reports usually organise information clearly so readers can understand the issue quickly.","zh":"報告通常會清楚整理資料，讓讀者迅速理解問題。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"decline in","meaning":"……下降","examples":[{"en":"The report explains the decline in cinema attendance.","zh":"報告解釋戲院入場人次下降的情況。"},{"en":"A decline in something means a reduction in its amount, level or number over time.","zh":"「a decline in」表示某事物的數量、水平或程度隨時間減少。"},{"en":"The company noticed a decline in sales after prices increased.","zh":"價格上升後，公司發現銷售量下降。"},{"en":"A decline in cinema attendance means fewer people are going to cinemas than before.","zh":"戲院入場人次下降表示現在入戲院的人比以前少。"},{"en":"Understanding the reasons for a decline helps organisations decide how to respond.","zh":"了解下降的原因，有助機構決定如何回應。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"cinema attendance","meaning":"戲院入場人次","examples":[{"en":"Cinema attendance in Hong Kong has declined.","zh":"香港的戲院入場人次有所下降。"},{"en":"Cinema attendance means the number of people who go to cinemas to watch films.","zh":"戲院入場人次是指前往戲院看電影的人數。"},{"en":"Cinema attendance often increases when a highly anticipated film is released.","zh":"萬眾期待的電影上映時，戲院入場人次通常會增加。"},{"en":"High ticket prices may reduce cinema attendance among students and families.","zh":"高昂票價可能令學生和家庭減少入戲院。"},{"en":"Cinemas monitor attendance because it affects ticket income and future planning.","zh":"戲院會留意入場人次，因為這會影響票房收入和未來規劃。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"The English Panel","meaning":"英文科組","examples":[{"en":"The report has been prepared for the English Panel.","zh":"這份報告是為英文科組而準備的。"},{"en":"The English Panel is the group of teachers responsible for planning and developing English teaching in a school.","zh":"英文科組是負責規劃和發展學校英文教學的一組老師。"},{"en":"The English Panel may discuss examinations, teaching materials and language activities.","zh":"英文科組可能討論考試、教材和語文活動。"},{"en":"Students may prepare reports for the English Panel as part of an English project.","zh":"學生可能要為英文科組撰寫報告，作為英文專題的一部分。"},{"en":"A school subject panel helps coordinate teaching within that subject.","zh":"學校科組有助協調該科目的教學工作。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"subject","meaning":"主題","examples":[{"en":"The subject of the report is cinemas in Hong Kong.","zh":"這份報告的主題是香港戲院。"},{"en":"The subject is the main topic or area that a piece of writing, discussion or study is about.","zh":"主題是文章、討論或研究所集中處理的主要內容。"},{"en":"The subject of today’s meeting is school transport.","zh":"今天會議的主題是學校交通。"},{"en":"A clear subject helps readers know what a report will discuss.","zh":"清楚的主題讓讀者知道報告會討論甚麼。"},{"en":"Formal reports usually state their subject near the beginning.","zh":"正式報告通常會在開首附近說明主題。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"introduction","meaning":"引言","examples":[{"en":"The introduction explains the purpose of the report.","zh":"引言解釋這份報告的目的。"},{"en":"An introduction is the opening section that tells readers what a piece of writing will discuss.","zh":"引言是文章開首部分，用來告訴讀者內容會討論甚麼。"},{"en":"The introduction of a report may explain its purpose, background and scope.","zh":"報告的引言可能交代目的、背景和範圍。"},{"en":"A clear introduction prepares readers for the information that follows.","zh":"清楚的引言可以幫助讀者準備理解之後的內容。"},{"en":"The introduction should usually be brief but informative.","zh":"引言通常應簡短但資料充足。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"be prepared for","meaning":"為……而準備","examples":[{"en":"This report has been prepared for the module project.","zh":"這份報告是為單元專題而準備的。"},{"en":"To be prepared for something means to be created or completed for a particular purpose, event or audience.","zh":"「be prepared for」表示為特定目的、活動或讀者而製作或完成。"},{"en":"The presentation was prepared for the school open day.","zh":"那份簡報是為學校開放日而準備的。"},{"en":"A report prepared for a project should follow the requirements of that project.","zh":"為專題準備的報告應符合該專題的要求。"},{"en":"Knowing who something is prepared for helps determine its tone and content.","zh":"知道內容是為誰而準備，有助決定語氣和內容。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"Learning English through Popular Culture","meaning":"透過流行文化學習英語","examples":[{"en":"The project is part of the Learning English through Popular Culture module.","zh":"這個專題屬於「透過流行文化學習英語」單元的一部分。"},{"en":"Learning English through Popular Culture is a learning approach that uses films, music, media and other popular cultural materials to develop English skills.","zh":"「透過流行文化學習英語」是利用電影、音樂、媒體和其他流行文化材料發展英語能力的學習方式。"},{"en":"Students may study advertisements or films in Learning English through Popular Culture.","zh":"學生可能在這個單元中研究廣告或電影。"},{"en":"Popular culture can provide familiar topics for practising reading, writing and discussion.","zh":"流行文化可以提供熟悉題材，讓學生練習閱讀、寫作和討論。"},{"en":"The module connects language learning with media students encounter in daily life.","zh":"這個單元把語言學習與學生日常接觸的媒體連結起來。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"module project","meaning":"單元專題報告","examples":[{"en":"The report was written for a module project.","zh":"這份報告是為一項單元專題而寫的。"},{"en":"A module project is a piece of assessed or organised work connected with one part of a course.","zh":"單元專題是與課程其中一個單元相關的有組織或評核工作。"},{"en":"Students completed interviews for their environmental module project.","zh":"學生為環境單元專題進行了訪問。"},{"en":"A module project often requires students to apply skills learned during the unit.","zh":"單元專題通常要求學生運用該單元學過的技能。"},{"en":"Reports, presentations and surveys can all form part of a module project.","zh":"報告、簡報和調查都可以成為單元專題的一部分。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"choose to watch films","meaning":"選擇看電影","examples":[{"en":"Fewer people now choose to watch films in cinemas.","zh":"現在較少人選擇在戲院看電影。"},{"en":"To choose to watch films means to decide that watching films is the activity you want to do.","zh":"選擇看電影表示決定把觀看電影作為自己想做的活動。"},{"en":"Many families choose to watch films at home because it is cheaper.","zh":"很多家庭選擇在家看電影，因為成本較低。"},{"en":"People may choose to watch films in cinemas when the experience feels special.","zh":"當戲院體驗感覺特別，人們可能選擇到戲院看電影。"},{"en":"Entertainment choices depend on convenience, cost and personal preference.","zh":"娛樂選擇會受到方便程度、成本和個人喜好影響。"}],"source":"2015 Q7.pdf","sourcePage":1},{"front":"in cinemas","meaning":"在戲院","examples":[{"en":"Fewer people are watching films in cinemas.","zh":"現在較少人在戲院看電影。"},{"en":"“In cinemas” means inside movie theatres rather than at home or on another device.","zh":"「in cinemas」表示在電影院內，而不是在家或其他裝置上觀看。"},{"en":"Some films are more impressive in cinemas because of the large screen and sound system.","zh":"有些電影在戲院看會更震撼，因為有大銀幕和音響系統。"},{"en":"Audiences used to watch new releases mainly in cinemas.","zh":"過去觀眾主要在戲院觀看新上映電影。"},{"en":"Watching films in cinemas requires people to travel, buy tickets and follow a fixed showtime.","zh":"在戲院看電影需要外出、買票和配合固定放映時間。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"cinema operators","meaning":"戲院經營者","examples":[{"en":"Cinema operators need to rethink the cinema-going experience.","zh":"戲院經營者需要重新思考入戲院看電影的體驗。"},{"en":"Cinema operators are companies or managers responsible for running cinemas.","zh":"戲院經營者是負責營運戲院的公司或管理者。"},{"en":"Cinema operators decide ticket prices, facilities, schedules and customer services.","zh":"戲院經營者會決定票價、設施、放映時間和顧客服務。"},{"en":"If attendance falls, cinema operators may need to introduce new ideas.","zh":"如果入場人次下降，戲院經營者可能需要推出新構思。"},{"en":"Successful cinema operators must understand what audiences value beyond the film itself.","zh":"成功的戲院經營者必須理解觀眾在電影本身以外重視甚麼。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"consider how to","meaning":"考慮如何","examples":[{"en":"Cinema operators are considering how to attract more moviegoers.","zh":"戲院經營者正在考慮如何吸引更多電影觀眾。"},{"en":"To consider how to do something means to think carefully about the best method for achieving it.","zh":"「consider how to」表示仔細思考達成某件事的最佳方法。"},{"en":"The school is considering how to reduce food waste.","zh":"學校正在考慮如何減少食物浪費。"},{"en":"Cinemas must consider how to make a visit more attractive than staying at home.","zh":"戲院必須考慮如何令外出看電影比留在家更吸引。"},{"en":"Careful planning begins by considering different possible approaches.","zh":"仔細規劃通常由考慮不同可行方法開始。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"turn… from… into…","meaning":"將……由……變成……","examples":[{"en":"Cinemas need to turn cinema-going from a routine purchase into a memorable social experience.","zh":"戲院需要將入戲院看電影由例行消費變成難忘的社交體驗。"},{"en":"“Turn A from X into Y” means to change A so that its nature or role becomes very different.","zh":"「turn A from X into Y」表示改變A，使其性質或作用由X變成Y。"},{"en":"The school turned an empty yard from a parking area into a garden.","zh":"學校把空置庭院由停車地方變成花園。"},{"en":"Cinemas can turn a simple film screening into an event by adding discussions and activities.","zh":"戲院可以加入討論和活動，把普通放映變成一場特別活動。"},{"en":"This structure clearly describes transformation from one state to another.","zh":"這個句式清楚描述由一種狀態轉變成另一種狀態。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"cinema-going","meaning":"入戲院看電影","examples":[{"en":"Cinema-going should feel like a memorable social experience.","zh":"入戲院看電影應該感覺像一次難忘的社交體驗。"},{"en":"Cinema-going means the activity of going out to a cinema to watch a film.","zh":"入戲院看電影是指外出去電影院觀看電影的活動。"},{"en":"Cinema-going often involves travelling, buying snacks and watching with other people.","zh":"入戲院看電影通常包括乘車、買小食和與其他人一起觀看。"},{"en":"Cinema-going competes with home entertainment because it requires more time and effort.","zh":"入戲院看電影需要更多時間和精力，因此要與在家娛樂競爭。"},{"en":"To attract audiences, cinema-going needs to offer something that home viewing cannot.","zh":"要吸引觀眾，入戲院看電影需要提供在家觀看無法得到的東西。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"routine purchase","meaning":"例行消費","examples":[{"en":"Cinema-going should not feel like a routine purchase.","zh":"入戲院看電影不應只感覺像例行消費。"},{"en":"A routine purchase is something people buy regularly without finding the experience especially exciting or memorable.","zh":"例行消費是人們經常購買、卻不覺得過程特別刺激或難忘的東西。"},{"en":"Buying toothpaste is usually a routine purchase.","zh":"買牙膏通常是一種例行消費。"},{"en":"If cinema tickets feel like a routine purchase, people may choose cheaper entertainment instead.","zh":"如果電影票只像例行消費，人們可能會改選較便宜的娛樂。"},{"en":"Experiences become more attractive when they offer more than the product being purchased.","zh":"當體驗提供的不只是所購買的產品，它便會更有吸引力。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"memorable social experience","meaning":"難忘的社交體驗","examples":[{"en":"Cinemas should offer a memorable social experience.","zh":"戲院應提供難忘的社交體驗。"},{"en":"A memorable social experience is an enjoyable shared activity that people remember afterwards.","zh":"難忘的社交體驗是與別人共同參與，而且事後仍令人記得的愉快活動。"},{"en":"A birthday dinner can become a memorable social experience when friends celebrate together.","zh":"朋友一起慶祝時，生日晚餐可以成為難忘的社交體驗。"},{"en":"Themed screenings and discussions can make cinema visits more memorable and social.","zh":"主題放映和討論可以令戲院到訪更難忘、更有社交性。"},{"en":"Shared experiences give people reasons to leave home that private viewing cannot provide.","zh":"共同體驗可以提供在家私人觀看無法帶來的外出理由。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"main reasons for","meaning":"……的主要原因","examples":[{"en":"The report explains the main reasons for the decline.","zh":"報告解釋入場人次下降的主要原因。"},{"en":"“The main reasons for” means the most important causes behind a situation or problem.","zh":"「the main reasons for」表示造成某種情況或問題最重要的原因。"},{"en":"The report identifies the main reasons for student stress.","zh":"報告指出學生壓力的主要原因。"},{"en":"High costs and weaker novelty are two main reasons for lower cinema attendance.","zh":"高成本和特別感減弱，是戲院入場人次下降的兩個主要原因。"},{"en":"Focusing on the main reasons helps avoid being distracted by minor details.","zh":"集中分析主要原因，可以避免被次要細節分散注意力。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"practical ways to","meaning":"……的實際方法","examples":[{"en":"The report suggests practical ways to increase the number of moviegoers.","zh":"報告提出增加電影觀眾人數的實際方法。"},{"en":"“Practical ways to” means realistic and workable methods for achieving something.","zh":"「practical ways to」表示達成某件事的現實而可行方法。"},{"en":"Teachers discussed practical ways to help weak readers.","zh":"老師討論幫助閱讀能力較弱學生的實際方法。"},{"en":"Discount tickets are one practical way to make cinema-going more affordable.","zh":"優惠票價是令入戲院看電影更可負擔的一個實際方法。"},{"en":"A practical suggestion should be possible to carry out, not merely sound attractive.","zh":"實際建議應該能真正執行，而不只是聽起來吸引。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"increase the number of","meaning":"增加……的數目","examples":[{"en":"Cinemas need to increase the number of moviegoers.","zh":"戲院需要增加電影觀眾的數目。"},{"en":"To increase the number of something means to make more people or items belong to that group.","zh":"「increase the number of」表示令某一群體中的人或物數量增加。"},{"en":"The school hopes to increase the number of students joining sports clubs.","zh":"學校希望增加參加運動學會的學生人數。"},{"en":"Lower prices may increase the number of young people visiting cinemas.","zh":"較低票價可能增加到戲院的年輕人數目。"},{"en":"Organisations often measure success by whether participation numbers rise.","zh":"機構常以參與人數是否上升來衡量成效。"}],"source":"2015 Q7.pdf","sourcePage":2},{"front":"moviegoers","meaning":"電影觀眾；入戲院看電影的人","examples":[{"en":"Cinemas need to attract more moviegoers.","zh":"戲院需要吸引更多電影觀眾。"},{"en":"Moviegoers are people who go to cinemas to watch films.","zh":"電影觀眾是會到戲院觀看電影的人。"},{"en":"Young moviegoers may be especially sensitive to ticket prices.","zh":"年輕電影觀眾可能特別在意票價。"},{"en":"Cinemas need to understand why some moviegoers now prefer streaming.","zh":"戲院需要了解為甚麼部分電影觀眾現在較喜歡串流平台。"},{"en":"A good cinema experience can encourage occasional moviegoers to return more often.","zh":"良好的戲院體驗可以鼓勵偶爾入場的觀眾更常回來。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"central finding","meaning":"主要結論","examples":[{"en":"The central finding is that cinemas must improve value and experience.","zh":"主要結論是戲院必須改善價值和體驗。"},{"en":"A central finding is the most important conclusion or result reached by a report or study.","zh":"主要結論是報告或研究得出的最重要結果或看法。"},{"en":"The survey’s central finding was that students wanted more flexible study spaces.","zh":"那項調查的主要結論是學生希望有更多靈活的學習空間。"},{"en":"A central finding should be strongly supported by the evidence presented earlier.","zh":"主要結論應由之前提出的證據有力支持。"},{"en":"Readers often look to the central finding for the report’s main message.","zh":"讀者通常會從主要結論了解報告的核心訊息。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"regain audiences","meaning":"重新吸引觀眾","examples":[{"en":"Hong Kong cinemas can regain audiences by improving the experience.","zh":"香港戲院可以透過改善體驗重新吸引觀眾。"},{"en":"To regain audiences means to attract back people who have stopped or reduced their participation.","zh":"重新吸引觀眾表示把已經停止或減少參與的人再次吸引回來。"},{"en":"The theatre regained audiences after introducing cheaper weekday performances.","zh":"劇院推出較便宜的平日表演後重新吸引了觀眾。"},{"en":"Cinemas may regain audiences if visits become more affordable and distinctive.","zh":"如果到訪戲院變得更可負擔和有特色，戲院可能重新吸引觀眾。"},{"en":"Regaining an audience usually requires understanding why people left in the first place.","zh":"要重新吸引觀眾，通常先要了解他們當初為甚麼離開。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"only if","meaning":"只有在……情況下","examples":[{"en":"Cinemas can regain audiences only if they improve value and experience.","zh":"戲院只有在改善價值和體驗的情況下，才能重新吸引觀眾。"},{"en":"“Only if” introduces a condition that must be satisfied before something can happen.","zh":"「only if」帶出某件事發生前必須符合的條件。"},{"en":"Students can enter the competition only if they submit the form on time.","zh":"學生只有按時提交表格才能參加比賽。"},{"en":"Cinemas will compete effectively only if people feel the visit is worth the effort.","zh":"只有當人們覺得到訪值得付出時間和精力，戲院才能有效競爭。"},{"en":"“Only if” expresses a stronger condition than simply saying something may help.","zh":"「only if」表達的是必要條件，比單純說某件事有幫助更強。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"value and experience","meaning":"價值與體驗","examples":[{"en":"Cinemas must improve both value and experience.","zh":"戲院必須同時改善價值與體驗。"},{"en":"“Value and experience” refers to whether customers feel something is worth the cost and whether the activity itself is enjoyable.","zh":"「value and experience」分別指顧客是否覺得值得付出成本，以及活動本身是否愉快。"},{"en":"A restaurant succeeds when both value and experience satisfy customers.","zh":"餐廳在價值和體驗都令顧客滿意時較容易成功。"},{"en":"Cheaper tickets improve value, while better events improve the cinema experience.","zh":"較便宜票價改善價值，而更好的活動改善戲院體驗。"},{"en":"Customers often judge a service by both what they pay and what they receive emotionally and practically.","zh":"顧客常同時根據付出多少，以及實際和情感上得到甚麼來評價服務。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"reasons for the decline","meaning":"衰退的原因","examples":[{"en":"The report lists two reasons for the decline.","zh":"報告列出兩個衰退的原因。"},{"en":"“Reasons for the decline” means the causes explaining why a number, level or activity has fallen.","zh":"「reasons for the decline」表示解釋某個數量、程度或活動為何下降的原因。"},{"en":"Researchers looked at reasons for the decline in reading among teenagers.","zh":"研究人員分析青少年閱讀下降的原因。"},{"en":"Cost and weaker excitement are major reasons for the decline in cinema-going.","zh":"成本和特別感減弱，是入戲院看電影衰退的主要原因。"},{"en":"Identifying causes is necessary before proposing effective solutions.","zh":"在提出有效解決方法前，必須先找出原因。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"cost-benefit balance","meaning":"成本效益平衡","examples":[{"en":"The cost-benefit balance of cinema-going has changed.","zh":"入戲院看電影的成本效益平衡已經改變。"},{"en":"The cost-benefit balance is the relationship between what something costs and the advantages it provides.","zh":"成本效益平衡是付出的成本與得到的好處之間的關係。"},{"en":"People reconsider the cost-benefit balance when a service becomes more expensive.","zh":"當服務變得更昂貴，人們會重新考慮其成本效益平衡。"},{"en":"Streaming has changed the cost-benefit balance by offering many films at home for one subscription fee.","zh":"串流平台以一個訂閱費提供大量在家電影，改變了成本效益平衡。"},{"en":"Consumers are less willing to pay when the perceived benefits no longer justify the cost.","zh":"當感受到的好處不再值得所付成本，消費者會較不願意付款。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"has changed","meaning":"已經改變","examples":[{"en":"The cost-benefit balance has changed.","zh":"成本效益平衡已經改變。"},{"en":"“Has changed” means something is now different from how it was before.","zh":"「has changed」表示某件事現在與以前不同。"},{"en":"The way students find information has changed because of smartphones.","zh":"因為智能手機，學生找資料的方法已經改變。"},{"en":"Cinema competition has changed as home entertainment has improved.","zh":"隨着家庭娛樂改善，戲院面對的競爭已經改變。"},{"en":"When conditions change, businesses may need to change their strategies too.","zh":"當環境改變，企業也可能需要改變策略。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"no longer compared only with","meaning":"不再只與……比較","examples":[{"en":"A cinema ticket is no longer compared only with another night out.","zh":"電影票現在不再只與另一次外出消遣比較。"},{"en":"“No longer compared only with” means people now judge something against a wider range of alternatives than before.","zh":"「no longer compared only with」表示人們現在會用比以前更廣泛的選擇作比較。"},{"en":"Universities are no longer compared only with local institutions because students also consider overseas options.","zh":"大學不再只與本地院校比較，因為學生也會考慮海外選擇。"},{"en":"Cinema prices are now compared with streaming subscriptions, games and short videos.","zh":"電影票價現在會與串流訂閱、遊戲和短片比較。"},{"en":"More alternatives make consumers judge value more strictly.","zh":"替代選擇越多，消費者對價值的判斷便越嚴格。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"another night out","meaning":"另一次外出消遣","examples":[{"en":"A cinema ticket is now compared with many other forms of entertainment.","zh":"電影票現在會與很多其他娛樂形式比較。"},{"en":"Another night out means another evening spent outside the home for leisure or social activity.","zh":"另一次外出消遣是指另一個離開家中進行休閒或社交活動的晚上。"},{"en":"Dinner with friends is another night out that competes for the same entertainment budget.","zh":"與朋友吃晚飯也是一次外出消遣，會競爭同一筆娛樂預算。"},{"en":"People may choose a concert or restaurant instead of another night out at the cinema.","zh":"人們可能選擇演唱會或餐廳，而不是另一次去戲院的外出消遣。"},{"en":"Consumers compare different leisure activities when deciding how to spend limited time and money.","zh":"消費者會比較不同休閒活動，決定如何使用有限時間和金錢。"}],"source":"2015 Q7.pdf","sourcePage":3},{"front":"streaming platforms","meaning":"串流平台","examples":[{"en":"Cinemas compete with streaming platforms.","zh":"戲院要與串流平台競爭。"},{"en":"Streaming platforms are online services that let users watch films, series or other video content over the internet.","zh":"串流平台是讓使用者透過互聯網觀看電影、劇集或其他影片內容的網上服務。"},{"en":"Many streaming platforms offer large libraries for a monthly fee.","zh":"很多串流平台以每月收費提供大量影片。"},{"en":"Streaming platforms make home viewing convenient because users can choose when to watch.","zh":"串流平台讓使用者自由選擇觀看時間，因此在家觀看很方便。"},{"en":"Cinemas must offer a different kind of value because they cannot compete with streaming on convenience alone.","zh":"戲院不能單靠方便程度與串流競爭，所以必須提供不同價值。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"mobile games","meaning":"手機遊戲","examples":[{"en":"Mobile games compete for young people’s attention.","zh":"手機遊戲會爭奪年輕人的注意力。"},{"en":"Mobile games are video games designed to be played on smartphones or tablets.","zh":"手機遊戲是為智能手機或平板電腦而設計的電子遊戲。"},{"en":"Many people play mobile games during short journeys or breaks.","zh":"很多人在短途車程或休息時間玩手機遊戲。"},{"en":"Mobile games compete with films because both require leisure time and attention.","zh":"手機遊戲與電影競爭，因為兩者都需要人的休閒時間和注意力。"},{"en":"Entertainment businesses compete not only for money but also for the limited time people have.","zh":"娛樂企業競爭的不只是金錢，也包括人們有限的時間。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"short videos","meaning":"短片","examples":[{"en":"Short videos have become a common form of entertainment.","zh":"短片已成為常見娛樂形式。"},{"en":"Short videos are brief pieces of video content designed to be watched quickly, often on social media.","zh":"短片是時間較短、通常在社交媒體快速觀看的影片內容。"},{"en":"People may watch several short videos while waiting for a bus.","zh":"人們等巴士時可能連續觀看幾段短片。"},{"en":"Short videos suit fragmented free time better than a two-hour film.","zh":"短片比兩小時電影更適合零碎空閒時間。"},{"en":"Their convenience can make long-form entertainment feel like a bigger commitment.","zh":"短片的方便性可能令較長娛樂內容感覺需要更大投入。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"between transport, food and tickets","meaning":"連同交通、食物和門票","examples":[{"en":"Between transport, food and tickets, a cinema visit can feel expensive.","zh":"連同交通、食物和門票，一次戲院之行可能令人覺得昂貴。"},{"en":"“Between A, B and C” here means when the combined costs of all these items are considered together.","zh":"這裏的「between A, B and C」表示把幾項成本加在一起考慮。"},{"en":"Between rent, bills and transport, the monthly budget disappeared quickly.","zh":"連同租金、帳單和交通，每月預算很快便花光。"},{"en":"A cinema visit may cost much more than the ticket price once transport and snacks are added.","zh":"加上交通和小食後，一次戲院之行的成本可能遠高於票價本身。"},{"en":"Consumers often judge the total cost of an outing rather than one item alone.","zh":"消費者常會評估整次外出的總成本，而不只是單一項目。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"casual evening","meaning":"輕鬆晚間活動","examples":[{"en":"Even a casual evening at the cinema can feel expensive.","zh":"即使只是輕鬆去戲院一晚，也可能令人覺得昂貴。"},{"en":"A casual evening is a relaxed outing without a formal or special occasion.","zh":"輕鬆晚間活動是沒有正式或特別場合、以放鬆為主的外出。"},{"en":"We planned a casual evening of dinner and a film after work.","zh":"我們計劃下班後輕鬆吃晚飯再看電影。"},{"en":"If an ordinary casual evening becomes costly, people may stay home instead.","zh":"如果普通的輕鬆晚間活動也變得昂貴，人們可能會選擇留在家。"},{"en":"Leisure activities need reasonable prices if people are expected to enjoy them regularly.","zh":"如果希望人們經常參與休閒活動，價格需要合理。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"feel expensive","meaning":"感覺昂貴","examples":[{"en":"A cinema visit can feel expensive for many families.","zh":"對很多家庭來說，去戲院可能感覺昂貴。"},{"en":"To feel expensive means to seem costly relative to what someone can afford or what they think the experience is worth.","zh":"「feel expensive」表示相對於負擔能力或所得價值，某件事看起來成本很高。"},{"en":"A meal can feel expensive even at a moderate price if the quality is poor.","zh":"即使價格不算非常高，如果食物質素差，一餐仍可能令人覺得昂貴。"},{"en":"Cinema-going feels expensive when families must buy several tickets plus food and transport.","zh":"家庭需要買幾張票，再加食物和交通時，入戲院便會感覺昂貴。"},{"en":"Perceived value matters because people react to whether a cost feels justified.","zh":"人們會根據成本是否值得來判斷價值，所以感受十分重要。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, watching a film at home is convenient.","zh":"相比之下，在家看電影很方便。"},{"en":"“By contrast” introduces a situation that is clearly different from the one just described.","zh":"「by contrast」用來帶出與剛才描述明顯不同的情況。"},{"en":"Cinema-going requires travel; by contrast, streaming begins with a few clicks.","zh":"去戲院需要乘車；相比之下，串流平台只需按幾下便可以開始。"},{"en":"City centres are crowded; by contrast, some rural areas are quiet.","zh":"市中心很擠迫；相比之下，一些鄉郊地方很安靜。"},{"en":"This phrase is useful when two alternatives have noticeably different qualities.","zh":"當兩個選擇的特點明顯不同時，這個片語很有用。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"watching a film at home","meaning":"在家看電影","examples":[{"en":"Watching a film at home allows viewers to relax in private.","zh":"在家看電影讓觀眾可以私下放鬆。"},{"en":"Watching a film at home means viewing it in your own living space rather than going to a cinema.","zh":"在家看電影表示在自己的居住空間觀看，而不是前往戲院。"},{"en":"Families can pause for dinner when watching a film at home.","zh":"家庭在家看電影時可以中途暫停吃晚飯。"},{"en":"Home viewing removes travel time and lets people control the environment.","zh":"在家觀看不用乘車，也能讓人控制周圍環境。"},{"en":"Its comfort is one of the strongest alternatives to cinema-going.","zh":"這種舒適性是入戲院看電影最強的替代選擇之一。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"allow viewers to","meaning":"讓觀眾能夠","examples":[{"en":"Home viewing allows viewers to pause the story.","zh":"在家觀看讓觀眾能夠暫停劇情。"},{"en":"To allow viewers to do something means to give them the freedom or possibility to do it.","zh":"「allow viewers to」表示讓觀眾有自由或可能去做某件事。"},{"en":"Online lessons allow viewers to replay difficult explanations.","zh":"網上課堂讓觀眾能夠重播較難的解釋。"},{"en":"Streaming allows viewers to choose when and where they watch.","zh":"串流平台讓觀眾能夠自行選擇何時何地觀看。"},{"en":"Greater control makes home viewing attractive to people with busy schedules.","zh":"更大的控制權令在家觀看對忙碌的人更有吸引力。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"pause the story","meaning":"暫停劇情","examples":[{"en":"Viewers can pause the story when they watch at home.","zh":"觀眾在家觀看時可以暫停劇情。"},{"en":"To pause the story means to temporarily stop the film and continue later.","zh":"暫停劇情是指暫時停止電影，之後再繼續觀看。"},{"en":"She paused the story to answer the phone.","zh":"她暫停劇情去接電話。"},{"en":"At home, parents can pause the story if a child needs attention.","zh":"在家看電影時，如果孩子需要照顧，父母可以暫停劇情。"},{"en":"Cinemas cannot offer this flexibility because the film continues for everyone.","zh":"戲院無法提供這種彈性，因為電影會為所有觀眾繼續播放。"}],"source":"2015 Q7.pdf","sourcePage":4},{"front":"choose subtitles","meaning":"選擇字幕","examples":[{"en":"Viewers can choose subtitles when watching at home.","zh":"觀眾在家觀看時可以選擇字幕。"},{"en":"To choose subtitles means to select the language or type of written dialogue shown on the screen.","zh":"選擇字幕表示選取螢幕上顯示對白的語言或字幕類型。"},{"en":"Language learners may choose English subtitles to practise reading.","zh":"語言學習者可能選擇英文字幕練習閱讀。"},{"en":"Home viewers can choose subtitles that best match their needs.","zh":"在家觀看的人可以選擇最適合自己需要的字幕。"},{"en":"Personalised options make digital viewing more flexible than a fixed cinema screening.","zh":"個人化選項令數碼觀看比固定的戲院放映更有彈性。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"avoid queues","meaning":"避免排隊","examples":[{"en":"Home viewing allows people to avoid queues.","zh":"在家觀看讓人可以避免排隊。"},{"en":"To avoid queues means not having to wait in lines for tickets, food or entry.","zh":"避免排隊表示不用排隊等候買票、食物或入場。"},{"en":"Buying tickets online helps visitors avoid queues at the entrance.","zh":"網上買票有助訪客避免在入口排隊。"},{"en":"Staying home allows viewers to avoid queues completely.","zh":"留在家觀看可以完全避免排隊。"},{"en":"Avoiding waiting is especially attractive to people who already have busy days.","zh":"對本來已經很忙的人來說，不用等待特別有吸引力。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"relax in private","meaning":"私下放鬆","examples":[{"en":"Viewers can relax in private at home.","zh":"觀眾可以在家私下放鬆。"},{"en":"To relax in private means to rest comfortably without being watched by strangers or following public rules.","zh":"私下放鬆表示不用被陌生人看到，也不用配合公眾場合規矩，可以舒服休息。"},{"en":"After a long day, she preferred to relax in private rather than go out.","zh":"漫長一天後，她寧願私下放鬆而不是外出。"},{"en":"Home viewers can wear comfortable clothes and talk freely while relaxing in private.","zh":"在家觀看的人可以穿舒適衣服，也可以自在說話。"},{"en":"Privacy can make home entertainment especially attractive to tired people.","zh":"私隱和自在感令家庭娛樂對疲倦的人特別吸引。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"rushing home after","meaning":"在……後趕回家","examples":[{"en":"A teenager may be rushing home after tutorial classes.","zh":"青少年可能在補習課後趕回家。"},{"en":"“Rushing home after” means hurrying back home immediately following another activity.","zh":"「rushing home after」表示完成另一項活動後立即急忙回家。"},{"en":"She was rushing home after work because she had an online meeting.","zh":"她下班後趕回家，因為還有網上會議。"},{"en":"Teenagers may not want another journey when they are already rushing home after lessons.","zh":"青少年上完課已經趕回家時，未必還想再外出一趟。"},{"en":"Busy schedules make home entertainment more attractive because it requires no extra travel.","zh":"繁忙日程令家庭娛樂更有吸引力，因為不用再乘車。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"tutorial classes","meaning":"補習課","examples":[{"en":"Teenagers may feel tired after tutorial classes.","zh":"青少年上完補習課後可能感到疲倦。"},{"en":"Tutorial classes are extra academic lessons taken outside normal school hours.","zh":"補習課是在正常上課時間以外進行的額外學業課堂。"},{"en":"Many Hong Kong students attend tutorial classes before important examinations.","zh":"很多香港學生在重要考試前會上補習課。"},{"en":"A student finishing tutorial classes late may prefer to go straight home.","zh":"晚上才完成補習課的學生可能寧願直接回家。"},{"en":"Long school days reduce the time and energy available for evening entertainment.","zh":"漫長的上課日會減少晚上娛樂可用的時間和精力。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"exhausted after work","meaning":"下班後筋疲力盡","examples":[{"en":"A parent may be exhausted after work.","zh":"家長下班後可能筋疲力盡。"},{"en":"To be exhausted after work means to feel extremely tired after completing the working day.","zh":"下班後筋疲力盡表示完成一天工作後感到非常疲累。"},{"en":"He was exhausted after work and fell asleep shortly after dinner.","zh":"他下班後筋疲力盡，晚飯後不久便睡着。"},{"en":"Parents who are exhausted after work may prefer a film at home to another trip outside.","zh":"下班後筋疲力盡的家長可能較喜歡在家看電影，而不是再外出。"},{"en":"Physical and mental tiredness strongly influence leisure choices.","zh":"身體和精神疲勞會強烈影響休閒選擇。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"such convenience","meaning":"這種方便","examples":[{"en":"Such convenience is hard to resist.","zh":"這種方便很難抗拒。"},{"en":"“Such convenience” refers back to the high level of ease and flexibility just described.","zh":"「such convenience」指前面所描述的高度方便和彈性。"},{"en":"With food delivered in twenty minutes, such convenience changes shopping habits.","zh":"食物二十分鐘便送到，這種方便改變了購物習慣。"},{"en":"Pausing, choosing subtitles and avoiding travel create such convenience that home viewing becomes attractive.","zh":"可以暫停、選字幕又不用外出，這種方便令在家觀看很吸引。"},{"en":"When one option offers much greater convenience, competitors need to offer value in another way.","zh":"當一個選擇方便得多，競爭者便需要用其他方式提供價值。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"hard to resist","meaning":"難以抗拒","examples":[{"en":"The convenience of home viewing is hard to resist.","zh":"在家觀看的方便很難抗拒。"},{"en":"“Hard to resist” means very tempting or difficult to refuse.","zh":"「hard to resist」表示非常吸引，令人很難拒絕。"},{"en":"The smell of fresh bread was hard to resist.","zh":"新鮮麵包的香味令人難以抗拒。"},{"en":"Home viewing is hard to resist when people are tired and the weather is bad.","zh":"當人疲倦而天氣又差，在家觀看會特別難以抗拒。"},{"en":"Something becomes hard to resist when its advantages match a person’s immediate needs.","zh":"當某個選擇的優點正好符合眼前需要，它就會變得難以抗拒。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"as a result","meaning":"因此","examples":[{"en":"As a result, many people question the need to go out.","zh":"因此，很多人會質疑是否有需要外出。"},{"en":"“As a result” introduces a consequence caused by the situation just described.","zh":"「as a result」用來帶出由前面情況造成的結果。"},{"en":"The road was flooded; as a result, buses were delayed.","zh":"道路水浸；因此巴士延誤。"},{"en":"Home viewing is easy and cheap; as a result, cinemas face stronger competition.","zh":"在家觀看既容易又便宜；因此戲院面對更強競爭。"},{"en":"This phrase clearly links a cause with its effect.","zh":"這個片語清楚連接原因和結果。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"ask themselves","meaning":"問自己","examples":[{"en":"Many people ask themselves why they should go out.","zh":"很多人問自己為甚麼要外出。"},{"en":"To ask yourself something means to think privately about a question before making a decision.","zh":"「ask yourself」表示在作決定前，自己在心裏思考某個問題。"},{"en":"Before buying the expensive phone, she asked herself whether she really needed it.","zh":"買昂貴手機前，她問自己是否真的需要它。"},{"en":"Consumers ask themselves whether a cinema visit offers enough extra value.","zh":"消費者會問自己去戲院是否提供足夠額外價值。"},{"en":"When alternatives increase, people naturally ask themselves which option is worth the effort.","zh":"當選擇增加，人自然會問自己哪個選擇最值得付出。"}],"source":"2015 Q7.pdf","sourcePage":5},{"front":"why go out if…","meaning":"如果……，為何要外出？","examples":[{"en":"People may ask, “Why go out if the same story can be watched later?”","zh":"人們可能會問：「如果同一個故事之後可以看，為何要外出？」"},{"en":"“Why go out if…?” questions whether leaving home is worthwhile when an easier alternative exists.","zh":"「Why go out if…?」是在有較容易替代方法時，質疑外出是否值得。"},{"en":"Why drive across town if the meeting can be held online?","zh":"如果會議可以網上進行，為何要駕車橫跨城市？"},{"en":"Viewers may ask why they should go out if the film will soon be available at home.","zh":"如果電影很快便可在家觀看，觀眾可能會問為甚麼還要外出。"},{"en":"This question highlights the extra effort required by one option compared with another.","zh":"這個問題突出其中一個選擇比另一個需要更多精力。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"the same story","meaning":"同一個故事","examples":[{"en":"The same story can often be watched later at home.","zh":"同一個故事往往之後可以在家觀看。"},{"en":"“The same story” means essentially the same film content or narrative, regardless of where it is watched.","zh":"「the same story」表示無論在哪裏觀看，基本上都是相同的電影內容或情節。"},{"en":"Viewers may ask why they should pay more when the same story will appear on streaming later.","zh":"如果同一個故事之後會在串流平台出現，觀眾可能會問為何要付更多。"},{"en":"The cinema must therefore offer something beyond the same story itself.","zh":"因此戲院必須提供同一個故事本身以外的東西。"},{"en":"Place and social experience can change how the same story feels.","zh":"地點和社交體驗可以改變觀看同一個故事時的感受。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"be watched later","meaning":"稍後觀看","examples":[{"en":"A film can be watched later with less effort.","zh":"電影可以稍後用較少精力觀看。"},{"en":"To be watched later means to view something at a future time instead of immediately.","zh":"「be watched later」表示不立即觀看，而在之後某個時間觀看。"},{"en":"The programme can be watched later online if you miss the live broadcast.","zh":"如果錯過直播，節目之後可以在網上觀看。"},{"en":"Knowing a film can be watched later reduces the urgency to visit a cinema now.","zh":"知道電影可以稍後觀看，會減少現在去戲院的迫切性。"},{"en":"Delayed availability gives consumers more freedom to choose the time that suits them.","zh":"可以延後觀看讓消費者更自由選擇合適時間。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"with less effort","meaning":"用較少精力","examples":[{"en":"Many films can be watched at home with less effort.","zh":"很多電影可以在家用較少精力觀看。"},{"en":"“With less effort” means requiring less time, energy, planning or physical action.","zh":"「with less effort」表示需要較少時間、精力、規劃或實際行動。"},{"en":"Online banking lets people pay bills with less effort.","zh":"網上銀行讓人用較少精力繳付帳單。"},{"en":"Home viewing requires less effort because people do not need to travel or queue.","zh":"在家觀看不用乘車或排隊，因此需要較少精力。"},{"en":"When two options offer similar results, people often choose the one requiring less effort.","zh":"當兩個選擇帶來相似結果，人往往會選較省力的一個。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"another reason","meaning":"另一個原因","examples":[{"en":"Another reason is that cinema-going feels less special.","zh":"另一個原因是入戲院看電影感覺沒有以前那麼特別。"},{"en":"“Another reason” introduces an additional cause after one reason has already been discussed.","zh":"「another reason」在已討論一個原因後，帶出另一個額外原因。"},{"en":"High rent is one problem; another reason for closure is lower customer demand.","zh":"高租金是一個問題；另一個結業原因是顧客需求下降。"},{"en":"After discussing cost, the report gives another reason connected with experience.","zh":"報告討論成本後，再提出另一個與體驗有關的原因。"},{"en":"This phrase helps organise several causes clearly in a report.","zh":"這個片語有助在報告中清楚整理多個原因。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"special feeling","meaning":"特別感覺","examples":[{"en":"The special feeling of cinema-going has become weaker.","zh":"入戲院看電影的特別感覺已經變弱。"},{"en":"A special feeling is a sense that an experience is unusual, exciting or more meaningful than ordinary daily activity.","zh":"特別感覺是認為某段經歷不普通、令人興奮或比日常活動更有意義的感受。"},{"en":"Dressing up for a celebration can create a special feeling.","zh":"為慶祝活動特別打扮可以帶來特別感覺。"},{"en":"Cinemas lose some of their appeal when the special feeling disappears.","zh":"當特別感覺消失，戲院會失去部分吸引力。"},{"en":"People are more willing to spend time and money on experiences that feel distinctive.","zh":"人們較願意為有特色的體驗付出時間和金錢。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"become weaker","meaning":"變弱","examples":[{"en":"The special feeling of going to the cinema has become weaker.","zh":"去戲院的特別感覺已經變弱。"},{"en":"To become weaker means to lose strength, intensity or influence over time.","zh":"「become weaker」表示某種力量、程度或影響隨時間減少。"},{"en":"Her interest in the hobby became weaker after she started a new job.","zh":"她開始新工作後，對那項嗜好的興趣變弱了。"},{"en":"The cinema’s specialness became weaker as films became available everywhere.","zh":"隨着電影到處都能觀看，戲院的特別感變弱。"},{"en":"When an advantage becomes weaker, competitors need new reasons to attract customers.","zh":"當一項優勢變弱，競爭者就需要新的理由吸引顧客。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"in the past","meaning":"在過去","examples":[{"en":"In the past, cinemas were among the few places to watch new films.","zh":"在過去，戲院是少數可以觀看新電影的地方之一。"},{"en":"“In the past” refers to an earlier time before the present.","zh":"「in the past」指現在以前的較早時期。"},{"en":"In the past, people often bought music on CDs.","zh":"在過去，人們常購買CD聽音樂。"},{"en":"In the past, cinema had less competition from home technology.","zh":"在過去，戲院面對來自家庭科技的競爭較少。"},{"en":"Comparing the past with the present helps explain why consumer behaviour has changed.","zh":"比較過去和現在，有助解釋消費者行為為何改變。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"among the few places","meaning":"少數地方之一","examples":[{"en":"Cinemas were among the few places where people could enjoy new films.","zh":"戲院曾是人們可以欣賞新電影的少數地方之一。"},{"en":"“Among the few places” means one of only a small number of locations offering something.","zh":"「among the few places」表示只有少量地方提供某項東西，而它是其中之一。"},{"en":"The library was among the few places in the village with internet access.","zh":"圖書館是村內少數有互聯網的地方之一。"},{"en":"When cinemas were among the few places showing new releases, they felt more essential.","zh":"當戲院是少數播放新電影的地方之一，它便顯得更重要。"},{"en":"A service loses uniqueness when many more places begin offering the same thing.","zh":"當越來越多地方提供同一服務，它原本的獨特性便會下降。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"large screen","meaning":"大銀幕","examples":[{"en":"Cinemas once offered films on a large screen.","zh":"戲院以前提供大銀幕電影體驗。"},{"en":"A large screen is a big display surface that makes images appear much larger than on a phone or television.","zh":"大銀幕是大型顯示畫面，令影像比手機或電視上大得多。"},{"en":"Action films can feel more dramatic on a large screen.","zh":"動作電影在大銀幕上可能感覺更震撼。"},{"en":"The large screen remains one advantage of cinema-going.","zh":"大銀幕仍是入戲院看電影的一項優勢。"},{"en":"However, a large screen alone may not be enough if audiences find the rest of the experience ordinary.","zh":"不過，如果其他體驗很普通，單靠大銀幕可能已不足夠。"}],"source":"2015 Q7.pdf","sourcePage":6},{"front":"entertainment is everywhere","meaning":"娛樂無處不在","examples":[{"en":"Now, entertainment is everywhere.","zh":"現在，娛樂無處不在。"},{"en":"“Entertainment is everywhere” means people can easily access enjoyable content in many places and through many devices.","zh":"「entertainment is everywhere」表示人們在很多地方和裝置都很容易接觸娛樂內容。"},{"en":"Phones make entertainment available on buses, in cafés and at home.","zh":"手機令人在巴士、咖啡店和家中都能娛樂。"},{"en":"When entertainment is everywhere, cinemas no longer control access to popular films and media.","zh":"當娛樂無處不在，戲院不再控制人們接觸熱門電影和媒體的途徑。"},{"en":"Constant entertainment increases competition for people’s attention.","zh":"無處不在的娛樂令爭奪注意力的競爭加劇。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"trailers","meaning":"預告片","examples":[{"en":"Trailers appear on social media before the film is released.","zh":"電影上映前，預告片已會出現在社交媒體。"},{"en":"Trailers are short promotional videos showing selected scenes from a film before its release.","zh":"預告片是在電影上映前，展示部分精選片段的短宣傳影片。"},{"en":"A good trailer creates interest without revealing the whole story.","zh":"好的預告片會引起興趣，但不會揭露整個故事。"},{"en":"Viewers often watch trailers online before deciding whether to buy tickets.","zh":"觀眾買票前常會先在網上觀看預告片。"},{"en":"Trailers now reach audiences through phones long before people enter a cinema.","zh":"現在觀眾早在進入戲院前，已能透過手機接觸預告片。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"reviews","meaning":"影評","examples":[{"en":"Reviews can influence whether people buy cinema tickets.","zh":"影評可以影響人們是否購買電影票。"},{"en":"Reviews are opinions or evaluations discussing the quality of a film, product or experience.","zh":"影評是評論電影品質的意見或評價。"},{"en":"Positive reviews encouraged us to try the new restaurant.","zh":"正面評價鼓勵我們去試那間新餐廳。"},{"en":"Film reviews may influence audiences before they decide on a screening.","zh":"觀眾決定看哪場電影前，影評可能已影響他們。"},{"en":"Reviews can reduce uncertainty by giving potential customers information from other people.","zh":"評論提供其他人的資訊，可以減少潛在顧客的不確定。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"spoilers","meaning":"劇透","examples":[{"en":"Spoilers may appear online before friends agree on a showtime.","zh":"朋友還未決定放映時間前，網上可能已出現劇透。"},{"en":"Spoilers are details that reveal important plot events before someone has watched the story.","zh":"劇透是在某人觀看故事前，提前揭露重要情節的資訊。"},{"en":"She avoided social media because she did not want spoilers for the final episode.","zh":"她避開社交媒體，因為不想看到大結局劇透。"},{"en":"Spoilers can reduce the excitement of seeing a film for the first time.","zh":"劇透可以減少第一次觀看電影時的驚喜。"},{"en":"Fast online discussion means audiences may learn key plot details before reaching the cinema.","zh":"網上討論速度很快，觀眾可能在去戲院前已知道重要情節。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"film clips","meaning":"電影片段","examples":[{"en":"Film clips are widely shared on social media.","zh":"電影片段在社交媒體被廣泛分享。"},{"en":"Film clips are short sections taken from a longer film.","zh":"電影片段是從較長電影中截取的一小部分。"},{"en":"A funny film clip may become popular online even among people who have not watched the movie.","zh":"有趣的電影片段可能在網上流行，即使很多人未看過整套電影。"},{"en":"Sharing film clips can create interest but can also reveal too much of the story.","zh":"分享電影片段可以引起興趣，但也可能透露太多劇情。"},{"en":"Social media allows fragments of films to circulate independently of the cinema experience.","zh":"社交媒體令電影的部分片段可以脫離戲院體驗獨立流傳。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Film clips and spoilers often appear on social media.","zh":"電影片段和劇透經常出現在社交媒體。"},{"en":"Social media consists of online platforms where people create, share and respond to content.","zh":"社交媒體是讓人製作、分享和回應內容的網上平台。"},{"en":"Young people often discover new films through social media.","zh":"年輕人經常透過社交媒體發現新電影。"},{"en":"Social media can promote cinema but also compete for the same audience attention.","zh":"社交媒體既可以宣傳戲院，也會爭奪同一批觀眾的注意力。"},{"en":"Its speed makes film discussion spread before groups have organised cinema visits.","zh":"它傳播速度很快，朋友還未安排好戲院活動，電影討論已經開始。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"agree on a showtime","meaning":"決定放映時間","examples":[{"en":"Friends may see spoilers before they agree on a showtime.","zh":"朋友可能還未決定放映時間便已看到劇透。"},{"en":"To agree on a showtime means for several people to decide together which screening time they will attend.","zh":"「agree on a showtime」表示幾個人一起決定參加哪個放映時段。"},{"en":"It took us half an hour to agree on a showtime that everyone could manage.","zh":"我們花了半小時才決定一個大家都可以的放映時間。"},{"en":"Busy schedules make it difficult for groups to agree on a showtime.","zh":"繁忙日程令一群朋友更難決定放映時間。"},{"en":"Home viewing avoids this coordination problem because each person can choose their own time.","zh":"在家觀看沒有這個協調問題，因為每個人可以自己選時間。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"showtime","meaning":"放映時間","examples":[{"en":"Friends need to agree on a showtime before buying tickets.","zh":"朋友買票前需要先決定放映時間。"},{"en":"A showtime is the scheduled time when a film screening begins.","zh":"放映時間是電影場次預定開始的時間。"},{"en":"The last showtime tonight is at 10:15 p.m.","zh":"今晚最後一場放映時間是晚上十時十五分。"},{"en":"Fixed showtimes reduce flexibility compared with streaming.","zh":"與串流相比，固定放映時間降低了彈性。"},{"en":"Cinemas can attract different audiences by offering convenient showtimes.","zh":"戲院可以透過提供方便的放映時間吸引不同觀眾。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, some cinemas offer a rather ordinary experience.","zh":"與此同時，一些戲院提供的體驗相當普通。"},{"en":"“Meanwhile” introduces another situation happening at the same time or another related point.","zh":"「meanwhile」用來帶出同時發生的另一情況或另一個相關重點。"},{"en":"Ticket prices are rising; meanwhile, streaming services are becoming more convenient.","zh":"電影票價上升；與此同時，串流服務變得更方便。"},{"en":"Audiences have more entertainment choices; meanwhile, some cinemas have changed very little.","zh":"觀眾有更多娛樂選擇；與此同時，一些戲院幾乎沒有改變。"},{"en":"The word helps connect two developments that should be considered together.","zh":"這個詞幫助連接兩個需要一起考慮的發展。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"rather ordinary experience","meaning":"相當普通的體驗","examples":[{"en":"Some cinemas offer a rather ordinary experience.","zh":"一些戲院提供相當普通的體驗。"},{"en":"A rather ordinary experience is one that feels quite normal and does not stand out as special.","zh":"相當普通的體驗是感覺很一般，沒有特別突出的經歷。"},{"en":"The restaurant looked attractive online but offered a rather ordinary experience.","zh":"那間餐廳網上看起來很吸引，但實際體驗相當普通。"},{"en":"If the cinema visit feels ordinary, audiences may not see why they should leave home.","zh":"如果戲院到訪感覺普通，觀眾可能不明白為甚麼要外出。"},{"en":"Experiences need distinctive features when customers have many alternatives.","zh":"當顧客有很多替代選擇，體驗便需要具有特色。"}],"source":"2015 Q7.pdf","sourcePage":7},{"front":"plain lobby","meaning":"平平無奇的大堂","examples":[{"en":"A plain lobby does not make the cinema feel special.","zh":"平平無奇的大堂不會令戲院感覺特別。"},{"en":"A plain lobby is a simple entrance or waiting area with little decoration or distinctive character.","zh":"平平無奇的大堂是裝飾不多、沒有明顯特色的簡單入口或等候區。"},{"en":"The hotel had a plain lobby with white walls and a few chairs.","zh":"那間酒店有一個白牆和幾張椅子的普通大堂。"},{"en":"A plain cinema lobby may feel no different from an ordinary shopping area.","zh":"平凡的戲院大堂可能與一般商場空間沒有分別。"},{"en":"Attractive public spaces can help turn waiting time into part of the experience.","zh":"吸引的公共空間可以令等候時間也成為體驗的一部分。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"similar snacks","meaning":"類似的小食","examples":[{"en":"Similar snacks make different cinemas feel the same.","zh":"類似的小食令不同戲院感覺一樣。"},{"en":"Similar snacks are food and drinks that are nearly identical across different places.","zh":"類似的小食是不同地方提供、內容幾乎相同的食物和飲品。"},{"en":"If every cinema sells similar snacks, customers have little reason to prefer one venue.","zh":"如果每間戲院都售賣類似小食，顧客便較少理由偏好某一間。"},{"en":"Special local food could make a cinema’s snack selection more distinctive.","zh":"特別的本地食物可以令戲院小食更有特色。"},{"en":"Small product differences can contribute to a stronger sense of identity.","zh":"細小的產品差異也可以建立更強的場所身份。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"little interaction","meaning":"甚少互動","examples":[{"en":"Some cinemas offer little interaction before or after the film.","zh":"一些戲院在電影前後甚少提供互動。"},{"en":"“Little interaction” means there are few chances for people to communicate, participate or engage with others.","zh":"「little interaction」表示人們幾乎沒有溝通、參與或與別人交流的機會。"},{"en":"An online lecture with little interaction can make students lose attention.","zh":"甚少互動的網上課堂可能令學生失去注意力。"},{"en":"Cinemas with little interaction may feel like places where people simply enter, watch and leave.","zh":"甚少互動的戲院可能只像人進去、看完、離開的地方。"},{"en":"Social activities can increase interaction and make an experience more memorable.","zh":"社交活動可以增加互動，令體驗更難忘。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"before or after the film","meaning":"電影前後","examples":[{"en":"Cinemas should create interaction before or after the film.","zh":"戲院應在電影前後創造互動。"},{"en":"“Before or after the film” refers to the periods immediately surrounding the screening itself.","zh":"「before or after the film」指電影放映本身前後的一段時間。"},{"en":"Audiences could join a short discussion after the film.","zh":"觀眾可以在電影後參加簡短討論。"},{"en":"Exhibitions before the film can build excitement for the story.","zh":"電影前的小型展覽可以增加觀眾對故事的期待。"},{"en":"Activities around the screening extend the cinema experience beyond the film itself.","zh":"放映前後的活動可以把戲院體驗延伸到電影本身以外。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"be seen merely as","meaning":"僅被視為","examples":[{"en":"If a cinema is seen merely as a bigger screen, it will lose its appeal.","zh":"如果戲院僅被視為一個較大的螢幕，它會失去吸引力。"},{"en":"To be seen merely as something means to be regarded as only that thing and nothing more valuable.","zh":"「be seen merely as」表示只被看成某一樣東西，而沒有更多價值。"},{"en":"A school should not be seen merely as a place for examinations.","zh":"學校不應僅被視為考試的地方。"},{"en":"If cinemas are seen merely as large screens, home televisions become strong substitutes.","zh":"如果戲院僅被視為大型螢幕，家中電視便會成為強力替代品。"},{"en":"Businesses need a broader identity when their basic function can be copied elsewhere.","zh":"當基本功能可以在其他地方複製，企業需要更廣泛的身份。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"bigger screen","meaning":"較大的螢幕","examples":[{"en":"A cinema should be more than a bigger screen.","zh":"戲院應該不只是較大的螢幕。"},{"en":"A bigger screen is simply a larger visual display than the one people already use at home or on devices.","zh":"較大的螢幕只是比人們家中或裝置上的顯示畫面更大。"},{"en":"A bigger screen can improve visual impact but does not automatically create a better overall experience.","zh":"較大的螢幕可以提升視覺效果，但不會自動創造更好的整體體驗。"},{"en":"Cinemas need atmosphere, sound and social value in addition to a bigger screen.","zh":"戲院除了較大的螢幕，還需要氣氛、音響和社交價值。"},{"en":"Physical size alone is a weak advantage when technology at home keeps improving.","zh":"當家庭科技不斷改善，單靠尺寸便是較弱的優勢。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"struggle to compete with","meaning":"難以與……競爭","examples":[{"en":"Cinemas struggle to compete with the screens people carry in their pockets.","zh":"戲院難以與人們隨身攜帶的螢幕競爭。"},{"en":"To struggle to compete with something means to find it difficult to remain attractive against a strong alternative.","zh":"「struggle to compete with」表示面對強大替代選擇時，很難保持吸引力。"},{"en":"Small shops struggle to compete with large online retailers on price.","zh":"小店在價格方面難以與大型網上零售商競爭。"},{"en":"Cinemas struggle to compete with phones on convenience and constant availability.","zh":"戲院在方便程度和隨時可用方面難以與手機競爭。"},{"en":"Strong competitors force businesses to focus on advantages that cannot easily be copied.","zh":"強大的競爭者會迫使企業集中發展難以被複製的優勢。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"carry in their pockets","meaning":"隨身攜帶","examples":[{"en":"People already carry screens in their pockets.","zh":"人們早已隨身攜帶螢幕。"},{"en":"To carry something in your pocket means to have it with you almost everywhere because it is small and portable.","zh":"把某物放在口袋隨身攜帶，表示它細小便攜，幾乎去哪裏都能帶着。"},{"en":"Most commuters carry a smartphone in their pockets or bags.","zh":"大部分通勤者都會把智能手機放在口袋或袋中隨身攜帶。"},{"en":"People can access entertainment anywhere because they carry powerful screens with them.","zh":"因為人們隨身帶着功能強大的螢幕，所以任何地方都能娛樂。"},{"en":"Portable technology makes entertainment available without planning a special trip.","zh":"便攜科技令娛樂不用特別安排外出也能得到。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, the cinema trip no longer feels special enough.","zh":"簡單來說，去戲院這件事已經不夠特別。"},{"en":"“Put simply” means expressed in a short and easy-to-understand way.","zh":"「put simply」表示用簡短而容易明白的方式說明。"},{"en":"Put simply, the project failed because costs were too high.","zh":"簡單來說，項目失敗是因為成本太高。"},{"en":"After discussing many details, “put simply” introduces the basic conclusion.","zh":"討論很多細節後，「put simply」可以帶出最基本的結論。"},{"en":"This phrase is useful when summarising a complex argument in plain language.","zh":"這個片語適合把複雜論點用簡單語言總結。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"losing not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"Cinemas are losing not because films are unimportant, but because the trip feels ordinary.","zh":"戲院失去觀眾，不是因為電影不重要，而是因為整趟外出感覺普通。"},{"en":"“Not because A, but because B” corrects one possible explanation and identifies another as the real cause.","zh":"「not because A, but because B」否定一個可能解釋，並指出另一個才是真正原因。"},{"en":"The shop closed not because customers disliked the products, but because the rent became too high.","zh":"商店結業不是因為顧客不喜歡產品，而是因為租金太高。"},{"en":"Cinema attendance falls not because stories have lost value, but because the outing offers too little extra value.","zh":"戲院入場人次下降，不是因為故事失去價值，而是因為外出體驗提供的額外價值太少。"},{"en":"This structure is useful for separating an assumed cause from the real one.","zh":"這個句式有助把假定原因與真正原因分開。"}],"source":"2015 Q7.pdf","sourcePage":8},{"front":"the trip itself","meaning":"這趟外出本身","examples":[{"en":"The trip itself no longer feels important enough.","zh":"這趟外出本身已不再感覺足夠重要。"},{"en":"“The trip itself” emphasises the entire act of going out to the cinema rather than the film being shown.","zh":"「the trip itself」強調整個外出去戲院的行動，而不只是所播放的電影。"},{"en":"The destination was interesting, but the trip itself was also enjoyable.","zh":"目的地很有趣，但旅程本身也很愉快。"},{"en":"Cinemas need to improve the trip itself through atmosphere, activities and social value.","zh":"戲院需要透過氣氛、活動和社交價值改善這趟外出本身。"},{"en":"When the main product is available at home, the journey and experience around it become more important.","zh":"當主要內容在家也能得到，周邊的旅程和體驗便變得更重要。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"no longer feels important enough","meaning":"不再感覺足夠重要","examples":[{"en":"The cinema trip no longer feels important enough.","zh":"去戲院這趟外出已不再感覺足夠重要。"},{"en":"“No longer feels important enough” means something has lost enough significance that people may not consider it worth extra effort.","zh":"「no longer feels important enough」表示某件事的重要性下降，以致人們未必覺得值得額外付出。"},{"en":"The event no longer felt important enough to justify travelling across the city.","zh":"那場活動已不再感覺重要到值得橫跨城市前往。"},{"en":"Cinema-going may decline when the outing no longer feels important enough to plan around.","zh":"當去戲院不再重要到值得特別安排，入場人次便可能下降。"},{"en":"People protect their limited time by choosing activities that feel meaningful or necessary.","zh":"人們會把有限時間留給感覺有意義或有必要的活動。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"suggestions","meaning":"建議","examples":[{"en":"The report gives suggestions for increasing cinema attendance.","zh":"報告提出增加戲院入場人次的建議。"},{"en":"Suggestions are ideas or recommendations about what could be done.","zh":"建議是關於可以採取甚麼行動的想法或推薦。"},{"en":"Students gave suggestions for improving the school library.","zh":"學生提出改善學校圖書館的建議。"},{"en":"Good report suggestions should respond directly to the causes identified earlier.","zh":"好的報告建議應直接回應之前找出的原因。"},{"en":"Practical suggestions are more useful when they explain how change could be achieved.","zh":"如果實際建議能說明如何實行改變，便會更有用。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"make each visit feel like an event","meaning":"令每次到訪都像一場活動","examples":[{"en":"Cinemas should make each visit feel like an event.","zh":"戲院應令每次到訪都像一場活動。"},{"en":"To make each visit feel like an event means to make it seem special, planned and worth remembering rather than routine.","zh":"令每次到訪都像一場活動，表示令它顯得特別、有安排，而且值得記住，而不是例行。"},{"en":"Live music in the lobby could make a festival screening feel like an event.","zh":"大堂現場音樂可以令電影節放映更像一場活動。"},{"en":"Themed activities can make a normal cinema visit feel more special.","zh":"主題活動可以令普通戲院到訪變得更特別。"},{"en":"People are more willing to leave home when an outing feels unique rather than ordinary.","zh":"當外出感覺獨特而不普通，人們會更願意離開家。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"not merely about","meaning":"不只是關於","examples":[{"en":"Going to the cinema should not be merely about watching a film.","zh":"去戲院不應只是關於看一套電影。"},{"en":"“Not merely about” means something should involve more than one obvious purpose or activity.","zh":"「not merely about」表示某件事不應只有一個最明顯的目的或活動。"},{"en":"School is not merely about examination results.","zh":"學校不只是關於考試成績。"},{"en":"Cinema-going should include atmosphere and social participation, not merely the film.","zh":"入戲院應包括氣氛和社交參與，而不只是電影本身。"},{"en":"This phrase introduces deeper value beyond the most basic function.","zh":"這個片語用來帶出基本功能以外的更深價值。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"rather","meaning":"相反；更準確地說","examples":[{"en":"Rather, it should be about entering a shared world.","zh":"相反，更準確地說，它應該是關於進入一個共享世界。"},{"en":"“Rather” introduces a more accurate or preferred alternative to the idea just rejected.","zh":"「rather」用來帶出比剛才否定的想法更準確或更理想的另一個選擇。"},{"en":"The programme should not punish weak students; rather, it should give them more support.","zh":"這個計劃不應懲罰能力較弱的學生；相反，應給他們更多支援。"},{"en":"Cinema-going should not be passive; rather, it should create connection and participation.","zh":"入戲院不應只是被動觀看；相反，應創造連結和參與。"},{"en":"This word is useful for replacing one idea with a stronger alternative.","zh":"這個詞適合用一個更強的替代想法取代前面的觀點。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"enter a shared world","meaning":"進入一個共享世界","examples":[{"en":"Cinema-going should feel like entering a shared world.","zh":"入戲院看電影應該感覺像進入一個共享世界。"},{"en":"To enter a shared world means to join an experience that many people enjoy and participate in together.","zh":"進入一個共享世界表示加入很多人一起享受和參與的共同體驗。"},{"en":"A concert can feel like entering a shared world of music and excitement.","zh":"演唱會可以令人感覺進入一個充滿音樂和興奮氣氛的共享世界。"},{"en":"A themed cinema event can make audiences feel connected to the film and one another.","zh":"主題戲院活動可以令觀眾與電影和其他人產生連結。"},{"en":"Shared atmosphere is something private home viewing cannot fully reproduce.","zh":"共同氣氛是在家私人觀看很難完全複製的東西。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"to achieve this","meaning":"為了做到這一點","examples":[{"en":"To achieve this, cinemas could organise themed screenings.","zh":"為了做到這一點，戲院可以舉辦主題放映。"},{"en":"“To achieve this” introduces an action designed to reach the goal just mentioned.","zh":"「to achieve this」用來帶出為達成剛才所說目標而採取的行動。"},{"en":"The school wants to reduce waste; to achieve this, it will add more recycling bins.","zh":"學校想減少廢物；為了做到這一點，會增加回收箱。"},{"en":"Cinemas want to create memorable experiences; to achieve this, they need extra activities.","zh":"戲院想創造難忘體驗；為了做到這一點，需要加入額外活動。"},{"en":"This phrase clearly connects a goal with a proposed method.","zh":"這個片語清楚連接目標和建議方法。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"organise themed screenings","meaning":"舉辦主題放映","examples":[{"en":"Cinemas could organise themed screenings for special film events.","zh":"戲院可以為特別電影活動舉辦主題放映。"},{"en":"To organise themed screenings means to arrange film sessions built around a particular topic, series, director or style.","zh":"舉辦主題放映是指圍繞某個題材、系列、導演或風格安排電影場次。"},{"en":"A cinema could organise themed screenings of classic horror films in October.","zh":"戲院可以在十月舉辦經典恐怖片主題放映。"},{"en":"Themed screenings give audiences a stronger reason to attend together.","zh":"主題放映給觀眾更強理由一起到場。"},{"en":"Organised events can make older films feel fresh and socially relevant again.","zh":"有組織的活動可以令舊電影再次顯得新鮮而有社交意義。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"themed screenings","meaning":"主題放映","examples":[{"en":"Themed screenings can make a cinema visit more memorable.","zh":"主題放映可以令戲院到訪更難忘。"},{"en":"Themed screenings are film showings connected by a particular idea, genre, person or occasion.","zh":"主題放映是由某個概念、類型、人物或場合連繫起來的電影放映。"},{"en":"A science-fiction week could include themed screenings of famous space films.","zh":"科幻電影周可以包括多套著名太空電影的主題放映。"},{"en":"Decorations and discussions can strengthen themed screenings.","zh":"裝飾和討論可以加強主題放映的效果。"},{"en":"A theme gives separate film visits a stronger sense of identity and occasion.","zh":"主題可以令不同場次有更強的身份和活動感。"}],"source":"2015 Q7.pdf","sourcePage":9},{"front":"director talks","meaning":"導演分享會","examples":[{"en":"Director talks can help audiences understand films more deeply.","zh":"導演分享會可以幫助觀眾更深入理解電影。"},{"en":"Director talks are sessions where film directors discuss their work, ideas and creative decisions.","zh":"導演分享會是電影導演討論作品、構思和創作決定的活動。"},{"en":"The audience asked questions during the director talk after the screening.","zh":"放映後的導演分享會中，觀眾向導演提問。"},{"en":"Director talks can reveal why certain scenes or camera choices were made.","zh":"導演分享會可以解釋某些場景或鏡頭選擇背後的原因。"},{"en":"Meeting creators gives cinema audiences something unavailable from simply streaming the film.","zh":"與創作者交流，能提供單純串流觀看得不到的體驗。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"audience discussions","meaning":"觀眾討論","examples":[{"en":"Audience discussions can create interaction after a film.","zh":"觀眾討論可以在電影後創造互動。"},{"en":"Audience discussions are conversations in which viewers share opinions and interpretations after watching.","zh":"觀眾討論是觀看後由觀眾分享意見和理解的對話。"},{"en":"The cinema organised an audience discussion about the film’s ending.","zh":"戲院就電影結局舉辦了一場觀眾討論。"},{"en":"Different viewpoints can help people notice details they missed themselves.","zh":"不同觀點可以幫助人發現自己原本錯過的細節。"},{"en":"Discussion turns a private reaction into a shared social experience.","zh":"討論把私人感受變成共同社交體驗。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"costume nights","meaning":"服裝主題夜","examples":[{"en":"Costume nights can make cinema-going more enjoyable.","zh":"服裝主題夜可以令入戲院看電影更有趣。"},{"en":"Costume nights are special events where audiences are encouraged to dress as characters or according to a theme.","zh":"服裝主題夜是鼓勵觀眾打扮成角色或按主題穿着的特別活動。"},{"en":"Fans wore superhero costumes during the costume night.","zh":"粉絲在服裝主題夜穿上超級英雄服裝。"},{"en":"Costume nights create photographs, conversation and shared excitement before the film.","zh":"服裝主題夜在電影開始前創造拍照、交流和共同興奮感。"},{"en":"Participatory events can make audiences feel part of the film culture rather than passive customers.","zh":"參與式活動可以令觀眾覺得自己是電影文化的一部分，而不只是被動顧客。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"small exhibitions","meaning":"小型展覽","examples":[{"en":"Small exhibitions about film-making could attract audiences.","zh":"關於電影製作的小型展覽可以吸引觀眾。"},{"en":"Small exhibitions are limited displays of objects, images or information organised around a topic.","zh":"小型展覽是圍繞某個主題展示少量物件、圖片或資料的活動。"},{"en":"The cinema lobby hosted a small exhibition of old film posters.","zh":"戲院大堂舉辦了一個舊電影海報小型展覽。"},{"en":"A small exhibition can give audiences something to explore before the screening.","zh":"小型展覽可以讓觀眾在放映前有東西參觀。"},{"en":"Even a modest display can make a venue feel more cultural and distinctive.","zh":"即使規模不大，展示也能令場所更有文化感和特色。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"film-making","meaning":"電影製作","examples":[{"en":"An exhibition about film-making can make the cinema trip more educational.","zh":"關於電影製作的展覽可以令戲院之行更有教育意義。"},{"en":"Film-making is the process of creating films, including writing, directing, acting, filming, editing and sound.","zh":"電影製作是創作電影的過程，包括編劇、導演、演戲、拍攝、剪接和聲音。"},{"en":"Students learned about film-making by watching how a scene was shot.","zh":"學生透過觀看場景如何拍攝來學習電影製作。"},{"en":"Exhibitions about film-making can show audiences the work behind the final movie.","zh":"電影製作展覽可以讓觀眾看到成品背後的工作。"},{"en":"Understanding production can deepen appreciation of what appears on screen.","zh":"了解製作過程可以加深人們對銀幕內容的欣賞。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"a week of Hong Kong films","meaning":"香港電影周","examples":[{"en":"A week of Hong Kong films could celebrate local cinema.","zh":"香港電影周可以慶祝本地電影。"},{"en":"“A week of Hong Kong films” means a seven-day programme focusing on movies made in or strongly connected with Hong Kong.","zh":"香港電影周是為期七天、集中播放香港製作或與香港密切相關電影的活動。"},{"en":"The cinema organised a week of Hong Kong films from different decades.","zh":"戲院舉辦了一個播放不同年代作品的香港電影周。"},{"en":"Such a programme could introduce younger audiences to local classics.","zh":"這類活動可以向年輕觀眾介紹本地經典作品。"},{"en":"Film weeks can create a clear theme that encourages repeated visits.","zh":"電影周有清楚主題，可以鼓勵觀眾多次到訪。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"display old posters","meaning":"展示舊海報","examples":[{"en":"The lobby could display old posters during a Hong Kong film week.","zh":"香港電影周期間，大堂可以展示舊海報。"},{"en":"To display old posters means to put historical promotional images where visitors can see them.","zh":"展示舊海報是指把歷史宣傳圖片放在訪客可以看見的地方。"},{"en":"The museum displayed old posters from famous concerts.","zh":"博物館展示著名演唱會的舊海報。"},{"en":"Old film posters can help create atmosphere and remind audiences of local cinema history.","zh":"舊電影海報可以營造氣氛，並提醒觀眾本地電影歷史。"},{"en":"Displays turn unused lobby space into part of the cultural experience.","zh":"展示可以把原本普通的大堂空間變成文化體驗的一部分。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"invite viewers to vote for","meaning":"邀請觀眾投票選出","examples":[{"en":"Cinemas could invite viewers to vote for their favourite classic.","zh":"戲院可以邀請觀眾投票選出最喜愛的經典作品。"},{"en":"To invite viewers to vote for something means to ask audiences to choose their preferred option through voting.","zh":"「invite viewers to vote for」表示請觀眾透過投票選擇最喜歡的選項。"},{"en":"The school invited students to vote for the next book club title.","zh":"學校邀請學生投票選出下一本讀書會書籍。"},{"en":"Letting viewers vote gives them influence over future screenings.","zh":"讓觀眾投票可以令他們對未來放映內容有影響力。"},{"en":"Participation increases when audiences feel their choices affect what happens next.","zh":"當觀眾覺得自己的選擇會影響之後發生甚麼，參與度會增加。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"favourite classic","meaning":"最喜愛的經典作品","examples":[{"en":"Viewers could vote for their favourite classic.","zh":"觀眾可以投票選出最喜愛的經典作品。"},{"en":"A favourite classic is an older work that someone especially likes and considers enduring or important.","zh":"最喜愛的經典作品是某人特別喜歡，而且認為歷久不衰或重要的舊作品。"},{"en":"My favourite classic is a film I have watched many times.","zh":"我最喜愛的經典電影是一套已看過很多次的作品。"},{"en":"Re-screening audience favourites can attract people who want to see them on a large screen again.","zh":"重映觀眾喜歡的經典，可以吸引想再次在大銀幕觀看的人。"},{"en":"Classics can connect older memories with new audiences.","zh":"經典作品可以把舊回憶與新觀眾連接起來。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"these activities","meaning":"這些活動","examples":[{"en":"These activities would offer something beyond home viewing.","zh":"這些活動可以提供在家觀看以外的東西。"},{"en":"“These activities” refers to the events and programmes just mentioned, such as talks, discussions and exhibitions.","zh":"「these activities」指前面提到的分享會、討論和展覽等活動。"},{"en":"These activities give visitors more reasons to stay after the main event.","zh":"這些活動讓訪客在主要活動後有更多理由留下來。"},{"en":"Cinema activities add social and cultural value around the film itself.","zh":"戲院活動為電影本身增加社交和文化價值。"},{"en":"Referring to several ideas as “these activities” helps connect them in a report.","zh":"在報告中用「these activities」可以把前面幾個構思連接起來。"}],"source":"2015 Q7.pdf","sourcePage":10},{"front":"give audiences something","meaning":"給觀眾一些……","examples":[{"en":"These activities give audiences something they cannot get at home.","zh":"這些活動給觀眾一些在家得不到的東西。"},{"en":"To give audiences something means to provide viewers with a benefit, experience or opportunity.","zh":"「give audiences something」表示向觀眾提供某種好處、體驗或機會。"},{"en":"Live questions give audiences something more personal than a recorded video.","zh":"現場提問給觀眾一些錄影影片沒有的個人互動。"},{"en":"Discussions give cinema audiences direct social interaction.","zh":"討論給戲院觀眾直接社交交流。"},{"en":"A strong service provides customers with benefits that alternatives cannot easily copy.","zh":"優秀服務會提供替代選擇難以複製的好處。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"cannot get from a sofa at home","meaning":"在家中梳化上得不到的","examples":[{"en":"Audiences would get something they cannot get from a sofa at home.","zh":"觀眾可以得到一些在家中梳化上得不到的東西。"},{"en":"“Cannot get from a sofa at home” means unavailable through private, comfortable home viewing.","zh":"「cannot get from a sofa at home」表示單靠舒適的私人家庭觀看無法得到。"},{"en":"Meeting a director is something viewers cannot get simply from a sofa at home.","zh":"與導演見面是單坐在家中梳化上得不到的體驗。"},{"en":"Shared laughter with a large audience cannot be reproduced in exactly the same way at home.","zh":"與大量觀眾一起笑的感覺，很難在家完全複製。"},{"en":"Cinemas should focus on benefits that require physical presence and other people.","zh":"戲院應集中提供需要親身到場和其他人共同參與的好處。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, the activities turn viewing into participation.","zh":"更重要的是，這些活動把觀看變成參與。"},{"en":"“More importantly” introduces a point considered more significant than the one just mentioned.","zh":"「more importantly」用來帶出比剛才所說更加重要的重點。"},{"en":"The new bus is cheaper and, more importantly, more reliable.","zh":"新巴士較便宜；更重要的是，它更可靠。"},{"en":"Cinema events may be entertaining; more importantly, they create involvement.","zh":"戲院活動可以有娛樂性；更重要的是，它們創造參與感。"},{"en":"This phrase helps writers rank ideas by importance.","zh":"這個片語幫助作者按重要性排列觀點。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"turn passive viewing into","meaning":"將被動觀看變成","examples":[{"en":"The activities would turn passive viewing into social participation.","zh":"這些活動會將被動觀看變成社交參與。"},{"en":"To turn passive viewing into something means to change simple watching into a more active form of involvement.","zh":"「turn passive viewing into」表示把單純觀看改變成更主動的參與形式。"},{"en":"Questions can turn passive listening into classroom discussion.","zh":"提問可以把被動聆聽變成課堂討論。"},{"en":"Voting and talks turn cinema audiences from silent viewers into participants.","zh":"投票和分享會把沉默觀眾由觀看者變成參與者。"},{"en":"Active involvement often creates stronger memories than simply receiving information.","zh":"主動參與通常比單純接收資訊更容易留下深刻記憶。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"passive viewing","meaning":"被動觀看","examples":[{"en":"Cinemas should turn passive viewing into social participation.","zh":"戲院應把被動觀看變成社交參與。"},{"en":"Passive viewing means watching content without actively responding, discussing or taking part.","zh":"被動觀看是只看內容，而沒有主動回應、討論或參與。"},{"en":"Watching television silently alone is usually a form of passive viewing.","zh":"一個人安靜看電視通常是一種被動觀看。"},{"en":"Traditional cinema screenings often involve passive viewing during the film.","zh":"傳統戲院放映在電影期間通常主要是被動觀看。"},{"en":"Activities before and after the screening can add interaction around passive viewing.","zh":"電影前後活動可以在被動觀看之外增加互動。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"social participation","meaning":"社交參與","examples":[{"en":"Audience discussions can encourage social participation.","zh":"觀眾討論可以鼓勵社交參與。"},{"en":"Social participation means actively joining activities and interacting with other people.","zh":"社交參與是主動加入活動並與其他人互動。"},{"en":"Community festivals encourage social participation by inviting residents to help and perform.","zh":"社區節日邀請居民幫忙和表演，鼓勵社交參與。"},{"en":"Cinema discussions create social participation because viewers share opinions.","zh":"戲院討論讓觀眾分享意見，因此創造社交參與。"},{"en":"Social participation can make entertainment feel communal rather than private.","zh":"社交參與可以令娛樂感覺像共同活動，而不是私人活動。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"improve affordability","meaning":"提高可負擔性","examples":[{"en":"Cinemas should improve affordability without confusing customers.","zh":"戲院應提高可負擔性，同時不要令顧客感到混亂。"},{"en":"To improve affordability means to make a product or service easier for people to pay for.","zh":"提高可負擔性是指令產品或服務更容易由人們負擔。"},{"en":"Student discounts improve affordability for young people.","zh":"學生優惠可以提高年輕人的可負擔性。"},{"en":"Family packages can improve affordability without lowering every ticket price.","zh":"家庭套票可以提高可負擔性，而不用所有票價都下降。"},{"en":"Better affordability can encourage more frequent participation among price-sensitive groups.","zh":"較高可負擔性可以鼓勵較在意價格的群體更常參與。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"affordability","meaning":"可負擔性","examples":[{"en":"Affordability is important for attracting young moviegoers.","zh":"可負擔性對吸引年輕電影觀眾很重要。"},{"en":"Affordability is the degree to which people can reasonably pay for something without excessive financial pressure.","zh":"可負擔性是指人們能否在不造成過大經濟壓力下合理支付某項東西。"},{"en":"Housing affordability is a major concern in expensive cities.","zh":"在昂貴城市，住屋可負擔性是一大問題。"},{"en":"Cinema affordability depends on ticket prices as well as transport and food costs.","zh":"戲院的可負擔性不只取決於票價，也包括交通和食物成本。"},{"en":"A product may be desirable but still fail if customers cannot comfortably afford it.","zh":"一件產品即使很吸引，如果顧客無法輕鬆負擔，也可能失敗。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"without making discounts confusing","meaning":"在不令優惠混亂的情況下","examples":[{"en":"Cinemas should offer discounts without making them confusing.","zh":"戲院應提供優惠，同時不要令優惠變得混亂。"},{"en":"This means lower-price offers should remain simple and easy for customers to understand.","zh":"這表示較低價格的優惠應保持簡單，讓顧客容易理解。"},{"en":"The shop simplified its promotion so customers could see the final price immediately.","zh":"商店簡化促銷，讓顧客立即看見最終價格。"},{"en":"Too many conditions can make discounts frustrating rather than attractive.","zh":"太多條件可以令優惠令人煩躁，而不是吸引。"},{"en":"A good offer should reduce cost without increasing mental effort.","zh":"好的優惠應降低成本，而不是增加理解它的心力。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"student tickets","meaning":"學生票","examples":[{"en":"Student tickets on weekday evenings could attract young viewers.","zh":"平日晚上提供學生票可以吸引年輕觀眾。"},{"en":"Student tickets are discounted admission tickets available to people who can prove they are students.","zh":"學生票是供能證明學生身份的人購買的優惠入場票。"},{"en":"The museum offers student tickets at half the adult price.","zh":"博物館學生票價格是成人票的一半。"},{"en":"Cheaper student tickets can make cinema-going more realistic for teenagers.","zh":"較便宜學生票可以令青少年更負擔得起入戲院看電影。"},{"en":"Targeted pricing can attract groups with limited spending power.","zh":"針對性定價可以吸引消費能力較有限的群體。"}],"source":"2015 Q7.pdf","sourcePage":11},{"front":"weekday evenings","meaning":"平日晚上","examples":[{"en":"Student tickets could be offered on weekday evenings.","zh":"戲院可以在平日晚上提供學生票。"},{"en":"Weekday evenings are the evenings from Monday to Friday rather than weekends.","zh":"平日晚上是星期一至星期五的晚上，而不是週末。"},{"en":"Restaurants are often quieter on weekday evenings than on Saturdays.","zh":"餐廳在平日晚上通常比星期六安靜。"},{"en":"Discounting weekday evenings can help cinemas fill seats during less busy periods.","zh":"平日晚上提供優惠，可以幫助戲院在較不繁忙時段增加入座率。"},{"en":"Different prices at different times can better match demand.","zh":"不同時間採用不同價格，可以更配合需求。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"family packages","meaning":"家庭套票","examples":[{"en":"Family packages could make cinema visits more affordable.","zh":"家庭套票可以令戲院到訪更可負擔。"},{"en":"Family packages are combined offers that give better value when several family members buy or attend together.","zh":"家庭套票是幾位家庭成員一起購買或參與時提供較優惠價值的組合。"},{"en":"The theme park offers family packages for two adults and two children.","zh":"主題公園提供兩位成人和兩位兒童的家庭套票。"},{"en":"Cinema family packages could include several tickets and snacks at a lower total price.","zh":"戲院家庭套票可以用較低總價包括幾張票和小食。"},{"en":"Package deals can reduce the high cost faced by larger groups.","zh":"套票可以降低較大群體面對的總成本。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"bring-a-friend offers","meaning":"帶朋友同行優惠","examples":[{"en":"Bring-a-friend offers could encourage people to visit cinemas together.","zh":"帶朋友同行優惠可以鼓勵人們一起去戲院。"},{"en":"Bring-a-friend offers are promotions that give a benefit when one customer attends with another person.","zh":"帶朋友同行優惠是顧客與另一個人一起參與時可得到好處的促銷。"},{"en":"The gym offered a free guest pass as part of a bring-a-friend offer.","zh":"健身室以免費賓客入場券作為帶朋友同行優惠。"},{"en":"Cinema bring-a-friend offers can support both affordability and social participation.","zh":"戲院帶朋友同行優惠可以同時改善可負擔性和社交參與。"},{"en":"Discounts linked to companionship encourage customers to treat the outing as a shared activity.","zh":"與同行朋友掛鈎的優惠會鼓勵顧客把外出視為共同活動。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"combined coupons","meaning":"聯合優惠券","examples":[{"en":"Combined coupons with nearby restaurants could make the evening better value.","zh":"與附近餐廳合作的聯合優惠券可以令整個晚上更划算。"},{"en":"Combined coupons are discount offers that link two or more businesses or purchases together.","zh":"聯合優惠券是把兩間或以上商戶或消費項目連接起來的折扣優惠。"},{"en":"The mall offered combined coupons for a meal and a cinema ticket.","zh":"商場提供一餐加電影票的聯合優惠券。"},{"en":"Combined coupons can make a whole evening cheaper rather than reducing only the ticket price.","zh":"聯合優惠券可以降低整晚總成本，而不只是票價。"},{"en":"Partnerships between nearby businesses can create extra value for customers.","zh":"附近商戶合作可以為顧客創造額外價值。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"nearby restaurants","meaning":"附近餐廳","examples":[{"en":"Cinemas could offer coupons with nearby restaurants.","zh":"戲院可以與附近餐廳合作提供優惠券。"},{"en":"Nearby restaurants are eating places located close enough to reach conveniently from the cinema.","zh":"附近餐廳是距離戲院很近、方便前往的食肆。"},{"en":"We had dinner at one of the nearby restaurants before the film.","zh":"我們看電影前在其中一間附近餐廳吃晚飯。"},{"en":"Cinema partnerships with nearby restaurants can turn a screening into a fuller evening out.","zh":"戲院與附近餐廳合作，可以把單純放映變成更完整的晚間活動。"},{"en":"Local businesses can benefit when they encourage customers to visit one another.","zh":"本地商戶互相鼓勵顧客到訪，可以共同受益。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"reduce the psychological barrier","meaning":"降低心理門檻","examples":[{"en":"Discounts could reduce the psychological barrier to going out.","zh":"優惠可以降低外出消遣的心理門檻。"},{"en":"To reduce the psychological barrier means to make a choice feel mentally easier and less difficult to justify.","zh":"降低心理門檻表示令某個選擇在心理上更容易接受和更容易說服自己去做。"},{"en":"A free trial can reduce the psychological barrier to trying an unfamiliar service.","zh":"免費試用可以降低嘗試陌生服務的心理門檻。"},{"en":"Lower ticket prices may make a cinema visit feel less risky or wasteful.","zh":"較低票價可以令去戲院感覺風險較低、沒有那麼浪費。"},{"en":"People sometimes avoid an activity because of how costly it feels, not only because they literally cannot afford it.","zh":"人有時避免某項活動，是因為它感覺太貴，而不一定是真的完全負擔不起。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"psychological barrier","meaning":"心理門檻","examples":[{"en":"High prices create a psychological barrier to cinema-going.","zh":"高票價會為入戲院看電影建立心理門檻。"},{"en":"A psychological barrier is a mental obstacle that makes someone reluctant to take an action.","zh":"心理門檻是令某人不願採取行動的心理障礙。"},{"en":"Fear of embarrassment can be a psychological barrier to public speaking.","zh":"害怕尷尬可以成為公開演說的心理門檻。"},{"en":"Even affordable tickets may feel unattractive if customers believe cinema-going is poor value.","zh":"即使票價負擔得起，如果顧客覺得不划算，仍可能不想去。"},{"en":"Psychological barriers affect decisions even when no physical barrier exists.","zh":"即使沒有實際障礙，心理門檻仍會影響決定。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"going out","meaning":"外出消遣","examples":[{"en":"Affordable tickets make going out feel easier.","zh":"負擔得起的票價令外出消遣感覺更容易。"},{"en":"Going out means leaving home for leisure, social activity or another purpose.","zh":"外出消遣表示離開家中進行休閒、社交或其他活動。"},{"en":"We are going out for dinner and a film tonight.","zh":"我們今晚會外出吃晚飯和看電影。"},{"en":"Tired people may choose home entertainment instead of going out.","zh":"疲倦的人可能選擇家庭娛樂，而不是外出。"},{"en":"Lower costs and attractive experiences can make going out feel more worthwhile.","zh":"較低成本和吸引體驗可以令外出更值得。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"dynamic pricing","meaning":"動態定價","examples":[{"en":"Dynamic pricing could be used for older films.","zh":"較舊電影可以使用動態定價。"},{"en":"Dynamic pricing is a system in which prices change according to demand, time, availability or other conditions.","zh":"動態定價是價格按需求、時間、供應或其他條件而改變的制度。"},{"en":"Airlines commonly use dynamic pricing for tickets.","zh":"航空公司常對機票使用動態定價。"},{"en":"Cinemas could charge less for quiet screenings and more for highly demanded ones.","zh":"戲院可以對較冷門場次收較低價格，而熱門場次收較高價格。"},{"en":"Dynamic pricing can improve seat usage if customers understand the system clearly.","zh":"如果顧客清楚明白制度，動態定價可以改善座位使用率。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"older films","meaning":"較舊的電影","examples":[{"en":"Older films could be shown at lower prices.","zh":"較舊的電影可以用較低價格放映。"},{"en":"Older films are movies released some time ago rather than current new releases.","zh":"較舊的電影是已上映一段時間，而不是最新上映的作品。"},{"en":"The cinema re-screened older films during its anniversary month.","zh":"戲院在周年月份重映較舊電影。"},{"en":"Lower prices can attract audiences to older films they missed the first time.","zh":"較低價格可以吸引觀眾觀看第一次錯過的舊片。"},{"en":"Re-screening older films can make better use of quiet periods and celebrate film history.","zh":"重映舊電影既可善用冷門時段，也能慶祝電影歷史。"}],"source":"2015 Q7.pdf","sourcePage":12},{"front":"less popular showtimes","meaning":"較冷門的放映時段","examples":[{"en":"Dynamic pricing could help fill less popular showtimes.","zh":"動態定價可以幫助提高較冷門放映時段的入座率。"},{"en":"Less popular showtimes are screening times that usually attract fewer customers.","zh":"較冷門的放映時段是通常吸引較少顧客的電影場次。"},{"en":"Early afternoon screenings may be less popular showtimes on working days.","zh":"工作日早下午場可能是較冷門的放映時段。"},{"en":"Lower prices can encourage flexible customers to choose less popular showtimes.","zh":"較低票價可以鼓勵時間較有彈性的顧客選擇冷門時段。"},{"en":"Moving some demand away from peak periods can improve overall seat usage.","zh":"把部分需求由繁忙時段移走，可以改善整體座位使用。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"cut prices blindly","meaning":"盲目減價","examples":[{"en":"Cinemas should not simply cut prices blindly.","zh":"戲院不應只是盲目減價。"},{"en":"To cut prices blindly means to reduce prices without a clear strategy or understanding of the consequences.","zh":"盲目減價是指沒有清楚策略或不了解後果便降低價格。"},{"en":"A business that cuts prices blindly may increase sales but lose too much profit.","zh":"企業如果盲目減價，可能增加銷量卻損失太多利潤。"},{"en":"Cinemas should target discounts rather than lowering every ticket without thought.","zh":"戲院應針對特定群體提供優惠，而不是毫無考慮地降低所有票價。"},{"en":"Good pricing should solve specific problems rather than treat low prices as the only answer.","zh":"良好定價應解決具體問題，而不是把低價當成唯一答案。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"make the evening worth paying for","meaning":"令這個晚上值得付款","examples":[{"en":"Cinemas should make the evening worth paying for.","zh":"戲院應令這個晚上值得付款。"},{"en":"To make the evening worth paying for means to provide enough value and enjoyment to justify the total cost.","zh":"令這個晚上值得付款，表示提供足夠價值和享受，令人覺得總成本合理。"},{"en":"Good food and live music made the expensive dinner worth paying for.","zh":"好食物和現場音樂令那頓昂貴晚餐值得付款。"},{"en":"Cinemas can justify ticket prices by improving the whole outing rather than only the screen.","zh":"戲院可以透過改善整個外出體驗，而不只是螢幕，令票價更合理。"},{"en":"Customers accept higher prices more easily when the experience feels distinctive and satisfying.","zh":"當體驗有特色而令人滿意，顧客會較容易接受較高價格。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"certain evenings","meaning":"某些晚上","examples":[{"en":"Students may return if certain evenings are reliably affordable.","zh":"如果某些晚上穩定地負擔得起，學生可能會回來。"},{"en":"“Certain evenings” means particular selected evenings rather than every evening.","zh":"「certain evenings」表示特定選出的晚上，而不是每一晚。"},{"en":"The restaurant offers student discounts on certain evenings each week.","zh":"那間餐廳每星期某些晚上提供學生優惠。"},{"en":"Cinemas could make certain evenings especially attractive to young customers.","zh":"戲院可以令某些晚上特別吸引年輕顧客。"},{"en":"Predictable special periods help people plan habits around them.","zh":"固定的優惠時段可以幫助人圍繞它建立習慣。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"reliably affordable","meaning":"穩定地負擔得起","examples":[{"en":"Certain evenings should be reliably affordable for students.","zh":"某些晚上對學生而言應穩定地負擔得起。"},{"en":"“Reliably affordable” means consistently low enough in cost that people can depend on being able to pay.","zh":"「reliably affordable」表示價格持續維持在可負擔水平，讓人可以放心預計付得起。"},{"en":"Public transport should remain reliably affordable for low-income workers.","zh":"公共交通對低收入工人應保持穩定地負擔得起。"},{"en":"Students may return regularly if they know Tuesday tickets are reliably affordable.","zh":"如果學生知道星期二票價一直負擔得起，可能會定期回來。"},{"en":"Predictable affordability can be more useful than occasional surprise discounts.","zh":"可預測的可負擔性可能比偶爾出現的驚喜折扣更有用。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"be more likely to","meaning":"更有可能","examples":[{"en":"Students are more likely to return if prices are predictable.","zh":"如果價格可以預測，學生會更有可能再次回來。"},{"en":"To be more likely to do something means to have a greater chance of doing it.","zh":"「be more likely to」表示做某件事的可能性較高。"},{"en":"People are more likely to exercise when the gym is close to home.","zh":"如果健身室離家很近，人們更有可能做運動。"},{"en":"Customers are more likely to return when they know what price to expect.","zh":"當顧客知道預期價格，他們更有可能再次光顧。"},{"en":"Removing uncertainty can increase the chance that a behaviour is repeated.","zh":"減少不確定性可以增加某種行為重複發生的可能。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"develop a habit of returning","meaning":"培養回來的習慣","examples":[{"en":"Affordable evenings may help students develop a habit of returning.","zh":"負擔得起的晚上可能幫助學生培養回來的習慣。"},{"en":"To develop a habit of returning means to begin coming back regularly until it becomes a normal routine.","zh":"培養回來的習慣表示開始定期再次到訪，直到變成正常習慣。"},{"en":"Weekly library visits helped the children develop a habit of returning for new books.","zh":"每星期去圖書館令孩子養成回去借新書的習慣。"},{"en":"Reliable student nights could make cinema-going a regular social habit.","zh":"穩定的學生優惠夜可以令入戲院成為固定社交習慣。"},{"en":"Repeated positive experiences are more likely to build long-term behaviour than one-off promotions.","zh":"反覆良好體驗比一次性促銷更容易建立長期行為。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"work together","meaning":"合作","examples":[{"en":"Schools and cinemas should work together.","zh":"學校和戲院應該合作。"},{"en":"To work together means to cooperate towards a shared goal.","zh":"「work together」表示為共同目標而合作。"},{"en":"Teachers and parents need to work together to support struggling students.","zh":"老師和家長需要合作支援學習有困難的學生。"},{"en":"Schools and cinemas can work together on educational screenings.","zh":"學校和戲院可以在教育放映方面合作。"},{"en":"Cooperation allows different organisations to contribute different strengths.","zh":"合作讓不同機構可以貢獻各自的長處。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"rebuild young people’s interest in","meaning":"重建年輕人對……的興趣","examples":[{"en":"Schools and cinemas should rebuild young people’s interest in films.","zh":"學校和戲院應重建年輕人對電影的興趣。"},{"en":"To rebuild interest in something means to restore enthusiasm that has become weaker.","zh":"重建對某事的興趣表示恢復已經減弱的熱情。"},{"en":"The museum launched workshops to rebuild teenagers’ interest in local history.","zh":"博物館推出工作坊，重建青少年對本地歷史的興趣。"},{"en":"School screenings may rebuild young people’s interest in cinema as a shared experience.","zh":"學校專場放映可以重建年輕人對戲院共同觀看體驗的興趣。"},{"en":"Interest can return when people are given fresh and meaningful ways to engage with a subject.","zh":"當人們有新鮮而有意義的參與方法，興趣可以重新建立。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"part of popular culture","meaning":"流行文化的一部分","examples":[{"en":"Films are part of popular culture.","zh":"電影是流行文化的一部分。"},{"en":"Something that is part of popular culture belongs to the widely shared entertainment, media and ideas enjoyed by many people.","zh":"屬於流行文化的一部分，表示它屬於很多人共同接觸的娛樂、媒體和觀念。"},{"en":"Music videos, television dramas and fashion are all part of popular culture.","zh":"音樂影片、電視劇和時尚都是流行文化的一部分。"},{"en":"Films shape language, trends and conversations because they are part of popular culture.","zh":"電影會影響語言、潮流和話題，因為它屬於流行文化。"},{"en":"Popular culture provides familiar material that can be used for learning and discussion.","zh":"流行文化提供熟悉材料，可以用來學習和討論。"}],"source":"2015 Q7.pdf","sourcePage":13},{"front":"be used to teach","meaning":"被用來教授","examples":[{"en":"Films can be used to teach language, values and creativity.","zh":"電影可以被用來教授語言、價值觀和創意。"},{"en":"To be used to teach something means to serve as a tool for helping people learn it.","zh":"「be used to teach」表示某物可以成為幫助人學習某項內容的工具。"},{"en":"Maps can be used to teach geography.","zh":"地圖可以被用來教授地理。"},{"en":"Films can be used to teach language through dialogue and subtitles.","zh":"電影可以透過對白和字幕被用來教授語言。"},{"en":"Entertainment materials become educational when teachers design suitable learning activities around them.","zh":"當老師圍繞娛樂材料設計合適學習活動，它便可以具有教育用途。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"language, values and creativity","meaning":"語言、價值觀和創意","examples":[{"en":"Films can teach language, values and creativity.","zh":"電影可以教授語言、價值觀和創意。"},{"en":"“Language, values and creativity” refers to communication skills, beliefs about what matters, and the ability to produce new ideas.","zh":"「language, values and creativity」分別指溝通能力、對甚麼重要的信念，以及創造新想法的能力。"},{"en":"Stories can teach language while also raising questions about values.","zh":"故事可以教授語言，同時引發對價值觀的思考。"},{"en":"Film-making encourages creativity because students must make choices about images and stories.","zh":"電影製作鼓勵創意，因為學生需要就影像和故事作選擇。"},{"en":"One cultural product can support several kinds of learning at the same time.","zh":"一項文化作品可以同時支援多種學習。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"school screenings","meaning":"學校專場放映","examples":[{"en":"Cinemas could offer school screenings of documentaries and local productions.","zh":"戲院可以為紀錄片和本地製作提供學校專場放映。"},{"en":"School screenings are film sessions specially arranged for students and teachers as part of educational activities.","zh":"學校專場放映是特別為學生和老師安排、作教育用途的電影場次。"},{"en":"The cinema held a morning school screening for history students.","zh":"戲院為歷史科學生舉辦早上學校專場。"},{"en":"School screenings can introduce young people to cinemas in an educational context.","zh":"學校專場放映可以在教育情境下把年輕人帶進戲院。"},{"en":"Special screenings allow teachers to connect films directly with classroom learning.","zh":"特別放映讓老師能直接把電影與課堂學習連結。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"film adaptations","meaning":"改編電影","examples":[{"en":"Film adaptations can help students connect books with cinema.","zh":"改編電影可以幫助學生把書本與電影連結。"},{"en":"Film adaptations are films based on novels, plays, comics or other existing works.","zh":"改編電影是根據小說、劇本、漫畫或其他已有作品拍成的電影。"},{"en":"Students compared the novel with its film adaptation.","zh":"學生比較小說和它的改編電影。"},{"en":"Film adaptations can help learners notice how stories change when moved to another medium.","zh":"改編電影可以幫助學習者留意故事轉到另一種媒介時如何改變。"},{"en":"Comparing source texts with films encourages discussion about storytelling choices.","zh":"比較原著和電影可以鼓勵人討論敘事選擇。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"documentaries","meaning":"紀錄片","examples":[{"en":"Documentaries can be used for educational screenings.","zh":"紀錄片可以用於教育放映。"},{"en":"Documentaries are non-fiction films that present real people, events, issues or information.","zh":"紀錄片是呈現真實人物、事件、議題或資訊的非虛構電影。"},{"en":"The class watched a documentary about ocean pollution.","zh":"全班觀看了一套關於海洋污染的紀錄片。"},{"en":"Documentaries can make social issues feel more immediate through real images and interviews.","zh":"紀錄片透過真實影像和訪問，可以令社會問題更有現實感。"},{"en":"Educational screenings can use documentaries to connect classroom topics with real life.","zh":"教育放映可以利用紀錄片把課堂主題與現實生活連接。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"local productions","meaning":"本地製作","examples":[{"en":"Local productions can help students understand Hong Kong culture.","zh":"本地製作可以幫助學生理解香港文化。"},{"en":"Local productions are films, programmes or creative works made within the local region or industry.","zh":"本地製作是在本地地區或產業內製作的電影、節目或創作作品。"},{"en":"Film festivals can give local productions more public attention.","zh":"電影節可以令本地製作得到更多公眾關注。"},{"en":"Local productions often use familiar places, language and social issues.","zh":"本地製作常使用熟悉的地方、語言和社會議題。"},{"en":"Showing local work helps young audiences see their own community represented on screen.","zh":"展示本地作品可以讓年輕觀眾在銀幕上看見自己的社區。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"followed by","meaning":"隨後有","examples":[{"en":"School screenings could be followed by short talks.","zh":"學校專場放映後可以隨後有簡短講座。"},{"en":"“Followed by” means one event happens immediately or soon after another.","zh":"「followed by」表示一件事之後立即或很快發生另一件事。"},{"en":"The presentation was followed by a question-and-answer session.","zh":"簡報之後隨即有問答環節。"},{"en":"A film followed by a talk gives students time to reflect on what they watched.","zh":"電影之後有講座，可以讓學生反思所看的內容。"},{"en":"Combining two activities can turn a screening into a fuller learning experience.","zh":"把兩項活動組合，可以令放映變成更完整的學習體驗。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"short talks on","meaning":"關於……的簡短講座","examples":[{"en":"Cinemas could offer short talks on subtitles and storytelling.","zh":"戲院可以提供關於字幕和敘事的簡短講座。"},{"en":"“Short talks on” means brief presentations explaining particular topics.","zh":"「short talks on」表示就特定主題進行簡短介紹或講解。"},{"en":"The library organised short talks on online safety.","zh":"圖書館舉辦關於網上安全的簡短講座。"},{"en":"Short talks on film techniques can help students notice how meaning is created.","zh":"關於電影技巧的短講可以幫助學生留意意義如何被創造。"},{"en":"Brief explanations are useful when they add knowledge without making an activity too long.","zh":"簡短講解可以增加知識，同時不會令活動拖得太長。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"subtitles","meaning":"字幕","examples":[{"en":"Students could learn how subtitles shape understanding.","zh":"學生可以學習字幕如何影響理解。"},{"en":"Subtitles are written words displayed on a screen to represent spoken dialogue or provide translation.","zh":"字幕是在螢幕上顯示、代表口頭對白或提供翻譯的文字。"},{"en":"Foreign-language films often use subtitles for local audiences.","zh":"外語電影常為本地觀眾提供字幕。"},{"en":"Different subtitle choices can affect how humour or emotion is understood.","zh":"不同字幕選擇可以影響幽默或情感如何被理解。"},{"en":"Studying subtitles helps language learners see how meaning changes across languages.","zh":"研究字幕可以幫助語言學習者了解意思如何跨語言改變。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"camera angles","meaning":"鏡頭角度","examples":[{"en":"Short talks could explain camera angles and storytelling.","zh":"簡短講座可以解釋鏡頭角度和敘事技巧。"},{"en":"Camera angles are the positions and directions from which a camera records a subject.","zh":"鏡頭角度是攝影機拍攝人物或物件時的位置和方向。"},{"en":"A low camera angle can make a character appear powerful.","zh":"低角度鏡頭可以令角色看起來更有力量。"},{"en":"Directors choose camera angles to guide the audience’s attention and feelings.","zh":"導演選擇鏡頭角度，引導觀眾的注意和感受。"},{"en":"Learning about camera angles helps students understand that film images are carefully constructed.","zh":"學習鏡頭角度可以幫助學生明白電影畫面是經仔細設計的。"}],"source":"2015 Q7.pdf","sourcePage":14},{"front":"storytelling","meaning":"敘事技巧","examples":[{"en":"Films can teach students about storytelling.","zh":"電影可以教授學生敘事技巧。"},{"en":"Storytelling is the art of organising characters, events and ideas into a meaningful narrative.","zh":"敘事技巧是把人物、事件和想法組織成有意義故事的藝術。"},{"en":"Good storytelling makes audiences care about what happens next.","zh":"良好的敘事技巧會令觀眾關心之後發生甚麼。"},{"en":"Films use images, dialogue, music and editing as storytelling tools.","zh":"電影利用影像、對白、音樂和剪接作為敘事工具。"},{"en":"Understanding storytelling helps students both analyse and create narratives.","zh":"理解敘事技巧可以幫助學生分析和創作故事。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"through a school activity","meaning":"透過學校活動","examples":[{"en":"Students may first visit a cinema through a school activity.","zh":"學生可能第一次透過學校活動到訪戲院。"},{"en":"“Through a school activity” means because participation has been arranged as part of school learning or an event.","zh":"「through a school activity」表示因學校學習或活動安排而參與。"},{"en":"She first visited the museum through a school activity.","zh":"她第一次去博物館是透過學校活動。"},{"en":"A school screening can introduce students to cinemas in a low-cost and educational way.","zh":"學校專場可以用低成本而有教育意義的方法讓學生接觸戲院。"},{"en":"First experiences organised by schools can influence later personal habits.","zh":"學校安排的第一次經驗可以影響之後的個人習慣。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"later return with friends","meaning":"之後和朋友再來","examples":[{"en":"Students may later return with friends.","zh":"學生之後可能和朋友再來。"},{"en":"To later return with friends means to come back at a future time voluntarily with one’s own social group.","zh":"「later return with friends」表示日後自願與自己的朋友再次到訪。"},{"en":"After visiting the exhibition with school, she later returned with friends at the weekend.","zh":"跟學校參觀展覽後，她週末又和朋友再來。"},{"en":"A positive school cinema experience may encourage students to return socially.","zh":"良好的學校戲院體驗可能鼓勵學生之後與朋友再來。"},{"en":"Turning first-time visitors into repeat customers is valuable for long-term attendance.","zh":"把第一次訪客變成重複到訪顧客，對長期入場人次很重要。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"in the meantime","meaning":"與此同時","examples":[{"en":"In the meantime, cinema operators should use social media creatively.","zh":"與此同時，戲院經營者應有創意地使用社交媒體。"},{"en":"“In the meantime” means during the period while other actions or developments are happening.","zh":"「in the meantime」表示在其他行動或發展正在進行的期間。"},{"en":"The new library will open next year; in the meantime, students can use the temporary study room.","zh":"新圖書館明年開幕；與此同時，學生可以使用臨時自修室。"},{"en":"Schools may build long-term interest; in the meantime, cinemas can improve online engagement.","zh":"學校可以建立長期興趣；與此同時，戲院可以改善網上互動。"},{"en":"This phrase introduces something useful that can happen while waiting for another process.","zh":"這個片語帶出在等待另一個過程期間可以先做的事情。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"not only to…, but also to…","meaning":"不只是為了……也為了……","examples":[{"en":"Cinemas should use social media not only to advertise, but also to invite participation.","zh":"戲院使用社交媒體不只是為了宣傳，也為了邀請參與。"},{"en":"“Not only to A, but also to B” means something should serve both purposes rather than only the first.","zh":"「not only to A, but also to B」表示某件事應同時服務兩個目的，而不只是第一個。"},{"en":"Schools use websites not only to share notices, but also to collect feedback.","zh":"學校使用網站不只是為了發布通知，也為了收集意見。"},{"en":"Cinema social media can promote films and also ask audiences to vote or comment.","zh":"戲院社交媒體可以宣傳電影，也可以邀請觀眾投票或留言。"},{"en":"This structure emphasises that a tool has a broader purpose than people may first assume.","zh":"這個句式強調一項工具的用途比最初想像更廣。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"advertise","meaning":"宣傳","examples":[{"en":"Cinema operators use social media to advertise films.","zh":"戲院經營者使用社交媒體宣傳電影。"},{"en":"To advertise means to promote a product, service or event so that more people know about it.","zh":"宣傳表示推廣產品、服務或活動，讓更多人知道。"},{"en":"Shops advertise special offers online before holidays.","zh":"商店在節日前於網上宣傳特別優惠。"},{"en":"Cinemas advertise new releases through trailers and posters.","zh":"戲院透過預告片和海報宣傳新上映電影。"},{"en":"Advertising can create awareness, but it does not automatically create engagement or loyalty.","zh":"宣傳可以提高知名度，但不會自動建立參與或忠誠。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"share recommendations","meaning":"分享推薦","examples":[{"en":"Young people could share recommendations online.","zh":"年輕人可以在網上分享推薦。"},{"en":"To share recommendations means to tell other people what films, products or activities you think they should try.","zh":"分享推薦表示告訴其他人你認為值得嘗試的電影、產品或活動。"},{"en":"Friends often share restaurant recommendations in group chats.","zh":"朋友常在群組聊天中分享餐廳推薦。"},{"en":"Cinema communities could invite viewers to share recommendations after screenings.","zh":"戲院社群可以邀請觀眾在放映後分享推薦。"},{"en":"Personal recommendations can make audiences feel involved in helping others discover films.","zh":"個人推薦可以令觀眾覺得自己參與幫助別人發現電影。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"that way","meaning":"這樣一來","examples":[{"en":"That way, moviegoers become part of a community.","zh":"這樣一來，電影觀眾便會成為社群的一部分。"},{"en":"“That way” means by using the method just described.","zh":"「that way」表示透過剛才所描述的方法。"},{"en":"Invite students to plan the event; that way, they will feel more involved.","zh":"邀請學生一起策劃活動；這樣一來，他們會更投入。"},{"en":"If cinemas encourage discussion, that way audiences can build relationships around films.","zh":"如果戲院鼓勵討論，這樣一來觀眾可以圍繞電影建立關係。"},{"en":"This phrase links an action directly to its expected result.","zh":"這個片語把行動直接連接到預期結果。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"become part of a community","meaning":"成為社群的一部分","examples":[{"en":"Moviegoers can become part of a community.","zh":"電影觀眾可以成為社群的一部分。"},{"en":"To become part of a community means to feel connected with a group that shares interests, activities or identity.","zh":"成為社群的一部分表示與一群有共同興趣、活動或身份的人建立連結。"},{"en":"Joining the local running club helped her become part of a community.","zh":"加入本地跑步會令她成為一個社群的一部分。"},{"en":"Film discussions can help regular audiences recognise and connect with one another.","zh":"電影討論可以幫助常客彼此認識和交流。"},{"en":"Community creates emotional reasons to return beyond the product being sold.","zh":"社群可以提供產品本身以外、令人再次回來的情感理由。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"rather than just customers","meaning":"而不只是顧客","examples":[{"en":"Moviegoers should become part of a community rather than just customers.","zh":"電影觀眾應成為社群的一部分，而不只是顧客。"},{"en":"“Rather than just customers” means people should have a richer relationship with the cinema than simply buying tickets.","zh":"「rather than just customers」表示人們與戲院的關係應比單純買票更豐富。"},{"en":"Members of a club are participants rather than just customers.","zh":"學會會員是參與者，而不只是顧客。"},{"en":"Cinemas can build loyalty when audiences feel involved rather than merely sold to.","zh":"當觀眾感到自己有參與，而不只是被推銷，戲院更容易建立忠誠。"},{"en":"Community relationships are usually stronger than purely transactional ones.","zh":"社群關係通常比純交易關係更強。"}],"source":"2015 Q7.pdf","sourcePage":15},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, the decline is serious but not irreversible.","zh":"綜合而言，這次下降情況嚴重，但並非不可逆轉。"},{"en":"“All things considered” means after taking the main facts, causes and possibilities into account.","zh":"「all things considered」表示把主要事實、原因和可能性都考慮之後。"},{"en":"All things considered, the cheaper plan offers better value.","zh":"綜合而言，較便宜的方案提供更好價值。"},{"en":"After considering cost, convenience and experience, the report reaches a balanced conclusion.","zh":"考慮成本、方便和體驗後，報告得出一個平衡結論。"},{"en":"This phrase is especially useful for introducing a final judgement.","zh":"這個片語特別適合用來帶出最終判斷。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"serious but not irreversible","meaning":"嚴重但並非不可逆轉","examples":[{"en":"The decline in cinema attendance is serious but not irreversible.","zh":"戲院入場人次下降情況嚴重，但並非不可逆轉。"},{"en":"“Serious but not irreversible” means the problem is important and worrying, but it can still be improved or changed.","zh":"「serious but not irreversible」表示問題重要而令人擔心，但仍然可以改善或改變。"},{"en":"The environmental damage is serious but not irreversible if action begins now.","zh":"如果現在開始行動，環境損害雖嚴重但並非不可逆轉。"},{"en":"Cinema attendance may recover if operators respond effectively.","zh":"如果戲院經營者有效回應，入場人次仍可能回升。"},{"en":"The phrase avoids both underestimating the problem and treating it as hopeless.","zh":"這個說法既不低估問題，也不把它說成毫無希望。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"irreversible","meaning":"不可逆轉的","examples":[{"en":"The decline is not irreversible if cinemas improve the experience.","zh":"如果戲院改善體驗，這次下降並非不可逆轉。"},{"en":"Irreversible means impossible to change back to the previous condition.","zh":"「irreversible」表示無法再改回以前狀態。"},{"en":"Some environmental damage can become irreversible if action comes too late.","zh":"如果行動太遲，部分環境破壞可能變成不可逆轉。"},{"en":"The fall in attendance is not irreversible because consumer habits can change again.","zh":"入場人次下降並非不可逆轉，因為消費習慣仍可以再次改變。"},{"en":"Calling a problem reversible means there is still room for effective action.","zh":"說問題可以逆轉，表示仍有空間採取有效行動。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"have not stopped loving stories","meaning":"並沒有停止喜愛故事","examples":[{"en":"People have not stopped loving stories.","zh":"人們並沒有停止喜愛故事。"},{"en":"“Have not stopped loving stories” means people still enjoy narratives even if the way they consume them has changed.","zh":"「have not stopped loving stories」表示即使接觸故事的方式改變，人仍然喜歡敘事內容。"},{"en":"Streaming success shows that audiences have not stopped loving stories.","zh":"串流平台的成功顯示觀眾並沒有停止喜愛故事。"},{"en":"Falling cinema attendance does not prove that interest in films has disappeared.","zh":"戲院入場人次下降並不能證明人們已失去對電影的興趣。"},{"en":"The problem may lie in the delivery experience rather than in the content itself.","zh":"問題可能在提供體驗的方法，而不是內容本身。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"harder to persuade","meaning":"更難說服","examples":[{"en":"Audiences have simply become harder to persuade.","zh":"觀眾只是變得更難說服。"},{"en":"To become harder to persuade means to require stronger reasons before agreeing to do or buy something.","zh":"「harder to persuade」表示需要更有力的理由，才能令人同意做或購買某事。"},{"en":"Consumers become harder to persuade when they have many competing choices.","zh":"當消費者有很多競爭選擇，他們會變得更難說服。"},{"en":"Cinemas must offer clearer value because audiences are harder to persuade to leave home.","zh":"因為觀眾更難被說服離開家，戲院必須提供更清楚的價值。"},{"en":"Better-informed customers usually expect stronger reasons before spending time or money.","zh":"資訊更充足的顧客通常需要更強理由才願意付出時間或金錢。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"act together","meaning":"一起行動","examples":[{"en":"Cinema operators, schools, malls and film-makers should act together.","zh":"戲院經營者、學校、商場和電影人應一起行動。"},{"en":"To act together means for several groups to coordinate their efforts towards the same goal.","zh":"「act together」表示幾個群體協調行動，共同達成同一目標。"},{"en":"Residents and local businesses acted together to clean the neighbourhood.","zh":"居民和本地商戶一起行動，清潔社區。"},{"en":"Different organisations can revive cinema culture more effectively if they cooperate.","zh":"不同機構如果合作，可以更有效復興戲院文化。"},{"en":"Shared problems often require action from more than one group.","zh":"共同問題往往需要多於一個群體採取行動。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"local film-makers","meaning":"本地電影人","examples":[{"en":"Local film-makers can help revive cinema-going.","zh":"本地電影人可以幫助復興入戲院看電影的文化。"},{"en":"Local film-makers are directors, producers, writers and other creators who make films within the local industry.","zh":"本地電影人是在本地電影業工作的導演、監製、編劇和其他創作者。"},{"en":"Local film-makers often tell stories rooted in familiar places and experiences.","zh":"本地電影人常講述扎根於熟悉地方和生活經驗的故事。"},{"en":"Talks with local film-makers could make cinema events more distinctive.","zh":"與本地電影人的分享會可以令戲院活動更有特色。"},{"en":"Supporting local creators can strengthen both film culture and audience connection.","zh":"支持本地創作者可以同時加強電影文化和觀眾連結。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"affordable, distinctive and socially meaningful","meaning":"負擔得起、有特色、有社交意義","examples":[{"en":"Cinema-going should be affordable, distinctive and socially meaningful.","zh":"入戲院看電影應該負擔得起、有特色，而且有社交意義。"},{"en":"“Affordable, distinctive and socially meaningful” means reasonably priced, clearly different from alternatives, and valuable as a shared social activity.","zh":"「affordable, distinctive and socially meaningful」表示價格合理、明顯有別於替代選擇，而且作為共同社交活動有價值。"},{"en":"A community event succeeds when it is affordable, distinctive and meaningful to local people.","zh":"一項社區活動如果負擔得起、有特色，而且對本地人有意義，就較容易成功。"},{"en":"Lower prices address affordability, themed events create distinction, and discussions add social meaning.","zh":"較低票價改善可負擔性，主題活動帶來特色，而討論增加社交意義。"},{"en":"These three qualities directly respond to the major weaknesses identified in the report.","zh":"這三項特質直接回應報告指出的主要弱點。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"home viewing","meaning":"在家觀看","examples":[{"en":"Home viewing cannot replace a strong cinema experience.","zh":"在家觀看不能取代強而有力的戲院體驗。"},{"en":"Home viewing means watching films or other content at home rather than in a cinema or public venue.","zh":"在家觀看是指在家而不是戲院或公共場所觀看電影或其他內容。"},{"en":"Home viewing offers convenience, privacy and control over timing.","zh":"在家觀看提供方便、私隱和時間控制。"},{"en":"Cinemas should not try to copy home viewing because their strengths are different.","zh":"戲院不應嘗試完全模仿在家觀看，因為兩者優勢不同。"},{"en":"A strong public experience can offer social and sensory benefits beyond home viewing.","zh":"優秀的公共觀看體驗可以提供在家觀看以外的社交和感官價值。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"cannot replace","meaning":"不能取代","examples":[{"en":"Home viewing cannot replace a memorable cinema experience.","zh":"在家觀看不能取代難忘的戲院體驗。"},{"en":"“Cannot replace” means cannot provide the same role, value or experience strongly enough to make the original unnecessary.","zh":"「cannot replace」表示無法充分提供相同功能、價值或體驗，以致原本的東西變得沒有必要。"},{"en":"Video calls cannot completely replace face-to-face friendship.","zh":"視像通話不能完全取代面對面的友誼。"},{"en":"Home screens cannot replace the social atmosphere of a strong cinema event.","zh":"家中螢幕不能取代優秀戲院活動的社交氣氛。"},{"en":"One option may be convenient without reproducing every benefit of another.","zh":"一個選擇可以很方便，卻未必能複製另一個選擇的所有好處。"}],"source":"2015 Q7.pdf","sourcePage":16},{"front":"big-screen culture","meaning":"大銀幕文化","examples":[{"en":"Hong Kong’s big-screen culture should be protected.","zh":"香港的大銀幕文化應受到保護。"},{"en":"Big-screen culture refers to the shared tradition and experience of watching films in cinemas on large screens.","zh":"大銀幕文化是指在戲院大銀幕共同觀看電影的傳統和體驗。"},{"en":"Film festivals help keep big-screen culture alive by bringing audiences together.","zh":"電影節透過把觀眾聚集起來，幫助大銀幕文化延續。"},{"en":"Big-screen culture includes more than technology; it also includes collective viewing habits and local film memory.","zh":"大銀幕文化不只包括科技，也包括共同觀看習慣和本地電影記憶。"},{"en":"Protecting cinema culture requires giving younger audiences reasons to value the shared experience.","zh":"保護戲院文化需要給年輕觀眾理由去重視共同觀看體驗。"}],"source":"2015 Q7.pdf","sourcePage":17},{"front":"become a thing of the past","meaning":"成為過去式","examples":[{"en":"Hong Kong’s big-screen culture should not become a thing of the past.","zh":"香港的大銀幕文化不應成為過去式。"},{"en":"To become a thing of the past means to disappear from current life and exist only as a memory or historical practice.","zh":"「become a thing of the past」表示從現代生活消失，只留下回憶或歷史做法。"},{"en":"Paper train tickets have largely become a thing of the past in some cities.","zh":"在一些城市，紙製車票已大致成為過去式。"},{"en":"If cinemas fail to adapt, regular cinema-going could become a thing of the past for younger generations.","zh":"如果戲院不作改變，對年輕一代來說，經常入戲院可能成為過去式。"},{"en":"Preventing something from becoming a thing of the past requires keeping it useful and meaningful in the present.","zh":"要防止某事成為過去式，就必須令它在今天仍然有用和有意義。"}],"source":"2015 Q7.pdf","sourcePage":17}],"dse/writing/part-b/2015/Q8":[{"front":"let words walk off the page","meaning":"讓文字走出書頁","examples":[{"en":"The proposed activities let words walk off the page.","zh":"這些建議活動讓文字走出書頁。"},{"en":"Let words walk off the page means make written language feel alive through speaking, acting, movement, or interaction.","zh":"let words walk off the page 指透過朗讀、表演、動作或互動，令書面語言變得有生命。"},{"en":"A poem can walk off the page when students perform it with voice and gesture.","zh":"當學生用聲音和手勢表演一首詩，詩就能走出書頁。"},{"en":"When language becomes active, students remember it better than when they only read silently.","zh":"當語言變得主動，學生會比只默讀時更容易記住它。"},{"en":"These activities help English become something students experience, not just something they study.","zh":"這些活動幫助英語成為學生能體驗的東西，而不只是要溫習的東西。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"proposed activities","meaning":"建議活動","examples":[{"en":"The letter introduces two proposed activities for the festival.","zh":"這封信介紹了兩項為藝術節而設的建議活動。"},{"en":"Proposed activities are suggested events or programmes that people may choose to organise.","zh":"proposed activities 指建議舉辦、可供考慮的活動或課程。"},{"en":"A school club may send proposed activities to the library before a festival begins.","zh":"學校學會可能在藝術節開始前向圖書館提交建議活動。"},{"en":"Proposed activities should explain what students will do and why the activity is useful.","zh":"建議活動應解釋學生會做甚麼，以及活動為何有用。"},{"en":"These proposed activities aim to make English lively, social, and memorable.","zh":"這些建議活動旨在令英語變得生動、社交化和難忘。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"Language Arts Festival","meaning":"語文藝術節","examples":[{"en":"The Central Library is organising a summer Language Arts Festival.","zh":"中央圖書館正在籌辦一個夏季語文藝術節。"},{"en":"A Language Arts Festival is an event that celebrates reading, writing, speaking, drama, and creative language use.","zh":"Language Arts Festival 是慶祝閱讀、寫作、說話、戲劇和創意語言運用的活動。"},{"en":"Students may join workshops, performances, and games at a Language Arts Festival.","zh":"學生可以在語文藝術節參加工作坊、表演和遊戲。"},{"en":"Such a festival can help students see English as creative, not only academic.","zh":"這類藝術節能幫助學生把英語視為創意工具，而不只是學科。"},{"en":"The Central Library’s festival gives students a chance to use language actively.","zh":"中央圖書館的藝術節給學生主動使用語言的機會。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"on behalf of","meaning":"代表","examples":[{"en":"Chris writes on behalf of the school’s Poetry Club.","zh":"Chris 代表學校詩會寫信。"},{"en":"On behalf of means representing another person or group.","zh":"on behalf of 指代表某人或某個團體。"},{"en":"A class monitor may speak on behalf of classmates during a meeting.","zh":"班長可能在會議中代表同學發言。"},{"en":"When someone writes on behalf of a club, the letter carries the club’s shared view.","zh":"當某人代表學會寫信，信件表達的是學會的共同看法。"},{"en":"Chris uses this phrase to show that the suggestions come from the Poetry Club, not only from himself.","zh":"Chris 使用這個片語，顯示建議來自詩會，而不只是他個人。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"Poetry Club","meaning":"詩會","examples":[{"en":"The school’s Poetry Club submits suggestions for the festival.","zh":"學校詩會為藝術節提交建議。"},{"en":"A Poetry Club is a group of students who read, write, discuss, or perform poems together.","zh":"Poetry Club 是一群一起閱讀、寫作、討論或表演詩歌的學生。"},{"en":"A Poetry Club may organise readings, poetry walls, or writing workshops.","zh":"詩會可以籌辦朗讀會、詩牆或寫作工作坊。"},{"en":"Students in a Poetry Club learn to treat language as sound, image, and feeling.","zh":"詩會學生學會把語言視為聲音、意象和情感。"},{"en":"The Poetry Club is suitable for giving festival suggestions because it understands student interest in language.","zh":"詩會適合提出藝術節建議，因為它了解學生對語言的興趣。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"be delighted to submit","meaning":"很高興提交","examples":[{"en":"The Poetry Club is delighted to submit its suggestions.","zh":"詩會很高興提交建議。"},{"en":"Be delighted to submit means be very pleased to formally give something for consideration.","zh":"be delighted to submit 指很高興正式提交某物供考慮。"},{"en":"A student may be delighted to submit a poem to a school magazine.","zh":"學生可能很高興向校刊提交一首詩。"},{"en":"This phrase sounds polite and positive in a formal proposal letter.","zh":"這個片語在正式建議信中聽起來禮貌而正面。"},{"en":"The club is delighted because the festival matches its love of language.","zh":"詩會感到高興，因為藝術節與他們對語言的熱愛相符。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"suggestions for","meaning":"給予……的建議","examples":[{"en":"The letter gives suggestions for the Central Library’s festival.","zh":"這封信給予中央圖書館藝術節的建議。"},{"en":"Suggestions for something are ideas offered to improve, plan, or support it.","zh":"suggestions for something 指為改善、計劃或支援某事而提出的想法。"},{"en":"Students gave suggestions for making English lessons more interactive.","zh":"學生就如何令英文課更互動提出建議。"},{"en":"Good suggestions explain both the activity and its purpose.","zh":"好建議會解釋活動內容和活動目的。"},{"en":"These suggestions for the festival focus on performance, problem-solving, and creativity.","zh":"這些給藝術節的建議集中於表演、解難和創意。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"summer language arts festival","meaning":"夏季語文藝術節","examples":[{"en":"The suggestions are for the summer language arts festival.","zh":"這些建議是為夏季語文藝術節而設。"},{"en":"A summer language arts festival is a language-focused event held during the summer.","zh":"summer language arts festival 指在夏天舉行、以語文藝術為重點的活動。"},{"en":"Students may join a summer language arts festival when they have more free time.","zh":"學生在暑假較有空時，可以參加夏季語文藝術節。"},{"en":"A summer festival can make learning feel less like schoolwork and more like discovery.","zh":"夏季藝術節可以令學習不像功課，而更像探索。"},{"en":"This festival can help students meet English in an active and enjoyable way.","zh":"這個藝術節可以幫助學生以主動而愉快的方式接觸英語。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"meet English mainly through","meaning":"主要透過……接觸英語","examples":[{"en":"Many students meet English mainly through tests and grammar drills.","zh":"許多學生主要透過測驗和文法操練接觸英語。"},{"en":"Meet English mainly through means experience or encounter English mostly in one particular way.","zh":"meet English mainly through 指主要以某種方式經歷或接觸英語。"},{"en":"Some children meet English mainly through textbooks, not real conversation.","zh":"有些孩子主要透過教科書接觸英語，而不是透過真實對話。"},{"en":"If students meet English only through exams, they may see it as pressure.","zh":"如果學生只透過考試接觸英語，他們可能會把英語視為壓力。"},{"en":"The festival should help students meet English through play, performance, and imagination.","zh":"藝術節應幫助學生透過遊戲、表演和想像接觸英語。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"grammar drills","meaning":"文法操練","examples":[{"en":"Some students learn English through grammar drills.","zh":"有些學生透過文法操練學習英語。"},{"en":"Grammar drills are repeated exercises used to practise sentence rules and structures.","zh":"grammar drills 是用來反覆練習句子規則和結構的練習。"},{"en":"Students may do grammar drills on tenses, prepositions, or question forms.","zh":"學生可能做關於時態、介詞或疑問句的文法操練。"},{"en":"Grammar drills can be useful, but they may feel boring if used alone.","zh":"文法操練可以有用，但如果單獨使用，可能會令人沉悶。"},{"en":"The festival balances grammar practice with creative language use.","zh":"藝術節把文法練習與創意語言運用平衡起來。"}],"source":"2015 Q8.pdf","sourcePage":1},{"front":"model answers","meaning":"模範答案","examples":[{"en":"Students often study tests, grammar drills and model answers.","zh":"學生常研讀測驗、文法操練和模範答案。"},{"en":"Model answers are sample answers that show how a good response may be written.","zh":"model answers 是展示好答案可以如何寫成的範例答案。"},{"en":"Students read model answers to learn structure, useful phrases, and exam style.","zh":"學生閱讀模範答案，以學習結構、實用片語和考試風格。"},{"en":"Model answers can help, but copying them may stop students from finding their own voice.","zh":"模範答案可以有幫助，但抄襲它們可能阻礙學生找到自己的聲音。"},{"en":"Creative activities encourage students to use English beyond model answers.","zh":"創意活動鼓勵學生在模範答案以外使用英語。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"respect the language","meaning":"尊重這種語言","examples":[{"en":"Students may respect the language without truly enjoying it.","zh":"學生可能尊重這種語言，卻沒有真正享受它。"},{"en":"Respect the language means understand that a language is important and worth learning.","zh":"respect the language 指明白一種語言重要並值得學習。"},{"en":"Students may respect English because it helps with exams, study, and work.","zh":"學生可能因英語有助考試、升學和工作而尊重英語。"},{"en":"However, respect alone does not always create interest or confidence.","zh":"然而，單有尊重不一定能產生興趣或信心。"},{"en":"The festival aims to turn respect into enjoyment through active use.","zh":"藝術節旨在透過主動使用，把尊重轉化為享受。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"without truly enjoying it","meaning":"卻沒有真正享受它","examples":[{"en":"Students may study English without truly enjoying it.","zh":"學生可能學習英語，卻沒有真正享受它。"},{"en":"Without truly enjoying it means doing something without real pleasure, interest, or connection.","zh":"without truly enjoying it 指做某事時沒有真正樂趣、興趣或連繫。"},{"en":"A student may practise piano every day without truly enjoying it.","zh":"學生可能每天練琴，卻沒有真正享受它。"},{"en":"If students study English only for marks, they may not truly enjoy the language.","zh":"如果學生只為分數學英語，他們可能沒有真正享受這種語言。"},{"en":"Activities with performance and games can help students enjoy English more genuinely.","zh":"包含表演和遊戲的活動能幫助學生更真切地享受英語。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"help change this","meaning":"幫助改變這種情況","examples":[{"en":"The Central Library can help change this situation.","zh":"中央圖書館可以幫助改變這種情況。"},{"en":"Help change this means play a part in improving or transforming the present problem.","zh":"help change this 指在改善或轉變目前問題中發揮作用。"},{"en":"A school can help change this by giving students more chances to speak.","zh":"學校可以透過給學生更多說話機會，幫助改變這種情況。"},{"en":"Libraries can change attitudes by making reading social and enjoyable.","zh":"圖書館可以透過令閱讀變得社交而有趣，改變學生態度。"},{"en":"The festival can help change how students feel about English.","zh":"藝術節可以幫助改變學生對英語的感覺。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"by offering activities","meaning":"透過提供活動","examples":[{"en":"The library can help by offering lively activities.","zh":"圖書館可以透過提供生動活動來幫助。"},{"en":"By offering activities means through providing events for people to join.","zh":"by offering activities 指透過提供讓人參與的活動。"},{"en":"A museum can attract families by offering weekend workshops.","zh":"博物館可以透過提供週末工作坊吸引家庭。"},{"en":"Offering activities gives students a reason to use language outside lessons.","zh":"提供活動能給學生在課堂以外使用語言的理由。"},{"en":"The library can make English enjoyable by offering activities that involve performance and discovery.","zh":"圖書館可以透過提供包含表演和探索的活動，令英語變得有趣。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"lively, inclusive and memorable","meaning":"生動、共融而難忘","examples":[{"en":"The activities should be lively, inclusive and memorable.","zh":"活動應該生動、共融而難忘。"},{"en":"Lively, inclusive and memorable means energetic, welcoming to different students, and easy to remember.","zh":"lively, inclusive and memorable 指有活力、歡迎不同學生參與，並令人容易記住。"},{"en":"A lively activity keeps students moving, speaking, and laughing.","zh":"生動的活動讓學生走動、說話和笑。"},{"en":"An inclusive activity allows shy and confident students to join in different ways.","zh":"共融的活動讓害羞和自信的學生都能以不同方式參與。"},{"en":"A memorable festival experience can change how students feel about English.","zh":"難忘的藝術節經驗可以改變學生對英語的感覺。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"in order to enhance","meaning":"為了提升","examples":[{"en":"The activities are suggested in order to enhance students’ interest.","zh":"建議這些活動是為了提升學生的興趣。"},{"en":"In order to enhance means for the purpose of improving or increasing something.","zh":"in order to enhance 指為了改善或增加某事物。"},{"en":"Schools may organise reading days in order to enhance students’ confidence in English.","zh":"學校可能舉辦閱讀日，為了提升學生使用英語的信心。"},{"en":"A clear purpose helps a proposal sound practical and focused.","zh":"清楚目的能令建議書聽起來實際而集中。"},{"en":"These activities are designed to enhance interest through active language use.","zh":"這些活動旨在透過主動使用語言來提升興趣。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"students’ interest in learning English","meaning":"學生學習英語的興趣","examples":[{"en":"The festival aims to enhance students’ interest in learning English.","zh":"藝術節旨在提升學生學習英語的興趣。"},{"en":"Students’ interest in learning English means how much students want to learn and use English.","zh":"students’ interest in learning English 指學生想學習和使用英語的程度。"},{"en":"Games, stories, and performances can increase students’ interest in learning English.","zh":"遊戲、故事和表演可以提升學生學習英語的興趣。"},{"en":"If English feels useful and creative, students are more willing to practise it.","zh":"如果英語感覺有用又有創意，學生會更願意練習。"},{"en":"The festival supports interest by making English active rather than mechanical.","zh":"藝術節透過令英語變得主動，而不是機械化，來支持學生興趣。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"central belief","meaning":"核心信念","examples":[{"en":"The writer’s central belief is that students enjoy English when they use it actively.","zh":"作者的核心信念是，當學生主動使用英語時，他們會享受英語。"},{"en":"A central belief is the main idea or principle behind an argument or plan.","zh":"central belief 指一個論點或計劃背後的主要想法或原則。"},{"en":"A teacher’s central belief may be that every student can improve with practice.","zh":"老師的核心信念可能是每個學生都能透過練習進步。"},{"en":"A proposal becomes clearer when its central belief is stated directly.","zh":"當核心信念被直接說出，建議會更清晰。"},{"en":"Here, the central belief links enjoyment with active use of English.","zh":"在這裏，核心信念把享受和主動使用英語連繫起來。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"become interested in","meaning":"對……產生興趣","examples":[{"en":"Students become interested in English when they can use it creatively.","zh":"當學生能創意地使用英語，他們就會對英語產生興趣。"},{"en":"Become interested in means start to feel curiosity, attention, or enjoyment towards something.","zh":"become interested in 指開始對某事感到好奇、注意或享受。"},{"en":"Children may become interested in reading when stories connect with their lives.","zh":"當故事與孩子生活有關，他們可能會對閱讀產生興趣。"},{"en":"Students become interested when learning feels useful instead of forced.","zh":"當學習感覺有用而不是被迫，學生就會產生興趣。"},{"en":"The festival helps students become interested in English through performance and problem-solving.","zh":"藝術節透過表演和解難，幫助學生對英語產生興趣。"}],"source":"2015 Q8.pdf","sourcePage":2},{"front":"use it to perform","meaning":"用它來表演","examples":[{"en":"Students can use English to perform.","zh":"學生可以用英語來表演。"},{"en":"Use it to perform means use English as a tool for acting, speaking, or presenting before others.","zh":"use it to perform 指把英語用作在他人面前演出、說話或展示的工具。"},{"en":"Students use English to perform when they read poems aloud on stage.","zh":"學生在台上朗讀詩作時，就是用英語來表演。"},{"en":"Performance helps language feel physical because students use voice, face, and movement.","zh":"表演令語言變得具體，因為學生使用聲音、表情和動作。"},{"en":"When students use English to perform, vocabulary becomes part of action.","zh":"當學生用英語表演，詞彙就成為行動的一部分。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"solve problems","meaning":"解決問題","examples":[{"en":"The activities allow students to use English to solve problems.","zh":"這些活動讓學生用英語解決問題。"},{"en":"Solve problems means find answers or solutions to difficulties, questions, or puzzles.","zh":"solve problems 指為困難、問題或謎題找出答案或解決方法。"},{"en":"Students solve problems when they use clues to finish a detective story.","zh":"學生用線索完成偵探故事時，就是在解決問題。"},{"en":"Problem-solving makes English purposeful because students need language to complete a task.","zh":"解難令英語有目的，因為學生需要語言去完成任務。"},{"en":"English becomes more memorable when students use it to solve problems together.","zh":"當學生一起用英語解決問題，英語會變得更難忘。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"express themselves","meaning":"表達自己","examples":[{"en":"Students become interested when they can express themselves in English.","zh":"當學生能用英語表達自己，他們就會產生興趣。"},{"en":"Express themselves means show their thoughts, feelings, and personality through words or actions.","zh":"express themselves 指透過文字或行動表達想法、感受和個性。"},{"en":"A shy student may express herself through a short poem before speaking in a speech.","zh":"害羞學生可能先透過短詩表達自己，再嘗試演講。"},{"en":"Students enjoy language more when it helps them say something personal.","zh":"當語言幫助學生說出個人想法，他們會更享受語言。"},{"en":"The festival gives students more ways to express themselves beyond worksheets.","zh":"藝術節給學生在工作紙以外表達自己的方式。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"Page-to-Stage Studio","meaning":"從書頁到舞台工作室","examples":[{"en":"Poetry Alive is a Page-to-Stage Studio.","zh":"Poetry Alive 是一個從書頁到舞台工作室。"},{"en":"A Page-to-Stage Studio is a workshop where written texts are turned into spoken or acted performances.","zh":"Page-to-Stage Studio 是把書面文本轉化為朗讀或演出的工作坊。"},{"en":"In a Page-to-Stage Studio, students move from reading a poem to performing it.","zh":"在從書頁到舞台工作室中，學生由閱讀詩作走向表演詩作。"},{"en":"This kind of studio helps students understand words through voice and movement.","zh":"這類工作室幫助學生透過聲音和動作理解文字。"},{"en":"Poetry Alive uses the stage to make poems feel alive.","zh":"Poetry Alive 使用舞台令詩歌變得有生命。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"a workshop in which","meaning":"一個讓……的工作坊","examples":[{"en":"Poetry Alive would be a workshop in which students perform poems.","zh":"Poetry Alive 將會是一個讓學生表演詩作的工作坊。"},{"en":"A workshop in which means a practical learning session where a certain activity happens.","zh":"a workshop in which 指一個進行某項活動的實用學習課節。"},{"en":"A debate workshop in which students practise arguments can build confidence.","zh":"一個讓學生練習論證的辯論工作坊可以建立信心。"},{"en":"This phrase helps describe not only the activity name but also what participants do.","zh":"這個片語幫助描述不只是活動名稱，還包括參加者做甚麼。"},{"en":"Poetry Alive is a workshop in which reading becomes performance.","zh":"Poetry Alive 是一個讓閱讀變成表演的工作坊。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"turn poems into short performances","meaning":"把詩變成短表演","examples":[{"en":"Students would turn poems into short performances.","zh":"學生會把詩變成短表演。"},{"en":"Turn poems into short performances means change written poems into brief acted or spoken presentations.","zh":"turn poems into short performances 指把書面詩作轉化為簡短的演出或朗讀展示。"},{"en":"A group can turn a sad poem into a performance using slow voices and still bodies.","zh":"小組可以用緩慢聲音和靜止身體，把悲傷的詩變成表演。"},{"en":"This process helps students think about tone, rhythm, and meaning.","zh":"這個過程幫助學生思考語氣、節奏和意義。"},{"en":"When poems become performances, students understand them with both mind and body.","zh":"當詩變成表演，學生會用思想和身體一起理解它。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"participants","meaning":"參加者","examples":[{"en":"Participants would choose a poem from a poetry wall.","zh":"參加者會從詩牆選擇一首詩。"},{"en":"Participants are people who take part in an activity or event.","zh":"participants 指參與某項活動或事件的人。"},{"en":"Workshop participants may read, discuss, rehearse, and perform together.","zh":"工作坊參加者可能一起朗讀、討論、排練和表演。"},{"en":"An inclusive activity gives different participants different ways to contribute.","zh":"共融活動會給不同參加者不同的貢獻方式。"},{"en":"The participants in Poetry Alive would become active users of English.","zh":"Poetry Alive 的參加者會成為主動使用英語的人。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"poetry wall","meaning":"詩牆","examples":[{"en":"The poetry wall would include classic and student-written poems.","zh":"詩牆會包括經典詩作和學生創作的詩。"},{"en":"A poetry wall is a display area where poems are posted for people to read and choose from.","zh":"poetry wall 是張貼詩作供人閱讀和選擇的展示區。"},{"en":"A school corridor can become a poetry wall during a reading week.","zh":"在閱讀週期間，學校走廊可以變成詩牆。"},{"en":"A poetry wall invites students to meet poems casually before performing them.","zh":"詩牆邀請學生在表演前輕鬆接觸詩作。"},{"en":"It makes poetry visible, shared, and easier to approach.","zh":"它令詩歌變得可見、可分享，也更容易親近。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"classic poems","meaning":"經典詩作","examples":[{"en":"Participants could choose classic poems from the poetry wall.","zh":"參加者可以從詩牆選擇經典詩作。"},{"en":"Classic poems are well-known poems that many readers continue to value over time.","zh":"classic poems 是經過時間仍被許多讀者重視的著名詩作。"},{"en":"Students may read classic poems to learn rhythm, imagery, and strong language.","zh":"學生可以閱讀經典詩作，學習節奏、意象和有力語言。"},{"en":"Classic poems can feel difficult, but performance may make them easier to enter.","zh":"經典詩作可能感覺艱深，但表演可以令它們更容易進入。"},{"en":"Including classic poems connects students with a wider literary tradition.","zh":"加入經典詩作，能把學生與更廣闊的文學傳統連繫起來。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"humorous verse","meaning":"幽默詩","examples":[{"en":"The poetry wall would include humorous verse.","zh":"詩牆會包括幽默詩。"},{"en":"Humorous verse is poetry that uses jokes, playful language, or funny situations.","zh":"humorous verse 是使用笑話、俏皮語言或有趣情況的詩。"},{"en":"Children may enjoy humorous verse because it makes language sound lively.","zh":"孩子可能喜歡幽默詩，因為它令語言聽起來生動。"},{"en":"Humorous verse can reduce fear of poetry by making students laugh.","zh":"幽默詩可以透過令人發笑，減少學生對詩歌的恐懼。"},{"en":"A funny poem can still teach rhythm, rhyme, and careful word choice.","zh":"有趣的詩仍能教授節奏、押韻和仔細選字。"}],"source":"2015 Q8.pdf","sourcePage":3},{"front":"poems written by Hong Kong students","meaning":"由香港學生創作的詩","examples":[{"en":"Participants could perform poems written by Hong Kong students.","zh":"參加者可以表演由香港學生創作的詩。"},{"en":"Poems written by Hong Kong students are student-created poems based on local voices and experiences.","zh":"poems written by Hong Kong students 指由學生創作、包含本地聲音和經驗的詩。"},{"en":"Such poems may describe MTR rides, exams, family meals, or city streets.","zh":"這些詩可能描寫港鐵旅程、考試、家庭飯局或城市街道。"},{"en":"Local student poems can make the festival feel closer to participants’ lives.","zh":"本地學生詩作能令藝術節更貼近參加者生活。"},{"en":"Performing them shows students that their own voices also belong in literature.","zh":"表演這些詩顯示學生自己的聲音也屬於文學。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"join small groups","meaning":"加入小組","examples":[{"en":"Participants would join small groups led by student ambassadors.","zh":"參加者會加入由學生大使帶領的小組。"},{"en":"Join small groups means become part of smaller teams for discussion or activity.","zh":"join small groups 指成為較小隊伍的一員，進行討論或活動。"},{"en":"Students often speak more comfortably when they join small groups instead of facing a whole hall.","zh":"學生加入小組時，通常比面對整個禮堂更能自在說話。"},{"en":"Small groups allow shy students to practise before performing publicly.","zh":"小組讓害羞學生在公開表演前先練習。"},{"en":"The activity uses small groups to make participation safer and more active.","zh":"活動使用小組，令參與更安全也更主動。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"led by student ambassadors","meaning":"由學生大使帶領","examples":[{"en":"The groups would be led by student ambassadors.","zh":"小組會由學生大使帶領。"},{"en":"Led by student ambassadors means guided by trained students who help other participants.","zh":"led by student ambassadors 指由受過訓練、協助其他參加者的學生引導。"},{"en":"Student ambassadors can explain instructions and encourage quieter members.","zh":"學生大使可以解釋指示並鼓勵較安靜的成員。"},{"en":"A group led by friendly students may feel less formal than one led only by adults.","zh":"由友善學生帶領的小組，可能比只由成人帶領更不拘謹。"},{"en":"Student ambassadors help make the workshop welcoming and peer-supported.","zh":"學生大使幫助工作坊變得歡迎人，並有同儕支援。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"step by step","meaning":"逐步地","examples":[{"en":"Step by step, students would prepare their performances.","zh":"學生會逐步準備他們的表演。"},{"en":"Step by step means gradually, one stage at a time.","zh":"step by step 指逐漸地，一個階段接一個階段。"},{"en":"Students can write a story step by step by planning, drafting, revising, and editing.","zh":"學生可以透過計劃、起草、修改和編輯，逐步寫成故事。"},{"en":"Step-by-step guidance helps less confident students avoid feeling lost.","zh":"逐步指導能幫助較缺乏信心的學生避免迷失。"},{"en":"In the workshop, students move step by step from reading to performance.","zh":"在工作坊中，學生逐步由閱讀走向表演。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"read the poem aloud","meaning":"朗讀詩作","examples":[{"en":"Students would read the poem aloud.","zh":"學生會朗讀詩作。"},{"en":"Read the poem aloud means speak the poem so that its sound can be heard.","zh":"read the poem aloud 指把詩讀出聲，讓人聽見它的聲音。"},{"en":"Reading aloud helps students notice rhythm, pauses, and repeated sounds.","zh":"朗讀能幫助學生留意節奏、停頓和重複聲音。"},{"en":"A quiet poem may become clearer when students hear it in a human voice.","zh":"當學生用人的聲音讀出來，安靜的詩可能會變得更清楚。"},{"en":"This step turns poetry from silent text into living sound.","zh":"這一步把詩歌由沉默文本變成活生生的聲音。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"identify its mood","meaning":"辨認它的情緒","examples":[{"en":"Students would identify the mood of the poem.","zh":"學生會辨認詩作的情緒。"},{"en":"Identify its mood means work out the feeling or atmosphere created by the poem.","zh":"identify its mood 指判斷詩所創造的感覺或氣氛。"},{"en":"Students may decide whether a poem feels joyful, lonely, angry, or playful.","zh":"學生可以判斷一首詩感覺快樂、孤獨、憤怒還是俏皮。"},{"en":"Identifying mood helps performers choose voice, speed, and gesture.","zh":"辨認情緒幫助表演者選擇聲音、速度和手勢。"},{"en":"A poem becomes easier to perform when students understand its emotional direction.","zh":"當學生明白詩的情感方向，詩就更容易表演。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"mark its pauses","meaning":"標示停頓","examples":[{"en":"Students would mark the pauses in the poem.","zh":"學生會標示詩中的停頓。"},{"en":"Mark its pauses means note where the reader should stop briefly while reading aloud.","zh":"mark its pauses 指記下朗讀時應短暫停下的位置。"},{"en":"Students may draw slashes between words to show short pauses.","zh":"學生可以在字詞之間畫斜線來表示短暫停頓。"},{"en":"Pauses can change meaning because they control rhythm and emphasis.","zh":"停頓可以改變意思，因為它控制節奏和重點。"},{"en":"Marking pauses helps students perform the poem more clearly.","zh":"標示停頓能幫助學生更清楚地表演詩作。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"experiment with sound effects","meaning":"嘗試音效","examples":[{"en":"Students would experiment with sound effects during rehearsal.","zh":"學生會在排練時嘗試音效。"},{"en":"Experiment with sound effects means try different noises or audio ideas to support a performance.","zh":"experiment with sound effects 指嘗試不同聲響或音訊點子來支援表演。"},{"en":"A group may use clapping, tapping, or whispers as sound effects.","zh":"小組可能使用拍手、敲擊或耳語作為音效。"},{"en":"Sound effects can make a storm, heartbeat, or busy street feel real.","zh":"音效可以令暴風雨、心跳或繁忙街道感覺真實。"},{"en":"Experimenting helps students understand how sound changes meaning.","zh":"嘗試音效幫助學生理解聲音如何改變意義。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"create a two-minute performance","meaning":"創作兩分鐘表演","examples":[{"en":"Each group would create a two-minute performance.","zh":"每組會創作一個兩分鐘表演。"},{"en":"Create a two-minute performance means prepare a short presentation lasting about two minutes.","zh":"create a two-minute performance 指準備一個約兩分鐘的短展示。"},{"en":"Students need to choose only the strongest ideas because two minutes is brief.","zh":"因為兩分鐘很短，學生需要只選擇最有力的想法。"},{"en":"A time limit helps groups focus on clear voice, movement, and meaning.","zh":"時間限制幫助小組集中於清楚聲音、動作和意思。"},{"en":"The short performance makes poetry manageable for beginners.","zh":"短表演令初學者也能掌握詩歌。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"voice, gesture or simple props","meaning":"聲音、手勢或簡單道具","examples":[{"en":"The performance could use voice, gesture or simple props.","zh":"表演可以使用聲音、手勢或簡單道具。"},{"en":"Voice, gesture or simple props means spoken sound, body movement, or basic objects used on stage.","zh":"voice, gesture or simple props 指舞台上的說話聲音、身體動作或基本物件。"},{"en":"Students may use a soft voice for sadness and a raised hand for surprise.","zh":"學生可以用柔和聲音表達悲傷，用舉手表達驚訝。"},{"en":"Simple props, such as paper masks or chairs, can suggest setting without much cost.","zh":"紙面具或椅子等簡單道具，可以不花太多錢就暗示場景。"},{"en":"These tools help students perform meaning without needing expensive equipment.","zh":"這些工具幫助學生不用昂貴設備也能表演意義。"}],"source":"2015 Q8.pdf","sourcePage":4},{"front":"the session could end with","meaning":"該節活動可以以……作結","examples":[{"en":"The session could end with a friendly mini-slam.","zh":"該節活動可以以友善的小型詩歌表演賽作結。"},{"en":"The session could end with means the activity may finish by doing a final event.","zh":"the session could end with 指活動可以透過一個最後環節結束。"},{"en":"A reading workshop could end with students sharing one favourite line.","zh":"閱讀工作坊可以以學生分享一句喜歡的句子作結。"},{"en":"Ending with a small performance gives participants a goal during practice.","zh":"以小型表演作結，能給參加者練習時的目標。"},{"en":"This phrase shows how the workshop can close in an energetic way.","zh":"這個片語顯示工作坊可以用充滿活力的方式完結。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"friendly mini-slam","meaning":"友善的小型詩歌表演賽","examples":[{"en":"The workshop could end with a friendly mini-slam.","zh":"工作坊可以以友善的小型詩歌表演賽作結。"},{"en":"A friendly mini-slam is a small, supportive poetry performance competition.","zh":"friendly mini-slam 是一個小型、有支持氣氛的詩歌表演比賽。"},{"en":"Students can perform poems in a mini-slam without feeling harshly judged.","zh":"學生可以在小型詩歌表演賽中演出，而不覺得被嚴厲評判。"},{"en":"A friendly atmosphere encourages beginners to try speaking before others.","zh":"友善氣氛鼓勵初學者嘗試在他人面前說話。"},{"en":"The mini-slam celebrates effort, expression, and creativity.","zh":"小型詩歌表演賽慶祝努力、表達和創意。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"awards such as","meaning":"例如……的獎項","examples":[{"en":"The activity could include awards such as Most Expressive Voice.","zh":"活動可以包括例如「最具表現力聲音」的獎項。"},{"en":"Awards such as introduces examples of prizes or recognition.","zh":"awards such as 用來引出獎項或表揚的例子。"},{"en":"A school contest may offer awards such as Best Teamwork and Most Creative Idea.","zh":"學校比賽可能設有例如「最佳團隊合作」和「最具創意意念」的獎項。"},{"en":"Clear award categories help students understand what qualities are valued.","zh":"清楚的獎項類別幫助學生明白哪些特質受重視。"},{"en":"These awards can reward expression, originality, and effort rather than only perfect English.","zh":"這些獎項可以獎勵表達、原創性和努力，而不只是完美英語。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"expressive voice","meaning":"富表現力的聲音","examples":[{"en":"The award could recognise the most expressive voice.","zh":"這個獎項可以表揚最富表現力的聲音。"},{"en":"An expressive voice shows feeling, meaning, and character through sound.","zh":"expressive voice 指透過聲音表現感情、意思和角色。"},{"en":"A reader uses an expressive voice when sadness, anger, or humour can be heard clearly.","zh":"當讀者讓悲傷、憤怒或幽默清楚被聽見，就是使用富表現力的聲音。"},{"en":"Expressive speaking helps listeners understand the mood of a poem.","zh":"富表現力的朗讀能幫助聽眾理解詩的情緒。"},{"en":"This award encourages students to speak with feeling, not only correct pronunciation.","zh":"這個獎項鼓勵學生帶着感情說話，而不只是發音正確。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"original interpretation","meaning":"原創演繹","examples":[{"en":"The activity could reward the most original interpretation.","zh":"活動可以獎勵最具原創演繹的作品。"},{"en":"Original interpretation means a fresh, personal, or creative way of understanding and presenting a text.","zh":"original interpretation 指以新鮮、個人或創意方式理解並呈現文本。"},{"en":"One group may interpret a sad poem as quiet hope instead of defeat.","zh":"有小組可能把悲傷的詩演繹成安靜的希望，而不是失敗。"},{"en":"Original interpretation shows that students are thinking, not simply copying the teacher’s answer.","zh":"原創演繹顯示學生在思考，而不是只複製老師答案。"},{"en":"Rewarding originality helps students feel that their ideas matter.","zh":"獎勵原創性能令學生覺得自己的想法重要。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"increase students’ interest in","meaning":"提升學生對……的興趣","examples":[{"en":"This activity would increase students’ interest in English.","zh":"這項活動會提升學生對英語的興趣。"},{"en":"Increase students’ interest in means make students more curious about or willing to learn something.","zh":"increase students’ interest in 指令學生對某事更好奇或更願意學習。"},{"en":"A drama game can increase students’ interest in speaking English.","zh":"戲劇遊戲可以提升學生對說英語的興趣。"},{"en":"Interest increases when students feel successful, active, and included.","zh":"當學生感到成功、主動和被包容，興趣就會提升。"},{"en":"Poetry Alive increases interest by turning difficult texts into shared performance.","zh":"Poetry Alive 透過把艱深文本變成共同表演來提升興趣。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"encounter difficult language","meaning":"接觸艱深語言","examples":[{"en":"The workshop changes how students encounter difficult language.","zh":"這個工作坊改變學生接觸艱深語言的方式。"},{"en":"Encounter difficult language means meet words, phrases, or texts that are hard to understand.","zh":"encounter difficult language 指遇到難以理解的字詞、片語或文本。"},{"en":"Students often encounter difficult language when reading poems or old stories.","zh":"學生閱讀詩或舊故事時，常會接觸艱深語言。"},{"en":"If difficult language is only tested, students may feel afraid of it.","zh":"如果艱深語言只用來考核，學生可能會害怕它。"},{"en":"The workshop helps students encounter difficult language through sound, movement, and teamwork.","zh":"工作坊幫助學生透過聲音、動作和團隊合作接觸艱深語言。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"be put off by","meaning":"對……卻步；被……嚇怕","examples":[{"en":"Many students are put off by poetry.","zh":"許多學生對詩歌卻步。"},{"en":"Be put off by means feel discouraged, frightened, or unwilling because of something.","zh":"be put off by 指因某事而感到氣餒、害怕或不願意嘗試。"},{"en":"Students may be put off by a long passage full of unknown words.","zh":"學生可能被滿是生字的長篇文章嚇怕。"},{"en":"If poetry seems too abstract, students may avoid it before trying.","zh":"如果詩歌看似太抽象，學生可能未嘗試前已避開它。"},{"en":"Performance can reduce this fear by making poetry more active and friendly.","zh":"表演可以透過令詩更主動和友善，減少這種恐懼。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"silently, alone and under pressure","meaning":"沉默地、獨自地、在壓力下","examples":[{"en":"Students often meet poetry silently, alone and under pressure.","zh":"學生常常沉默地、獨自地、在壓力下接觸詩歌。"},{"en":"Silently, alone and under pressure describes studying quietly by oneself while feeling stressed.","zh":"silently, alone and under pressure 形容一個人在緊張中安靜地獨自學習。"},{"en":"A student may read a poem silently, alone and under pressure before a test.","zh":"學生可能在測驗前沉默地、獨自地、在壓力下閱讀詩。"},{"en":"This situation can make poetry feel like a burden instead of an experience.","zh":"這種情況會令詩歌感覺像負擔，而不是體驗。"},{"en":"The workshop changes poetry from private pressure into shared discovery.","zh":"工作坊把詩歌由私人壓力變成共同探索。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"meaning develops naturally","meaning":"意義自然形成","examples":[{"en":"In the workshop, meaning develops naturally.","zh":"在工作坊中，意義會自然形成。"},{"en":"Meaning develops naturally means understanding grows gradually through activity, not through forced explanation.","zh":"meaning develops naturally 指理解透過活動逐漸增長，而不是被迫解釋出來。"},{"en":"Students may understand a poem naturally after hearing its rhythm several times.","zh":"學生多次聽到詩的節奏後，可能自然理解它。"},{"en":"Discussion and performance help meaning appear step by step.","zh":"討論和表演幫助意義一步步出現。"},{"en":"Natural understanding makes students feel less afraid of literary language.","zh":"自然理解令學生不那麼害怕文學語言。"}],"source":"2015 Q8.pdf","sourcePage":5},{"front":"first through rhythm","meaning":"首先透過節奏","examples":[{"en":"Students first understand the poem through rhythm.","zh":"學生首先透過節奏理解詩作。"},{"en":"First through rhythm means beginning understanding by hearing the beat, movement, or pattern of sound.","zh":"first through rhythm 指先透過聽見節拍、流動或聲音模式來開始理解。"},{"en":"A poem’s rhythm can tell students whether it feels quick, calm, playful, or tense.","zh":"詩的節奏可以告訴學生它感覺快速、平靜、俏皮還是緊張。"},{"en":"Rhythm gives students a way into meaning before they analyse every word.","zh":"在分析每個字之前，節奏先給學生進入意義的方法。"},{"en":"Starting with rhythm makes poetry less silent and more physical.","zh":"從節奏開始，令詩不那麼沉默，而更具身體感。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"then through discussion","meaning":"然後透過討論","examples":[{"en":"Meaning then develops through discussion.","zh":"意義然後透過討論形成。"},{"en":"Then through discussion means the next stage of understanding comes from talking with others.","zh":"then through discussion 指下一階段的理解來自與他人交談。"},{"en":"Students may discuss why one line sounds angry while another sounds sad.","zh":"學生可以討論為何某一句聽起來憤怒，而另一句聽起來悲傷。"},{"en":"Discussion helps students test ideas instead of keeping confusion private.","zh":"討論幫助學生檢視想法，而不是把困惑留在心裏。"},{"en":"Talking together turns poetry into a shared search for meaning.","zh":"一起討論把詩歌變成共同尋找意義的過程。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"through performance","meaning":"透過表演","examples":[{"en":"Students understand the poem through performance.","zh":"學生透過表演理解詩作。"},{"en":"Through performance means by acting, speaking, moving, or presenting the poem aloud.","zh":"through performance 指透過演出、朗讀、動作或公開展示來理解詩。"},{"en":"A student may understand a character’s fear through performing a trembling voice.","zh":"學生可能透過表演顫抖的聲音，理解角色的恐懼。"},{"en":"Performance forces students to decide how each line should sound.","zh":"表演迫使學生決定每一句應該如何聽起來。"},{"en":"This helps language become action rather than only text.","zh":"這幫助語言變成行動，而不只是文本。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"shy Form Three student","meaning":"害羞的中三學生","examples":[{"en":"A shy Form Three student may begin by reading only one line.","zh":"害羞的中三學生可能以朗讀一句詩開始。"},{"en":"A shy Form Three student is a quiet Secondary Three student who may feel nervous speaking publicly.","zh":"shy Form Three student 指一位安靜、可能害怕公開說話的中三學生。"},{"en":"Such a student may need a small role before joining a full performance.","zh":"這樣的學生可能需要先有一個小角色，再參與完整表演。"},{"en":"Starting with one line can help shy students build confidence safely.","zh":"從一句詩開始，可以幫助害羞學生安全地建立信心。"},{"en":"The example shows how the activity supports students with different confidence levels.","zh":"這個例子顯示活動如何支援不同信心水平的學生。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"begin by","meaning":"以……開始","examples":[{"en":"She may begin by reading only one line.","zh":"她可能以只朗讀一句詩開始。"},{"en":"Begin by means start with a first simple action before doing more.","zh":"begin by 指先用一個簡單動作開始，再逐步做更多。"},{"en":"A nervous speaker may begin by introducing herself in one sentence.","zh":"緊張的演講者可以先以一句自我介紹開始。"},{"en":"Beginning with a small task can make a difficult activity feel possible.","zh":"以小任務開始，可以令困難活動感覺變得可行。"},{"en":"In the workshop, students can begin by doing something manageable.","zh":"在工作坊中，學生可以先從能應付的事開始。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"after practising with teammates","meaning":"與隊友練習之後","examples":[{"en":"After practising with teammates, she may speak confidently.","zh":"與隊友練習之後，她可能會自信地說話。"},{"en":"After practising with teammates means following rehearsal and support from group members.","zh":"after practising with teammates 指在與小組成員排練和互相支援之後。"},{"en":"A student may feel braver after practising with teammates several times.","zh":"學生與隊友練習幾次後，可能會更勇敢。"},{"en":"Team practice reduces pressure because mistakes are shared and corrected together.","zh":"團隊練習能減低壓力，因為錯誤會一起分享和修正。"},{"en":"This shows how group work can help shy students grow.","zh":"這顯示小組合作如何幫助害羞學生成長。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"find herself speaking confidently","meaning":"發現自己自信地說話","examples":[{"en":"She may find herself speaking confidently before an audience.","zh":"她可能會發現自己在觀眾面前自信地說話。"},{"en":"Find herself speaking confidently means unexpectedly realise that she is speaking with confidence.","zh":"find herself speaking confidently 指意外地發現自己能有信心地說話。"},{"en":"After enough practice, a shy student may find herself answering clearly in class.","zh":"經過足夠練習後，害羞學生可能發現自己能在課堂上清楚回答。"},{"en":"Confidence can appear gradually when students are supported step by step.","zh":"當學生一步步得到支援，信心可以慢慢出現。"},{"en":"The workshop helps students discover abilities they did not know they had.","zh":"工作坊幫助學生發現自己原本不知道擁有的能力。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"before an audience","meaning":"在觀眾面前","examples":[{"en":"The student may speak confidently before an audience.","zh":"學生可能會在觀眾面前自信地說話。"},{"en":"Before an audience means in front of people who are watching or listening.","zh":"before an audience 指在觀看或聆聽的人面前。"},{"en":"Performing before an audience can feel frightening at first.","zh":"在觀眾面前表演起初可能令人害怕。"},{"en":"Students gain confidence when an audience responds warmly.","zh":"當觀眾作出溫暖回應，學生會建立信心。"},{"en":"Speaking before an audience turns private practice into public communication.","zh":"在觀眾面前說話，把私人練習變成公開溝通。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"the more..., the less...","meaning":"越……就越不……","examples":[{"en":"The more students create emotion, the less they see vocabulary as a burden.","zh":"學生越能創造情感，就越不會把詞彙視為負擔。"},{"en":"The more A, the less B means when A increases, B decreases.","zh":"the more A, the less B 指 A 增加時，B 就減少。"},{"en":"The more students read for fun, the less they fear long English passages.","zh":"學生越是為樂趣而閱讀，就越不害怕長篇英文文章。"},{"en":"This structure shows a clear relationship between two changes.","zh":"這個結構顯示兩個變化之間的清楚關係。"},{"en":"The more language feels creative, the less it feels like exam pressure.","zh":"語言越有創意感，就越不像考試壓力。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"create emotion","meaning":"創造情感","examples":[{"en":"Students use English to create emotion in performance.","zh":"學生在表演中用英語創造情感。"},{"en":"Create emotion means make listeners or readers feel something through language, sound, or action.","zh":"create emotion 指透過語言、聲音或行動令聽眾或讀者產生感受。"},{"en":"A performer can create emotion by lowering her voice during a sad line.","zh":"表演者可以在悲傷詩句中壓低聲音來創造情感。"},{"en":"Students understand poems better when they try to create emotion themselves.","zh":"當學生親自嘗試創造情感，他們會更理解詩。"},{"en":"This turns English from correct answers into expressive choices.","zh":"這把英語由正確答案變成表達選擇。"}],"source":"2015 Q8.pdf","sourcePage":6},{"front":"see vocabulary as","meaning":"把詞彙視為","examples":[{"en":"Students may stop seeing vocabulary as an examination burden.","zh":"學生可能不再把詞彙視為考試負擔。"},{"en":"See vocabulary as means regard words in a particular way.","zh":"see vocabulary as 指以某種方式看待詞彙。"},{"en":"Some students see vocabulary as a list to memorise, not a tool to use.","zh":"有些學生把詞彙視為要背誦的清單，而不是可使用的工具。"},{"en":"Performance helps students see vocabulary as sound, action, and feeling.","zh":"表演幫助學生把詞彙視為聲音、行動和感受。"},{"en":"Changing how students see vocabulary can change how they learn English.","zh":"改變學生看待詞彙的方式，可以改變他們學英語的方式。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"examination burden","meaning":"考試負擔","examples":[{"en":"Vocabulary should not feel like an examination burden.","zh":"詞彙不應感覺像考試負擔。"},{"en":"An examination burden is pressure caused by tests, marks, and memorisation.","zh":"examination burden 指由測驗、分數和背誦造成的壓力。"},{"en":"Students may feel vocabulary is an examination burden if they only meet words in quizzes.","zh":"如果學生只在小測中接觸詞彙，他們可能覺得詞彙是考試負擔。"},{"en":"Creative use can reduce this burden by giving words purpose and emotion.","zh":"創意使用可以透過給詞語目的和情感，減輕這種負擔。"},{"en":"The festival helps words feel useful instead of heavy.","zh":"藝術節幫助詞語感覺有用，而不是沉重。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, literary terms would become meaningful.","zh":"更重要的是，文學術語會變得有意義。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"more importantly 用來引出比前一點更重要的重點。"},{"en":"The game is fun; more importantly, it helps students practise speaking.","zh":"這個遊戲很有趣；更重要的是，它幫助學生練習說話。"},{"en":"This phrase helps writers organise ideas by importance.","zh":"這個片語幫助作者按重要性組織想法。"},{"en":"Here, it shows that learning literary terms through action is a key benefit.","zh":"在這裏，它顯示透過行動學習文學術語是一個重要好處。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"literary terms","meaning":"文學術語","examples":[{"en":"Literary terms would no longer be abstract labels.","zh":"文學術語將不再是抽象標籤。"},{"en":"Literary terms are words used to describe features of literature, such as tone, imagery, and rhythm.","zh":"literary terms 是用來描述文學特徵的詞語，例如語氣、意象和節奏。"},{"en":"Students learn literary terms to discuss how poems and stories create meaning.","zh":"學生學習文學術語，以討論詩和故事如何創造意義。"},{"en":"Literary terms become clearer when students use them in real reading or performance.","zh":"當學生在真實閱讀或表演中使用文學術語，它們會變得更清楚。"},{"en":"The workshop helps terms become practical tools rather than empty labels.","zh":"工作坊幫助術語變成實用工具，而不是空洞標籤。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"tone, alliteration and imagery","meaning":"語氣、頭韻和意象","examples":[{"en":"Students would learn tone, alliteration and imagery through performance.","zh":"學生會透過表演學習語氣、頭韻和意象。"},{"en":"Tone, alliteration and imagery are a text’s attitude, repeated beginning sounds, and picture-making language.","zh":"tone, alliteration and imagery 指文本的態度、重複開首音，以及製造畫面的語言。"},{"en":"A playful tone can be shown through a bright voice.","zh":"俏皮語氣可以透過明亮聲音表現出來。"},{"en":"Alliteration becomes easier to hear when repeated sounds are spoken aloud.","zh":"當重複聲音被讀出來，頭韻會更容易聽見。"},{"en":"Imagery becomes clearer when students turn word-pictures into movement.","zh":"當學生把文字畫面變成動作，意象會更清楚。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"no longer","meaning":"不再","examples":[{"en":"Literary terms would no longer be abstract labels.","zh":"文學術語將不再是抽象標籤。"},{"en":"No longer means something was true before but is not true now or later.","zh":"no longer 指某事以前是真實的，但現在或將來不再如此。"},{"en":"After practice, students may no longer fear speaking English.","zh":"練習後，學生可能不再害怕說英語。"},{"en":"If poetry becomes active, it is no longer only a difficult exam text.","zh":"如果詩歌變得主動，它就不再只是艱深考試文本。"},{"en":"The activity helps English feel no longer distant from students’ lives.","zh":"活動幫助英語感覺不再遠離學生生活。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"abstract labels","meaning":"抽象標籤","examples":[{"en":"Terms such as tone and imagery would not remain abstract labels.","zh":"語氣和意象等術語不會仍然只是抽象標籤。"},{"en":"Abstract labels are names or ideas that feel difficult because they are not connected to clear examples.","zh":"abstract labels 指沒有連接清楚例子、因而感覺難明的名稱或概念。"},{"en":"“Tone” may feel like an abstract label until students hear it in a voice.","zh":"「語氣」可能像抽象標籤，直到學生在聲音中聽見它。"},{"en":"Abstract labels become useful when students connect them to action and meaning.","zh":"當學生把抽象標籤連接到行動和意義，它們就變得有用。"},{"en":"Performance turns literary terms into things students can hear and feel.","zh":"表演把文學術語變成學生能聽見和感受的東西。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"decide whether","meaning":"決定是否","examples":[{"en":"Students decide whether a line should sound angry or playful.","zh":"學生決定某一句應聽起來憤怒還是俏皮。"},{"en":"Decide whether means make a choice between possible options.","zh":"decide whether 指在不同可能選項之間作出選擇。"},{"en":"A reader must decide whether a sentence sounds serious or joking.","zh":"讀者必須決定一句話聽起來是認真還是開玩笑。"},{"en":"When students decide how a line should sound, they analyse meaning actively.","zh":"當學生決定詩句應如何聽起來，他們就主動分析意思。"},{"en":"This decision makes literary study feel like performance, not memorisation.","zh":"這個決定令文學學習感覺像表演，而不是背誦。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"sound angry, playful or sorrowful","meaning":"聽起來憤怒、俏皮或悲傷","examples":[{"en":"A line may sound angry, playful or sorrowful.","zh":"一句詩可能聽起來憤怒、俏皮或悲傷。"},{"en":"Sound angry, playful or sorrowful means create feelings of anger, fun, or sadness through voice.","zh":"sound angry, playful or sorrowful 指透過聲音創造憤怒、有趣或悲傷的感覺。"},{"en":"The same line can sound playful if read quickly and sorrowful if read slowly.","zh":"同一句話讀得快可以聽起來俏皮，讀得慢可以聽起來悲傷。"},{"en":"Voice changes help students understand how tone affects meaning.","zh":"聲音變化幫助學生理解語氣如何影響意思。"},{"en":"Choosing the sound of a line turns reading into interpretation.","zh":"選擇一句詩如何聽起來，就是把閱讀變成演繹。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"analyse language","meaning":"分析語言","examples":[{"en":"Students are analysing language through performance.","zh":"學生正在透過表演分析語言。"},{"en":"Analyse language means study how words, sounds, structure, and meaning work.","zh":"analyse language 指研究字詞、聲音、結構和意思如何運作。"},{"en":"Students analyse language when they ask why a poet repeats a sound.","zh":"當學生問詩人為何重複某個聲音時，他們就是在分析語言。"},{"en":"Performance allows students to analyse language by testing voice and movement.","zh":"表演讓學生透過測試聲音和動作來分析語言。"},{"en":"This makes analysis active instead of only written.","zh":"這令分析變得主動，而不只是書面工作。"}],"source":"2015 Q8.pdf","sourcePage":7},{"front":"without feeling that","meaning":"而不覺得","examples":[{"en":"Students analyse language without feeling that they are doing another worksheet.","zh":"學生分析語言，而不覺得自己在做另一份工作紙。"},{"en":"Without feeling that means not having the impression or emotion that something is happening.","zh":"without feeling that 指沒有某種印象或感覺。"},{"en":"Students may practise speaking without feeling that they are being tested.","zh":"學生可能練習說話，而不覺得自己正在被考核。"},{"en":"If learning feels like a game, students may work hard without feeling bored.","zh":"如果學習感覺像遊戲，學生可能努力參與而不覺得沉悶。"},{"en":"The activity hides serious learning inside enjoyable action.","zh":"活動把認真的學習藏在愉快行動之中。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"complete another worksheet","meaning":"完成另一份工作紙","examples":[{"en":"Students should not feel that they are completing another worksheet.","zh":"學生不應覺得自己在完成另一份工作紙。"},{"en":"Complete another worksheet means finish one more written exercise sheet.","zh":"complete another worksheet 指完成又一份書面練習紙。"},{"en":"Students may feel tired if every English activity asks them to complete another worksheet.","zh":"如果每項英語活動都要求學生完成另一份工作紙，他們可能會感到疲倦。"},{"en":"Worksheets can practise skills, but too many may make language feel mechanical.","zh":"工作紙可以練習技巧，但太多工作紙會令語言感覺機械化。"},{"en":"The festival offers a different experience from ordinary worksheet-based learning.","zh":"藝術節提供有別於普通工作紙學習的經驗。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, poetry becomes something to be experienced.","zh":"換句話說，詩歌變成一種可以被體驗的東西。"},{"en":"In other words means the same idea is being explained again more clearly.","zh":"in other words 指用更清楚的方式重新解釋同一個想法。"},{"en":"She needs rest; in other words, she should not join another activity today.","zh":"她需要休息；換句話說，她今天不應再參加另一項活動。"},{"en":"Writers use this phrase to restate an important point simply.","zh":"作者用這個片語簡單重述重要觀點。"},{"en":"Here, it explains that poetry should be felt and performed, not only analysed.","zh":"在這裏，它解釋詩應被感受和表演，而不只是被分析。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"be experienced, not merely decoded","meaning":"被體驗，而不只是被解碼","examples":[{"en":"Poetry becomes something to be experienced, not merely decoded.","zh":"詩歌變成可以被體驗的東西，而不只是被解碼。"},{"en":"Be experienced, not merely decoded means be felt and lived through, not only translated or analysed word by word.","zh":"be experienced, not merely decoded 指被感受和經歷，而不只是逐字翻譯或分析。"},{"en":"A song should be experienced, not merely decoded through grammar notes.","zh":"一首歌應被體驗，而不只是透過文法筆記被解碼。"},{"en":"When students perform poems, they experience rhythm, mood, and voice directly.","zh":"當學生表演詩作，他們直接體驗節奏、情緒和聲音。"},{"en":"This phrase argues that literature should touch students, not only test them.","zh":"這個片語主張文學應觸動學生，而不只是考核學生。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"the second activity I propose","meaning":"我建議的第二項活動","examples":[{"en":"The second activity I propose is The Library Story Quest.","zh":"我建議的第二項活動是 The Library Story Quest。"},{"en":"The second activity I propose means the next suggested event in the proposal.","zh":"the second activity I propose 指建議書中的下一項建議活動。"},{"en":"The second activity I propose focuses on reading, clues, and teamwork.","zh":"我建議的第二項活動集中於閱讀、線索和團隊合作。"},{"en":"This phrase helps organise a formal proposal clearly.","zh":"這個片語幫助正式建議書有清楚組織。"},{"en":"It signals that the writer is moving from poetry performance to a library treasure hunt.","zh":"它顯示作者正由詩歌表演轉向圖書館尋寶活動。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"interactive treasure hunt","meaning":"互動尋寶遊戲","examples":[{"en":"The Library Story Quest would be an interactive treasure hunt.","zh":"The Library Story Quest 會是一個互動尋寶遊戲。"},{"en":"An interactive treasure hunt is a game where participants solve tasks and search for clues by taking action.","zh":"interactive treasure hunt 是參加者透過行動解任務和尋找線索的遊戲。"},{"en":"Students may move between stations to answer questions and collect clues.","zh":"學生可能在不同站點之間移動，回答問題並收集線索。"},{"en":"The interactive nature keeps students reading, listening, speaking, and moving.","zh":"互動性令學生持續閱讀、聆聽、說話和走動。"},{"en":"This makes English useful because it helps teams complete the quest.","zh":"這令英語變得有用，因為它幫助小隊完成任務。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"different zones of the Central Library","meaning":"中央圖書館的不同區域","examples":[{"en":"The treasure hunt would use different zones of the Central Library.","zh":"尋寶遊戲會使用中央圖書館的不同區域。"},{"en":"Different zones of the Central Library means separate areas or sections inside the library building.","zh":"different zones of the Central Library 指圖書館大樓內不同的範圍或部分。"},{"en":"Teams might visit the children’s library, reading area, exhibition space, and reference section.","zh":"小隊可能到訪兒童圖書館、閱讀區、展覽空間和參考資料區。"},{"en":"Using different zones encourages students to explore the library actively.","zh":"使用不同區域鼓勵學生主動探索圖書館。"},{"en":"The library becomes part of the story instead of just a background.","zh":"圖書館成為故事的一部分，而不只是背景。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"upon registration","meaning":"登記後","examples":[{"en":"Upon registration, teams would receive a booklet.","zh":"登記後，小隊會收到一本小冊子。"},{"en":"Upon registration means immediately after signing up or checking in for an activity.","zh":"upon registration 指報名或登記活動後立即。"},{"en":"Upon registration, participants may receive name tags and instructions.","zh":"登記後，參加者可能會收到名牌和指示。"},{"en":"This phrase is common in formal event descriptions.","zh":"這個片語常見於正式活動描述。"},{"en":"In the quest, registration begins the game by giving teams their story booklet.","zh":"在尋寶遊戲中，登記透過給小隊故事小冊子來開始遊戲。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"teams of four","meaning":"四人小隊","examples":[{"en":"Teams of four would receive a missing ending booklet.","zh":"四人小隊會收到一本缺失結局小冊子。"},{"en":"Teams of four are groups with four members each.","zh":"teams of four 指每組有四名成員的小隊。"},{"en":"Teams of four allow students to share reading, writing, speaking, and drawing tasks.","zh":"四人小隊讓學生分擔閱讀、寫作、說話和繪圖任務。"},{"en":"Four-person teams are small enough for everyone to take part.","zh":"四人小隊夠小，能讓每個人參與。"},{"en":"This grouping supports cooperation without making shy students feel too exposed.","zh":"這種分組支援合作，同時不會令害羞學生太暴露。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"missing ending booklet","meaning":"缺失結局小冊子","examples":[{"en":"Each team would receive a missing ending booklet.","zh":"每隊會收到一本缺失結局小冊子。"},{"en":"A missing ending booklet is a small book containing a story whose ending is incomplete.","zh":"missing ending booklet 是一本包含結局未完成故事的小冊子。"},{"en":"Students must read the booklet carefully to understand what is missing.","zh":"學生必須仔細閱讀小冊子，理解缺少了甚麼。"},{"en":"A missing ending gives teams a clear reason to collect clues and write.","zh":"缺失結局給小隊明確理由去收集線索和寫作。"},{"en":"The booklet turns reading into a mission rather than a passive task.","zh":"小冊子把閱讀變成任務，而不是被動工作。"}],"source":"2015 Q8.pdf","sourcePage":8},{"front":"short detective story","meaning":"短篇偵探故事","examples":[{"en":"The booklet would contain a short detective story.","zh":"小冊子會包含一個短篇偵探故事。"},{"en":"A short detective story is a brief mystery story about solving a crime or puzzle.","zh":"short detective story 是關於破解罪案或謎團的簡短神秘故事。"},{"en":"A detective story usually includes clues, suspects, motives, and a solution.","zh":"偵探故事通常包括線索、嫌疑人、動機和解答。"},{"en":"Students enjoy detective stories because they invite guessing and reasoning.","zh":"學生喜歡偵探故事，因為它邀請人猜測和推理。"},{"en":"A short detective story is suitable for a festival because it gives reading a purpose.","zh":"短篇偵探故事適合藝術節，因為它給閱讀一個目的。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"clues have disappeared","meaning":"線索消失了","examples":[{"en":"The story contains several clues that have disappeared.","zh":"故事包含幾條已經消失的線索。"},{"en":"Clues have disappeared means important pieces of information are missing from the story.","zh":"clues have disappeared 指重要資料從故事中不見了。"},{"en":"If clues disappear, readers cannot solve the mystery immediately.","zh":"如果線索消失，讀者就不能立刻破解謎團。"},{"en":"Missing clues make students search, read, listen, and discuss more actively.","zh":"缺失線索令學生更主動地搜尋、閱讀、聆聽和討論。"},{"en":"The disappeared clues create the reason for the treasure hunt.","zh":"消失的線索創造了尋寶遊戲的理由。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"recover them","meaning":"找回它們","examples":[{"en":"Participants must recover the missing clues.","zh":"參加者必須找回缺失的線索。"},{"en":"Recover them means find or get back things that were lost or missing.","zh":"recover them 指找回或取回遺失的東西。"},{"en":"A team may recover missing words by solving a puzzle at each station.","zh":"小隊可以透過在每個站點解謎，找回缺失字詞。"},{"en":"Recovering clues helps students understand the story step by step.","zh":"找回線索幫助學生一步步理解故事。"},{"en":"This task makes reading feel like investigation.","zh":"這項任務令閱讀感覺像調查。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"visit stations around the library","meaning":"到訪圖書館各個站點","examples":[{"en":"Participants would visit stations around the library.","zh":"參加者會到訪圖書館各個站點。"},{"en":"Visit stations around the library means go to different activity points inside the library.","zh":"visit stations around the library 指前往圖書館內不同活動點。"},{"en":"A team may visit one station for listening and another for writing.","zh":"小隊可能到一個站點聆聽，再到另一個站點寫作。"},{"en":"Moving between stations keeps students active and curious.","zh":"在站點之間移動能讓學生保持主動和好奇。"},{"en":"The activity helps students discover different parts of the library while using English.","zh":"活動幫助學生在使用英語的同時，發現圖書館不同地方。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"solve an idiom puzzle","meaning":"解開成語謎題","examples":[{"en":"One station could ask students to solve an idiom puzzle.","zh":"其中一個站點可以要求學生解開成語謎題。"},{"en":"Solve an idiom puzzle means work out the meaning or missing part of a fixed expression.","zh":"solve an idiom puzzle 指推斷固定表達的意思或缺失部分。"},{"en":"Students may match “break the ice” with a situation where people begin talking.","zh":"學生可以把 “break the ice” 配對到人們開始交談的情境。"},{"en":"Idiom puzzles help learners understand expressions through context.","zh":"成語謎題幫助學習者透過語境理解表達。"},{"en":"Solving the puzzle makes vocabulary feel like discovery rather than memorisation.","zh":"解開謎題令詞彙感覺像探索，而不是背誦。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"listen to a ninety-second conversation","meaning":"聽一段九十秒對話","examples":[{"en":"Students may listen to a ninety-second conversation for clues.","zh":"學生可能要聽一段九十秒對話來尋找線索。"},{"en":"Listen to a ninety-second conversation means hear a short dialogue lasting about one and a half minutes.","zh":"listen to a ninety-second conversation 指聆聽一段約一分半鐘的短對話。"},{"en":"Students must listen carefully for names, motives, times, or places.","zh":"學生必須仔細聽名字、動機、時間或地點。"},{"en":"A short conversation keeps the task manageable but meaningful.","zh":"短對話令任務容易掌握，但仍有意義。"},{"en":"Listening becomes purposeful because students need evidence to finish the story.","zh":"聆聽變得有目的，因為學生需要證據完成故事。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"match book blurbs with character motives","meaning":"把書籍簡介與角色動機配對","examples":[{"en":"Students could match book blurbs with character motives.","zh":"學生可以把書籍簡介與角色動機配對。"},{"en":"Match book blurbs with character motives means connect short book descriptions with reasons why characters act.","zh":"match book blurbs with character motives 指把簡短書籍描述和角色行動原因連接起來。"},{"en":"A blurb about jealousy may match a character who wants revenge.","zh":"關於嫉妒的簡介可能配對到想報復的角色。"},{"en":"This task trains students to infer meaning, not just copy words.","zh":"這項任務訓練學生推斷意思，而不是只抄字。"},{"en":"Matching blurbs and motives helps students read between the lines.","zh":"配對簡介和動機幫助學生讀出字裏行間的意思。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"book blurbs","meaning":"書籍簡介","examples":[{"en":"Book blurbs can help students infer character motives.","zh":"書籍簡介可以幫助學生推斷角色動機。"},{"en":"Book blurbs are short descriptions on or about books that introduce the story and attract readers.","zh":"book blurbs 是介紹故事並吸引讀者的簡短書籍描述。"},{"en":"A book blurb may mention the main problem, setting, or mystery.","zh":"書籍簡介可能提到主要問題、背景或謎團。"},{"en":"Students can use blurbs to guess what a character wants or fears.","zh":"學生可以用簡介猜測角色想要甚麼或害怕甚麼。"},{"en":"Reading blurbs is a useful way to practise quick understanding.","zh":"閱讀簡介是練習快速理解的有用方法。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"character motives","meaning":"角色動機","examples":[{"en":"Students would match the blurbs with character motives.","zh":"學生會把簡介與角色動機配對。"},{"en":"Character motives are the reasons why characters think, speak, or act in a story.","zh":"character motives 指故事中角色思考、說話或行動的原因。"},{"en":"A detective asks about character motives to understand who may have lied.","zh":"偵探會詢問角色動機，以了解誰可能說謊。"},{"en":"If students understand motives, they can predict what may happen next.","zh":"如果學生理解動機，他們就能預測接下來可能發生甚麼。"},{"en":"Motives make stories more logical and human.","zh":"動機令故事更合邏輯，也更有人性。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"compose a four-line clue","meaning":"創作四行線索","examples":[{"en":"Participants would compose a four-line clue.","zh":"參加者會創作四行線索。"},{"en":"Compose a four-line clue means write a clue using four short lines.","zh":"compose a four-line clue 指用四行短句寫出一條線索。"},{"en":"Students may write a four-line clue that points to a hidden book title.","zh":"學生可以寫一條四行線索，指向一個隱藏書名。"},{"en":"Limiting the clue to four lines helps students write clearly and carefully.","zh":"把線索限制在四行內，能幫助學生寫得清楚而仔細。"},{"en":"This task combines creative writing with problem-solving.","zh":"這項任務結合創意寫作和解難。"}],"source":"2015 Q8.pdf","sourcePage":9},{"front":"after collecting the clues","meaning":"收集線索後","examples":[{"en":"After collecting the clues, each team would write its own ending.","zh":"收集線索後，每隊會寫出自己的結局。"},{"en":"After collecting the clues means once all the needed hints or evidence have been gathered.","zh":"after collecting the clues 指在收集到所有需要的提示或證據之後。"},{"en":"After collecting the clues, detectives can decide which suspect is most likely guilty.","zh":"收集線索後，偵探可以判斷哪名嫌疑人最可能有罪。"},{"en":"This phrase shows that writing comes after reading, listening, and reasoning.","zh":"這個片語顯示寫作是在閱讀、聆聽和推理之後發生。"},{"en":"The ending becomes earned because students have evidence to use.","zh":"因為學生有證據可用，結局就會更有根據。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"write its own ending","meaning":"寫出自己的結局","examples":[{"en":"Each team would write its own ending to the detective story.","zh":"每隊會為偵探故事寫出自己的結局。"},{"en":"Write its own ending means create a final part of the story using the team’s ideas.","zh":"write its own ending 指用小隊自己的想法創作故事最後部分。"},{"en":"A group may write an ending where the quiet librarian solves the mystery.","zh":"小組可能寫出一個由安靜圖書館員破解謎團的結局。"},{"en":"Writing their own endings lets students use imagination and evidence together.","zh":"寫自己的結局讓學生把想像和證據結合起來。"},{"en":"This makes students co-creators of the story, not just readers.","zh":"這令學生成為故事的共同創作者，而不只是讀者。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"present it in sixty seconds","meaning":"在六十秒內匯報","examples":[{"en":"Each team would present its ending in sixty seconds.","zh":"每隊會在六十秒內匯報自己的結局。"},{"en":"Present it in sixty seconds means explain or perform it within one minute.","zh":"present it in sixty seconds 指在一分鐘內解釋或表演它。"},{"en":"A short time limit forces students to choose the clearest details.","zh":"短時間限制迫使學生選擇最清楚的細節。"},{"en":"Students practise speaking skills when they present ideas briefly and confidently.","zh":"學生簡短而自信地匯報想法時，會練習說話技巧。"},{"en":"Sixty seconds is short enough to feel manageable but long enough to share a story ending.","zh":"六十秒短得容易掌握，但也足夠分享故事結局。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"Publisher’s Desk","meaning":"出版人工作枱","examples":[{"en":"The teams would present their endings at the Publisher’s Desk.","zh":"小隊會在出版人工作枱匯報自己的結局。"},{"en":"The Publisher’s Desk is a themed station where teams share or submit their finished story endings.","zh":"Publisher’s Desk 是一個主題站點，讓小隊分享或提交完成的故事結局。"},{"en":"Calling the station a Publisher’s Desk makes the activity feel like real writing work.","zh":"把站點稱為出版人工作枱，令活動感覺像真正寫作工作。"},{"en":"Students may feel proud when they present their ending as if to a publisher.","zh":"當學生像向出版人匯報一樣呈現結局，他們可能會感到自豪。"},{"en":"This station gives the quest a clear final destination.","zh":"這個站點給尋寶遊戲一個清楚終點。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"make English purposeful","meaning":"令英語有目的","examples":[{"en":"This quest would make English purposeful.","zh":"這個尋寶任務會令英語有目的。"},{"en":"Make English purposeful means give students a clear reason to use English.","zh":"make English purposeful 指給學生清楚理由去使用英語。"},{"en":"English becomes purposeful when students need it to find clues or persuade teammates.","zh":"當學生需要英語尋找線索或說服隊友，英語就變得有目的。"},{"en":"A purposeful task helps students focus on communication, not only accuracy.","zh":"有目的的任務幫助學生集中於溝通，而不只是準確。"},{"en":"The quest makes English useful because every language skill helps complete the mission.","zh":"尋寶任務令英語有用，因為每項語言技能都幫助完成任務。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"that is why it would be powerful","meaning":"這就是它有力量的原因","examples":[{"en":"The activity is purposeful, and that is why it would be powerful.","zh":"這項活動有目的，這就是它有力量的原因。"},{"en":"That is why it would be powerful means this is the reason the activity would have a strong effect.","zh":"that is why it would be powerful 指這就是活動會產生強大效果的原因。"},{"en":"A reading game gives students a goal; that is why it can be powerful.","zh":"閱讀遊戲給學生一個目標；這就是它有力量的原因。"},{"en":"When learners understand why they are using language, motivation becomes stronger.","zh":"當學習者明白自己為何使用語言，動機會更強。"},{"en":"The quest is powerful because English becomes necessary to finish the story.","zh":"尋寶任務有力量，因為英語成為完成故事所必需的東西。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"read because they wanted clues","meaning":"因為想找線索而閱讀","examples":[{"en":"Students would read because they wanted clues.","zh":"學生會因為想找線索而閱讀。"},{"en":"Read because they wanted clues means reading is driven by a real purpose, not only by instruction.","zh":"read because they wanted clues 指閱讀由真正目的推動，而不只是因為指示。"},{"en":"In a mystery game, students read carefully to find what happened.","zh":"在神秘遊戲中，學生會仔細閱讀以找出發生了甚麼。"},{"en":"Wanting clues makes students notice details they might usually skip.","zh":"想找線索會令學生留意平時可能跳過的細節。"},{"en":"Purposeful reading can make English feel active and exciting.","zh":"有目的的閱讀能令英語感覺主動而刺激。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"listen because they needed evidence","meaning":"因為需要證據而聆聽","examples":[{"en":"Students would listen because they needed evidence.","zh":"學生會因為需要證據而聆聽。"},{"en":"Listen because they needed evidence means students pay attention because the information helps prove or solve something.","zh":"listen because they needed evidence 指學生因資料能證明或解決某事而專心聽。"},{"en":"In a detective task, one short conversation may contain the missing fact.","zh":"在偵探任務中，一段短對話可能包含缺失事實。"},{"en":"Needing evidence makes listening practical rather than passive.","zh":"需要證據令聆聽變得實際，而不是被動。"},{"en":"This kind of listening trains students to catch meaning, not just sound.","zh":"這種聆聽訓練學生捕捉意思，而不只是聲音。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"teammates depended on them","meaning":"隊友依靠他們","examples":[{"en":"They would speak because their teammates depended on them.","zh":"他們會說話，因為隊友依靠他們。"},{"en":"Teammates depended on them means other group members needed their help or contribution.","zh":"teammates depended on them 指其他小組成員需要他們的幫助或貢獻。"},{"en":"A quiet student may speak up when teammates depend on her clue.","zh":"當隊友依靠她手上的線索，安靜學生可能會開口說話。"},{"en":"Team dependence gives students a real reason to communicate clearly.","zh":"團隊依靠給學生清楚溝通的真實理由。"},{"en":"This makes speaking less like performance pressure and more like useful teamwork.","zh":"這令說話不像表演壓力，而更像有用的團隊合作。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"could not be completed without","meaning":"沒有……就不能完成","examples":[{"en":"The story could not be completed without their imagination.","zh":"沒有他們的想像力，故事就不能完成。"},{"en":"Could not be completed without means something cannot be finished unless a certain thing is included.","zh":"could not be completed without 指如果沒有某物，某事就無法完成。"},{"en":"The map could not be completed without the missing street names.","zh":"沒有缺失街名，地圖就不能完成。"},{"en":"A group story cannot be completed without each member’s ideas.","zh":"沒有每位成員的想法，小組故事就不能完成。"},{"en":"This phrase shows students that their imagination is necessary, not extra.","zh":"這個片語顯示學生的想像力是必要的，而不是額外的。"}],"source":"2015 Q8.pdf","sourcePage":10},{"front":"suit students of different abilities","meaning":"適合不同能力的學生","examples":[{"en":"The activity would suit students of different abilities.","zh":"這項活動會適合不同能力的學生。"},{"en":"Suit students of different abilities means be appropriate for learners with different skill levels.","zh":"suit students of different abilities 指適合不同技能水平的學習者。"},{"en":"Stronger students may write complex endings, while others may find clues or draw maps.","zh":"能力較強的學生可以寫複雜結局，其他學生可以找線索或畫地圖。"},{"en":"A suitable activity lets every student contribute meaningfully.","zh":"合適活動讓每位學生都有意義地貢獻。"},{"en":"This makes the quest inclusive rather than only useful for confident students.","zh":"這令尋寶任務具共融性，而不只是適合自信學生。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"stronger students","meaning":"能力較強的學生","examples":[{"en":"Stronger students could craft elegant endings.","zh":"能力較強的學生可以寫出優雅的結局。"},{"en":"Stronger students are students with higher confidence or skill in a particular area.","zh":"stronger students 指在某方面較有信心或能力較高的學生。"},{"en":"Stronger students may lead writing, explain clues, or polish the final presentation.","zh":"能力較強的學生可以帶領寫作、解釋線索或修飾最後匯報。"},{"en":"Giving stronger students challenging tasks keeps them engaged.","zh":"給能力較強的學生有挑戰性的任務，可以保持他們投入。"},{"en":"They can support teammates without taking over the whole activity.","zh":"他們可以支援隊友，而不必主導整個活動。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"craft elegant endings","meaning":"寫出優雅的結局","examples":[{"en":"Stronger students could craft elegant endings.","zh":"能力較強的學生可以寫出優雅的結局。"},{"en":"Craft elegant endings means write endings carefully, beautifully, and logically.","zh":"craft elegant endings 指細心、優美而合邏輯地寫出結局。"},{"en":"An elegant ending solves the mystery while still surprising the reader.","zh":"優雅的結局會解開謎團，同時仍令讀者驚喜。"},{"en":"Students craft better endings when they connect clues with character motives.","zh":"當學生把線索與角色動機連接起來，他們就能寫出更好的結局。"},{"en":"This task challenges stronger writers to combine style with structure.","zh":"這項任務挑戰能力較強的作者結合風格和結構。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"less confident students","meaning":"較缺乏信心的學生","examples":[{"en":"Less confident students could contribute in other ways.","zh":"較缺乏信心的學生可以用其他方式作出貢獻。"},{"en":"Less confident students are students who may feel unsure about their English or public speaking.","zh":"less confident students 指對英語或公開說話較不肯定的學生。"},{"en":"Less confident students may prefer spotting key words before presenting aloud.","zh":"較缺乏信心的學生可能較喜歡先找關鍵詞，再公開匯報。"},{"en":"Good activities give these students safe ways to help the team.","zh":"好活動會給這些學生安全方法去幫助小隊。"},{"en":"The quest values different strengths, so confidence can grow gradually.","zh":"尋寶任務重視不同長處，所以信心可以慢慢增長。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"contribute by","meaning":"透過……作出貢獻","examples":[{"en":"Less confident students could contribute by spotting key words.","zh":"較缺乏信心的學生可以透過找出關鍵詞作出貢獻。"},{"en":"Contribute by means help a task or group through a particular action.","zh":"contribute by 指透過某個具體行動幫助任務或小組。"},{"en":"A quiet student can contribute by drawing the team’s map.","zh":"安靜學生可以透過繪畫小隊地圖作出貢獻。"},{"en":"Students feel included when there are several ways to contribute.","zh":"當有多種貢獻方式，學生會感到被包括在內。"},{"en":"This phrase shows that contribution does not only mean speaking loudly.","zh":"這個片語顯示貢獻不只是大聲說話。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"spotting key words","meaning":"找出關鍵詞","examples":[{"en":"Some students could contribute by spotting key words.","zh":"有些學生可以透過找出關鍵詞作出貢獻。"},{"en":"Spotting key words means noticing important words that help understanding or problem-solving.","zh":"spotting key words 指留意有助理解或解難的重要字詞。"},{"en":"In a detective story, words like “before midnight” may be key words.","zh":"在偵探故事中，“before midnight” 這類詞可能是關鍵詞。"},{"en":"Spotting key words helps teams find clues more quickly.","zh":"找出關鍵詞幫助小隊更快發現線索。"},{"en":"This skill is useful for exams, reading, and real communication.","zh":"這項技能對考試、閱讀和真實溝通都有用。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"drawing maps","meaning":"繪畫地圖","examples":[{"en":"Students could contribute by drawing maps.","zh":"學生可以透過繪畫地圖作出貢獻。"},{"en":"Drawing maps means creating visual plans that show places, routes, or relationships.","zh":"drawing maps 指製作顯示地方、路線或關係的視覺圖。"},{"en":"A team may draw a map of library stations to track where clues were found.","zh":"小隊可以畫一張圖書館站點地圖，記錄線索在哪裏找到。"},{"en":"Drawing maps helps visual learners understand the quest more clearly.","zh":"繪畫地圖幫助視覺型學習者更清楚理解任務。"},{"en":"This role allows students with artistic or spatial skills to contribute.","zh":"這個角色讓有藝術或空間能力的學生作出貢獻。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"reading short dialogues","meaning":"朗讀短對話","examples":[{"en":"Students could help by reading short dialogues.","zh":"學生可以透過朗讀短對話來幫忙。"},{"en":"Reading short dialogues means speaking brief conversations aloud, often in roles.","zh":"reading short dialogues 指把簡短對話讀出來，通常會分角色。"},{"en":"Two students may read a detective and witness dialogue at a station.","zh":"兩名學生可以在站點朗讀偵探和目擊者的對話。"},{"en":"Short dialogues are less frightening than long speeches for shy students.","zh":"對害羞學生來說，短對話比長演說不那麼可怕。"},{"en":"This task practises pronunciation, tone, and listening at the same time.","zh":"這項任務同時練習發音、語氣和聆聽。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"word banks","meaning":"詞彙庫","examples":[{"en":"Word banks would support less confident students.","zh":"詞彙庫會支援較缺乏信心的學生。"},{"en":"Word banks are lists of useful words or phrases that help students speak or write.","zh":"word banks 是幫助學生說話或寫作的實用字詞清單。"},{"en":"A word bank for detective stories may include “suspect,” “motive,” and “evidence.”","zh":"偵探故事詞彙庫可能包括 “suspect”、“motive” 和 “evidence”。"},{"en":"Word banks reduce fear because students do not need to think of every word alone.","zh":"詞彙庫減少恐懼，因為學生不用獨自想出所有字。"},{"en":"They help weaker students join the same task with more confidence.","zh":"它們幫助能力較弱的學生更有信心參與同一任務。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"sentence starters","meaning":"句子開首提示","examples":[{"en":"Sentence starters could help students begin writing.","zh":"句子開首提示可以幫助學生開始寫作。"},{"en":"Sentence starters are opening phrases that help students start a sentence or paragraph.","zh":"sentence starters 是幫助學生開始句子或段落的開首片語。"},{"en":"Examples include “We believe that…” and “The clue suggests…”.","zh":"例子包括 “We believe that…” 和 “The clue suggests…”。"},{"en":"Sentence starters help students who feel stuck in front of a blank page.","zh":"句子開首提示幫助面對空白頁時卡住的學生。"},{"en":"They support writing without taking away students’ own ideas.","zh":"它們支援寫作，但不會取走學生自己的想法。"}],"source":"2015 Q8.pdf","sourcePage":11},{"front":"QR-code audio support","meaning":"QR code 音訊支援","examples":[{"en":"QR-code audio support would help students with listening.","zh":"QR code 音訊支援會幫助學生聆聽。"},{"en":"QR-code audio support means students scan a code to hear recorded instructions, clues, or pronunciation.","zh":"QR-code audio support 指學生掃描代碼來聽錄音指示、線索或發音。"},{"en":"A student can scan a QR code to replay a conversation at a station.","zh":"學生可以掃描 QR code，重聽站點的一段對話。"},{"en":"Audio support helps students who need to hear English more than once.","zh":"音訊支援幫助需要多聽一次英語的學生。"},{"en":"This makes the activity fairer for students with different listening abilities.","zh":"這令活動對不同聆聽能力的學生更公平。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"few, if any","meaning":"即使有也很少","examples":[{"en":"Few, if any, participants would be left helpless.","zh":"即使有，也很少參加者會被留下無助。"},{"en":"Few, if any means almost none, or possibly none at all.","zh":"few, if any 指幾乎沒有，甚至可能完全沒有。"},{"en":"With clear instructions, few, if any, students will misunderstand the task.","zh":"有清楚指示時，即使有，也很少學生會誤解任務。"},{"en":"This phrase is useful when a writer wants to make a careful, not absolute, claim.","zh":"當作者想作出謹慎而非絕對的說法時，這個片語很有用。"},{"en":"Support tools mean very few students should feel unable to take part.","zh":"支援工具意味很少學生會覺得自己無法參與。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"be left staring helplessly at","meaning":"被留下無助地望着","examples":[{"en":"Few students would be left staring helplessly at a blank page.","zh":"很少學生會被留下無助地望着空白頁。"},{"en":"Be left staring helplessly at means be stuck looking at something without knowing what to do.","zh":"be left staring helplessly at 指被困在望着某物而不知道怎樣做的狀態。"},{"en":"A student may be left staring helplessly at an essay question without examples.","zh":"如果沒有例子，學生可能會無助地望着作文題目。"},{"en":"Sentence starters prevent students from feeling frozen before writing.","zh":"句子開首提示防止學生在寫作前僵住。"},{"en":"Good support helps students begin instead of giving up.","zh":"好支援幫助學生開始，而不是放棄。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"a blank page","meaning":"空白頁","examples":[{"en":"Sentence starters can help students face a blank page.","zh":"句子開首提示可以幫助學生面對空白頁。"},{"en":"A blank page is an empty sheet or screen where nothing has been written yet.","zh":"a blank page 指尚未寫上任何東西的空白紙張或螢幕。"},{"en":"Many writers feel nervous when they see a blank page.","zh":"許多作者看見空白頁時會感到緊張。"},{"en":"A blank page feels less frightening when students have clues and useful phrases.","zh":"當學生有線索和實用片語，空白頁就不那麼可怕。"},{"en":"The activity gives students enough support to turn a blank page into a story ending.","zh":"活動給學生足夠支援，把空白頁變成故事結局。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, the quest would introduce students to the library itself.","zh":"此外，尋寶任務會向學生介紹圖書館本身。"},{"en":"In addition means also, or as another point.","zh":"in addition 指此外，也就是另一點。"},{"en":"The workshop improves speaking; in addition, it builds teamwork.","zh":"工作坊改善說話能力；此外，它建立團隊合作。"},{"en":"This phrase helps writers add another benefit clearly.","zh":"這個片語幫助作者清楚加入另一個好處。"},{"en":"Here, it introduces the library-learning value of the treasure hunt.","zh":"在這裏，它引入尋寶遊戲對認識圖書館的價值。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"introduce students to","meaning":"向學生介紹","examples":[{"en":"The quest would introduce students to the Central Library.","zh":"尋寶任務會向學生介紹中央圖書館。"},{"en":"Introduce students to means help students become familiar with something new.","zh":"introduce students to 指幫助學生熟悉某個新事物。"},{"en":"A teacher may introduce students to Shakespeare through short scenes.","zh":"老師可能透過短場景向學生介紹莎士比亞。"},{"en":"The quest introduces the library by making students move through its different areas.","zh":"尋寶任務透過讓學生走過不同區域來介紹圖書館。"},{"en":"Students may return later if the activity makes the library feel welcoming.","zh":"如果活動令圖書館感覺歡迎人，學生日後可能會再回來。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"the library itself","meaning":"圖書館本身","examples":[{"en":"The activity would introduce students to the library itself.","zh":"這項活動會向學生介紹圖書館本身。"},{"en":"The library itself means the actual library as a place, not only the books inside it.","zh":"the library itself 指實際的圖書館這個地方，而不只是裏面的書。"},{"en":"Students may discover reading rooms, service counters, displays, and quiet corners.","zh":"學生可能發現閱讀室、服務櫃枱、展示區和安靜角落。"},{"en":"Knowing the library itself helps students feel more comfortable using it later.","zh":"認識圖書館本身，能幫助學生日後更自在地使用它。"},{"en":"The quest turns the library building into a learning environment.","zh":"尋寶任務把圖書館建築變成學習環境。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"a silent warehouse of books","meaning":"沉默的書本倉庫","examples":[{"en":"The Central Library is not a silent warehouse of books.","zh":"中央圖書館不是一個沉默的書本倉庫。"},{"en":"A silent warehouse of books means a lifeless place where books are only stored quietly.","zh":"a silent warehouse of books 指只安靜存放書本、缺乏生命力的地方。"},{"en":"Some students may imagine libraries as silent warehouses of books before visiting them actively.","zh":"有些學生在主動到訪前，可能把圖書館想像成沉默的書本倉庫。"},{"en":"Interactive activities show that a library can be full of stories, questions, and discovery.","zh":"互動活動顯示圖書館可以充滿故事、問題和探索。"},{"en":"This phrase rejects the idea that libraries are boring storage spaces.","zh":"這個片語否定圖書館只是沉悶儲存空間的想法。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"stories begin","meaning":"故事開始","examples":[{"en":"The library is a place where stories begin.","zh":"圖書館是故事開始的地方。"},{"en":"Stories begin means ideas for stories start or come to life there.","zh":"stories begin 指故事的想法在那裏開始或變得有生命。"},{"en":"A child may find a picture book and feel a new story begin in her mind.","zh":"孩子可能找到一本圖畫書，感到一個新故事在腦中開始。"},{"en":"Libraries help stories begin by giving readers books, space, and curiosity.","zh":"圖書館透過提供書本、空間和好奇心，幫助故事開始。"},{"en":"The quest makes students feel that they can begin stories too.","zh":"尋寶任務令學生覺得自己也可以開始故事。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"questions grow","meaning":"問題滋長","examples":[{"en":"The library is a place where questions grow.","zh":"圖書館是問題滋長的地方。"},{"en":"Questions grow means curiosity becomes stronger and leads to more thinking.","zh":"questions grow 指好奇心變得更強，並帶來更多思考。"},{"en":"A student may enter with one question about history and leave with five more.","zh":"學生可能帶着一個歷史問題進入，離開時多了五個問題。"},{"en":"Good libraries encourage questions instead of only giving quick answers.","zh":"好圖書館鼓勵提問，而不只是提供快速答案。"},{"en":"The quest helps questions grow by making students search for clues.","zh":"尋寶任務透過讓學生尋找線索，幫助問題滋長。"}],"source":"2015 Q8.pdf","sourcePage":12},{"front":"curiosity is rewarded","meaning":"好奇心得到回報","examples":[{"en":"The library is a place where curiosity is rewarded.","zh":"圖書館是好奇心得到回報的地方。"},{"en":"Curiosity is rewarded means asking questions and exploring lead to useful discoveries.","zh":"curiosity is rewarded 指提問和探索會帶來有用發現。"},{"en":"A student who searches the shelves may discover a book that changes her interest.","zh":"搜尋書架的學生可能發現一本改變她興趣的書。"},{"en":"In the quest, curious teams find clues and move closer to the ending.","zh":"在尋寶任務中，好奇的小隊會找到線索並更接近結局。"},{"en":"This makes the library feel like a place where effort and wonder matter.","zh":"這令圖書館感覺像一個努力和驚奇都重要的地方。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, the two activities serve the same purpose.","zh":"總括而言，兩項活動達到相同目的。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 指在思考所有重要因素之後。"},{"en":"All things considered, the festival should include both performance and problem-solving.","zh":"總括而言，藝術節應包括表演和解難。"},{"en":"This phrase is useful near the end of a proposal to give a final judgement.","zh":"這個片語在建議書結尾附近很有用，可提出最終判斷。"},{"en":"The writer uses it to bring the two activities together.","zh":"作者用它把兩項活動連繫起來。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"serve the same educational purpose","meaning":"達到相同的教育目的","examples":[{"en":"The two activities serve the same educational purpose.","zh":"兩項活動達到相同的教育目的。"},{"en":"Serve the same educational purpose means help students learn towards the same goal.","zh":"serve the same educational purpose 指幫助學生朝同一學習目標進步。"},{"en":"A reading game and a drama task can serve the same purpose if both build language confidence.","zh":"如果閱讀遊戲和戲劇任務都建立語言信心，它們就能達到相同目的。"},{"en":"Different activities can support the same learning aim in different ways.","zh":"不同活動可以用不同方式支援同一學習目標。"},{"en":"Both proposed activities help students use English actively.","zh":"兩項建議活動都幫助學生主動使用英語。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"in different but complementary ways","meaning":"以不同但互補的方式","examples":[{"en":"The activities work in different but complementary ways.","zh":"這些活動以不同但互補的方式運作。"},{"en":"In different but complementary ways means through different methods that support each other.","zh":"in different but complementary ways 指透過不同但彼此支援的方法。"},{"en":"Reading and speaking practise different skills, but they can complement each other.","zh":"閱讀和說話練習不同技能，但可以互相補足。"},{"en":"One activity gives students a voice, while the other gives them a mission.","zh":"一項活動給學生發聲機會，另一項給他們任務。"},{"en":"Together, the two activities create a fuller language experience.","zh":"兩項活動合起來創造更完整的語言經驗。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"the former","meaning":"前者","examples":[{"en":"The former gives students a voice.","zh":"前者給學生發聲的機會。"},{"en":"The former means the first of two things just mentioned.","zh":"the former 指剛提到兩件事中的第一件。"},{"en":"If we discuss reading and speaking, the former refers to reading.","zh":"如果我們討論閱讀和說話，前者就是閱讀。"},{"en":"This phrase helps avoid repeating the first activity’s name.","zh":"這個片語幫助避免重複第一項活動的名稱。"},{"en":"Here, the former refers to Poetry Alive, the first proposed activity.","zh":"在這裏，前者指 Poetry Alive，即第一項建議活動。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"the latter","meaning":"後者","examples":[{"en":"The latter gives students a mission.","zh":"後者給學生一個任務。"},{"en":"The latter means the second of two things just mentioned.","zh":"the latter 指剛提到兩件事中的第二件。"},{"en":"If we mention poetry performance and story quest, the latter is the story quest.","zh":"如果我們提到詩歌表演和故事尋寶，後者就是故事尋寶。"},{"en":"This phrase keeps writing concise when comparing two items.","zh":"比較兩件事時，這個片語令寫作更簡潔。"},{"en":"Here, the latter refers to The Library Story Quest.","zh":"在這裏，後者指 The Library Story Quest。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"give students a voice","meaning":"給學生發聲的機會","examples":[{"en":"Poetry Alive gives students a voice.","zh":"Poetry Alive 給學生發聲的機會。"},{"en":"Give students a voice means provide chances for students to express ideas, feelings, and opinions.","zh":"give students a voice 指給學生表達想法、感受和意見的機會。"},{"en":"A school magazine gives students a voice by publishing their writing.","zh":"校刊透過刊登學生作品，給學生發聲的機會。"},{"en":"Performance gives quiet students a structured way to speak.","zh":"表演給安靜學生一個有結構的說話方式。"},{"en":"Poetry Alive gives students a voice by letting them interpret poems publicly.","zh":"Poetry Alive 讓學生公開演繹詩作，從而給他們發聲機會。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"give them a mission","meaning":"給他們一個任務","examples":[{"en":"The Library Story Quest gives students a mission.","zh":"The Library Story Quest 給學生一個任務。"},{"en":"Give them a mission means provide a clear task or purpose to complete.","zh":"give them a mission 指給他們一個清楚要完成的任務或目的。"},{"en":"A science challenge gives students a mission to build a working model.","zh":"科學挑戰給學生一個製作可運作模型的任務。"},{"en":"Missions make learning more active because students know what they are trying to achieve.","zh":"任務令學習更主動，因為學生知道自己要達成甚麼。"},{"en":"The Story Quest gives students a reason to read, listen, speak, and write.","zh":"Story Quest 給學生閱讀、聆聽、說話和寫作的理由。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"less distant","meaning":"沒那麼遙遠","examples":[{"en":"The activities would make English feel less distant.","zh":"這些活動會令英語感覺沒那麼遙遠。"},{"en":"Less distant means closer, more familiar, and easier to connect with.","zh":"less distant 指更接近、更熟悉，也更容易連繫。"},{"en":"English feels less distant when students use it to tell their own stories.","zh":"當學生用英語講自己的故事，英語就沒那麼遙遠。"},{"en":"A language becomes less distant when it appears in games, performances, and teamwork.","zh":"當語言出現在遊戲、表演和團隊合作中，它就會變得不那麼遙遠。"},{"en":"The festival can bring English closer to students’ daily imagination.","zh":"藝術節可以把英語帶近學生的日常想像。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"less mechanical","meaning":"沒那麼機械化","examples":[{"en":"The activities would make English feel less mechanical.","zh":"這些活動會令英語感覺沒那麼機械化。"},{"en":"Less mechanical means less like repeated, lifeless practice and more natural or meaningful.","zh":"less mechanical 指不像重複而缺乏生命的練習，而更自然或有意義。"},{"en":"English feels mechanical when students only fill in blanks.","zh":"當學生只填空時，英語會感覺機械化。"},{"en":"Performance and quests make language less mechanical because students must make choices.","zh":"表演和尋寶令語言沒那麼機械化，因為學生必須作出選擇。"},{"en":"The activities help English feel alive rather than automatic.","zh":"這些活動幫助英語感覺有生命，而不是自動化。"}],"source":"2015 Q8.pdf","sourcePage":13},{"front":"far more memorable","meaning":"難忘得多","examples":[{"en":"Together, the activities would make English far more memorable.","zh":"兩項活動合起來會令英語難忘得多。"},{"en":"Far more memorable means much easier to remember because the experience is stronger or more meaningful.","zh":"far more memorable 指因經驗更強或更有意義而更容易記住。"},{"en":"Students remember a performed poem better than a poem they only copied.","zh":"學生會比只抄寫一首詩更記得自己表演過的詩。"},{"en":"Active tasks become memorable because students use body, voice, and teamwork.","zh":"主動任務令人難忘，因為學生使用身體、聲音和團隊合作。"},{"en":"These activities make English memorable by linking it with emotion and purpose.","zh":"這些活動透過把英語連接到情感和目的，令它難忘。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"sincerely hope","meaning":"衷心希望","examples":[{"en":"The Poetry Club sincerely hopes the library will consider the suggestions.","zh":"詩會衷心希望圖書館會考慮這些建議。"},{"en":"Sincerely hope means genuinely and politely wish that something will happen.","zh":"sincerely hope 指真誠而禮貌地希望某事發生。"},{"en":"We sincerely hope the school will support the reading campaign.","zh":"我們衷心希望學校支持閱讀推廣活動。"},{"en":"This phrase sounds respectful in a formal letter.","zh":"這個片語在正式信件中聽起來尊重。"},{"en":"The club sincerely hopes its ideas can help the festival succeed.","zh":"詩會衷心希望自己的想法能幫助藝術節成功。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"consider these suggestions","meaning":"考慮這些建議","examples":[{"en":"The writer hopes the Central Library will consider these suggestions.","zh":"作者希望中央圖書館會考慮這些建議。"},{"en":"Consider these suggestions means think carefully about these proposed ideas before making a decision.","zh":"consider these suggestions 指在作決定前仔細思考這些建議想法。"},{"en":"A principal may consider students’ suggestions for improving the school library.","zh":"校長可能會考慮學生改善學校圖書館的建議。"},{"en":"This phrase politely asks the reader not to reject the ideas too quickly.","zh":"這個片語禮貌地請讀者不要太快拒絕想法。"},{"en":"Chris hopes the library will see the educational value of the two activities.","zh":"Chris 希望圖書館看見兩項活動的教育價值。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"be honoured to","meaning":"很榮幸能夠","examples":[{"en":"The Poetry Club would be honoured to provide student helpers.","zh":"詩會很榮幸能夠提供學生助手。"},{"en":"Be honoured to means feel proud and grateful to have the chance to do something.","zh":"be honoured to 指因有機會做某事而感到自豪和感激。"},{"en":"Students may be honoured to represent their school at a public event.","zh":"學生可能很榮幸能夠代表學校參加公開活動。"},{"en":"This phrase shows respect and willingness in a formal offer.","zh":"這個片語在正式提出協助時顯示尊重和意願。"},{"en":"The club would be honoured because helping the festival matches its purpose.","zh":"詩會會感到榮幸，因為協助藝術節符合它的宗旨。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"provide student helpers","meaning":"提供學生助手","examples":[{"en":"The Poetry Club could provide student helpers for the activities.","zh":"詩會可以為活動提供學生助手。"},{"en":"Provide student helpers means offer students who can assist with running an event.","zh":"provide student helpers 指提供能協助活動進行的學生。"},{"en":"Student helpers may guide teams, explain rules, or manage materials.","zh":"學生助手可以引導小隊、解釋規則或管理材料。"},{"en":"Providing helpers shows that the club is not only suggesting ideas but also willing to support them.","zh":"提供助手顯示詩會不只是提出想法，也願意支援落實。"},{"en":"Student helpers can make the activities smoother and more welcoming.","zh":"學生助手可以令活動更順暢、更歡迎人。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"should the activities be adopted","meaning":"如活動獲採納","examples":[{"en":"The club would help should the activities be adopted.","zh":"如活動獲採納，學會會提供協助。"},{"en":"Should the activities be adopted means if the activities are accepted and used.","zh":"should the activities be adopted 指如果活動被接受並使用。"},{"en":"Should the proposal be accepted, students can help with registration.","zh":"如建議獲接納，學生可以協助登記。"},{"en":"This structure sounds formal and is common in proposal letters.","zh":"這個結構聽起來正式，常見於建議信。"},{"en":"Chris uses it to offer help politely if the library chooses the ideas.","zh":"Chris 用它禮貌地表示，如果圖書館選用這些想法，詩會願意幫忙。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully is used to close a formal proposal letter.","zh":"Yours faithfully 用於結束正式建議信。"},{"en":"Yours faithfully is a formal closing used when the recipient is not named personally.","zh":"Yours faithfully 是收信人沒有以姓名稱呼時使用的正式結尾語。"},{"en":"A student may write Yours faithfully before signing a letter to a committee.","zh":"學生寫給委員會的信，可能在簽名前寫 Yours faithfully。"},{"en":"Using the correct closing makes the proposal sound respectful and complete.","zh":"使用正確結尾語，能令建議信聽起來尊重而完整。"},{"en":"Chris uses Yours faithfully to match the formal tone of the letter.","zh":"Chris 使用 Yours faithfully，以配合信件的正式語氣。"}],"source":"2015 Q8.pdf","sourcePage":14},{"front":"Chairperson, Poetry Club","meaning":"詩會主席","examples":[{"en":"Chris Wong signs the letter as Chairperson of the Poetry Club.","zh":"Chris Wong 以詩會主席身份簽署這封信。"},{"en":"Chairperson, Poetry Club means the student leader who represents and helps organise the Poetry Club.","zh":"Chairperson, Poetry Club 指代表並協助組織詩會的學生領袖。"},{"en":"A chairperson may lead meetings, collect ideas, and speak for club members.","zh":"主席可以主持會議、收集意見並代表會員發言。"},{"en":"Signing with this title shows Chris has authority to write on behalf of the club.","zh":"以這個職銜簽署，顯示 Chris 有權代表詩會寫信。"},{"en":"The title makes the proposal more official and responsible.","zh":"這個職銜令建議書更正式，也更有責任感。"}],"source":"2015 Q8.pdf","sourcePage":14}],"dse/writing/part-b/2015/Q9":[{"front":"I hope you are well","meaning":"希望你一切安好","examples":[{"en":"The letter begins with “I hope you are well.”","zh":"這封信以「希望你一切安好」開始。"},{"en":"I hope you are well is a polite opening used to show care before discussing the main purpose of a letter.","zh":"I hope you are well 是一種禮貌開首，用來在討論主要目的前表示關心。"},{"en":"A student may write “I hope you are well” before asking a teacher for advice.","zh":"學生向老師請教前，可能會寫 “I hope you are well”。"},{"en":"This phrase helps a formal letter sound warm, not sudden or demanding.","zh":"這個短語令正式信件聽起來溫暖，而不是突然或強硬。"},{"en":"It is common in emails because it creates a respectful tone at the beginning.","zh":"它常見於電郵中，因為它在開首建立尊重的語氣。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"chairperson of","meaning":"……的主席","examples":[{"en":"Chris Wong is the chairperson of the Reading Club.","zh":"Chris Wong 是閱讀學會的主席。"},{"en":"Chairperson of a group means the person who leads or represents that group.","zh":"chairperson of 某組織，指領導或代表該組織的人。"},{"en":"The chairperson of the student council usually runs meetings and speaks for members.","zh":"學生會主席通常主持會議，並代表成員發言。"},{"en":"A good chairperson of a club listens to ideas before making decisions.","zh":"好的學會主席會在作決定前聆聽不同意見。"},{"en":"This role matters because the chairperson often connects the group with teachers or organisers.","zh":"這個角色很重要，因為主席常把組織與老師或主辦者連接起來。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"Reading Club","meaning":"閱讀學會","examples":[{"en":"The Reading Club wants to invite a guest speaker.","zh":"閱讀學會想邀請一位嘉賓講者。"},{"en":"A Reading Club is a group where students or members read, discuss books, and promote reading.","zh":"Reading Club 指學生或成員一起閱讀、討論書本和推廣閱讀的小組。"},{"en":"A Reading Club may choose one book each month and share opinions after reading it.","zh":"閱讀學會可能每月選一本書，閱讀後分享意見。"},{"en":"Reading Clubs help students discover books they may not choose alone.","zh":"閱讀學會幫助學生發現自己未必會主動選擇的書。"},{"en":"A good Reading Club builds both reading interest and discussion skills.","zh":"好的閱讀學會能建立閱讀興趣和討論能力。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"I am writing to recommend that","meaning":"我寫信建議","examples":[{"en":"I am writing to recommend that we invite James Clear.","zh":"我寫信建議我們邀請 James Clear。"},{"en":"I am writing to recommend that is a formal way to state a suggestion in a letter.","zh":"I am writing to recommend that 是在信中正式提出建議的說法。"},{"en":"I am writing to recommend that the school extend library opening hours.","zh":"我寫信建議學校延長圖書館開放時間。"},{"en":"This phrase is useful because it makes the purpose of the letter clear immediately.","zh":"這個短語很有用，因為它立即清楚說明信件目的。"},{"en":"It sounds polite and organised when giving advice to a teacher or committee.","zh":"向老師或委員會提出建議時，它聽起來禮貌而有條理。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"invite someone to be","meaning":"邀請某人成為","examples":[{"en":"The club wants to invite James Clear to be its guest speaker.","zh":"學會想邀請 James Clear 成為嘉賓講者。"},{"en":"To invite someone to be something means to ask that person to take a particular role.","zh":"invite someone to be something 指邀請某人擔任某個角色。"},{"en":"A school may invite a doctor to be the speaker at a health talk.","zh":"學校可能邀請醫生成為健康講座的講者。"},{"en":"Clubs invite people to be guests when those people can share useful experience.","zh":"學會在某人能分享有用經驗時，會邀請他成為嘉賓。"},{"en":"The phrase shows both invitation and the role the person is expected to play.","zh":"這個短語同時顯示邀請和對方預期擔任的角色。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"author of","meaning":"……的作者","examples":[{"en":"James Clear is the author of Atomic Habits.","zh":"James Clear 是《Atomic Habits》的作者。"},{"en":"The author of a book is the person who wrote it.","zh":"author of a book 指寫該書的人。"},{"en":"A student may introduce J.K. Rowling as the author of the Harry Potter series.","zh":"學生可能介紹 J.K. Rowling 為《Harry Potter》系列的作者。"},{"en":"Knowing the author of a book helps readers understand whose ideas they are reading.","zh":"知道一本書的作者，能幫助讀者理解自己正在閱讀誰的想法。"},{"en":"When recommending a guest speaker, naming the author of a well-known book gives clear background.","zh":"推薦嘉賓講者時，說明他是知名書本的作者，可以提供清楚背景。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"guest speaker","meaning":"嘉賓講者","examples":[{"en":"James Clear could be the guest speaker for the evening.","zh":"James Clear 可以成為當晚的嘉賓講者。"},{"en":"A guest speaker is a person invited to give a talk at an event.","zh":"guest speaker 指受邀在活動中發表演講的人。"},{"en":"A school may invite an athlete as a guest speaker for Sports Day.","zh":"學校可能邀請運動員作為運動日的嘉賓講者。"},{"en":"Guest speakers can make an event special because they bring outside experience.","zh":"嘉賓講者能令活動特別，因為他們帶來外界經驗。"},{"en":"A good guest speaker connects their topic with the audience’s daily life.","zh":"好的嘉賓講者會把主題與觀眾日常生活連繫起來。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"Meet the Author evening","meaning":"與作者見面晚會","examples":[{"en":"The Reading Club is planning a Meet the Author evening.","zh":"閱讀學會正在計劃一個與作者見面晚會。"},{"en":"A Meet the Author evening is an event where readers meet and listen to a writer.","zh":"Meet the Author evening 指讀者與作者見面並聆聽作者分享的活動。"},{"en":"During a Meet the Author evening, students may ask questions about writing and reading habits.","zh":"在與作者見面晚會中，學生可以詢問關於寫作和閱讀習慣的問題。"},{"en":"Such an evening can make books feel more personal because readers meet the person behind them.","zh":"這類晚會能令書本感覺更個人化，因為讀者見到書本背後的人。"},{"en":"It works best when the author’s message is relevant to students.","zh":"當作者的訊息與學生相關時，活動效果最好。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"during Reading Week","meaning":"在閱讀週期間","examples":[{"en":"The event would take place during Reading Week.","zh":"活動會在閱讀週期間舉行。"},{"en":"During Reading Week means in the period when the school holds special reading activities.","zh":"during Reading Week 指在學校舉辦特別閱讀活動的期間。"},{"en":"Schools may invite writers, organise book displays, and hold reading challenges during Reading Week.","zh":"學校在閱讀週期間可能邀請作家、舉辦書展和閱讀挑戰。"},{"en":"Events held during Reading Week should encourage students to read more willingly.","zh":"在閱讀週期間舉行的活動應鼓勵學生更願意閱讀。"},{"en":"A guest talk during Reading Week can connect reading with real-life goals.","zh":"閱讀週期間的嘉賓講座可以把閱讀與現實生活目標連接起來。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"the purpose of","meaning":"……的目的","examples":[{"en":"The purpose of Reading Week is to help students enjoy reading.","zh":"閱讀週的目的是幫助學生享受閱讀。"},{"en":"The purpose of something is the reason why it is done or created.","zh":"the purpose of something 指某事被進行或創造的原因。"},{"en":"The purpose of homework should be to help students practise, not only to keep them busy.","zh":"功課的目的應是幫助學生練習，而不只是令他們忙碌。"},{"en":"When people understand the purpose of an activity, they are more likely to take it seriously.","zh":"當人們明白活動目的時，他們更可能認真對待它。"},{"en":"Explaining the purpose of Reading Week helps show why the proposed speaker matters.","zh":"解釋閱讀週的目的，有助顯示建議講者為何重要。"}],"source":"2015 Q9.pdf","sourcePage":1},{"front":"not simply to","meaning":"不只是為了","examples":[{"en":"The purpose is not simply to add another activity to the calendar.","zh":"目的不只是為了在行事曆上加多一項活動。"},{"en":"Not simply to means not only for that basic or surface reason.","zh":"not simply to 指不只是為了那個基本或表面的原因。"},{"en":"A school trip is not simply to leave the classroom; it should help students learn from real places.","zh":"學校旅行不只是為了離開課室；它應幫助學生從真實地方學習。"},{"en":"This phrase helps show that an action has a deeper purpose.","zh":"這個短語有助顯示一個行動有更深層目的。"},{"en":"Reading Week should not simply fill time; it should change how students see reading.","zh":"閱讀週不應只是填滿時間；它應改變學生看待閱讀的方式。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"add another activity to","meaning":"加多一項活動到","examples":[{"en":"The event should not simply add another activity to the school calendar.","zh":"這項活動不應只是加多一項活動到學校行事曆。"},{"en":"To add another activity to something means to include one more event in an existing schedule.","zh":"add another activity to something 指在現有日程中再加入一項活動。"},{"en":"Teachers should not add another activity to a busy week unless it has clear value.","zh":"除非活動有清楚價值，否則老師不應在繁忙一週再加多一項活動。"},{"en":"Adding activities without purpose can make students tired rather than interested.","zh":"沒有目的地增加活動，可能令學生疲倦，而不是感興趣。"},{"en":"A good event should do more than add another item to the calendar.","zh":"好活動不應只是為行事曆加多一項內容。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"school calendar","meaning":"學校行事曆","examples":[{"en":"Reading Week is part of the school calendar.","zh":"閱讀週是學校行事曆的一部分。"},{"en":"A school calendar is the official schedule of school events, holidays, tests, and activities.","zh":"school calendar 指列出學校活動、假期、測驗和特別活動的正式日程。"},{"en":"Students check the school calendar to know when exams and special days will happen.","zh":"學生查看學校行事曆，以知道考試和特別日子的時間。"},{"en":"A crowded school calendar can make it difficult to add meaningful new events.","zh":"擁擠的學校行事曆會令加入有意義的新活動變得困難。"},{"en":"When an event is placed on the school calendar, it should serve a clear educational purpose.","zh":"當活動被放進學校行事曆時，它應有清楚教育目的。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"see reading as","meaning":"把閱讀視為","examples":[{"en":"The event should help students see reading as useful.","zh":"這項活動應幫助學生把閱讀視為有用。"},{"en":"To see reading as something means to understand or treat reading in that way.","zh":"see reading as something 指以某種方式理解或看待閱讀。"},{"en":"Students may see reading as boring if they only connect it with exams.","zh":"如果學生只把閱讀與考試連繫起來，他們可能把閱讀視為沉悶。"},{"en":"A good speaker can help students see reading as a tool for personal growth.","zh":"好的講者可以幫助學生把閱讀視為個人成長的工具。"},{"en":"Changing how students see reading can change whether they continue reading after school.","zh":"改變學生看待閱讀的方式，可以改變他們離開學校後是否繼續閱讀。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"connected to their own lives","meaning":"與他們自己的生活有關","examples":[{"en":"Students should see reading as connected to their own lives.","zh":"學生應把閱讀視為與他們自己的生活有關。"},{"en":"Connected to their own lives means related to students’ real experiences, problems, goals, or feelings.","zh":"connected to their own lives 指與學生的真實經驗、問題、目標或感受有關。"},{"en":"A book about habits feels connected to students’ lives when it helps them manage homework.","zh":"當一本關於習慣的書幫助學生管理功課時，它就與學生生活有關。"},{"en":"Learning becomes stronger when students see how an idea connects to their own lives.","zh":"當學生看見一個想法如何連繫到自己的生活時，學習會更有力量。"},{"en":"Reading feels less distant when it answers questions students already have.","zh":"當閱讀回答學生本來已有的問題時，它就不再那麼遙遠。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"given that","meaning":"鑑於","examples":[{"en":"Given that many students are under pressure, the book would be relevant.","zh":"鑑於許多學生承受壓力，這本書會很相關。"},{"en":"Given that means considering the fact that something is true.","zh":"given that 指考慮到某事是真實情況。"},{"en":"Given that the exam is next week, students should start revising today.","zh":"鑑於考試在下星期，學生應今天開始溫習。"},{"en":"Writers use given that to explain why a suggestion makes sense in a particular situation.","zh":"作者使用 given that 來解釋為何某建議在特定情況下合理。"},{"en":"Given that students face stress, a book about small habits may be especially useful.","zh":"鑑於學生面對壓力，一本關於細小習慣的書可能特別有用。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"under pressure from","meaning":"承受來自……的壓力","examples":[{"en":"Many students are under pressure from tests and examinations.","zh":"許多學生承受來自測驗和考試的壓力。"},{"en":"To be under pressure from something means to feel stress because of that thing.","zh":"be under pressure from something 指因某事而感到壓力。"},{"en":"Workers may be under pressure from deadlines and customer complaints.","zh":"員工可能承受來自截止日期和顧客投訴的壓力。"},{"en":"Students under pressure from exams may find it hard to build healthy routines.","zh":"承受考試壓力的學生可能難以建立健康習慣。"},{"en":"Understanding the source of pressure helps people choose more realistic solutions.","zh":"理解壓力來源，有助人們選擇更實際的解決方法。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"tests and examinations","meaning":"測驗和考試","examples":[{"en":"Students are under pressure from tests and examinations.","zh":"學生承受來自測驗和考試的壓力。"},{"en":"Tests and examinations are assessments used to measure what students know or can do.","zh":"tests and examinations 指用來評估學生知道甚麼或能做甚麼的評核。"},{"en":"Tests may cover one topic, while examinations often cover a larger part of the course.","zh":"測驗可能涵蓋一個課題，而考試通常涵蓋更大部分課程。"},{"en":"Too many tests and examinations can make students focus only on marks.","zh":"太多測驗和考試會令學生只專注分數。"},{"en":"Good study habits help students face tests and examinations with more confidence.","zh":"良好學習習慣幫助學生更有信心面對測驗和考試。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"small, realistic improvements","meaning":"細小而實際的改善","examples":[{"en":"The book is about small, realistic improvements.","zh":"這本書是關於細小而實際的改善。"},{"en":"Small, realistic improvements are little changes that ordinary people can actually make.","zh":"small, realistic improvements 指普通人真正能做到的小改變。"},{"en":"Reading two pages a day is a small, realistic improvement for a busy student.","zh":"對繁忙學生來說，每天閱讀兩頁是一個細小而實際的改善。"},{"en":"Small improvements work because they are less frightening than huge promises.","zh":"小改善有效，因為它們比巨大承諾較不令人害怕。"},{"en":"Realistic improvements are more likely to last because they fit daily life.","zh":"實際的改善較可能持續，因為它們配合日常生活。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"speak directly to","meaning":"直接回應","examples":[{"en":"The book would speak directly to students’ concerns.","zh":"這本書會直接回應學生的憂慮。"},{"en":"To speak directly to concerns means to address problems or worries clearly and relevantly.","zh":"speak directly to concerns 指清楚而相關地處理問題或擔憂。"},{"en":"A talk about sleep may speak directly to students who feel tired every morning.","zh":"關於睡眠的講座可能直接回應每天早上疲倦的學生。"},{"en":"Advice speaks directly to people when it feels written for their real situation.","zh":"當建議感覺像是為人們的真實情況而寫時，它就直接回應他們。"},{"en":"Atomic Habits may speak directly to students because it discusses pressure, routines, and progress.","zh":"《Atomic Habits》可能直接回應學生，因為它討論壓力、習慣和進步。"}],"source":"2015 Q9.pdf","sourcePage":2},{"front":"students’ concerns","meaning":"學生的憂慮","examples":[{"en":"The book speaks directly to students’ concerns.","zh":"這本書直接回應學生的憂慮。"},{"en":"Students’ concerns are the worries, questions, or problems students have.","zh":"students’ concerns 指學生擁有的擔心、問題或困難。"},{"en":"Common students’ concerns include exams, time management, friendships, and future choices.","zh":"常見的學生憂慮包括考試、時間管理、友誼和未來選擇。"},{"en":"A good school event should notice students’ concerns instead of only adults’ plans.","zh":"好的學校活動應留意學生的憂慮，而不只是成年人計劃。"},{"en":"When a speaker addresses students’ concerns, students are more likely to listen.","zh":"當講者處理學生的憂慮時，學生較可能聆聽。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"I therefore believe","meaning":"因此我相信","examples":[{"en":"I therefore believe Mr Clear would be the most suitable choice.","zh":"因此我相信 Clear 先生會是最合適的選擇。"},{"en":"I therefore believe means I believe this as a result of the reasons already given.","zh":"I therefore believe 指基於前面已提出的理由，所以我相信。"},{"en":"I therefore believe the school should open the library earlier before exams.","zh":"因此我相信學校應在考試前提早開放圖書館。"},{"en":"This phrase helps connect evidence with a clear recommendation.","zh":"這個短語有助把證據與清晰建議連接起來。"},{"en":"It is useful in formal letters because it sounds logical and respectful.","zh":"它在正式信件中很有用，因為語氣合邏輯而尊重。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"the most suitable choice","meaning":"最合適的選擇","examples":[{"en":"Mr Clear would be the most suitable choice.","zh":"Clear 先生會是最合適的選擇。"},{"en":"The most suitable choice means the best option for a particular purpose or situation.","zh":"the most suitable choice 指最符合某目的或情況的最佳選項。"},{"en":"A quiet classroom may be the most suitable choice for a reading workshop.","zh":"安靜課室可能是閱讀工作坊最合適的選擇。"},{"en":"The most suitable choice is not always the most famous one; it should fit the audience’s needs.","zh":"最合適的選擇不一定是最有名的；它應符合觀眾需要。"},{"en":"Mr Clear is presented as suitable because his topic matches students’ habits and pressure.","zh":"Clear 先生被視為合適，因為他的主題配合學生的習慣和壓力。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"attract reluctant readers","meaning":"吸引抗拒閱讀的人","examples":[{"en":"Mr Clear can attract reluctant readers.","zh":"Clear 先生可以吸引抗拒閱讀的人。"},{"en":"To attract reluctant readers means to make people who do not like reading become interested.","zh":"attract reluctant readers 指令不喜歡閱讀的人產生興趣。"},{"en":"Comics, short chapters, and practical topics can attract reluctant readers.","zh":"漫畫、短章節和實用題材可以吸引抗拒閱讀的人。"},{"en":"Reluctant readers may respond better when books connect with real problems.","zh":"當書本與真實問題有關時，抗拒閱讀的人可能反應更好。"},{"en":"A speaker can attract reluctant readers by showing that reading can solve daily difficulties.","zh":"講者可以透過展示閱讀能解決日常困難，吸引抗拒閱讀的人。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"reluctant readers","meaning":"抗拒閱讀的人","examples":[{"en":"Reluctant readers may be attracted by Atomic Habits.","zh":"抗拒閱讀的人可能會被《Atomic Habits》吸引。"},{"en":"Reluctant readers are people who avoid reading or do not feel confident about it.","zh":"reluctant readers 指避開閱讀或對閱讀沒有信心的人。"},{"en":"A reluctant reader may choose videos instead of books whenever possible.","zh":"抗拒閱讀的人只要可以，可能會選擇影片而不是書本。"},{"en":"Reluctant readers often need short, clear, and useful texts to begin.","zh":"抗拒閱讀的人常需要短、清楚和有用的文本作開始。"},{"en":"Helping reluctant readers matters because one good book can change their attitude.","zh":"幫助抗拒閱讀的人很重要，因為一本好書可以改變他們的態度。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"accessible non-fiction","meaning":"易懂的非小說類作品","examples":[{"en":"Students can improve their English through accessible non-fiction.","zh":"學生可以透過易懂的非小說類作品提升英文。"},{"en":"Accessible non-fiction means factual writing that is easy enough for general readers to understand.","zh":"accessible non-fiction 指一般讀者較容易理解的事實類寫作。"},{"en":"A clear book about habits or health can be accessible non-fiction for teenagers.","zh":"一本關於習慣或健康的清晰書籍，可以是適合青少年的易懂非小說作品。"},{"en":"Accessible non-fiction helps students learn useful vocabulary without feeling lost in a long story.","zh":"易懂的非小說類作品幫助學生學習實用詞彙，而不會在長故事中迷失。"},{"en":"It can build confidence because students understand real ideas in English.","zh":"它能建立信心，因為學生能用英文理解真實想法。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"build a lasting reading habit","meaning":"建立持久的閱讀習慣","examples":[{"en":"Mr Clear can show students how to build a lasting reading habit.","zh":"Clear 先生可以向學生展示如何建立持久的閱讀習慣。"},{"en":"To build a lasting reading habit means to create a regular pattern of reading that continues over time.","zh":"build a lasting reading habit 指建立能長時間持續的定期閱讀模式。"},{"en":"Reading five pages after dinner every day can help build a lasting reading habit.","zh":"每天晚飯後閱讀五頁，可以幫助建立持久的閱讀習慣。"},{"en":"Lasting habits need simple routines, visible books, and small rewards.","zh":"持久習慣需要簡單常規、看得見的書和小獎勵。"},{"en":"A lasting reading habit is more valuable than reading a lot for only one week.","zh":"持久的閱讀習慣比只在一星期內大量閱讀更有價值。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"excellent choice","meaning":"出色的選擇","examples":[{"en":"Mr Clear is an excellent choice for Reading Week.","zh":"Clear 先生是閱讀週的出色選擇。"},{"en":"An excellent choice is a very good option for a particular purpose.","zh":"excellent choice 指對某個目的而言非常好的選項。"},{"en":"A local author may be an excellent choice for a talk about Hong Kong stories.","zh":"本地作家可能是香港故事講座的出色選擇。"},{"en":"Someone becomes an excellent choice when their message matches the audience’s needs.","zh":"當某人的訊息符合觀眾需要時，他就成為出色選擇。"},{"en":"Mr Clear is an excellent choice because his ideas are practical for students.","zh":"Clear 先生是出色選擇，因為他的想法對學生很實用。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"highly relevant to","meaning":"與……高度相關","examples":[{"en":"Atomic Habits is highly relevant to Hong Kong students.","zh":"《Atomic Habits》與香港學生高度相關。"},{"en":"Highly relevant to means strongly connected to someone’s situation, needs, or concerns.","zh":"highly relevant to 指與某人的情況、需要或關注有強烈關連。"},{"en":"Time-management skills are highly relevant to students preparing for public exams.","zh":"時間管理技巧與準備公開考試的學生高度相關。"},{"en":"A topic becomes highly relevant when people can use it in daily life.","zh":"當人們能在日常生活中使用某主題時，它就變得高度相關。"},{"en":"The book is relevant because many students struggle with habits, motivation, and pressure.","zh":"這本書相關，因為許多學生在習慣、動力和壓力方面掙扎。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"beneficial","meaning":"有益的","examples":[{"en":"Many students know that reading is beneficial.","zh":"許多學生知道閱讀是有益的。"},{"en":"Beneficial means helpful or good for someone’s development, health, or success.","zh":"beneficial 指對某人的發展、健康或成功有幫助或有好處。"},{"en":"Regular exercise is beneficial because it improves energy and mood.","zh":"定期運動有益，因為它改善精力和心情。"},{"en":"Reading is beneficial when it builds language, knowledge, imagination, and confidence.","zh":"當閱讀建立語言、知識、想像力和信心時，它就是有益的。"},{"en":"Knowing something is beneficial does not always mean people will do it regularly.","zh":"知道某事有益，不一定代表人們會定期做。"}],"source":"2015 Q9.pdf","sourcePage":3},{"front":"fail to","meaning":"未能","examples":[{"en":"Students often fail to turn knowledge into action.","zh":"學生常未能把知識化為行動。"},{"en":"To fail to do something means to not manage to do it successfully.","zh":"fail to do something 指未能成功做到某事。"},{"en":"A student may fail to finish homework if the task is too large and unclear.","zh":"如果任務太大又不清楚，學生可能未能完成功課。"},{"en":"People often fail to change habits because they rely only on motivation.","zh":"人們常因只依靠動力而未能改變習慣。"},{"en":"The phrase points to a gap between knowing the right thing and actually doing it.","zh":"這個短語指出知道正確事情與真正做到之間的差距。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"turn knowledge into action","meaning":"把知識化為行動","examples":[{"en":"Students often fail to turn their knowledge into action.","zh":"學生常未能把知識化為行動。"},{"en":"To turn knowledge into action means to use what you know in real behaviour.","zh":"turn knowledge into action 指把所知道的東西用在實際行為中。"},{"en":"Knowing that sleep is important is not enough; students must turn knowledge into action by going to bed earlier.","zh":"知道睡眠重要並不足夠；學生必須透過早睡把知識化為行動。"},{"en":"People turn knowledge into action when they create small routines that support their goals.","zh":"當人們建立支持目標的小習慣時，就是把知識化為行動。"},{"en":"This phrase is useful because learning only matters when it changes what people do.","zh":"這個短語很有用，因為學習只有在改變行為時才有意義。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"with enthusiasm","meaning":"滿懷熱情地","examples":[{"en":"A student may buy an English book with enthusiasm.","zh":"學生可能滿懷熱情地買一本英文書。"},{"en":"With enthusiasm means with excitement, energy, and strong interest.","zh":"with enthusiasm 指帶着興奮、活力和強烈興趣。"},{"en":"A child may join the school choir with enthusiasm after watching a concert.","zh":"孩子看完音樂會後，可能滿懷熱情地加入學校合唱團。"},{"en":"Starting with enthusiasm is useful, but long-term habits need structure too.","zh":"帶着熱情開始是有用的，但長期習慣也需要結構。"},{"en":"Enthusiasm often fades if the task feels too difficult after the first day.","zh":"如果任務在第一天後感覺太難，熱情常會減退。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"on the first night","meaning":"在第一晚","examples":[{"en":"The student may read ten pages on the first night.","zh":"學生可能在第一晚讀十頁。"},{"en":"On the first night means during the first evening after starting something.","zh":"on the first night 指開始某事後的第一個晚上。"},{"en":"On the first night of camp, students may feel excited and unable to sleep.","zh":"露營第一晚，學生可能很興奮而睡不着。"},{"en":"People often do too much on the first night because motivation is still high.","zh":"人們常在第一晚做太多，因為動力仍然很高。"},{"en":"A habit should be small enough to continue after the first night.","zh":"習慣應該小到能在第一晚之後仍繼續。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"leave it untouched","meaning":"把它放着不碰","examples":[{"en":"The student may leave the book untouched for three months.","zh":"學生可能把那本書放着三個月不碰。"},{"en":"To leave it untouched means to not open, use, or continue with it.","zh":"leave it untouched 指不打開、不使用或不繼續做某事。"},{"en":"Someone may buy a notebook and leave it untouched on the desk.","zh":"有人可能買了一本筆記簿，然後把它放在桌上不碰。"},{"en":"A book can be left untouched when the reader’s first plan is too ambitious.","zh":"當讀者一開始的計劃太宏大時，書本可能被放着不碰。"},{"en":"This phrase shows the difference between buying a book and building a reading habit.","zh":"這個短語顯示買書與建立閱讀習慣之間的差別。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"sounds familiar","meaning":"聽起來很熟悉","examples":[{"en":"Sounds familiar, doesn’t it?","zh":"聽起來很熟悉，對嗎？"},{"en":"Sounds familiar means this situation seems like something people have experienced before.","zh":"sounds familiar 指這種情況像人們以前經歷過的事。"},{"en":"You planned to exercise every day and stopped after a week—sounds familiar, doesn’t it?","zh":"你計劃每天運動，卻一星期後停止——聽起來很熟悉吧？"},{"en":"Writers use this phrase to connect with readers through shared experience.","zh":"作者使用這個短語，透過共同經驗與讀者連繫。"},{"en":"It makes the tone conversational because it invites readers to recognise themselves.","zh":"它令語氣較像對話，因為它邀請讀者認出自己。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"central message","meaning":"核心訊息","examples":[{"en":"Clear’s central message is about tiny repeated actions.","zh":"Clear 的核心訊息是關於細小而重複的行動。"},{"en":"A central message is the main idea that a book, talk, or text wants readers to remember.","zh":"central message 指一本書、演講或文章希望讀者記住的主要想法。"},{"en":"The central message of a health talk may be that small daily choices matter.","zh":"健康講座的核心訊息可能是每日小選擇很重要。"},{"en":"Readers understand a book better when they can identify its central message.","zh":"當讀者能找出一本書的核心訊息時，他們會更明白它。"},{"en":"Clear’s central message is useful because it turns change into small actions.","zh":"Clear 的核心訊息有用，因為它把改變變成小行動。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"tiny repeated actions","meaning":"細小而重複的行動","examples":[{"en":"Tiny repeated actions can lead to long-term change.","zh":"細小而重複的行動可以帶來長遠改變。"},{"en":"Tiny repeated actions are very small behaviours done again and again.","zh":"tiny repeated actions 指一次又一次做的很小行為。"},{"en":"Reading one paragraph every night is a tiny repeated action.","zh":"每晚閱讀一段文字就是細小而重複的行動。"},{"en":"Tiny repeated actions matter because they are easier to continue than huge plans.","zh":"細小而重複的行動很重要，因為它們比宏大計劃更容易持續。"},{"en":"Over time, tiny repeated actions can change what a person becomes used to doing.","zh":"長遠來說，細小而重複的行動可以改變一個人習慣做的事情。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"lead to","meaning":"導致；帶來","examples":[{"en":"Small actions can lead to remarkable change.","zh":"小行動可以帶來顯著改變。"},{"en":"To lead to something means to cause it or help it happen.","zh":"lead to something 指導致某事或幫助它發生。"},{"en":"Poor sleep can lead to weaker memory and lower concentration.","zh":"睡眠不足可能導致記憶力較弱和專注力下降。"},{"en":"Reading a little every day can lead to stronger vocabulary over time.","zh":"每天閱讀一點，長遠可以帶來更強詞彙量。"},{"en":"This phrase is useful for showing a cause-and-effect relationship.","zh":"這個短語很適合用來展示因果關係。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"remarkable long-term change","meaning":"顯著的長遠改變","examples":[{"en":"Tiny repeated actions can lead to remarkable long-term change.","zh":"細小而重複的行動可以帶來顯著的長遠改變。"},{"en":"Remarkable long-term change means important improvement that becomes clear over a long period.","zh":"remarkable long-term change 指經過長時間後變得明顯的重要改善。"},{"en":"Saving a small amount every week can create remarkable long-term change in personal finance.","zh":"每星期儲蓄小金額，可以在個人理財上帶來顯著的長遠改變。"},{"en":"Long-term change often looks slow at first but becomes powerful later.","zh":"長遠改變起初常看似緩慢，但之後會變得有力量。"},{"en":"The phrase encourages students to value small habits instead of quick results.","zh":"這個短語鼓勵學生重視小習慣，而不是快速成果。"}],"source":"2015 Q9.pdf","sourcePage":4},{"front":"directly addresses","meaning":"直接處理","examples":[{"en":"Clear’s message directly addresses students’ difficulty.","zh":"Clear 的訊息直接處理學生的困難。"},{"en":"Directly addresses means deals with a problem clearly and without avoiding it.","zh":"directly addresses 指清楚而不迴避地處理問題。"},{"en":"A workshop on time management directly addresses students’ problem of late homework.","zh":"時間管理工作坊直接處理學生功課遲交的問題。"},{"en":"Advice is more useful when it directly addresses the reason people struggle.","zh":"當建議直接處理人們掙扎的原因時，它會更有用。"},{"en":"Clear’s message directly addresses the gap between wanting to read and actually reading.","zh":"Clear 的訊息直接處理想閱讀與真正閱讀之間的差距。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"instead of","meaning":"而不是","examples":[{"en":"Instead of telling students to read more, he can show them how.","zh":"他可以向學生展示方法，而不是只叫他們多閱讀。"},{"en":"Instead of means in place of one action, choice, or method.","zh":"instead of 指以一個行動、選擇或方法取代另一個。"},{"en":"Instead of blaming students, a teacher can help them plan better.","zh":"老師可以幫助學生更好計劃，而不是責怪學生。"},{"en":"This phrase shows contrast between a weaker method and a better method.","zh":"這個短語顯示較弱方法與較好方法之間的對比。"},{"en":"Instead of giving vague advice, the speaker can offer practical steps.","zh":"講者可以提供實際步驟，而不是給出含糊建議。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"vaguely","meaning":"含糊地","examples":[{"en":"Teachers should not tell students vaguely to read more.","zh":"老師不應含糊地叫學生多閱讀。"},{"en":"Vaguely means in an unclear or general way, without enough detail.","zh":"vaguely 指以不清楚或籠統的方式，沒有足夠細節。"},{"en":"Saying “try harder” vaguely may not help a student know what to do next.","zh":"含糊地說「努力一點」可能不能幫助學生知道下一步做甚麼。"},{"en":"Vague advice often fails because people need specific actions.","zh":"含糊建議常失效，因為人們需要具體行動。"},{"en":"Students need clear reading steps, not vague encouragement alone.","zh":"學生需要清晰閱讀步驟，而不只是含糊鼓勵。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"make reading obvious","meaning":"令閱讀變得明顯","examples":[{"en":"Students can learn how to make reading obvious.","zh":"學生可以學習如何令閱讀變得明顯。"},{"en":"To make reading obvious means to place reminders or books where reading is easy to notice.","zh":"make reading obvious 指把提示或書本放在容易注意到的位置。"},{"en":"Putting an English book on the desk can make reading obvious after dinner.","zh":"把英文書放在書桌上，可以令晚飯後閱讀變得明顯。"},{"en":"If a habit is visible, people are more likely to remember it.","zh":"如果習慣是看得見的，人們較可能記得它。"},{"en":"Making reading obvious helps students reduce the chance of forgetting their plan.","zh":"令閱讀變得明顯，有助學生減少忘記計劃的機會。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"make reading attractive","meaning":"令閱讀變得吸引","examples":[{"en":"Students can learn how to make reading attractive.","zh":"學生可以學習如何令閱讀變得吸引。"},{"en":"To make reading attractive means to make reading feel enjoyable, inviting, or rewarding.","zh":"make reading attractive 指令閱讀感覺有趣、吸引人或有回報。"},{"en":"Choosing a topic you care about can make reading attractive.","zh":"選擇自己關心的題材可以令閱讀變得吸引。"},{"en":"A comfortable chair and a short book can make reading more inviting after school.","zh":"一張舒適椅子和一本短書，可以令放學後閱讀更吸引。"},{"en":"Reading becomes easier to continue when it feels attractive instead of painful.","zh":"當閱讀感覺吸引而不是痛苦時，就更容易持續。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"make reading easy","meaning":"令閱讀變得容易","examples":[{"en":"Students can learn how to make reading easy.","zh":"學生可以學習如何令閱讀變得容易。"},{"en":"To make reading easy means to reduce the effort needed to start or continue reading.","zh":"make reading easy 指減少開始或繼續閱讀所需的努力。"},{"en":"Keeping a book in your schoolbag can make reading easy during travel time.","zh":"把書放在書包裏，可以令乘車時間閱讀變得容易。"},{"en":"Short chapters make reading easy because students can finish one quickly.","zh":"短章節令閱讀變得容易，因為學生可以很快完成一章。"},{"en":"Habits last longer when the first step is easy to begin.","zh":"當第一步容易開始時，習慣會更持久。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"make reading satisfying","meaning":"令閱讀帶來滿足感","examples":[{"en":"Students can learn how to make reading satisfying.","zh":"學生可以學習如何令閱讀帶來滿足感。"},{"en":"To make reading satisfying means to make readers feel rewarded or pleased after reading.","zh":"make reading satisfying 指令讀者在閱讀後感到有回報或愉快。"},{"en":"Ticking a box after reading two pages can make reading satisfying.","zh":"讀完兩頁後在方格上打勾，可以令閱讀帶來滿足感。"},{"en":"Sharing a favourite sentence with a friend can make reading feel rewarding.","zh":"與朋友分享一句喜歡的句子，可以令閱讀感覺有回報。"},{"en":"When reading is satisfying, students want to repeat it.","zh":"當閱讀帶來滿足感時，學生會想重複去做。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"place a book beside their bed","meaning":"把書放在床邊","examples":[{"en":"Students could place a short English book beside their bed.","zh":"學生可以把一本短英文書放在床邊。"},{"en":"To place a book beside their bed means to put it near where they sleep so it is easy to see and reach.","zh":"place a book beside their bed 指把書放在睡覺地方旁邊，讓它容易看見和拿到。"},{"en":"A student may place a book beside the bed to read before sleeping.","zh":"學生可能把書放在床邊，以便睡前閱讀。"},{"en":"Visible books remind students of their reading plan without needing extra effort.","zh":"看得見的書會提醒學生閱讀計劃，而不需要額外努力。"},{"en":"This small action makes reading obvious and easier to start.","zh":"這個小行動令閱讀變得明顯，也更容易開始。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"before using their phone","meaning":"在使用電話之前","examples":[{"en":"Students could read two pages before using their phone.","zh":"學生可以在使用電話之前閱讀兩頁。"},{"en":"Before using their phone means earlier than checking messages, apps, or social media.","zh":"before using their phone 指在查看訊息、應用程式或社交媒體之前。"},{"en":"A student may read for five minutes before using their phone after school.","zh":"學生放學後可以在使用電話之前閱讀五分鐘。"},{"en":"Linking reading to phone use can help students control distractions.","zh":"把閱讀與使用電話連繫起來，可以幫助學生控制分心。"},{"en":"This habit works because it places reading before a strong temptation.","zh":"這個習慣有效，因為它把閱讀放在強烈誘惑之前。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"record their progress","meaning":"記錄進度","examples":[{"en":"Students could record their progress on a tracker.","zh":"學生可以在記錄表上記錄進度。"},{"en":"To record their progress means to write down or mark what they have completed.","zh":"record their progress 指寫下或標記自己已完成的事情。"},{"en":"A runner records progress by noting distance and time after each practice.","zh":"跑手每次練習後記下距離和時間，就是記錄進度。"},{"en":"Recording progress helps people see improvement that may feel slow day by day.","zh":"記錄進度幫助人看見每日可能感覺緩慢的改善。"},{"en":"Students who record their reading may feel more motivated to continue.","zh":"記錄閱讀進度的學生可能更有動力繼續。"}],"source":"2015 Q9.pdf","sourcePage":5},{"front":"progress tracker","meaning":"進度記錄表","examples":[{"en":"A progress tracker can help students keep reading.","zh":"進度記錄表可以幫助學生持續閱讀。"},{"en":"A progress tracker is a tool used to record and show what someone has completed over time.","zh":"progress tracker 指用來記錄和顯示某人一段時間內完成了甚麼的工具。"},{"en":"A calendar with check marks can be a simple progress tracker.","zh":"有剔號的月曆可以是一個簡單的進度記錄表。"},{"en":"Progress trackers make invisible effort visible, which can encourage people.","zh":"進度記錄表把看不見的努力變得可見，能鼓勵人。"},{"en":"A reading tracker helps students see that small daily actions are adding up.","zh":"閱讀記錄表幫助學生看見每日小行動正在累積。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"little by little","meaning":"一點一點地","examples":[{"en":"Little by little, reading can become part of a student’s identity.","zh":"一點一點地，閱讀可以成為學生身份的一部分。"},{"en":"Little by little means gradually, through small steps over time.","zh":"little by little 指透過小步驟，隨時間逐漸發生。"},{"en":"Little by little, a shy student may become more confident in group discussion.","zh":"一點一點地，害羞學生可能在小組討論中變得更有信心。"},{"en":"Habits often change little by little rather than all at once.","zh":"習慣常是一點一點地改變，而不是一次過改變。"},{"en":"This phrase encourages patience because progress may be slow but real.","zh":"這個短語鼓勵耐性，因為進步可能緩慢但真實。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"what once felt like","meaning":"曾經感覺像……的事物","examples":[{"en":"What once felt like a burden can become part of their identity.","zh":"曾經感覺像負擔的事物，可以成為他們身份的一部分。"},{"en":"What once felt like means something that used to seem or feel a certain way.","zh":"what once felt like 指某事物過去曾經看似或感覺像某種情況。"},{"en":"What once felt like a boring chore may become a relaxing routine.","zh":"曾經感覺像沉悶雜務的事，可能變成放鬆的日常。"},{"en":"This phrase shows that people’s feelings about an activity can change over time.","zh":"這個短語顯示人們對活動的感覺會隨時間改變。"},{"en":"Reading may once feel heavy, but small success can change that feeling.","zh":"閱讀曾經可能感覺沉重，但小成功可以改變那種感覺。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"a burden","meaning":"負擔","examples":[{"en":"Reading may once have felt like a burden.","zh":"閱讀可能曾經感覺像負擔。"},{"en":"A burden is something that feels heavy, difficult, or stressful to carry or do.","zh":"burden 指讓人覺得沉重、困難或有壓力去承擔或完成的事。"},{"en":"Extra homework can feel like a burden when students are already tired.","zh":"當學生已經疲倦時，額外功課可能感覺像負擔。"},{"en":"A burden becomes lighter when it is broken into small manageable steps.","zh":"當負擔被分成可處理的小步驟時，就會變得較輕。"},{"en":"Reading stops feeling like a burden when students find meaning and routine in it.","zh":"當學生在閱讀中找到意義和常規時，閱讀就不再像負擔。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"become part of their identity","meaning":"成為他們身份的一部分","examples":[{"en":"Reading can become part of students’ identity.","zh":"閱讀可以成為學生身份的一部分。"},{"en":"To become part of their identity means to become something they see as part of who they are.","zh":"become part of their identity 指成為他們認為屬於自己的一部分。"},{"en":"A student who runs every morning may begin to see exercise as part of their identity.","zh":"每天早上跑步的學生，可能開始把運動視為自己身份的一部分。"},{"en":"Habits become stronger when people think, “This is what I do.”","zh":"當人們認為「這就是我會做的事」時，習慣會變得更強。"},{"en":"Reading becomes part of identity when students see themselves as readers, not just exam takers.","zh":"當學生視自己為讀者，而不只是應試者時，閱讀就成為身份的一部分。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, inviting him would promote both interest and discipline.","zh":"簡單來說，邀請他會同時推廣興趣和自律。"},{"en":"Put simply means to explain an idea in a short and clear way.","zh":"put simply 指用簡短清楚的方式解釋一個想法。"},{"en":"Put simply, a habit is easier to keep when it is small and visible.","zh":"簡單來說，當習慣細小而看得見時，就較容易保持。"},{"en":"Writers use this phrase before giving the main point without extra detail.","zh":"作者在不加額外細節地提出重點前，會使用這個短語。"},{"en":"It helps readers understand the conclusion quickly.","zh":"它幫助讀者快速理解結論。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"allow Reading Week to","meaning":"讓閱讀週能夠","examples":[{"en":"Inviting him would allow Reading Week to promote better habits.","zh":"邀請他會讓閱讀週能夠推廣更好的習慣。"},{"en":"To allow Reading Week to do something means to make it possible for the event to achieve that result.","zh":"allow Reading Week to do something 指令閱讀週有可能達到某個效果。"},{"en":"A book fair can allow Reading Week to reach students who rarely visit the library.","zh":"書展可以讓閱讀週接觸很少到圖書館的學生。"},{"en":"Good planning allows an event to have long-term influence.","zh":"良好規劃讓活動能夠產生長遠影響。"},{"en":"Inviting the right speaker could allow Reading Week to become practical, not only celebratory.","zh":"邀請合適講者可以讓閱讀週變得實用，而不只是慶祝性活動。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"promote a love of books","meaning":"推廣對書本的熱愛","examples":[{"en":"Reading Week should promote a love of books.","zh":"閱讀週應推廣對書本的熱愛。"},{"en":"To promote a love of books means to encourage people to enjoy and value reading.","zh":"promote a love of books 指鼓勵人們享受並重視閱讀。"},{"en":"A library display can promote a love of books by showing exciting choices.","zh":"圖書館展覽可以透過展示有趣選擇，推廣對書本的熱愛。"},{"en":"Teachers promote a love of books when they let students talk honestly about what they like.","zh":"當老師讓學生誠實談論自己喜歡甚麼時，就是推廣對書本的熱愛。"},{"en":"A love of books grows best when reading feels meaningful, not forced.","zh":"當閱讀感覺有意義而不是被強迫時，對書本的熱愛最容易成長。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"not only…, but also…","meaning":"不只……而且……","examples":[{"en":"The event would promote not only a love of books, but also discipline.","zh":"這項活動不只會推廣對書本的熱愛，而且會推廣自律。"},{"en":"Not only…, but also… adds a second important idea to the first one.","zh":"not only…, but also… 在第一個重要想法之外，再加入第二個重要想法。"},{"en":"Reading builds not only vocabulary, but also patience.","zh":"閱讀不只建立詞彙，而且建立耐性。"},{"en":"This structure shows that both benefits matter.","zh":"這個結構顯示兩個好處都重要。"},{"en":"In this letter, the event is valuable because it develops both interest and self-control.","zh":"在這封信中，這項活動有價值，因為它同時培養興趣和自制力。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"the discipline needed to","meaning":"做……所需的自律","examples":[{"en":"Students need the discipline needed to keep reading.","zh":"學生需要持續閱讀所需的自律。"},{"en":"The discipline needed to do something means the self-control required to continue doing it.","zh":"the discipline needed to do something 指持續做某事所需的自制力。"},{"en":"Athletes need the discipline needed to train even when they feel tired.","zh":"運動員需要即使疲倦也繼續訓練所需的自律。"},{"en":"Reading regularly requires discipline because distractions are easy to find.","zh":"定期閱讀需要自律，因為分心事物很容易找到。"},{"en":"The phrase shows that enjoyment alone may not be enough for long-term habits.","zh":"這個短語顯示，單靠享受未必足以維持長期習慣。"}],"source":"2015 Q9.pdf","sourcePage":6},{"front":"keep reading","meaning":"持續閱讀","examples":[{"en":"Students need discipline to keep reading after the event.","zh":"學生需要自律，才能在活動後持續閱讀。"},{"en":"To keep reading means to continue reading regularly instead of stopping after a short time.","zh":"keep reading 指定期繼續閱讀，而不是短時間後停止。"},{"en":"A student can keep reading by choosing a short book and setting a fixed time.","zh":"學生可以透過選擇短書和設定固定時間來持續閱讀。"},{"en":"People keep reading when books feel useful, enjoyable, and easy to reach.","zh":"當書本感覺有用、有趣和容易拿到時，人們會持續閱讀。"},{"en":"Reading Week succeeds if students keep reading after the activities end.","zh":"如果學生在活動結束後仍持續閱讀，閱讀週才算成功。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"after the event","meaning":"活動之後","examples":[{"en":"Students should keep reading after the event.","zh":"學生應在活動之後持續閱讀。"},{"en":"After the event means when the activity has finished.","zh":"after the event 指活動結束之後。"},{"en":"After the event, students may borrow the speaker’s recommended books from the library.","zh":"活動之後，學生可以到圖書館借講者推薦的書。"},{"en":"A school activity has more value when learning continues after the event.","zh":"當學習在活動之後繼續，學校活動就更有價值。"},{"en":"The letter argues that the talk should create habits that last beyond one evening.","zh":"這封信主張講座應創造能超越一晚的習慣。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"particularly suitable for","meaning":"特別適合","examples":[{"en":"Atomic Habits is particularly suitable for improving students’ English.","zh":"《Atomic Habits》特別適合提升學生英文。"},{"en":"Particularly suitable for means especially appropriate or useful for a certain purpose.","zh":"particularly suitable for 指對某目的特別合適或有用。"},{"en":"Short stories are particularly suitable for students who are beginning to read independently.","zh":"短篇故事特別適合開始獨立閱讀的學生。"},{"en":"A practical book may be suitable for English learning because students can reuse its vocabulary.","zh":"實用書可能適合英文學習，因為學生可以重用其中詞彙。"},{"en":"This phrase helps explain why one choice fits better than others.","zh":"這個短語有助解釋為何某選擇比其他選擇更合適。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"practical, modern and accessible","meaning":"實用、現代而易懂","examples":[{"en":"The book is practical, modern and accessible.","zh":"這本書實用、現代而易懂。"},{"en":"Practical, modern and accessible means useful, connected to present-day life, and easy to understand.","zh":"practical, modern and accessible 指有用、與現代生活相連，並容易理解。"},{"en":"A good student guide should be practical, modern and accessible.","zh":"好的學生指南應該實用、現代而易懂。"},{"en":"These qualities help reluctant readers because the book does not feel old-fashioned or difficult.","zh":"這些特質幫助抗拒閱讀的人，因為書本不會感覺過時或困難。"},{"en":"A practical and accessible book can make English reading less frightening.","zh":"實用而易懂的書可以令英文閱讀較不令人害怕。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"assume that","meaning":"假設；以為","examples":[{"en":"Some students assume that good English can only be learned through novels.","zh":"有些學生以為好英文只能透過小說學到。"},{"en":"To assume that means to believe something is true without fully checking it.","zh":"assume that 指在沒有完全查證下相信某事是真的。"},{"en":"Some people assume that quiet students have no opinions.","zh":"有些人以為安靜學生沒有意見。"},{"en":"Assumptions can limit learning when they stop people trying other methods.","zh":"當假設阻止人們嘗試其他方法時，它會限制學習。"},{"en":"Students may assume novels are the only path, but non-fiction can also help.","zh":"學生可能以為小說是唯一途徑，但非小說作品也能幫助學習。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"classic novels","meaning":"經典小說","examples":[{"en":"Some students think English must be learned through classic novels.","zh":"有些學生認為英文必須透過經典小說學習。"},{"en":"Classic novels are famous older works of fiction that are widely respected.","zh":"classic novels 指廣受尊重的著名較舊小說作品。"},{"en":"Students may read classic novels such as stories by Dickens or Austen in literature lessons.","zh":"學生可能在文學課閱讀 Dickens 或 Austen 等作家的經典小說。"},{"en":"Classic novels can improve language, but they may feel difficult for beginners.","zh":"經典小說可以提升語言能力，但對初學者可能感覺困難。"},{"en":"Reading English should not depend only on classic novels; useful non-fiction also matters.","zh":"英文閱讀不應只依靠經典小說；有用的非小說作品也很重要。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"examination passages","meaning":"考試篇章","examples":[{"en":"Students often learn English through examination passages.","zh":"學生常透過考試篇章學習英文。"},{"en":"Examination passages are reading texts used in tests or exam practice.","zh":"examination passages 指測驗或考試練習中使用的閱讀文本。"},{"en":"A student may answer questions about tone, vocabulary, and main ideas after reading examination passages.","zh":"學生閱讀考試篇章後，可能要回答關於語氣、詞彙和主旨的問題。"},{"en":"Examination passages help test skills, but they may not always build a love of reading.","zh":"考試篇章有助測試技巧，但未必能建立對閱讀的熱愛。"},{"en":"Students need reading beyond examination passages if they are to see English as part of life.","zh":"如果學生要把英文視為生活一部分，就需要考試篇章以外的閱讀。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"this is not to say that","meaning":"這並不是說","examples":[{"en":"This is not to say that literature is unimportant.","zh":"這並不是說文學不重要。"},{"en":"This is not to say that means the writer is clarifying that they are not making an extreme claim.","zh":"this is not to say that 指作者澄清自己並不是在提出極端說法。"},{"en":"This is not to say that exams do not matter, but learning should be wider than exams.","zh":"這並不是說考試不重要，而是學習應比考試更廣闊。"},{"en":"Writers use this phrase to avoid misunderstanding and show balance.","zh":"作者使用這個短語來避免誤解並顯示平衡。"},{"en":"The phrase allows the writer to support non-fiction without attacking literature.","zh":"這個短語讓作者支持非小說作品，而不攻擊文學。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"literature","meaning":"文學","examples":[{"en":"This is not to say that literature is unimportant.","zh":"這並不是說文學不重要。"},{"en":"Literature means written works with artistic value, such as novels, poems, plays, and stories.","zh":"literature 指有藝術價值的文字作品，例如小說、詩歌、劇本和故事。"},{"en":"Literature helps students understand language, emotion, culture, and human choices.","zh":"文學幫助學生理解語言、情感、文化和人的選擇。"},{"en":"Some students find literature difficult because it often uses symbolism and older language.","zh":"有些學生覺得文學困難，因為它常使用象徵和較舊語言。"},{"en":"Literature is important, but it is not the only useful form of English reading.","zh":"文學很重要，但它不是唯一有用的英文閱讀形式。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"rather","meaning":"而是","examples":[{"en":"Rather, non-fiction can serve as a bridge.","zh":"而是，非小說類作品可以充當橋樑。"},{"en":"Rather is used to correct or replace a previous idea with a more accurate one.","zh":"rather 用來修正或取代前一個想法，並提出更準確的說法。"},{"en":"The aim is not to make homework longer; rather, it is to make practice clearer.","zh":"目標不是令功課更長；而是令練習更清晰。"},{"en":"This word helps writers shift from what they do not mean to what they really mean.","zh":"這個詞幫助作者由自己不是甚麼意思，轉到真正意思。"},{"en":"In this sentence, rather introduces non-fiction as a helpful path, not a threat to literature.","zh":"在這句中，rather 把非小說作品介紹為有幫助的途徑，而不是文學的威脅。"}],"source":"2015 Q9.pdf","sourcePage":7},{"front":"serve as a bridge","meaning":"充當橋樑","examples":[{"en":"Non-fiction can serve as a bridge for students.","zh":"非小說類作品可以為學生充當橋樑。"},{"en":"To serve as a bridge means to connect two things and help people move from one to the other.","zh":"serve as a bridge 指連接兩件事，幫助人由一方走向另一方。"},{"en":"Short articles can serve as a bridge between textbook English and real-life reading.","zh":"短文章可以充當課本英文與真實生活閱讀之間的橋樑。"},{"en":"A bridge is useful when the final goal feels too difficult at first.","zh":"當最終目標起初感覺太難時，橋樑很有用。"},{"en":"Accessible non-fiction can bridge reluctant readers and more challenging books.","zh":"易懂的非小說作品可以連接抗拒閱讀者和更具挑戰的書本。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"find long stories intimidating","meaning":"覺得長篇故事令人卻步","examples":[{"en":"Some students find long stories intimidating.","zh":"有些學生覺得長篇故事令人卻步。"},{"en":"To find long stories intimidating means to feel nervous or discouraged when facing lengthy fiction.","zh":"find long stories intimidating 指面對長篇小說時感到緊張或退縮。"},{"en":"A beginner may find long stories intimidating if there are too many characters.","zh":"如果角色太多，初學者可能覺得長篇故事令人卻步。"},{"en":"Students often avoid texts that look too long before they even begin reading.","zh":"學生常在開始閱讀前，已避開看起來太長的文本。"},{"en":"Shorter non-fiction can help these students start with less fear.","zh":"較短的非小說作品可以幫助這些學生較少恐懼地開始。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"intimidating","meaning":"令人卻步的","examples":[{"en":"Long stories may feel intimidating to some students.","zh":"長篇故事對一些學生來說可能令人卻步。"},{"en":"Intimidating means frightening, difficult, or discouraging to approach.","zh":"intimidating 指令人害怕、覺得困難或不敢接近的。"},{"en":"A thick English novel can look intimidating to a student who rarely reads.","zh":"對很少閱讀的學生來說，一本厚英文小說可能令人卻步。"},{"en":"Tasks feel less intimidating when they are divided into small steps.","zh":"當任務被分成小步驟時，就會較不令人卻步。"},{"en":"Reading becomes less intimidating when students begin with clear and useful texts.","zh":"當學生由清晰而有用的文本開始時，閱讀會較不令人卻步。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"useful vocabulary connected with","meaning":"與……有關的實用詞彙","examples":[{"en":"The book introduces useful vocabulary connected with routines and motivation.","zh":"這本書介紹與日常習慣和動力有關的實用詞彙。"},{"en":"Useful vocabulary connected with something means practical words related to that topic.","zh":"useful vocabulary connected with something 指與某主題有關的實用詞語。"},{"en":"A health article introduces useful vocabulary connected with exercise, sleep, and diet.","zh":"健康文章介紹與運動、睡眠和飲食有關的實用詞彙。"},{"en":"Topic-based vocabulary is easier to remember because the words support one another.","zh":"以主題組織的詞彙較容易記住，因為詞語彼此支援。"},{"en":"Students can use vocabulary about routines and motivation in speaking and writing.","zh":"學生可以在說話和寫作中使用關於日常習慣和動力的詞彙。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"routines","meaning":"日常習慣；常規","examples":[{"en":"Atomic Habits discusses routines and self-control.","zh":"《Atomic Habits》討論日常習慣和自制力。"},{"en":"Routines are regular actions or habits repeated in daily life.","zh":"routines 指日常生活中定期重複的行動或習慣。"},{"en":"A morning routine may include brushing teeth, packing a schoolbag, and reading for five minutes.","zh":"早晨常規可能包括刷牙、收拾書包和閱讀五分鐘。"},{"en":"Routines reduce effort because people do not need to decide every time.","zh":"常規能減少努力，因為人們不需要每次重新決定。"},{"en":"Good routines help students keep studying even when motivation is low.","zh":"良好日常習慣幫助學生即使動力低，也能持續學習。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"motivation","meaning":"動力","examples":[{"en":"The book includes vocabulary about motivation.","zh":"這本書包括關於動力的詞彙。"},{"en":"Motivation is the reason or desire that makes someone want to do something.","zh":"motivation 指令人想做某事的原因或意願。"},{"en":"A student may lose motivation when progress feels too slow.","zh":"當進步感覺太慢時，學生可能失去動力。"},{"en":"Motivation can start a habit, but systems and routines help maintain it.","zh":"動力可以開始一個習慣，但系統和常規幫助維持它。"},{"en":"Understanding motivation helps students explain why they begin, stop, or continue tasks.","zh":"理解動力幫助學生解釋自己為何開始、停止或繼續任務。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"identity","meaning":"身份認同","examples":[{"en":"The book explores the link between habits and identity.","zh":"這本書探討習慣與身份認同之間的連繫。"},{"en":"Identity means how people understand who they are and what kind of person they are becoming.","zh":"identity 指人們如何理解自己是誰，以及正在成為怎樣的人。"},{"en":"A student who reads every day may begin to see reading as part of their identity.","zh":"每天閱讀的學生可能開始把閱讀視為身份的一部分。"},{"en":"Habits can shape identity because repeated actions affect self-image.","zh":"習慣能塑造身份認同，因為重複行動會影響自我形象。"},{"en":"Identity matters because people act more consistently when behaviour matches who they believe they are.","zh":"身份認同很重要，因為當行為符合人們相信自己是誰時，他們會更持續地行動。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"progress","meaning":"進步；進展","examples":[{"en":"Students can learn vocabulary about progress.","zh":"學生可以學習關於進步的詞彙。"},{"en":"Progress means improvement or movement toward a goal.","zh":"progress 指朝目標改善或前進。"},{"en":"A student shows progress when they can read longer passages with less help.","zh":"當學生能在較少幫助下閱讀更長篇章時，就顯示有進步。"},{"en":"Progress may be slow at first, but small improvements still matter.","zh":"進步起初可能緩慢，但小改善仍然重要。"},{"en":"Tracking progress can help students notice that their effort is working.","zh":"記錄進展可以幫助學生注意到自己的努力正在有效。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"self-control","meaning":"自制力","examples":[{"en":"The book introduces ideas about self-control.","zh":"這本書介紹關於自制力的想法。"},{"en":"Self-control is the ability to manage your actions, emotions, or desires.","zh":"self-control 指管理自己行動、情緒或慾望的能力。"},{"en":"A student uses self-control when they finish reading before checking messages.","zh":"學生在查看訊息前先完成閱讀，就是運用自制力。"},{"en":"Self-control is easier when the environment makes good choices simple.","zh":"當環境令好選擇變得簡單時，自制力會較容易發揮。"},{"en":"Reading habits need self-control because distractions are always nearby.","zh":"閱讀習慣需要自制力，因為分心事物總在附近。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"speaking, writing and reflection","meaning":"說話、寫作和反思","examples":[{"en":"Students can use these topics in speaking, writing and reflection.","zh":"學生可以在說話、寫作和反思中使用這些題材。"},{"en":"Speaking, writing and reflection are ways students express ideas aloud, in text, and through personal thinking.","zh":"speaking, writing and reflection 指學生透過口頭、文字和個人思考表達想法的方式。"},{"en":"A reading activity can lead to speaking, writing and reflection when students discuss and journal about it.","zh":"當學生討論並寫日誌時，閱讀活動可以引向說話、寫作和反思。"},{"en":"These skills help students move from understanding a book to using its ideas.","zh":"這些技能幫助學生由理解一本書，走向運用其中想法。"},{"en":"Topics like habits and motivation are useful because students can apply them in many tasks.","zh":"習慣和動力等主題很有用，因為學生可以在許多任務中應用它們。"}],"source":"2015 Q9.pdf","sourcePage":8},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, Clear’s style is well-structured.","zh":"更好的是，Clear 的寫作風格結構清晰。"},{"en":"Better still means even better than the point just mentioned.","zh":"better still 指比剛才提到的優點更好的是。"},{"en":"The book is short; better still, each chapter gives practical examples.","zh":"這本書很短；更好的是，每章都提供實用例子。"},{"en":"Writers use better still to add a stronger advantage.","zh":"作者使用 better still 來加入更強的優點。"},{"en":"This phrase helps build a positive argument step by step.","zh":"這個短語幫助一步一步建立正面論點。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"well-structured","meaning":"結構清晰的","examples":[{"en":"Clear’s writing style is well-structured.","zh":"Clear 的寫作風格結構清晰。"},{"en":"Well-structured means organised clearly, with ideas arranged in a logical order.","zh":"well-structured 指組織清楚，想法按合邏輯次序安排。"},{"en":"A well-structured essay has a clear introduction, body paragraphs, and conclusion.","zh":"結構清晰的文章有清楚引言、正文段落和結論。"},{"en":"Well-structured writing helps readers follow the argument without confusion.","zh":"結構清晰的寫作幫助讀者不混亂地跟隨論點。"},{"en":"Students can learn from well-structured non-fiction because it shows how ideas are built.","zh":"學生可以從結構清晰的非小說作品中學習，因為它展示想法如何建立。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"an excellent model for","meaning":"……的出色範例","examples":[{"en":"The book is an excellent model for DSE writing.","zh":"這本書是文憑試寫作的出色範例。"},{"en":"An excellent model for something is a very good example that people can learn from.","zh":"an excellent model for something 指可供人學習的非常好例子。"},{"en":"A clear speech can be an excellent model for students learning public speaking.","zh":"清晰演講可以成為學生學習公開演說的出色範例。"},{"en":"Students improve writing by studying models that show strong organisation and examples.","zh":"學生透過研究展示良好組織和例子的範本來改善寫作。"},{"en":"Atomic Habits can model how to explain a problem, give examples, and offer solutions.","zh":"《Atomic Habits》可以示範如何解釋問題、給出例子和提供解決方法。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"DSE writing","meaning":"文憑試寫作","examples":[{"en":"Clear’s style can help students improve DSE writing.","zh":"Clear 的風格可以幫助學生改善文憑試寫作。"},{"en":"DSE writing refers to writing tasks in the Hong Kong Diploma of Secondary Education examination.","zh":"DSE writing 指香港中學文憑考試中的寫作任務。"},{"en":"DSE writing often requires clear arguments, examples, organisation, and suitable tone.","zh":"文憑試寫作常需要清楚論點、例子、組織和合適語氣。"},{"en":"Students can improve DSE writing by reading well-structured English texts.","zh":"學生可以透過閱讀結構清晰的英文文本改善文憑試寫作。"},{"en":"A practical non-fiction style may help students explain ideas more clearly in exams.","zh":"實用的非小說風格可能幫助學生在考試中更清楚解釋想法。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"observe how","meaning":"觀察如何","examples":[{"en":"Students can observe how an argument is built.","zh":"學生可以觀察論點如何建立。"},{"en":"To observe how something happens means to look carefully and learn the process.","zh":"observe how something happens 指仔細觀看並學習過程。"},{"en":"Students can observe how a teacher solves a maths problem step by step.","zh":"學生可以觀察老師如何一步一步解數學題。"},{"en":"Observing how a writer explains ideas helps students copy useful structures.","zh":"觀察作者如何解釋想法，幫助學生模仿有用結構。"},{"en":"This phrase emphasises learning by watching the method, not just the result.","zh":"這個短語強調學習方法，而不只是看結果。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"an argument is built","meaning":"論點如何建立","examples":[{"en":"Students can observe how an argument is built.","zh":"學生可以觀察論點如何建立。"},{"en":"An argument is built when a writer develops a claim with reasons, examples, and explanation.","zh":"an argument is built 指作者用理由、例子和解釋發展主張。"},{"en":"In an essay, an argument is built paragraph by paragraph.","zh":"在文章中，論點是一段一段建立起來的。"},{"en":"A weak argument fails when it gives opinions without support.","zh":"如果只給意見而沒有支持，論點就會薄弱。"},{"en":"Learning how an argument is built helps students write more convincing essays.","zh":"學會論點如何建立，能幫助學生寫出更有說服力的文章。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"a problem is introduced","meaning":"問題被提出","examples":[{"en":"In Clear’s writing, a problem is introduced first.","zh":"在 Clear 的寫作中，問題會先被提出。"},{"en":"A problem is introduced means the writer first presents the difficulty or issue to be solved.","zh":"a problem is introduced 指作者先提出需要解決的困難或議題。"},{"en":"In a good essay, a problem is introduced before the writer suggests solutions.","zh":"在好文章中，作者會在建議解決方法前先提出問題。"},{"en":"Introducing the problem helps readers understand why the topic matters.","zh":"提出問題幫助讀者理解主題為何重要。"},{"en":"Students can learn that clear writing often begins by showing the problem.","zh":"學生可以學到清晰寫作常由展示問題開始。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"an example is given","meaning":"例子被提出","examples":[{"en":"After the problem is introduced, an example is given.","zh":"問題被提出後，例子會被提出。"},{"en":"An example is given means a specific case is provided to make an idea clearer.","zh":"an example is given 指提供一個具體個案，使想法更清楚。"},{"en":"When teaching new vocabulary, a teacher explains the meaning and then gives an example.","zh":"老師教授新詞彙時，會先解釋意思，然後提出例子。"},{"en":"Examples help readers understand abstract ideas through real situations.","zh":"例子透過真實情況幫助讀者理解抽象想法。"},{"en":"Good writing uses examples so readers do not feel lost in theory.","zh":"好寫作會使用例子，讓讀者不會迷失在理論中。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"a principle is explained","meaning":"原則被解釋","examples":[{"en":"A principle is explained after the example.","zh":"例子之後，原則會被解釋。"},{"en":"A principle is explained means the general rule or idea behind the example is made clear.","zh":"a principle is explained 指例子背後的一般規則或想法被清楚說明。"},{"en":"After showing a science experiment, the teacher explains the principle behind it.","zh":"展示科學實驗後，老師會解釋背後原則。"},{"en":"Explaining a principle helps students use the idea in new situations.","zh":"解釋原則幫助學生把想法用於新情況。"},{"en":"This structure moves from concrete example to broader understanding.","zh":"這個結構由具體例子走向更廣泛理解。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"an action step follows","meaning":"接着是行動步驟","examples":[{"en":"An action step follows the explanation.","zh":"解釋之後，接着是行動步驟。"},{"en":"An action step follows means a practical thing to do comes after the explanation.","zh":"an action step follows 指解釋之後出現一個實際可做的行動。"},{"en":"After a talk about health, an action step may be to drink more water each day.","zh":"健康講座後，行動步驟可能是每天多喝水。"},{"en":"Action steps help people turn ideas into behaviour.","zh":"行動步驟幫助人們把想法轉化為行為。"},{"en":"A writing structure with action steps feels practical because readers know what to do next.","zh":"有行動步驟的寫作結構感覺實用，因為讀者知道下一步做甚麼。"}],"source":"2015 Q9.pdf","sourcePage":9},{"front":"as useful for… as…","meaning":"對……和對……一樣有用","examples":[{"en":"This structure is as useful for writing an essay as it is for changing a habit.","zh":"這個結構對寫文章和對改變習慣一樣有用。"},{"en":"As useful for one thing as another means equally helpful in both situations.","zh":"as useful for one thing as another 指在兩種情況中同樣有幫助。"},{"en":"Planning is as useful for group projects as it is for personal study.","zh":"計劃對小組專題和對個人溫習一樣有用。"},{"en":"This pattern compares two uses and shows both have value.","zh":"這個句式比較兩種用途，並顯示兩者都有價值。"},{"en":"Clear structure can help students organise both their writing and their habits.","zh":"清晰結構可以幫助學生組織寫作，也幫助他們組織習慣。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"writing an essay","meaning":"寫文章","examples":[{"en":"The structure is useful for writing an essay.","zh":"這個結構對寫文章有用。"},{"en":"Writing an essay means producing a piece of organised writing about a topic or argument.","zh":"writing an essay 指就某個題目或論點寫出有組織的文章。"},{"en":"Students writing an essay need a clear point, examples, and explanation.","zh":"學生寫文章時需要清楚觀點、例子和解釋。"},{"en":"Writing an essay becomes easier when the writer knows the structure before beginning.","zh":"當作者開始前知道結構時，寫文章會變得較容易。"},{"en":"Reading well-organised books can give students models for essay writing.","zh":"閱讀組織良好的書，可以給學生寫文章的範本。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"changing a habit","meaning":"改變習慣","examples":[{"en":"The structure is also useful for changing a habit.","zh":"這個結構對改變習慣也有用。"},{"en":"Changing a habit means replacing an old pattern of behaviour with a new one.","zh":"changing a habit 指用新行為模式取代舊有行為模式。"},{"en":"A student changing a habit may put their phone outside the bedroom at night.","zh":"正在改變習慣的學生，可能晚上把電話放在睡房外。"},{"en":"Habit change works better when the new action is small and specific.","zh":"當新行動細小而具體時，改變習慣會更有效。"},{"en":"The same clear structure that helps writing can also help people change behaviour.","zh":"幫助寫作的同一清晰結構，也可以幫助人改變行為。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"make the evening engaging","meaning":"令晚會更吸引","examples":[{"en":"The activities would make the evening engaging.","zh":"這些活動會令晚會更吸引。"},{"en":"To make the evening engaging means to make the event interesting enough to hold people’s attention.","zh":"make the evening engaging 指令活動有趣到能抓住人們的注意力。"},{"en":"Games, questions, and real examples can make a school talk engaging.","zh":"遊戲、問題和真實例子可以令學校講座更吸引。"},{"en":"An engaging evening makes students participate instead of only sitting silently.","zh":"吸引的晚會會令學生參與，而不只是安靜坐着。"},{"en":"Activities matter because they help turn a speech into an experience.","zh":"活動很重要，因為它們幫助把演講變成體驗。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"lead three activities","meaning":"主持三項活動","examples":[{"en":"Mr Clear could lead three activities.","zh":"Clear 先生可以主持三項活動。"},{"en":"To lead three activities means to guide, run, or host three organised parts of an event.","zh":"lead three activities 指引導、負責或主持活動中的三個有組織部分。"},{"en":"A teacher may lead three activities during an English workshop.","zh":"老師可能在英文工作坊中主持三項活動。"},{"en":"Leading activities requires clear instructions so participants know what to do.","zh":"主持活動需要清楚指示，讓參加者知道做甚麼。"},{"en":"If Mr Clear leads activities, students may become more involved than in a normal talk.","zh":"如果 Clear 先生主持活動，學生可能比普通講座更投入。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"a short talk entitled","meaning":"題為……的簡短演講","examples":[{"en":"The first activity could be a short talk entitled “How to Build an English Reading Habit.”","zh":"第一項活動可以是題為「如何建立英文閱讀習慣」的簡短演講。"},{"en":"A short talk entitled something means a brief speech with that title.","zh":"a short talk entitled something 指以某個題目命名的簡短演講。"},{"en":"The teacher gave a short talk entitled “How to Study Without Panic.”","zh":"老師作了一個題為「如何不慌張地溫習」的簡短演講。"},{"en":"A clear title tells the audience what the talk will help them understand.","zh":"清楚題目告訴觀眾講座會幫助他們理解甚麼。"},{"en":"A short talk works well when students need direct advice without too much theory.","zh":"當學生需要直接建議而不是太多理論時，簡短演講很有效。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"build an English reading habit","meaning":"建立英文閱讀習慣","examples":[{"en":"The talk could explain how to build an English reading habit.","zh":"講座可以解釋如何建立英文閱讀習慣。"},{"en":"To build an English reading habit means to make reading English a regular part of daily life.","zh":"build an English reading habit 指令英文閱讀成為日常生活中的固定部分。"},{"en":"A student can build an English reading habit by reading one article after breakfast.","zh":"學生可以透過早餐後閱讀一篇文章，建立英文閱讀習慣。"},{"en":"The habit becomes stronger when the reading time and place are fixed.","zh":"當閱讀時間和地點固定時，習慣會變得更強。"},{"en":"Building an English reading habit helps language improve naturally over time.","zh":"建立英文閱讀習慣有助語言能力隨時間自然提升。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"start with a habit so small that","meaning":"從小到……的習慣開始","examples":[{"en":"Students can start with a habit so small that it is almost impossible to refuse.","zh":"學生可以從小到幾乎不可能拒絕的習慣開始。"},{"en":"Start with a habit so small that means begin with an action easy enough to avoid resistance.","zh":"start with a habit so small that 指由容易到不會產生抗拒的行動開始。"},{"en":"A student may start with a habit so small that reading one sentence counts as success.","zh":"學生可以從小到讀一句也算成功的習慣開始。"},{"en":"Tiny habits reduce fear because they do not feel like a heavy demand.","zh":"微小習慣能減少恐懼，因為它們不感覺像沉重要求。"},{"en":"Starting small helps students build confidence before increasing the challenge.","zh":"從小開始能幫助學生在增加挑戰前建立信心。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"almost impossible to refuse","meaning":"幾乎不可能拒絕","examples":[{"en":"The habit should be almost impossible to refuse.","zh":"這個習慣應該幾乎不可能拒絕。"},{"en":"Almost impossible to refuse means so easy or attractive that people have little reason to say no.","zh":"almost impossible to refuse 指容易或吸引到人幾乎沒有理由拒絕。"},{"en":"Reading one line a day is almost impossible to refuse because it takes less than a minute.","zh":"每天讀一行幾乎不可能拒絕，因為它少於一分鐘便能完成。"},{"en":"A habit that is almost impossible to refuse is easier to repeat.","zh":"幾乎不可能拒絕的習慣較容易重複。"},{"en":"This idea helps students overcome the first barrier: starting.","zh":"這個想法幫助學生克服第一個障礙：開始。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"one paragraph a day","meaning":"每日一段","examples":[{"en":"Students could begin by reading one paragraph a day.","zh":"學生可以由每日閱讀一段開始。"},{"en":"One paragraph a day means a small daily reading amount of just one section of text.","zh":"one paragraph a day 指每天只閱讀一小段文字的細小閱讀量。"},{"en":"A busy student can still read one paragraph a day before sleeping.","zh":"繁忙學生仍可以在睡前每日閱讀一段。"},{"en":"This goal is small enough to feel possible even during exam periods.","zh":"這個目標夠小，即使在考試期間也感覺可行。"},{"en":"One paragraph a day can grow into one page, then one chapter, over time.","zh":"每日一段可以隨時間增長成每日一頁，然後一章。"}],"source":"2015 Q9.pdf","sourcePage":10},{"front":"mini workshop","meaning":"小型工作坊","examples":[{"en":"The second activity could be a mini workshop.","zh":"第二項活動可以是小型工作坊。"},{"en":"A mini workshop is a short practical session where participants learn by doing.","zh":"mini workshop 指參加者透過實踐學習的簡短實用環節。"},{"en":"A mini workshop on note-taking may ask students to practise with a short article.","zh":"關於筆記技巧的小型工作坊，可能要求學生用短文章練習。"},{"en":"Workshops are useful because students do not only listen; they try the skill themselves.","zh":"工作坊有用，因為學生不只是聆聽，而是親自嘗試技能。"},{"en":"A mini workshop can make a reading event more active and memorable.","zh":"小型工作坊可以令閱讀活動更主動和難忘。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"Design Your Reading Environment","meaning":"設計你的閱讀環境","examples":[{"en":"The workshop could be called “Design Your Reading Environment.”","zh":"工作坊可以名為「設計你的閱讀環境」。"},{"en":"Design Your Reading Environment means plan the places and conditions that make reading easier.","zh":"Design Your Reading Environment 指規劃令閱讀更容易的地方和條件。"},{"en":"A student designs a reading environment by removing the phone and placing a book on the desk.","zh":"學生透過拿走電話並把書放在桌上，設計閱讀環境。"},{"en":"Environment matters because habits are affected by what is nearby and visible.","zh":"環境很重要，因為習慣會受附近和看得見的東西影響。"},{"en":"This title tells students that reading can be supported by better surroundings.","zh":"這個題目告訴學生，閱讀可以由更好的周遭環境支援。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"work in groups","meaning":"分組合作","examples":[{"en":"Students would work in groups during the workshop.","zh":"學生會在工作坊期間分組合作。"},{"en":"To work in groups means to cooperate with classmates or teammates in small teams.","zh":"work in groups 指與同學或隊友以小組形式合作。"},{"en":"Students work in groups when they discuss ideas and divide tasks for a project.","zh":"學生討論想法並為專題分工時，就是分組合作。"},{"en":"Group work helps students hear solutions they may not think of alone.","zh":"小組合作幫助學生聽到自己一個人未必想到的解決方法。"},{"en":"In a reading workshop, working in groups can make habit design more creative.","zh":"在閱讀工作坊中，分組合作可以令習慣設計更有創意。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"redesign a typical student’s day","meaning":"重新設計一個普通學生的一天","examples":[{"en":"Students would redesign a typical student’s day.","zh":"學生會重新設計一個普通學生的一天。"},{"en":"To redesign a typical student’s day means to change an ordinary daily schedule to make it work better.","zh":"redesign a typical student’s day 指改變普通日常時間表，使它運作得更好。"},{"en":"A class may redesign a student’s day by adding short breaks and fixed reading time.","zh":"全班可以透過加入短休息和固定閱讀時間，重新設計學生的一天。"},{"en":"Redesigning a day helps people find space for habits instead of only wishing for time.","zh":"重新設計一天幫助人找到習慣的位置，而不是只希望有時間。"},{"en":"This activity makes habit-building practical because students work with real routines.","zh":"這項活動令建立習慣變得實際，因為學生處理真實日常安排。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"typical student","meaning":"普通學生","examples":[{"en":"The workshop focuses on a typical student’s day.","zh":"工作坊集中於一個普通學生的一天。"},{"en":"A typical student is an ordinary student with common routines, pressures, and habits.","zh":"typical student 指有常見日常、壓力和習慣的一般學生。"},{"en":"A typical student may attend lessons, do homework, use a phone, and feel tired at night.","zh":"普通學生可能上課、做功課、用電話，並在晚上感到疲倦。"},{"en":"Using a typical student as an example helps classmates recognise their own problems.","zh":"以普通學生為例，幫助同學認出自己的問題。"},{"en":"The phrase keeps the activity realistic rather than based on an ideal student.","zh":"這個短語令活動保持實際，而不是建基於理想學生。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"reduce distractions","meaning":"減少分心事物","examples":[{"en":"Students would discuss how to reduce distractions.","zh":"學生會討論如何減少分心事物。"},{"en":"To reduce distractions means to make things that take attention away less common or less powerful.","zh":"reduce distractions 指令奪走注意力的事物變少或影響變弱。"},{"en":"Turning off phone notifications can reduce distractions during reading time.","zh":"關閉電話通知可以在閱讀時間減少分心事物。"},{"en":"Students read better when distractions such as noise, apps, and messages are controlled.","zh":"當噪音、應用程式和訊息等分心事物受控制時，學生會讀得更好。"},{"en":"Reducing distractions is easier when the environment is designed before reading begins.","zh":"在閱讀開始前先設計環境，會較容易減少分心事物。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"reward themselves","meaning":"獎勵自己","examples":[{"en":"Students would decide how to reward themselves for reading.","zh":"學生會決定如何因閱讀而獎勵自己。"},{"en":"To reward themselves means to give themselves something pleasant after completing a task.","zh":"reward themselves 指完成任務後給自己一些愉快的東西。"},{"en":"A student may reward themselves with ten minutes of music after reading a chapter.","zh":"學生讀完一章後，可能用十分鐘音樂來獎勵自己。"},{"en":"Rewards help habits feel satisfying, especially at the beginning.","zh":"獎勵幫助習慣帶來滿足感，尤其在開始階段。"},{"en":"A good reward should support the habit rather than destroy it.","zh":"好獎勵應支持習慣，而不是破壞它。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"take someone for example","meaning":"以某人為例","examples":[{"en":"Take a Form Five student, for example.","zh":"以一名中五學生為例。"},{"en":"Take someone for example is used to introduce a specific person or case to explain a point.","zh":"take someone for example 用來引入一個具體人物或個案，以解釋重點。"},{"en":"Take a shy student for example: group practice may help before a formal speech.","zh":"以一名害羞學生為例：正式演講前，小組練習可能有幫助。"},{"en":"This phrase makes advice easier to understand by showing it in a real situation.","zh":"這個短語透過真實情況展示建議，令它較容易理解。"},{"en":"It is useful in essays because it turns a general idea into a concrete example.","zh":"它在文章中很有用，因為它把一般想法變成具體例子。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"Form Five student","meaning":"中五學生","examples":[{"en":"A Form Five student could link reading to dinner.","zh":"一名中五學生可以把閱讀與晚飯連繫起來。"},{"en":"A Form Five student is a secondary school student in the fifth year of secondary education.","zh":"Form Five student 指中學第五年級的學生。"},{"en":"A Form Five student may be busy with tests, homework, activities, and exam preparation.","zh":"中五學生可能忙於測驗、功課、活動和考試準備。"},{"en":"Using a Form Five student as an example makes the routine realistic for senior students.","zh":"以中五學生為例，令這個常規對高中學生更實際。"},{"en":"The phrase suggests a student old enough to face serious academic pressure.","zh":"這個短語暗示學生已年長到面對較大學業壓力。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"by linking… to…","meaning":"透過把……連繫到……","examples":[{"en":"By linking ten minutes of reading to dinner, a student can build a routine.","zh":"透過把十分鐘閱讀連繫到晚飯，學生可以建立日常常規。"},{"en":"By linking one action to another means using an existing habit as a cue for a new habit.","zh":"by linking one action to another 指用已有習慣作為新習慣的提示。"},{"en":"By linking vocabulary revision to the bus ride, students can practise every morning.","zh":"透過把詞彙溫習連繫到巴士旅程，學生可以每天早上練習。"},{"en":"Linking habits works because the old routine reminds people to start the new one.","zh":"連繫習慣有效，因為舊常規會提醒人開始新習慣。"},{"en":"This method makes reading part of life instead of an extra decision.","zh":"這個方法令閱讀成為生活的一部分，而不是額外決定。"}],"source":"2015 Q9.pdf","sourcePage":11},{"front":"ten minutes of English reading","meaning":"十分鐘英文閱讀","examples":[{"en":"A student could do ten minutes of English reading after dinner.","zh":"學生可以在晚飯後做十分鐘英文閱讀。"},{"en":"Ten minutes of English reading means a short period spent reading English text.","zh":"ten minutes of English reading 指花一小段時間閱讀英文文本。"},{"en":"Ten minutes of English reading is small enough for a busy school night.","zh":"十分鐘英文閱讀對繁忙的上學晚上來說夠細小。"},{"en":"Short reading periods can build confidence because students finish them easily.","zh":"短閱讀時間可以建立信心，因為學生容易完成。"},{"en":"Over time, ten minutes of English reading can improve vocabulary and fluency.","zh":"長遠來說，十分鐘英文閱讀可以提升詞彙和流暢度。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"the end of dinner","meaning":"晚飯結束時","examples":[{"en":"The student could read at the end of dinner.","zh":"學生可以在晚飯結束時閱讀。"},{"en":"The end of dinner means the moment when the meal has finished.","zh":"the end of dinner 指晚餐完成的時刻。"},{"en":"At the end of dinner, a family may clear the table and talk about the day.","zh":"晚飯結束時，一家人可能收拾餐桌並談論當天事情。"},{"en":"Linking reading to the end of dinner gives the habit a clear starting point.","zh":"把閱讀連繫到晚飯結束時，給習慣一個清楚開始點。"},{"en":"A fixed daily moment helps students avoid asking, “When should I read?”","zh":"固定的每日時刻幫助學生避免問：「我應該何時閱讀？」"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"create a realistic routine","meaning":"建立實際可行的日常安排","examples":[{"en":"A student may create a realistic routine during a busy term.","zh":"學生可以在繁忙學期建立實際可行的日常安排。"},{"en":"To create a realistic routine means to build a daily pattern that can actually fit one’s life.","zh":"create a realistic routine 指建立真正能配合生活的日常模式。"},{"en":"A student can create a realistic routine by reading for five minutes before homework.","zh":"學生可以透過做功課前閱讀五分鐘，建立實際可行的日常安排。"},{"en":"Realistic routines are small enough to continue even when life is busy.","zh":"實際可行的常規夠細小，即使生活繁忙也能持續。"},{"en":"A routine fails if it looks perfect but cannot survive a normal school week.","zh":"如果常規看似完美但不能撐過普通上學週，它就會失敗。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"even during","meaning":"即使在……期間","examples":[{"en":"A student can create a routine even during a busy term.","zh":"學生即使在繁忙學期也能建立常規。"},{"en":"Even during means despite being in a difficult, busy, or unusual period.","zh":"even during 指即使處於困難、繁忙或不尋常的時期。"},{"en":"Students can still sleep well even during exam season if they plan carefully.","zh":"如果計劃得宜，學生即使在考試季也能睡得好。"},{"en":"This phrase shows that a habit is possible under less-than-perfect conditions.","zh":"這個短語顯示，即使條件不完美，習慣仍然可能存在。"},{"en":"A reading routine matters most when students can keep it even during busy times.","zh":"當學生即使在繁忙時期仍能維持閱讀常規，這個常規就最有價值。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"a busy term","meaning":"繁忙的學期","examples":[{"en":"Students need realistic routines during a busy term.","zh":"學生在繁忙學期需要實際可行的常規。"},{"en":"A busy term is a school period filled with lessons, homework, tests, activities, and deadlines.","zh":"busy term 指充滿課堂、功課、測驗、活動和截止日期的學校時期。"},{"en":"During a busy term, students may feel they have no time for extra reading.","zh":"在繁忙學期，學生可能覺得自己沒有時間作額外閱讀。"},{"en":"Simple habits are important during a busy term because energy is limited.","zh":"在繁忙學期，簡單習慣很重要，因為精力有限。"},{"en":"A routine that survives a busy term is likely to last longer.","zh":"能撐過繁忙學期的常規，較可能持續更久。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"question-and-answer session","meaning":"問答環節","examples":[{"en":"The evening could include a question-and-answer session.","zh":"晚會可以包括問答環節。"},{"en":"A question-and-answer session is a part of an event where the audience asks questions and the speaker replies.","zh":"question-and-answer session 指活動中觀眾提問、講者回答的部分。"},{"en":"After a talk, a question-and-answer session lets students clarify ideas they did not understand.","zh":"講座後的問答環節讓學生澄清不明白的想法。"},{"en":"Such sessions make events more interactive because students can raise their own concerns.","zh":"這類環節令活動更互動，因為學生可以提出自己的關注。"},{"en":"A good Q&A session connects the speaker’s ideas with the audience’s real problems.","zh":"好的問答環節把講者想法與觀眾的真實問題連接起來。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"procrastination","meaning":"拖延症","examples":[{"en":"Students could ask questions about procrastination.","zh":"學生可以提出關於拖延症的問題。"},{"en":"Procrastination means delaying work that should be done, often even when you know it matters.","zh":"procrastination 指延遲應該完成的工作，即使知道它重要。"},{"en":"A student shows procrastination when they scroll on their phone instead of starting homework.","zh":"學生不開始功課而滑手機時，就是拖延。"},{"en":"Procrastination can grow when a task feels too large, boring, or frightening.","zh":"當任務感覺太大、沉悶或可怕時，拖延症可能加重。"},{"en":"Small first steps help reduce procrastination because starting becomes less painful.","zh":"小小第一步能減少拖延，因為開始變得較不痛苦。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"consistency","meaning":"持之以恆；一致性","examples":[{"en":"The session could discuss motivation and consistency.","zh":"這個環節可以討論動力和持之以恆。"},{"en":"Consistency means doing something regularly and steadily over time.","zh":"consistency 指長時間定期而穩定地做某事。"},{"en":"A student builds vocabulary through consistency, not by memorising many words once.","zh":"學生透過持之以恆建立詞彙，而不是一次過背很多字。"},{"en":"Consistency matters because small actions become powerful only when repeated.","zh":"持之以恆很重要，因為小行動只有在重複時才變得有力量。"},{"en":"Motivation may begin a habit, but consistency keeps it alive.","zh":"動力可以開始習慣，但持之以恆令習慣保持生命力。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"extend the impact","meaning":"延伸影響","examples":[{"en":"The Reading Club could launch a challenge to extend the impact.","zh":"閱讀學會可以推出挑戰活動來延伸影響。"},{"en":"To extend the impact means to make an event’s influence last longer or reach more people.","zh":"extend the impact 指令活動的影響持續更久或接觸更多人。"},{"en":"A school can extend the impact of a talk by giving students follow-up activities.","zh":"學校可以透過給學生跟進活動，延伸講座的影響。"},{"en":"Without follow-up, even an inspiring evening may be quickly forgotten.","zh":"沒有跟進，即使鼓舞人心的晚會也可能很快被忘記。"},{"en":"A reading challenge extends the impact by turning one event into several days of action.","zh":"閱讀挑戰透過把一次活動變成多日行動來延伸影響。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"launch a challenge","meaning":"推出挑戰活動","examples":[{"en":"The Reading Club could launch a seven-day reading challenge.","zh":"閱讀學會可以推出七日閱讀挑戰。"},{"en":"To launch a challenge means to start and introduce an organised activity that asks people to complete a goal.","zh":"launch a challenge 指開始並介紹一項要求人們完成目標的有組織活動。"},{"en":"A PE department may launch a walking challenge to encourage daily exercise.","zh":"體育科可能推出步行挑戰，以鼓勵每日運動。"},{"en":"Challenges work well when the goal is clear, short, and achievable.","zh":"當目標清楚、短期而可達成時，挑戰活動效果較好。"},{"en":"Launching a reading challenge gives students a reason to practise immediately after the talk.","zh":"推出閱讀挑戰，給學生在講座後立即練習的理由。"}],"source":"2015 Q9.pdf","sourcePage":12},{"front":"seven-day challenge","meaning":"七日挑戰","examples":[{"en":"The club could launch a seven-day Atomic Reading Challenge.","zh":"學會可以推出七日原子閱讀挑戰。"},{"en":"A seven-day challenge is an activity where people try to complete a goal every day for one week.","zh":"seven-day challenge 指人們在一星期內每天嘗試完成目標的活動。"},{"en":"A seven-day sleep challenge may ask students to sleep before eleven each night.","zh":"七日睡眠挑戰可能要求學生每晚十一點前睡覺。"},{"en":"Seven days is short enough to feel possible but long enough to begin a habit.","zh":"七日短到令人覺得可行，但也長到足以開始習慣。"},{"en":"A seven-day reading challenge can help students test whether a small routine works.","zh":"七日閱讀挑戰可以幫助學生測試小常規是否有效。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"Atomic Reading Challenge","meaning":"原子閱讀挑戰","examples":[{"en":"The Atomic Reading Challenge would encourage students to read daily.","zh":"原子閱讀挑戰會鼓勵學生每日閱讀。"},{"en":"The Atomic Reading Challenge is a proposed reading activity based on the idea of small daily habits.","zh":"Atomic Reading Challenge 指一項基於每日小習慣概念的建議閱讀活動。"},{"en":"In an Atomic Reading Challenge, students may read one short passage every day.","zh":"在原子閱讀挑戰中，學生可能每天閱讀一篇短文。"},{"en":"The word atomic suggests the habit should be tiny but powerful over time.","zh":"atomic 這個字暗示習慣應細小，但長遠有力量。"},{"en":"This challenge helps students practise the message of Atomic Habits instead of only hearing it.","zh":"這項挑戰幫助學生實踐《Atomic Habits》的訊息，而不只是聆聽它。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"in which","meaning":"在當中","examples":[{"en":"The club could launch a challenge in which students read every day.","zh":"學會可以推出一項挑戰，學生在當中每天閱讀。"},{"en":"In which means in that activity, situation, or thing just mentioned.","zh":"in which 指在剛提到的活動、情況或事物當中。"},{"en":"The school held a competition in which students designed posters about kindness.","zh":"學校舉辦一項比賽，學生在當中設計關於善意的海報。"},{"en":"This phrase helps writers add details about what happens inside a plan or event.","zh":"這個短語幫助作者加入計劃或活動內會發生的細節。"},{"en":"In the reading challenge, “in which” introduces the action students will take.","zh":"在閱讀挑戰中，in which 引入學生將採取的行動。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"read a little every day","meaning":"每天閱讀一點","examples":[{"en":"Students would read a little every day.","zh":"學生會每天閱讀一點。"},{"en":"To read a little every day means to do a small amount of reading daily.","zh":"read a little every day 指每天做少量閱讀。"},{"en":"A student may read a little every day on the bus to school.","zh":"學生可以在上學巴士上每天閱讀一點。"},{"en":"Reading a little every day is easier than waiting for a long free afternoon.","zh":"每天閱讀一點，比等待一個很長的空閒下午更容易。"},{"en":"Small daily reading helps students build consistency without feeling overwhelmed.","zh":"每日小量閱讀幫助學生建立持之以恆，而不會感到壓倒性。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"post a short reflection","meaning":"張貼簡短反思","examples":[{"en":"Students would post a short reflection outside the library.","zh":"學生會在圖書館外張貼簡短反思。"},{"en":"To post a short reflection means to display a brief written response about what one has learned or felt.","zh":"post a short reflection 指展示一段簡短文字，回應自己學到或感受到的東西。"},{"en":"After reading an article, students may post a short reflection on a classroom board.","zh":"閱讀文章後，學生可能在課室壁報板張貼簡短反思。"},{"en":"Reflections help students think beyond finishing the text.","zh":"反思幫助學生不只停留在完成文本。"},{"en":"Posting reflections also lets classmates discover books through one another’s thoughts.","zh":"張貼反思也讓同學透過彼此想法發現書本。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"outside the library","meaning":"在圖書館外","examples":[{"en":"Students could post their reflections outside the library.","zh":"學生可以在圖書館外張貼反思。"},{"en":"Outside the library means in the area near the entrance or exterior of the library.","zh":"outside the library 指在圖書館入口附近或外部區域。"},{"en":"Schools may display book recommendations outside the library to attract passing students.","zh":"學校可能在圖書館外展示書本推薦，以吸引路過學生。"},{"en":"Posting work outside the library makes reading visible to the whole school.","zh":"在圖書館外張貼作品，令閱讀在全校變得可見。"},{"en":"This location is useful because it connects the challenge with the place where books are found.","zh":"這個位置很有用，因為它把挑戰與找到書本的地方連接起來。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, the writer strongly recommends inviting James Clear.","zh":"綜合而言，作者強烈建議邀請 James Clear。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 指在考慮所有重要因素之後。"},{"en":"All things considered, the school should continue the reading programme next year.","zh":"綜合而言，學校應在明年繼續閱讀計劃。"},{"en":"Writers use this phrase near the conclusion to give a balanced final judgement.","zh":"作者常在結論附近使用這個短語，作出平衡的最後判斷。"},{"en":"It shows that the recommendation comes after considering benefits, relevance, and practical plans.","zh":"它顯示建議是在考慮好處、相關性和實際計劃後提出的。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"strongly recommend inviting","meaning":"強烈建議邀請","examples":[{"en":"I strongly recommend inviting James Clear for the event.","zh":"我強烈建議邀請 James Clear 出席活動。"},{"en":"To strongly recommend inviting someone means to clearly and firmly suggest that the person should be invited.","zh":"strongly recommend inviting someone 指清楚而堅定地建議邀請某人。"},{"en":"The committee strongly recommended inviting a local scientist to speak at Science Week.","zh":"委員會強烈建議邀請本地科學家在科學週演講。"},{"en":"A strong recommendation should be supported by clear reasons.","zh":"強烈建議應有清楚理由支持。"},{"en":"This phrase is suitable when the writer is confident that the guest fits the event.","zh":"當作者有信心嘉賓適合活動時，這個短語很合適。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"bring star appeal to","meaning":"為……帶來明星吸引力","examples":[{"en":"James Clear would bring star appeal to Reading Week.","zh":"James Clear 會為閱讀週帶來明星吸引力。"},{"en":"To bring star appeal to something means to make an event more attractive by involving a famous or admired person.","zh":"bring star appeal to something 指透過邀請有名或受欣賞的人，令活動更吸引。"},{"en":"A well-known athlete can bring star appeal to a school sports ceremony.","zh":"知名運動員可以為學校運動典禮帶來明星吸引力。"},{"en":"Star appeal can attract people who might not normally attend.","zh":"明星吸引力可以吸引平時未必會出席的人。"},{"en":"However, star appeal is most useful when it is connected to a meaningful message.","zh":"然而，當明星吸引力與有意義的訊息相連時，它最有用。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"star appeal","meaning":"明星吸引力","examples":[{"en":"James Clear would bring star appeal to the event.","zh":"James Clear 會為活動帶來明星吸引力。"},{"en":"Star appeal is the attraction created by someone famous, successful, or widely admired.","zh":"star appeal 指由有名、成功或廣受欣賞的人所帶來的吸引力。"},{"en":"A popular singer’s star appeal may bring more students to a charity concert.","zh":"受歡迎歌手的明星吸引力可能吸引更多學生參加慈善音樂會。"},{"en":"Star appeal can open the door, but the content must keep the audience interested.","zh":"明星吸引力可以打開大門，但內容必須令觀眾保持興趣。"},{"en":"In this proposal, star appeal supports the larger goal of encouraging reading.","zh":"在這項建議中，明星吸引力支援鼓勵閱讀這個更大目標。"}],"source":"2015 Q9.pdf","sourcePage":13},{"front":"practical reason to","meaning":"做……的實際理由","examples":[{"en":"The talk would give students a practical reason to pick up English books.","zh":"這場講座會給學生拿起英文書閱讀的實際理由。"},{"en":"A practical reason to do something is a clear and useful reason connected to real life.","zh":"practical reason to do something 指與現實生活有關的清楚而有用理由。"},{"en":"A career talk gives students a practical reason to improve their interview skills.","zh":"職業講座給學生改善面試技巧的實際理由。"},{"en":"Students act more willingly when they understand the practical reason behind a task.","zh":"當學生明白任務背後的實際理由時，他們會更願意行動。"},{"en":"The talk can show that English books help with habits, exams, and personal growth.","zh":"講座可以顯示英文書有助習慣、考試和個人成長。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"pick up English books","meaning":"拿起英文書閱讀","examples":[{"en":"The event may encourage students to pick up English books.","zh":"這項活動可能鼓勵學生拿起英文書閱讀。"},{"en":"To pick up English books means to start reading English books, often after avoiding them.","zh":"pick up English books 指開始閱讀英文書，通常是在曾經避開它們之後。"},{"en":"A student may pick up an English book if the first chapter feels short and clear.","zh":"如果第一章感覺短而清楚，學生可能會拿起英文書閱讀。"},{"en":"Encouragement works best when students know which books are suitable for them.","zh":"當學生知道哪些書適合自己時，鼓勵最有效。"},{"en":"Picking up English books is the first visible step toward a reading habit.","zh":"拿起英文書閱讀是建立閱讀習慣的第一個可見步驟。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"keep going","meaning":"堅持下去","examples":[{"en":"Students need a reason to pick up books and keep going.","zh":"學生需要一個理由去拿起書本並堅持下去。"},{"en":"To keep going means to continue even after the first excitement becomes weaker.","zh":"keep going 指即使最初興奮感減弱，仍然繼續。"},{"en":"A runner keeps going by slowing down instead of stopping completely.","zh":"跑手透過放慢速度而不是完全停止來堅持下去。"},{"en":"Students keep going when the goal feels manageable and progress is visible.","zh":"當目標感覺可處理，而且進度可見時，學生會堅持下去。"},{"en":"Reading habits depend not only on starting, but also on continuing.","zh":"閱讀習慣不只取決於開始，也取決於持續。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"approve of this suggestion","meaning":"批准這個建議","examples":[{"en":"If Ms Li approves of this suggestion, Chris can help prepare.","zh":"如果李老師批准這個建議，Chris 可以協助準備。"},{"en":"To approve of this suggestion means to agree that the proposal is acceptable or worth doing.","zh":"approve of this suggestion 指同意這項建議可接受或值得進行。"},{"en":"If the principal approves of the suggestion, the club can start planning the event.","zh":"如果校長批准這個建議，學會就可以開始計劃活動。"},{"en":"Approval is important because school activities usually need permission before action.","zh":"批准很重要，因為學校活動通常需要得到許可才能行動。"},{"en":"This phrase politely leaves the final decision to the person in authority.","zh":"這個短語禮貌地把最終決定留給有權限的人。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"be delighted to","meaning":"很樂意","examples":[{"en":"Chris would be delighted to help prepare the invitation email.","zh":"Chris 很樂意協助準備邀請電郵。"},{"en":"To be delighted to do something means to be very happy and willing to do it.","zh":"be delighted to do something 指非常高興並願意做某事。"},{"en":"A student may be delighted to help organise a book fair if they love reading.","zh":"如果學生熱愛閱讀，他可能很樂意協助籌辦書展。"},{"en":"This phrase sounds warmer and more formal than simply saying “I can help.”","zh":"這個短語比簡單說 “I can help” 更溫暖和正式。"},{"en":"It shows enthusiasm while still sounding polite.","zh":"它顯示熱情，同時保持禮貌。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"prepare the invitation email","meaning":"準備邀請電郵","examples":[{"en":"Chris can help prepare the invitation email.","zh":"Chris 可以協助準備邀請電郵。"},{"en":"To prepare the invitation email means to write or arrange the message inviting someone to an event.","zh":"prepare the invitation email 指撰寫或整理邀請某人參加活動的訊息。"},{"en":"A club secretary may prepare the invitation email for a guest speaker.","zh":"學會秘書可能為嘉賓講者準備邀請電郵。"},{"en":"A good invitation email should explain the event, date, audience, and reason for inviting the speaker.","zh":"好的邀請電郵應說明活動、日期、觀眾和邀請原因。"},{"en":"Preparing the email carefully helps the invitation sound professional and respectful.","zh":"細心準備電郵能令邀請聽起來專業而尊重。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"design the reading tracker","meaning":"設計閱讀記錄表","examples":[{"en":"Chris can help design the reading tracker.","zh":"Chris 可以協助設計閱讀記錄表。"},{"en":"To design the reading tracker means to create the tool used to record students’ reading progress.","zh":"design the reading tracker 指製作一個用來記錄學生閱讀進度的工具。"},{"en":"Students may design a reading tracker with dates, book titles, pages read, and reflections.","zh":"學生可以設計包含日期、書名、閱讀頁數和反思的閱讀記錄表。"},{"en":"A clear tracker helps students see whether they are keeping the habit.","zh":"清晰記錄表幫助學生看見自己是否維持習慣。"},{"en":"Designing the tracker well can make the challenge more motivating.","zh":"好好設計記錄表，可以令挑戰更有動力。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"collect questions from","meaning":"從……收集問題","examples":[{"en":"Chris can collect questions from different classes.","zh":"Chris 可以從不同班別收集問題。"},{"en":"To collect questions from people means to gather the questions they want to ask.","zh":"collect questions from people 指收集他們想提出的問題。"},{"en":"A teacher may collect questions from students before inviting a guest speaker.","zh":"老師可能在邀請嘉賓講者前，從學生收集問題。"},{"en":"Collecting questions helps organisers understand what the audience cares about.","zh":"收集問題幫助主辦方了解觀眾關心甚麼。"},{"en":"It also makes students feel involved before the event begins.","zh":"它也令學生在活動開始前已感到參與其中。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"different classes","meaning":"不同班別","examples":[{"en":"Questions could be collected from different classes.","zh":"問題可以從不同班別收集。"},{"en":"Different classes means more than one class or groups of students from separate classes.","zh":"different classes 指不止一個班，或來自不同班級的學生群體。"},{"en":"A school survey may collect opinions from different classes to be fairer.","zh":"學校問卷可能從不同班別收集意見，以更公平。"},{"en":"Questions from different classes can show a wider range of student concerns.","zh":"來自不同班別的問題可以顯示更廣泛的學生關注。"},{"en":"Including different classes helps the event feel like a whole-school activity.","zh":"包括不同班別，有助令活動感覺像全校活動。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"one simple truth","meaning":"一個簡單道理","examples":[{"en":"The event would help students understand one simple truth.","zh":"這項活動會幫助學生明白一個簡單道理。"},{"en":"One simple truth means one clear and important idea that is easy to understand.","zh":"one simple truth 指一個清楚、重要而容易理解的想法。"},{"en":"A sports coach may teach one simple truth: practice matters more than excuses.","zh":"體育教練可能教一個簡單道理：練習比藉口重要。"},{"en":"Writers use this phrase before stating the main lesson.","zh":"作者在說出主要教訓前會使用這個短語。"},{"en":"In this proposal, the simple truth is that regular reading builds confident English use.","zh":"在這項建議中，這個簡單道理是：定期閱讀能建立更有信心的英文使用。"}],"source":"2015 Q9.pdf","sourcePage":14},{"front":"the more…, the more…","meaning":"越……就越……","examples":[{"en":"The more consistently we read, the more confidently we use English.","zh":"我們越持之以恆地閱讀，就越有信心地使用英文。"},{"en":"The more…, the more… shows that one change increases together with another change.","zh":"the more…, the more… 顯示一個變化增加時，另一個變化也一起增加。"},{"en":"The more students practise speaking, the more natural their English becomes.","zh":"學生越練習說話，英文就越自然。"},{"en":"This pattern is useful for explaining a clear relationship between effort and result.","zh":"這個句式很適合解釋努力與結果之間的清楚關係。"},{"en":"Here, it shows that regular reading can lead to stronger confidence.","zh":"在這裏，它顯示定期閱讀可以帶來更強信心。"}],"source":"2015 Q9.pdf","sourcePage":15},{"front":"consistently","meaning":"持之以恆地","examples":[{"en":"The more consistently we read, the better our English becomes.","zh":"我們越持之以恆地閱讀，英文就變得越好。"},{"en":"Consistently means regularly and steadily, without stopping often.","zh":"consistently 指定期而穩定地做，不常停止。"},{"en":"A student who reads consistently for ten minutes a day may improve more than one who reads only before exams.","zh":"每天持之以恆地閱讀十分鐘的學生，可能比只在考試前閱讀的學生進步更多。"},{"en":"Consistent practice is powerful because it turns effort into habit.","zh":"持續練習有力量，因為它把努力變成習慣。"},{"en":"Reading consistently helps English feel familiar instead of foreign.","zh":"持之以恆地閱讀幫助英文變得熟悉，而不是陌生。"}],"source":"2015 Q9.pdf","sourcePage":15},{"front":"confidently","meaning":"有信心地","examples":[{"en":"The more we read, the more confidently we use English.","zh":"我們閱讀越多，就越有信心地使用英文。"},{"en":"Confidently means with belief in one’s ability and without too much fear.","zh":"confidently 指相信自己的能力，並沒有太多恐懼。"},{"en":"Students speak more confidently when they have seen useful phrases many times in books.","zh":"當學生在書中多次看見有用短語時，他們會更有信心地說話。"},{"en":"Confidence grows when practice makes language feel familiar.","zh":"當練習令語言感覺熟悉時，信心會增長。"},{"en":"Reading helps students use English more confidently because they meet words in real contexts.","zh":"閱讀幫助學生更有信心地使用英文，因為他們在真實語境中遇見詞語。"}],"source":"2015 Q9.pdf","sourcePage":15},{"front":"Yours sincerely","meaning":"謹啟；此致","examples":[{"en":"The letter ends with “Yours sincerely.”","zh":"這封信以 “Yours sincerely” 結尾。"},{"en":"Yours sincerely is a polite formal closing used at the end of a letter when the writer knows the recipient’s name.","zh":"Yours sincerely 是在作者知道收信人姓名時，信件結尾使用的禮貌正式結語。"},{"en":"A student may write Yours sincerely before signing their name in a formal letter to a teacher.","zh":"學生在寫給老師的正式信件中，可能在簽名前寫 Yours sincerely。"},{"en":"This closing makes the letter sound complete and respectful.","zh":"這個結語令信件聽起來完整而尊重。"},{"en":"It is suitable for school letters, applications, and formal recommendations.","zh":"它適合用於學校信件、申請信和正式建議信。"}],"source":"2015 Q9.pdf","sourcePage":15},{"front":"Chairperson, Reading Club","meaning":"閱讀學會主席","examples":[{"en":"Chris Wong signs as Chairperson of the Reading Club.","zh":"Chris Wong 以閱讀學會主席身份簽署。"},{"en":"Chairperson, Reading Club is a signature title showing the writer’s role in the club.","zh":"Chairperson, Reading Club 是簽名職銜，顯示作者在學會中的角色。"},{"en":"A student may sign “Secretary, Music Club” after writing an official club email.","zh":"學生寫正式學會電郵後，可能簽署「音樂學會秘書」。"},{"en":"Adding a title helps the reader understand why the writer has authority to make the suggestion.","zh":"加上職銜幫助讀者理解作者為何有身份提出建議。"},{"en":"This closing shows that Chris is writing not only as an individual, but as a club representative.","zh":"這個結尾顯示 Chris 不只是以個人身份寫信，而是作為學會代表。"}],"source":"2015 Q9.pdf","sourcePage":15}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
